local compiler = loadstring or load
if type(compiler) ~= "function" then
    error("runtime requires loadstring support.", 0)
end

local nativeSource = [======[
local env = getgenv and getgenv() or _G
env["_SILENT_UI_PRODUCT"] = "Gakuran"

do
    local previousRuntime = rawget(env, "__GakuranScriptRuntime")
    if type(previousRuntime) == "table"
        and type(previousRuntime.Unload) == "function"
    then
        pcall(previousRuntime.Unload, previousRuntime)
    end

    local runtime = {
        alive = true,
        connections = {},
        cleanups = {},
    }

    function runtime:Track(connection)
        if connection then
            if self.alive ~= true then
                pcall(function()
                    connection:Disconnect()
                end)
                return connection
            end
            self.connections[#self.connections + 1] = connection
        end
        return connection
    end

    function runtime:AddCleanup(callback)
        if type(callback) == "function" then
            self.cleanups[#self.cleanups + 1] = callback
        end
        return callback
    end

    function runtime:Unload()
        if self.alive ~= true then
            return
        end

        self.alive = false
        for index = #self.cleanups, 1, -1 do
            local callback = self.cleanups[index]
            self.cleanups[index] = nil
            pcall(callback)
        end

        for index = #self.connections, 1, -1 do
            local connection = self.connections[index]
            self.connections[index] = nil
            pcall(function()
                connection:Disconnect()
            end)
        end

        if rawget(env, "__GakuranScriptRuntime") == self then
            rawset(env, "__GakuranScriptRuntime", nil)
        end
    end

    rawset(env, "__GakuranScriptRuntime", runtime)
end

do
    local state =
        env.__SilentSolutionsWarningFilter

    if type(state) ~= "table" then
        state = {
            cqcVfx = true,
            loadingScreen = true,
            installed = false,
        }

        env.__SilentSolutionsWarningFilter =
            state
    else
        state.cqcVfx = true
        state.loadingScreen = true
    end

    if state.installed ~= true
        and type(hookfunction) == "function"
        and type(warn) == "function"
    then
        local originalWarn

        local function filteredWarn(...)
            local first =
                select(1, ...)

            if type(first) == "string" then
                if state.cqcVfx == true
                    and first:match(
                        "^%[CQCVfx%]"
                    )
                then
                    return
                end

                if state.loadingScreen == true
                    and first:match(
                        "^%[LoadingScreen%] Animation preload finished"
                    )
                then
                    return
                end
            end

            if type(originalWarn) == "function" then
                return originalWarn(...)
            end
        end

        local replacement =
            filteredWarn

        if type(newcclosure) == "function" then
            local okClosure,
                closure =
                pcall(
                    newcclosure,
                    filteredWarn
                )

            if okClosure
                and type(closure) == "function"
            then
                replacement =
                    closure
            end
        end

        local okHook,
            oldWarn =
            pcall(
                hookfunction,
                warn,
                replacement
            )

        if okHook
            and type(oldWarn) == "function"
        then
            originalWarn =
                oldWarn
            state.originalWarn =
                oldWarn
            state.filteredWarn =
                replacement
            state.installed =
                true
        end
    end
end

local function loadInterface()
