                    local sideAwareRows = [=[        hud["is_left_side"] = function(self)
            local viewport = menu["_get_logical_viewport_size"]()
            local width = tonumber(self["frame"]["real_size"]["X"]) or 74

            -- Prefer the frame's actual UDim2 offset. It is the same position
            -- used by drag/config persistence and is more reliable here than
            -- depending only on the Drawing proxy's derived real_position.
            local current = rawget(self["frame"], "position")
            local x = nil

            if current and current["X"] then
                x = tonumber(current["X"]["Offset"])
            end

            if x == nil then
                local real = self["frame"]["real_position"]
                x = real and tonumber(real["X"]) or 0
            end

            return (x + width * 0.5)
                <= (tonumber(viewport["X"]) or 0) * 0.5
        end

        hud["right_x"] = function(self, row)
            local header_width = tonumber(self["frame"]["real_size"]["X"]) or 74
            local row_width = row and tonumber(row["frame"]["real_size"]["X"]) or header_width

            if self:is_left_side() then
