            tab,
            tabSelected
        )
            if not child then
                return
            end

            local nativeSetVisible =
                child["_subtab_native_set_visible"]
                or child["set_visible"]

            if type(nativeSetVisible) ~= "function" then
                return
            end

            local requested =
                child["_subtab_requested_visible"]

            if requested == nil then
                requested = true
            end

            local desired =
                tabSelected
