                            end)
                            if not s then
                                s = pcall(function()
                                    key = Enum["KeyCode"][key]
                                end)
                            end
                            if s then
]=]

            local newContextKeyResolve = [=[                            local key =
                                menu["_resolve_config_input"](
                                    new_keybind["key"]
                                )

                            if key then
]=]

            local contextStart, contextEnd =
                librarySource:find(
                    oldContextKeyResolve,
                    1,
                    true
                )

            if contextStart then
                librarySource =
                    librarySource:sub(1, contextStart - 1)
                    .. newContextKeyResolve
                    .. librarySource:sub(contextEnd + 1)
            end

            local oldElementKeyResolve = [=[                                        if new_value ~= nil and value ~= new_value then
                                            local s, err = pcall(function()
                                                new_value = Enum["UserInputType"][new_value]
                                            end)
                                            if not s then
                                                new_value = Enum["KeyCode"][new_value]
                                            end
                                            element:set_key(new_value)
                                        end
]=]

            local newElementKeyResolve = [=[                                        if new_value ~= nil and value ~= new_value then
                                            local resolvedKey =
                                                menu["_resolve_config_input"](
                                                    new_value
                                                )

                                            if resolvedKey then
                                                element:set_key(
                                                    resolvedKey
                                                )
                                            end
                                        end
]=]

            for _ = 1, 2 do
                local keyStart2, keyEnd2 =
                    librarySource:find(
                        oldElementKeyResolve,
                        1,
                        true
                    )

                if not keyStart2 then
                    break
                end

                librarySource =
                    librarySource:sub(1, keyStart2 - 1)
                    .. newElementKeyResolve
                    .. librarySource:sub(keyEnd2 + 1)
            end
        end

        librarySource =
            librarySource:gsub(
                'frame%["Visible"%] = not a%s+inside%["Visible"%] = not a',
                'frame["Visible"] = menu_open and not a\n'
                    .. '        inside["Visible"] = menu_open and not a',
                1
            )

        if not librarySource:find("customTabs:set_menu_visible(menu_open)", 1, true) then
        librarySource =
            librarySource:gsub(
                'menu_open = opening_menu',
                'menu_open = opening_menu\n'
                    .. '        if menu["_custom_subtabs"] then\n'
                    .. '            for _, customTabs in menu["_custom_subtabs"] do\n'
                    .. '                if customTabs and type(customTabs.set_menu_visible) == "function" then\n'
                    .. '                    customTabs:set_menu_visible(menu_open)\n'
                    .. '                end\n'
                    .. '            end\n'
                    .. '        end\n'
                    .. '        if menu_open and type(menu["_RefreshConfigList"]) == "function" then\n'
                    .. '            task.defer(menu["_RefreshConfigList"])\n'
                    .. '        end',
                1
            )
        end
    end

    local chunk, compileError = compiler(librarySource, "@Interface.lua")
    assert(
        type(chunk) == "function",
        "interface compile error: " .. tostring(compileError or "unknown error")
    )

    local menu = chunk()
    assert(type(menu) == "table", "interface did not return a menu table")

    -- Reuse the exact main UI logo animation for lightweight HUD icons.
    menu._silent_main_logo_frames = customLogoFrames
    menu._silent_main_logo_durations = customLogoDurations

    return menu
end

