-- Execution greeting. The loader exports the authenticated Discord account and
-- expiry returned by the Silent.solutions auth service. Keep the Roblox
-- headshot as the notification image, but identify the buyer by Discord.
task.spawn(function()
    local welcomePlayers =
        game:GetService("Players")
    local welcomeHttp =
        game:GetService("HttpService")
    local welcomePlayer =
        welcomePlayers.LocalPlayer
    local welcomeEnv =
        getgenv and getgenv()
        or _G

    if not welcomePlayer then
        return
    end

    local function fetchHeadshotBytes()
        local apiUrl =
            "https://thumbnails.roblox.com/v1/users/avatar-headshot?userIds="
            .. tostring(
                welcomePlayer.UserId
            )
            .. "&size=150x150&format=Png&isCircular=false"

        local okMetadata,
            metadata =
            pcall(
                game.HttpGet,
                game,
                apiUrl
            )

        if okMetadata
            and type(metadata)
                == "string"
        then
            local okDecode,
                decoded =
                pcall(
                    welcomeHttp.JSONDecode,
                    welcomeHttp,
                    metadata
                )

            local row =
                okDecode
                and type(decoded)
                    == "table"
                and type(decoded.data)
                    == "table"
                and decoded.data[1]
                or nil

            local imageUrl =
                row
                and row.imageUrl

            if type(imageUrl) == "string"
                and imageUrl ~= ""
            then
                local okImage,
                    bytes =
                    pcall(
                        game.HttpGet,
                        game,
                        imageUrl
                    )

                if okImage
                    and type(bytes)
                        == "string"
                    and #bytes > 0
                then
                    return bytes
                end
            end
        end

        return nil
    end

    local function authPayload()
        local payload =
            welcomeEnv.SilentSolutionsAuthResult

        if type(payload) == "table" then
            return payload
        end

        return {}
    end

    local function discordUsername()
        local payload =
            authPayload()

        local username =
            welcomeEnv.SilentSolutionsDiscordUsername
            or payload.discordUsername
            or payload.discord_username
            or payload.username

        username =
            tostring(username or "")
                :gsub("^@", "")
                :match("^%s*(.-)%s*$")
            or ""

        if username ~= "" then
            return username
        end

        local discordId =
            welcomeEnv.SilentSolutionsDiscordId
            or payload.discordId
            or payload.discord_id

        if discordId ~= nil
            and tostring(discordId) ~= ""
        then
            -- Never fall back to the Roblox display name. If an older loader
            -- has not exported the Discord username yet, show its Discord ID
            -- until loader.lua/bot.py are updated.
            return tostring(discordId)
        end

        return "Discord"
    end

    local function statusText()
        local payload =
            authPayload()

        local expiresAt =
            welcomeEnv.SilentSolutionsExpiresAt

        if expiresAt == nil then
            expiresAt =
                payload.expiresAt
                or payload.expires_at
        end

        local explicitLifetime =
            welcomeEnv.SilentSolutionsLifetime
            == true
            or payload.lifetime == true

        if expiresAt == nil
            or expiresAt == ""
        then
            -- In the current auth backend, no expires_at value means the
            -- whitelist has no duration and is therefore lifetime.
            if explicitLifetime
                or payload.ok == true
                or tostring(
                    payload.reason
                    or ""
                ):lower()
                    == "whitelisted"
                or welcomeEnv
                    .SilentSolutionsAuthorized
                    == true
            then
                return "Lifetime"
            end

            return "Lifetime"
        end

        local expiry =
            tonumber(expiresAt)

        if not expiry then
            return "Lifetime"
        end

        if expiry > 100000000000 then
            expiry = expiry / 1000
        end

        local remaining =
            expiry - os.time()

        if remaining <= 0 then
            return "Expired"
        end

        local days =
            math.max(
                1,
                math.ceil(
                    remaining / 86400
                )
            )

        return tostring(days)
            .. (
                days == 1
                and " Day"
                or " Days"
            )
    end

    local function isNewUser()
        local payload =
            authPayload()

        return welcomeEnv.SilentSolutionsNewUser
            == true
            or payload.isNewUser == true
            or payload.newUser == true
    end

    local headshot =
        fetchHeadshotBytes()

    task.wait(0.15)

    if type(Menu.new_notification)
        == "function"
    then
        local greeting =
            isNewUser()
            and "Welcome to 黙案 @"
            or "Welcome back @"

        pcall(
            Menu.new_notification,
            greeting
                .. discordUsername()
                .. " | Status: "
                .. statusText(),
            1,
            5,
            headshot
        )
    end
end)


-- Per-player relation state shared by List, ESP, AutoParry, AutoFace,
-- AutoPunish, and Evasive. Relations are runtime-only and keyed by UserId.
do
    local RelationPlayers = game:GetService("Players")

    Menu._PlayerRelations = {}

    local function resolveRelationPlayer(subject)
        if subject == nil then
            return nil
        end

        if typeof(subject) == "Instance" then
            if subject:IsA("Player") then
                return subject
            end

            local model = subject:IsA("Model")
                and subject
                or subject:FindFirstAncestorOfClass("Model")
            if model then
                local player = RelationPlayers:GetPlayerFromCharacter(model)
                    or RelationPlayers:FindFirstChild(model.Name)
                if player and player:IsA("Player") then
                    return player
                end

                local userId = tonumber(
                    model:GetAttribute("UserId")
                    or model:GetAttribute("PlayerId")
                )
                if userId then
                    local ok, byId = pcall(
                        RelationPlayers.GetPlayerByUserId,
                        RelationPlayers,
                        userId
                    )
                    if ok and byId then
                        return byId
                    end
                end
            end
        elseif type(subject) == "string" and subject ~= "" then
            local player = RelationPlayers:FindFirstChild(subject)
            if player and player:IsA("Player") then
                return player
            end
        elseif type(subject) == "number" then
            local ok, player = pcall(
                RelationPlayers.GetPlayerByUserId,
                RelationPlayers,
                subject
            )
            if ok then
                return player
            end
        end

        return nil
    end

    Menu._FriendWhitelist = Menu._FriendWhitelist or {}
    Menu._ResolveRelationPlayer = resolveRelationPlayer
    Menu._GetPlayerRelation = function(subject)
        local player = resolveRelationPlayer(subject)
        if not player then
            return nil
        end

        local explicit = Menu._PlayerRelations[player.UserId]
        -- Manual Priority always wins, including over automatic friend whitelist.
        if explicit == "Priority" then
            return "Priority"
        elseif explicit == "Friendly" then
            return "Friendly"
        end

        if Flags.list_whitelist_friends == true
            and Menu._FriendWhitelist[player.UserId] == true
        then
            return "Friendly"
        end

        return nil
    end
    Menu._IsFriendlyCharacter = function(subject)
        return Menu._GetPlayerRelation(subject) == "Friendly"
    end
    Menu._IsPrioritizedCharacter = function(subject)
        return Menu._GetPlayerRelation(subject) == "Priority"
    end
    Menu._ShouldVisualizeWhitelistedFriend = function(subject)
        if Flags.list_whitelist_friends ~= true
            or Flags.list_visualize_whitelist ~= true
        then
            return false
        end

        local player = resolveRelationPlayer(subject)
        return player ~= nil
            and Menu._FriendWhitelist[player.UserId] == true
    end
    Menu._HasWhitelistVisualizeTarget = function()
        if Flags.list_whitelist_friends ~= true
            or Flags.list_visualize_whitelist ~= true
        then
            return false
        end

        for _, isFriend in pairs(Menu._FriendWhitelist) do
            if isFriend == true then
                return true
            end
        end

        return false
    end
end

