    )

    local refreshPlayerVisualize

    local function refreshFriendState(player)
        if not player or player == LocalListPlayer then
            return
        end

        task.spawn(function()
            local ok, isFriend = pcall(
                LocalListPlayer.IsFriendsWith,
                LocalListPlayer,
                player.UserId
            )
            if ListRuntime.destroyed or player.Parent ~= PlayerListPlayers then
                return
            end
            Menu._FriendWhitelist[player.UserId] = ok and isFriend == true or false

            local refresh = ListRuntime.refreshRow
            if type(refresh) == "function" then
                refresh(player)
            end

            if Flags.list_whitelist_friends == true
                and Flags.list_visualize_whitelist == true
                and type(refreshPlayerVisualize) == "function"
            then
                refreshPlayerVisualize()
            end
        end)
    end

    refreshPlayerVisualize = function()
        local esp = Menu._ESPVisuals
        if esp and type(esp.Cache) == "table" then
            for _, data in pairs(esp.Cache) do
                if data then
                    data.NextESPUpdateAt = 0
                end
            end
            esp.ChamsAccumulator = 1
            esp.ChamsCreateNextAt = 0
            esp.ChamsEnableNextAt = 0
        end

        if type(Menu._RefreshESPEnabled) == "function" then
            Menu._RefreshESPEnabled()
        end
    end

    local FRIENDLY_ROW_COLOR = Color3.fromRGB(124, 132, 158)
    local PRIORITY_ROW_COLOR = Color3.fromRGB(158, 124, 124)

    local function getRowStatusColor(player)
        local relation = Menu._GetPlayerRelation(player)
        if relation == "Friendly" then
            return FRIENDLY_ROW_COLOR
        elseif relation == "Priority" then
            return PRIORITY_ROW_COLOR
        end
        return nil
    end

    local function getPlayerListPingSeconds()
        local item
        pcall(function()
            local network = PlayerListStats:FindFirstChild("Network")
            local serverStats = network and network:FindFirstChild("ServerStatsItem")
            item = serverStats and serverStats:FindFirstChild("Data Ping")
        end)
        if not item then
            return 0.055
        end

        local value
        pcall(function()
            if type(item.GetValue) == "function" then
                value = tonumber(item:GetValue())
            end
        end)
        if value then
            return math.clamp(value / 1000, 0, 0.25)
        end

        pcall(function()
            if type(item.GetValueString) == "function" then
                value = tonumber((item:GetValueString() or ""):match("[%d%.]+"))
            end
        end)
        return math.clamp((tonumber(value) or 55) / 1000, 0, 0.25)
    end

    local function stopPlayerListFling()
        ListRuntime.flingRunning = false
        ListRuntime.flingToken += 1
    end

    local function flingSelectedPlayer(targetPlayer)
        if ListRuntime.flingRunning
            or not targetPlayer
            or targetPlayer == LocalListPlayer
            or targetPlayer.Parent ~= PlayerListPlayers
        then
            return
        end

        local character = LocalListPlayer.Character
        local humanoid = character and character:FindFirstChildOfClass("Humanoid")
        local root = character and character:FindFirstChild("HumanoidRootPart")
        local targetCharacter = targetPlayer.Character
        local targetHumanoid = targetCharacter and targetCharacter:FindFirstChildOfClass("Humanoid")
        local targetRoot = targetCharacter and targetCharacter:FindFirstChild("HumanoidRootPart")

        if not humanoid
            or not root
            or not targetHumanoid
            or targetHumanoid.Health <= 0
            or not targetRoot
        then
            return
        end

        ListRuntime.flingRunning = true
        ListRuntime.flingToken += 1
        local token = ListRuntime.flingToken

        task.spawn(function()
            local savedCFrame = root.CFrame
            local savedLinearVelocity = root.AssemblyLinearVelocity
            local savedAngularVelocity = root.AssemblyAngularVelocity
            local savedAutoRotate = humanoid.AutoRotate
            local savedPlatformStand = humanoid.PlatformStand
            local savedDestroyHeight = PlayerListWorkspace.FallenPartsDestroyHeight
            local ownCollision = {}
            local targetCollision = {}

            for _, part in ipairs(character:GetDescendants()) do
                if part:IsA("BasePart") then
                    ownCollision[part] = part.CanCollide
                    part.CanCollide = part == root
                end
            end
            for _, part in ipairs(targetCharacter:GetDescendants()) do
                if part:IsA("BasePart") then
                    targetCollision[part] = part.CanCollide
                    part.CanCollide = true
                end
            end

            pcall(function()
                PlayerListWorkspace.FallenPartsDestroyHeight = 0 / 0
            end)
            pcall(function()
                if sethiddenproperty then
                    sethiddenproperty(LocalListPlayer, "SimulationRadius", math.huge)
                end
            end)

            humanoid.AutoRotate = false
            humanoid.PlatformStand = true
            humanoid:ChangeState(Enum.HumanoidStateType.Physics)

            local startedAt = os.clock()
            local frame = 0
            local lastPosition = targetRoot.Position
            local smoothedVelocity = Vector3.new(
                targetRoot.AssemblyLinearVelocity.X,
                0,
                targetRoot.AssemblyLinearVelocity.Z
            )
            local smoothedAcceleration = Vector3.zero
            local previousDirection = smoothedVelocity.Magnitude > 1.25
                and smoothedVelocity.Unit
                or Vector3.new(0, 0, -1)
            local smoothedTurnRate = 0
            local smoothedVerticalVelocity = targetRoot.AssemblyLinearVelocity.Y
            local motionHistory = {}
            local motionHistoryTime = 0

            local function rotateHorizontal(vector, angle)
                if vector.Magnitude < 0.0001 or math.abs(angle) < 0.0001 then
                    return vector
                end
                local cosine = math.cos(angle)
                local sine = math.sin(angle)
                return Vector3.new(
                    vector.X * cosine + vector.Z * sine,
                    0,
                    -vector.X * sine + vector.Z * cosine
                )
            end

            while ListRuntime.flingRunning
                and token == ListRuntime.flingToken
                and not ListRuntime.destroyed
                and LocalListPlayer.Character == character
                and targetPlayer.Parent == PlayerListPlayers
                and targetCharacter == targetPlayer.Character
                and targetRoot.Parent
                and targetHumanoid.Health > 0
                and os.clock() - startedAt < 2.15
            do
                frame += 1

                local heartbeatDt = PlayerListRunService.Heartbeat:Wait()
                local dt = math.clamp(
                    tonumber(heartbeatDt) or (1 / 60),
                    1 / 240,
                    0.08
                )
                local currentPosition = targetRoot.Position
                local assemblyVelocity = targetRoot.AssemblyLinearVelocity
                local horizontalAssembly = Vector3.new(
                    assemblyVelocity.X,
                    0,
                    assemblyVelocity.Z
                )

                -- Use both replicated AssemblyLinearVelocity and measured
                -- displacement, but reject one-frame replication corrections.
                -- The smoothing is dt-normalized so prediction behaves the same
                -- at low FPS and high FPS instead of changing with frame rate.
                local positionDelta = currentPosition - lastPosition
                local measured = Vector3.new(
                    positionDelta.X / dt,
                    0,
                    positionDelta.Z / dt
                )
                local measuredVertical = positionDelta.Y / dt
                lastPosition = currentPosition

                motionHistoryTime += dt
                motionHistory[#motionHistory + 1] = {
                    position = currentPosition,
                    time = motionHistoryTime,
                }
                while #motionHistory > 10 do
                    table.remove(motionHistory, 1)
                end

                -- A short displacement sample catches sudden strafes quickly,
                -- while a slightly longer history sample rejects noisy replicated
                -- position corrections. At high speed we trust the recent sample
                -- more so the predictor does not trail behind the target.
                local historyVelocity = measured
                local longHistoryVelocity = measured
                if #motionHistory >= 3 then
                    local historyStart = motionHistory[math.max(1, #motionHistory - 3)]
                    local historyElapsed = motionHistoryTime - historyStart.time
                    if historyElapsed > 0.001 then
                        local historyDelta = currentPosition - historyStart.position
                        historyVelocity = Vector3.new(
                            historyDelta.X / historyElapsed,
                            0,
                            historyDelta.Z / historyElapsed
                        )
                    end
                end
                if #motionHistory >= 6 then
                    local longStart = motionHistory[math.max(1, #motionHistory - 6)]
                    local longElapsed = motionHistoryTime - longStart.time
                    if longElapsed > 0.001 then
                        local longDelta = currentPosition - longStart.position
                        longHistoryVelocity = Vector3.new(
                            longDelta.X / longElapsed,
                            0,
                            longDelta.Z / longElapsed
                        )
                    end
                else
                    longHistoryVelocity = historyVelocity
                end

                local motionConsistency = 1
                if historyVelocity.Magnitude > 1.25
                    and longHistoryVelocity.Magnitude > 1.25
                then
                    motionConsistency = math.clamp(
                        (historyVelocity.Unit:Dot(longHistoryVelocity.Unit) + 1) * 0.5,
                        0,
                        1
                    )
                end

                local assemblySpeed = horizontalAssembly.Magnitude
                local measuredSpeed = measured.Magnitude
                local historySpeed = historyVelocity.Magnitude
                local referenceSpeed = math.max(assemblySpeed, historySpeed)
                local measuredCap = math.max(82, referenceSpeed * 2.55 + 28)
                if measuredSpeed > measuredCap and measuredSpeed > 0 then
                    measured = measured.Unit * measuredCap
                    measuredSpeed = measuredCap
                end
                if historySpeed > measuredCap and historySpeed > 0 then
                    historyVelocity = historyVelocity.Unit * measuredCap
                    historySpeed = measuredCap
                end

                local historyBlend = longHistoryVelocity:Lerp(
                    historyVelocity,
                    math.clamp(0.56 + referenceSpeed / 420, 0.56, 0.78)
                )
                local displacementVelocity = historyBlend:Lerp(
                    measured,
                    math.clamp(
                        0.38 + referenceSpeed / 250 + (1 - motionConsistency) * 0.10,
                        0.38,
                        0.76
                    )
                )
                local disagreement = (displacementVelocity - horizontalAssembly).Magnitude
                local measuredWeight = math.clamp(
                    0.66 - disagreement / 215,
                    0.22,
                    0.66
                )
                if assemblySpeed < 1.0 and displacementVelocity.Magnitude > 2.5 then
                    measuredWeight = math.max(measuredWeight, 0.54)
                elseif referenceSpeed > 75 then
                    measuredWeight = math.max(measuredWeight, 0.56)
                elseif referenceSpeed > 45 then
                    measuredWeight = math.max(measuredWeight, 0.50)
                end

                local candidateVelocity = horizontalAssembly:Lerp(
                    displacementVelocity,
                    measuredWeight
                )

                -- Do not bend prediction toward Humanoid.MoveDirection. It is
                -- input intent, not replicated travel, and can point somewhere the
                -- character never actually reaches (especially during strafes,
                -- knockback, slow walking, or abrupt camera turns). Prediction is
                -- driven only by observed displacement + AssemblyLinearVelocity.
                local observedSpeed = candidateVelocity.Magnitude
                if observedSpeed <= 24 and displacementVelocity.Magnitude > 0.45 then
                    -- Walking/slow targets need the measured path to dominate.
                    -- AssemblyLinearVelocity can be damped or animation-biased at
                    -- these speeds, which used to make the fling sit in front of
                    -- the target rather than staying attached to their root.
                    local slowMeasuredWeight = math.clamp(
                        0.74 + (24 - observedSpeed) / 120,
                        0.74,
                        0.88
                    )
                    candidateVelocity = horizontalAssembly:Lerp(
                        displacementVelocity,
                        slowMeasuredWeight
                    )
                end

                local previousVelocity = smoothedVelocity
                local responsiveness = math.clamp(
                    21
                        + candidateVelocity.Magnitude * 0.145
                        + (1 - motionConsistency) * 4,
                    21,
                    43
                )
                local velocityAlpha = 1 - math.exp(-dt * responsiveness)
                smoothedVelocity = smoothedVelocity:Lerp(
                    candidateVelocity,
                    velocityAlpha
                )

                local rawAcceleration = (smoothedVelocity - previousVelocity) / dt
                local rawAccelerationMagnitude = rawAcceleration.Magnitude
                if rawAccelerationMagnitude > 220 then
                    rawAcceleration = rawAcceleration.Unit * 220
                end
                local accelerationAlpha = 1 - math.exp(
                    -dt * math.clamp(11 + smoothedVelocity.Magnitude * 0.035, 11, 16)
                )
                smoothedAcceleration = smoothedAcceleration:Lerp(
                    rawAcceleration,
                    accelerationAlpha
                )

                local verticalCandidate = assemblyVelocity.Y * 0.62
                    + measuredVertical * 0.38
                verticalCandidate = math.clamp(verticalCandidate, -180, 180)
                local verticalAlpha = 1 - math.exp(-dt * 18)
                smoothedVerticalVelocity = smoothedVerticalVelocity
                    + (verticalCandidate - smoothedVerticalVelocity) * verticalAlpha

                local speed = smoothedVelocity.Magnitude
                local moveDirection
                if speed > 1.25 then
                    moveDirection = smoothedVelocity.Unit
                else
                    local look = targetRoot.CFrame.LookVector
                    moveDirection = Vector3.new(look.X, 0, look.Z)
                    if moveDirection.Magnitude < 0.05 then
                        moveDirection = Vector3.new(0, 0, -1)
                    else
                        moveDirection = moveDirection.Unit
                    end
                end

                -- Track signed turn rate instead of only treating a direction
                -- change as uncertainty. This lets fast circling/zig-zag movement
                -- produce a curved lead rather than always predicting straight.
                local turnDot = math.clamp(
                    previousDirection:Dot(moveDirection),
                    -1,
                    1
                )
                local crossY = previousDirection.Z * moveDirection.X
                    - previousDirection.X * moveDirection.Z
                local signedTurn = math.atan2(crossY, turnDot)
                local rawTurnRate = math.clamp(signedTurn / dt, -12, 12)
                local turnRateAlpha = 1 - math.exp(-dt * 15)
                smoothedTurnRate += (rawTurnRate - smoothedTurnRate) * turnRateAlpha
                if turnDot < -0.30 then
                    -- A near reversal is a zig-zag, not a stable circular arc.
                    -- Drop stale angular momentum so the new direction wins now.
                    smoothedTurnRate = 0
                end

                local turnSeverity = math.clamp((1 - turnDot) * 0.5, 0, 1)
                local lateralAcceleration = smoothedAcceleration
                    - moveDirection * smoothedAcceleration:Dot(moveDirection)
                turnSeverity = math.max(
                    turnSeverity,
                    math.clamp(lateralAcceleration.Magnitude / 190, 0, 1) * 0.68,
                    math.clamp(math.abs(smoothedTurnRate) / 8, 0, 1) * 0.72
                )
                previousDirection = moveDirection

                local ping = getPlayerListPingSeconds()
                local agreementPenalty = math.clamp(disagreement / 145, 0, 1)
                local fastMovementBonus = math.clamp((speed - 28) / 100, 0, 1)
                local stableFastBonus = fastMovementBonus
                    * math.clamp((motionConsistency - 0.52) / 0.48, 0, 1)
                local fastPredictionTime = math.clamp(
                    0.035
                        + ping * 0.98
                        + dt * 0.46
                        + math.min(speed, 155) * 0.00102
                        + fastMovementBonus * 0.014
                        + stableFastBonus * 0.022,
                    0.043,
                    0.285
                )
                local slowPredictionTime = math.clamp(
                    0.016
                        + ping * 0.52
                        + dt * 0.22
                        + math.min(speed, 24) * 0.00032,
                    0.026,
                    0.074
                )
                local speedHorizonBlend = math.clamp((speed - 10) / 30, 0, 1)
                local predictionTime = slowPredictionTime
                    + (fastPredictionTime - slowPredictionTime) * speedHorizonBlend
                predictionTime *= 1
                    - math.max(
                        turnSeverity * (0.24 + (1 - motionConsistency) * 0.18),
                        agreementPenalty * 0.20
                    )
                predictionTime = math.max(predictionTime, 0.024)

                -- Integrate the observed turn as an arc. Midpoint rotation gives
                -- the chord direction, while sinc scaling keeps the chord length
                -- accurate during hard circles instead of over-leading the curve.
                local angularTravel = math.clamp(
                    smoothedTurnRate * predictionTime,
                    -1.12,
                    1.12
                )
                local halfTurn = angularTravel * 0.5
                local arcScale = 1
                if math.abs(halfTurn) > 0.001 then
                    arcScale = math.sin(halfTurn) / halfTurn
                end
                local trajectoryVelocity = rotateHorizontal(
                    smoothedVelocity,
                    halfTurn
                ) * arcScale

                local accelerationLead = smoothedAcceleration
                    * (0.5 * predictionTime * predictionTime)
                local accelerationLeadMagnitude = accelerationLead.Magnitude
                local accelerationLeadCap = math.clamp(
                    0.35 + speed * predictionTime * 0.42,
                    0.35,
                    2.4
                )
                if accelerationLeadMagnitude > accelerationLeadCap
                    and accelerationLeadMagnitude > 0
                then
                    accelerationLead = accelerationLead.Unit * accelerationLeadCap
                end

                local predictedDelta = trajectoryVelocity * predictionTime
                    + accelerationLead
                local predictedDeltaMagnitude = predictedDelta.Magnitude
                local slowCapture = math.clamp((18 - speed) / 18, 0, 1)
                local maxPredictionDistance = math.clamp(
                    speed
                        * predictionTime
                        * (1.18 + stableFastBonus * 0.24)
                        + (0.24 + (1 - slowCapture) * 0.38),
                    0.24,
                    18
                )
                if predictedDeltaMagnitude > maxPredictionDistance
                    and predictedDeltaMagnitude > 0
                then
                    predictedDelta = predictedDelta.Unit * maxPredictionDistance
                end

                local verticalLead = math.clamp(
                    smoothedVerticalVelocity
                        * predictionTime
                        * (0.38 + stableFastBonus * 0.12),
                    -2.25,
                    2.25
                )
                local predictedPosition = currentPosition
                    + predictedDelta
                    + Vector3.new(0, verticalLead, 0)

                local side = Vector3.new(-moveDirection.Z, 0, moveDirection.X)
                local slowContact = math.clamp((20 - speed) / 20, 0, 1)
                local sideRadius = math.clamp(
                    0.026 + speed * 0.00105,
                    0.026,
                    0.16
                )
                local sideOffset = (frame % 2 == 0 and 1 or -1) * sideRadius
                local forwardOffset = math.clamp(
                    speed * 0.00155,
                    0,
                    0.14
                ) * (1 - slowContact * 0.72)
                local contactHeight = 0.36 + (1 - slowContact) * 0.32

                -- Slow walkers get a near-center capture pulse every few frames.
                -- This prevents a small prediction error from keeping the fling
                -- permanently just ahead/alongside a target moving at walk speed.
                if slowContact > 0.15 and frame % 4 == 0 then
                    sideOffset *= 0.28
                    forwardOffset *= 0.20
                    contactHeight = 0.32
                end

                local contactPosition = predictedPosition
                    + side * sideOffset
                    + moveDirection * forwardOffset
                    + Vector3.new(0, contactHeight, 0)

                root.CFrame = CFrame.lookAt(
                    contactPosition,
                    contactPosition + moveDirection
                )
                root.AssemblyLinearVelocity = Vector3.new(
                    smoothedVelocity.X * 0.15,
                    -1000000000,
                    smoothedVelocity.Z * 0.15
                )
                root.AssemblyAngularVelocity = Vector3.new(
                    0,
                    (frame % 2 == 0 and 1 or -1) * 100000000,
                    0
                )

                pcall(function()
                    targetRoot.AssemblyLinearVelocity = Vector3.new(
                        assemblyVelocity.X * 0.15,
                        -1000000000,
                        assemblyVelocity.Z * 0.15
                    )
                end)
            end

            ListRuntime.flingRunning = false

            for part, canCollide in pairs(targetCollision) do
                if part.Parent then
                    part.CanCollide = canCollide
                end
            end
            for part, canCollide in pairs(ownCollision) do
                if part.Parent then
                    part.CanCollide = canCollide
                end
            end

            pcall(function()
                PlayerListWorkspace.FallenPartsDestroyHeight = savedDestroyHeight
            end)

            if root.Parent and LocalListPlayer.Character == character then
                root.AssemblyLinearVelocity = Vector3.zero
                root.AssemblyAngularVelocity = Vector3.zero
                root.CFrame = savedCFrame + Vector3.new(0, 3, 0)
                humanoid.PlatformStand = savedPlatformStand
                humanoid.AutoRotate = savedAutoRotate
                humanoid:ChangeState(Enum.HumanoidStateType.GettingUp)

                task.defer(function()
                    if root.Parent and LocalListPlayer.Character == character then
                        root.AssemblyLinearVelocity = savedLinearVelocity
                        root.AssemblyAngularVelocity = savedAngularVelocity
                    end
                end)
            end
        end)
    end

    Connect(FlingButton.on_clicked, function()
        local targetPlayer = ListRuntime.selected
        if not targetPlayer or targetPlayer == LocalListPlayer then
            return
        end
        flingSelectedPlayer(targetPlayer)
    end)

    Connect(TeleportTo.on_clicked, function()
        local targetPlayer = ListRuntime.selected
        if not targetPlayer or targetPlayer == LocalListPlayer then
            return
        end

        local localCharacter = LocalListPlayer.Character
        local targetCharacter = targetPlayer.Character
        if not localCharacter or not targetCharacter then
            return
        end

        local localRoot = localCharacter:FindFirstChild("HumanoidRootPart")
            or localCharacter.PrimaryPart
        local targetRoot = targetCharacter:FindFirstChild("HumanoidRootPart")
            or targetCharacter.PrimaryPart

        if not localRoot or not targetRoot then
            return
        end

        pcall(function()
            localCharacter:PivotTo(targetRoot.CFrame * CFrame.new(3, 0, 0))
        end)
    end)

    local function trim(value)
        value = tostring(value or "")
        return value:match("^%s*(.-)%s*$") or ""
    end

    local function compactProfileValue(value, maxChars)
        value = tostring(value or "")
        maxChars = tonumber(maxChars) or 15
        if #value <= maxChars then
            return value
        end
        return value:sub(1, math.max(1, maxChars - 3)) .. "..."
    end

    local getInGameName

    local function updateProfileIdentity(player)
        if not player then
            return
        end

        local gameName = getInGameName and getInGameName(player) or ""
        profileName.Text = "InGame : "
            .. compactProfileValue(gameName ~= "" and gameName or "Unknown", 22)

        if profileDisplay then
            profileDisplay.Text = "Display : "
                .. compactProfileValue(player.DisplayName or player.Name, 22)
        end

        if profileId then
            profileId.Text = "User : "
                .. compactProfileValue(player.Name, 24)
        end
    end

    local FIRST_KEYS = {
        "FirstName", "Firstname", "First", "GivenName", "Forename",
    }
    local LAST_KEYS = {
        "LastName", "Lastname", "Last", "Surname", "FamilyName",
    }
    local FULL_KEYS = {
        "RPName", "RoleplayName", "CharacterName", "FullName",
    }

    local function readNameValue(target, keys)
        if not target then
            return nil
        end

        for _, key in ipairs(keys) do
            local ok, value = pcall(target.GetAttribute, target, key)
            if ok and typeof(value) == "string" then
                value = trim(value)
                if value ~= "" then
                    return value
                end
            end

            local child = target:FindFirstChild(key)
            if child and child:IsA("StringValue") then
                local valueObject = trim(child.Value)
                if valueObject ~= "" then
                    return valueObject
                end
            end
        end

        return nil
    end

    getInGameName = function(player)
        if not player then
            return ""
        end

        local character = player.Character
        local playerData = character and character:FindFirstChild("PlayerData")
        local targets = {player, character, playerData}
        local first, last, full

        for _, target in ipairs(targets) do
            if target then
                first = first or readNameValue(target, FIRST_KEYS)
                last = last or readNameValue(target, LAST_KEYS)
                full = full or readNameValue(target, FULL_KEYS)
            end
        end

        if first or last then
            local combined = trim((first or "") .. " " .. (last or ""))
            if combined ~= "" then
                return combined
            end
        end

        if full and full ~= "" then
            return full
        end

        return trim(player.DisplayName) ~= ""
            and player.DisplayName
            or player.Name
    end

    local function restoreLocalCamera()
        local camera = PlayerListWorkspace.CurrentCamera
        local character = LocalListPlayer and LocalListPlayer.Character
        local humanoid = character and character:FindFirstChildOfClass("Humanoid")
        if camera and humanoid then
            pcall(function()
                camera.CameraSubject = humanoid
            end)
        end
    end

    local function applySpectate()
        if Flags.list_player_spectate ~= true then
            restoreLocalCamera()
            return
        end

        local player = ListRuntime.selected
        local character = player and player.Character
        local humanoid = character and character:FindFirstChildOfClass("Humanoid")
        local camera = PlayerListWorkspace.CurrentCamera
        if not player or not player.Parent or not humanoid or not camera then
            restoreLocalCamera()
            return
        end

        pcall(function()
            camera.CameraSubject = humanoid
        end)
    end

    local function destroyAvatarImage()
        ListRuntime.avatarSerial += 1
        if avatarImage then
            pcall(function()
                avatarImage:Destroy()
            end)
            avatarImage = nil
        end
    end

    local function setAvatarData(data, serial)
        if ListRuntime.destroyed
            or serial ~= ListRuntime.avatarSerial
            or type(data) ~= "string"
            or data == ""
            or not avatarInside
            or type(Menu.create_proxy_drawing) ~= "function"
        then
            return
        end

        if avatarImage then
            pcall(function()
                avatarImage:Destroy()
            end)
        end

        avatarImage = Menu.create_proxy_drawing("Image", {
            ["Parent"] = avatarInside,
            ["Position"] = UDim2.new(0, 0, 0, 0),
            ["Size"] = UDim2.new(1, 0, 1, 0),
            ["Color"] = Color3.fromRGB(255, 255, 255),
            ["Transparency"] = 1,
            ["Visible"] = true,
            ["ZIndex"] = Profile.frame.ZIndex + 4,
            ["Data"] = data,
        })
    end

    local function fetchAvatarBytes(userId)
        local metadata = playerListHttpGet(
            "https://thumbnails.roblox.com/v1/users/avatar-headshot?userIds="
            .. tostring(userId)
            .. "&size=150x150&format=Png&isCircular=false"
        )
        local decoded = playerListJsonDecode(metadata)
        local entry = decoded
            and decoded.data
            and decoded.data[1]
        local imageUrl = entry and entry.imageUrl
        if type(imageUrl) ~= "string" or imageUrl == "" then
            return nil
        end
        return playerListHttpGet(imageUrl)
    end

    local function prefetchAvatar(player)
        if not player then
            return
        end

        local userId = player.UserId
        if ListRuntime.thumbnailCache[userId]
            or ListRuntime.thumbnailLoading[userId]
        then
            return
        end

        ListRuntime.thumbnailLoading[userId] = true
        task.spawn(function()
            local ok, bytes = pcall(fetchAvatarBytes, userId)
            ListRuntime.thumbnailLoading[userId] = nil

            if ListRuntime.destroyed then
                return
            end

            if ok and type(bytes) == "string" and bytes ~= "" then
                ListRuntime.thumbnailCache[userId] = bytes
                local selected = ListRuntime.selected
                if selected and selected.UserId == userId then
                    setAvatarData(bytes, ListRuntime.avatarSerial)
                end
            end
        end)
    end

    local function prefetchAllAvatars(players)
        local pending = {}
        local ids = {}

        for _, player in ipairs(players or {}) do
            if player
                and player ~= LocalListPlayer
                and not ListRuntime.thumbnailCache[player.UserId]
                and not ListRuntime.thumbnailLoading[player.UserId]
            then
                local userId = player.UserId
                pending[userId] = true
                ids[#ids + 1] = tostring(userId)
                ListRuntime.thumbnailLoading[userId] = true
            end
        end

        if #ids == 0 then
            return
        end

        task.spawn(function()
            local ok, decoded = pcall(function()
                local metadata = playerListHttpGet(
                    "https://thumbnails.roblox.com/v1/users/avatar-headshot?userIds="
                    .. table.concat(ids, ",")
                    .. "&size=150x150&format=Png&isCircular=false"
                )
                return playerListJsonDecode(metadata)
            end)

            if ListRuntime.destroyed then
                return
            end

            if not ok or type(decoded) ~= "table" or type(decoded.data) ~= "table" then
                for userId in pairs(pending) do
                    ListRuntime.thumbnailLoading[userId] = nil
                    local player = playerListGetPlayerByUserId(userId)
                    if player then
                        prefetchAvatar(player)
                    end
                end
                return
            end

            local resolved = {}
            for _, entry in ipairs(decoded.data) do
                local userId = tonumber(entry and (entry.targetId or entry.userId))
                local imageUrl = entry and entry.imageUrl
                if userId and pending[userId] then
                    resolved[userId] = true
                    if type(imageUrl) == "string" and imageUrl ~= "" then
                        task.spawn(function()
                            local imageOk, bytes = pcall(function()
                                return playerListHttpGet(imageUrl)
                            end)
                            ListRuntime.thumbnailLoading[userId] = nil

                            if ListRuntime.destroyed then
                                return
                            end

                            if imageOk and type(bytes) == "string" and bytes ~= "" then
                                ListRuntime.thumbnailCache[userId] = bytes
                                local selected = ListRuntime.selected
                                if selected and selected.UserId == userId then
                                    setAvatarData(bytes, ListRuntime.avatarSerial)
                                end
                            end
                        end)
                    else
                        ListRuntime.thumbnailLoading[userId] = nil
                    end
                end
            end

            for userId in pairs(pending) do
                if not resolved[userId] then
                    ListRuntime.thumbnailLoading[userId] = nil
                    local player = playerListGetPlayerByUserId(userId)
                    if player then
                        prefetchAvatar(player)
                    end
                end
            end
        end)
    end

    local function loadAvatar(player)
        destroyAvatarImage()
        if not player or not avatarInside then
            return
        end

        local userId = player.UserId
        local cached = ListRuntime.thumbnailCache[userId]
        if cached then
            setAvatarData(cached, ListRuntime.avatarSerial)
            return
        end

        -- Initial server thumbnails are batch-warmed as List is built. This
        -- remains as a priority fallback for a newly joined/uncached player.
        prefetchAvatar(player)
    end

    local function updateProfile(player)
        ListRuntime.selected = player

        if not player then
            profileName.Text = "No players"
            profileName.Color = Menu.colors.inactive_text
            if profileDisplay then
                profileDisplay.Text = ""
            end
            if profileId then
                profileId.Text = ""
            end
            destroyAvatarImage()
            TeleportTo:set_visible(false)
            FlingButton:set_visible(false)
            Spectate:set_visible(false)
            Visualize:set_visible(false)
            Status:set_visible(false)
            if Flags.list_player_spectate == true then
                Spectate:set_toggle(false)
            else
                restoreLocalCamera()
            end
            if Flags.list_player_visualize == true then
                Visualize:set_toggle(false)
            else
                refreshPlayerVisualize()
            end
            Status:set_dropdown(nil, false, true)
            PlayerSection:recalculate_size()
            return
        end

        updateProfileIdentity(player)
        profileName.Color = Menu.colors.active_text

        TeleportTo:set_visible(true)
        FlingButton:set_visible(true)
        Spectate:set_visible(true)
        Visualize:set_visible(true)
        Status:set_visible(true)

        local relation = Menu._GetPlayerRelation(player)
        Status:set_dropdown(relation and {relation} or nil, false, true)
        PlayerSection:recalculate_size()

        if Flags.list_player_spectate == true then
            applySpectate()
        end
        if Flags.list_player_visualize == true then
            refreshPlayerVisualize()
        end
    end

    local function trimPlayerListText(object, fullText, maxWidth)
        if not object then
            return
        end

        fullText = tostring(fullText or "")
        maxWidth = math.max(0, tonumber(maxWidth) or 0)
        object.Text = fullText

        if maxWidth <= 0 then
            object.Text = ""
            return
        end

        if (tonumber(object.TextBounds.X) or 0) <= maxWidth then
            return
        end

        local suffix = ".."
        object.Text = suffix
        if (tonumber(object.TextBounds.X) or 0) > maxWidth then
            object.Text = ""
            return
        end

        local length = utf8.len(fullText) or #fullText
        local low = 0
        local high = length

        while low < high do
            local mid = math.ceil((low + high) * 0.5)
            local nextByte = utf8.offset(fullText, mid + 1)
            local prefix = nextByte
                and fullText:sub(1, nextByte - 1)
                or fullText

            object.Text = prefix .. suffix
            if (tonumber(object.TextBounds.X) or 0) <= maxWidth then
                low = mid
            else
                high = mid - 1
            end
        end

        local nextByte = utf8.offset(fullText, low + 1)
        local prefix = nextByte
            and fullText:sub(1, nextByte - 1)
            or fullText
        object.Text = prefix .. suffix
    end

    local function fitPlayerListRow(row)
        local drawings = row and row.drawings
        if not drawings then
            return
        end

        local border = drawings.border
        local usernameText = drawings.text
        local gameNameText = drawings.text2
        if not border or not usernameText then
            return
        end

        local borderSize = border.real_size
        local borderPosition = border.real_position
        local usernamePosition = usernameText.real_position
        local width = typeof(borderSize) == "Vector2"
            and borderSize.X
            or 0
        local startX = 4

        if typeof(borderPosition) == "Vector2"
            and typeof(usernamePosition) == "Vector2"
        then
            startX = math.max(0, usernamePosition.X - borderPosition.X)
        end

        local available = math.max(24, width - startX - 6)
        local username = tostring(row.name or "")
        local gameName = tostring(row.text2 or "")

        usernameText.Text = username
        if not gameNameText or gameName == "" then
            trimPlayerListText(usernameText, username, available)
            return
        end

        gameNameText.Text = gameName
        local gap = 3
        local usernameWidth = tonumber(usernameText.TextBounds.X) or 0
        local gameNameWidth = tonumber(gameNameText.TextBounds.X) or 0

        if usernameWidth + gap + gameNameWidth > available then
            local reservedForGameName = math.min(
                gameNameWidth,
                math.max(44, available * 0.45)
            )
            local usernameMax = math.max(
                38,
                available - reservedForGameName - gap
            )
            trimPlayerListText(usernameText, username, usernameMax)
            usernameWidth = tonumber(usernameText.TextBounds.X) or 0
        end

        -- Drawing proxies do not guarantee Position.X is a UDim. Use the
        -- already-resolved pixel offset so long-name fitting cannot index
        -- a numeric X value as `.Offset`.
        local relativeX = startX
        gameNameText.Position = UDim2.new(
            0,
            relativeX + usernameWidth + gap,
            0,
            3
        )

        local remaining = math.max(
            0,
            available - usernameWidth - gap
        )
        trimPlayerListText(gameNameText, gameName, remaining)
    end

    local function refreshRow(player)
        if not player or player == LocalListPlayer then
            return
        end
        local row = ListRuntime.rows[player.UserId]
        if not row then
            return
        end

        local gameName = getInGameName(player)
        if row.text2 ~= gameName then
            row.text2 = gameName
            local text2 = row.drawings and row.drawings.text2
            if text2 then
                text2.Text = gameName
            end
        end

        local statusColor = getRowStatusColor(player)
        -- Relation state must not tint the row itself. Only the in-game name
        -- carries Friendly/Priority color; normal hover/selection owns the border.
        row.status_color = nil

        local drawings = row.drawings
        if drawings then
            local border = drawings.border
            local usernameText = drawings.text
            local gameNameText = drawings.text2

            if border then
                border.Color = PlayersPanel.selected == row
                    and Menu.colors.highlighted
                    or Menu.colors.border
            end
            if usernameText then
                usernameText.Color = Menu.colors.inactive_text
            end
            if gameNameText then
                gameNameText.Color = statusColor or Menu.colors.dark_text
            end

            fitPlayerListRow(row)
        end

        if ListRuntime.selected == player then
            updateProfileIdentity(player)
        end
    end
    ListRuntime.refreshRow = refreshRow

    local function setPanelSelectedPlayer(player)
        if not player
            or player == LocalListPlayer
            or player.Parent ~= PlayerListPlayers
        then
            return false
        end

        local row = ListRuntime.rows[player.UserId]
        if not row then
            return false
        end

        local previousRow = PlayersPanel.selected
        if previousRow and previousRow ~= row then
            local previousBorder = previousRow.drawings and previousRow.drawings.border
            if previousBorder then
                previousBorder.Color = Menu.colors.border
            end
        end

        PlayersPanel.selected = row
        local border = row.drawings and row.drawings.border
        if border then
            border.Color = Menu.colors.highlighted
        end

        updateProfile(player)
        return true
    end

    local function selectFirstAvailablePlayer()
        if ListRuntime.destroyed then
            return nil
        end

        local elements = PlayersPanel.elements or {}
        for _, row in ipairs(elements) do
            local username = row
                and row.name
                or row
                and row.drawings
                and row.drawings.text
                and row.drawings.text.Text

            if type(username) == "string" and username ~= "" then
                local player = PlayerListPlayers:FindFirstChild(username)
                if player
                    and player:IsA("Player")
                    and player ~= LocalListPlayer
                    and setPanelSelectedPlayer(player)
                then
                    return player
                end
            end
        end

        for _, player in ipairs(PlayerListPlayers:GetPlayers()) do
            if player ~= LocalListPlayer and setPanelSelectedPlayer(player) then
                return player
            end
        end

        PlayersPanel.selected = nil
        updateProfile(nil)
        return nil
    end

    local function disconnectPlayer(player)
        if not player then
            return
        end
        local connections = ListRuntime.playerConnections[player.UserId]
        ListRuntime.playerConnections[player.UserId] = nil
        if type(connections) == "table" then
            for _, connection in ipairs(connections) do
                pcall(function()
                    connection:Disconnect()
                end)
            end
        end
    end

    local function addPlayer(player)
        if not player
            or player == LocalListPlayer
            or ListRuntime.rows[player.UserId]
        then
            return
        end

        local row = PlayersPanel:add_item({
            ["text"] = player.Name,
            ["text2"] = getInGameName(player),
            ["icons"] = {PLAYER_ROW_ICON_DATA},
        })
        ListRuntime.rows[player.UserId] = row
        refreshRow(player)
        refreshFriendState(player)

        local connections = {}
        ListRuntime.playerConnections[player.UserId] = connections

        connections[#connections + 1] = player.CharacterAdded:Connect(function()
            task.delay(0.20, function()
                if player.Parent and not ListRuntime.destroyed then
                    refreshRow(player)
                    if ListRuntime.selected == player
                        and Flags.list_player_spectate == true
                    then
                        applySpectate()
                    end
                    if (ListRuntime.selected == player
                            and Flags.list_player_visualize == true)
                        or (Flags.list_whitelist_friends == true
                            and Flags.list_visualize_whitelist == true
                            and Menu._FriendWhitelist[player.UserId] == true)
                    then
                        refreshPlayerVisualize()
                    end
                end
            end)
            task.delay(1.00, function()
                if player.Parent and not ListRuntime.destroyed then
                    refreshRow(player)
                end
            end)
        end)

        connections[#connections + 1] = player:GetPropertyChangedSignal("DisplayName"):Connect(function()
            refreshRow(player)
        end)
    end

    local function removePlayer(player)
        if not player or player == LocalListPlayer then
            return
        end

        local wasSelected = ListRuntime.selected == player
            or PlayersPanel.selected == ListRuntime.rows[player.UserId]

        disconnectPlayer(player)
        Menu._FriendWhitelist[player.UserId] = nil
        ListRuntime.rows[player.UserId] = nil
        PlayersPanel:remove_item(player.Name, false, true)

        if wasSelected or not ListRuntime.selected
            or ListRuntime.selected.Parent ~= PlayerListPlayers
        then
            selectFirstAvailablePlayer()
        end
    end

    Connect(PlayersPanel.on_selection_change, function(username)
        if type(username) == "string" and username ~= "" then
            local candidate = PlayerListPlayers:FindFirstChild(username)
            if candidate
                and candidate:IsA("Player")
                and candidate ~= LocalListPlayer
            then
                setPanelSelectedPlayer(candidate)
                return
            end
        end

        selectFirstAvailablePlayer()
    end)

    Connect(Spectate.on_toggle_change, function()
        applySpectate()
    end)

    Connect(Visualize.on_toggle_change, function()
        refreshPlayerVisualize()
    end)

    Connect(VisualizeWhitelist.on_toggle_change, function()
        if Flags.list_whitelist_friends == true then
            for _, player in ipairs(PlayerListPlayers:GetPlayers()) do
                if player ~= LocalListPlayer then
                    refreshFriendState(player)
                end
            end
        end
        refreshPlayerVisualize()
    end)

    Connect(Status.on_dropdown_change, function(value)
        local player = ListRuntime.selected
        if not player then
            return
        end

        local relation = type(value) == "table" and value[1] or value
        if relation ~= "Friendly" and relation ~= "Priority" then
            relation = nil
        end
        Menu._PlayerRelations[player.UserId] = relation
        refreshRow(player)
        refreshPlayerVisualize()

        if relation == "Friendly" then
            local character = player.Character
            local faceRuntime = Menu._AutoFaceRuntime
            if character and faceRuntime then
                if faceRuntime.lockedTarget == character
                    and type(faceRuntime.clearTargetLock) == "function"
                then
                    pcall(faceRuntime.clearTargetLock)
                end
                if faceRuntime.defenseHintTarget == character
                    and type(faceRuntime.clearDefenseHint) == "function"
                then
                    pcall(faceRuntime.clearDefenseHint)
                end
            end
        end
    end)

    Connect(WhitelistFriends.on_toggle_change, function(value)
        if value == true then
            for _, player in ipairs(PlayerListPlayers:GetPlayers()) do
                if player ~= LocalListPlayer then
                    refreshFriendState(player)
                end
            end
        end

        for _, player in ipairs(PlayerListPlayers:GetPlayers()) do
            if player ~= LocalListPlayer then
                refreshRow(player)
            end
        end
        refreshPlayerVisualize()

        if value == true then
            local faceRuntime = Menu._AutoFaceRuntime
            local locked = faceRuntime and faceRuntime.lockedTarget
            if locked and Menu._IsFriendlyCharacter(locked) then
                if type(faceRuntime.clearTargetLock) == "function" then
                    pcall(faceRuntime.clearTargetLock)
                end
                if type(faceRuntime.clearDefenseHint) == "function" then
                    pcall(faceRuntime.clearDefenseHint)
                end
            end
        end
    end)

    local initialPlayers = PlayerListPlayers:GetPlayers()
    for _, player in ipairs(initialPlayers) do
        addPlayer(player)
    end
    selectFirstAvailablePlayer()

    local function onPlayerAdded(player)
        addPlayer(player)

        if not ListRuntime.selected
            or ListRuntime.selected.Parent ~= PlayerListPlayers
        then
            selectFirstAvailablePlayer()
        end
    end

    local runtime = Menu._ScriptRuntime
    if runtime and type(runtime.Track) == "function" then
        runtime:Track(PlayerListPlayers.PlayerAdded:Connect(onPlayerAdded))
        runtime:Track(PlayerListPlayers.PlayerRemoving:Connect(removePlayer))
    else
        Connect(PlayerListPlayers.PlayerAdded, onPlayerAdded)
        Connect(PlayerListPlayers.PlayerRemoving, removePlayer)
    end

    task.spawn(function()
        while not ListRuntime.destroyed
            and (not runtime or runtime.alive == true)
        do
            task.wait(1.5)
            if ListRuntime.destroyed then
                break
            end
            for _, player in ipairs(PlayerListPlayers:GetPlayers()) do
                if player ~= LocalListPlayer then
                    refreshRow(player)
                end
            end
        end
    end)

    local function cleanupPlayerList()
        if ListRuntime.destroyed then
            return
        end
        ListRuntime.destroyed = true
        stopPlayerListFling()
        restoreLocalCamera()
        destroyAvatarImage()
        for _, player in ipairs(PlayerListPlayers:GetPlayers()) do
            disconnectPlayer(player)
        end
    end

    if runtime and type(runtime.AddCleanup) == "function" then
        runtime:AddCleanup(cleanupPlayerList)
    end
end

Menu._SettingsUI = Menu._SettingsUI or {}

