do
    local CONFIG_ROW_ICON_DATA = base64_decode(
        ""
    )
    local panel = Menu._SettingsUI.Configs
    local nativeConfigUpdatePosition = panel.update_position

    local function stabilizeConfigRows(self)
        for _, row in ipairs(self.elements or {}) do
            local drawings = row and row.drawings
            local border = drawings and drawings.border
            local inside = drawings and drawings.inside

            if border then
                border.Transparency = 1
                border.Rounding = 4
                border.Color = self.selected == row
                    and Menu.colors.highlighted
                    or Menu.colors.border
            end

            if inside then
                inside.Transparency = 1
                inside.Rounding = 4
                inside.Color = Menu.colors.background
            end
        end
    end

    function panel:update_position(...)
        if type(nativeConfigUpdatePosition) == "function" then
            nativeConfigUpdatePosition(self, ...)
        end
        stabilizeConfigRows(self)
    end

    function panel:set_options(options)
        options = type(options) == "table" and options or {}
        local existing = {}
        for index = 1, #(self.elements or {}) do
            local row = self.elements[index]
            existing[#existing + 1] = row and row.name
        end
        for index = #existing, 1, -1 do
            if existing[index] then
                self:remove_item(existing[index], false, true)
            end
        end

        for _, name in ipairs(options) do
            -- Use the panel library's native list-item button exactly like Player List:
            -- normal border when idle, highlighted border on hover/selection.
            self:add_item({
                ["text"] = tostring(name),
                ["icons"] = {CONFIG_ROW_ICON_DATA},
            })
        end
        self:update_position()
        stabilizeConfigRows(self)
    end

    function panel:set_dropdown(value)
        local selected = type(value) == "table" and value[1] or value
        selected = selected and tostring(selected) or nil

        if self.selected and self.selected.drawings and self.selected.drawings.border then
            self.selected.drawings.border.Color = Menu.colors.border
        end
        self.selected = nil

        for _, row in ipairs(self.elements or {}) do
            if row and row.name == selected then
                self.selected = row
                if row.drawings and row.drawings.border then
                    row.drawings.border.Color = Menu.colors.highlighted
                end
                break
            end
        end

        Flags.settings_config_selected = selected and {selected} or nil
        self:update_position()
    end

    Connect(panel.on_selection_change, function(name)
        if type(name) == "string" and name ~= "" then
            Flags.settings_config_selected = {name}
        else
            Flags.settings_config_selected = nil
        end

        if panel.selected
            and panel.selected.drawings
            and panel.selected.drawings.border
        then
            panel.selected.drawings.border.Color = Menu.colors.highlighted
        end

        if type(Menu._UpdateConfigInfo) == "function" then
            Menu._UpdateConfigInfo(name)
        end
    end)
end

do
    local function notifyConfig(message, kind, duration)
        local notifier = Menu and Menu.new_notification
        if type(notifier) == "function" then
            pcall(
                notifier,
                tostring(message or ""),
                tonumber(kind) or 0,
                tonumber(duration) or 2.5
            )
        end
    end

    local function normalizeConfigName(value)
        local depth = 0
        while type(value) == "table"
            and depth < 6
        do
            value =
                value[1]
                or value.value
                or value.Value
                or value.name
                or value.Name
            depth += 1
        end

        value = tostring(value or "")
            :gsub("[^%w%-%_]", "_")

        return value
    end

    local function configEditorName()
        return normalizeConfigName(
            Flags.settings_config_name
        )
    end

    local function selectedConfigName()
        local selected = Flags.settings_config_selected
        if type(selected) == "table" then
            selected = selected[1]
        end
        return normalizeConfigName(selected)
    end

    local function getConfigList()
        if type(Menu.get_config_list) == "function" then
            local ok, result = pcall(Menu.get_config_list)
            if not ok then
                ok, result = pcall(Menu.get_config_list, Menu)
            end
            if ok and type(result) == "table" then
                return result
            end
        end

        local options = {}
        local root = tostring(Menu.storage_root or "SilentSolutions/Gakuran")
        if type(listfiles) == "function" then
            local ok, files = pcall(listfiles, root .. "/configs/")
            if ok and type(files) == "table" then
                for _, path in ipairs(files) do
                    local name = tostring(path)
                        :gsub("\\", "/")
                        :match("([^/]+)%.cfg$")
                    if name and name ~= "" then
                        options[#options + 1] = name
                    end
                end
            end
        end
        table.sort(options)
        return options
    end

    local function configExists(name)
        name = normalizeConfigName(name)
        if name == "" then
            return false
        end
        for _, existing in ipairs(getConfigList()) do
            if tostring(existing) == name then
                return true
            end
        end
        return false
    end

    local function refreshConfigList(preferredSelection)
        local options = getConfigList()
        local seen = {}
        local clean = {}

        for _, value in ipairs(options) do
            local name = normalizeConfigName(value)
            if name ~= ""
                and name:lower() ~= "default"
                and not seen[name]
            then
                seen[name] = true
                clean[#clean + 1] = name
            end
        end

        table.sort(clean)

        local list = Menu._SettingsUI.ConfigList
        if list and type(list.set_options) == "function" then
            pcall(list.set_options, list, clean)
        end

        local selection = preferredSelection
        if selection == nil then
            local current = Flags.settings_config_selected
            if type(current) == "table" then
                current = current[1]
            end
            selection = current
        end
        selection = selection and normalizeConfigName(selection) or nil

        local validSelection = false
        if selection then
            for _, name in ipairs(clean) do
                if name == selection then
                    validSelection = true
                    break
                end
            end
        end
        if not validSelection then
            selection = nil
        end

        if list and type(list.set_dropdown) == "function" then
            pcall(
                list.set_dropdown,
                list,
                selection and {selection} or nil,
                false,
                true
            )
        else
            Flags.settings_config_selected = selection and { selection } or nil
        end

        if type(Menu._UpdateConfigInfo) == "function" then
            Menu._UpdateConfigInfo(selection)
        end

        Menu._SettingsConfigOptions = clean
        return clean, selection
    end

    local MAIN_CONFIG_MAGIC =
        "SILENT_MAIN_CFG_V1\n"

    local function safeConfigValue(
        value,
        seen,
        depth
    )
        local valueType =
            typeof(value)

        depth =
            tonumber(depth)
            or 0

        if depth > 10 then
            return nil
        end

        if value == nil
            or valueType == "string"
            or valueType == "boolean"
        then
            return value
        end

        if valueType == "number" then
            if value ~= value
                or value == math.huge
                or value == -math.huge
            then
                return nil
            end

            return value
        end

        if valueType == "Color3" then
            return {
                math.floor(
                    value.R * 255 + 0.5
                ),
                math.floor(
                    value.G * 255 + 0.5
                ),
                math.floor(
                    value.B * 255 + 0.5
                ),
            }
        end

        if valueType == "EnumItem" then
            return value.Name
        end

        if valueType == "Vector2" then
            return {
                value.X,
                value.Y,
            }
        end

        if valueType == "Vector3" then
            return {
                value.X,
                value.Y,
                value.Z,
            }
        end

        if valueType == "UDim" then
            return {
                value.Scale,
                value.Offset,
            }
        end

        if valueType == "UDim2" then
            return {
                value.X.Scale,
                value.X.Offset,
                value.Y.Scale,
                value.Y.Offset,
            }
        end

        if valueType == "CFrame" then
            return {
                value:GetComponents()
            }
        end

        if valueType ~= "table" then
            return nil
        end

        seen =
            seen
            or {}

        if seen[value] then
            return nil
        end

        seen[value] =
            true

        local result = {}

        for key, child in pairs(value) do
            local keyType =
                typeof(key)

            if keyType == "string"
                or keyType == "number"
            then
                local safeChild =
                    safeConfigValue(
                        child,
                        seen,
                        depth + 1
                    )

                if safeChild ~= nil then
                    result[key] =
                        safeChild
                end
            end
        end

        seen[value] =
            nil

        return result
    end

    local function configPath(name)
        local root =
            tostring(
                Menu.storage_root
                or "SilentSolutions/Gakuran"
            )

        return root
            .. "/configs/"
            .. normalizeConfigName(name)
            .. ".cfg"
    end

    local function ensureConfigFolder()
        if type(makefolder) ~= "function"
            or type(isfolder) ~= "function"
        then
            return
        end

        local root =
            tostring(
                Menu.storage_root
                or "SilentSolutions/Gakuran"
            )

        if not isfolder("SilentSolutions") then
            pcall(
                makefolder,
                "SilentSolutions"
            )
        end

        if not isfolder(root) then
            pcall(
                makefolder,
                root
            )
        end

        local configs =
            root
            .. "/configs"

        if not isfolder(configs) then
            pcall(
                makefolder,
                configs
            )
        end
    end

    local function normalizeSingleDropdownValue(
        value,
        fallback
    )
        local depth = 0

        while type(value) == "table"
            and depth < 6
        do
            value =
                value[1]
                or value.value
                or value.Value
                or value.name
                or value.Name
            depth += 1
        end

        value =
            tostring(
                value
                or fallback
                or ""
            )

        return value
    end

    local WORLD_SOUND_CONFIG_LABELS = {
        ["Resturant"] = true,
        ["Night Ambience"] = true,
        ["Ambience 1"] = true,
        ["Ambience 2"] = true,
        ["Ambience 3"] = true,
        ["Ambience 4"] = true,
        ["Birds 1"] = true,
        ["Birds 2"] = true,
        ["Birds 3"] = true,
        ["Wind / Birds"] = true,
        ["Indoor rain"] = true,
        ["Heavy rain"] = true,
    }

    local WORLD_SOUND_LEGACY_INDEX_TO_LABEL = {
        ["1"] = "Resturant",
        ["2"] = "Birds 1",
        ["3"] = "Birds 2",
        ["4"] = "Night Ambience",
        ["5"] = "Birds 3",
        ["6"] = "Ambience 1",
        ["7"] = "Indoor rain",
        ["8"] = "Ambience 2",
        ["10"] = "Ambience 3",
        ["14"] = "Wind / Birds",
        ["16"] = "Heavy rain",
        ["17"] = "Ambience 4",
    }

    local function normalizeWorldSoundConfigSelection(value)
        local depth = 0

        while type(value) == "table"
            and depth < 6
        do
            value =
                value[1]
                or value.value
                or value.Value
                or value.name
                or value.Name
            depth += 1
        end

        value = tostring(value or "")

        if WORLD_SOUND_CONFIG_LABELS[value] then
            return value
        end

        local legacy =
            WORLD_SOUND_LEGACY_INDEX_TO_LABEL[
                value
            ]
        if legacy then
            return legacy
        end

        local lower =
            value:lower()

        for label in pairs(
            WORLD_SOUND_CONFIG_LABELS
        ) do
            if label:lower() == lower then
                return label
            end
        end

        return "Birds 1"
    end

    local function normalizeWorldSoundConfigVolume(value)
        return math.clamp(
            tonumber(value) or 20,
            0,
            100
        )
    end

    local PARTICLE_AURA_PRESET_NAMES = {
        starlight = true,
        heavenly = true,
        ribbon = true,
        sakura = true,
        angel = true,
        wind = true,
        flow = true,
        star = true,
    }

    local function normalizeParticleAuraConfigSelection(value)
        local depth = 0

        while type(value) == "table"
            and depth < 6
        do
            value =
                value[1]
                or value.value
                or value.Value
                or value.name
                or value.Name
            depth += 1
        end

        value =
            tostring(value or "")

        if value == "" then
            return "angel"
        end

        local lower =
            value:lower()

        if PARTICLE_AURA_PRESET_NAMES[
            lower
        ] then
            return lower
        end

        -- Preserve custom .rbxm/.rbmx selections exactly as saved.
        return value
    end

    local function normalizeHudConfigPosition(
        value,
        fallback
    )
        local x = nil
        local y = nil

        if typeof(value) == "Vector2" then
            x = tonumber(value.X)
            y = tonumber(value.Y)
        elseif type(value) == "table" then
            x = tonumber(
                value[1]
                or value.x
                or value.X
            )
            y = tonumber(
                value[2]
                or value.y
                or value.Y
            )
        end

        if x == nil or x ~= x
            or x == math.huge
            or x == -math.huge
        then
            x = nil
        end

        if y == nil or y ~= y
            or y == math.huge
            or y == -math.huge
        then
            y = nil
        end

        if (x == nil or y == nil)
            and fallback ~= nil
        then
            local fallbackPosition =
                normalizeHudConfigPosition(
                    fallback,
                    nil
                )

            if fallbackPosition then
                x = x or fallbackPosition[1]
                y = y or fallbackPosition[2]
            end
        end

        if x == nil or y == nil then
            return nil
        end

        return { x, y }
    end

    local function readHudProxyPosition(
        frame,
        fallback
    )
        if type(frame) == "table" then
            local current =
                rawget(frame, "position")

            if current
                and current.X
                and current.Y
            then
                local fromUdim =
                    normalizeHudConfigPosition({
                        current.X.Offset,
                        current.Y.Offset,
                    })

                if fromUdim then
                    return fromUdim
                end
            end

            local real =
                frame.real_position

            if real then
                local fromReal =
                    normalizeHudConfigPosition({
                        real.X,
                        real.Y,
                    })

                if fromReal then
                    return fromReal
                end
            end
        end

        return normalizeHudConfigPosition(
            fallback,
            nil
        )
    end

    local function clampHudConfigPosition(
        value,
        width,
        height
    )
        local position =
            normalizeHudConfigPosition(
                value,
                nil
            )

        if not position then
            return nil
        end

        local viewport = nil

        if type(
            Menu._get_logical_viewport_size
        ) == "function"
        then
            local ok,
                resolved =
                pcall(
                    Menu._get_logical_viewport_size
                )

            if ok then
                viewport = resolved
            end
        end

        if viewport then
            local viewportX =
                tonumber(viewport.X)
            local viewportY =
                tonumber(viewport.Y)

            if viewportX and viewportY then
                position[1] =
                    math.clamp(
                        position[1],
                        0,
                        math.max(
                            0,
                            viewportX
                                - (tonumber(width) or 74)
                        )
                    )
                position[2] =
                    math.clamp(
                        position[2],
                        0,
                        math.max(
                            0,
                            viewportY
                                - (tonumber(height) or 20)
                        )
                    )
            end
        end

        return position
    end

    local function applyHudConfigPositions(
        keybindPosition,
        statusPosition
    )
        keybindPosition =
            clampHudConfigPosition(
                keybindPosition,
                74,
                20
            )

        statusPosition =
            clampHudConfigPosition(
                statusPosition,
                74,
                20
            )

        if keybindPosition then
            Flags.keybinds_position = {
                keybindPosition[1],
                keybindPosition[2],
            }

            local keybindFrame =
                Menu._keybind_proxy_root

            if type(keybindFrame) == "table" then
                pcall(function()
                    keybindFrame.Position =
                        UDim2.new(
                            0,
                            keybindPosition[1],
                            0,
                            keybindPosition[2]
                        )
                end)
            end
        end

        if statusPosition then
            Flags.autoparry_status_position = {
                statusPosition[1],
                statusPosition[2],
            }

            local statusHud =
                Menu._autoparry_status_hud
            local statusFrame =
                statusHud
                and statusHud.frame

            if type(statusFrame) == "table" then
                pcall(function()
                    statusFrame.Position =
                        UDim2.new(
                            0,
                            statusPosition[1],
                            0,
                            statusPosition[2]
                        )
                end)
            end

            if statusHud
                and type(
                    statusHud.reflow
                ) == "function"
            then
                pcall(
                    statusHud.reflow,
                    statusHud
                )
            end
        end
    end

    local function buildMainConfigData()
        local data = {
            __format =
                "SILENT_MAIN_CFG_V1",
            date =
                os.date("%x"),
        }

        for flag, value in pairs(Flags) do
            if type(flag) == "string"
                and flag:sub(1, 1) ~= "!"
                and flag ~= "settings_config_name"
                and flag ~= "settings_config_selected"
            then
                local safe =
                    safeConfigValue(
                        value
                    )

                if safe ~= nil then
                    data[flag] =
                        safe
                end
            end
        end

        local indicatorSide =
            normalizeSingleDropdownValue(
                Flags.visual_player_indicator_side,
                "Right"
            )

        if indicatorSide ~= "Left" then
            indicatorSide = "Right"
        end

        data.visual_player_indicator_side =
            indicatorSide

        -- Keep World Sound canonical in every saved config instead of relying
        -- on the UI library's internal dropdown representation.
        data.visual_world_sound =
            Flags.visual_world_sound == true
        data.visual_world_sound_selection = {
            normalizeWorldSoundConfigSelection(
                Flags.visual_world_sound_selection
            ),
        }
        data.visual_world_sound_volume =
            normalizeWorldSoundConfigVolume(
                Flags.visual_world_sound_volume
            )

        data.local_particle_aura =
            Flags.local_particle_aura == true
        data.local_particle_aura_particle = {
            normalizeParticleAuraConfigSelection(
                Flags.local_particle_aura_particle
            ),
        }

        -- Textured was removed from World in R36. Do not carry its obsolete
        -- flags forward when updating older configs.
        data.visual_world_textured = nil
        data.visual_world_texture_pack = nil

        -- Save the actual current HUD coordinates, not just whatever value may
        -- happen to be left in the flag table.
        data.keybinds_position =
            readHudProxyPosition(
                Menu._keybind_proxy_root,
                Flags.keybinds_position
            )

        local statusHud =
            Menu._autoparry_status_hud

        data.autoparry_status_position =
            readHudProxyPosition(
                statusHud
                    and statusHud.frame,
                Flags.autoparry_status_position
            )

        return data
    end

    local function writeMainConfig(name)
        if type(writefile) ~= "function" then
            return false,
                "writefile unavailable"
        end

        ensureConfigFolder()

        local http =
            game:GetService(
                "HttpService"
            )

        local okEncode,
            encoded =
            pcall(
                http.JSONEncode,
                http,
                buildMainConfigData()
            )

        if not okEncode
            or type(encoded) ~= "string"
        then
            return false,
                tostring(
                    encoded
                    or "JSONEncode failed"
                )
        end

        local path =
            configPath(name)

        local okWrite,
            writeError =
            pcall(
                writefile,
                path,
                MAIN_CONFIG_MAGIC
                    .. encoded
            )

        if not okWrite then
            return false,
                tostring(
                    writeError
                    or "writefile failed"
                )
        end

        return true
    end

    local function decodeConfigPayload(raw)
        if type(raw) ~= "string" then
            return nil,
                "config payload is not text"
        end

        local http =
            game:GetService(
                "HttpService"
            )

        if raw:sub(
            1,
            #MAIN_CONFIG_MAGIC
        ) == MAIN_CONFIG_MAGIC
        then
            local ok,
                decoded =
                pcall(
                    http.JSONDecode,
                    http,
                    raw:sub(
                        #MAIN_CONFIG_MAGIC + 1
                    )
                )

            if ok
                and type(decoded) == "table"
            then
                return decoded
            end

            return nil,
                tostring(
                    decoded
                    or "invalid Main config JSON"
                )
        end

        if raw:sub(1, 1) == "{" then
            local ok,
                decoded =
                pcall(
                    http.JSONDecode,
                    http,
                    raw
                )

            if ok
                and type(decoded) == "table"
            then
                return decoded
            end
        end

        if type(
            Menu.get_config_data
        ) == "function"
        then
            local ok,
                decoded =
                pcall(
                    Menu.get_config_data,
                    raw
                )

            if ok
                and type(decoded) == "table"
            then
                return decoded
            end
        end

        return nil,
            "unsupported or unreadable config format"
    end

    local function resolveConfigKey(value)
        if typeof(value) == "EnumItem" then
            return value
        end

        if type(value) ~= "string"
            or value == ""
        then
            return nil
        end

        return Enum.KeyCode[value]
            or Enum.UserInputType[value]
    end

    local function applyConfigElement(
        element,
        newFlags
    )
        if type(element) ~= "table"
            or type(newFlags) ~= "table"
        then
            return
        end

        local sliderFlag =
            element.slider_flag
        if sliderFlag
            and newFlags[sliderFlag] ~= nil
            and type(element.set_slider) == "function"
        then
            pcall(
                element.set_slider,
                element,
                newFlags[sliderFlag]
            )
        end

        local toggleFlag =
            element.toggle_flag
        if toggleFlag
            and newFlags[toggleFlag] ~= nil
            and type(element.set_toggle) == "function"
        then
            pcall(
                element.set_toggle,
                element,
                newFlags[toggleFlag]
                    == true
            )
        end

        local dropdownFlag =
            element.dropdown_flag
        if dropdownFlag
            and newFlags[dropdownFlag] ~= nil
            and type(element.set_dropdown) == "function"
        then
            local value =
                newFlags[dropdownFlag]

            if type(value) ~= "table" then
                value = { value }
            end

            local allowed = {}
            local options =
                type(element.options) == "table"
                and element.options
                or {}

            for _, candidate in ipairs(value) do
                for _, option in ipairs(options) do
                    if candidate == option then
                        allowed[#allowed + 1] =
                            candidate
                        break
                    end
                end
            end

            if #allowed > 0
                or element.requires_one ~= true
            then
                pcall(
                    element.set_dropdown,
                    element,
                    allowed,
                    false,
                    true
                )
            end
        end

        local textboxFlag =
            element.textbox_flag
        if textboxFlag
            and newFlags[textboxFlag] ~= nil
            and type(element.set_textbox) == "function"
        then
            pcall(
                element.set_textbox,
                element,
                tostring(
                    newFlags[textboxFlag]
                )
            )
        end

        local colorFlag =
            element.color_flag
        if colorFlag
            and type(newFlags[colorFlag]) == "table"
            and type(element.set_colorpicker) == "function"
        then
            local color =
                newFlags[colorFlag]

            if tonumber(color[1])
                and tonumber(color[2])
                and tonumber(color[3])
            then
                pcall(
                    element.set_colorpicker,
                    element,
                    Color3.fromRGB(
                        color[1],
                        color[2],
                        color[3]
                    )
                )
            end
        end

        local transparencyFlag =
            element.transparency_flag
        if transparencyFlag
            and newFlags[transparencyFlag] ~= nil
            and type(
                element.set_colorpicker_transparency
            ) == "function"
        then
            pcall(
                element.set_colorpicker_transparency,
                element,
                tonumber(
                    newFlags[transparencyFlag]
                ) or 0
            )
        end

        local keybindFlag =
            element.keybind_flag
        if keybindFlag
            and type(element.set_key) == "function"
        then
            local key =
                resolveConfigKey(
                    newFlags[keybindFlag]
                )

            -- Missing/nil key flags mean unbound. Explicitly clear the current
            -- inline key so loading another config cannot leave a stale bind.
            pcall(
                element.set_key,
                element,
                key
            )
        end
    end

    local function safeLoadConfig(name)
        name =
            normalizeConfigName(name)

        if type(readfile) ~= "function"
            or type(isfile) ~= "function"
            or type(Menu.get_config_data)
                ~= "function"
        then
            return false,
                "config filesystem/data API unavailable"
        end

        local path =
            configPath(name)

        if not isfile(path) then
            return false,
                "config file does not exist"
        end

        local okRead,
            encoded =
            pcall(
                readfile,
                path
            )

        if not okRead
            or type(encoded) ~= "string"
        then
            return false,
                tostring(
                    encoded
                    or "readfile failed"
                )
        end

        local newFlags,
            decodeError =
            decodeConfigPayload(
                encoded
            )

        if type(newFlags) ~= "table" then
            return false,
                tostring(
                    decodeError
                    or "config decode returned no data"
                )
        end

        -- Canonicalize World Sound before the generic control loader sees it.
        -- This migrates the old numbered dropdown configs and guarantees the
        -- current curated labels/default volume are always valid.
        newFlags.visual_world_sound =
            newFlags.visual_world_sound == true
        newFlags.visual_world_sound_selection = {
            normalizeWorldSoundConfigSelection(
                newFlags.visual_world_sound_selection
            ),
        }
        newFlags.visual_world_sound_volume =
            normalizeWorldSoundConfigVolume(
                newFlags.visual_world_sound_volume
            )

        newFlags.local_particle_aura =
            newFlags.local_particle_aura == true
        newFlags.local_particle_aura_particle = {
            normalizeParticleAuraConfigSelection(
                newFlags.local_particle_aura_particle
            ),
        }

        -- Ignore Textured values from R35/older configs.
        newFlags.visual_world_textured = nil
        newFlags.visual_world_texture_pack = nil

        newFlags.keybinds_position =
            normalizeHudConfigPosition(
                newFlags.keybinds_position,
                readHudProxyPosition(
                    Menu._keybind_proxy_root,
                    Flags.keybinds_position
                )
            )

        local currentStatusHud =
            Menu._autoparry_status_hud

        newFlags.autoparry_status_position =
            normalizeHudConfigPosition(
                newFlags.autoparry_status_position,
                readHudProxyPosition(
                    currentStatusHud
                        and currentStatusHud.frame,
                    Flags.autoparry_status_position
                )
            )

        -- Features with side effects can use this to defer runtime work until
        -- all sliders/toggles/dropdowns have reached their final config state.
        Menu._ConfigApplying = true

        for _, group in pairs(
            Menu.groups or {}
        ) do
            for _, tab in pairs(
                group.tabs or {}
            ) do
                for _, section in pairs(
                    tab.sections or {}
                ) do
                    for _, element in ipairs(
                        section.elements or {}
                    ) do
                        applyConfigElement(
                            element,
                            newFlags
                        )
                    end
                end
            end
        end

        for _, settings in pairs(
            Menu.settings or {}
        ) do
            for _, element in ipairs(
                settings.elements or {}
            ) do
                applyConfigElement(
                    element,
                    newFlags
                )
            end
        end

        do
            local indicatorSide =
                normalizeSingleDropdownValue(
                    newFlags.visual_player_indicator_side,
                    "Right"
                )

            if indicatorSide ~= "Left" then
                indicatorSide = "Right"
            end

            local sideElement =
                Menu._IndicatorUI
                and Menu._IndicatorUI.Side

            if sideElement
                and type(
                    sideElement.set_dropdown
                ) == "function"
            then
                pcall(
                    sideElement.set_dropdown,
                    sideElement,
                    { indicatorSide },
                    false,
                    true
                )
            else
                Flags.visual_player_indicator_side =
                    { indicatorSide }
            end

            local indicatorRuntime =
                Menu._IndicatorRuntime

            if indicatorRuntime
                and type(
                    indicatorRuntime.setSide
                ) == "function"
            then
                pcall(
                    indicatorRuntime.setSide,
                    indicatorSide
                )
            end
        end

        for flag, value in pairs(newFlags) do
            if type(flag) == "string"
                and flag ~= "keybinds"
                and flag ~= "author"
                and flag ~= "date"
            then
                local valueType =
                    type(value)

                if valueType == "boolean"
                    or valueType == "number"
                    or valueType == "string"
                then
                    Flags[flag] =
                        value
                end
            end
        end

        -- Position flags are tables, so the scalar fallback loop above cannot
        -- restore them. Move both HUDs explicitly for this config.
        applyHudConfigPositions(
            newFlags.keybinds_position,
            newFlags.autoparry_status_position
        )

        Menu._ConfigApplying = false

        if Menu.on_config_loaded
            and type(
                Menu.on_config_loaded.Fire
            ) == "function"
        then
            pcall(
                Menu.on_config_loaded.Fire,
                Menu.on_config_loaded
            )
        end

        return true
    end

    local function readConfigInfo(name)
        name = normalizeConfigName(name)
        if name == "" or type(isfile) ~= "function" or type(readfile) ~= "function" then
            return nil
        end

        local path = configPath(name)
        if not isfile(path) then
            return nil
        end

        local okRead, raw = pcall(readfile, path)
        if not okRead or type(raw) ~= "string" then
            return nil
        end

        local data = decodeConfigPayload(raw)
        if type(data) ~= "table" then
            return nil
        end

        local date = tostring(data.date or data.updated or data.last_updated or "")
        return {
            date = date ~= "" and date or "Unknown",
        }
    end

    Menu._UpdateConfigInfo = function(name)
        name = normalizeConfigName(name)
        local selected = name ~= "" and configExists(name)

        local infoElement = Menu._SettingsUI.ConfigLastUpdated
        local configNameElement = Menu._SettingsUI.ConfigName
        local createElement = Menu._SettingsUI.CreateConfig
        local refreshElement = Menu._SettingsUI.RefreshConfigList
        local deleteElement = Menu._SettingsUI.DeleteConfig
        local updateElement = Menu._SettingsUI.UpdateConfig
        local loadElement = Menu._SettingsUI.LoadConfig

        if infoElement then
            infoElement:set_visible(selected)
        end
        if configNameElement then
            configNameElement:set_visible(not selected)
        end
        if createElement then
            createElement:set_visible(not selected)
        end
        if refreshElement then
            refreshElement:set_visible(not selected)
        end
        if deleteElement then
            deleteElement:set_visible(selected)
        end
        if updateElement then
            updateElement:set_visible(selected)
        end
        if loadElement then
            loadElement:set_visible(selected)
        end

        if selected and infoElement then
            local metadata = readConfigInfo(name)
            if type(infoElement.set_info) == "function" then
                infoElement:set_info(
                    "Text",
                    metadata and metadata.date or "Unknown"
                )
            end
        end

        if Menu._SettingsUI.ConfigInfo then
            Menu._SettingsUI.ConfigInfo:recalculate_size()
        end
        if Menu._SettingsUI.ConfigEditor then
            Menu._SettingsUI.ConfigEditor:recalculate_size()
        end
    end

    local function callConfigMethod(action, name)
        name =
            normalizeConfigName(name)

        if name == "" then
            Menu._LastConfigError = "config name is empty"
            return false
        end

        if action == "load" then
            local safeOk,
                safeErr =
                safeLoadConfig(name)

            if safeOk then
                Menu._LastConfigError =
                    nil
                return true
            end

            local method =
                Menu.load_config
                or Menu.LoadConfig
                or Menu.loadConfig

            if type(method) == "function" then
                local ok, err =
                    pcall(
                        method,
                        name
                    )

                if ok then
                    Menu._LastConfigError =
                        nil
                    return true
                end

                Menu._LastConfigError =
                    tostring(
                        err
                        or safeErr
                        or "unknown config load error"
                    )
                return false
            end

            Menu._LastConfigError =
                tostring(
                    safeErr
                    or "unknown config load error"
                )
            return false
        end

        if action == "save" then
            local ok,
                err =
                writeMainConfig(name)

            if ok then
                Menu._LastConfigError =
                    nil
                return true
            end

            Menu._LastConfigError =
                tostring(
                    err
                    or "unknown config save error"
                )
            return false
        end

        if action == "delete"
            and type(delfile) == "function"
            and type(isfile) == "function"
        then
            local root =
                tostring(
                    Menu.storage_root
                    or "SilentSolutions/Gakuran"
                )
            local path =
                root
                .. "/configs/"
                .. name
                .. ".cfg"

            if isfile(path) then
                local ok, err =
                    pcall(
                        delfile,
                        path
                    )

                if ok then
                    Menu._LastConfigError =
                        nil
                    return true
                end

                Menu._LastConfigError =
                    tostring(err)
            end
        end

        return false
    end

    Connect(Menu._SettingsUI.CreateConfig["on_clicked"], function()
        local name = configEditorName()
        if name == "" then
            notifyConfig(
                "Type a config name first",
                2,
                3.0
            )
            return
        end

        if configExists(name) then
            notifyConfig(
                "Config '" .. name .. "' already exists",
                2,
                3.0
            )
            return
        end

        if callConfigMethod("save", name) then
            if Menu._SettingsUI.ConfigName
                and type(Menu._SettingsUI.ConfigName.set_textbox) == "function"
            then
                pcall(
                    Menu._SettingsUI.ConfigName.set_textbox,
                    Menu._SettingsUI.ConfigName,
                    ""
                )
            else
                Flags.settings_config_name = ""
            end

            task.defer(function()
                refreshConfigList(name)
            end)
            notifyConfig(
                "Created config '" .. name .. "'",
                1,
                2.2
            )
        else
            notifyConfig(
                "Failed to create config '"
                    .. name
                    .. "': "
                    .. tostring(Menu._LastConfigError or "unknown error"),
                3,
                4
            )
        end
    end)

    Connect(Menu._SettingsUI.RefreshConfigList["on_clicked"], function()
        refreshConfigList(nil)
        notifyConfig("Refreshed config list", 1, 1.5)
    end)

    Connect(Menu._SettingsUI.DeleteConfig["on_clicked"], function()
        local name = selectedConfigName()
        if name == "" then
            return
        end

        if callConfigMethod("delete", name) then
            Flags.settings_config_selected = nil
            task.defer(function()
                refreshConfigList(nil)
            end)
            notifyConfig("Deleted config '" .. name .. "'", 1, 2)
        else
            notifyConfig("Failed to delete config '" .. name .. "'", 3, 3)
        end
    end)

    Connect(Menu._SettingsUI.UpdateConfig["on_clicked"], function()
        local name = selectedConfigName()
        if name == "" then
            return
        end

        if callConfigMethod("save", name) then
            refreshConfigList(name)
            notifyConfig("Updated config '" .. name .. "'", 1, 2.2)
        else
            notifyConfig(
                "Failed to update config '"
                    .. name
                    .. "': "
                    .. tostring(Menu._LastConfigError or "unknown error"),
                3,
                4
            )
        end
    end)

    Connect(Menu._SettingsUI.LoadConfig["on_clicked"], function()
        local name = selectedConfigName()
        if name == "" then
            return
        end

        if callConfigMethod("load", name) then
            refreshConfigList(name)
            notifyConfig("Loaded config '" .. name .. "'", 1, 2)
        else
            local detail = tostring(Menu._LastConfigError or "unknown error")
            if #detail > 90 then
                detail = detail:sub(1, 90) .. "..."
            end
            notifyConfig(
                "Failed to load config '" .. name .. "': " .. detail,
                3,
                4
            )
        end
    end)

    Menu._RefreshConfigList = refreshConfigList
    task.defer(refreshConfigList)
end

