            local Workspace, Players, RunService, HttpService, UserInputService = GetService["Workspace"], GetService["Players"], GetService["RunService"], GetService["HttpService"], GetService["UserInputService"];
            local LocalPlayer, Camera = Players.LocalPlayer, Workspace.CurrentCamera;
