            local ESPCombatConfig = nil
            local ESPCombatAnimationUtils = nil

            pcall(function()
                local Shared = ReplicatedStorage:FindFirstChild("Shared")
                local Config = Shared and Shared:FindFirstChild("Config")
                local Utils = Shared and Shared:FindFirstChild("Utils")
                local ESPCombatConfigModule = Config and Config:FindFirstChild("CombatConfig")
                local CombatAnimationModule = Utils and Utils:FindFirstChild("CombatAnimationUtils")

                if ESPCombatConfigModule and ESPCombatConfigModule:IsA("ModuleScript") then
                    ESPCombatConfig = require(ESPCombatConfigModule)
                end
                if CombatAnimationModule and CombatAnimationModule:IsA("ModuleScript") then
                    ESPCombatAnimationUtils = require(CombatAnimationModule)
                end
