            local function NormalizeESPStyleKey(style)
                return string.lower(tostring(style or "default")):gsub("[^%w]", "")
            end

            local ESPCharacterStyleCache = setmetatable({}, {__mode = "k"})

            local function CleanESPCombatStyle(style)
                if typeof(style) ~= "string" then
                    return nil
                end
                style = style:gsub("^%s+", ""):gsub("%s+$", "")
                if style == "" then
                    return nil
                end
                return style
            end

            local function RememberESPCharacterStyle(character, style)
                style = CleanESPCombatStyle(style)
                if character and style then
                    ESPCharacterStyleCache[character] = style
                end
                return style
            end

            local function GetESPCharacterStyle(character)
                if not character then
                    return nil
                end

                local playerData = character:FindFirstChild("PlayerData")
                local style = nil

                if playerData then
                    style = CleanESPCombatStyle(playerData:GetAttribute("CombatStyle"))
                        or CleanESPCombatStyle(playerData:GetAttribute("CombatType"))
                    if style then
                        return RememberESPCharacterStyle(character, style)
                    end
                end

                style = CleanESPCombatStyle(character:GetAttribute("CombatStyle"))
                    or CleanESPCombatStyle(character:GetAttribute("CombatType"))
                    or CleanESPCombatStyle(character:GetAttribute("Style"))
                if style then
                    return RememberESPCharacterStyle(character, style)
                end

                if ESPCombatAnimationUtils then
                    local okCharacter, officialStyle = pcall(function()
                        if typeof(ESPCombatAnimationUtils.GetCombatStyleForCharacter) == "function" then
                            return ESPCombatAnimationUtils.GetCombatStyleForCharacter(character)
                        end
                    end)
                    officialStyle = okCharacter and CleanESPCombatStyle(officialStyle) or nil

                    if officialStyle
                        and (string.lower(officialStyle) ~= "basic" or not ESPCharacterStyleCache[character])
                    then
                        return RememberESPCharacterStyle(character, officialStyle)
                    end

                    local player = Players:GetPlayerFromCharacter(character)
                    if player then
                        local okPlayer, playerStyle = pcall(function()
                            if typeof(ESPCombatAnimationUtils.GetPlayerCombatStyle) == "function" then
                                return ESPCombatAnimationUtils.GetPlayerCombatStyle(player)
                            end
                        end)
                        playerStyle = okPlayer and CleanESPCombatStyle(playerStyle) or nil
                        if playerStyle
                            and (string.lower(playerStyle) ~= "basic" or not ESPCharacterStyleCache[character])
                        then
                            return RememberESPCharacterStyle(character, playerStyle)
                        end
                    end
                end

                return ESPCharacterStyleCache[character]
            end

            local NewVector3, NewVector2, Dim, Dim2, DimOffset = Vector3.new, Vector2.new, UDim.new, UDim2.new, UDim2.fromOffset;
