    }
            local Table = ESPVisuals['Table'];

            local ESPFriendlyRelationColor = Color3.fromRGB(124, 132, 158)
            local ESPPriorityRelationColor = Color3.fromRGB(158, 124, 124)

            local function GetESPRelationColor(Player)
                local Relation =
