            }

            ESPVisuals.SmallestPixel = ESPFontFaces["smallest_pixel-7"]
            ESPVisuals.ProggyTiny = ESPFontFaces["smallest_pixel-7"]
            ESPVisuals.ProggyClean = ESPFontFaces["smallest_pixel-7"]
            ESPVisuals.Tahoma = ESPFontFaces["Segoe UI"]
            ESPVisuals.TahomaBold = ESPFontFaces["Made Bold"]

            local function ResolveESPFontFace(selection)
                if type(selection) == "string" and ESPFontFaces[selection] then
                    return ESPFontFaces[selection]
                end
                return ESPVisuals.SmallestPixel
            end

            ESPVisuals.__index = ESPVisuals;

            function ESPVisuals:CreateObjects(Name, Prop)
                local New = Instance.new(Name);

                for Property, Value in Prop or {} do
                    New[Property] = Value;
                end;

                return New;
            end

            function ESPVisuals:CreateThreads(Name, Signal, Callback)
                local Connection = Signal:Connect(Callback);
                self.Threads[Name] = Connection;
                return Connection;
            end


            local ESPHeavyColor = ThemeAccent

            local function GetESPHeavyCooldownData(Character, Data, Now)
                Now =
                    tonumber(Now)
                    or os.clock()

                if not Character
                    or not Character.Parent
                then
                    Data['HeavySourceActive'] = false
                    Data['HeavySeen'] = false
                    Data['HeavyEndTime'] = 0
                    Data['HeavyDuration'] = 7
                    return 0, 0, 7
                end

                if not Data['HeavyDuration']
                    or Now
                        >= (
                            Data['NextHeavyStylePoll']
                            or 0
                        )
                then
                    Data['NextHeavyStylePoll'] =
                        Now + (0.50 * ESPVisuals:GetPerformanceScale())

                    local Style =
                        GetESPCharacterStyle(Character)
                        or "default"

                    local StyleKey =
                        NormalizeESPStyleKey
                        and NormalizeESPStyleKey(
                            Style
                            or "default"
                        )
                        or string.lower(
                            tostring(
                                Style
                                or "default"
                            )
                        ):gsub(
                            "[^%w]",
                            ""
                        )

                    local Duration =
                        7

                    pcall(function()
                        if ESPCombatConfig
                            and typeof(
                                ESPCombatConfig
                                    .GetStyleM2Cooldown
                            ) == "function"
                        then
                            local Value =
                                ESPCombatConfig
                                    .GetStyleM2Cooldown(
                                        StyleKey
                                    )

                            if typeof(Value) == "number"
                                and Value > 0
                            then
                                Duration =
                                    Value
                            end
                        end
                    end)

                    Data['HeavyDuration'] =
                        Duration
                end

                local Duration =
                    math.max(
                        tonumber(
                            Data['HeavyDuration']
                        )
                            or 7,
                        0.001
                    )

                if Now
                    >= (
                        Data['NextHeavySourcePoll']
                        or 0
                    )
                then
                    Data['NextHeavySourcePoll'] =
                        Now + (0.08 * ESPVisuals:GetPerformanceScale())

                    local RemainingAttr =
                        Character:GetAttribute(
                            "M2CooldownRemaining"
                        )
                    local CooldownAttr =
                        Character:GetAttribute(
                            "M2Cooldown"
                        )

                    local SourceActive =
                        false
                    local SourceRemaining =
                        Duration
                    local NumericRemaining =
                        false

                    if typeof(RemainingAttr)
                            == "number"
                        and RemainingAttr > 0
                    then
                        SourceActive =
                            true
                        SourceRemaining =
                            RemainingAttr
                        NumericRemaining =
                            true
                    elseif typeof(CooldownAttr)
                            == "number"
                        and CooldownAttr > 0
                    then
                        SourceActive =
                            true
                        SourceRemaining =
                            CooldownAttr
                        NumericRemaining =
                            true
                    elseif CooldownAttr == true
                        or Character:GetAttribute(
                            "M2"
                        ) == true
                        or Character:GetAttribute(
                            "PendingM2"
                        ) == true
                    then
                        SourceActive =
                            true
                    end

                    if SourceActive then
                        if Data['HeavySourceActive']
                                ~= true
                            or Data['HeavySeen']
                                ~= true
                        then
                            Data['HeavySeen'] =
                                true
                            Data['HeavyEndTime'] =
                                Now
                                + math.clamp(
                                    tonumber(
                                        SourceRemaining
                                    )
                                        or Duration,
                                    0,
                                    Duration
                                )
                        elseif NumericRemaining then
                            Data['HeavyEndTime'] =
                                Now
                                + math.clamp(
                                    tonumber(
                                        SourceRemaining
                                    )
                                        or 0,
                                    0,
                                    Duration
                                )
                        end
                    elseif Data['HeavySourceActive']
                        == true
                    then
                        Data['HeavyEndTime'] =
                            Now
                        Data['HeavySeen'] =
                            false
                    end

                    Data['HeavySourceActive'] =
                        SourceActive
                end

                local Remaining =
                    Data['HeavySeen'] == true
                    and math.max(
                        0,
                        (
                            tonumber(
                                Data['HeavyEndTime']
                            )
                            or 0
                        ) - Now
                    )
                    or 0

                local Ratio =
                    math.clamp(
                        Remaining
                            / Duration,
                        0,
                        1
                    )

                return Ratio,
                    Remaining,
                    Duration
            end

            local ESPWallRaycastParams = RaycastParams.new()
            ESPWallRaycastParams.FilterType = Enum.RaycastFilterType.Exclude
            ESPWallRaycastParams.IgnoreWater = true

            local ESPWallFilterCharacter = nil

            local function IsESPWallVisible(Character, RootPart, Data)
                if Table['Wall Check'] ~= true then
                    return true
                end

                local CurrentCamera = Camera or Workspace.CurrentCamera
                if not CurrentCamera or not Character or not RootPart then
                    return false
                end

                local AimPart =
                    Data
                    and Data['HeadPart']
                    or nil

                if not AimPart
                    or AimPart.Parent ~= Character
                then
                    AimPart =
                        FindFirstChild(
                            Character,
                            "Head"
                        )
                        or RootPart

                    if Data then
                        Data['HeadPart'] =
                            AimPart
                    end
                end

                if not AimPart
                    or not AimPart:IsA("BasePart")
                then
                    return false
                end

                local LocalCharacter =
                    LocalPlayer.Character

                if ESPWallFilterCharacter
                    ~= LocalCharacter
                then
                    ESPWallFilterCharacter =
                        LocalCharacter

                    ESPWallRaycastParams.FilterDescendantsInstances =
                        LocalCharacter
                        and {LocalCharacter}
                        or {}
                end

                local Origin =
                    CurrentCamera.CFrame.Position
                local Direction =
                    AimPart.Position
                    - Origin

                if Direction.Magnitude <= 0.001 then
                    return true
                end

                local Result =
                    Workspace:Raycast(
                        Origin,
                        Direction,
                        ESPWallRaycastParams
                    )

                return not Result
                    or Result.Instance:IsDescendantOf(
                        Character
                    )
            end

            function ESPVisuals:PushDiagnostic(Player, Data, W, H, X, Y, Distance, Force)
                local Diagnostics = self.Diagnostics
                if not Diagnostics
                    or Diagnostics.Enabled ~= true
                then
                    return
                end

                local Now = os.clock()
                local Key = Player and Player.UserId or tostring(Player)
                local LastSample = Diagnostics.LastSampleAt[Key] or 0
                local MouseLocked = UserInputService.MouseBehavior == Enum.MouseBehavior.LockCenter

                if not Force and not MouseLocked and Now - LastSample < 0.75 then
                    return
                end

                if not Force and MouseLocked and Now - LastSample < 0.12 then
                    return
                end

                Diagnostics.LastSampleAt[Key] = Now

                local CurrentCamera = Workspace.CurrentCamera or Camera
                local RootPart = Data and Data.RootPart
                local Objects = Data and Data.Objects or {}
                if not CurrentCamera or not RootPart then
                    return
                end

                local RootScreen, RootOnScreen = CurrentCamera:WorldToViewportPoint(RootPart.Position)
                local LocalRoot = CurrentCamera.CFrame:PointToObjectSpace(RootPart.Position)
                local TrueDistance = (CurrentCamera.CFrame.Position - RootPart.Position).Magnitude

                local HolderSize = Objects.TargetHolder and Objects.TargetHolder.AbsoluteSize or Vector2.zero
                local BoxSize = Objects.BoxOutlineHolder and Objects.BoxOutlineHolder.AbsoluteSize or Vector2.zero
                local FillSize = Objects.BoxFill and Objects.BoxFill.AbsoluteSize or Vector2.zero
                local GlowSize = Objects.BoxGlow and Objects.BoxGlow.AbsoluteSize or Vector2.zero
                local HolderPos = Objects.TargetHolder and Objects.TargetHolder.AbsolutePosition or Vector2.zero

                local CalcW = tonumber(W) or -1
                local CalcH = tonumber(H) or -1
                local SizeMismatch =
                    math.abs(BoxSize.X - CalcW) > 3
                    or math.abs(BoxSize.Y - CalcH) > 3
                    or math.abs(FillSize.X - CalcW) > 3
                    or math.abs(FillSize.Y - CalcH) > 3
                    or math.abs(HolderSize.X - CalcW) > 3
                    or math.abs(HolderSize.Y - CalcH) > 3

                local Viewport = CurrentCamera.ViewportSize
                local Oversized =
                    CalcW > Viewport.X * 0.32
                    or CalcH > Viewport.Y * 0.65
                    or BoxSize.X > Viewport.X * 0.32
                    or BoxSize.Y > Viewport.Y * 0.65

                local Anomaly = SizeMismatch or Oversized

                Diagnostics.Samples += 1
                if Anomaly then
                    Diagnostics.Anomalies += 1
                end

                local Snapshot = {
                    time = Now,
                    player = Player and Player.Name or "?",
                    locked = MouseLocked,
                    distance = Distance or TrueDistance,
                    trueDistance = TrueDistance,
                    calcW = CalcW,
                    calcH = CalcH,
                    calcX = tonumber(X) or -1,
                    calcY = tonumber(Y) or -1,
                    holderW = HolderSize.X,
                    holderH = HolderSize.Y,
                    boxW = BoxSize.X,
                    boxH = BoxSize.Y,
                    fillW = FillSize.X,
                    fillH = FillSize.Y,
                    glowW = GlowSize.X,
                    glowH = GlowSize.Y,
                    holderX = HolderPos.X,
                    holderY = HolderPos.Y,
                    rootScreenX = RootScreen.X,
                    rootScreenY = RootScreen.Y,
                    rootZ = RootScreen.Z,
                    rootLocalX = LocalRoot.X,
                    rootLocalY = LocalRoot.Y,
                    rootLocalZ = LocalRoot.Z,
                    rootOnScreen = RootOnScreen,
                    fov = CurrentCamera.FieldOfView,
                    viewportX = Viewport.X,
                    viewportY = Viewport.Y,
                    anomaly = Anomaly,
                    sizeMismatch = SizeMismatch,
                    oversized = Oversized,
                }

                Diagnostics.LastByPlayer[Key] = Snapshot

                local Line = string.format(
                    "t=%.3f target=%s lock=%s dist=%.2f true=%.2f calc=(%d,%d @ %d,%d) holder=(%d,%d @ %d,%d) box=(%d,%d) fill=(%d,%d) glow=(%d,%d) rootScreen=(%.1f,%.1f,z=%.2f,on=%s) rootLocal=(%.2f,%.2f,%.2f) fov=%.1f viewport=%dx%d mismatch=%s oversized=%s",
                    Now,
                    Snapshot.player,
                    MouseLocked and "ON" or "OFF",
                    tonumber(Distance) or -1,
                    TrueDistance,
                    math.floor(CalcW + 0.5),
                    math.floor(CalcH + 0.5),
                    math.floor((tonumber(X) or -1) + 0.5),
                    math.floor((tonumber(Y) or -1) + 0.5),
                    math.floor(HolderSize.X + 0.5),
                    math.floor(HolderSize.Y + 0.5),
                    math.floor(HolderPos.X + 0.5),
                    math.floor(HolderPos.Y + 0.5),
                    math.floor(BoxSize.X + 0.5),
                    math.floor(BoxSize.Y + 0.5),
                    math.floor(FillSize.X + 0.5),
                    math.floor(FillSize.Y + 0.5),
                    math.floor(GlowSize.X + 0.5),
                    math.floor(GlowSize.Y + 0.5),
                    RootScreen.X,
                    RootScreen.Y,
                    RootScreen.Z,
                    tostring(RootOnScreen),
                    LocalRoot.X,
                    LocalRoot.Y,
                    LocalRoot.Z,
                    CurrentCamera.FieldOfView,
                    math.floor(Viewport.X + 0.5),
                    math.floor(Viewport.Y + 0.5),
                    tostring(SizeMismatch),
                    tostring(Oversized)
                )

                if Anomaly then
                    Line = "[ANOMALY] " .. Line
                end

                table.insert(Diagnostics.Events, Line)
                while #Diagnostics.Events > (Diagnostics.Limit or 180) do
                    table.remove(Diagnostics.Events, 1)
                end
            end

            local ESPHolderParent =
                LocalPlayer
                and LocalPlayer:FindFirstChildOfClass("PlayerGui")

            if not ESPHolderParent then
                pcall(function()
                    ESPHolderParent =
                        LocalPlayer
                        and LocalPlayer:WaitForChild("PlayerGui", 3)
                end)
            end

            if not ESPHolderParent
                and type(gethui) == "function"
            then
                pcall(function()
                    ESPHolderParent = gethui()
                end)
            end

            ESPVisuals.Holder = ESPVisuals:CreateObjects("ScreenGui", {
                Name = "Silent.solutionsESP",
                Parent = ESPHolderParent,
                ScreenInsets = Enum.ScreenInsets.None,
                ZIndexBehavior = Enum.ZIndexBehavior.Global,
                ResetOnSpawn = false,

                DisplayOrder =
                    Menu._VisualsDisplayOrder,

                IgnoreGuiInset = true,
            })
            ESPVisuals.Holder:SetAttribute("RendererGeneration", "RenderFOVSyncedBox_v2")

            pcall(function()
                local env =
                    getgenv and getgenv()
                    or _G
                local drawing =
                    env["silent_ui_drawing"]

                if type(drawing) == "table"
                    and typeof(drawing.sgui) == "Instance"
                    and drawing.sgui:IsA("ScreenGui")
                then
                    drawing.sgui.DisplayOrder =
                        math.max(
                            tonumber(
                                drawing.sgui.DisplayOrder
                            ) or 0,
                            1000
                        )
                end
            end)

            function ESPVisuals:_EnsureChamsPool()
                self.ChamsPool = self.ChamsPool or {}
                self.ChamsPoolByHighlight = self.ChamsPoolByHighlight or {}
                self.ChamsPoolLimit = math.max(
                    1,
                    math.floor(
                        tonumber(self.ChamsPoolLimit)
                        or tonumber(Players.MaxPlayers)
                        or 32
                    )
                )

                local Folder = self.ChamsPoolFolder
                if typeof(Folder) ~= "Instance"
                    or Folder.Parent == nil
                then
                    Folder = Instance.new("Folder")
                    Folder.Name = "Silent.solutions_ChamsPool"
                    Folder.Parent = Workspace
                    self.ChamsPoolFolder = Folder
                end

                return Folder
            end

            function ESPVisuals:ReleaseChams(Data)
                if not Data or type(Data.Objects) ~= "table" then
                    return
                end

                local Objects = Data.Objects
                local Chams = Objects["Chams"]
                Objects["Chams"] = nil
                Data.ChamsAttachAt = nil
                Data.ChamsReadyAt = nil
                Data.ChamsDistance = nil

                if typeof(Chams) ~= "Instance" then
                    return
                end

                pcall(function()
                    Chams.Enabled = false
                    Chams.Adornee = nil
                end)

                local Entry = self.ChamsPoolByHighlight
                    and self.ChamsPoolByHighlight[Chams]
                if Entry then
                    Entry.Data = nil
                    Entry.Character = nil
                    Entry.Distance = nil
                    Entry.LastReleased = os.clock()

                    local Folder = self:_EnsureChamsPool()
                    if Chams.Parent ~= Folder then
                        Chams.Parent = Folder
                    end
                else
                    pcall(function()
                        Chams:Destroy()
                    end)
                end
            end

            function ESPVisuals:IsPlayerVisualized(Player)
                local runtime = Menu._PlayerListRuntime
                local selectedVisualize = Flags.list_player_visualize == true
                    and runtime ~= nil
                    and runtime.selected == Player
                if selectedVisualize then
                    return true
                end

                return type(Menu._ShouldVisualizeWhitelistedFriend) == "function"
                    and Menu._ShouldVisualizeWhitelistedFriend(Player) == true
            end

            function ESPVisuals:GetChamsCandidateDistance(Data)
                if not Data or type(Data.Objects) ~= "table" then
                    return nil
                end

                local Character = Data.Character
                local RootPart = Data.RootPart
                if not Character
                    or not Character.Parent
                    or not RootPart
                    or not RootPart.Parent
                then
                    self:ReleaseChams(Data)
                    return nil
                end

                local Distance = (
                    CameraPosition
                    - RootPart.Position
                ).Magnitude
                local ForceVisualize =
                    self:IsPlayerVisualized(Data.Player)
                local RangeLimit = ForceVisualize
                    and 1500
                    or (tonumber(Table.Distance) or 100)

                if Distance > RangeLimit then
                    self:ReleaseChams(Data)
                    return nil
                end

                if Table["Down Check"] == true then
                    local Humanoid =
                        Data.Humanoid
                        or Character:FindFirstChildOfClass("Humanoid")
                    local downed =
                        Character:GetAttribute("Downed") == true
                        or Data.Alive == false
                        or not Humanoid
                        or Humanoid.Health <= 0

                    if downed then
                        self:ReleaseChams(Data)
                        return nil
                    end
                end

                if ForceVisualize ~= true
                    and Table["Wall Check"] == true
                    and Data.LastWallVisible == false
                then
                    self:ReleaseChams(Data)
                    return nil
                end

                Data.ChamsDistance = Distance
                return Distance
            end

            function ESPVisuals:EnsureChams(Data, Character, FrameNow)
                if not Data or type(Data.Objects) ~= "table" then
                    return nil
                end

                FrameNow = tonumber(FrameNow) or os.clock()

                local Folder = self:_EnsureChamsPool()
                local Objects = Data.Objects
                local Chams = Objects["Chams"]
                local Entry = nil

                if typeof(Chams) == "Instance" then
                    local okClass, isHighlight = pcall(
                        Chams.IsA,
                        Chams,
                        "Highlight"
                    )
                    if okClass and isHighlight == true then
                        Entry = self.ChamsPoolByHighlight[Chams]
                    end
                end

                if not Entry or Entry.Data ~= Data then
                    if typeof(Chams) == "Instance" then
                        pcall(function()
                            Chams.Enabled = false
                            Chams.Adornee = nil
                        end)
                    end
                    Objects["Chams"] = nil
                    Chams = nil
                    Entry = nil
                end

                if not Chams then
                    local Pool = self.ChamsPool

                    -- Reuse an already-created Highlight before allocating anything.
                    for index = #Pool, 1, -1 do
                        local Candidate = Pool[index]
                        local CandidateHighlight = Candidate
                            and Candidate.Highlight

                        if typeof(CandidateHighlight) ~= "Instance"
                            or CandidateHighlight.Parent == nil
                        then
                            if typeof(CandidateHighlight) == "Instance" then
                                self.ChamsPoolByHighlight[CandidateHighlight] = nil
                            end
                            table.remove(Pool, index)
                        elseif Candidate.Data == nil and not Entry then
                            Entry = Candidate
                        end
                    end

                    -- The pool is intentionally small. One new neutral Highlight can
                    -- be created only on a healthy frame and only when no free pooled
                    -- entry exists. It is parented once and kept for reuse.
                    if not Entry then
                        if #Pool >= (tonumber(self.ChamsPoolLimit) or tonumber(Players.MaxPlayers) or 32)
                            or self.ChamsCreateAllowed ~= true
                        then
                            return nil
                        end

                        Chams = Instance.new("Highlight")
                        Chams.Name = "Silent.solutions_Chams"
                        Chams.Enabled = false
                        Chams.Adornee = nil
                        Chams.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
                        Chams.Parent = Folder

                        Entry = {
                            Highlight = Chams,
                            Data = nil,
                            Character = nil,
                            Distance = nil,
                            LastReleased = FrameNow,
                        }
                        Pool[#Pool + 1] = Entry
                        self.ChamsPoolByHighlight[Chams] = Entry

                        -- Aggressive adaptive pool population. Healthy frames can
                        -- lease one new Highlight every Chams update slice; if frame time
                        -- rises, automatically back off before allocation becomes a spike.
                        local ChamsFrameAverage =
                            tonumber(self.ChamsFrameAverage) or (1 / 60)
                        local ChamsCreateGap =
                            ChamsFrameAverage <= 0.0185 and 0.015
                            or ChamsFrameAverage <= 0.024 and 0.030
                            or 0.075

                        self.ChamsCreateNextAt =
                            FrameNow + ChamsCreateGap
                        self.ChamsCreateAllowed = false
                    else
                        Chams = Entry.Highlight
                    end

                    Entry.Data = Data
                    Entry.Character = Character
                    Entry.Distance = tonumber(Data.ChamsDistance) or math.huge
                    Objects["Chams"] = Chams

                    -- Separate pool leasing, Adornee assignment, and Enabled=true
                    -- across different updates. This is the expensive renderer path.
                    Chams.Enabled = false
                    if Chams.Adornee ~= nil then
                        Chams.Adornee = nil
                    end
                    if Chams.Parent ~= Folder then
                        Chams.Parent = Folder
                    end

                    Data.ChamsAttachAt = FrameNow + 0.020
                    Data.ChamsReadyAt = nil

                    Data["LastChamsAdornee"] = nil
                    Data["LastChamsFillColor"] = nil
                    Data["LastChamsOutlineColor"] = nil
                    Data["LastChamsDepthMode"] = nil
                    Data["FinalChamsEnabled"] = nil
                    Data["FinalChamsFillT"] = nil
                    Data["FinalChamsOutlineT"] = nil
                else
                    Entry.Character = Character
                    Entry.Distance = tonumber(Data.ChamsDistance) or Entry.Distance
                end

                local AttachAt = tonumber(Data.ChamsAttachAt)
                if AttachAt then
                    if FrameNow < AttachAt then
                        Chams.Enabled = false
                        return Chams
                    end

                    Data.ChamsAttachAt = nil
                    if Character and Character.Parent then
                        if Chams.Adornee ~= Character then
                            Chams.Adornee = Character
                        end
                        Data["LastChamsAdornee"] = Character
                        Data.ChamsReadyAt = FrameNow + 0.025
                        Chams.Enabled = false
                        return Chams
                    end
                elseif Character and Character.Parent
                    and Chams.Adornee ~= Character
                then
                    Chams.Enabled = false
                    Chams.Adornee = Character
                    Data["LastChamsAdornee"] = Character
                    Data.ChamsReadyAt = FrameNow + 0.025
                    return Chams
                end

                local cfg = Table["Chams"]
                local RelationColor = GetESPRelationColor(Data["Player"])
                Chams.FillColor = RelationColor or cfg["FillRGB"]
                Chams.OutlineColor = RelationColor or cfg["OutlineRGB"]
                Chams.DepthMode =
                    (self:IsPlayerVisualized(Data["Player"]) ~= true and cfg["VisibleCheck"])
                    and Enum.HighlightDepthMode.Occluded
                    or Enum.HighlightDepthMode.AlwaysOnTop

                return Chams
            end

            function ESPVisuals:ApplyChamsIndependent(
                Data,
                Character,
                FrameNow,
                RangeFadeAlpha,
                DownFade
            )
                local cfg = Table["Chams"]
                if cfg["Enabled"] ~= true then
                    local old = Data.Objects["Chams"]
                    if old then
                        old.Enabled = false
                    end
                    return
                end

                local Chams =
                    self:EnsureChams(
                        Data,
                        Character
                    )

                if not Chams then
                    return
                end

                local Alpha =
                    self:GetVisualFadeAlpha(
                        Data,
                        "Chams",
                        true,
                        FrameNow
                    )
                    * math.clamp(
                        tonumber(RangeFadeAlpha) or 0,
                        0,
                        1
                    )
                    * (
                        1
                        - math.clamp(
                            tonumber(DownFade) or 0,
                            0,
                            1
                        )
                    )

                if Alpha <= 0.001 then
                    Chams.Enabled = false
                    return
                end

                local FillBase =
                    math.clamp(
                        tonumber(
                            cfg["FillTransparency"]
                        ) or 0.70,
                        0,
                        1
                    )
                local OutlineBase =
                    math.clamp(
                        tonumber(
                            cfg["OutlineTransparency"]
                        ) or 0.80,
                        0,
                        1
                    )

                if cfg["Thermal"] then
                    local Wave =
                        (math.sin(FrameNow * 1.35) + 1)
                        * 0.5
                    local VisiblePoint =
                        math.max(
                            0,
                            FillBase - 0.18
                        )
                    local FadedPoint =
                        math.min(
                            0.96,
                            FillBase + 0.08
                        )
                    FillBase =
                        VisiblePoint
                        + (
                            FadedPoint
                            - VisiblePoint
                        ) * Wave
                end

                Chams.FillTransparency =
                    FillBase
                    + (
                        (1 - FillBase)
                        * (1 - Alpha)
                    )
                Chams.OutlineTransparency =
                    OutlineBase
                    + (
                        (1 - OutlineBase)
                        * (1 - Alpha)
                    )
                Chams.Enabled = true
            end

