            function ESPVisuals:CalculateBox(Data, FrameNow)
                local RootPart = Data['RootPart']
                local Character = Data['Character']

                if not RootPart
                    or not Character
                    or not Camera
                then
                    return nil, nil, nil, nil, false
                end

                FrameNow =
                    tonumber(FrameNow)
                    or os.clock()

                local SizeY =
                    tonumber(
                        Data['MeasuredESPHeight']
                    )
                local CenterYOffset =
                    tonumber(
                        Data[
                            'MeasuredESPCenterYOffset'
                        ]
                    )

                if not SizeY
                    or not CenterYOffset
                    or FrameNow
                        >= (
                            Data['NextBodyMeasureAt']
                            or 0
                        )
                then
                    Data['NextBodyMeasureAt'] =
                        FrameNow + (0.10 * self:GetPerformanceScale())

                    local MinBodyY =
                        math.huge
                    local MaxBodyY =
                        -math.huge

                    local BodyParts =
                        Data['BodyParts']
                        or Data['Children']
                        or {}

                    for I = 1, #BodyParts do
                        local Part =
                            BodyParts[I]

                        if Part
                            and Part.Parent
                                == Character
                        then
                            local Half =
                                Part.Size * 0.5
                            local CF =
                                Part.CFrame

                            local VerticalRadius =
                                math.abs(
                                    CF.RightVector.Y
                                ) * Half.X
                                + math.abs(
                                    CF.UpVector.Y
                                ) * Half.Y
                                + math.abs(
                                    CF.LookVector.Y
                                ) * Half.Z

                            MinBodyY =
                                math.min(
                                    MinBodyY,
                                    Part.Position.Y
                                        - VerticalRadius
                                )

                            MaxBodyY =
                                math.max(
                                    MaxBodyY,
                                    Part.Position.Y
                                        + VerticalRadius
                                )
                        end
                    end

                    local MeasuredHeight
                    local MeasuredCenterYOffset

                    if MinBodyY ~= math.huge
                        and MaxBodyY ~= -math.huge
                        and MaxBodyY > MinBodyY
                    then
                        MeasuredHeight =
                            (
                                MaxBodyY
                                - MinBodyY
                            ) + 0.10

                        MeasuredCenterYOffset =
                            (
                                (
                                    MinBodyY
                                    + MaxBodyY
                                ) * 0.5
                            )
                            - RootPart.Position.Y
                    else
                        MeasuredHeight =
                            4.75
                        MeasuredCenterYOffset =
                            0.15
                    end

                    if not SizeY then
                        SizeY =
                            MeasuredHeight
                    elseif math.abs(
                        MeasuredHeight
                            - SizeY
                    ) > 0.03
                    then
                        SizeY =
                            SizeY
                            + (
                                MeasuredHeight
                                - SizeY
                            ) * 0.30
                    end

                    if not CenterYOffset then
                        CenterYOffset =
                            MeasuredCenterYOffset
                    elseif math.abs(
                        MeasuredCenterYOffset
                            - CenterYOffset
                    ) > 0.03
                    then
                        CenterYOffset =
                            CenterYOffset
                            + (
                                MeasuredCenterYOffset
                                - CenterYOffset
                            ) * 0.30
                    end

                    SizeY =
                        math.clamp(
                            SizeY,
                            2.5,
                            9.0
                        )

                    Data['MeasuredESPHeight'] =
                        SizeY
                    Data[
                        'MeasuredESPCenterYOffset'
                    ] =
                        CenterYOffset
                end

                local SizeX =
                    SizeY
                    * (
                        2.55
                        / 4.75
                    )
                local HalfY =
                    SizeY * 0.5

                local CenterPosition =
                    RootPart.Position
                    + NewVector3(
                        0,
                        CenterYOffset,
                        0
                    )

                local TopScreen =
                    Camera:WorldToViewportPoint(
                        CenterPosition
                        + NewVector3(
                            0,
                            HalfY,
                            0
                        )
                    )

                local BottomScreen =
                    Camera:WorldToViewportPoint(
                        CenterPosition
                        - NewVector3(
                            0,
                            HalfY,
                            0
                        )
                    )

                if TopScreen.Z <= 0.05
                    or BottomScreen.Z <= 0.05
                then
                    return nil, nil, nil, nil, false
                end

                local MinY =
                    math.min(
                        TopScreen.Y,
                        BottomScreen.Y
                    )
                local MaxY =
                    math.max(
                        TopScreen.Y,
                        BottomScreen.Y
                    )
                local H =
                    MaxY - MinY

                if H ~= H
                    or H <= 1
                then
                    return nil, nil, nil, nil, false
                end

                local Aspect =
                    SizeX / SizeY
                local W =
                    H * Aspect
                local CenterX =
                    (
                        TopScreen.X
                        + BottomScreen.X
                    ) * 0.5
                local MinX =
                    CenterX
                    - W * 0.5
                local MaxX =
                    CenterX
                    + W * 0.5

                local BoundingBox =
                    Table['Boxes'][
                        'Bounding Box'
                    ]
                local ExtraX =
                    tonumber(
                        BoundingBox['BoxX']
                    ) or 0
                local ExtraY =
                    tonumber(
                        BoundingBox['BoxY']
                    ) or 0

                MinX -=
                    ExtraX * 0.5
                MaxX +=
                    ExtraX * 0.5
                MinY -=
                    ExtraY * 0.5
                MaxY +=
                    ExtraY * 0.5

                W =
                    MaxX - MinX
                H =
                    MaxY - MinY

                local Viewport =
                    Camera.ViewportSize

                if W > Viewport.X * 0.82
                    or H > Viewport.Y * 0.94
                then
                    return nil, nil, nil, nil, false
                end

                if MaxX < 0
                    or MaxY < 0
                    or MinX > Viewport.X
                    or MinY > Viewport.Y
                then
                    return nil, nil, nil, nil, false
                end

                return W,
                    H,
                    MinX,
                    MinY,
                    true
            end


            function ESPVisuals:AddTarget(Player)
                if Player == LocalPlayer then
                    return
                end;

                if self.Cache[Player] then
                    return
                end;

                local Data = {
                    ['Player'] = Player,
                    ['Objects'] = {},
                    ['Conns'] = {},
                    ['Character'] = nil,
                    ['RootPart'] = nil,
                    ['Humanoid'] = nil,
                    ['Children'] = nil,
                    ['Health'] = 0,
                    ['MaxHealth'] = 100,
                                ['Alive'] = false,
                    ['LastW'] = nil,
                    ['LastH'] = nil,
                    ['LastX'] = nil,
                    ['LastY'] = nil,
                            ['IncludeAccessories'] = Table['Boxes']['Bounding Box']['IncludeAcsessories'],
                    ['LastGlowTop'] = nil,
                    ['LastGlowBot'] = nil,
                    ['LastGlowT1'] = nil,
                    ['LastGlowT2'] = nil,
                    ['LastGradTop'] = nil,
                    ['LastGradBot'] = nil,
                    ['LastFillTop'] = nil,
                    ['LastFillBot'] = nil,
                    ['LastFillT1'] = nil,
                    ['LastFillT2'] = nil,
                    ['LastDist'] = nil,
                    ['LastDistColor'] = nil,
                    ['LastDisplayName'] = nil,
                    ['LastNameColor'] = nil,
                    ['LastHealthTop'] = nil,
                    ['LastHealthMid'] = nil,
                    ['LastHealthBot'] = nil,
                    ['LastHealthFloor'] = nil,
                    ['LastRatio'] = nil,

                    ['LastHeavyRatio'] = nil,
                    ['LastHeavyColor'] = nil,
                    ['LastHeavyTransparency'] = nil,
                    ['HeavySeen'] = false,
                    ['HeavySourceActive'] = false,
                    ['HeavyDuration'] = 0,
                    ['HeavyEndTime'] = 0,
                                                ['LastBoxTransparency'] = nil,
                    ['LastHealthTransparency'] = nil,
                    ['LastNameTransparency'] = nil,
                    ['LastDistanceTransparency'] = nil,
                    ['LastNameFont'] = nil,
                    ['LastDistanceFont'] = nil,
                ['LastStyleTransparency'] = nil,
                ['LastStunnedTransparency'] = nil,
                ['LastStyleFont'] = nil,
                ['LastStunnedFont'] = nil,
                ['LastStyleText'] = nil,
                            }
                Data['VisualsInitialized'] = false
                self['Cache'][Player] = Data;

                local HealthHandler = {}; do
                    function HealthHandler.BindHealth(Humanoid)
                        if Data['Conns']['Health'] then
                            Data['Conns']['Health']:Disconnect()
                        end

                        if Data['Conns']['Died'] then
                            Data['Conns']['Died']:Disconnect()
                        end

                        Data['Humanoid'] = Humanoid
                        Data['Health'] = Humanoid.Health
                        Data['MaxHealth'] = Humanoid.MaxHealth
                        Data['Alive'] = Humanoid.Health > 0

                        Data['Conns']['Health'] = Humanoid.HealthChanged:Connect(function(NewHealth)
                            Data['Alive'] = NewHealth > 0
                            Data['Health'] = NewHealth
                        end)

                        Data['Conns']['Died'] = Humanoid.Died:Connect(function()
                            Data['Alive'] = false
                        end)
                    end

                    Data['BindHealth'] = HealthHandler.BindHealth;
                end

                local ChildHandler = {}; do
                    function ChildHandler.BindChildren(Character)
                        if Data['Conns']['ChildAdded'] then
                            Data['Conns']['ChildAdded']:Disconnect();
                        end;

                        if Data['Conns']['ChildRemoved'] then
                            Data['Conns']['ChildRemoved']:Disconnect();
                        end;

                        local Children =
                            Character:GetChildren()
                        Data['Children'] =
                            Children

                        local BodyParts =
                            {}

                        for I = 1, #Children do
                            local Child =
                                Children[I]

                            if Child:IsA("BasePart")
                                and ESPBodyPartNames[
                                    Child.Name
                                ]
                            then
                                BodyParts[
                                    #BodyParts + 1
                                ] =
                                    Child
                            end

                            if Child.Name == "Head"
                                and Child:IsA("BasePart")
                            then
                                Data['HeadPart'] =
                                    Child
                            end
                        end

                        Data['BodyParts'] =
                            BodyParts

                        Data['Conns']['ChildAdded'] = Character.ChildAdded:Connect(function(Child)
                            Children[#Children + 1] = Child

                            if Child:IsA("BasePart")
                                and ESPBodyPartNames[
                                    Child.Name
                                ]
                            then
                                BodyParts[
                                    #BodyParts + 1
                                ] =
                                    Child
                            end

                            if Child.Name == "Head"
                                and Child:IsA("BasePart")
                            then
                                Data['HeadPart'] =
                                    Child
                            end
                        end)

                        Data['Conns']['ChildRemoved'] = Character.ChildRemoved:Connect(function(Child)
                            for I = #Children, 1, -1 do
                                if Children[I] == Child then
                                    Remove(
                                        Children,
                                        I
                                    )
                                    break
                                end
                            end

                            for I = #BodyParts, 1, -1 do
                                if BodyParts[I] == Child then
                                    Remove(
                                        BodyParts,
                                        I
                                    )
                                    break
                                end
                            end

                            if Data['HeadPart']
                                == Child
                            then
                                Data['HeadPart'] =
                                    nil
                            end
                        end)

                        end

                    Data['BindChildren'] = ChildHandler.BindChildren;
                end

                local CharacterHandler = {}; do
                    function CharacterHandler.OnCharacter(Character)
                        Data['Character'] = Character;
                        Data['RootPart'] = nil;
                        Data['Humanoid'] = nil;
                        Data['Children'] = nil;
                        Data['BodyParts'] = nil;
                        Data['HeadPart'] = nil;
                        Data['Alive'] = false;
                        Data['MeasuredESPHeight'] = nil;
                        Data['MeasuredESPCenterYOffset'] = nil;

                        if not Character or not Character.Parent then
                            return;
                        end;

                        local RootPart = FindFirstChild(Character, "HumanoidRootPart");

                        if not RootPart then
                            RootPart = Character:WaitForChild('HumanoidRootPart', 10);
                        end

                        local Humanoid = FindFirstChildOfClass(Character, 'Humanoid');

                        if not Humanoid then
                            Humanoid = Character:WaitForChild('Humanoid', 10);
                        end;

                        if not RootPart or not Humanoid then
                            return;
                        end;

                        if not Character.Parent then
                            return;
                        end;

                        Data['RootPart'] = RootPart;
                        Data['Humanoid'] = Humanoid;

                        Data['BindChildren'](Character);
                        Data['BindHealth'](Humanoid);
                        end

                    Data['Conns']['CharAdded'] = Player.CharacterAdded:Connect(function(Character)
                        task.defer(CharacterHandler.OnCharacter, Character)
                    end)

                    if Player.Character and Player.Character.Parent then
                        task.defer(CharacterHandler.OnCharacter, Player.Character)
                    end
                end
            end

            function ESPVisuals:RemoveTarget(Player)
                local Data = self['Cache'][Player];

                if not Data then
                    return;
                end;

                for _, Connections in Data['Conns'] do
                    Connections:Disconnect()
                end;

                Clear(Data['Conns']);

                if Data['Objects']['TargetHolder'] then
                    Data['Objects']['TargetHolder']:Destroy();
                end;

                if Data['Objects']['Chams'] then
                    self:ReleaseChams(Data)
                end;

                Clear(Data['Objects']);
                self['Cache'][Player] = nil;
            end

            local FightingStyleRarities = {
                basic = "Common",
                striker = "Epic",
                slugger = "Uncommon",
                muaythai = "Uncommon",
                karate = "Uncommon",
                kickboxing = "Uncommon",
                boxing = "Epic",
                hakari = "Legendary",
                kyokushin = "Legendary",
                kyokushinkarate = "Legendary",
                capoeira = "Legendary",
                wrestling = "Legendary",
                kure = "Legendary",
                ali = "???",
                cqc = "???",
                closequarterscombat = "???",
                wingchun = "???",
            }

            Menu._FightingStyleColorAliasRarity = {
                hakari = "Legendary",             
                kyokushin = "Legendary",          
                kyokushinkarate = "Legendary",    
                cqc = "???",                      
                closequarterscombat = "???",      
                striker = "Epic",                 
                kickboxing = "Uncommon",          
            }

            local FightingStyleRarityColors = {
                common = Color3.fromRGB(225, 225, 225),
                uncommon = Color3.fromRGB(95, 155, 255),
                epic = Color3.fromRGB(175, 95, 255),
                legendary = Color3.fromRGB(255, 210, 75),
                unknown = Color3.fromRGB(207, 243, 255),
            }

            local function GetFightingStyleRarity(Character, FightingStyle)
                local Key =
                    NormalizeESPStyleKey
                    and NormalizeESPStyleKey(
                        FightingStyle
                    )
                    or string.lower(
                        tostring(
                            FightingStyle
                            or ""
                        )
                    ):gsub(
                        "[^%w]",
                        ""
                    )

                local VisualAlias =
                    Menu._FightingStyleColorAliasRarity
                    and Menu._FightingStyleColorAliasRarity[
                        Key
                    ]

                if VisualAlias then
                    return VisualAlias
                end

                local PlayerData = Character and Character:FindFirstChild("PlayerData")
                local Rarity

                for _, Source in ipairs({PlayerData, Character}) do
                    if Source then
                        for _, Attribute in ipairs({"CombatStyleRarity", "StyleRarity", "CombatRarity", "Rarity"}) do
                            local Value = Source:GetAttribute(Attribute)
                            if typeof(Value) == "string" and Value ~= "" then
                                Rarity = Value
                                break
                            end
                        end
                    end
                    if Rarity then break end
                end

                if not Rarity then
                    Rarity =
                        FightingStyleRarities[
                            Key
                        ]
                end

                return Rarity or "Common"
            end

            local function GetFightingStyleRarityColor(Character, FightingStyle)
                local Rarity = string.lower(tostring(GetFightingStyleRarity(Character, FightingStyle) or "common"))
                Rarity = Rarity:gsub("[^%a%?]", "")

                if Rarity == "???" or Rarity == "unknown" then
                    return FightingStyleRarityColors.unknown
                end

                return FightingStyleRarityColors[Rarity] or FightingStyleRarityColors.common
            end

            Menu._GetFightingStyleRarityColor =
                GetFightingStyleRarityColor

            function ESPVisuals:ResetDownFade(Data)
                if not Data then return end

                local Targets = Data['DownFadeTargets']
                if Targets then
                    for _, Target in ipairs(Targets) do
                        local Object = Target.Object
                        if Object and Object.Parent then
                            pcall(function()
                                Object[Target.Property] = Target.Base
                            end)
                        end
                    end
                end

                Data['DownFadeTargets'] = nil
                Data['DownFadeStartedAt'] = nil
                Data['DownFadeActive'] = false
            end

            function ESPVisuals:CaptureDownFadeTargets(Data)
                if not Data or Data['DownFadeTargets'] then return end

                local Objects = Data['Objects'] or {}
                local Holder = Objects['TargetHolder']
                local Targets = {}

                local function AddTarget(Object, Property)
                    if not Object then return end
                    local ok, Value = pcall(function()
                        return Object[Property]
                    end)
                    if ok and typeof(Value) == "number" then
                        table.insert(Targets, {
                            Object = Object,
                            Property = Property,
                            Base = Value,
                        })
                    end
                end

                local function AddObject(Object)
                    if Object == Objects['BoxGlow'] or Object == Objects['BoxFill'] then
                        return
                    end
                    if Object:IsA("GuiObject") then
                        AddTarget(Object, "BackgroundTransparency")
                    end

                    if Object:IsA("TextLabel")
                        or Object:IsA("TextButton")
                        or Object:IsA("TextBox") then
                        AddTarget(Object, "TextTransparency")
                        AddTarget(Object, "TextStrokeTransparency")
                    elseif Object:IsA("ImageLabel")
                        or Object:IsA("ImageButton") then
                        AddTarget(Object, "ImageTransparency")
                    elseif Object:IsA("UIStroke") then
                        AddTarget(Object, "Transparency")
                    end
                end

                if Holder then
                    AddObject(Holder)
                    for _, Descendant in ipairs(Holder:GetDescendants()) do
                        AddObject(Descendant)
                    end
                end

                Data['DownFadeTargets'] = Targets
            end

            function ESPVisuals:ApplyDownFade(Data, Amount)
                if not Data then return end
                Amount = math.clamp(tonumber(Amount) or 0, 0, 1)

                if Amount <= 0 then
                    if Data['DownFadeActive'] then
                        self:ResetDownFade(Data)
                    end
                    return
                end

                if not Data['DownFadeTargets'] then
                    self:CaptureDownFadeTargets(Data)
                end

                Data['DownFadeActive'] = true

                for _, Target in ipairs(Data['DownFadeTargets'] or {}) do
                    local Object = Target.Object
                    if Object and Object.Parent then
                        local Base = math.clamp(tonumber(Target.Base) or 0, 0, 1)
                        local Transparency = Base + ((1 - Base) * Amount)
                        pcall(function()
                            Object[Target.Property] = Transparency
                        end)
                    end
                end
            end

            function ESPVisuals:SetFlagPosition(Data, ObjectName, Position, LayoutOrder)
                if not Data or not Data.Objects then return end
                local Objects = Data.Objects
                local Object = Objects[ObjectName]
                if not Object then return end

                Position = tostring(Position or "Right")

                Data['LastFlagPositions'] =
                    Data['LastFlagPositions']
                    or {}

                if Data['LastFlagPositions'][
                    ObjectName
                ] == Position
                then
                    return
                end

                Data['LastFlagPositions'][
                    ObjectName
                ] =
                    Position

                local Parent
                if Position == "Left" then
                    Parent = Objects["LeftTextHolder"]
                    Object.TextXAlignment = Enum.TextXAlignment.Right
                    Object.LayoutOrder = (LayoutOrder or 10) + 20
                elseif Position == "Top" then
                    Parent = Objects["TopTextHolder"]
                    Object.TextXAlignment = Enum.TextXAlignment.Center
                    Object.LayoutOrder = LayoutOrder or 10
                elseif Position == "Bottom" then
                    Parent = Objects["BottomTextHolder"]
                    Object.TextXAlignment = Enum.TextXAlignment.Center
                    Object.LayoutOrder = LayoutOrder or 10
                else
                    Position = "Right"
                    Parent = Objects["RightTextHolder"]
                    Object.TextXAlignment = Enum.TextXAlignment.Left
                    Object.LayoutOrder = LayoutOrder or 10
                end

                if Parent and Object.Parent ~= Parent then
                    Object.Parent = Parent
                end
            end

            ESPVisuals.VisualFadeDuration = 0.22

            function ESPVisuals:GetPerformanceScale()
                local fps =
                    math.clamp(
                        tonumber(
                            self.TargetFPS
                        ) or 60,
                        15,
                        240
                    )

                return math.clamp(
                    60 / fps,
                    1,
                    4
                )
            end

            function ESPVisuals:GetVisualFadeAlpha(Data, Key, Enabled, Now)
                if not Data then return Enabled and 1 or 0 end
                Data['VisualFadeStates'] = Data['VisualFadeStates'] or {}
                local States = Data['VisualFadeStates']
                Now =
                    tonumber(Now)
                    or os.clock()
                local Target = Enabled == true and 1 or 0
                local State = States[Key]

                if not State then
                    State = {Alpha = 0, StartAlpha = 0, Target = Target, ChangedAt = Now}
                    States[Key] = State
                elseif State.Target ~= Target then
                    State.StartAlpha = math.clamp(tonumber(State.Alpha) or 0, 0, 1)
                    State.Target = Target
                    State.ChangedAt = Now
                end

                local Duration = math.max(0.05, tonumber(self.VisualFadeDuration) or 0.22)
                local Progress = math.clamp((Now - (State.ChangedAt or Now)) / Duration, 0, 1)
                local Smooth = Progress * Progress * (3 - 2 * Progress)
                local Goal = State.Target
                State.Alpha = State.StartAlpha + ((Goal - State.StartAlpha) * Smooth)
                if Progress >= 1 then
                    State.Alpha = Goal
                    State.StartAlpha = Goal
                end
                return math.clamp(State.Alpha, 0, 1)
            end

            local function ESPFadeTransparency(BaseTransparency, Alpha)
                BaseTransparency = math.clamp(tonumber(BaseTransparency) or 0, 0, 1)
                Alpha = math.clamp(tonumber(Alpha) or 0, 0, 1)
                return BaseTransparency + ((1 - BaseTransparency) * (1 - Alpha))
            end

            local function HideESPTarget(Objects)
                local holder =
                    Objects
                    and Objects['TargetHolder']

                if holder and holder.Visible then
                    holder.Visible = false
                end
            end

            local function SetESPProperty(
                Data,
                CacheKey,
                Object,
                Property,
                Value
            )
                if not Object then
                    return
                end

                if Data[CacheKey] ~= Value then
                    Object[Property] =
                        Value
                    Data[CacheKey] =
                        Value
                end
            end

            local function ApplyESPTextFade(
                Data,
                Prefix,
                Object,
                Stroke,
                BaseTransparency,
                Alpha
            )
                if not Object then
                    return
                end

                local Visible =
                    Alpha > 0.001

                SetESPProperty(
                    Data,
                    Prefix .. "Visible",
                    Object,
                    "Visible",
                    Visible
                )

                local Effective =
                    ESPFadeTransparency(
                        BaseTransparency,
                        Alpha
                    )

                SetESPProperty(
                    Data,
                    Prefix .. "TextT",
                    Object,
                    "TextTransparency",
                    Effective
                )

                if Stroke then
                    SetESPProperty(
                        Data,
                        Prefix .. "StrokeT",
                        Stroke,
                        "Transparency",
                        Effective
                    )
                end
            end

            function ESPVisuals:Update(Player, Data, FrameNow, PrecomputedDistance)
                local Objects = Data['Objects']
                local Character = Data['Character']
                local Humanoid = Data['Humanoid']

                FrameNow =
                    tonumber(FrameNow)
                    or os.clock()

                local VisualizeSelected =
                    self:IsPlayerVisualized(Player)

                if not Data['RootPart'] or not Character or not Character.Parent then
                    HideESPTarget(Objects)
                    return
                end

                if Data['VisualsInitialized'] ~= true then
                    local quickDistance =
                        tonumber(PrecomputedDistance)
                    local rangeLimit =
                        VisualizeSelected == true
                        and 1500
                        or (tonumber(Table['Distance']) or 100)

                    if quickDistance
                        and quickDistance > rangeLimit + 24
                    then
                        return
                    end

                    self:InitEsp(Data)
                    Objects = Data['Objects']
                end

                if not Humanoid or not Humanoid.Parent then
                    Humanoid = Character:FindFirstChildOfClass("Humanoid")
                    Data['Humanoid'] = Humanoid
                end

                local DownCheckEnabled =
                    Table['Down Check'] == true

                local DownConfirmed =
                    false

                if DownCheckEnabled then
                    local HumanoidDead =
                        not Humanoid
                        or Humanoid.Health <= 0
                        or Humanoid:GetState()
                            == Enum.HumanoidStateType.Dead

                    local CharacterDowned =
                        Character:GetAttribute(
                            "Downed"
                        ) == true

                    DownConfirmed =
                        not Data['Alive']
                        or HumanoidDead
                        or CharacterDowned
                end

                local DownFade = 0

                if DownConfirmed then
                    if typeof(Data['DownFadeStartedAt']) ~= "number" then
                        Data['DownFadeStartedAt'] = FrameNow
                        self:CaptureDownFadeTargets(Data)
                    end

                    local FadeDuration = math.max(0.05, tonumber(Table['Down Fade Duration']) or 0.45)
                    DownFade = math.clamp((FrameNow - Data['DownFadeStartedAt']) / FadeDuration, 0, 1)
                else
                    self:ResetDownFade(Data)
                end

                local RootPos =
                    Data['RootPart'].Position

                local Distance =
                    tonumber(
                        PrecomputedDistance
                    )

                if Distance == nil then
                    Distance =
                        Floor(
                            (
                                CameraPosition
                                - RootPos
                            ).Magnitude
                        )
                end
                local RangeLimit = VisualizeSelected == true
                    and 1500
                    or (tonumber(Table['Distance']) or 100)
                local InRange = Distance <= RangeLimit
                local RangeFadeAlpha = self:GetVisualFadeAlpha(Data, "__Range", InRange, FrameNow)

                if not InRange and RangeFadeAlpha <= 0.001 then
                    if Objects['TargetHolder'].Visible then
                        Objects['TargetHolder'].Visible = false
                    end
                    if Objects['Chams'] then Objects['Chams'].Enabled = false end
                    return
                end

                if Table['Wall Check'] == true then
                    if FrameNow
                        >= (
                            Data['NextWallCheckAt']
                            or 0
                        )
                    then
                        Data['NextWallCheckAt'] =
                            FrameNow + (0.08 * self:GetPerformanceScale())

                        Data['LastWallVisible'] =
                            IsESPWallVisible(
                                Character,
                                Data['RootPart'],
                                Data
                            )
                    end

                    if Data['LastWallVisible']
                        == false
                    then
                        HideESPTarget(Objects)
                        return
                    end
                else
                    Data['LastWallVisible'] =
                        true
                end

                local W, H, X, Y, OnScreen = self:CalculateBox(Data, FrameNow)

                if not OnScreen or not W then
                    if Objects['TargetHolder'].Visible then
                        Objects['TargetHolder'].Visible = false
                    end
                    return
                end

                W = Floor(W)
                H = Floor(H)
                X = Floor(X)
                Y = Floor(Y)

                if not Objects['TargetHolder'].Visible then
                    Objects['TargetHolder'].Visible = true
                end

                local DirtySizes = Data['LastW'] ~= W or Data['LastH'] ~= H
                local DirtyPosition = Data['LastX'] ~= X or Data['LastY'] ~= Y

                if DirtyPosition then
                    Objects['TargetHolder'].Position = DimOffset(X, Y)
                    Data['LastX'] = X
                    Data['LastY'] = Y
                end

                if DirtySizes then
                    Objects['TargetHolder'].Size = DimOffset(W, H)


                    Objects['BoxGlow'].Position = DimOffset(-21, -21)
                    Objects['BoxGlow'].Size = DimOffset(W + 42, H + 42)


                    Objects['BoxOutlineHolder'].Position = DimOffset(0, 0)
                    Objects['BoxOutlineHolder'].Size = DimOffset(W, H)

                    Objects['BoxInlineHolder'].Position = DimOffset(-1, -1)
                    Objects['BoxInlineHolder'].Size = DimOffset(W + 2, H + 2)

                    Objects['BoxFill'].Position = DimOffset(0, 0)
                    Objects['BoxFill'].Size = DimOffset(W, H)

                    Data['LastW'] = W
                    Data['LastH'] = H
                end

                if FrameNow
                        >= (
                            Data['NextBoxSanityAt']
                            or 0
                        )
                then
                    Data['NextBoxSanityAt'] =
                        FrameNow + (0.75 * self:GetPerformanceScale())

                    if Objects['BoxOutlineHolder'].AbsoluteSize.X > W + 3
                        or Objects['BoxOutlineHolder'].AbsoluteSize.Y > H + 3
                        or Objects['BoxFill'].AbsoluteSize.X > W + 3
                        or Objects['BoxFill'].AbsoluteSize.Y > H + 3
                    then
                        Objects['BoxOutlineHolder'].AutomaticSize =
                            Enum.AutomaticSize.None
                        Objects['BoxInlineHolder'].AutomaticSize =
                            Enum.AutomaticSize.None
                        Objects['BoxFill'].AutomaticSize =
                            Enum.AutomaticSize.None

                        Objects['BoxOutlineHolder'].Position =
                            DimOffset(0, 0)
                        Objects['BoxOutlineHolder'].Size =
                            DimOffset(W, H)
                        Objects['BoxInlineHolder'].Position =
                            DimOffset(-1, -1)
                        Objects['BoxInlineHolder'].Size =
                            DimOffset(W + 2, H + 2)
                        Objects['BoxFill'].Position =
                            DimOffset(0, 0)
                        Objects['BoxFill'].Size =
                            DimOffset(W, H)
                    end
                end

                self:PushDiagnostic(Player, Data, W, H, X, Y, Distance, false)

                local ChamsCfg = Table['Chams']
                -- Chams creation is owned exclusively by the lightweight ChamsState
                -- scheduler. The 2D ESP renderer must never allocate Highlights,
                -- otherwise enabling Chams alongside another ESP feature can bypass
                -- the global creation budget and hitch the client.
                local Chams = Objects['Chams']

                local BoxesCfg = Table['Boxes']
                local TextsCfg = Table['Texts']

                local RelationColor = GetESPRelationColor(Player)
                local BoxEnabled =
                    VisualizeSelected ~= true
                    and BoxesCfg['Enabled'] == true
                local NameEnabled =
                    VisualizeSelected ~= true
                    and TextsCfg['Name']['Enabled'] == true
                local DistanceEnabled =
                    VisualizeSelected == true
                    or TextsCfg['Distance']['Enabled'] == true

                local BoxGlowCfg = BoxesCfg['Box Glow']
                local FilledCfg = BoxesCfg['Filled']
                local BoxEffectsAllowed = BoxEnabled and InRange

                if BoxEffectsAllowed and BoxGlowCfg['Enabled'] then
                    if Objects['BoxGlow'].ImageTransparency ~= 0 then
                        Objects['BoxGlow'].ImageTransparency = 0
                    end

                    local GlowTop = RelationColor or BoxGlowCfg['Top']
                    local GlowBot = RelationColor or BoxGlowCfg['Bot']

                    if Data['LastGlowTop'] ~= GlowTop or Data['LastGlowBot'] ~= GlowBot then
                        Objects['BoxGlowGradient'].Color = ColorSequence.new({
                            ColorSequenceKeypoint.new(0, GlowTop),
                            ColorSequenceKeypoint.new(1, GlowBot),
                        })
                        Data['LastGlowTop'] = GlowTop
                        Data['LastGlowBot'] = GlowBot
                    end

                    local T1 = BoxGlowCfg['Transparency'][1]
                    local T2 = BoxGlowCfg['Transparency'][2]

                    if Data['LastGlowT1'] ~= T1 or Data['LastGlowT2'] ~= T2 then
                        Objects['BoxGlowGradient'].Transparency = NumSeq({NumKey(0, T1), NumKey(1, T2)})
                        Data['LastGlowT1'] = T1
                        Data['LastGlowT2'] = T2
                    end
                else
                    if Objects['BoxGlow'].ImageTransparency ~= 1 then
                        Objects['BoxGlow'].ImageTransparency = 1
                    end
                end

                if BoxEnabled then
                    if not Objects['BoxOutlineHolder'].Visible then
                        Objects['BoxOutlineHolder'].Visible = true
                    end

                    if not Objects['BoxInlineHolder'].Visible then
                        Objects['BoxInlineHolder'].Visible = true
                    end

                    local GradTop = RelationColor or BoxesCfg['Gradients']['Top']
                    local GradBot = RelationColor or BoxesCfg['Gradients']['Bot']

                    if Data['LastGradTop'] ~= GradTop or Data['LastGradBot'] ~= GradBot then
                        Objects['BoxInlineGradient'].Color = ColorSequence.new({
                            ColorSequenceKeypoint.new(0, GradTop),
                            ColorSequenceKeypoint.new(1, GradBot),
                        })
                        Data['LastGradTop'] = GradTop
                        Data['LastGradBot'] = GradBot
                    end
                    local BoxTransparency = math.clamp(BoxesCfg['Gradients']['Transparency'] or 0, 0, 1)
                    if Data['LastBoxTransparency'] ~= BoxTransparency then
                        Objects['BoxOutline'].Transparency = BoxTransparency
                        Objects['BoxInline'].Transparency = BoxTransparency
                        Data['LastBoxTransparency'] = BoxTransparency
                    end
                else
                    if Objects['BoxOutlineHolder'].Visible then
                        Objects['BoxOutlineHolder'].Visible = false
                    end

                    if Objects['BoxInlineHolder'].Visible then
                        Objects['BoxInlineHolder'].Visible = false
                    end
                end

                if BoxEffectsAllowed and FilledCfg['Enabled'] then
                    if not Objects['BoxFill'].Visible then
                        Objects['BoxFill'].Visible = true
                    end

                    local FillTop = RelationColor or FilledCfg['Top']
                    local FillBot = RelationColor or FilledCfg['Bot']
                    local FillT1 = FilledCfg['Transparency'][1]
                    local FillT2 = FilledCfg['Transparency'][2]

                    if Data['LastFillTop'] ~= FillTop or Data['LastFillBot'] ~= FillBot then
                        Objects['BoxFillGradient'].Color = ColorSequence.new({
                            ColorSequenceKeypoint.new(0, FillTop),
                            ColorSequenceKeypoint.new(1, FillBot),
                        })
                        Data['LastFillTop'] = FillTop
                        Data['LastFillBot'] = FillBot
                    end

                    if Data['LastFillT1'] ~= FillT1 or Data['LastFillT2'] ~= FillT2 then
                        Objects['BoxFillGradient'].Transparency = NumSeq({NumKey(0, FillT1), NumKey(1, FillT2)})
                        Data['LastFillT1'] = FillT1
                        Data['LastFillT2'] = FillT2
                    end

                    if FilledCfg['Animated'] then
                        local AnimationTime = FrameNow
                        local CircleSpeed = 0.42
                        local RotationSpeed = 12
                        local Radius = 0.13

                        Objects['BoxFillGradient'].Rotation =
                            (90 + (AnimationTime * RotationSpeed)) % 360

                        Objects['BoxFillGradient'].Offset = NewVector2(
                            math.cos(AnimationTime * CircleSpeed) * Radius,
                            math.sin(AnimationTime * CircleSpeed) * Radius
                        )

                        Data['LastFillAnimated'] = true
                    elseif Data['LastFillAnimated'] then
                        Objects['BoxFillGradient'].Rotation = 90
                        Objects['BoxFillGradient'].Offset = NewVector2(0, 0)
                        Data['LastFillAnimated'] = false
                    end
                else
                    if Objects['BoxFill'].Visible then
                        Objects['BoxFill'].Visible = false
                    end
                end

                if NameEnabled then
                    if not Objects['Name'].Visible then
                        Objects['Name'].Visible = true
                    end

                    local NameText = Player.Name

                    if Data['LastNameText'] ~= NameText then
                        Objects['Name'].Text = NameText
                        Data['LastNameText'] = NameText
                    end

                    local NameFont = TextsCfg['Name']['Font']
                    if Data['LastNameFont'] ~= NameFont then
                        Objects['Name'].FontFace =
                            ResolveESPFontFace(NameFont)
                        Data['LastNameFont'] = NameFont
                    end

                    local NameColor = RelationColor or TextsCfg['Name']['Color']

                    if Data['LastNameColor'] ~= NameColor then
                        Objects['Name'].TextColor3 = NameColor
                        Data['LastNameColor'] = NameColor
                    end
                    local NameTransparency = math.clamp(TextsCfg['Name']['Transparency'] or 0, 0, 1)
                    if Data['LastNameTransparency'] ~= NameTransparency then
                        Objects['Name'].TextTransparency = NameTransparency
                        if Objects['NameStroke'] then
                            Objects['NameStroke'].Transparency = NameTransparency
                        end
                        Data['LastNameTransparency'] = NameTransparency
                    end
                else
                    if Objects['Name'].Visible then
                        Objects['Name'].Visible = false
                    end
                end

                if DistanceEnabled then
                    if not Objects['Distance'].Visible then
                        Objects['Distance'].Visible = true
                    end

                    if Data['LastDist'] ~= Distance then
                        Objects['Distance'].Text = Format('%dst', Distance)
                        Data['LastDist'] = Distance
                    end

                    local DistanceFont = TextsCfg['Distance']['Font']
                    if Data['LastDistanceFont'] ~= DistanceFont then
                        Objects['Distance'].FontFace =
                            ResolveESPFontFace(DistanceFont)
                        Data['LastDistanceFont'] = DistanceFont
                    end

                    local DistColor = RelationColor or TextsCfg['Distance']['Color']

                    if Data['LastDistColor'] ~= DistColor then
                        Objects['Distance'].TextColor3 = DistColor
                        Data['LastDistColor'] = DistColor
                    end
                    local DistanceTransparency = math.clamp(TextsCfg['Distance']['Transparency'] or 0, 0, 1)
                    if Data['LastDistanceTransparency'] ~= DistanceTransparency then
                        Objects['Distance'].TextTransparency = DistanceTransparency
                        if Objects['DistanceStroke'] then
                            Objects['DistanceStroke'].Transparency = DistanceTransparency
                        end
                        Data['LastDistanceTransparency'] = DistanceTransparency
                    end
                else
                    if Objects['Distance'].Visible then
                        Objects['Distance'].Visible = false
                    end
                end

                local HealthCfg = Table['Bars']['Health Bar']
                local HealthEnabled =
                    VisualizeSelected == true
                    or HealthCfg['Enabled'] == true

                if HealthEnabled then
                    local Health = Data['Health'] or 0
                    local MaxHealth = Data['MaxHealth'] or 100
                    local Ratio = Clamp(Health / MaxHealth, 0, 1)

                    if not Objects['LeftBarHolder'].Visible then
                        Objects['LeftBarHolder'].Visible = true
                    end

                    if not Objects['HealthBarOutline'].Visible then
                        Objects['HealthBarOutline'].Visible = true
                    end

                    if Data['LastRatio'] ~= Ratio then
                        Objects['HealthBar'].Size = Dim2(1, 0, Ratio, 0)
                        Data['LastRatio'] = Ratio
                    end

                    local HealthRelationColor =
                        VisualizeSelected and RelationColor or nil
                    local GradTop = HealthRelationColor or HealthCfg['Top']
                    local GradMid = HealthRelationColor or HealthCfg['Mid']
                    local GradBot = HealthRelationColor or HealthCfg['Bot']

                    if Data['LastHealthTop'] ~= GradTop or Data['LastHealthMid'] ~= GradMid or Data['LastHealthBot'] ~= GradBot then
                        Objects['HealthBarGradient'].Color = ColorSequence.new({
                            ColorSequenceKeypoint.new(0, GradTop),
                            ColorSequenceKeypoint.new(0.5, GradMid),
                            ColorSequenceKeypoint.new(1, GradBot),
                        })
                        Data['LastHealthTop'] = GradTop
                        Data['LastHealthMid'] = GradMid
                        Data['LastHealthBot'] = GradBot
                    end
                    local HealthTransparency = HealthCfg['Transparency'] or {0, 0, 0}
                    local HealthTopTransparency = math.clamp(tonumber(HealthTransparency[1]) or 0, 0, 1)
                    local HealthMidTransparency = math.clamp(tonumber(HealthTransparency[2]) or 0, 0, 1)
                    local HealthBotTransparency = math.clamp(tonumber(HealthTransparency[3]) or 0, 0, 1)
                    if Data['LastHealthTopTransparency'] ~= HealthTopTransparency
                        or Data['LastHealthMidTransparency'] ~= HealthMidTransparency
                        or Data['LastHealthBotTransparency'] ~= HealthBotTransparency then
                        Objects['HealthBarGradient'].Transparency = NumSeq({
                            NumKey(0, HealthTopTransparency),
                            NumKey(0.5, HealthMidTransparency),
                            NumKey(1, HealthBotTransparency),
                        })
                        Data['LastHealthTopTransparency'] = HealthTopTransparency
                        Data['LastHealthMidTransparency'] = HealthMidTransparency
                        Data['LastHealthBotTransparency'] = HealthBotTransparency
                    end
                else
                    if Objects['HealthBarOutline'].Visible then
                        Objects['HealthBarOutline'].Visible = false
                    end


                    if Objects['LeftBarHolder'].Visible then
                        Objects['LeftBarHolder'].Visible = false
                    end
                end

                local HeavyCfg = Table['Bars']['Heavy Bar']
                local HeavyEnabled =
                    HeavyCfg ~= nil
                    and (
                        VisualizeSelected == true
                        or HeavyCfg['Enabled'] == true
                    )
                local HeavyRatio = 0
                local HeavyRemaining = 0
                local HeavyVisible = false

                if HeavyEnabled then
                    HeavyRatio, HeavyRemaining = GetESPHeavyCooldownData(Data['Character'], Data, FrameNow)
                    HeavyRemaining = math.max(0, tonumber(HeavyRemaining) or 0)
                    HeavyRatio = math.clamp(tonumber(HeavyRatio) or 0, 0, 1)
                end

                if HeavyEnabled then
                    HeavyVisible = HeavyRemaining > 0.001 and HeavyRatio > 0.001

                    if HeavyVisible then
                        if not Objects['BottomBarHolder'].Visible then
                            Objects['BottomBarHolder'].Visible = true
                        end
                        if not Objects['HeavyBarOutline'].Visible then
                            Objects['HeavyBarOutline'].Visible = true
                        end

                        if Data['LastHeavyRatio'] ~= HeavyRatio then
                            Objects['HeavyBar'].Size = Dim2(HeavyRatio, 0, 1, 0)
                            Data['LastHeavyRatio'] = HeavyRatio
                        end

                        local HeavyColor =
                            (VisualizeSelected and RelationColor)
                            or HeavyCfg['Color']
                            or ESPHeavyColor
                        if Data['LastHeavyColor'] ~= HeavyColor then
                            Objects['HeavyBar'].BackgroundColor3 = HeavyColor
                            Data['LastHeavyColor'] = HeavyColor
                        end

                        local HeavyFadeWindow = 0.45
                        local HeavyFade = 1 - math.clamp(HeavyRemaining / HeavyFadeWindow, 0, 1)
                        local BaseHeavyTransparency = math.clamp(tonumber(HeavyCfg['Transparency']) or 0, 0, 1)
                        local EffectiveHeavyTransparency = BaseHeavyTransparency
                            + ((1 - BaseHeavyTransparency) * HeavyFade)

                        if Data['LastHeavyEffectiveTransparency'] ~= EffectiveHeavyTransparency then
                            Objects['HeavyBar'].BackgroundTransparency = EffectiveHeavyTransparency
                            Data['LastHeavyEffectiveTransparency'] = EffectiveHeavyTransparency
                        end

                        if Data['LastHeavyOutlineTransparency'] ~= HeavyFade then
                            Objects['HeavyBarOutline'].BackgroundTransparency = HeavyFade
                            if Objects['HeavyBarStroke'] then
                                Objects['HeavyBarStroke'].Transparency = HeavyFade
                            end
                            Data['LastHeavyOutlineTransparency'] = HeavyFade
                        end
                    end
                end

                if not HeavyVisible and Objects['HeavyBarOutline'].Visible then
                    Objects['HeavyBarOutline'].Visible = false
                end

                if not HeavyVisible and Objects['BottomBarHolder'].Visible then
                    Objects['BottomBarHolder'].Visible = false
                end

                local FlagsCfg = Table['Flags']
                local Character = Data['Character']
                local StyleCfg = FlagsCfg['Fighting Style']
                local StunnedCfg = FlagsCfg['Stunned']
                local HealthNumberCfg = FlagsCfg['Health Number']
                local StyleEnabled =
                    VisualizeSelected == true
                    or StyleCfg['Enabled'] == true
                local StunnedEnabled =
                    VisualizeSelected == true
                    or StunnedCfg['Enabled'] == true
                local HealthNumberEnabled =
                    VisualizeSelected == true
                    or HealthNumberCfg['Enabled'] == true

                local FightingStyle =
                    StyleEnabled
                    and Character
                    and GetESPCharacterStyle(Character)
                    or nil

                local StyleFont = StyleCfg['Font']
                if Data['LastStyleFont'] ~= StyleFont then
                    Objects['StyleFlag'].FontFace =
                        ResolveESPFontFace(StyleFont)
                    Data['LastStyleFont'] = StyleFont
                end

                local StunnedFont = StunnedCfg['Font']
                if Data['LastStunnedFont'] ~= StunnedFont then
                    Objects['StunnedFlag'].FontFace =
                        ResolveESPFontFace(StunnedFont)
                    Data['LastStunnedFont'] = StunnedFont
                end

                local HealthNumberFont = HealthNumberCfg['Font']
                if Data['LastHealthNumberFont'] ~= HealthNumberFont then
                    Objects['HealthFlag'].FontFace =
                        ResolveESPFontFace(HealthNumberFont)
                    Data['LastHealthNumberFont'] = HealthNumberFont
                end

                if StyleEnabled then
                    self:SetFlagPosition(Data, "StyleFlag", StyleCfg['Position'] or "Right", 10)
                end

                if StunnedEnabled then
                    self:SetFlagPosition(Data, "StunnedFlag", StunnedCfg['Position'] or "Right", 11)
                end

                local IsStunned =
                    StunnedEnabled
                    and Character
                    and (
                        Character:GetAttribute("Parried") == true
                        or Character:GetAttribute("Stunned") == true
                    )
                    or false

                Objects['StyleFlag'].Visible = StyleEnabled and FightingStyle ~= nil and tostring(FightingStyle) ~= ""
                if Objects['StyleFlag'].Visible then
                    local StyleText = tostring(FightingStyle)
                    if Data['LastStyleText'] ~= StyleText then
                        Objects['StyleFlag'].Text = StyleText
                        Data['LastStyleText'] = StyleText
                    end
                end
                Objects['StunnedFlag'].Visible = StunnedEnabled and IsStunned
                Objects['StunnedFlag'].Text = "Stunned"
                Objects['HealthFlag'].Visible =
                    HealthNumberEnabled
                    and HealthEnabled

                if Objects['HealthFlag'].Visible then
                    local Health = Data['Health'] or 0
                    local MaxHealth = math.max(Data['MaxHealth'] or 100, 1)
                    local Ratio = Clamp(Health / MaxHealth, 0, 1)
                    local FlooredHealth = Floor(Health)

                    if Data['LastHealthFlagValue'] ~= FlooredHealth then
                        Objects['HealthFlag'].Text = Format('%d', FlooredHealth)
                        Data['LastHealthFlagValue'] = FlooredHealth
                    end

                    local StyleOnLeft =
                        Objects['StyleFlag'].Visible == true
                        and tostring(StyleCfg['Position'] or "Right") == "Left"
                    local StunnedOnLeft =
                        Objects['StunnedFlag'].Visible == true
                        and tostring(StunnedCfg['Position'] or "Right") == "Left"
                    local HasLeftStatusFlag = StyleOnLeft or StunnedOnLeft

                    local HealthNumberX = -9
                    local HealthNumberStartPixel = 0

                    if HasLeftStatusFlag
                        and Objects['LeftTextHolder']
                        and Objects['TargetHolder'] then
                        local TargetAbsolute = Objects['TargetHolder'].AbsolutePosition
                        local LeftAbsolute = Objects['LeftTextHolder'].AbsolutePosition
                        local LeftSize = Objects['LeftTextHolder'].AbsoluteSize

                        local LaneRight =
                            (LeftAbsolute.X + LeftSize.X) - TargetAbsolute.X
                        local LaneBottom =
                            (LeftAbsolute.Y + LeftSize.Y) - TargetAbsolute.Y

                        if LeftSize.X > 0 then
                            HealthNumberX = Floor(LaneRight)
                        else
                            HealthNumberX = -14
                        end

                        HealthNumberStartPixel = math.max(
                            4,
                            LaneBottom + 2
                        )
                    end

                    local HealthBarTopPixel = Clamp(1 - Ratio, 0, 1) * H
                    local HealthTextPixel = Clamp(
                        math.max(HealthNumberStartPixel, HealthBarTopPixel),
                        0,
                        H * 0.96
                    )

                    Objects['HealthFlag'].Position = Dim2(
                        0,
                        HealthNumberX,
                        0,
                        Floor(HealthTextPixel)
                    )
                    Objects['HealthFlag'].TextColor3 = RelationColor or HealthNumberCfg['Color']
                end

                if StyleEnabled
                    and FightingStyle
                then
                    local StyleColor =
                        (VisualizeSelected and RelationColor)
                        or GetFightingStyleRarityColor(
                            Character,
                            FightingStyle
                        )

                    if Data['LastStyleColor']
                        ~= StyleColor
                    then
                        Objects['StyleFlag'].TextColor3 =
                            StyleColor
                        Data['LastStyleColor'] =
                            StyleColor
                    end
                end

                local StunnedColor =
                    (VisualizeSelected and RelationColor)
                    or StunnedCfg['Color']

                if Data['LastStunnedColor']
                    ~= StunnedColor
                then
                    Objects['StunnedFlag'].TextColor3 =
                        StunnedColor
                    Data['LastStunnedColor'] =
                        StunnedColor
                end

                local StyleTransparency = math.clamp(StyleCfg['Transparency'] or 0, 0, 1)
                local StunnedTransparency = math.clamp(StunnedCfg['Transparency'] or 0, 0, 1)
                local HealthNumberTransparency = math.clamp(HealthNumberCfg['Transparency'] or 0, 0, 1)
                if Data['LastStyleTransparency'] ~= StyleTransparency then
                    Objects['StyleFlag'].TextTransparency = StyleTransparency
                    if Objects['StyleFlagStroke'] then
                        Objects['StyleFlagStroke'].Transparency = StyleTransparency
                    end
                    Data['LastStyleTransparency'] = StyleTransparency
                end
                if Data['LastStunnedTransparency'] ~= StunnedTransparency then
                    Objects['StunnedFlag'].TextTransparency = StunnedTransparency
                    if Objects['StunnedFlagStroke'] then
                        Objects['StunnedFlagStroke'].Transparency = StunnedTransparency
                    end
                    Data['LastStunnedTransparency'] = StunnedTransparency
                end
                if Data['LastHealthNumberTransparency'] ~= HealthNumberTransparency then
                    Objects['HealthFlag'].TextTransparency = HealthNumberTransparency
                    if Objects['HealthFlagStroke'] then
                        Objects['HealthFlagStroke'].Transparency = HealthNumberTransparency
                    end
                    Data['LastHealthNumberTransparency'] = HealthNumberTransparency
                end

                local BoxFade = self:GetVisualFadeAlpha(Data, "Box", BoxEnabled, FrameNow) * RangeFadeAlpha
                local NameFade = self:GetVisualFadeAlpha(Data, "Name", NameEnabled, FrameNow) * RangeFadeAlpha
                local DistanceTextFade = self:GetVisualFadeAlpha(Data, "Distance", DistanceEnabled, FrameNow) * RangeFadeAlpha
                local HealthFade = self:GetVisualFadeAlpha(Data, "Health", HealthEnabled, FrameNow) * RangeFadeAlpha
                local StyleTarget = StyleEnabled and FightingStyle ~= nil and tostring(FightingStyle) ~= ""
                local StyleFade = self:GetVisualFadeAlpha(Data, "Style", StyleTarget, FrameNow) * RangeFadeAlpha
                local StunnedFade = self:GetVisualFadeAlpha(Data, "Stunned", StunnedEnabled and IsStunned, FrameNow) * RangeFadeAlpha
                local HealthNumberFade = self:GetVisualFadeAlpha(Data, "HealthNumber", HealthNumberEnabled and HealthEnabled, FrameNow) * RangeFadeAlpha

                local BoxBaseTransparency = math.clamp(BoxesCfg['Gradients']['Transparency'] or 0, 0, 1)
                local BoxTransparency = ESPFadeTransparency(BoxBaseTransparency, BoxFade)
                local FinalBoxVisible =
                    BoxFade > 0.001

                SetESPProperty(
                    Data,
                    "FinalBoxOutlineVisible",
                    Objects['BoxOutlineHolder'],
                    "Visible",
                    FinalBoxVisible
                )
                SetESPProperty(
                    Data,
                    "FinalBoxInlineVisible",
                    Objects['BoxInlineHolder'],
                    "Visible",
                    FinalBoxVisible
                )
                SetESPProperty(
                    Data,
                    "FinalBoxOutlineT",
                    Objects['BoxOutline'],
                    "Transparency",
                    BoxTransparency
                )
                SetESPProperty(
                    Data,
                    "FinalBoxInlineT",
                    Objects['BoxInline'],
                    "Transparency",
                    BoxTransparency
                )


                ApplyESPTextFade(
                    Data,
                    "FinalName",
                    Objects['Name'],
                    Objects['NameStroke'],
                    TextsCfg['Name']['Transparency'] or 0,
                    NameFade
                )

                ApplyESPTextFade(
                    Data,
                    "FinalDistance",
                    Objects['Distance'],
                    Objects['DistanceStroke'],
                    TextsCfg['Distance']['Transparency'] or 0,
                    DistanceTextFade
                )

                ApplyESPTextFade(
                    Data,
                    "FinalStyle",
                    Objects['StyleFlag'],
                    Objects['StyleFlagStroke'],
                    StyleCfg['Transparency'] or 0,
                    StyleFade
                )

                ApplyESPTextFade(
                    Data,
                    "FinalStunned",
                    Objects['StunnedFlag'],
                    Objects['StunnedFlagStroke'],
                    StunnedCfg['Transparency'] or 0,
                    StunnedFade
                )

                ApplyESPTextFade(
                    Data,
                    "FinalHealthFlag",
                    Objects['HealthFlag'],
                    Objects['HealthFlagStroke'],
                    HealthNumberCfg['Transparency'] or 0,
                    HealthNumberFade
                )

                local FinalHealthVisible =
                    HealthFade > 0.001
                local FinalHealthT =
                    1 - HealthFade

                SetESPProperty(
                    Data,
                    "FinalHealthOutlineVisible",
                    Objects['HealthBarOutline'],
                    "Visible",
                    FinalHealthVisible
                )
                SetESPProperty(
                    Data,
                    "FinalHealthOutlineT",
                    Objects['HealthBarOutline'],
                    "BackgroundTransparency",
                    FinalHealthT
                )
                SetESPProperty(
                    Data,
                    "FinalHealthStrokeT",
                    Objects['HealthBarStroke'],
                    "Transparency",
                    FinalHealthT
                )
                SetESPProperty(
                    Data,
                    "FinalHealthBarT",
                    Objects['HealthBar'],
                    "BackgroundTransparency",
                    FinalHealthT
                )
                SetESPProperty(
                    Data,
                    "FinalLeftBarVisible",
                    Objects['LeftBarHolder'],
                    "Visible",
                    FinalHealthVisible
                )

                local HeavyFadeTarget = HeavyEnabled and HeavyVisible
                local HeavyFeatureFade = self:GetVisualFadeAlpha(Data, "Heavy", HeavyFadeTarget, FrameNow) * RangeFadeAlpha
                if HeavyFeatureFade > 0.001 then
                    Objects['BottomBarHolder'].Visible = true
                    Objects['HeavyBarOutline'].Visible = true
                    local BaseHeavyTransparency = math.clamp(tonumber(HeavyCfg and HeavyCfg['Transparency']) or 0, 0, 1)
                    local CooldownFade = HeavyVisible and (1 - math.clamp(HeavyRemaining / 0.45, 0, 1)) or 0
                    local HeavyBase = BaseHeavyTransparency + ((1 - BaseHeavyTransparency) * CooldownFade)
                    Objects['HeavyBar'].BackgroundTransparency = ESPFadeTransparency(HeavyBase, HeavyFeatureFade)
                    Objects['HeavyBarOutline'].BackgroundTransparency = ESPFadeTransparency(CooldownFade, HeavyFeatureFade)
                    if Objects['HeavyBarStroke'] then
                        Objects['HeavyBarStroke'].Transparency = ESPFadeTransparency(CooldownFade, HeavyFeatureFade)
                    end
                else
                    Objects['HeavyBarOutline'].Visible = false
                    Objects['BottomBarHolder'].Visible = false
                end

                if not InRange or not BoxEnabled or DownConfirmed then
                    Objects['BoxGlow'].ImageTransparency = 1
                    Objects['BoxFill'].Visible = false
                end

                if DownFade > 0 then
                    self:ApplyDownFade(Data, DownFade)

                    if DownFade >= 0.999 then
                        if Objects['Chams'] then
                            Objects['Chams'].FillTransparency = 1
                            Objects['Chams'].OutlineTransparency = 1
                        end
                        HideESPTarget(Objects)
                    end
                end
            end

            function ESPVisuals:UpdateChamsState(Data, FrameNow, PrecomputedDistance)
                local cfg = Table["Chams"]
                local Objects = Data and Data.Objects
                if not Objects then
                    return
                end

                local existing = Objects["Chams"]
                local ForceVisualize =
                    self:IsPlayerVisualized(Data.Player)

                if cfg["Enabled"] ~= true
                    and not ForceVisualize
                then
                    Data.ChamsAttachAt = nil
                    Data.ChamsReadyAt = nil
                    if existing then
                        existing.Enabled = false
                    end
                    return
                end

                local Character = Data.Character
                local Distance = tonumber(PrecomputedDistance)
                    or self:GetChamsCandidateDistance(Data)
                if not Distance or not Character or not Character.Parent then
                    return
                end

                local Chams = self:EnsureChams(
                    Data,
                    Character,
                    FrameNow
                )
                if not Chams then
                    return
                end

                -- EnsureChams deliberately stages a new/reused lease. Do not enable
                -- until the Adornee assignment has had its own frame budget.
                if Data.ChamsAttachAt ~= nil then
                    return
                end

                local readyAt = tonumber(Data.ChamsReadyAt) or 0
                if FrameNow < readyAt then
                    Chams.Enabled = false
                    return
                end
                Data.ChamsReadyAt = nil

                local RelationColor = GetESPRelationColor(Data["Player"])
                Chams.FillColor = RelationColor or cfg["FillRGB"]
                Chams.OutlineColor = RelationColor or cfg["OutlineRGB"]
                Chams.DepthMode =
                    (ForceVisualize ~= true and cfg["VisibleCheck"])
                    and Enum.HighlightDepthMode.Occluded
                    or Enum.HighlightDepthMode.AlwaysOnTop

                local FillBase =
                    math.clamp(
                        tonumber(cfg["FillTransparency"]) or 0.70,
                        0,
                        1
                    )

                if cfg["Thermal"] == true
                    or ForceVisualize == true
                then
                    local Wave =
                        (math.sin(FrameNow * 1.35) + 1) * 0.5
                    local VisiblePoint = math.max(0, FillBase - 0.18)
                    local FadedPoint = math.min(0.96, FillBase + 0.08)
                    FillBase = VisiblePoint
                        + (FadedPoint - VisiblePoint) * Wave
                end

                Chams.FillTransparency = FillBase
                Chams.OutlineTransparency =
                    math.clamp(
                        tonumber(cfg["OutlineTransparency"]) or 0.80,
                        0,
                        1
                    )

                if Chams.Enabled ~= true then
                    local nextEnable =
                        tonumber(self.ChamsEnableNextAt) or 0
                    if FrameNow < nextEnable then
                        return
                    end

                    -- Renderer activation is also serialized. Reused pool entries do
                    -- not need a new Instance allocation, only this cheap enable step.
                    self.ChamsEnableNextAt = FrameNow + 0.025
                end

                Chams.Enabled = true
            end

            do
                ESPVisuals.ChamsAccumulator = 0
                ESPVisuals.ChamsCreateNextAt = 0
                ESPVisuals.ChamsEnableNextAt = 0
                ESPVisuals.ChamsCreateAllowed = false
                ESPVisuals.ChamsFrameAverage = nil
                ESPVisuals.ChamsPoolLimit = math.max(
                    1,
                    tonumber(Players.MaxPlayers) or 32
                )
                ESPVisuals.ChamsCandidates = {}

                ESPVisuals:CreateThreads(
                    "ChamsState",
                    RunService.Heartbeat,
                    function(DeltaTime)
                        local dt =
                            math.max(
                                tonumber(DeltaTime) or 0,
                                0
                            )

                        if not Camera then
                            Camera = Workspace.CurrentCamera
                        end
                        if not Camera then
                            return
                        end

                        CameraPosition = Camera.CFrame.Position

                        local now = os.clock()
                        local frameAverage =
                            tonumber(ESPVisuals.ChamsFrameAverage)
                            or dt
                        frameAverage =
                            frameAverage * 0.90
                            + dt * 0.10
                        ESPVisuals.ChamsFrameAverage = frameAverage

                        local VisualizeRuntime =
                            Menu._PlayerListRuntime
                        local VisualizePlayer =
                            Flags.list_player_visualize == true
                            and VisualizeRuntime
                            and VisualizeRuntime.selected
                            or nil
                        local WhitelistVisualizeActive =
                            type(Menu._HasWhitelistVisualizeTarget) == "function"
                            and Menu._HasWhitelistVisualizeTarget() == true
                        local GlobalChamsEnabled =
                            Table["Chams"]["Enabled"] == true

                        -- Chams can run for Player Visualize targets (selected or
                        -- whitelisted friends) even when global Chams is disabled.
                        if not GlobalChamsEnabled
                            and not VisualizePlayer
                            and not WhitelistVisualizeActive
                        then
                            ESPVisuals.ChamsAccumulator = 0
                            ESPVisuals.ChamsCreateAllowed = false

                            local Pool = ESPVisuals.ChamsPool
                            if type(Pool) == "table" then
                                for index = 1, #Pool do
                                    local Entry = Pool[index]
                                    local Highlight = Entry and Entry.Highlight
                                    if typeof(Highlight) == "Instance"
                                        and Highlight.Enabled == true
                                    then
                                        Highlight.Enabled = false
                                    end
                                end
                            end
                            return
                        end

                        ESPVisuals.ChamsAccumulator =
                            (ESPVisuals.ChamsAccumulator or 0) + dt

                        -- 40 Hz keeps pool population effectively instant in a full
                        -- server while still avoiding a full-cache scan every Heartbeat.
                        if ESPVisuals.ChamsAccumulator < 0.025 then
                            return
                        end
                        ESPVisuals.ChamsAccumulator =
                            ESPVisuals.ChamsAccumulator % 0.025

                        ESPVisuals.ChamsCreateAllowed =
                            dt <= math.max(0.022, frameAverage * 1.25)
                            and now >= (
                                tonumber(ESPVisuals.ChamsCreateNextAt) or 0
                            )

                        local Candidates = ESPVisuals.ChamsCandidates
                        table.clear(Candidates)

                        for _, Data in ESPVisuals.Cache do
                            local ShouldRenderChams =
                                GlobalChamsEnabled
                                or ESPVisuals:IsPlayerVisualized(Data.Player)

                            if ShouldRenderChams then
                                local Distance =
                                    ESPVisuals:GetChamsCandidateDistance(Data)
                                if Distance then
                                    Candidates[#Candidates + 1] = Data
                                end
                            elseif Data
                                and Data.Objects
                                and Data.Objects["Chams"]
                            then
                                ESPVisuals:ReleaseChams(Data)
                            end
                        end

                        table.sort(Candidates, function(A, B)
                            return (tonumber(A.ChamsDistance) or math.huge)
                                < (tonumber(B.ChamsDistance) or math.huge)
                        end)

                        -- Distance owns Chams eligibility. Do not cap the active
                        -- set to the nearest N players: that made the Distance slider
                        -- appear disconnected. Missing pooled Highlights are still
                        -- created gradually by EnsureChams, so covering the full range
                        -- does not reintroduce a one-frame allocation burst.
                        for index = 1, #Candidates do
                            local Data = Candidates[index]
                            ESPVisuals:UpdateChamsState(
                                Data,
                                now,
                                Data.ChamsDistance
                            )
                        end
                    end
                )
            end

            do
                ESPVisuals.RendererSignal = "Heartbeat"

                pcall(function()
                    RunService:UnbindFromRenderStep("Silent.solutions.ESP")
                    RunService:UnbindFromRenderStep("Gakuran.ESP")
                end)

                ESPVisuals.TargetFPS =
                    math.clamp(
                        math.floor(
                            (
                                tonumber(
                                    Flags.visual_esp_fps
                                )
                                or 60
                            ) + 0.5
                        ),
                        15,
                        240
                    )
                ESPVisuals.RenderInterval =
                    1 / ESPVisuals.TargetFPS
                ESPVisuals.RenderAccumulator =
                    0

                ESPVisuals:CreateThreads("Renderer", RunService.Heartbeat, function(DeltaTime)
                    local FrameNow =
                        os.clock()

                    if not Table['Enabled']
                        and FrameNow
                            >= (
                                ESPVisuals.VisualFadeUntil
                                or 0
                            )
                    then
                        ESPVisuals.RenderAccumulator =
                            0
                        return
                    end

                    local TargetFPS =
                        math.clamp(
                            tonumber(
                                ESPVisuals.TargetFPS
                            ) or 60,
                            15,
                            240
                        )
                    ESPVisuals.RenderInterval =
                        1 / TargetFPS

                    ESPVisuals.RenderAccumulator =
                        (
                            ESPVisuals.RenderAccumulator
                            or 0
                        )
                        + math.max(
                            tonumber(DeltaTime)
                                or 0,
                            0
                        )

                    if ESPVisuals.RenderAccumulator
                        < ESPVisuals.RenderInterval
                    then
                        return
                    end

                    ESPVisuals.RenderAccumulator =
                        ESPVisuals.RenderAccumulator
                        % ESPVisuals.RenderInterval

                    local CurrentCamera =
                        Workspace.CurrentCamera

                    if CurrentCamera
                        and CurrentCamera ~= Camera
                    then
                        Camera =
                            CurrentCamera
                    end

                    if not Camera then
                        return
                    end

                    CameraPosition =
                        Camera.CFrame.Position

                    local ForceFullRate =
                        FrameNow
                        < (
                            ESPVisuals.VisualFadeUntil
                            or 0
                        )

                    local Global2DEnabled =
                        Table['Boxes']['Enabled'] == true
                        or Table['Bars']['Health Bar']['Enabled'] == true
                        or (
                            Table['Bars']['Heavy Bar']
                            and Table['Bars']['Heavy Bar']['Enabled'] == true
                        )
                        or Table['Texts']['Name']['Enabled'] == true
                        or Table['Texts']['Distance']['Enabled'] == true
                        or Table['Flags']['Fighting Style']['Enabled'] == true
                        or Table['Flags']['Stunned']['Enabled'] == true
                        or Table['Flags']['Health Number']['Enabled'] == true

                    for Player, Data in ESPVisuals['Cache'] do
                        local ForceVisualize =
                            ESPVisuals:IsPlayerVisualized(Player)

                        if not Global2DEnabled
                            and not ForceVisualize
                        then
                            local holder =
                                Data.Objects
                                and Data.Objects.TargetHolder
                            if holder and holder.Visible then
                                holder.Visible = false
                            end
                            Data['NextESPUpdateAt'] =
                                FrameNow + 0.12
                            continue
                        end
                        local Interval =
                            1 / math.clamp(
                                tonumber(
                                    ESPVisuals.TargetFPS
                                ) or 60,
                                15,
                                240
                            )

                        if ForceFullRate then
                            Interval =
                                math.min(
                                    Interval,
                                    1 / 60
                                )
                        end

                        local NextAt =
                            tonumber(
                                Data['NextESPUpdateAt']
                            )
                            or 0

                        if FrameNow < NextAt then
                            continue
                        end

                        local RootPart =
                            Data['RootPart']

                        if not RootPart
                            or not RootPart.Parent
                        then
                            ESPVisuals:Update(
                                Player,
                                Data,
                                FrameNow
                            )
                            continue
                        end

                        local QuickDistance =
                            Floor(
                                (
                                    CameraPosition
                                    - RootPart.Position
                                ).Magnitude
                            )

                        local RangeLimit =
                            ForceVisualize
                            and 1500
                            or (
                                tonumber(
                                    Table['Distance']
                                ) or 100
                            )

                        local RangeState =
                            Data['VisualFadeStates']
                            and Data['VisualFadeStates']['__Range']
                        local RangeAlpha =
                            RangeState
                            and tonumber(RangeState.Alpha)
                            or 0

                        if QuickDistance > RangeLimit + 24
                            and RangeAlpha <= 0.001
                        then
                            local holder =
                                Data.Objects
                                and Data.Objects.TargetHolder
                            if holder and holder.Visible then
                                holder.Visible = false
                            end

                            Data['NextESPUpdateAt'] =
                                FrameNow
                                + math.max(
                                    0.10
                                        * ESPVisuals:GetPerformanceScale(),
                                    Interval * 2
                                )
                            continue
                        end

                        local RootScreen =
                            Camera:WorldToViewportPoint(
                                RootPart.Position
                            )
                        local Viewport =
                            Camera.ViewportSize
                        local Margin = 140

                        if RootScreen.Z <= 0.05
                            or RootScreen.X < -Margin
                            or RootScreen.X > Viewport.X + Margin
                            or RootScreen.Y < -Margin
                            or RootScreen.Y > Viewport.Y + Margin
                        then
                            local holder =
                                Data.Objects
                                and Data.Objects.TargetHolder
                            if holder and holder.Visible then
                                holder.Visible = false
                            end

                            Data['NextESPUpdateAt'] =
                                FrameNow
                                + math.max(
                                    Interval,
                                    0.05
                                        * ESPVisuals:GetPerformanceScale()
                                )
                            continue
                        end

                        ESPVisuals:Update(
                            Player,
                            Data,
                            FrameNow,
                            QuickDistance
                        )

                        local UserId =
                            tonumber(
                                Player.UserId
                            )
                            or 0

                        local Phase =
                            (
                                UserId % 17
                            )
                            / 17
                            * Interval

                        local Slot =
                            math.floor(
                                (
                                    FrameNow
                                    - Phase
                                )
                                / Interval
                            ) + 1

                        Data['NextESPUpdateAt'] =
                            Slot
                                * Interval
                                + Phase
                    end
                end)
            end

            do
                for _, Player in Players:GetPlayers() do
                    ESPVisuals:AddTarget(Player)
                end

                ESPVisuals:CreateThreads('PlayerAdded', Players.PlayerAdded, function(Player)
                    ESPVisuals:AddTarget(Player)
                end)

                ESPVisuals:CreateThreads('PlayerRemoving', Players.PlayerRemoving, function(Player)
                    ESPVisuals:RemoveTarget(Player)
                end)
            end

            do
                function ESPVisuals:Unload()
                    for Player in self['Cache'] do
                        self:RemoveTarget(Player);
                    end;

                    if type(self.ChamsPool) == "table" then
                        for index = 1, #self.ChamsPool do
                            local Entry = self.ChamsPool[index]
                            local Highlight = Entry and Entry.Highlight
                            if typeof(Highlight) == "Instance" then
                                pcall(function()
                                    Highlight:Destroy()
                                end)
                            end
                        end
                        table.clear(self.ChamsPool)
                    end
                    self.ChamsPoolByHighlight = {}
                    if typeof(self.ChamsPoolFolder) == "Instance" then
                        pcall(function()
                            self.ChamsPoolFolder:Destroy()
                        end)
                    end
                    self.ChamsPoolFolder = nil

                    for _, Conn in self['Connections'] do
                        Conn:Disconnect();
                    end;

                    Clear(self['Connections']);

                    for _, Conn in self['Threads'] do
                        Conn:Disconnect();
                    end;

                    Clear(self['Threads']);

                    if self['Holder'] then
                        self['Holder']:Destroy();
                        self['Holder'] = nil;
                    end;

                    pcall(function()
                        local GuiRoots = {}
                        local PlayerGui =
                            LocalPlayer
                            and LocalPlayer:FindFirstChildOfClass("PlayerGui")
                        if PlayerGui then
                            GuiRoots[#GuiRoots + 1] = PlayerGui
                        end
                        if type(gethui) == "function" then
                            local okHui, Hui = pcall(gethui)
                            if okHui and Hui and Hui ~= PlayerGui then
                                GuiRoots[#GuiRoots + 1] = Hui
                            end
                        end

                        for _, GuiRoot in ipairs(GuiRoots) do
                            local okChildren, Children =
                                pcall(function()
                                    return GuiRoot:GetChildren()
                                end)
                            if okChildren and type(Children) == "table" then
                                for _, Child in ipairs(Children) do
                                    if Child.Name == "Silent.solutionsESP"
                                        or Child.Name:match("^Silent%.solutionsESP") then
                                        pcall(function()
                                            Child:Destroy()
                                        end)
                                    end
                                end
                            end
                        end
                    end);

                    Clear(self['Cache']);
                end
            end

            return ESPVisuals
end)()

    env.__GakuranESPVisuals = Menu._ESPVisuals

    local ESP = Menu._ESPVisuals
    local ESPTable = ESP and ESP.Table
    local ESPSection = Menu._VisualsUI.ESP
    local FlagsSection = Menu._VisualsUI.Flags
    local WorldSection = Menu._VisualsUI.World
    local SettingsSection = Menu._VisualsUI.Settings

    local function normalizeDropdown(value, fallback)
        if type(value) == "table" then
            value = value[1] or value.value or value.Value
        end
        if value == nil or value == "" then
            return fallback
        end
        return tostring(value)
    end

    local function colorFlag(name, fallback)
        local value = Flags[name]
        if typeof(value) == "Color3" then
            return value
        end
        return fallback
    end

    local function alphaFlag(name, fallback)
        local value = tonumber(Flags[name])
        if value == nil or value ~= value then
            return fallback
        end
        return math.clamp(value, 0, 1)
    end

    local function bindColor(element, colorName, alphaName, fallbackColor, fallbackAlpha, callback)
        if not element then
            return
        end

        local function apply()
            callback(
                colorFlag(colorName, fallbackColor),
                alphaFlag(alphaName, fallbackAlpha)
            )
        end

        if element["on_color_change"] then
            Connect(element["on_color_change"], apply)
        end
        if element["on_transparency_change"] then
            Connect(element["on_transparency_change"], apply)
        end

        apply()
    end

    local function hideAllESP()
        if not ESP or not ESP.Cache then
            return
        end
        for _, data in pairs(ESP.Cache) do
            local objects = data and data.Objects
            if objects then
                local holder = objects.TargetHolder
                if holder then
                    holder.Visible = false
                end
            end
        end
    end

    local function refreshESPEnabled()
        if not ESPTable then
            return
        end

        local boxes = ESPTable.Boxes
        local bars = ESPTable.Bars
        local texts = ESPTable.Texts
        local espFlags = ESPTable.Flags
        local selectedPlayerVisualizeEnabled =
            Flags.list_player_visualize == true
            and Menu._PlayerListRuntime ~= nil
            and Menu._PlayerListRuntime.selected ~= nil
            and Menu._PlayerListRuntime.selected.Parent ~= nil
        local whitelistVisualizeEnabled =
            type(Menu._HasWhitelistVisualizeTarget) == "function"
            and Menu._HasWhitelistVisualizeTarget() == true
        local playerVisualizeEnabled =
            selectedPlayerVisualizeEnabled
            or whitelistVisualizeEnabled

        -- Chams has its own lightweight updater. Do not wake the full 2D ESP
        -- renderer just because Chams is enabled; that was the remaining
        -- first-toggle frame spike.
        local any2DEnabled =
            boxes.Enabled
            or bars["Health Bar"].Enabled
            or (bars["Heavy Bar"] and bars["Heavy Bar"].Enabled)
            or texts.Name.Enabled
            or texts.Distance.Enabled
            or espFlags["Fighting Style"].Enabled
            or espFlags.Stunned.Enabled
            or espFlags["Health Number"].Enabled
            or playerVisualizeEnabled

        ESPTable.Enabled = any2DEnabled == true

        if any2DEnabled then
            ESP.VisualFadeUntil = 0
        else
            ESP.VisualFadeUntil = os.clock() + 0.28
            task.delay(0.30, function()
                if ESPTable
                    and ESPTable.Enabled ~= true
                    and os.clock() >= (ESP.VisualFadeUntil or 0)
                then
                    -- Only hide 2D holders here. Chams is controlled by its
                    -- independent updater and must not be torn down/re-enabled.
                    hideAllESP()
                end
            end)
        end
    end

    Menu._RefreshESPEnabled = refreshESPEnabled

    local fontOptions = {
        "Made Bold",
        "Segoe UI",
        "Verdana",
    }

    local fontOptionsWithFallback = {
        "Made Bold",
        "Segoe UI",
        "Verdana",
        "smallest_pixel-7",
    }

    local function addESPDivider(section, name)
        return section:create_element({
            ["name"] = tostring(name or ""),
        }, {
            ["divider"] = {},
        })
    end

    addESPDivider(ESPSection, "Boxes")

    Menu._VisualsUI.Box = ESPSection:create_element({
        ["name"] = "Box",
    }, {
        ["toggle"] = {
            ["default"] = false,
            ["flag"] = "visual_esp_box",
        },
        ["colorpicker"] = {
            ["default_color"] = themeAccent,
            ["default_transparency"] = 0,
            ["color_flag"] = "visual_esp_box_color",
            ["transparency_flag"] = "visual_esp_box_transparency",
        },
    })

    Menu._VisualsUI.BoxGlow = ESPSection:create_element({
        ["name"] = "Box Glow",
    }, {
        ["toggle"] = {
            ["default"] = false,
            ["flag"] = "visual_esp_box_glow",
        },
        ["colorpicker"] = {
            ["default_color"] = themeAccent,
            ["default_transparency"] = 0.90,
            ["color_flag"] = "visual_esp_box_glow_color",
            ["transparency_flag"] = "visual_esp_box_glow_transparency",
        },
    })

    Menu._VisualsUI.BoxFill = ESPSection:create_element({
        ["name"] = "Box Fill",
    }, {
        ["toggle"] = {
            ["default"] = false,
            ["flag"] = "visual_esp_box_fill",
        },
    })
    Menu._VisualsUI.BoxFillSettings = Menu._VisualsUI.BoxFill:create_settings()
    Menu._VisualsUI.BoxFillTop = Menu._VisualsUI.BoxFillSettings:create_element({
        ["name"] = "Top",
    }, {
        ["colorpicker"] = {
            ["default_color"] = themeAccent,
            ["default_transparency"] = 0.80,
            ["color_flag"] = "visual_esp_box_fill_top_color",
            ["transparency_flag"] = "visual_esp_box_fill_top_transparency",
        },
    })
    Menu._VisualsUI.BoxFillBottom = Menu._VisualsUI.BoxFillSettings:create_element({
        ["name"] = "Bottom",
    }, {
        ["colorpicker"] = {
            ["default_color"] = themeAccent,
            ["default_transparency"] = 0.80,
            ["color_flag"] = "visual_esp_box_fill_bottom_color",
            ["transparency_flag"] = "visual_esp_box_fill_bottom_transparency",
        },
    })

    addESPDivider(ESPSection, "Chams")

    Menu._VisualsUI.Chams = ESPSection:create_element({
        ["name"] = "Chams",
    }, {
        ["toggle"] = {
            ["default"] = false,
            ["flag"] = "visual_esp_chams",
        },
    })
    Menu._VisualsUI.ChamsSettings = Menu._VisualsUI.Chams:create_settings()
    Menu._VisualsUI.ChamsFill = Menu._VisualsUI.ChamsSettings:create_element({
        ["name"] = "Fill",
    }, {
        ["colorpicker"] = {
            ["default_color"] = themeAccent,
            ["default_transparency"] = 0.70,
            ["color_flag"] = "visual_esp_chams_fill_color",
            ["transparency_flag"] = "visual_esp_chams_fill_transparency",
        },
    })
    Menu._VisualsUI.ChamsOutline = Menu._VisualsUI.ChamsSettings:create_element({
        ["name"] = "Outline",
    }, {
        ["colorpicker"] = {
            ["default_color"] = Color3.fromRGB(0, 0, 0),
            ["default_transparency"] = 0.80,
            ["color_flag"] = "visual_esp_chams_outline_color",
            ["transparency_flag"] = "visual_esp_chams_outline_transparency",
        },
    })

    -- Material changes the rendered material/texture treatment only. Player fade is
    -- intentionally separate so Transparency can preserve the avatar's normal look.
    Menu._VisualsUI.Material = ESPSection:create_element({
        ["name"] = "Material",
    }, {
        ["toggle"] = {
            ["default"] = false,
            ["flag"] = "visual_esp_material",
        },
        ["colorpicker"] = {
            ["default_color"] = themeAccent,
            ["default_transparency"] = 0,
            ["color_flag"] = "visual_esp_material_color",
            ["transparency_flag"] = "visual_esp_material_transparency",
        },
    })
    Menu._VisualsUI.MaterialSettings = Menu._VisualsUI.Material:create_settings()
    if Menu._VisualsUI.Material.drawings
        and Menu._VisualsUI.Material.drawings.cog_icon
    then
        Menu._VisualsUI.Material.drawings.cog_icon.Position = UDim2.new(1, -40, 0, 1)
    end
    Menu._VisualsUI.MaterialType = Menu._VisualsUI.MaterialSettings:create_element({
        ["name"] = "Material",
    }, {
        ["dropdown"] = {
            ["default"] = {"Neon"},
            ["options"] = {"Neon", "ForceField", "Transparency"},
            ["requires_one"] = true,
            ["flag"] = "visual_esp_material_type",
        },
    })

    -- Transparency is a Material mode, not a separate toggle. The amount slider
    -- is only visible while "Transparency" is selected in the Material dropdown.
    Menu._VisualsUI.TransparencyAmount = Menu._VisualsUI.MaterialSettings:create_element({
        ["name"] = "Transparency",
    }, {
        ["slider"] = {
            ["default"] = 70,
            ["flag"] = "visual_esp_transparency_percent",
            ["min"] = 0,
            ["max"] = 100,
            ["decimals"] = 0,
            ["suffix"] = "%",
        },
    })

    -- Local Particle Aura: ported from the supplied source and scoped to the
    -- local character. Its default color follows the Silent UI accent.
    Menu._VisualsUI.LocalParticleAura = Menu._VisualsUI.Local:create_element({
        ["name"] = "Particle Aura",
    }, {
        ["toggle"] = {
            ["default"] = false,
            ["flag"] = "local_particle_aura",
        },
    })
    Menu._VisualsUI.LocalParticleAuraSettings = Menu._VisualsUI.LocalParticleAura:create_settings()
    Menu._VisualsUI.LocalParticleAuraColor = Menu._VisualsUI.LocalParticleAuraSettings:create_element({
        ["name"] = "Color",
    }, {
        ["colorpicker"] = {
            ["color_flag"] = "local_particle_aura_color",
            ["transparency_flag"] = "local_particle_aura_transparency",
            ["default_color"] = themeAccent,
            ["default_transparency"] = 0.2,
        },
    })
    Menu._VisualsUI.LocalParticleAuraParticle = Menu._VisualsUI.LocalParticleAuraSettings:create_element({
        ["name"] = "Particle",
    }, {
        ["dropdown"] = {
            ["flag"] = "local_particle_aura_particle",
            ["default"] = {"angel"},
            ["options"] = {"starlight", "heavenly", "ribbon", "sakura", "angel", "wind", "flow", "star"},
            ["use_custom_extensions"] = {"rbxm", "rbmx"},
            ["requires_one"] = true,
        },
    })

    -- Local Material mirrors the full Visuals Material control group,
    -- but applies the selected appearance only to LocalPlayer.Character.
    Menu._VisualsUI.LocalMaterial = Menu._VisualsUI.Local:create_element({
        ["name"] = "Material",
    }, {
        ["toggle"] = {
            ["default"] = false,
            ["flag"] = "local_visual_material",
        },
        ["colorpicker"] = {
            ["default_color"] = themeAccent,
            ["default_transparency"] = 0,
            ["color_flag"] = "local_visual_material_color",
            ["transparency_flag"] = "local_visual_material_transparency",
        },
    })
    Menu._VisualsUI.LocalMaterialSettings = Menu._VisualsUI.LocalMaterial:create_settings()
    if Menu._VisualsUI.LocalMaterial.drawings
        and Menu._VisualsUI.LocalMaterial.drawings.cog_icon
    then
        Menu._VisualsUI.LocalMaterial.drawings.cog_icon.Position = UDim2.new(1, -40, 0, 1)
    end
    Menu._VisualsUI.LocalMaterialType = Menu._VisualsUI.LocalMaterialSettings:create_element({
        ["name"] = "Material",
    }, {
        ["dropdown"] = {
            ["default"] = {"Neon"},
            ["options"] = {"Neon", "ForceField", "Transparency"},
            ["requires_one"] = true,
            ["flag"] = "local_visual_material_type",
        },
    })

    -- Local Transparency is the third Local Material mode. Its slider remains
    -- local-only and appears only while that dropdown option is selected.
    Menu._VisualsUI.LocalTransparencyAmount = Menu._VisualsUI.LocalMaterialSettings:create_element({
        ["name"] = "Transparency",
    }, {
        ["slider"] = {
            ["default"] = 70,
            ["flag"] = "local_visual_transparency_percent",
            ["min"] = 0,
            ["max"] = 100,
            ["decimals"] = 0,
            ["suffix"] = "%",
        },
    })

    -- World Sound.
    --
    -- The supplied AmbienceSoundDump archive did not contain the collector's
    -- completed sounds.txt manifest, so this builds the exact same catalog
    -- directly from the live game's replicated Sound instances. Entries are
    -- intentionally displayed as 1..N only, as requested.
    Menu._WorldSoundRuntime = Menu._WorldSoundRuntime or {}
    do
        local worldSoundRuntime = Menu._WorldSoundRuntime
        local worldSoundService = game:GetService("SoundService")

        if worldSoundRuntime.descendantConnection then
            pcall(function()
                worldSoundRuntime.descendantConnection:Disconnect()
            end)
            worldSoundRuntime.descendantConnection = nil
        end

        if worldSoundRuntime.heartbeatConnection then
            pcall(function()
                worldSoundRuntime.heartbeatConnection:Disconnect()
            end)
            worldSoundRuntime.heartbeatConnection = nil
        end

        if worldSoundRuntime.player then
            pcall(function()
                worldSoundRuntime.player:Stop()
                worldSoundRuntime.player:Destroy()
            end)
            worldSoundRuntime.player = nil
        end

        if type(worldSoundRuntime.restoreMuted) == "function" then
            pcall(worldSoundRuntime.restoreMuted)
        end

        worldSoundRuntime.catalog = {}
        worldSoundRuntime.options = {}
        worldSoundRuntime.originalVolumes = setmetatable({}, {
            __mode = "k",
        })
        worldSoundRuntime.ambienceSounds =
            setmetatable({}, {
                __mode = "k",
            })

        local seenSoundIds = {}
        local worldCollectionService =
            game:GetService("CollectionService")

        -- Only the game's environmental ambience/weather layer belongs in this
        -- dropdown. Do NOT include songs, instruments, combat, UI or arbitrary
        -- looped Sounds.
        local ambienceKeywords = {
            "ambience",
            "ambienceservice",
            "ambient",
            "environment",
            "environmental",
            "exterior",
            "interior",
            "indoor",
            "outdoor",
            "outside",
            "inside",
            "weather",
            "weatherservice",
            "rain",
            "rainfall",
            "storm",
            "thunder",
            "wind",
            "windy",
            "acoustic",
            "acoustics",
            "reverb",
            "roomtone",
            "room tone",
            "soundscape",
            "soundscape",
            "atmosphere",
            "atmospheric",
        }

        local rejectKeywords = {
            "music",
            "song",
            "instrument",
            "performance",
            "radio",
            "combat",
            "attack",
            "punch",
            "hit",
            "parry",
            "block",
            "dodge",
            "footstep",
            "character",
            "voice",
            "ui",
            "button",
            "click",
            "notification",
            "basketball",
            "volleyball",
            "ball",
            "sfx",
        }

        local function containsKeyword(value, list)
            local lower =
                tostring(value or ""):lower()

            for _, keyword in ipairs(list) do
                if lower:find(
                    keyword,
                    1,
                    true
                )
                then
                    return true
                end
            end

            return false
        end

        local function instanceMetadata(instance)
            local pieces = {}

            if not instance then
                return ""
            end

            pieces[#pieces + 1] =
                tostring(instance.Name or "")
            pieces[#pieces + 1] =
                tostring(instance.ClassName or "")

            pcall(function()
                pieces[#pieces + 1] =
                    instance:GetFullName()
            end)

            pcall(function()
                for _, tag in ipairs(
                    worldCollectionService:GetTags(
                        instance
                    )
                ) do
                    pieces[#pieces + 1] =
                        tostring(tag)
                end
            end)

            pcall(function()
                for key, value in pairs(
                    instance:GetAttributes()
                ) do
                    pieces[#pieces + 1] =
                        tostring(key)
                    pieces[#pieces + 1] =
                        tostring(value)
                end
            end)

            return table.concat(pieces, " ")
        end

        local function isAmbienceWeatherSound(sound)
            if not sound
                or not sound.Parent
                or not sound:IsA("Sound")
                or sound
                    == worldSoundRuntime.player
            then
                return false
            end

            local positive = false
            local negative = false

            local current = sound
            local depth = 0

            -- Inspect the Sound plus its containing ambience/weather hierarchy.
            -- This catches generic child names such as "Sound" beneath folders
            -- like WeatherService/Rain/Exterior/Interior.
            while current
                and current ~= game
                and depth <= 7
            do
                local metadata =
                    instanceMetadata(current)

                if containsKeyword(
                    metadata,
                    ambienceKeywords
                ) then
                    positive = true
                end

                if containsKeyword(
                    metadata,
                    rejectKeywords
                ) then
                    negative = true
                end

                current = current.Parent
                depth += 1
            end

            pcall(function()
                local group =
                    sound.SoundGroup

                if group then
                    local metadata =
                        instanceMetadata(group)

                    if containsKeyword(
                        metadata,
                        ambienceKeywords
                    ) then
                        positive = true
                    end

                    if containsKeyword(
                        metadata,
                        rejectKeywords
                    ) then
                        negative = true
                    end
                end
            end)

            -- Positive ambience/weather evidence is mandatory. A generic
            -- looped Sound by itself is not enough.
            if not positive then
                return false
            end

            -- If a Sound is explicitly part of an ambience/weather hierarchy,
            -- that wins over weak generic words elsewhere in its ancestry.
            local directMetadata =
                instanceMetadata(sound)
            local directPositive =
                containsKeyword(
                    directMetadata,
                    ambienceKeywords
                )

            if negative
                and not directPositive
            then
                -- A weather/ambience parent can contain unrelated music or
                -- instrument content; keep those out.
                return false
            end

            worldSoundRuntime.ambienceSounds[
                sound
            ] = true

            return true
        end

        worldSoundRuntime.isAmbienceWeatherSound =
            isAmbienceWeatherSound

        local function normalizeSoundId(value)
            value = tostring(value or "")
            if value == "" then
                return nil
            end

            local numeric =
                value:match("rbxassetid://(%d+)")
                or value:match("rbxasset://sounds/(%d+)")
                or value:match("^(%d+)$")

            if numeric then
                return "rbxassetid://" .. numeric
            end

            if value:find("rbxasset", 1, true)
                or value:find("https://", 1, true)
                or value:find("http://", 1, true)
            then
                return value
            end

            return nil
        end

        local function addCatalogSound(sound)
            if not isAmbienceWeatherSound(sound) then
                return
            end

            local soundId =
                normalizeSoundId(
                    sound.SoundId
                )

            if not soundId
                or seenSoundIds[soundId]
            then
                return
            end

            seenSoundIds[soundId] = true

            local entry = {
                soundId = soundId,
                source = sound,
                volume = tonumber(sound.Volume) or 1,
                playbackSpeed =
                    tonumber(sound.PlaybackSpeed) or 1,
                looped = sound.Looped == true,
                name = sound.Name,
                path = "",
            }

            pcall(function()
                entry.path = sound:GetFullName()
            end)

            worldSoundRuntime.catalog[
                #worldSoundRuntime.catalog + 1
            ] = entry
        end

        -- Catalog ONLY the environmental sounds driven by the game's
        -- AmbienceService / WeatherService / interior-exterior soundscape.
        -- One initial scan only. This populates both the numeric catalog and
        -- the ambience/weather cache used by the runtime watchdog.
        for _, descendant in ipairs(
            game:GetDescendants()
        ) do
            if descendant:IsA("Sound") then
                if isAmbienceWeatherSound(
                    descendant
                ) then
                    addCatalogSound(descendant)
                end
            end
        end

        table.sort(
            worldSoundRuntime.catalog,
            function(a, b)
                local aPath =
                    tostring(a.path):lower()
                local bPath =
                    tostring(b.path):lower()

                if aPath == bPath then
                    return tostring(a.soundId)
                        < tostring(b.soundId)
                end

                return aPath < bPath
            end
        )

        -- Curated ambience list. These numbers refer to the original R24
        -- numeric dropdown ordering before filtering.
        local curatedWorldSounds = {
            [1] = "Resturant",
            [2] = "Birds 1",
            [3] = "Birds 2",
            [4] = "Night Ambience",
            [5] = "Birds 3",
            [6] = "Ambience 1",
            [7] = "Indoor rain",
            [8] = "Ambience 2",
            [10] = "Ambience 3",
            [14] = "Wind / Birds",
            [16] = "Heavy rain",
            [17] = "Ambience 4",
        }

        -- Organized by type instead of the original numeric asset order:
        -- locations -> general ambience -> birds/nature -> weather.
        local curatedWorldSoundOrder = {
            1,          -- Resturant
            4,          -- Night Ambience
            6, 8, 10, 17, -- Ambience 1-4
            2, 3, 5,    -- Birds 1-3
            14,         -- Wind / Birds
            7,          -- Indoor rain
            16,         -- Heavy rain
        }

        local originalCatalog =
            worldSoundRuntime.catalog
        worldSoundRuntime.catalog = {}
        worldSoundRuntime.options = {}
        worldSoundRuntime.optionToIndex = {}
        worldSoundRuntime.originalOptionToIndex = {}

        for _, originalIndex in ipairs(
            curatedWorldSoundOrder
        ) do
            local label =
                curatedWorldSounds[
                    originalIndex
                ]
            local entry =
                originalCatalog[
                    originalIndex
                ]

            if label and entry then
                entry.originalIndex =
                    originalIndex
                entry.label = label

                local newIndex =
                    #worldSoundRuntime.catalog + 1
                worldSoundRuntime.catalog[
                    newIndex
                ] = entry
                worldSoundRuntime.options[
                    newIndex
                ] = label
                worldSoundRuntime.optionToIndex[
                    label
                ] = newIndex
                worldSoundRuntime.originalOptionToIndex[
                    tostring(originalIndex)
                ] = newIndex
            end
        end

        -- Keep the control valid if the game's ambience set changes so much
        -- that none of the known curated entries are present.
        if #worldSoundRuntime.options == 0 then
            worldSoundRuntime.options[1] =
                "No ambience found"
        end

        worldSoundRuntime.isDefaultWorldSound =
            function(sound)
                return isAmbienceWeatherSound(
                    sound
                )
            end

        worldSoundRuntime.muteDefault =
            function(sound)
                if not worldSoundRuntime.isDefaultWorldSound(
                    sound
                ) then
                    return
                end

                if worldSoundRuntime.originalVolumes[
                    sound
                ] == nil
                then
                    worldSoundRuntime.originalVolumes[
                        sound
                    ] = sound.Volume
                end

                pcall(function()
                    sound.Volume = 0
                end)
            end

        worldSoundRuntime.muteDefaults =
            function()
                for sound in pairs(
                    worldSoundRuntime.ambienceSounds
                ) do
                    if sound
                        and sound.Parent
                    then
                        worldSoundRuntime.muteDefault(
                            sound
                        )
                    else
                        worldSoundRuntime.ambienceSounds[
                            sound
                        ] = nil
                    end
                end
            end

        worldSoundRuntime.restoreMuted =
            function()
                local previous =
                    worldSoundRuntime.originalVolumes
                worldSoundRuntime.originalVolumes =
                    setmetatable({}, {
                        __mode = "k",
                    })

                for sound, volume in pairs(
                    previous or {}
                ) do
                    if sound
                        and sound.Parent
                    then
                        pcall(function()
                            sound.Volume = volume
                        end)
                    end
                end
            end

        worldSoundRuntime.playSerial =
            tonumber(
                worldSoundRuntime.playSerial
            ) or 0

        local OVERRIDE_SOUND_NAME =
            "__SilentSolutionsWorldSound"

        local function hardStopSound(sound)
            if not sound then
                return
            end

            pcall(function()
                sound.Volume = 0
            end)
            pcall(function()
                sound.Looped = false
            end)
            pcall(function()
                sound:Pause()
            end)
            pcall(function()
                sound:Stop()
            end)
            pcall(function()
                sound.TimePosition = 0
            end)
            pcall(function()
                sound:Destroy()
            end)
        end

        worldSoundRuntime.cleanupOverrideSounds =
            function(keep)
                -- R24 keeps the override under SoundService only. Avoid a
                -- whole-DataModel scan on every watchdog tick.
                for _, child in ipairs(
                    worldSoundService:GetChildren()
                ) do
                    if child:IsA("Sound")
                        and child.Name
                            == OVERRIDE_SOUND_NAME
                        and child ~= keep
                    then
                        hardStopSound(child)
                    end
                end
            end

        worldSoundRuntime.stop =
            function()
                -- Invalidate every in-flight/deferred play request before
                -- touching the current player.
                worldSoundRuntime.playSerial += 1

                local player =
                    worldSoundRuntime.player
                worldSoundRuntime.player = nil

                hardStopSound(player)
                worldSoundRuntime.cleanupOverrideSounds(
                    nil
                )
            end

        local function normalizeSelectedIndex(value)
            if type(value) == "table" then
                value =
                    value[1]
                    or value.value
                    or value.Value
            end

            value =
                tostring(value or "")

            local byLabel =
                worldSoundRuntime.optionToIndex[
                    value
                ]
            if byLabel then
                return byLabel
            end

            -- Backward compatibility for configs made while the dropdown was
            -- still numbered with the original R24 indices.
            local byOriginalNumber =
                worldSoundRuntime.originalOptionToIndex[
                    value
                ]
            if byOriginalNumber then
                return byOriginalNumber
            end

            local numeric =
                tonumber(value)
            if numeric then
                return math.clamp(
                    math.floor(numeric),
                    1,
                    math.max(
                        1,
                        #worldSoundRuntime.catalog
                    )
                )
            end

            return 1
        end

        local function selectedIndex()
            return normalizeSelectedIndex(
                Flags.visual_world_sound_selection
            )
        end

        local function selectedVolume()
            return math.clamp(
                tonumber(
                    Flags.visual_world_sound_volume
                ) or 20,
                0,
                100
            ) / 100
        end

        worldSoundRuntime.playSelected =
            function(indexOverride)
                -- Always kill the previous override before resolving/starting
                -- the next selection. This guarantees only one ambience track
                -- can exist at a time.
                worldSoundRuntime.stop()

                if Flags.visual_world_sound
                    ~= true
                then
                    worldSoundRuntime.restoreMuted()
                    return
                end

                worldSoundRuntime.muteDefaults()

                local index =
                    indexOverride ~= nil
                    and normalizeSelectedIndex(
                        indexOverride
                    )
                    or selectedIndex()

                local entry =
                    worldSoundRuntime.catalog[index]

                if not entry then
                    return
                end

                local requestSerial =
                    worldSoundRuntime.playSerial + 1
                worldSoundRuntime.playSerial =
                    requestSerial

                local player =
                    Instance.new("Sound")
                player.Name =
                    OVERRIDE_SOUND_NAME
                player.SoundId =
                    entry.soundId
                player.Volume =
                    selectedVolume()
                player.PlaybackSpeed =
                    entry.playbackSpeed
                player.Looped = true
                player.SoundGroup = nil
                player.Parent =
                    worldSoundService

                -- A toggle-off or another selection may have happened while
                -- Roblox was creating/loading this Sound. Never allow a stale
                -- request to become audible.
                if worldSoundRuntime.playSerial
                        ~= requestSerial
                    or Flags.visual_world_sound
                        ~= true
                then
                    hardStopSound(player)
                    return
                end

                worldSoundRuntime.player =
                    player

                -- IMPORTANT: do not use SoundService:PlayLocalSound here.
                -- PlayLocalSound can create playback that is harder to own
                -- reliably across executor/client paths. A normal local Sound
                -- parented to SoundService gives us one concrete instance that
                -- Stop/Destroy always controls.
                pcall(function()
                    player:Play()
                end)

                if worldSoundRuntime.playSerial
                        ~= requestSerial
                    or Flags.visual_world_sound
                        ~= true
                then
                    worldSoundRuntime.stop()
                    return
                end

                -- Enforce singleton playback immediately after starting.
                worldSoundRuntime.cleanupOverrideSounds(
                    player
                )
            end

        worldSoundRuntime.applyConfigState =
            function()
                -- Resolve all three flags only after config loading has
                -- completed, then perform exactly one runtime transition.
                worldSoundRuntime.stop()

                if Flags.visual_world_sound
                    == true
                then
                    worldSoundRuntime.playSelected(
                        Flags.visual_world_sound_selection
                    )
                else
                    worldSoundRuntime.restoreMuted()
                end
            end

        Menu._VisualsUI.WorldSound =
            WorldSection:create_element({
                ["name"] = "Sound",
            }, {
                ["toggle"] = {
                    ["default"] = false,
                    ["flag"] =
                        "visual_world_sound",
                },
            })

        Menu._VisualsUI.WorldSoundSettings =
            Menu._VisualsUI.WorldSound:create_settings()

        Menu._VisualsUI.WorldSoundSelection =
            Menu._VisualsUI.WorldSoundSettings:create_element({
                ["name"] = "Sound",
            }, {
                ["dropdown"] = {
                    ["default"] = {"Birds 1"},
                    ["flag"] =
                        "visual_world_sound_selection",
                    ["options"] =
                        worldSoundRuntime.options,
                    ["requires_one"] = true,
                },
            })

        Menu._VisualsUI.WorldSoundVolume =
            Menu._VisualsUI.WorldSoundSettings:create_element({
                ["name"] = "Volume",
            }, {
                ["slider"] = {
                    ["default"] = 20,
                    ["flag"] =
                        "visual_world_sound_volume",
                    ["min"] = 0,
                    ["max"] = 100,
                    ["decimals"] = 0,
                    ["suffix"] = "%",
                },
            })

        Connect(
            Menu._VisualsUI.WorldSound[
                "on_toggle_change"
            ],
            function(value)
                if Menu._ConfigApplying == true then
                    return
                end

                if value == true then
                    worldSoundRuntime.playSelected()
                else
                    -- Stop immediately on toggle-off, even before any other
                    -- flag/config callbacks can run.
                    worldSoundRuntime.stop()
                    worldSoundRuntime.restoreMuted()
                end
            end
        )

        Connect(
            Menu._VisualsUI.WorldSoundSelection[
                "on_dropdown_change"
            ],
            function(value)
                if Menu._ConfigApplying == true then
                    return
                end

                -- Switching selection is a strict stop-then-play handoff.
                -- Pass the callback value directly so we do not depend on the
                -- flag table updating one frame later.
                worldSoundRuntime.stop()

                if Flags.visual_world_sound
                    == true
                then
                    worldSoundRuntime.playSelected(
                        value
                    )
                end
            end
        )

        Connect(
            Menu._VisualsUI.WorldSoundVolume[
                "on_slider_change"
            ],
            function()
                if Menu._ConfigApplying == true then
                    return
                end

                local player =
                    worldSoundRuntime.player

                if player
                    and player.Parent
                then
                    player.Volume =
                        selectedVolume()
                elseif Flags.visual_world_sound
                    == true
                then
                    worldSoundRuntime.playSelected()
                end
            end
        )

        -- Mute newly streamed weather/ambience while override is enabled.
        -- Combat/UI/music/instrument sounds are untouched.
        worldSoundRuntime.descendantConnection =
            game.DescendantAdded:Connect(
                function(descendant)
                    if not descendant:IsA("Sound") then
                        return
                    end

                    task.defer(function()
                        if not descendant
                            or not descendant.Parent
                        then
                            return
                        end

                        if not isAmbienceWeatherSound(
                            descendant
                        ) then
                            return
                        end

                        if Flags.visual_world_sound
                            == true
                        then
                            worldSoundRuntime.muteDefault(
                                descendant
                            )

                            worldSoundRuntime.cleanupOverrideSounds(
                                worldSoundRuntime.player
                            )
                        end
                    end)
                end
            )

        -- The game's ambience/weather controller can rewrite Sound.Volume or
        -- replay its source Sounds after we mute them. Re-assert the override
        -- state at a low frequency so an old/default ambience track cannot leak
        -- back in while a numbered sound is selected.
        local worldSoundHeartbeatElapsed = 0
        worldSoundRuntime.heartbeatConnection =
            game:GetService("RunService").Heartbeat:Connect(
                function(dt)
                    worldSoundHeartbeatElapsed +=
                        tonumber(dt) or 0

                    if worldSoundHeartbeatElapsed
                        < 0.25
                    then
                        return
                    end

                    worldSoundHeartbeatElapsed = 0

                    if Flags.visual_world_sound
                        == true
                    then
                        worldSoundRuntime.muteDefaults()

                        local player =
                            worldSoundRuntime.player

                        worldSoundRuntime.cleanupOverrideSounds(
                            player
                        )

                        if player
                            and player.Parent
                        then
                            local targetVolume =
                                selectedVolume()

                            if math.abs(
                                player.Volume
                                    - targetVolume
                            ) > 0.001
                            then
                                player.Volume =
                                    targetVolume
                            end

                            if not player.Playing then
                                pcall(function()
                                    player:Play()
                                end)
                            end
                        end
                    else
                        -- If a callback was missed by a config/UI edge, the
                        -- watchdog still guarantees the custom track is gone.
                        if worldSoundRuntime.player
                            or worldSoundService:FindFirstChild(
                                OVERRIDE_SOUND_NAME
                            )
                        then
                            worldSoundRuntime.stop()
                        end
                    end
                end
            )

        if Menu.on_config_loaded
            and type(
                Menu.on_config_loaded.Connect
            ) == "function"
        then
            Connect(
                Menu.on_config_loaded,
                function()
                    task.defer(function()
                        if type(
                            worldSoundRuntime.applyConfigState
                        ) == "function"
                        then
                            worldSoundRuntime.applyConfigState()
                        end
                    end)
                end
            )
        end

        if Menu._ScriptRuntime
            and type(
                Menu._ScriptRuntime.Track
            ) == "function"
        then
            Menu._ScriptRuntime:Track(
                worldSoundRuntime.descendantConnection
            )
            Menu._ScriptRuntime:Track(
                worldSoundRuntime.heartbeatConnection
            )
        end

        if Menu._ScriptRuntime
            and type(
                Menu._ScriptRuntime.AddCleanup
            ) == "function"
        then
            Menu._ScriptRuntime:AddCleanup(
                function()
                    worldSoundRuntime.stop()
                    worldSoundRuntime.restoreMuted()

                    if worldSoundRuntime.descendantConnection then
                        pcall(function()
                            worldSoundRuntime.descendantConnection:Disconnect()
                        end)
                        worldSoundRuntime.descendantConnection = nil
                    end

                    if worldSoundRuntime.heartbeatConnection then
                        pcall(function()
                            worldSoundRuntime.heartbeatConnection:Disconnect()
                        end)
                        worldSoundRuntime.heartbeatConnection = nil
                    end
                end
            )
        end

        -- Apply the current/default/config-restored state after all three
        -- controls and runtime helpers exist.
        task.defer(function()
            if type(
                worldSoundRuntime.applyConfigState
            ) == "function"
            then
                worldSoundRuntime.applyConfigState()
            end
        end)
    end

    -- World visual environment controls implemented through SilentUI only:
    -- Tint, Ambient, Saturation, Contrast, and Atmosphere.
    Menu._WorldVisualRuntime = Menu._WorldVisualRuntime or {}
    do
        local worldRuntime =
            Menu._WorldVisualRuntime
        local worldLighting =
            game:GetService("Lighting")

        local function disconnectWorldConnection(
            connection
        )
            if connection then
                pcall(function()
                    connection:Disconnect()
                end)
            end
        end

        -- Clean the previous live runtime when the script is re-executed.
        if type(worldRuntime.cleanup) == "function" then
            pcall(worldRuntime.cleanup)
        end

        worldRuntime.connections = {}
        worldRuntime.applyingAmbient = false
        worldRuntime.customAtmosphere = nil

        worldRuntime.originalAmbient =
            worldLighting.Ambient
        worldRuntime.originalOutdoorAmbient =
            worldLighting.OutdoorAmbient

        local function resolveColorCorrection()
            local effect =
                worldRuntime.colorCorrection

            if effect and effect.Parent then
                return effect
            end

            local stale =
                worldLighting:FindFirstChild(
                    "__SilentSolutionsWorldColorCorrection"
                )

            if stale
                and stale:IsA(
                    "ColorCorrectionEffect"
                )
            then
                effect = stale
            else
                if stale then
                    pcall(function()
                        stale:Destroy()
                    end)
                end

                effect =
                    Instance.new(
                        "ColorCorrectionEffect"
                    )
                effect.Name =
                    "__SilentSolutionsWorldColorCorrection"
                effect.Parent =
                    worldLighting
            end

            -- This effect belongs only to SilentSolutions. Neutral values mean
            -- disabling Tint / Saturation / Contrast never edits the game's
            -- own ColorCorrectionEffect or changes its original look.
            effect.Enabled = true
            effect.TintColor =
                Color3.new(1, 1, 1)
            effect.Saturation = 0
            effect.Contrast = 0
            effect.Brightness = 0

            worldRuntime.colorCorrection =
                effect

            return effect
        end

        local worldColorCorrection =
            resolveColorCorrection()

        local function selectedWorldColor(
            flag,
            fallback
        )
            local value =
                Flags[flag]

            if typeof(value) == "Color3" then
                return value
            end

            return fallback
        end

        local function selectedWorldNumber(
            flag,
            fallback,
            minimum,
            maximum
        )
            local value =
                tonumber(Flags[flag])

            if value == nil or value ~= value then
                value = fallback
            end

            if minimum ~= nil
                and maximum ~= nil
            then
                value =
                    math.clamp(
                        value,
                        minimum,
                        maximum
                    )
            end

            return value
        end

        worldRuntime.applyTint =
            function()
                local effect =
                    resolveColorCorrection()

                if not effect then
                    return
                end

                pcall(function()
                    effect.TintColor =
                        Flags.visual_world_tint
                            == true
                        and selectedWorldColor(
                            "visual_world_tint_color",
                            Color3.fromRGB(
                                244,
                                240,
                                255
                            )
                        )
                        or Color3.new(
                            1,
                            1,
                            1
                        )
                end)

            end

        worldRuntime.applySaturation =
            function()
                local effect =
                    resolveColorCorrection()

                if not effect then
                    return
                end

                pcall(function()
                    effect.Saturation =
                        Flags.visual_world_saturation
                            == true
                        and selectedWorldNumber(
                            "visual_world_saturation_value",
                            0.08,
                            -1,
                            1
                        )
                        or 0
                end)

            end

        worldRuntime.applyContrast =
            function()
                local effect =
                    resolveColorCorrection()

                if not effect then
                    return
                end

                pcall(function()
                    effect.Contrast =
                        Flags.visual_world_contrast
                            == true
                        and selectedWorldNumber(
                            "visual_world_contrast_value",
                            0.12,
                            -1,
                            1
                        )
                        or 0
                end)

            end

        worldRuntime.applyAmbient =
            function()
                worldRuntime.applyingAmbient =
                    true

                if Flags.visual_world_ambient
                    == true
                then
                    worldLighting.Ambient =
                        selectedWorldColor(
                            "visual_world_ambient_color",
                            worldRuntime.originalAmbient
                        )
                    worldLighting.OutdoorAmbient =
                        selectedWorldColor(
                            "visual_world_outdoor_color",
                            worldRuntime.originalOutdoorAmbient
                        )
                else
                    worldLighting.Ambient =
                        worldRuntime.originalAmbient
                    worldLighting.OutdoorAmbient =
                        worldRuntime.originalOutdoorAmbient
                end

                worldRuntime.applyingAmbient =
                    false
            end

        local function destroyWorldAtmosphere()
            local atmosphere =
                worldRuntime.customAtmosphere
            worldRuntime.customAtmosphere =
                nil

            if atmosphere then
                pcall(function()
                    atmosphere:Destroy()
                end)
            end

            local stale =
                worldLighting:FindFirstChild(
                    "__SilentSolutionsWorldAtmosphere"
                )

            if stale then
                pcall(function()
                    stale:Destroy()
                end)
            end
        end

        worldRuntime.applyAtmosphere =
            function()
                destroyWorldAtmosphere()

                if Flags.visual_world_atmosphere
                    ~= true
                then
                    return
                end

                local atmosphere =
                    Instance.new(
                        "Atmosphere"
                    )
                atmosphere.Name =
                    "__SilentSolutionsWorldAtmosphere"
                atmosphere.Color =
                    selectedWorldColor(
                        "visual_world_atmosphere_color",
                        Color3.fromRGB(
                            214,
                            220,
                            235
                        )
                    )
                atmosphere.Decay =
                    selectedWorldColor(
                        "visual_world_atmosphere_decay_color",
                        Color3.fromRGB(
                            112,
                            116,
                            128
                        )
                    )
                atmosphere.Haze =
                    selectedWorldNumber(
                        "visual_world_atmosphere_haze",
                        0.45,
                        0,
                        10
                    )
                atmosphere.Glare =
                    selectedWorldNumber(
                        "visual_world_atmosphere_glare",
                        0.12,
                        0,
                        10
                    )
                atmosphere.Offset =
                    selectedWorldNumber(
                        "visual_world_atmosphere_offset",
                        0.08,
                        0,
                        1
                    )
                atmosphere.Density =
                    selectedWorldNumber(
                        "visual_world_atmosphere_density",
                        0.22,
                        0,
                        1
                    )
                atmosphere.Parent =
                    worldLighting

                worldRuntime.customAtmosphere =
                    atmosphere
            end

        worldRuntime.applyConfigState =
            function()
                worldRuntime.applyTint()
                worldRuntime.applyAmbient()
                worldRuntime.applySaturation()
                worldRuntime.applyContrast()
                worldRuntime.applyAtmosphere()
            end

        -- The supplied implementation protects the game's real Ambient values
        -- while an override is active. Property guards reproduce that behavior
        -- without replacing Lighting's raw metatable.
        local ambientChanged =
            worldLighting:GetPropertyChangedSignal(
                "Ambient"
            ):Connect(function()
                if worldRuntime.applyingAmbient then
                    return
                end

                if Flags.visual_world_ambient
                    == true
                then
                    worldRuntime.originalAmbient =
                        worldLighting.Ambient
                    worldRuntime.applyAmbient()
                else
                    worldRuntime.originalAmbient =
                        worldLighting.Ambient
                end
            end)

        local outdoorAmbientChanged =
            worldLighting:GetPropertyChangedSignal(
                "OutdoorAmbient"
            ):Connect(function()
                if worldRuntime.applyingAmbient then
                    return
                end

                if Flags.visual_world_ambient
                    == true
                then
                    worldRuntime.originalOutdoorAmbient =
                        worldLighting.OutdoorAmbient
                    worldRuntime.applyAmbient()
                else
                    worldRuntime.originalOutdoorAmbient =
                        worldLighting.OutdoorAmbient
                end
            end)

        worldRuntime.connections[
            #worldRuntime.connections + 1
        ] = ambientChanged
        worldRuntime.connections[
            #worldRuntime.connections + 1
        ] = outdoorAmbientChanged

        -- Organized World rows. Complex controls live in their own settings
        -- popouts so the section stays compact.
        Menu._VisualsUI.WorldTint =
            WorldSection:create_element({
                ["name"] = "Tint",
            }, {
                ["toggle"] = {
