        Menu._VisualsUI.WorldContrast =
            WorldSection:create_element({
                ["name"] = "Contrast",
            }, {
                ["toggle"] = {
                    ["flag"] =
                        "visual_world_contrast",
                    ["default"] = false,
                },
                ["slider"] = {
                    ["flag"] =
                        "visual_world_contrast_value",
                    ["min"] = -1,
                    ["max"] = 1,
                    ["decimals"] = 2,
                    ["default"] = 0.12,
                },
            })

        Menu._VisualsUI.WorldAtmosphere =
            WorldSection:create_element({
                ["name"] = "Atmosphere",
            }, {
                ["toggle"] = {
                    ["flag"] =
                        "visual_world_atmosphere",
                    ["default"] = false,
                },
            })
        Menu._VisualsUI.WorldAtmosphereSettings =
            Menu._VisualsUI.WorldAtmosphere:
