        Menu._VisualsUI.WorldAtmosphereColor =
            Menu._VisualsUI.WorldAtmosphereSettings:
                create_element({
                    ["name"] = "Color",
                }, {
                    ["colorpicker"] = {
                        ["color_flag"] =
