                            ),
                        ["default_transparency"] = 0,
                    },
                })
        Menu._VisualsUI.WorldAtmosphereDecay =
            Menu._VisualsUI.WorldAtmosphereSettings:
                create_element({
                    ["name"] = "Decay",
                }, {
                    ["colorpicker"] = {
                        ["color_flag"] =
                            "visual_world_atmosphere_decay_color",
                        ["transparency_flag"] =
                            "visual_world_atmosphere_decay_transparency",
                        ["default_color"] =
                            Color3.fromRGB(
                                112,
                                116,
                                128
                            ),
                        ["default_transparency"] = 0,
                    },
                })
        Menu._VisualsUI.WorldAtmosphereHaze =
            Menu._VisualsUI.WorldAtmosphereSettings:
                create_element({
