        local function worldConfigCallback(
            callback
        )
            return function(...)
                if Menu._ConfigApplying
                    == true
                then
                    return
                end

                callback(...)
            end
        end

        Connect(
            Menu._VisualsUI.WorldTint[
                "on_toggle_change"
