                "on_color_change"
            ],
            worldConfigCallback(
                worldRuntime.applyTint
            )
        )

        Connect(
            Menu._VisualsUI.WorldAmbient[
                "on_toggle_change"
            ],
            worldConfigCallback(
                worldRuntime.applyAmbient
            )
        )
        Connect(
