            )
        )

        Connect(
            Menu._VisualsUI.WorldAtmosphere[
                "on_toggle_change"
            ],
            worldConfigCallback(
                worldRuntime.applyAtmosphere
            )
        )
        Connect(
            Menu._VisualsUI.WorldAtmosphereColor[
                "on_color_change"
            ],
            worldConfigCallback(
                worldRuntime.applyAtmosphere
            )
        )
        Connect(
            Menu._VisualsUI.WorldAtmosphereDecay[
                "on_color_change"
            ],
            worldConfigCallback(
                worldRuntime.applyAtmosphere
            )
        )

        for _, slider in ipairs({
            Menu._VisualsUI.WorldAtmosphereHaze,
            Menu._VisualsUI.WorldAtmosphereGlare,
            Menu._VisualsUI.WorldAtmosphereOffset,
            Menu._VisualsUI.WorldAtmosphereDensity,
        }) do
            Connect(
                slider["on_slider_change"],
                worldConfigCallback(
                    worldRuntime.applyAtmosphere
                )
            )
        end

        if Menu.on_config_loaded
            and type(
                Menu.on_config_loaded.Connect
            ) == "function"
        then
            Connect(
                Menu.on_config_loaded,
                function()
                    task.defer(function()
                        if type(
                            worldRuntime.applyConfigState
                        ) == "function"
                        then
                            worldRuntime.applyConfigState()
                        end
                    end)
                end
            )
        end

        worldRuntime.cleanup =
            function()
                destroyWorldAtmosphere()

                worldRuntime.applyingAmbient =
                    true
                pcall(function()
                    worldLighting.Ambient =
                        worldRuntime.originalAmbient
                    worldLighting.OutdoorAmbient =
                        worldRuntime.originalOutdoorAmbient
                end)
                worldRuntime.applyingAmbient =
                    false

                local effect =
                    worldRuntime.colorCorrection
                worldRuntime.colorCorrection =
                    nil

                if effect
                    and effect.Parent
                    and effect.Name
                        == "__SilentSolutionsWorldColorCorrection"
                then
                    pcall(function()
                        effect:Destroy()
                    end)
                end

                for index =
                    #worldRuntime.connections,
                    1,
                    -1
                do
                    disconnectWorldConnection(
                        worldRuntime.connections[
                            index
                        ]
                    )
                    worldRuntime.connections[
                        index
                    ] = nil
                end
            end

        if Menu._ScriptRuntime
            and type(
                Menu._ScriptRuntime.AddCleanup
            ) == "function"
        then
            Menu._ScriptRuntime:AddCleanup(
                worldRuntime.cleanup
            )
        end

        task.defer(function()
            if type(
                worldRuntime.applyConfigState
            ) == "function"
            then
                worldRuntime.applyConfigState()
            end
        end)
    end

    -- Particle Aura runtime. Mirrors the supplied source's attachment cloning,
    -- preset/custom particle selection, recoloring, cleanup, and respawn behavior.
    Menu._LocalParticleAuraRuntime = Menu._LocalParticleAuraRuntime or {}
    do
        local auraRuntime = Menu._LocalParticleAuraRuntime
        local auraPlayers = game:GetService("Players")
        local auraLocalPlayer = auraPlayers.LocalPlayer

        if auraRuntime.characterConnection then
            pcall(function()
                auraRuntime.characterConnection:Disconnect()
            end)
            auraRuntime.characterConnection = nil
        end

        if type(auraRuntime.clear) == "function" then
            pcall(auraRuntime.clear)
        end
        if type(auraRuntime.destroyTemplates) == "function" then
            pcall(auraRuntime.destroyTemplates)
        end

        auraRuntime.live = {}
        auraRuntime.templates = {}
        auraRuntime.assetIds = {
            starlight = "rbxassetid://134645216613107",
            heavenly = "rbxassetid://139300897520961",
            ribbon = "rbxassetid://132069507632161",
            sakura = "rbxassetid://81755778619404",
            angel = "rbxassetid://97658130917593",
            wind = "rbxassetid://80694081850877",
            flow = "rbxassetid://119913533725648",
            star = "rbxassetid://73754563740680",
        }
        auraRuntime.allowedBodyParts = {
            Head = true,
            UpperTorso = true,
            LowerTorso = true,
            LeftUpperArm = true,
            LeftLowerArm = true,
            LeftHand = true,
            RightUpperArm = true,
            RightLowerArm = true,
            RightHand = true,
            LeftUpperLeg = true,
            LeftLowerLeg = true,
            LeftFoot = true,
            RightUpperLeg = true,
            RightLowerLeg = true,
            RightFoot = true,
            HumanoidRootPart = true,
        }

        auraRuntime.notify = function(message)
            if type(Menu.new_notification) == "function" then
                pcall(Menu.new_notification, tostring(message or ""), 3, 3)
            end
        end

        auraRuntime.clear = function()
            local live = auraRuntime.live or {}
            for index = #live, 1, -1 do
                local object = live[index]
                live[index] = nil
                if object then
                    pcall(function()
                        object:Destroy()
                    end)
                end
            end
        end

        auraRuntime.destroyTemplates = function()
            for name, object in pairs(auraRuntime.templates or {}) do
                auraRuntime.templates[name] = nil
                if object then
                    pcall(function()
                        object:Destroy()
                    end)
                end
            end
        end

        auraRuntime.applyAppearance = function(root)
            if not root then
                return
            end

            -- Preserve every preset's authored Transparency NumberSequence. The
            -- supplied aura implementation recolors lights/particles/beams/trails
            -- but does not flatten their transparency curves. Replacing those
            -- curves with one constant value makes effects such as heavenly/angel
            -- render as large solid light columns instead of their intended falloff.
            local color = colorFlag(
                "local_particle_aura_color",
                themeAccent
            )
            local colorSequence = ColorSequence.new(color)

            local function applyOne(object)
                if not object then
                    return
                end
                local className = object.ClassName
                if className == "PointLight" then
                    object.Color = color
                elseif className == "ParticleEmitter"
                    or className == "Beam"
                    or className == "Trail"
                then
                    object.Color = colorSequence
                end
            end

            applyOne(root)
            for _, object in ipairs(root:GetDescendants()) do
                applyOne(object)
            end
        end

        auraRuntime.loadPreset = function(name)
            name = tostring(name or "angel"):lower()
            local existing = auraRuntime.templates[name]
            if existing then
                return existing
            end
            local assetId = auraRuntime.assetIds[name]
            if not assetId then
                return nil
            end
            local ok, objects = pcall(game.GetObjects, game, assetId)
            local object = ok and type(objects) == "table" and objects[1] or nil
            if object then
                auraRuntime.applyAppearance(object)
                auraRuntime.templates[name] = object
            end
            return object
        end

        auraRuntime.validateCustom = function(object)
            if not object then
                return false
            end
            for _, child in ipairs(object:GetChildren()) do
                if not child:IsA("BasePart") then
                    auraRuntime.notify("invalid part " .. tostring(child.Name) .. " found in asset")
                    return false
                end
                if not auraRuntime.allowedBodyParts[child.Name] then
                    auraRuntime.notify("invalid body part " .. tostring(child.Name) .. " found in asset")
                    return false
                end
            end
            return true
        end

        auraRuntime.loadCustom = function(name)
            local cleanName = tostring(name or "")
            if cleanName == "" then
                return nil
            end
            local existing = auraRuntime.templates[cleanName]
            if existing then
                return existing
            end
            if type(isfile) ~= "function" or type(getcustomasset) ~= "function" then
                return nil
            end

            local root = tostring(Menu.storage_root or "SilentSolutions/Gakuran")
            local path = root .. "/custom/" .. cleanName
            if not isfile(path) then
                return nil
            end

            local okAsset, asset = pcall(getcustomasset, path)
            if not okAsset or not asset then
                return nil
            end
            local okObjects, objects = pcall(game.GetObjects, game, asset)
            local object = okObjects and type(objects) == "table" and objects[1] or nil
            if not object then
                return nil
            end
            if not auraRuntime.validateCustom(object) then
                pcall(function()
                    object:Destroy()
                end)
                return nil
            end

            auraRuntime.applyAppearance(object)
            auraRuntime.templates[cleanName] = object
            return object
        end

        auraRuntime.selectedName = function()
            local selected =
                Flags.local_particle_aura_particle
            local depth = 0

            while type(selected) == "table"
                and depth < 6
            do
                selected =
                    selected[1]
                    or selected.value
                    or selected.Value
                    or selected.name
                    or selected.Name
                depth += 1
            end

            selected =
                tostring(selected or "angel")

            if selected == "" then
                selected = "angel"
            end

            local lower =
                selected:lower()

            if auraRuntime.assetIds[lower] then
                return lower
            end

            return selected
        end

        auraRuntime.selectedTemplate = function()
            local name = auraRuntime.selectedName()
            return auraRuntime.loadPreset(name)
                or auraRuntime.loadCustom(name)
                or auraRuntime.loadPreset("angel")
        end

        auraRuntime.attach = function(character)
            auraRuntime.clear()
            if Flags.local_particle_aura ~= true then
                return
            end
            character = character or auraLocalPlayer.Character
            if not character or not character.Parent then
                return
            end

            local rootPart = character:FindFirstChild("HumanoidRootPart")
                or character:WaitForChild("HumanoidRootPart", 5)
            if not rootPart or Flags.local_particle_aura ~= true then
                return
            end

            local template = auraRuntime.selectedTemplate()
            if not template then
                return
            end
            auraRuntime.applyAppearance(template)

            local clone = template:Clone()
            for _, part in ipairs(clone:GetChildren()) do
                local localPart = character:FindFirstChild(part.Name)
                if localPart and localPart:IsA("BasePart") then
                    for _, child in ipairs(part:GetChildren()) do
                        child.Name = "\0\0"
                        child.Parent = localPart
                        auraRuntime.live[#auraRuntime.live + 1] = child
                        auraRuntime.applyAppearance(child)
                    end
                end
                pcall(function()
                    part:Destroy()
                end)
            end
            pcall(function()
                clone:Destroy()
            end)
        end

        auraRuntime.refreshAppearance = function()
            for _, template in pairs(auraRuntime.templates) do
                auraRuntime.applyAppearance(template)
            end
            for _, object in ipairs(auraRuntime.live) do
                if object and object.Parent then
                    auraRuntime.applyAppearance(object)
                end
            end
        end

        -- Preload the same eight presets as the supplied implementation.
        for name in pairs(auraRuntime.assetIds) do
            auraRuntime.loadPreset(name)
        end

        auraRuntime.disconnectCharacter =
            function()
                if auraRuntime.characterConnection then
                    pcall(function()
                        auraRuntime.characterConnection:Disconnect()
                    end)
                    auraRuntime.characterConnection = nil
                end
            end

        auraRuntime.applyConfigState =
            function()
                auraRuntime.clear()
                auraRuntime.disconnectCharacter()

                if Flags.local_particle_aura
                    ~= true
                then
                    return
                end

                task.spawn(
                    auraRuntime.attach,
                    auraLocalPlayer.Character
                )

                auraRuntime.characterConnection =
                    auraLocalPlayer.CharacterAdded:Connect(
                        function(character)
                            task.spawn(function()
                                auraRuntime.attach(
                                    character
                                )
                            end)
                        end
                    )

                if Menu._ScriptRuntime
                    and type(
                        Menu._ScriptRuntime.Track
                    ) == "function"
                then
                    Menu._ScriptRuntime:Track(
                        auraRuntime.characterConnection
                    )
                end
            end

        Connect(Menu._VisualsUI.LocalParticleAura["on_toggle_change"], function()
            if Menu._ConfigApplying == true then
                return
            end

            auraRuntime.applyConfigState()
        end)

        Connect(Menu._VisualsUI.LocalParticleAuraParticle["on_dropdown_change"], function()
            if Menu._ConfigApplying == true then
                return
            end

            if Flags.local_particle_aura == true then
                task.spawn(
                    auraRuntime.attach,
                    auraLocalPlayer.Character
                )
            end
        end)

        bindColor(
            Menu._VisualsUI.LocalParticleAuraColor,
            "local_particle_aura_color",
            "local_particle_aura_transparency",
            themeAccent,
            0.2,
            function()
                auraRuntime.refreshAppearance()
            end
        )

        if Menu.on_config_loaded
            and type(
                Menu.on_config_loaded.Connect
            ) == "function"
        then
            Connect(
                Menu.on_config_loaded,
                function()
                    task.defer(function()
                        if type(
                            auraRuntime.applyConfigState
                        ) == "function"
                        then
                            auraRuntime.applyConfigState()
                        end
                    end)
                end
            )
        end

        -- Apply defaults/current flags once after the runtime and controls
        -- exist. Config loading will re-apply once more from on_config_loaded.
        task.defer(function()
            if type(
                auraRuntime.applyConfigState
            ) == "function"
            then
                auraRuntime.applyConfigState()
            end
        end)

        if Menu._ScriptRuntime and type(Menu._ScriptRuntime.AddCleanup) == "function" then
            Menu._ScriptRuntime:AddCleanup(function()
                auraRuntime.clear()
                if type(
                    auraRuntime.disconnectCharacter
                ) == "function"
                then
                    auraRuntime.disconnectCharacter()
                end
                auraRuntime.destroyTemplates()
            end)
        end
    end

