    -- Material is independent from Highlight Chams and the 2D ESP renderer.
    -- It mirrors the supplied source lifecycle while restoring exact client-side
    -- appearance values rather than assuming every avatar started as Plastic.
    Menu._MaterialVisualRuntime = Menu._MaterialVisualRuntime or {}
    do
        local materialRuntime = Menu._MaterialVisualRuntime
        local materialRunService = game:GetService("RunService")
        local materialWorkspace = game:GetService("Workspace")
        local materialPlayers = game:GetService("Players")
        local materialLocalPlayer = materialPlayers.LocalPlayer

        if materialRuntime.connection then
            pcall(function()
                materialRuntime.connection:Disconnect()
            end)
            materialRuntime.connection = nil
        end

        if type(materialRuntime.restoreAll) == "function" then
            pcall(materialRuntime.restoreAll)
        end

        materialRuntime.states = {}
        materialRuntime.accumulator = 0
        materialRuntime.enabled = Flags.visual_esp_material == true
            and tostring(type(Flags.visual_esp_material_type) == "table"
                and Flags.visual_esp_material_type[1]
                or Flags.visual_esp_material_type or "Neon"):lower() ~= "transparency"
        materialRuntime.localEnabled = Flags.local_visual_material == true
            and tostring(type(Flags.local_visual_material_type) == "table"
                and Flags.local_visual_material_type[1]
                or Flags.local_visual_material_type or "Neon"):lower() ~= "transparency"

        local bodyPartNames = {
            Head = true,
            UpperTorso = true,
            LowerTorso = true,
            LeftUpperArm = true,
            LeftLowerArm = true,
            LeftHand = true,
            RightUpperArm = true,
            RightLowerArm = true,
            RightHand = true,
            LeftUpperLeg = true,
            LeftLowerLeg = true,
            LeftFoot = true,
            RightUpperLeg = true,
            RightLowerLeg = true,
            RightFoot = true,
            Torso = true,
            ["Left Arm"] = true,
            ["Right Arm"] = true,
            ["Left Leg"] = true,
            ["Right Leg"] = true,
        }

        materialRuntime.stateEnabled = function(state)
            if not state then
                return false
            end
            if state.localScope == true then
                return materialRuntime.localEnabled == true
            end
            return materialRuntime.enabled == true
        end

        materialRuntime.lastMaterialName = materialRuntime.lastMaterialName or "Neon"
        materialRuntime.lastLocalMaterialName = materialRuntime.lastLocalMaterialName or "Neon"

        local function selectedMaterialType(state)
            local localScope = state and state.localScope == true
            local value = localScope
                and Flags.local_visual_material_type
                or Flags.visual_esp_material_type
            if type(value) == "table" then
                value = value[1]
            end

            local lastKey = localScope and "lastLocalMaterialName" or "lastMaterialName"
            local normalized = tostring(value or "Neon"):lower()
            if normalized == "forcefield" then
                materialRuntime[lastKey] = "ForceField"
            elseif normalized == "neon" then
                materialRuntime[lastKey] = "Neon"
            end

            return tostring(materialRuntime[lastKey] or "Neon"):lower() == "forcefield"
                and Enum.Material.ForceField
                or Enum.Material.Neon
        end

        local function currentMaterialColor(state)
            local value = state and state.localScope == true
                and Flags.local_visual_material_color
                or Flags.visual_esp_material_color
            return typeof(value) == "Color3"
                and value
                or themeAccent
        end

        local function materialSignature(material, color)
            return tostring(material)
                .. "|" .. tostring(color)
        end

        local function isInsideTool(object, character)
            local current = object
            while current and current ~= character do
                if current:IsA("Tool") then
                    return true
                end
                current = current.Parent
            end
            return false
        end

        local function findAccoutrementAncestor(object, character)
            local current = object
            while current and current ~= character do
                if current:IsA("Accessory") or current:IsA("Accoutrement") then
                    return current
                end
                current = current.Parent
            end
            return nil
        end

        local function classifyTargetPart(state, object)
            if not object then
                return nil, false, false, nil
            end

            local part = object:IsA("BasePart")
                and object
                or object:FindFirstAncestorWhichIsA("BasePart")

            if not part
                or not part:IsDescendantOf(state.character)
                or part.Name == "HumanoidRootPart"
                or isInsideTool(part, state.character)
            then
                return nil, false, false, nil
            end

            local isBody = part.Parent == state.character
                and bodyPartNames[part.Name] == true
            local accessory = findAccoutrementAncestor(part, state.character)
            local isAccessory = accessory ~= nil

            if not isBody and not isAccessory then
                return nil, false, false, nil
            end

            return part, isBody, isAccessory, accessory
        end

        local function getObjectMaps(state, object)
            local originals = state.originals[object]
            if not originals then
                originals = {}
                state.originals[object] = originals
            end

            local forced = state.forced[object]
            if not forced then
                forced = {}
                state.forced[object] = forced
            end

            return originals, forced
        end

        local function forceProperty(state, object, property, value)
            if not object or not object.Parent then
                return
            end

            local originals, forced = getObjectMaps(state, object)
            local ok, current = pcall(function()
                return object[property]
            end)
            if not ok then
                return
            end

            -- Snapshot once. Never replace the original with a value observed while
            -- Material is active; Gakuran's appearance updater and our own enforcement can
            -- otherwise turn a Neon/ForceField value into the value restored on disable.
            if originals[property] == nil then
                originals[property] = current
            end

            forced[property] = value
            if current ~= value then
                pcall(function()
                    object[property] = value
                end)
            end
        end

        local function applyObject(state, object, material, color)
            if not object or not object.Parent then
                return
            end

            if object:IsA("BasePart") then
                local part, isBody, isAccessory, accessory = classifyTargetPart(state, object)
                if part ~= object then
                    return
                end

                local targetMaterial = isBody and object.Name == "Head"
                    and Enum.Material.ForceField
                    or material

                forceProperty(state, object, "MaterialVariant", "")
                forceProperty(state, object, "Material", targetMaterial)
                forceProperty(state, object, "Color", color)
                forceProperty(state, object, "Reflectance", 0)

                if object:IsA("MeshPart") then
                    forceProperty(state, object, "TextureID", "")
                end

            elseif object:IsA("SpecialMesh") then
                local _, isBody, isAccessory = classifyTargetPart(state, object)
                if isBody or isAccessory then
                    forceProperty(state, object, "TextureId", "")
                    forceProperty(state, object, "VertexColor", Vector3.new(1, 1, 1))
                end

            elseif object:IsA("SurfaceAppearance") then
                local _, isBody, isAccessory = classifyTargetPart(state, object)
                if isBody or isAccessory then
                    forceProperty(state, object, "ColorMap", "")
                    forceProperty(state, object, "NormalMap", "")
                    forceProperty(state, object, "MetalnessMap", "")
                    forceProperty(state, object, "RoughnessMap", "")
                end

            elseif object:IsA("Texture") or object:IsA("Decal") then
                local _, _, isAccessory = classifyTargetPart(state, object)
                if isAccessory then
                    -- Gakuran hair adds a separate HairColorTexture on top of its
                    -- SpecialMesh texture. Hide every accessory overlay while Material
                    -- is active; the exact original Transparency is restored on disable.
                    forceProperty(state, object, "Transparency", 1)
                end

            elseif object:IsA("Shirt") then
                forceProperty(state, object, "ShirtTemplate", "")
            elseif object:IsA("Pants") then
                forceProperty(state, object, "PantsTemplate", "")
            elseif object:IsA("ShirtGraphic") then
                forceProperty(state, object, "Graphic", "")
            end
        end

        local function restoreCharacter(character)
            local state = materialRuntime.states[character]
            if not state then
                return
            end

            if state.descendantConnection then
                pcall(function()
                    state.descendantConnection:Disconnect()
                end)
                state.descendantConnection = nil
            end

            -- Restore exact values captured before Material touched each object. Keep a
            -- short-lived strong copy so Gakuran cannot leave a Handle/SpecialMesh stuck in
            -- the forced state if its appearance controller writes during the same frame.
            local restoreEntries = {}
            for object, properties in pairs(state.originals) do
                if typeof(object) == "Instance" then
                    local copy = {}
                    for property, value in pairs(properties) do
                        copy[property] = value
                    end
                    restoreEntries[#restoreEntries + 1] = {object, copy}
                end
            end

            local function applyRestoreSnapshot()
                for index = 1, #restoreEntries do
                    local entry = restoreEntries[index]
                    local object = entry[1]
                    local properties = entry[2]
                    if typeof(object) == "Instance" and object.Parent then
                        for property, value in pairs(properties) do
                            pcall(function()
                                object[property] = value
                            end)
                        end
                    end
                end
            end

            applyRestoreSnapshot()
            task.defer(function()
                if not materialRuntime.stateEnabled(state)
                    or materialRuntime.states[character] == nil
                then
                    applyRestoreSnapshot()
                end
            end)
            task.delay(0.08, function()
                if not materialRuntime.stateEnabled(state)
                    or materialRuntime.states[character] == nil
                then
                    applyRestoreSnapshot()
                end
            end)
            task.delay(0.25, function()
                if not materialRuntime.stateEnabled(state)
                    or materialRuntime.states[character] == nil
                then
                    applyRestoreSnapshot()
                end
            end)

            state.forced = {}
            state.originals = {}
            materialRuntime.states[character] = nil
        end

        materialRuntime.restoreCharacter = restoreCharacter
        materialRuntime.restoreAll = function()
            local characters = {}
            for character in pairs(materialRuntime.states) do
                characters[#characters + 1] = character
            end
            for index = 1, #characters do
                restoreCharacter(characters[index])
            end
        end

        local function ensureState(character)
            local state = materialRuntime.states[character]
            if state then
                return state
            end

            state = {
                character = character,
                localScope = character == materialLocalPlayer.Character,
                originals = {},
                forced = {},
                signature = nil,
                nextEnforceAt = 0,
                descendantConnection = nil,
            }
            materialRuntime.states[character] = state

            state.descendantConnection = character.DescendantAdded:Connect(function(object)
                -- Gakuran populates Accessory Handles/SpecialMeshes immediately after
                -- parenting. A short delay captures their real TextureId/overlay state
                -- before forcing the selected Material.
                task.delay(0.10, function()
                    if materialRuntime.states[character] ~= state
                        or not materialRuntime.stateEnabled(state)
                        or not character.Parent
                    then
                        return
                    end

                    local material = selectedMaterialType(state)
                    local color = currentMaterialColor(state)

                    applyObject(state, object, material, color)
                    local ok, descendants = pcall(function()
                        return object:GetDescendants()
                    end)
                    if ok then
                        for _, nested in ipairs(descendants) do
                            applyObject(state, nested, material, color)
                        end
                    end
                end)
            end)

            return state
        end

        local function reassertForcedMaterialState(state)
            for object, properties in pairs(state.forced) do
                if typeof(object) == "Instance" and object.Parent then
                    for property, desired in pairs(properties) do
                        local ok, current = pcall(function()
                            return object[property]
                        end)
                        if ok and current ~= desired then
                            pcall(function()
                                object[property] = desired
                            end)
                        end
                    end
                end
            end
        end

        local function applyCharacter(character, forceScan)
            if not character or not character.Parent then
                return
            end

            local state = ensureState(character)
            local material = selectedMaterialType(state)
            local color = currentMaterialColor(state)
            local signature = materialSignature(material, color)
            local now = os.clock()
            local signatureChanged = state.signature ~= signature

            -- Scan the character tree once. After that, color/material changes only touch
            -- objects already owned by Material; DescendantAdded handles new cosmetics.
            -- This avoids repeated GetDescendants allocations while dragging color controls
            -- or standing inside crowded groups.
            if state.signature == nil then
                state.signature = signature
                state.nextEnforceAt = now + 0.35
                for _, object in ipairs(character:GetDescendants()) do
                    applyObject(state, object, material, color)
                end
                return
            end

            if signatureChanged or forceScan == true then
                state.signature = signature
                state.nextEnforceAt = now + 0.35
                local ownedObjects = {}
                for object in pairs(state.originals) do
                    ownedObjects[#ownedObjects + 1] = object
                end
                for index = 1, #ownedObjects do
                    applyObject(state, ownedObjects[index], material, color)
                end
                return
            end

            if now < (tonumber(state.nextEnforceAt) or 0) then
                return
            end

            state.nextEnforceAt = now + 0.35
            reassertForcedMaterialState(state)
        end

        materialRuntime.applyCharacter = applyCharacter
        materialRuntime.refresh = function(forceScan)
            if materialRuntime.enabled ~= true
                and materialRuntime.localEnabled ~= true
            then
                materialRuntime.restoreAll()
                return
            end

            local activeCharacters = {}

            -- Local Material uses the same material/texture/color enforcement as the
            -- Visuals Material control, but owns only LocalPlayer.Character.
            if materialRuntime.localEnabled == true then
                local localCharacter = materialLocalPlayer.Character
                if localCharacter and localCharacter.Parent then
                    activeCharacters[localCharacter] = true
                    applyCharacter(localCharacter, forceScan)
                end
            end

            if materialRuntime.enabled == true then
                local camera = materialWorkspace.CurrentCamera
                if camera then
                    local cameraPosition = camera.CFrame.Position
                    local maxDistance = tonumber(ESPTable and ESPTable.Distance) or 100

                    -- Do not use HasAppearanceLoaded in Gakuran. The dump reports false while
                    -- the complete managed accessory tree is already present.
                    for _, player in ipairs(materialPlayers:GetPlayers()) do
                        if player ~= materialLocalPlayer then
                            local character = player.Character
                            local root = character
                                and (character:FindFirstChild("HumanoidRootPart")
                                    or character.PrimaryPart)
                            local inRange = character
                                and character.Parent
                                and root
                                and root.Parent
                                and (cameraPosition - root.Position).Magnitude <= maxDistance

                            if inRange then
                                activeCharacters[character] = true
                                applyCharacter(character, forceScan)
                            elseif character then
                                restoreCharacter(character)
                            end
                        end
                    end
                end
            end

            local stale = {}
            for character in pairs(materialRuntime.states) do
                if not activeCharacters[character] then
                    stale[#stale + 1] = character
                end
            end
            for index = 1, #stale do
                restoreCharacter(stale[index])
            end
        end

        materialRuntime.connection = materialRunService.Heartbeat:Connect(function(deltaTime)
            if materialRuntime.enabled ~= true
                and materialRuntime.localEnabled ~= true
                and next(materialRuntime.states) == nil
            then
                materialRuntime.accumulator = 0
                return
            end

            materialRuntime.accumulator = (materialRuntime.accumulator or 0)
                + math.max(tonumber(deltaTime) or 0, 0)
            if materialRuntime.accumulator < 0.18 then
                return
            end
            materialRuntime.accumulator = materialRuntime.accumulator % 0.18
            materialRuntime.refresh(false)
        end)

        if Menu._ScriptRuntime and type(Menu._ScriptRuntime.Track) == "function" then
            Menu._ScriptRuntime:Track(materialRuntime.connection)
        end
        if Menu._ScriptRuntime and type(Menu._ScriptRuntime.AddCleanup) == "function" then
            Menu._ScriptRuntime:AddCleanup(function()
                materialRuntime.enabled = false
                materialRuntime.localEnabled = false
                if type(materialRuntime.restoreAll) == "function" then
                    materialRuntime.restoreAll()
                end
                if materialRuntime.connection then
                    pcall(function()
                        materialRuntime.connection:Disconnect()
                    end)
                    materialRuntime.connection = nil
                end
            end)
        end
    end

    -- Material is a single three-mode control: Neon, ForceField, or Transparency.
    -- The master Material checkbox enables whichever dropdown mode is selected.
    Menu._syncVisualMaterialMode = function(localScope)
        local isLocal = localScope == true
        local masterEnabled = isLocal
            and Flags.local_visual_material == true
            or (not isLocal and Flags.visual_esp_material == true)
        local selected = isLocal
            and Flags.local_visual_material_type
            or Flags.visual_esp_material_type
        if type(selected) == "table" then
            selected = selected[1]
        end
        local transparencySelected = tostring(selected or "Neon"):lower() == "transparency"

        local materialRuntime = Menu._MaterialVisualRuntime
        if materialRuntime then
            if isLocal then
                materialRuntime.localEnabled = masterEnabled and not transparencySelected
            else
                materialRuntime.enabled = masterEnabled and not transparencySelected
            end
            if type(materialRuntime.refresh) == "function" then
                materialRuntime.refresh(true)
            end
        end

        local transparencyRuntime = Menu._TransparencyVisualRuntime
        if transparencyRuntime then
            if isLocal then
                transparencyRuntime.localEnabled = masterEnabled and transparencySelected
                if not transparencyRuntime.localEnabled
                    and type(transparencyRuntime.restoreScope) == "function"
                then
                    transparencyRuntime.restoreScope(true)
                end
            else
                transparencyRuntime.enabled = masterEnabled and transparencySelected
                if not transparencyRuntime.enabled
                    and type(transparencyRuntime.restoreScope) == "function"
                then
                    transparencyRuntime.restoreScope(false)
                end
            end
            if type(transparencyRuntime.refresh) == "function" then
                transparencyRuntime.refresh(true)
            end
        end

        local slider = isLocal
            and Menu._VisualsUI.LocalTransparencyAmount
            or Menu._VisualsUI.TransparencyAmount
        if slider and type(slider.set_visible) == "function" then
            slider:set_visible(transparencySelected)
        end
    end

    Connect(Menu._VisualsUI.Material["on_toggle_change"], function()
        Menu._syncVisualMaterialMode(false)
    end)

    Connect(Menu._VisualsUI.LocalMaterial["on_toggle_change"], function()
        Menu._syncVisualMaterialMode(true)
    end)

    Connect(Menu._VisualsUI.MaterialType["on_dropdown_change"], function()
        Menu._syncVisualMaterialMode(false)
    end)

    Connect(Menu._VisualsUI.LocalMaterialType["on_dropdown_change"], function()
        Menu._syncVisualMaterialMode(true)
    end)

    if Menu._VisualsUI.Material["on_color_change"] then
        Connect(Menu._VisualsUI.Material["on_color_change"], function()
            local runtime = Menu._MaterialVisualRuntime
            if runtime
                and runtime.enabled == true
                and type(runtime.refresh) == "function"
            then
                runtime.refresh(true)
            end
        end)
    end

    if Menu._VisualsUI.LocalMaterial["on_color_change"] then
        Connect(Menu._VisualsUI.LocalMaterial["on_color_change"], function()
            local runtime = Menu._MaterialVisualRuntime
            if runtime
                and runtime.localEnabled == true
                and type(runtime.refresh) == "function"
            then
                runtime.refresh(true)
            end
        end)
    end

    -- Standalone player transparency. LocalTransparencyModifier preserves each
    -- character's normal materials, meshes, textures and colors and only fades the
    -- client-side render. This deliberately does not share Material's restore state.
    Menu._TransparencyVisualRuntime = Menu._TransparencyVisualRuntime or {}
    do
        local transparencyRuntime = Menu._TransparencyVisualRuntime
        local transparencyRunService = game:GetService("RunService")
        local transparencyWorkspace = game:GetService("Workspace")
        local transparencyPlayers = game:GetService("Players")
        local transparencyLocalPlayer = transparencyPlayers.LocalPlayer

        if transparencyRuntime.connection then
            pcall(function()
                transparencyRuntime.connection:Disconnect()
            end)
            transparencyRuntime.connection = nil
        end
        if type(transparencyRuntime.restoreAll) == "function" then
            pcall(transparencyRuntime.restoreAll)
        end

        transparencyRuntime.states = {}
        transparencyRuntime.accumulator = 0
        transparencyRuntime.enabled = Flags.visual_esp_material == true
            and tostring(type(Flags.visual_esp_material_type) == "table"
                and Flags.visual_esp_material_type[1]
                or Flags.visual_esp_material_type or "Neon"):lower() == "transparency"
        transparencyRuntime.localEnabled = Flags.local_visual_material == true
            and tostring(type(Flags.local_visual_material_type) == "table"
                and Flags.local_visual_material_type[1]
                or Flags.local_visual_material_type or "Neon"):lower() == "transparency"

        local function transparencyAmount(state)
            local value = state and state.localScope == true
                and Flags.local_visual_transparency_percent
                or Flags.visual_esp_transparency_percent
            return math.clamp(
                (tonumber(value) or 70) / 100,
                0,
                1
            )
        end

        local function scopeEnabled(state)
            return state and state.localScope == true
                and transparencyRuntime.localEnabled == true
                or state and state.localScope ~= true
                and transparencyRuntime.enabled == true
        end

        local function isTransparencyPart(character, object)
            if not object
                or not object:IsA("BasePart")
                or not object:IsDescendantOf(character)
                or object.Name == "HumanoidRootPart"
            then
                return false
            end

            local current = object
            while current and current ~= character do
                if current:IsA("Tool") then
                    return false
                end
                if current:IsA("Accessory") or current:IsA("Accoutrement") then
                    return true
                end
                current = current.Parent
            end

            return object.Parent == character
        end

        local function findTransparencyAccessory(character, object)
            local current = object
            while current and current ~= character do
                if current:IsA("Accessory") or current:IsA("Accoutrement") then
                    return current
                end
                current = current.Parent
            end
            return nil
        end

        local function rememberTransparencyProperty(state, object, property)
            local bucket = state.originals[object]
            if not bucket then
                bucket = {}
                state.originals[object] = bucket
            end
            if bucket[property] ~= nil then
                return bucket[property]
            end

            local ok, value = pcall(function()
                return object[property]
            end)
            if not ok then
                return nil
            end
            bucket[property] = value
            return value
        end

        local function forceTransparencyProperty(state, object, property, desired)
            if not object or not object.Parent then
                return
            end
            local original = rememberTransparencyProperty(state, object, property)
            if original == nil then
                return
            end
            local ok, current = pcall(function()
                return object[property]
            end)
            if ok and current ~= desired then
                pcall(function()
                    object[property] = desired
                end)
            end
        end

        local function applyTransparencyObject(state, object, amount)
            if not object or not object.Parent then
                return
            end

            if object:IsA("BasePart") then
                if not isTransparencyPart(state.character, object) then
                    return
                end

                local accessory = findTransparencyAccessory(state.character, object)
                if accessory then
                    -- Gakuran hair/accessories are Part + SpecialMesh. Their controller can
                    -- reset LocalTransparencyModifier, so own the Handle's real Transparency
                    -- instead. This preserves the original mesh/texture while making hair
                    -- obey the same 0-100 transparency control reliably.
                    local originalTransparency = rememberTransparencyProperty(
                        state, object, "Transparency"
                    )
                    if originalTransparency ~= nil then
                        local base = math.clamp(tonumber(originalTransparency) or 0, 0, 1)
                        local desired = base >= 1
                            and 1
                            or (base + ((1 - base) * amount))
                        forceTransparencyProperty(
                            state, object, "Transparency", desired
                        )
                    end
                else
                    local originalLtm = rememberTransparencyProperty(
                        state, object, "LocalTransparencyModifier"
                    )
                    if originalLtm ~= nil then
                        forceTransparencyProperty(
                            state,
                            object,
                            "LocalTransparencyModifier",
                            math.max(math.clamp(tonumber(originalLtm) or 0, 0, 1), amount)
                        )
                    end
                end

            elseif object:IsA("Texture") or object:IsA("Decal") then
                local accessory = findTransparencyAccessory(state.character, object)
                if not accessory then
                    return
                end
                local originalTransparency = rememberTransparencyProperty(
                    state, object, "Transparency"
                )
                if originalTransparency ~= nil then
                    local base = math.clamp(tonumber(originalTransparency) or 0, 0, 1)
                    local desired = base >= 1
                        and 1
                        or (base + ((1 - base) * amount))
                    forceTransparencyProperty(
                        state, object, "Transparency", desired
                    )
                end
            end
        end

        local function restoreTransparencyCharacter(character)
            local state = transparencyRuntime.states[character]
            if not state then
                return
            end

            if state.descendantConnection then
                pcall(function()
                    state.descendantConnection:Disconnect()
                end)
                state.descendantConnection = nil
            end

            local restoreEntries = {}
            for object, properties in pairs(state.originals) do
                local copy = {}
                for property, value in pairs(properties) do
                    copy[property] = value
                end
                restoreEntries[#restoreEntries + 1] = {object, copy}
            end

            local function applyRestore()
                for index = 1, #restoreEntries do
                    local entry = restoreEntries[index]
                    local object = entry[1]
                    if typeof(object) == "Instance" and object.Parent then
                        for property, value in pairs(entry[2]) do
                            pcall(function()
                                object[property] = value
                            end)
                        end
                    end
                end
            end

            applyRestore()
            transparencyRuntime.states[character] = nil

            local wasLocalScope = state.localScope == true
            task.delay(0.08, function()
                local stillEnabled = wasLocalScope
                    and transparencyRuntime.localEnabled == true
                    or (not wasLocalScope and transparencyRuntime.enabled == true)
                if not stillEnabled then
                    applyRestore()
                end
            end)
        end

        transparencyRuntime.restoreCharacter = restoreTransparencyCharacter
        transparencyRuntime.restoreAll = function()
            local characters = {}
            for character in pairs(transparencyRuntime.states) do
                characters[#characters + 1] = character
            end
            for index = 1, #characters do
                restoreTransparencyCharacter(characters[index])
            end
        end
        transparencyRuntime.restoreScope = function(localScope)
            local characters = {}
            for character, state in pairs(transparencyRuntime.states) do
                if (state.localScope == true) == (localScope == true) then
                    characters[#characters + 1] = character
                end
            end
            for index = 1, #characters do
                restoreTransparencyCharacter(characters[index])
            end
        end

        local function ensureTransparencyState(character, localScope)
            local state = transparencyRuntime.states[character]
            if state then
                return state
            end

            state = {
                character = character,
                localScope = localScope == true,
                originals = {},
                signature = nil,
                descendantConnection = nil,
            }
            transparencyRuntime.states[character] = state

            state.descendantConnection = character.DescendantAdded:Connect(function(object)
                if not scopeEnabled(state) then
                    return
                end
                task.defer(function()
                    if transparencyRuntime.states[character] ~= state
                        or not scopeEnabled(state)
                        or not character.Parent
                    then
                        return
                    end
                    local amount = transparencyAmount(state)
                    applyTransparencyObject(state, object, amount)
                    local ok, descendants = pcall(function()
                        return object:GetDescendants()
                    end)
                    if ok then
                        for _, nested in ipairs(descendants) do
                            applyTransparencyObject(state, nested, amount)
                        end
                    end
                end)
            end)

            return state
        end

        local function applyTransparencyCharacter(character, forceScan, localScope)
            if not character or not character.Parent then
                return
            end

            local state = ensureTransparencyState(character, localScope)
            local amount = transparencyAmount(state)
            local signatureChanged = state.signature ~= amount

            if state.signature == nil then
                state.signature = amount
                for _, object in ipairs(character:GetDescendants()) do
                    applyTransparencyObject(state, object, amount)
                end
                return
            end

            if signatureChanged then
                state.signature = amount
            end

            -- Reassert only objects already owned by Transparency. The initial scan plus
            -- DescendantAdded keeps this cache complete, so slider changes do not rescan
            -- every character in crowded servers.
            for object in pairs(state.originals) do
                if typeof(object) == "Instance" and object.Parent then
                    if object:IsA("BasePart")
                        or object:IsA("Texture")
                        or object:IsA("Decal")
                    then
                        applyTransparencyObject(state, object, amount)
                    end
                end
            end
        end

        transparencyRuntime.refresh = function(forceScan)
            if transparencyRuntime.enabled ~= true
                and transparencyRuntime.localEnabled ~= true
            then
                transparencyRuntime.restoreAll()
                return
            end

            local activeCharacters = {}

            if transparencyRuntime.enabled == true then
                local camera = transparencyWorkspace.CurrentCamera
                if camera then
                    local cameraPosition = camera.CFrame.Position
                    local maxDistance = tonumber(ESPTable and ESPTable.Distance) or 100

                    for _, player in ipairs(transparencyPlayers:GetPlayers()) do
                        if player ~= transparencyLocalPlayer then
                            local character = player.Character
                            local root = character
                                and (character:FindFirstChild("HumanoidRootPart") or character.PrimaryPart)
                            local inRange = character
                                and character.Parent
                                and root
                                and root.Parent
                                and (cameraPosition - root.Position).Magnitude <= maxDistance

                            if inRange then
                                activeCharacters[character] = true
                                applyTransparencyCharacter(character, forceScan, false)
                            elseif character then
                                restoreTransparencyCharacter(character)
                            end
                        end
                    end
                end
            else
                if type(transparencyRuntime.restoreScope) == "function" then
                    transparencyRuntime.restoreScope(false)
                end
            end

            if transparencyRuntime.localEnabled == true then
                local localCharacter = transparencyLocalPlayer.Character
                if localCharacter and localCharacter.Parent then
                    activeCharacters[localCharacter] = true
                    applyTransparencyCharacter(localCharacter, forceScan, true)
                end
            else
                if type(transparencyRuntime.restoreScope) == "function" then
                    transparencyRuntime.restoreScope(true)
                end
            end

            local stale = {}
            for character in pairs(transparencyRuntime.states) do
                if not activeCharacters[character] then
                    stale[#stale + 1] = character
                end
            end
            for index = 1, #stale do
                restoreTransparencyCharacter(stale[index])
            end
        end

        transparencyRuntime.connection = transparencyRunService.Heartbeat:Connect(function(deltaTime)
            if transparencyRuntime.enabled ~= true
                and transparencyRuntime.localEnabled ~= true
                and next(transparencyRuntime.states) == nil
            then
                transparencyRuntime.accumulator = 0
                return
            end

            transparencyRuntime.accumulator = (transparencyRuntime.accumulator or 0)
                + math.max(tonumber(deltaTime) or 0, 0)
            if transparencyRuntime.accumulator < 0.18 then
                return
            end
            transparencyRuntime.accumulator = transparencyRuntime.accumulator % 0.18
            transparencyRuntime.refresh(false)
        end)

        if Menu._ScriptRuntime and type(Menu._ScriptRuntime.Track) == "function" then
            Menu._ScriptRuntime:Track(transparencyRuntime.connection)
        end
        if Menu._ScriptRuntime and type(Menu._ScriptRuntime.AddCleanup) == "function" then
            Menu._ScriptRuntime:AddCleanup(function()
                transparencyRuntime.enabled = false
                transparencyRuntime.localEnabled = false
                if type(transparencyRuntime.restoreAll) == "function" then
                    transparencyRuntime.restoreAll()
                end
                if transparencyRuntime.connection then
                    pcall(function()
                        transparencyRuntime.connection:Disconnect()
                    end)
                    transparencyRuntime.connection = nil
                end
            end)
        end
    end

    Connect(Menu._VisualsUI.TransparencyAmount["on_slider_change"], function()
        local runtime = Menu._TransparencyVisualRuntime
        if runtime and runtime.enabled == true
            and type(runtime.refresh) == "function"
        then
            runtime.refresh(true)
        end
    end)

    Connect(Menu._VisualsUI.LocalTransparencyAmount["on_slider_change"], function()
        local runtime = Menu._TransparencyVisualRuntime
        if runtime and runtime.localEnabled == true
            and type(runtime.refresh) == "function"
        then
            runtime.refresh(true)
        end
    end)

    -- Apply saved/default dropdown modes after both material runtimes exist and keep
    -- the Transparency amount rows hidden for Neon / ForceField.
    Menu._syncVisualMaterialMode(false)
    Menu._syncVisualMaterialMode(true)

    Connect(Menu._VisualsUI.Chams["on_toggle_change"], function(v)
        local enabled =
            v == true

        ESPTable.Chams.Enabled =
            enabled

        if ESP then
            ESP.ChamsEnableEpoch =
                enabled
                and os.clock()
                or 0
            ESP.ChamsEnableNextAt =
                enabled
                and 0
                or ESP.ChamsEnableNextAt
            ESP.ChamsCreateNextAt =
                enabled
                and os.clock()
                or ESP.ChamsCreateNextAt
            ESP.ChamsCreateAllowed = false

            if not enabled and type(ESP.ChamsPool) == "table" then
                for index = 1, #ESP.ChamsPool do
                    local Entry = ESP.ChamsPool[index]
