        local materialRuntime = Menu._MaterialVisualRuntime
        if materialRuntime and type(materialRuntime.refresh) == "function" then
            materialRuntime.refresh()
        end

        if ESP then
            -- Force both renderers to observe the new range immediately.
            ESP.ChamsAccumulator = 0.050
            for _, data in pairs(ESP.Cache or {}) do
                data.NextESPUpdateAt = 0

                local objects = data and data.Objects
                local root = data and data.RootPart
                local currentCamera = Workspace.CurrentCamera
                if objects
                    and objects.Chams
                    and root
                    and root.Parent
                    and currentCamera
                    and (currentCamera.CFrame.Position - root.Position).Magnitude
                        > distanceLimit
                then
                    ESP:ReleaseChams(data)
                end
            end
        end
    end)
