                15,
                240
            )

        if ESP then
            ESP.TargetFPS =
                value
            ESP.RenderInterval =
                1 / value
            ESP.RenderAccumulator =
                0

            for _, data in pairs(ESP.Cache or {}) do
                data.NextESPUpdateAt = 0
            end
        end
    end)

