local autoParryDebugUi = {
    statusSerial = 0,
    accuracySamples = 0,
    accuracyHits = 0,
    lastErrorMs = nil,
    pendingParries = {},
    recentServerAccuracy = {},
    pendingSuccessfulParries = {},
    lastSuccessAt = 0,
    statusText = "--",
    accuracyText = "--",
    hud = nil,
    pendingActivity = nil,
    pendingAccuracy = nil,
}

local function setAutoParryDebugStatus(text, holdSeconds)
    autoParryDebugUi.statusSerial += 1
    local serial = autoParryDebugUi.statusSerial
    autoParryDebugUi.statusText = tostring(text or "--")




    if autoParryDebugUi.statusText ~= "--"
        and autoParryDebugUi.statusText ~= "Monitoring"
    then
        autoParryDebugUi.pendingActivity = {
            text = autoParryDebugUi.statusText,
            hold = tonumber(holdSeconds) or 0.85,
        }

        if autoParryDebugUi.queueHudFlush then
            autoParryDebugUi.queueHudFlush()
        end
    end

    local hold = tonumber(holdSeconds)
    if hold and hold > 0 then
        task.delay(hold, function()
            if autoParryDebugUi.statusSerial ~= serial then
                return
            end

            autoParryDebugUi.statusText = Flags.ap_enable == true
                and "Monitoring"
                or "--"
        end)
    end
end

local function refreshAutoParryDebugAccuracy()
    local samples = autoParryDebugUi.accuracySamples

    if samples <= 0 then
        autoParryDebugUi.accuracyText = "--"
    else
        local percent = math.clamp(
            math.floor((autoParryDebugUi.accuracyHits / samples) * 100 + 0.5),
            0,
            100
        )

        autoParryDebugUi.accuracyText = tostring(percent) .. "%"
    end

    -- Accuracy remains available internally for diagnostics, but it is no
    -- longer displayed in the Status HUD.
    autoParryDebugUi.pendingAccuracy = nil
end

autoParryDebugUi.syncFeatures = function()

end

autoParryDebugUi.syncHud = function(enabled)
    enabled = enabled == true

    if enabled
        and not autoParryDebugUi.hud
        and type(Menu.create_autoparry_status_hud) == "function"
    then
        autoParryDebugUi.hud = Menu:create_autoparry_status_hud()
    end

    if autoParryDebugUi.hud then
        if type(autoParryDebugUi.hud.set_visible) == "function" then
            autoParryDebugUi.hud:set_visible(enabled)
        end
    end

    if enabled
        and autoParryDebugUi.queueHudFlush
    then
        autoParryDebugUi.queueHudFlush()
    end
end

autoParryDebugUi.flushQueued =
    false

autoParryDebugUi.flushHud =
    function()
        autoParryDebugUi.flushQueued =
            false

        local hud =
            autoParryDebugUi.hud

        if not hud then
            autoParryDebugUi.pendingActivity =
                nil
            autoParryDebugUi.pendingAccuracy =
                nil
            return
        end

        autoParryDebugUi.pendingAccuracy =
            nil

        local activity =
            autoParryDebugUi.pendingActivity

        if activity then
            autoParryDebugUi.pendingActivity =
                nil

            if type(hud.push_activity)
                == "function"
            then
                pcall(
                    hud.push_activity,
                    hud,
                    activity.text,
                    activity.hold
                )
            end
        end
    end

autoParryDebugUi.queueHudFlush =
    function()
        if autoParryDebugUi.flushQueued then
            return
        end

        autoParryDebugUi.flushQueued =
            true

        task.defer(
            autoParryDebugUi.flushHud
        )
    end

Connect(Menu._AutoParryDebugStatus["on_toggle_change"], autoParryDebugUi.syncHud)

setAutoParryDebugStatus("--")
refreshAutoParryDebugAccuracy()
autoParryDebugUi.syncHud(Flags.ap_debug_status_hud == true)

