    then
        autoFaceDirectKeybind[
            "_silent_list_only_when_bound"
        ] = true

        local key =
            Flags.ap_auto_face_key

        local unbound =
            key == nil
            or key == Enum.KeyCode.Unknown
            or key == Enum.UserInputType.None
            or key == "Unknown"
            or key == "None"
            or key == ""

        if unbound
            and type(autoFaceToggle.set_key) == "function"
        then
            pcall(
                autoFaceToggle.set_key,
                autoFaceToggle,
                nil
            )
        end
    end

    local function applyBestAutoFaceDefaults()
        local currentSmoothness = tonumber(Flags.ap_auto_face_smoothness)
        local currentSpeed = tonumber(Flags.ap_auto_face_speed)

        if currentSmoothness == nil
            or currentSmoothness == 35
            or currentSmoothness == 22
        then
            smoothness:set_slider(BEST_SMOOTHNESS, false, true)
        end
        if currentSpeed == nil
            or currentSpeed == 720
            or currentSpeed == 1080
        then
            speed:set_slider(BEST_SPEED, false, true)
        end
    end

    local function syncAutoFaceControls(enabled)
        enabled = enabled == true

        for _, control in ipairs({smoothness, speed}) do
            if control and type(control.set_visible) == "function" then
                control:set_visible(enabled)
            end
        end

        if CombatMain and type(CombatMain.recalculate_size) == "function" then
            CombatMain:recalculate_size()
        end
    end

    Menu._AutoFaceUI.sync = syncAutoFaceControls
    applyBestAutoFaceDefaults()
    syncAutoFaceControls(Flags.ap_auto_face == true)
    Connect(autoFaceToggle["on_toggle_change"], syncAutoFaceControls)

    if Menu.on_config_loaded
        and type(Menu.on_config_loaded.Connect) == "function"
    then
        Connect(Menu.on_config_loaded, function()
            task.defer(function()
                applyBestAutoFaceDefaults()

                local key =
                    Flags.ap_auto_face_key

                local unbound =
                    key == nil
                    or key == Enum.KeyCode.Unknown
                    or key == Enum.UserInputType.None
                    or key == "Unknown"
                    or key == "None"
                    or key == ""

                if unbound
                    and type(autoFaceToggle.set_key) == "function"
                then
                    pcall(
                        autoFaceToggle.set_key,
                        autoFaceToggle,
                        nil
                    )
                end
            end)
        end)
    end
end

