    AutoPunishUI.PreferM2 = CombatMain:create_element({
        ["name"] = "Prefer M2",
    }, {
        ["toggle"] = {
            ["default"] = false,
            ["flag"] = "ap_auto_punish_prefer_m2",
        },
    })

    AutoPunishSettings:create_element({
        ["name"] = "",
    }, {
        ["divider"] = {},
    })

    local AutoPunishComboMode = AutoPunishSettings:create_element({
        ["name"] = "Combo Mode",
    }, {
        ["dropdown"] = {
            ["default"] = "Fixed",
            ["flag"] = "ap_auto_punish_combo_mode",
            ["options"] = {
                "Follow",
                "Fixed",
            },
        },
    })

    local AutoPunishFixedComboHit = AutoPunishSettings:create_element({
        ["name"] = "Fixed Combo Hit",
    }, {
        ["slider"] = {
            ["default"] = 1,
            ["flag"] = "ap_auto_punish_fixed_combo_hit",
            ["min"] = 1,
            ["max"] = 4,
            ["decimals"] = 0,
        },
    })

    local AutoPunishTestSwing = AutoPunishSettings:create_element({
        ["name"] = "Test Swing",
    }, {
        ["button"] = {},
    })

    AutoPunishUI.M2Range = AutoPunishSettings:create_element({
        ["name"] = "M2 Range",
    }, {
        ["slider"] = {
            ["default"] = 5.5,
            ["flag"] = "ap_auto_punish_m2_range",
            ["min"] = 3,
            ["max"] = 12,
            ["decimals"] = 1,
            ["suffix"] = " studs",
        },
    })

    Menu._AutoPunishTestSwingPending =
        tonumber(Menu._AutoPunishTestSwingPending) or 0

    Connect(AutoPunishTestSwing["on_clicked"], function()
        local runner = Menu._RunAutoPunishTestSwing
        if type(runner) == "function" then
            runner()
            return
        end

        Menu._AutoPunishTestSwingPending =
            (tonumber(Menu._AutoPunishTestSwingPending) or 0) + 1
    end)

    local AutoPunishVisibleControls = {
        AutoPunishParryMode,
    }

    local function comboModeValue()
        local value = Flags.ap_auto_punish_combo_mode
        if type(value) == "table" then
            value = value[1]
        end
        return value == "Fixed" and "Fixed" or "Follow"
    end

    local function syncAutoPunishSettingRows()
        local masterVisible = Flags.ap_auto_punish == true

        if AutoPunishUI.PreferM2
            and type(AutoPunishUI.PreferM2.set_visible) == "function"
        then
            AutoPunishUI.PreferM2:set_visible(masterVisible)
        end

        local showM2Range = masterVisible
            and Flags.ap_auto_punish_prefer_m2 == true

        if AutoPunishUI.M2Range
            and type(AutoPunishUI.M2Range.set_visible) == "function"
        then
            AutoPunishUI.M2Range:set_visible(showM2Range)
        end
    end

    local function setAutoPunishControlsVisible(visible)
        visible = visible == true

        for _, control in ipairs(AutoPunishVisibleControls) do
            if control and type(control.set_visible) == "function" then
                control:set_visible(visible)
            end
        end

        if AutoPunishComboMode
            and type(AutoPunishComboMode.set_visible) == "function"
        then
            AutoPunishComboMode:set_visible(true)
        end

        if AutoPunishFixedComboHit
            and type(AutoPunishFixedComboHit.set_visible) == "function"
        then
            AutoPunishFixedComboHit:set_visible(
                comboModeValue() == "Fixed"
            )
        end

        if AutoPunishTestSwing
            and type(AutoPunishTestSwing.set_visible) == "function"
        then
            AutoPunishTestSwing:set_visible(true)
        end

        syncAutoPunishSettingRows()

        if CombatMain and type(CombatMain.recalculate_size) == "function" then
            CombatMain:recalculate_size()
        end
    end

    local function syncAutoPunishControls(enabled)
        enabled = enabled == true

        Flags.ap_auto_punish_after_parry = enabled
        Flags.ap_auto_punish_reliable = enabled

        setAutoPunishControlsVisible(enabled)
    end

    AutoPunishUI.Toggle = AutoPunish
    AutoPunishUI.ParryMode = AutoPunishParryMode
    AutoPunishUI.ComboMode = AutoPunishComboMode
    AutoPunishUI.FixedComboHit = AutoPunishFixedComboHit
    AutoPunishUI.TestSwing = AutoPunishTestSwing
    AutoPunishUI.setVisible = setAutoPunishControlsVisible
    AutoPunishUI.syncVisible = syncAutoPunishControls
    AutoPunishUI.syncSettingRows = syncAutoPunishSettingRows

    setAutoPunishControlsVisible(false)
    Connect(AutoPunish["on_toggle_change"], syncAutoPunishControls)
    Connect(AutoPunishUI.PreferM2["on_toggle_change"], syncAutoPunishSettingRows)
    Connect(AutoPunishComboMode["on_dropdown_change"], function()
        setAutoPunishControlsVisible(Flags.ap_auto_punish == true)
    end)
    syncAutoPunishControls(Flags.ap_auto_punish == true)
end

