    "Visuals",
    "Other",
})

-- Combat-only subtab placement helper is retained for the divider only.
local function shiftCombatSubtabPosition(position, pixels)
    if typeof(position) ~= "UDim2" then
        return position
    end

    return UDim2.new(
        position.X.Scale,
        position.X.Offset,
        position.Y.Scale,
        position.Y.Offset + pixels
    )
end

for _, tabName in ipairs({"Visuals", "Other"}) do
    local tab = CombatVisualTabs[tabName]
    if tab then
        if tab["button_text"] then
            tab["button_text"]["Size"] = 12
        end

    end
end

-- Keep the Combat-only center divider visually aligned with the lowered
-- labels. The divider needs a slightly larger vertical correction than the
-- text itself because its shared renderer sits higher in the subtab row.
if CombatVisualTabs["divider"] then
    CombatVisualTabs["divider"]["tween_position"] =
        shiftCombatSubtabPosition(
            CombatVisualTabs["divider"]["tween_position"],
            1
        )
end

