            "Wrestling M2",
        },
        ["multi"] = true,
    },
})

local function normalizeMustEvadeList(value)
    value = type(value) == "table" and value or {}
    local output = {}
    local seen = {}

    for key, entry in pairs(value) do
        local label = entry == true
            and tostring(key or "")
            or tostring(entry or "")

        if label ~= "CQC Ring"
            and label ~= "CQC M2"
            and label ~= "Cqc M2"
            and label ~= "Wing Chun M2"
            and label ~= ""
            and not seen[label]
        then
            seen[label] = true
            output[#output + 1] = label
        end
    end

    MustDodgeList:set_dropdown(output)
end

normalizeMustEvadeList(Flags.dodge_must_dodge_list)
if Menu.on_config_loaded and type(Menu.on_config_loaded.Connect) == "function" then
    Connect(Menu.on_config_loaded, function()
        normalizeMustEvadeList(Flags.dodge_must_dodge_list)
        task.defer(forceAutoIFrameWindow)

        local comboMode = Flags.ap_auto_punish_combo_mode
        if type(comboMode) == "table" then
            comboMode = comboMode[1]
        end
        local parryMode = Flags.ap_auto_punish_parry_mode
        if type(parryMode) == "table" then
            parryMode = parryMode[1]
        end

        if comboMode == "Fixed" and parryMode == "While Stunned" then
            if type(Menu.new_notification) == "function" then
                pcall(
                    Menu.new_notification,
                    "While Stunned is unavailable with Fixed Combo Mode",
                    3,
                    4
                )
            end
        end
    end)
end

