local function refreshLocalSpoofFromUI(value)
    if Menu._MiscUI.SyncSpoofControls then
        Menu._MiscUI.SyncSpoofControls()
    end

    local runtime =
        Menu._SpoofRuntime

    if not runtime then
        return
    end

    if type(value) == "boolean" then
        if type(runtime.refresh)
            == "function"
        then
            runtime.refresh()
        end
    elseif type(runtime.queueRefresh)
        == "function"
    then
        runtime.queueRefresh()
    elseif type(runtime.refresh)
        == "function"
    then
        runtime.refresh()
    end
end

Connect(
    Menu._MiscUI.Spoof["on_toggle_change"],
    refreshLocalSpoofFromUI
)
Connect(
    Menu._MiscUI.UsernameSpoof["on_toggle_change"],
    refreshLocalSpoofFromUI
)
Connect(
    Menu._MiscUI.SpoofFirstName["on_textbox_change"],
    refreshLocalSpoofFromUI
)
Connect(
    Menu._MiscUI.SpoofLastName["on_textbox_change"],
    function(value)
        refreshLocalSpoofFromUI(value)

        local runtime = Menu._SpoofRuntime
        if runtime and runtime.enabled == true then
            task.defer(function()
                if runtime.enabled ~= true then
                    return
                end

                if type(runtime.discoverGameNameFields) == "function" then
                    runtime.discoverGameNameFields()
                end
                if type(runtime.applyGameNameFields) == "function" then
                    runtime.applyGameNameFields()
                end
                if type(runtime.watchGameNameFields) == "function" then
                    runtime.watchGameNameFields()
                end
                if type(runtime.enforceGakuranNameFields) == "function" then
                    runtime.enforceGakuranNameFields()
                end
                if type(runtime.rescanUiRoots) == "function" then
                    runtime.rescanUiRoots()
                end
            end)
        end
    end
)
Connect(
    Menu._MiscUI.SpoofDisplay["on_textbox_change"],
    refreshLocalSpoofFromUI
)
Connect(
    Menu._MiscUI.SpoofUsername["on_textbox_change"],
    refreshLocalSpoofFromUI
)

