    local function layoutPlayerModSettingsRow(control)
        local drawings = control and control.drawings
        local cog = drawings and drawings.cog_icon
        local keybind = drawings and drawings.keybind_border
        local keyText = drawings and drawings.keybind_text
        if not cog or not keybind then
            return
        end

        local width = 28
        pcall(function()
            local textWidth = keyText and keyText.TextBounds and keyText.TextBounds.X
            if tonumber(textWidth) then
                width = math.max(20, tonumber(textWidth) + 8)
            else
                local keySize = keybind.Size
                local offset = keySize and keySize.X and keySize.X.Offset
                width = math.max(20, tonumber(offset) or width)
            end
        end)

        cog.Position = UDim2.new(1, -(width + 18), 0, 1)
        pcall(function()
            cog.ZIndex = math.max(tonumber(cog.ZIndex) or 0, (tonumber(keybind.ZIndex) or 0) + 1)
        end)
    end

    local function bindPlayerModSettingsLayout(control)
        local function refresh()
            task.defer(function()
                layoutPlayerModSettingsRow(control)
                task.delay(0.05, function()
                    layoutPlayerModSettingsRow(control)
                end)
            end)
        end

        refresh()
        if control and control.on_key_change then
            Connect(control.on_key_change, refresh)
        end
    end

