Menu._PlayerModRuntime = (function()
    local previous =
        env.__GakuranPlayerModRuntime

    if type(previous) == "table"
        and type(previous.Unload) == "function"
    then
        pcall(
            previous.Unload,
            previous
        )
    end

    local ContextActionService =
        game:GetService(
            "ContextActionService"
        )
    local FLY_FREECAM_GUARD_ACTION =
        "SilentSolutions.FlyPFreecamGuard"
    local FLY_ANIMATION_CATALOG_IDS = {
        ["Bug"] = 129480390999027,
    }
    local FLY_BUG_ANIMATION_SPEED = 0.75
    local MISC_ANIMATION_CATALOG_IDS = {
        ["Skinwalker"] = 119060168059843,
        ["Ball"] = 93195109588878,
        ["Entity"] = 96276659101575,
        ["Fragmented"] = 108509354936859,
        ["Sturdy"] = 128911226991626,
        ["Wobbly"] = 112546913961358,
        ["Worm"] = 93296121617273,
    }
    local MISC_SKINWALKER_ANIMATION_SPEED = 1
    local MISC_ANIMATION_CAMERA_NO_SHAKE_PRE =
        "SilentSolutions.MiscAnimationNoShake.Pre"
    local MISC_ANIMATION_CAMERA_NO_SHAKE_POST =
        "SilentSolutions.MiscAnimationNoShake.Post"

    local runtime = {
        connection = nil,
        characterConnection = nil,
        character = nil,
        humanoid = nil,
        root = nil,
        birdTrack = nil,
        birdAnimation = nil,
        birdHumanoid = nil,
        birdAnimator = nil,
        birdLastLoadError = nil,
        birdLastWarnKey = nil,
        birdRetryAt = 0,
        birdRetrySelection = nil,
        birdSelection = nil,
        flyAnimationCache = {},
        walkTrack = nil,
        walkAnimation = nil,
        walkHumanoid = nil,
        walkAnimator = nil,
        walkLastLoadError = nil,
        walkLastWarnKey = nil,
        walkRetryAt = 0,
        walkRetrySelection = nil,
        walkSelection = nil,
        walkAnimationCache = {},
        defaultAnimateScript = nil,
        defaultAnimateWasEnabled = nil,
        defaultAnimateSuppressed = false,
        miscAnimationEvasiveSuppressed = false,
        miscAnimationEvasiveSuppressSerial = 0,
        cameraShakeBound = false,
        cameraShakeHumanoid = nil,
        savedCameraOffset = nil,
        cameraStableFocusOffset = nil,
        cameraStabilizerMode = nil,
        cameraOffsetConnection = nil,
        cameraOffsetWriteGuard = false,
        cameraOffsetStable = nil,
        cameraOffsetObserved = nil,
        cameraOffsetPending = nil,
        cameraOffsetPendingSince = 0,
        cameraOffsetLastExternalAt = 0,
        cameraOffsetRecalcSerial = 0,
        cameraOffsetRecalcReason = nil,
        savedAutoRotate = nil,
        flyHoldY = nil,
        flyWasMoving = false,
        parts = {},
        partConnections = {},
        originalCollision = setmetatable(
            {},
            {__mode = "k"}
        ),
    }

    env.__GakuranPlayerModRuntime =
        runtime

    local function dropdownValue(value, fallback)
        if type(value) == "table" then
            value = value[1]
        end

        value =
            tostring(
                value
                or fallback
                or ""
            )

        return value
    end

    local function disconnectPartConnections()
        for _, connection in ipairs(
            runtime.partConnections
        ) do
            pcall(function()
                connection:Disconnect()
            end)
        end

        table.clear(
            runtime.partConnections
        )
    end

    local function restoreCollision()
        for part, original in pairs(
            runtime.originalCollision
        ) do
            if part
                and part.Parent
                and part:IsA("BasePart")
            then
                pcall(function()
                    part.CanCollide =
                        original == true
                end)
            end
        end

        table.clear(
            runtime.originalCollision
        )
    end

    local function addPart(instance)
        if not instance
            or not instance:IsA("BasePart")
        then
            return
        end

        runtime.parts[
            #runtime.parts + 1
        ] =
            instance
    end

    local function removePart(instance)
        for i = #runtime.parts, 1, -1 do
            if runtime.parts[i] == instance then
                table.remove(
                    runtime.parts,
                    i
                )
                break
            end
        end

        runtime.originalCollision[
            instance
        ] =
            nil
    end

    local function flyKeyIsP()
        local value =
            Flags.other_player_fly_key

        if type(value) == "table" then
            value = value[1]
        end

        if typeof(value) == "EnumItem" then
            return value
                == Enum.KeyCode.P
        end

        return string.upper(
            tostring(
                value
                or ""
            )
        ) == "P"
    end

    local function installFlyFreecamGuard()
        pcall(
            ContextActionService.UnbindAction,
            ContextActionService,
            FLY_FREECAM_GUARD_ACTION
        )

        pcall(function()
            ContextActionService
                :BindActionAtPriority(
                    FLY_FREECAM_GUARD_ACTION,
                    function(
                        _,
                        inputState
                    )
                        if inputState
                                == Enum.UserInputState.Begin
                            and flyKeyIsP()
                            and (
                                UserInputService
                                    :IsKeyDown(
                                        Enum.KeyCode.LeftShift
                                    )
                                or UserInputService
                                    :IsKeyDown(
                                        Enum.KeyCode.RightShift
                                    )
                            )
                        then
                            runtime.freecamGuardHits =
                                (
                                    tonumber(
                                        runtime.freecamGuardHits
                                    ) or 0
                                ) + 1

                            return Enum
                                .ContextActionResult
                                .Sink
                        end

                        return Enum
                            .ContextActionResult
                            .Pass
                    end,
                    false,
                    10050,
                    Enum.KeyCode.P
                )
        end)
    end

    installFlyFreecamGuard()

    local function stopBirdAnimation()
        local track =
            runtime.birdTrack

        runtime.birdTrack = nil
        runtime.birdHumanoid = nil
        runtime.birdAnimator = nil
        runtime.birdSelection = nil

        if track then
            pcall(function()
                track:Stop(0.04)
            end)

            pcall(function()
                track:Destroy()
            end)
        end

        local animation =
            runtime.birdAnimation

        runtime.birdAnimation = nil

        if animation then
            pcall(function()
                animation:Destroy()
            end)
        end
    end

    local function keepBirdTrackActive(track)
        if not track then
            return false
        end

        local ok, playing =
            pcall(function()
                return track.IsPlaying
            end)

        if not ok then
            return false
        end

        pcall(function()
            track.Looped = true
            track.Priority =
                Enum.AnimationPriority.Action4
            track:AdjustSpeed(FLY_BUG_ANIMATION_SPEED)
            track:AdjustWeight(1, 0.03)
        end)

        if not playing then
            pcall(function()
                track:Play(0.03, 1, FLY_BUG_ANIMATION_SPEED)
                track:AdjustWeight(1, 0.03)
            end)
        end

        return true
    end

    local function selectedFlyAnimation()
        local value =
            Flags.other_player_fly_animation
        local selection = nil

        if type(value) == "table" then
            selection = value[1]

            if selection == nil then
                for key, entry in pairs(value) do
                    if entry == true then
                        selection = key
                        break
                    elseif type(entry) == "string"
                        and entry ~= ""
                    then
                        selection = entry
                        break
                    end
                end
            end
        else
            selection = value
        end

        selection =
            tostring(selection or "")

        if selection == "Flying Bug"
            or selection == "Bird"
        then
            selection = "Bug"
        end

        if selection == ""
            or FLY_ANIMATION_CATALOG_IDS[
                selection
            ] == nil
        then
            return nil, nil, nil
        end

        local catalogId =
            FLY_ANIMATION_CATALOG_IDS[
                selection
            ]

        return selection,
            catalogId,
            "rbxassetid://"
                .. tostring(catalogId)
    end

    local function findAnimationPayload(
        root,
        fallbackAssetUri
    )
        if not root then
            return nil, nil
        end

        local function inspect(instance)
            if instance:IsA("KeyframeSequence") then
                return "keyframe", instance
            end

            if instance:IsA("Animation") then
                local animationId =
                    tostring(
                        instance.AnimationId
                        or ""
                    )

                if animationId ~= ""
                    and animationId
                        ~= fallbackAssetUri
                then
                    return "animation", animationId
                end
            end

            return nil, nil
        end

        local kind, value =
            inspect(root)

        if kind then
            return kind, value
        end

        local ok, descendants =
            pcall(function()
                return root:GetDescendants()
            end)

        if ok then
            for _, descendant in ipairs(
                descendants
            ) do
                kind, value =
                    inspect(descendant)

                if kind then
                    return kind, value
                end
            end
        end

        return nil, nil
    end

    local function registerBirdPayload(kind, value)
        if kind == "animation" then
            return tostring(value),
                "embedded-animation"
        end

        if kind == "keyframe"
            and value
        then
            local ok, registered =
                pcall(function()
                    return KeyframeSequenceProvider
                        :RegisterKeyframeSequence(
                            value
                        )
                end)

            if ok
                and registered
                and tostring(registered) ~= ""
            then
                return tostring(registered),
                    "registered-keyframe"
            end
        end

        return nil, nil
    end

    local function resolveBirdAnimationId(
        selection,
        catalogId,
        assetUri
    )
        local cached =
            runtime.flyAnimationCache[
                selection
            ]

        if type(cached) == "table"
            and cached.animationId
        then
            return cached.animationId,
                cached.method
        end

        local lastError = nil

        local okObjects, objects =
            pcall(function()
                return game:GetObjects(
                    assetUri
                )
            end)

        if okObjects
            and type(objects) == "table"
        then
            for _, object in ipairs(objects) do
                local kind, payload =
                    findAnimationPayload(
                        object,
                        assetUri
                    )
                local animationId, method =
                    registerBirdPayload(
                        kind,
                        payload
                    )

                pcall(function()
                    object:Destroy()
                end)

                if animationId then
                    runtime.flyAnimationCache[
                        selection
                    ] = {
                        animationId =
                            animationId,
                        method =
                            "getobjects-"
                            .. method,
                    }

                    return animationId,
                        "getobjects-"
                            .. method
                end
            end
        elseif not okObjects then
            lastError = tostring(objects)
        end

        local okAsset, asset =
            pcall(function()
                return InsertService:LoadAsset(
                    catalogId
                )
            end)

        if okAsset
            and asset
        then
            local kind, payload =
                findAnimationPayload(
                    asset,
                    assetUri
                )
            local animationId, method =
                registerBirdPayload(
                    kind,
                    payload
                )

            pcall(function()
                asset:Destroy()
            end)

            if animationId then
                runtime.flyAnimationCache[
                    selection
                ] = {
                    animationId =
                        animationId,
                    method =
                        "insertservice-"
                        .. method,
                }

                return animationId,
                    "insertservice-"
                        .. method
            end
        elseif not okAsset then
            lastError = tostring(asset)
        end

        -- A raw Animation asset can still be rejected by Animator:LoadAnimation
        -- because of Roblox animation ownership rules. When the client can read
        -- the clip, convert it into a temporary registered KeyframeSequence so
        -- Custom IDs that expose their keyframes can still play locally.
        local okSequence, sequence =
            pcall(function()
                return KeyframeSequenceProvider
                    :GetKeyframeSequenceAsync(assetUri)
            end)

        if okSequence and sequence then
            local animationId, method =
                registerBirdPayload(
                    "keyframe",
                    sequence
                )

            pcall(function()
                sequence:Destroy()
            end)

            if animationId then
                runtime.flyAnimationCache[selection] = {
                    animationId = animationId,
                    method = "keyframeprovider-" .. tostring(method),
                }

                return animationId,
                    "keyframeprovider-" .. tostring(method)
            end
        elseif not okSequence then
            lastError = tostring(sequence)
        end

        runtime.flyAnimationCache[
            selection
        ] = {
            animationId = assetUri,
            method =
                "catalog-direct-fallback",
            lastError = lastError,
        }
        runtime.birdLastLoadError =
            lastError

        return assetUri,
            "catalog-direct-fallback"
    end

    local function loadBirdTrack(humanoid, animation)
        local animator =
            humanoid:FindFirstChildOfClass(
                "Animator"
            )
        local track = nil
        local lastError = nil

        if animator then
            local ok, loaded =
                pcall(function()
                    return animator:LoadAnimation(
                        animation
                    )
                end)

            if ok
                and loaded
            then
                track = loaded
            elseif not ok then
                lastError = tostring(loaded)
            else
                lastError =
                    "Animator:LoadAnimation returned nil"
            end
        end

        if not track then
            local ok, loaded =
                pcall(function()
                    return humanoid:LoadAnimation(
                        animation
                    )
                end)

            if ok
                and loaded
            then
                track = loaded
                animator =
                    humanoid:FindFirstChildOfClass(
                        "Animator"
                    )
            elseif not ok then
                lastError = tostring(loaded)
            else
                lastError =
                    "Humanoid:LoadAnimation returned nil"
            end
        end

        if not track
            and not animator
        then
            local okAnimator, createdAnimator =
                pcall(function()
                    local value =
                        Instance.new("Animator")
                    value.Parent = humanoid
                    return value
                end)

            if okAnimator
                and createdAnimator
            then
                animator = createdAnimator

                local okTrack, loaded =
                    pcall(function()
                        return animator:LoadAnimation(
                            animation
                        )
                    end)

                if okTrack
                    and loaded
                then
                    track = loaded
                elseif not okTrack then
                    lastError = tostring(loaded)
                else
                    lastError =
                        "Created Animator returned nil track"
                end
            elseif not okAnimator then
                lastError =
                    tostring(createdAnimator)
            end
        end

        return track, animator, lastError
    end

    local function disconnectStableCameraOffsetTracking()
        local connection =
            runtime.cameraOffsetConnection

        runtime.cameraOffsetConnection = nil

        if connection then
            pcall(function()
                connection:Disconnect()
            end)
        end

        runtime.cameraOffsetWriteGuard = false
        runtime.cameraOffsetStable = nil
        runtime.cameraOffsetObserved = nil
        runtime.cameraOffsetPending = nil
        runtime.cameraOffsetPendingSince = 0
        runtime.cameraOffsetLastExternalAt = 0
    end

    local function restoreMiscAnimationCameraShake()
        if runtime.cameraShakeBound == true then
            pcall(
                RunService.UnbindFromRenderStep,
                RunService,
                MISC_ANIMATION_CAMERA_NO_SHAKE_PRE
            )
            pcall(
                RunService.UnbindFromRenderStep,
                RunService,
                MISC_ANIMATION_CAMERA_NO_SHAKE_POST
            )
            runtime.cameraShakeBound = false
        end

        local humanoid =
            runtime.cameraShakeHumanoid
        local saved =
            runtime.savedCameraOffset

        disconnectStableCameraOffsetTracking()

        runtime.cameraShakeHumanoid = nil
        runtime.savedCameraOffset = nil
        runtime.cameraStableFocusOffset = nil
        runtime.cameraStabilizerMode = nil
        runtime.cameraOffsetRecalcReason = nil

        if humanoid
            and humanoid.Parent
            and typeof(saved) == "Vector3"
        then
            pcall(function()
                humanoid.CameraOffset = saved
            end)
        end

        -- Main154 used a temporary BasePart as CameraSubject. Never keep or
        -- recreate that proxy: Roblox's camera controller can lock onto it.
        -- If a stale proxy survived a previous runtime, remove it and put the
        -- native living Humanoid back as the subject only when the proxy was
        -- actually the current subject.
        local camera = Workspace.CurrentCamera
        local staleProxy =
            Workspace:FindFirstChild(
                "SilentSolutionsAnimationCameraProxy"
            )

        if staleProxy then
            if camera
                and camera.CameraSubject == staleProxy
            then
                local character =
                    LocalPlayer.Character
                local currentHumanoid =
                    character
                    and character:FindFirstChildOfClass(
                        "Humanoid"
                    )
                    or nil

                if currentHumanoid then
                    pcall(function()
                        camera.CameraSubject =
                            currentHumanoid
                    end)
                end
            end

            pcall(function()
                staleProxy:Destroy()
            end)
        end
    end

    local function getStableCameraBaseOffset(
        humanoid,
        root
    )
        if not humanoid
            or not root
            or not root.Parent
        then
            return nil
        end

        -- Roblox follows the HumanoidRootPart and applies a rig-dependent
        -- local-space head offset. Recompute this every frame so avatar scale,
        -- rig changes and respawns cannot leave Stable Camera at an old height.
        local height = 1.5

        if humanoid.RigType == Enum.HumanoidRigType.R15 then
            if humanoid.AutomaticScalingEnabled == true then
                height =
                    1.5
                    + (
                        (root.Size.Y * 0.5)
                        - 1
                    )
            else
                height = 2
            end
        end

        return Vector3.new(0, height, 0)
    end

    local function getStableCameraSubjectPosition(
        humanoid,
        root
    )
        local baseOffset =
            getStableCameraBaseOffset(
                humanoid,
                root
            )

        if typeof(baseOffset) ~= "Vector3" then
            return nil
        end

        local filteredCameraOffset =
            runtime.cameraOffsetStable

        if typeof(filteredCameraOffset)
            ~= "Vector3"
        then
            filteredCameraOffset =
                Vector3.zero
        end

        -- CameraOffset is object-space relative to HumanoidRootPart. Include
        -- the filtered legitimate offset instead of permanently forcing zero;
        -- this is what lets the stabilized view recalculate for crouches,
        -- stances and other sustained camera-height changes.
        return root.CFrame:PointToWorldSpace(
            baseOffset
                + filteredCameraOffset
        )
    end

    local function sameCameraOffsetCandidate(
        a,
        b,
        tolerance
    )
        return typeof(a) == "Vector3"
            and typeof(b) == "Vector3"
            and (a - b).Magnitude
                <= (tonumber(tolerance) or 0.06)
    end

    local function noteExternalCameraOffset(
        value
    )
        if runtime.cameraOffsetWriteGuard == true
            or typeof(value) ~= "Vector3"
        then
            return
        end

        local now = os.clock()
        runtime.cameraOffsetObserved = value
        runtime.cameraOffsetLastExternalAt = now

        local stable =
            runtime.cameraOffsetStable

        if typeof(stable) ~= "Vector3" then
            runtime.cameraOffsetStable = value
            runtime.cameraOffsetPending = nil
            runtime.cameraOffsetPendingSince = 0
            runtime.cameraOffsetRecalcSerial =
                (runtime.cameraOffsetRecalcSerial or 0)
                + 1
            runtime.cameraOffsetRecalcReason =
                "initial"
            return
        end

        -- Tiny changes are treated as harmless numerical noise. Large/real
        -- changes must remain coherent for a short settle window before they
        -- become the new baseline; fast oscillating camera shake therefore
        -- never becomes the stabilized offset.
        if (value - stable).Magnitude <= 0.025 then
            runtime.cameraOffsetPending = nil
            runtime.cameraOffsetPendingSince = 0
            return
        end

        local pending =
            runtime.cameraOffsetPending

        if sameCameraOffsetCandidate(
            pending,
            value,
            0.075
        ) then
            -- Keep the original pending timestamp so repeated writes of the
            -- same crouch/stance offset are allowed to settle and recalculate.
            runtime.cameraOffsetPending =
                pending:Lerp(value, 0.35)
        else
            runtime.cameraOffsetPending = value
            runtime.cameraOffsetPendingSince = now
        end
    end

    local function bindStableCameraOffsetTracking(
        humanoid
    )
        disconnectStableCameraOffsetTracking()

        if not humanoid
            or not humanoid.Parent
        then
            return
        end

        local initial =
            humanoid.CameraOffset

        if typeof(initial) ~= "Vector3" then
            initial = Vector3.zero
        end

        runtime.cameraOffsetStable = initial
        runtime.cameraOffsetObserved = initial
        runtime.cameraOffsetPending = nil
        runtime.cameraOffsetPendingSince = 0
        runtime.cameraOffsetLastExternalAt =
            os.clock()
        runtime.cameraOffsetRecalcSerial =
            (runtime.cameraOffsetRecalcSerial or 0)
            + 1
        runtime.cameraOffsetRecalcReason =
            "bind"

        local ok, connection =
            pcall(function()
                return humanoid
                    :GetPropertyChangedSignal(
                        "CameraOffset"
                    )
                    :Connect(function()
                        if runtime.cameraOffsetWriteGuard
                            == true
                        then
                            return
                        end

                        noteExternalCameraOffset(
                            humanoid.CameraOffset
                        )
                    end)
            end)

        if ok then
            runtime.cameraOffsetConnection =
                connection
        end
    end

    local function updateStableCameraOffset()
        local stable =
            runtime.cameraOffsetStable

        if typeof(stable) ~= "Vector3" then
            return Vector3.zero
        end

        local pending =
            runtime.cameraOffsetPending

        if typeof(pending) == "Vector3" then
            local now = os.clock()
            local pendingAge =
                now
                - (
                    tonumber(
                        runtime.cameraOffsetPendingSince
                    )
                    or now
                )

            -- A sustained value is a real camera-height recalculation. Shake
            -- normally keeps changing direction/magnitude and continuously
            -- resets this settle timer.
            if pendingAge >= 0.12 then
                runtime.cameraOffsetStable = pending
                runtime.cameraOffsetPending = nil
                runtime.cameraOffsetPendingSince = 0
                runtime.cameraOffsetRecalcSerial =
                    (runtime.cameraOffsetRecalcSerial or 0)
                    + 1
                runtime.cameraOffsetRecalcReason =
                    "settled-camera-offset"
                stable = pending
            end
        end

        return stable
    end

    local function resolveCameraStabilizerMode()
        -- Combat Enhancements owns the stabilizer whenever Stable Camera is
        -- enabled. Animate's private suppression becomes a fallback only, so
        -- the two correction paths can never stack on the same frame.
        if Flags.misc_stable_camera == true then
            return "combat"
        end

        if Flags.misc_animations == true then
            return "animations"
        end

        return nil
    end

    local function syncMiscAnimationCameraShake()
        local stabilizerMode =
            resolveCameraStabilizerMode()

        if stabilizerMode == nil then
            restoreMiscAnimationCameraShake()
            return
        end

        local previousMode =
            runtime.cameraStabilizerMode
        runtime.cameraStabilizerMode =
            stabilizerMode

        local humanoid =
            runtime.humanoid
        local root =
            runtime.root

        if not humanoid
            or not humanoid.Parent
            or humanoid.Health <= 0
            or not root
            or not root.Parent
        then
            restoreMiscAnimationCameraShake()
            return
        end

        if runtime.cameraShakeHumanoid ~= humanoid then
            restoreMiscAnimationCameraShake()
            runtime.cameraShakeHumanoid = humanoid
            runtime.savedCameraOffset = humanoid.CameraOffset
            runtime.cameraStabilizerMode =
                stabilizerMode
            bindStableCameraOffsetTracking(
                humanoid
            )
        elseif runtime.cameraOffsetConnection == nil
            or previousMode ~= stabilizerMode
        then
            -- Ownership changes (Stable Camera <-> Animate fallback) force a
            -- fresh camera-offset sample so neither path inherits stale state.
            bindStableCameraOffsetTracking(
                humanoid
            )
            runtime.cameraStabilizerMode =
                stabilizerMode
            runtime.cameraOffsetRecalcReason =
                previousMode ~= stabilizerMode
                and "mode-switch"
                or "rebind"
        end

        local function suppressCameraOffset()
            if resolveCameraStabilizerMode() == nil then
                return
            end

            local currentHumanoid =
                runtime.humanoid

            if currentHumanoid
                and currentHumanoid.Parent
                and currentHumanoid.Health > 0
            then
                local filteredOffset =
                    updateStableCameraOffset()

                pcall(function()
                    runtime.cameraOffsetWriteGuard =
                        true
                    currentHumanoid.CameraOffset =
                        filteredOffset
                    runtime.cameraOffsetWriteGuard =
                        false
                end)

                runtime.cameraOffsetWriteGuard =
                    false
            end
        end

        local function correctAnimationCameraBob()
            if resolveCameraStabilizerMode() == nil then
                return
            end

            local currentHumanoid =
                runtime.humanoid
            local currentRoot =
                runtime.root
            local camera =
                Workspace.CurrentCamera

            if not currentHumanoid
                or not currentHumanoid.Parent
                or currentHumanoid.Health <= 0
                or not currentRoot
                or not currentRoot.Parent
                or not camera
                or camera.CameraSubject ~= currentHumanoid
            then
                return
            end

            updateStableCameraOffset()

            -- Let Roblox update the camera normally first, then correct only
            -- the subject-position displacement. Both the rig-height component
            -- and any legitimate sustained CameraOffset are recalculated, so
            -- Stable Camera can follow real height/state changes without
            -- accepting high-frequency shake as the new baseline.
            local desiredFocus =
                getStableCameraSubjectPosition(
                    currentHumanoid,
                    currentRoot
                )

            if typeof(desiredFocus) ~= "Vector3" then
                return
            end

            local currentFocus =
                camera.Focus.Position
            local correction =
                desiredFocus - currentFocus

            if correction.Magnitude > 0.00001 then
                pcall(function()
                    camera.CFrame =
                        camera.CFrame + correction
                    camera.Focus =
                        camera.Focus + correction
                end)
            end

            local filteredOffset =
                runtime.cameraOffsetStable
            if typeof(filteredOffset)
                ~= "Vector3"
            then
                filteredOffset =
                    Vector3.zero
            end

            pcall(function()
                runtime.cameraOffsetWriteGuard =
                    true
                currentHumanoid.CameraOffset =
                    filteredOffset
                runtime.cameraOffsetWriteGuard =
                    false
            end)

            runtime.cameraOffsetWriteGuard =
                false
        end

        if runtime.cameraShakeBound ~= true then
            pcall(
                RunService.BindToRenderStep,
                RunService,
                MISC_ANIMATION_CAMERA_NO_SHAKE_PRE,
                Enum.RenderPriority.Camera.Value - 2,
                suppressCameraOffset
            )

            pcall(
                RunService.BindToRenderStep,
                RunService,
                MISC_ANIMATION_CAMERA_NO_SHAKE_POST,
                Enum.RenderPriority.Camera.Value + 2,
                correctAnimationCameraBob
            )

            runtime.cameraShakeBound = true
        end

        suppressCameraOffset()
    end

    local function restoreDefaultAnimateController()
        local animate = runtime.defaultAnimateScript
        local wasEnabled = runtime.defaultAnimateWasEnabled

        runtime.defaultAnimateScript = nil
        runtime.defaultAnimateWasEnabled = nil
        runtime.defaultAnimateSuppressed = false

        if animate and animate.Parent and wasEnabled ~= nil then
            pcall(function()
                animate.Enabled = wasEnabled
            end)
        end
    end

    local function suppressDefaultAnimateController()
        local character = runtime.character or LocalPlayer.Character
        if not character then
            return
        end

        local animate = character:FindFirstChild("Animate")
        if animate and (animate:IsA("LocalScript") or animate:IsA("Script")) then
            if runtime.defaultAnimateScript ~= animate then
                restoreDefaultAnimateController()
                runtime.defaultAnimateScript = animate
                local ok, enabled = pcall(function()
                    return animate.Enabled
                end)
                runtime.defaultAnimateWasEnabled = ok and enabled or true
            end

            if animate.Enabled == true then
                pcall(function()
                    animate.Enabled = false
                end)
            end
            runtime.defaultAnimateSuppressed = true
        end

        -- Disabling Animate does not stop tracks it already started. Clear only
        -- locomotion priorities once; combat/action animations remain untouched.
        local humanoid = runtime.humanoid
        local animator = humanoid and humanoid:FindFirstChildOfClass("Animator")
        if animator then
            local ok, tracks = pcall(function()
                return animator:GetPlayingAnimationTracks()
            end)
            if ok and type(tracks) == "table" then
                for _, otherTrack in ipairs(tracks) do
                    if otherTrack ~= runtime.walkTrack then
                        local priorityValue = nil
                        pcall(function()
                            priorityValue = otherTrack.Priority.Value
                        end)
                        if priorityValue ~= nil
                            and priorityValue <= Enum.AnimationPriority.Movement.Value
                        then
                            pcall(function()
                                otherTrack:AdjustWeight(0, 0.03)
                                otherTrack:Stop(0.04)
                            end)
                        end
                    end
                end
            end
        end
    end

    local function stopMiscAnimation()
        local track =
            runtime.walkTrack

        runtime.walkTrack = nil
        runtime.walkHumanoid = nil
        runtime.walkAnimator = nil
        runtime.walkSelection = nil

        if track then
            pcall(function()
                track:Stop(0.08)
            end)

            pcall(function()
                track:Destroy()
            end)
        end

        local animation =
            runtime.walkAnimation

        runtime.walkAnimation = nil

        if animation then
            pcall(function()
                animation:Destroy()
            end)
        end

        restoreDefaultAnimateController()
    end

    local function keepMiscAnimationTrackActive(track)
        if not track then
            return false
        end

        local ok, playing =
            pcall(function()
                return track.IsPlaying
            end)

        if not ok then
            return false
        end

        local isCustom = tostring(runtime.walkSelection or ""):sub(1, 7) == "Custom:"
        if isCustom then
            suppressDefaultAnimateController()
        end

        pcall(function()
            track.Looped = true
            -- Custom owns locomotion at Action priority so Roblox's default
            -- idle/walk/run tracks cannot blend over it. Skinwalker keeps the
            -- older Movement priority so combat/action behavior is unchanged.
            track.Priority = isCustom
                and Enum.AnimationPriority.Action
                or Enum.AnimationPriority.Movement
            track:AdjustSpeed(
                MISC_SKINWALKER_ANIMATION_SPEED
            )
            track:AdjustWeight(1, isCustom and 0.02 or 0.08)
        end)

        if not playing then
            pcall(function()
                track:Play(
                    isCustom and 0.02 or 0.08,
                    1,
                    MISC_SKINWALKER_ANIMATION_SPEED
                )
                track:AdjustWeight(1, isCustom and 0.02 or 0.08)
            end)
        end

        return true
    end

    local function selectedMiscAnimation()
        local value =
            Flags.misc_animation
        local selection = nil

        if type(value) == "table" then
            selection = value[1]

            if selection == nil then
                for key, entry in pairs(value) do
                    if entry == true then
                        selection = key
                        break
                    elseif type(entry) == "string"
                        and entry ~= ""
                    then
                        selection = entry
                        break
                    end
                end
            end
        else
            selection = value
        end

        selection =
            tostring(selection or "")

        -- Migrate Main147-150 configs without exposing the old name in UI.
        if selection == "Dog" then
            selection = "Skinwalker"
        end

        if selection == "Custom" then
            local rawId = tostring(Flags.misc_animation_asset_id or "")
            local assetId = rawId:match("(%d+)")
            if not assetId or #assetId < 6 then
                return nil, nil, nil
            end

            return "Custom:" .. assetId,
                tonumber(assetId),
                "rbxassetid://" .. assetId
        end

        if selection == ""
            or MISC_ANIMATION_CATALOG_IDS[
                selection
            ] == nil
        then
            return nil, nil, nil
        end

        local catalogId =
            MISC_ANIMATION_CATALOG_IDS[
                selection
            ]

        return selection,
            catalogId,
            "rbxassetid://"
                .. tostring(catalogId)
    end

    local function resolveMiscAnimationId(
        selection,
        catalogId,
        assetUri
    )
        local cached =
            runtime.walkAnimationCache[
                selection
            ]

        if type(cached) == "table"
            and cached.animationId
        then
            return cached.animationId,
                cached.method
        end

        if tostring(selection):sub(1, 7) == "Custom:" then
            -- Custom IDs may be catalog/container assets rather than a directly
            -- playable AnimationId. Resolve them through the same GetObjects /
            -- InsertService / KeyframeSequence path as the working presets first.
            local animationId, method =
                resolveBirdAnimationId(
                    "MiscAnimation:" .. selection,
                    catalogId,
                    assetUri
                )

            runtime.walkAnimationCache[selection] = {
                animationId = animationId or assetUri,
                method = "custom-" .. tostring(method or "direct"),
            }
            return animationId or assetUri,
                "custom-" .. tostring(method or "direct")
        end

        -- Reuse the catalog/keyframe resolver already used by Fly,
        -- but keep a separate standalone Misc animation cache/state.
        local animationId, method =
            resolveBirdAnimationId(
                "MiscAnimation:" .. selection,
                catalogId,
                assetUri
            )

        runtime.walkAnimationCache[
            selection
        ] = {
            animationId = animationId,
            method = method,
        }

        return animationId, method
    end

    local function syncMiscAnimation()
        if Flags.misc_animations ~= true then
            stopMiscAnimation()
            return
        end

        -- Cosmetic animations must yield to the game's real Evasive state.
        -- Keep the loaded track cached so it can resume without a reload,
        -- but do not let Heartbeat restart it during the dash/i-frame window.
        if runtime.miscAnimationEvasiveSuppressed == true then
            local currentTrack = runtime.walkTrack
            if currentTrack then
                pcall(function()
                    if currentTrack.IsPlaying then
                        currentTrack:AdjustWeight(0, 0.02)
                        currentTrack:Stop(0.025)
                    end
                end)
            end
            return
        end

        local humanoid =
            runtime.humanoid

        if not humanoid
            or not humanoid.Parent
            or humanoid.Health <= 0
        then
            stopMiscAnimation()
            return
        end

        local selection,
            catalogId,
            assetUri =
                selectedMiscAnimation()

        if not selection
            or not assetUri
        then
            stopMiscAnimation()
            return
        end

        local customSelection = tostring(selection):sub(1, 7) == "Custom:"
        if customSelection then
            suppressDefaultAnimateController()
        else
            restoreDefaultAnimateController()
        end

        if runtime.walkRetrySelection
            ~= selection
        then
            runtime.walkRetrySelection =
                selection
            runtime.walkRetryAt = 0
            runtime.walkLastWarnKey = nil
        end

        local currentTrack =
            runtime.walkTrack

        if currentTrack
            and runtime.walkHumanoid == humanoid
            and runtime.walkSelection
                == selection
            and keepMiscAnimationTrackActive(
                currentTrack
            )
        then
            return
        end

        stopMiscAnimation()
        runtime.walkSelection =
            selection

        if customSelection then
            suppressDefaultAnimateController()
        end

        local now = os.clock()

        if now < (
            tonumber(runtime.walkRetryAt)
            or 0
        ) then
            return
        end

        local animationId, resolveMethod =
            resolveMiscAnimationId(
                selection,
                catalogId,
                assetUri
            )

        local animation =
            Instance.new("Animation")
        animation.Name =
            "SilentMiscAnimation"
        animation.AnimationId =
            animationId
        animation.Parent =
            humanoid

        local track, animator, loadError =
            loadBirdTrack(
                humanoid,
                animation
            )

        if not track then
            if customSelection then
                restoreDefaultAnimateController()
            end

            runtime.walkRetryAt =
                now + 5
            runtime.walkRetrySelection =
                selection
            runtime.walkLastLoadError =
                tostring(
                    loadError
                    or "unknown animation load failure"
                )

            local warnKey =
                tostring(selection)
                .. "|"
                .. tostring(animationId)
                .. "|"
                .. tostring(
                    runtime.walkLastLoadError
                )

            if runtime.walkLastWarnKey
                ~= warnKey
            then
                runtime.walkLastWarnKey =
                    warnKey

                warn(
                    "Misc Animation failed: "
                    .. tostring(
                        runtime.walkLastLoadError
                    )
                    .. " | selection="
                    .. tostring(selection)
                    .. " | id="
                    .. tostring(animationId)
                    .. " | resolver="
                    .. tostring(resolveMethod)
                )
            end

            pcall(function()
                animation:Destroy()
            end)
            return
        end

        runtime.walkRetryAt = 0
        runtime.walkLastLoadError = nil
        runtime.walkSelection =
            selection
        runtime.walkAnimation =
            animation
        runtime.walkTrack =
            track
        runtime.walkHumanoid =
            humanoid
        runtime.walkAnimator =
            animator

        keepMiscAnimationTrackActive(
            track
        )
    end

    function runtime.beginEvasiveAnimationSuppression(holdSeconds)
        if Flags.misc_animations ~= true then
            return nil
        end

        runtime.miscAnimationEvasiveSuppressSerial += 1
        local serial = runtime.miscAnimationEvasiveSuppressSerial
        runtime.miscAnimationEvasiveSuppressed = true

        local track = runtime.walkTrack
        if track then
            pcall(function()
                track:AdjustWeight(0, 0.015)
                if track.IsPlaying then
                    track:Stop(0.025)
                end
            end)
        end

        local hold = math.clamp(
            tonumber(holdSeconds) or 0.38,
            0.12,
            0.75
        )

        task.delay(hold, function()
            if runtime.miscAnimationEvasiveSuppressSerial ~= serial then
                return
            end

            runtime.miscAnimationEvasiveSuppressed = false
            task.defer(syncMiscAnimation)
        end)

        return serial
    end

    function runtime.endEvasiveAnimationSuppression(serial)
        if serial ~= nil
            and runtime.miscAnimationEvasiveSuppressSerial ~= serial
        then
            return false
        end

        runtime.miscAnimationEvasiveSuppressSerial += 1
        runtime.miscAnimationEvasiveSuppressed = false
        task.defer(syncMiscAnimation)
        return true
    end

    local function syncBirdAnimation()
        if Flags.other_player_fly ~= true
            or Flags.other_player_fly_animations
                ~= true
        then
            stopBirdAnimation()
            return
        end

        local humanoid =
            runtime.humanoid

        if not humanoid
            or not humanoid.Parent
            or humanoid.Health <= 0
        then
            stopBirdAnimation()
            return
        end

        local selection,
            catalogId,
            assetUri =
                selectedFlyAnimation()

        if not selection
            or not catalogId
            or not assetUri
        then
            stopBirdAnimation()
            return
        end

        if runtime.birdRetrySelection
            ~= selection
        then
            runtime.birdRetrySelection =
                selection
            runtime.birdRetryAt = 0
            runtime.birdLastWarnKey = nil
        end

        local currentTrack =
            runtime.birdTrack

        if currentTrack
            and runtime.birdHumanoid == humanoid
            and runtime.birdSelection
                == selection
            and keepBirdTrackActive(
                currentTrack
            )
        then
            return
        end

        stopBirdAnimation()
        runtime.birdSelection =
            selection

        local now = os.clock()

        if now < (
            tonumber(runtime.birdRetryAt)
            or 0
        ) then
            return
        end

        local animationId, resolveMethod =
            resolveBirdAnimationId(
                selection,
                catalogId,
                assetUri
            )

        local animation =
            Instance.new("Animation")
        animation.Name =
            "SilentFlyAnimation"
        animation.AnimationId =
            animationId
        animation.Parent =
            humanoid

        local track, animator, loadError =
            loadBirdTrack(
                humanoid,
                animation
            )

        if not track then
            runtime.birdRetryAt =
                now + 5
            runtime.birdRetrySelection =
                selection
            runtime.birdLastLoadError =
                tostring(
                    loadError
                    or "unknown animation load failure"
                )

            local warnKey =
                tostring(selection)
                .. "|"
                .. tostring(animationId)
                .. "|"
                .. tostring(
                    runtime.birdLastLoadError
                )

            if runtime.birdLastWarnKey
                ~= warnKey
            then
                runtime.birdLastWarnKey =
                    warnKey

                warn(
                    "Fly Animation failed: "
                    .. tostring(
                        runtime.birdLastLoadError
                    )
                    .. " | selection="
                    .. tostring(selection)
                    .. " | id="
                    .. tostring(animationId)
                    .. " | resolver="
                    .. tostring(resolveMethod)
                )
            end

            pcall(function()
                animation:Destroy()
            end)
            return
        end

        runtime.birdRetryAt = 0
        runtime.birdLastLoadError = nil
        runtime.birdSelection =
            selection

        runtime.birdAnimation =
            animation
        runtime.birdTrack =
            track
        runtime.birdHumanoid =
            humanoid
        runtime.birdAnimator =
            animator

        keepBirdTrackActive(
            track
        )
    end

    local releaseFlyOrientation

    function runtime.bindCharacter(character)
        restoreCollision()
        disconnectPartConnections()
        stopBirdAnimation()
        stopMiscAnimation()
        restoreMiscAnimationCameraShake()
        releaseFlyOrientation()
        runtime.flyHoldY = nil
        runtime.flyWasMoving = false

        runtime.character =
            character
        runtime.humanoid =
            character
            and character:FindFirstChildOfClass(
                "Humanoid"
            )
            or nil
        runtime.root =
            character
            and character:FindFirstChild(
                "HumanoidRootPart"
            )
            or nil

        table.clear(
            runtime.parts
        )

        if not character then
            return
        end

        for _, descendant in ipairs(
            character:GetDescendants()
        ) do
            addPart(descendant)
        end

        runtime.partConnections[
            #runtime.partConnections + 1
        ] =
            character.DescendantAdded:Connect(
                addPart
            )

        runtime.partConnections[
            #runtime.partConnections + 1
        ] =
            character.DescendantRemoving:Connect(
                removePart
            )

        runtime.partConnections[
            #runtime.partConnections + 1
        ] =
            character.ChildAdded:Connect(
                function(child)
                    if child:IsA("Humanoid") then
                        runtime.humanoid =
                            child
                    elseif child.Name
                        == "HumanoidRootPart"
                        and child:IsA(
                            "BasePart"
                        )
                    then
                        runtime.root =
                            child
                    end
                end
            )
    end

    local function movementDirection()
        local camera =
            Workspace.CurrentCamera

        if not camera then
            return Vector3.zero, 0, 0, 0, nil
        end

        local forward =
            (
                UserInputService:IsKeyDown(
                    Enum.KeyCode.W
                )
                and 1
                or 0
            )
            - (
                UserInputService:IsKeyDown(
                    Enum.KeyCode.S
                )
                and 1
                or 0
            )

        local right =
            (
                UserInputService:IsKeyDown(
                    Enum.KeyCode.D
                )
                and 1
                or 0
            )
            - (
                UserInputService:IsKeyDown(
                    Enum.KeyCode.A
                )
                and 1
                or 0
            )

        -- Vertical fly input: Space rises, either Ctrl key descends.
        local up =
            (
                UserInputService:IsKeyDown(
                    Enum.KeyCode.Space
                )
                and 1
                or 0
            )
            - (
                (
                    UserInputService:IsKeyDown(
                        Enum.KeyCode.LeftControl
                    )
                    or UserInputService:IsKeyDown(
                        Enum.KeyCode.RightControl
                    )
                )
                and 1
                or 0
            )

        local cameraFrame =
            camera.CFrame

        -- Fly translation follows the camera's real orientation.
        -- W/S keep the full LookVector while Space/Ctrl add explicit
        -- world-space vertical movement.
        local look =
            cameraFrame.LookVector
        local rightVector =
            cameraFrame.RightVector

        if look.Magnitude > 0.0001 then
            look = look.Unit
        else
            look = Vector3.new(0, 0, -1)
        end

        if rightVector.Magnitude > 0.0001 then
            rightVector = rightVector.Unit
        else
            rightVector = Vector3.new(1, 0, 0)
        end

        local direction =
            look * forward
            + rightVector * right
            + Vector3.new(
                0,
                up,
                0
            )

        if direction.Magnitude > 1 then
            direction =
                direction.Unit
        end

        return direction,
            forward,
            right,
            up,
            camera
    end

    releaseFlyOrientation = function()
        local humanoid =
            runtime.humanoid

        if humanoid
            and humanoid.Parent
            and runtime.savedAutoRotate
                ~= nil
        then
            pcall(function()
                humanoid.AutoRotate =
                    runtime.savedAutoRotate
            end)
        end

        runtime.savedAutoRotate =
            nil
    end

    local function applyFlyOrientation(
        _,
        _,
        _,
        camera
    )
        if Flags.other_player_fly_animations
            ~= true
        then
            releaseFlyOrientation()
            return
        end

        local humanoid =
            runtime.humanoid
        local root =
            runtime.root

        if humanoid
            and humanoid.Parent
            and root
            and root.Parent
            and camera
        then
            if runtime.savedAutoRotate
                == nil
            then
                runtime.savedAutoRotate =
                    humanoid.AutoRotate
            end

            pcall(function()
                humanoid.AutoRotate = false
            end)

            pcall(function()
                -- Follow the camera's complete orientation (yaw + pitch)
                -- without using camera pitch for fly translation. Position is
                -- preserved here; movementDirection() remains horizontal.
                root.CFrame =
                    CFrame.new(root.Position)
                    * camera.CFrame.Rotation

                root.AssemblyAngularVelocity =
                    Vector3.zero
            end)
        end

        local track =
            runtime.birdTrack

        if track then
            pcall(function()
                track:AdjustSpeed(FLY_BUG_ANIMATION_SPEED)
            end)
        end
    end

    local function applyFly(deltaTime)
        if Flags.other_player_fly
            ~= true
        then
            stopBirdAnimation()
            releaseFlyOrientation()
            runtime.flyHoldY = nil
            runtime.flyWasMoving = false
            return false
        end

        syncBirdAnimation()

        local root =
            runtime.root

        if not root
            or not root.Parent
        then
            return true
        end

        local speed =
            math.clamp(
                tonumber(
                    Flags.other_player_fly_speed
                )
                    or 50,
                1,
                500
            )

        local method =
            dropdownValue(
                Flags.other_player_fly_method,
                "CFrame"
            )

        local direction,
            forward,
            right,
            _,
            camera =
                movementDirection()

        local isMoving =
            direction.Magnitude > 0.001

        if isMoving then
            runtime.flyHoldY = nil
        elseif runtime.flyWasMoving
            or runtime.flyHoldY == nil
        then
            runtime.flyHoldY =
                root.Position.Y
        end

        runtime.flyWasMoving =
            isMoving

        applyFlyOrientation(
            deltaTime,
            forward,
            right,
            camera
        )

        if not isMoving then
            root.AssemblyLinearVelocity =
                Vector3.zero

            local holdY =
                runtime.flyHoldY

            if holdY ~= nil
                and math.abs(
                    root.Position.Y - holdY
                ) > 0.0001
            then
                local current =
                    root.CFrame
                local rotation =
                    current - current.Position

                root.CFrame =
                    CFrame.new(
                        root.Position.X,
                        holdY,
                        root.Position.Z
                    ) * rotation
            end
        elseif method == "Velocity" then
            root.AssemblyLinearVelocity =
                direction * speed
        else
            root.AssemblyLinearVelocity =
                Vector3.zero
            root.CFrame =
                root.CFrame
                + direction
                    * speed
                    * deltaTime
        end

        return true
    end

    local function applyWalkSpeed(deltaTime)
        if Flags.other_player_walkspeed
            ~= true
        then
            return
        end

        local root =
            runtime.root
        local humanoid =
            runtime.humanoid

        if not root
            or not root.Parent
            or not humanoid
            or humanoid.Health <= 0
        then
            return
        end

        local direction =
            humanoid.MoveDirection
        local isMoving =
            direction.Magnitude > 0.001

        if not isMoving then
            return
        end

        local speed =
            math.clamp(
                tonumber(
                    Flags.other_player_walkspeed_speed
                )
                    or 32,
                1,
                250
            )

        local method =
            dropdownValue(
                Flags.other_player_walkspeed_method,
                "CFrame"
            )

        if method == "Velocity" then
            local velocity =
                root.AssemblyLinearVelocity

            root.AssemblyLinearVelocity =
                Vector3.new(
                    direction.X * speed,
                    velocity.Y,
                    direction.Z * speed
                )
        else
            local nativeSpeed =
                math.max(
                    tonumber(
                        humanoid.WalkSpeed
                    )
                        or 0,
                    0
                )

            local extraSpeed =
                speed - nativeSpeed

            if math.abs(extraSpeed)
                > 0.01
            then
                root.CFrame =
                    root.CFrame
                    + direction
                        * extraSpeed
                        * deltaTime
            end
        end
    end

    local function applyNoclip()
        -- Noclip is controlled only by its standalone toggle.
        -- Fly no longer changes character collision.
        local shouldNoclip =
            Flags.other_player_noclip == true

        if not shouldNoclip then
            restoreCollision()
            return
        end

        for i = 1, #runtime.parts do
            local part =
                runtime.parts[i]

            if part
                and part.Parent
                and part.CanCollide
            then
                if runtime.originalCollision[
                    part
                ] == nil
                then
                    runtime.originalCollision[
                        part
                    ] =
                        true
                end

                part.CanCollide =
                    false
            end
        end
    end

    function runtime.step(deltaTime)
        local character =
            LocalPlayer.Character

        if runtime.character
            ~= character
        then
            runtime.bindCharacter(
                character
            )
        end

        if not runtime.root
            or not runtime.root.Parent
        then
            runtime.root =
                character
                and character:FindFirstChild(
                    "HumanoidRootPart"
                )
                or nil
        end

        if not runtime.humanoid
            or not runtime.humanoid.Parent
        then
            runtime.humanoid =
                character
                and character:FindFirstChildOfClass(
                    "Humanoid"
                )
                or nil
        end

        local flying =
            applyFly(
                math.clamp(
                    tonumber(deltaTime)
                        or 0,
                    0,
                    0.05
                )
            )

        -- Standalone Misc animation playback is independent of WalkSpeed
        -- and movement state. Keep it active for as long as Animate is on.
        syncMiscAnimationCameraShake()
        syncMiscAnimation()

        if not flying then
            applyWalkSpeed(
                math.clamp(
                    tonumber(deltaTime)
                        or 0,
                    0,
                    0.05
                )
            )
        end

        applyNoclip()
    end

    function runtime.sync()
        installFlyFreecamGuard()

        if Flags.other_player_fly ~= true
            or Flags.other_player_fly_animations ~= true
        then
            stopBirdAnimation()
        end

        if Flags.misc_animations ~= true then
            runtime.miscAnimationEvasiveSuppressSerial += 1
            runtime.miscAnimationEvasiveSuppressed = false
            stopMiscAnimation()
        end

        -- Stable Camera has priority over Animate's private fallback. Calling
        -- one shared synchronizer guarantees there is only one correction
        -- pipeline bound at any time.
        syncMiscAnimationCameraShake()

        local shouldRun =
            Flags.other_player_fly == true
            or Flags.other_player_walkspeed == true
            or Flags.other_player_noclip == true
            or Flags.misc_animations == true
            or Flags.misc_stable_camera == true

        if shouldRun then
            if not runtime.connection then
                runtime.connection =
                    RunService.Heartbeat:Connect(
                        runtime.step
                    )
            end

            runtime.bindCharacter(
                LocalPlayer.Character
            )

            if Flags.misc_animations == true
                or Flags.misc_stable_camera == true
            then
                syncMiscAnimationCameraShake()
            end
        else
            if runtime.connection then
                pcall(function()
                    runtime.connection:Disconnect()
                end)
                runtime.connection =
                    nil
            end

            restoreCollision()

            if runtime.root
                and runtime.root.Parent
                and dropdownValue(
                    Flags.other_player_fly_method,
                    "CFrame"
                ) == "Velocity"
            then
                pcall(function()
                    local velocity =
                        runtime.root.AssemblyLinearVelocity

                    runtime.root.AssemblyLinearVelocity =
                        Vector3.new(
                            0,
                            velocity.Y,
                            0
                        )
                end)
            end
        end
    end

    function runtime.Unload()
        stopBirdAnimation()
        stopMiscAnimation()
        restoreMiscAnimationCameraShake()
        releaseFlyOrientation()

        pcall(
            ContextActionService.UnbindAction,
            ContextActionService,
            FLY_FREECAM_GUARD_ACTION
        )

        if runtime.connection then
            pcall(function()
                runtime.connection:Disconnect()
            end)
            runtime.connection =
                nil
        end

        if runtime.characterConnection then
            pcall(function()
                runtime.characterConnection:Disconnect()
            end)
            runtime.characterConnection =
                nil
        end

        disconnectPartConnections()
        restoreCollision()
    end

    runtime.characterConnection =
        LocalPlayer.CharacterAdded:Connect(
            function(character)
                runtime.bindCharacter(
                    character
                )

                if Flags.other_player_fly == true
                    or Flags.other_player_walkspeed == true
                    or Flags.other_player_noclip == true
                    or Flags.misc_animations == true
                    or Flags.misc_stable_camera == true
                then
                    runtime.sync()
                end
            end
        )

    runtime.bindCharacter(
        LocalPlayer.Character
    )

    return runtime
end)()

do
    local function syncPlayerModRuntime()
        if Menu._PlayerModRuntime
            and type(
                Menu._PlayerModRuntime.sync
            ) == "function"
        then
            Menu._PlayerModRuntime.sync()
        end
    end

    if Menu._MiscUI
        and Menu._MiscUI.Animations
        and Menu._MiscUI.Animations["on_toggle_change"]
    then
        Connect(
            Menu._MiscUI.Animations["on_toggle_change"],
            syncPlayerModRuntime
        )
    end

    if Menu._MiscUI
        and Menu._MiscUI.AnimationSelection
        and Menu._MiscUI.AnimationSelection["on_dropdown_change"]
    then
        Connect(
            Menu._MiscUI.AnimationSelection["on_dropdown_change"],
            syncPlayerModRuntime
        )
    end

    if Menu._MiscUI
        and Menu._MiscUI.AnimationAssetId
        and Menu._MiscUI.AnimationAssetId["on_textbox_change"]
    then
        Connect(
            Menu._MiscUI.AnimationAssetId["on_textbox_change"],
            function()
                local selected = Flags.misc_animation
                if type(selected) == "table" then
                    selected = selected[1]
                end
                if tostring(selected or "") == "Custom" then
                    syncPlayerModRuntime()
                end
            end
        )
    end

    if Menu._MiscUI
        and Menu._MiscUI.StableCamera
        and Menu._MiscUI.StableCamera["on_toggle_change"]
    then
        Connect(
            Menu._MiscUI.StableCamera["on_toggle_change"],
            syncPlayerModRuntime
        )
    end

    local bindingInfo = {
        {
            control =
                Menu._AutoFaceUI
                and Menu._AutoFaceUI.Toggle,
            toggleFlag = "ap_auto_face",
            keyFlag = "ap_auto_face_key",
            listOnlyWhenBound = true,
            playerModRuntime = false,
        },
        {
            control = Menu._OtherUI.Fly,
            toggleFlag = "other_player_fly",
            keyFlag = "other_player_fly_key",
            listOnlyWhenBound = true,
        },
        {
            control = Menu._OtherUI.WalkSpeed,
            toggleFlag = "other_player_walkspeed",
            keyFlag = "other_player_walkspeed_key",
            listOnlyWhenBound = true,
        },
        {
            control = Menu._OtherUI.Noclip,
            toggleFlag = "other_player_noclip",
            keyFlag = "other_player_noclip_key",
            listOnlyWhenBound = true,
        },
        {
            control = Menu._MiscUI.Animations,
            toggleFlag = "misc_animations",
            keyFlag = "misc_animations_key",
            listOnlyWhenBound = true,
        },
    }

    local function resolveKey(value)
        if typeof(value) == "EnumItem" then
            if value == Enum.KeyCode.Unknown
                or value == Enum.UserInputType.None
            then
                return nil
            end
            return value
        end

        if type(value) == "string"
            and value ~= ""
        then
            local resolved =
                Enum.KeyCode[value]
                or Enum.UserInputType[value]

            if resolved == Enum.KeyCode.Unknown
                or resolved == Enum.UserInputType.None
            then
                return nil
            end

            return resolved
        end

        return nil
    end

    local function repairBinding(info)
        local control =
            info.control

        if type(control) ~= "table" then
            return
        end

        local direct =
            rawget(
                control,
                "_direct_keybind_data"
            )

        if type(direct) ~= "table" then
            return
        end

        local key =
            resolveKey(
                Flags[info.keyFlag]
            )

        if key then
            direct.key =
                key
        elseif info.listOnlyWhenBound == true then
            -- Unbound player-mod/Animate controls stay out of the keybind list.
            direct.key = nil
        end

        direct.method =
            1
        direct.type =
            3
        direct.element =
            control
        direct.original_value =
            false
        direct.value =
            true
        direct.activated =
            Flags[info.toggleFlag]
                == true

        if info.listOnlyWhenBound == true then
            direct[
                "_silent_list_only_when_bound"
            ] = true
        end

        if rawget(
            direct,
            "_silent_verified_toggle_wrapper"
        ) ~= true then
            direct._silent_verified_toggle_wrapper = true

            direct.set_activated =
                function(self, activated)
                    activated = activated == true

                    -- Drive the real toggle control instead of calling a cached
                    -- keybind method. This keeps the checkbox, flag, runtime and
                    -- keybind-list activation state synchronized on every press.
                    if type(control.set_toggle) == "function" then
                        pcall(
                            control.set_toggle,
                            control,
                            activated,
                            false
                        )
                    end

                    self.activated =
                        Flags[info.toggleFlag]
                            == true
                    self.value = true
                    self.original_value = false

                    if info.playerModRuntime ~= false then
                        syncPlayerModRuntime()
                    end

                    return self.activated
                end
        end
    end

    local function repairAllBindings()
        for _, info in ipairs(
            bindingInfo
        ) do
            repairBinding(info)
        end
    end

    for _, info in ipairs(
        bindingInfo
    ) do
        local control =
            info.control

        if control
            and control.on_toggle_change
        then
            Connect(
                control.on_toggle_change,
                function()
                    repairBinding(info)

                    if info.playerModRuntime ~= false then
                        syncPlayerModRuntime()
                    end
                end
            )
        end

        if control
            and control.on_key_change
        then
            Connect(
                control.on_key_change,
                function(key)
                    Flags[info.keyFlag] =
                        key
                    repairBinding(info)
                end
            )
        end
    end

    if Menu.on_config_loaded
        and type(
            Menu.on_config_loaded.Connect
        ) == "function"
    then
        Menu.on_config_loaded:Connect(
            function()
                task.defer(
                    function()
                        repairAllBindings()
                        if Menu._OtherUI
                            and Menu._OtherUI
                                .SyncFlyAnimationSettings
                        then
                            Menu._OtherUI
                                .SyncFlyAnimationSettings()
                        end
                        if Menu._MiscUI
                            and Menu._MiscUI
                                .SyncAnimationSettings
                        then
                            Menu._MiscUI
                                .SyncAnimationSettings()
                        end
                        syncPlayerModRuntime()
                    end
                )
            end
        )
    end

    repairAllBindings()
    syncPlayerModRuntime()
end

Menu._SpoofRuntime = (function()
    local previous =
        env.__GakuranSpoofRuntime

    if type(previous) == "table"
        and type(previous.Unload) == "function"
    then
        pcall(
            previous.Unload,
            previous
        )
    end

    local CoreGui =
        game:GetService("CoreGui")

    local GuiService =
        game:GetService("GuiService")

    local SpoofRunService =
        game:GetService("RunService")

    local runtime = {
        enabled = false,
        rootConnections = {},
        gameNameFieldConnections = {},
        textConnections = setmetatable(
            {},
            {__mode = "k"}
        ),
        originalTexts = setmetatable(
            {},
            {__mode = "k"}
        ),
        lastSpoofed = setmetatable(
            {},
            {__mode = "k"}
        ),
        originalAttributes = setmetatable(
            {},
            {__mode = "k"}
        ),
        originalValues = setmetatable(
            {},
            {__mode = "k"}
        ),
        characterConnection = nil,
        gameNameEnforceConnection = nil,
        gameNameEnforceAccumulator = 0,
        watchedPlayerData = nil,
        robloxMenuOpen = false,
        robloxMenuDescendantConnection = nil,
        robloxMenuOpenConnection = nil,
        robloxMenuCloseConnection = nil,
        robloxMenuPropertyConnection = nil,
        robloxMenuScanSerial = 0,
        coreMenuTextInstances = setmetatable(
            {},
            {__mode = "k"}
        ),
        originalRPFull = nil,
        originalRPFirst = nil,
        originalRPLast = nil,
        discoveredNameSource = nil,
    }

    env.__GakuranSpoofRuntime =
        runtime

    local originalUsername =
        tostring(
            LocalPlayer.Name
            or ""
        )
    local originalDisplayName =
        tostring(
            LocalPlayer.DisplayName
            or originalUsername
        )

    local identityShared =
        env.__GakuranRobloxIdentitySpoofHook

    if type(identityShared)
        ~= "table"
    then
        identityShared = {
            enabled = false,
            display = "",
            username = "",
            userId =
                tonumber(
                    LocalPlayer.UserId
                ) or 0,
            originalUsername =
                originalUsername,
            originalDisplayName =
                originalDisplayName,
            userInfoHookInstalled = false,
            nameLookupHookInstalled = false,
        }

        env.__GakuranRobloxIdentitySpoofHook =
            identityShared
    else
        identityShared.userId =
            tonumber(
                LocalPlayer.UserId
            ) or identityShared.userId
        identityShared.originalUsername =
            originalUsername
        identityShared.originalDisplayName =
            originalDisplayName
    end

    local UserService =
        game:GetService(
            "UserService"
        )

    identityShared.userService =
        UserService
    identityShared.playersService =
        Players

    if identityShared.userInfoHookInstalled
            ~= true
        and type(hookfunction)
            == "function"
    then
        local originalFunction =
            nil

        local wrapper =
            function(service, userIds)
                local packed =
                    table.pack(
                        originalFunction(
                            service,
                            userIds
                        )
                    )

                local state =
                    env.__GakuranRobloxIdentitySpoofHook

                if type(state) == "table"
                    and state.enabled == true
                then
                    local infos =
                        packed[1]

                    if type(infos) == "table" then
                        for _, info in ipairs(
                            infos
                        ) do
                            if type(info) == "table"
                                and tonumber(
                                    info.Id
                                        or info.UserId
                                )
                                    == tonumber(
                                        state.userId
                                    )
                            then
                                if tostring(
                                    state.username
                                    or ""
                                ) ~= ""
                                then
                                    info.Username =
                                        state.username
                                    info.Name =
                                        state.username
                                end

                                if tostring(
                                    state.display
                                    or ""
                                ) ~= ""
                                then
                                    info.DisplayName =
                                        state.display
                                end
                            end
                        end
                    end
                end

                return table.unpack(
                    packed,
                    1,
                    packed.n
                )
            end

        if type(newcclosure)
            == "function"
        then
            wrapper =
                newcclosure(
                    wrapper
                )
        end

        local ok,
            old =
            pcall(
                hookfunction,
                UserService.GetUserInfosByUserIdsAsync,
                wrapper
            )

        if ok
            and type(old)
                == "function"
        then
            originalFunction =
                old
            identityShared.originalUserInfoFunction =
                old
            identityShared.userInfoHookInstalled =
                true
        end
    end

    if identityShared.nameLookupHookInstalled
            ~= true
        and type(hookfunction)
            == "function"
    then
        local originalFunction =
            nil

        local wrapper =
            function(service, userId)
                local state =
                    env.__GakuranRobloxIdentitySpoofHook

                if type(state) == "table"
                    and state.enabled == true
                    and tonumber(userId)
                        == tonumber(
                            state.userId
                        )
                    and tostring(
                        state.username
                        or ""
                    ) ~= ""
                then
                    return state.username
                end

                return originalFunction(
                    service,
                    userId
                )
            end

        if type(newcclosure)
            == "function"
        then
            wrapper =
                newcclosure(
                    wrapper
                )
        end

        local ok,
            old =
            pcall(
                hookfunction,
                Players.GetNameFromUserIdAsync,
                wrapper
            )

        if ok
            and type(old)
                == "function"
        then
            originalFunction =
                old
            identityShared.originalNameLookupFunction =
                old
            identityShared.nameLookupHookInstalled =
                true
        end
    end

    local getIdentity =
        getthreadidentity
        or getidentity

    local setIdentity =
        setthreadidentity
        or setidentity

    local function withLocalUiIdentity(callback)
        if type(callback) ~= "function" then
            return false
        end

        local oldIdentity =
            nil

        if type(getIdentity) == "function" then
            pcall(function()
                oldIdentity =
                    getIdentity()
            end)
        end

        if type(setIdentity) == "function" then
            pcall(
                setIdentity,
                8
            )
        end

        local ok,
            result =
            pcall(
                callback
            )

        if oldIdentity ~= nil
            and type(setIdentity) == "function"
        then
            pcall(
                setIdentity,
                oldIdentity
            )
        end

        return ok,
            result
    end

    local function clean(value)
        value =
            tostring(
                value
                or ""
            )

        value =
            value:gsub(
                "^%s+",
                ""
            ):gsub(
                "%s+$",
                ""
            )

        return value
    end

    local function escapePattern(value)
        return (
            tostring(value):gsub(
                "([^%w])",
                "%%%1"
            )
        )
    end

    local function safeReplace(
        source,
        from,
        to
    )
        source =
            tostring(
                source
                or ""
            )
        from =
            tostring(
                from
                or ""
            )
        to =
            tostring(
                to
                or ""
            )

        if from == ""
            or from == to
            or not source:find(
                from,
                1,
                true
            )
        then
            return source
        end

        local replacement =
            to:gsub(
                "%%",
                "%%%%"
            )

        return (
            source:gsub(
                escapePattern(from),
                replacement
            )
        )
    end

    local function replaceUsernameHandle(
        source,
        desiredUsername
    )
        source =
            tostring(
                source
                or ""
            )

        desiredUsername =
            clean(
                desiredUsername
            )

        if desiredUsername == ""
            or originalUsername == ""
        then
            return source
        end

        local originalLower =
            string.lower(
                originalUsername
            )

        return (
            source:gsub(
                "@([%w_]+)",
                function(handle)
                    if string.lower(
                        tostring(handle)
                    ) == originalLower
                    then
                        return "@"
                            .. desiredUsername
                    end

                    return "@"
                        .. tostring(handle)
                end
            )
        )
    end

    local function instancePathLower(
        instance
    )
        if not instance then
            return ""
        end

        local path =
            ""

        pcall(function()
            path =
                instance:GetFullName()
        end)

        return string.lower(
            tostring(path)
        )
    end

    local function isUsernameContext(
        instance
    )
        local path =
            instancePathLower(
                instance
            )

        return path:find(
            "username",
            1,
            true
        ) ~= nil
            or path:find(
                "user_name",
                1,
                true
            ) ~= nil
            or path:find(
                "handle",
                1,
                true
            ) ~= nil
    end


    local function currentNames()
        local first =
            clean(
                Flags.misc_spoof_first_name
            )
        local last =
            clean(
                Flags.misc_spoof_last_name
            )

        local full =
            first

        if last ~= "" then
            full =
                full ~= ""
                and (
                    full
                    .. " "
                    .. last
                )
                or last
        end

        local username =
            clean(
                Flags.misc_spoof_username
            )

        return first,
            last,
            full,
            username
    end

    local function currentAccountSpoofs()
        local display =
            clean(
                Flags.misc_spoof_display
            )

        local username =
            clean(
                Flags.misc_spoof_username
            )

        return display,
            username
    end

    function runtime.syncRobloxIdentityLayer()
        local display,
            username =
            currentAccountSpoofs()

        identityShared.enabled =
            runtime.enabled == true
            and Flags.misc_spoof_username_enabled
                == true

        identityShared.display =
            display
        identityShared.username =
            username
        identityShared.localPlayer =
            LocalPlayer
        identityShared.userId =
            tonumber(
                LocalPlayer.UserId
            ) or identityShared.userId

        runtime.identityRefreshSerial =
            (
                runtime.identityRefreshSerial
                or 0
            ) + 1

        local serial =
            runtime.identityRefreshSerial

        task.delay(
            0.06,
            function()
                if runtime.identityRefreshSerial
                    ~= serial
                then
                    return
                end

                if type(firesignal)
                    == "function"
                then
                    pcall(function()
                        firesignal(
                            LocalPlayer:GetPropertyChangedSignal(
                                "Name"
                            )
                        )
                    end)

                    pcall(function()
                        firesignal(
                            LocalPlayer:GetPropertyChangedSignal(
                                "DisplayName"
                            )
                        )
                    end)
                end
            end
        )
    end

    local function splitName(full)
        full =
            clean(
                full
            )

        if full == "" then
            return nil,
                nil
        end

        local first,
            rest =
            full:match(
                "^(%S+)%s+(.+)$"
            )

        if not first then
            return full,
                nil
        end

        return clean(first),
            clean(rest)
    end

    local function looksLikeRPFullName(value)
        value =
            clean(
                value
            )

        if value == ""
            or #value < 3
            or #value > 48
            or value:find(
                "\n",
                1,
                true
            )
        then
            return false
        end

        if value == originalUsername
            or value == originalDisplayName
            or value == (
                "@"
                .. originalUsername
            )
        then
            return false
        end

        local first,
            last =
            splitName(
                value
            )

        if not first
            or not last
            or first == ""
            or last == ""
        then
            return false
        end

        if value:find("%d")
            or value:find("[<>%[%]{}]")
        then
            return false
        end

        return true
    end

    local function rememberRPName(
        full,
        source
    )
        full =
            clean(
                full
            )

        if not looksLikeRPFullName(
            full
        ) then
            return false
        end

        if runtime.originalRPFull
            and runtime.originalRPFull ~= ""
        then
            return false
        end

        local first,
            last =
            splitName(
                full
            )

        runtime.originalRPFull =
            full
        runtime.originalRPFirst =
            first
        runtime.originalRPLast =
            last
        runtime.discoveredNameSource =
            tostring(
                source
                or "unknown"
            )

        return true
    end

    local function isLocalCharacterNameplateText(
        instance
    )
        if not instance
            or not instance.Parent
            or not (
                instance:IsA("TextLabel")
                or instance:IsA("TextButton")
            )
        then
            return false
        end

        local character =
            LocalPlayer.Character

        if not character
            or not instance:IsDescendantOf(
                character
            )
        then
            return false
        end

        local cursor =
            instance.Parent

        while cursor
            and cursor ~= character
        do
            if cursor:IsA("BillboardGui")
                or cursor:IsA("SurfaceGui")
            then
                return true
            end

            cursor =
                cursor.Parent
        end

        return false
    end

    local function classifyNameKey(key)
        key =
            tostring(
                key
                or ""
            ):lower():gsub(
                "[^%a]",
                ""
            )

        if key == "firstname"
            or key == "givenname"
            or key == "forename"
        then
            return "first"
        end

        if key == "lastname"
            or key == "surname"
            or key == "familyname"
        then
            return "last"
        end

        if key == "rpname"
            or key == "roleplayname"
            or key == "charactername"
            or key == "fullname"
            or key == "displayname"
        then
            return "full"
        end

        return nil
    end

    function runtime.discoverGameNameFields()
        local character =
            LocalPlayer.Character
        local playerData =
            character
            and character:FindFirstChild(
                "PlayerData"
            )
            or nil

        local discoveredFirst =
            runtime.originalRPFirst
        local discoveredLast =
            runtime.originalRPLast

        local targets = {
            LocalPlayer,
            character,
            playerData,
        }

        for _, target in ipairs(
            targets
        ) do
            if target
                and target.Parent
            then
                local okAttributes,
                    attributes =
                    pcall(
                        target.GetAttributes,
                        target
                    )

                if okAttributes
                    and type(attributes)
                        == "table"
                then
                    for key, value in pairs(
                        attributes
                    ) do
                        if typeof(value)
                            == "string"
                        then
                            local kind =
                                classifyNameKey(
                                    key
                                )

                            if kind == "first"
                                and clean(value)
                                    ~= ""
                            then
                                discoveredFirst =
                                    discoveredFirst
                                    or clean(value)
                            elseif kind == "last"
                                and clean(value)
                                    ~= ""
                            then
                                discoveredLast =
                                    discoveredLast
                                    or clean(value)
                            elseif kind == "full" then
                                rememberRPName(
                                    value,
                                    "attribute:"
                                        .. tostring(
                                            target.Name
                                        )
                                        .. "."
                                        .. tostring(
                                            key
                                        )
                                )
                            end
                        end
                    end
                end

                for _, descendant in ipairs(
                    target:GetDescendants()
                ) do
                    if descendant:IsA(
                        "StringValue"
                    )
                    then
                        local kind =
                            classifyNameKey(
                                descendant.Name
                            )
                        local value =
                            clean(
                                descendant.Value
                            )

                        if kind == "first"
                            and value ~= ""
                        then
                            discoveredFirst =
                                discoveredFirst
                                or value
                        elseif kind == "last"
                            and value ~= ""
                        then
                            discoveredLast =
                                discoveredLast
                                or value
                        elseif kind == "full" then
                            rememberRPName(
                                value,
                                "StringValue:"
                                    .. descendant:GetFullName()
                            )
                        end
                    end
                end
            end
        end

        if not runtime.originalRPFull
            and discoveredFirst
            and discoveredLast
            and discoveredFirst ~= ""
            and discoveredLast ~= ""
        then
            rememberRPName(
                discoveredFirst
                    .. " "
                    .. discoveredLast,
                "first-last-fields"
            )
        end

        if runtime.originalRPFirst == nil then
            runtime.originalRPFirst =
                discoveredFirst
        end

        if runtime.originalRPLast == nil then
            runtime.originalRPLast =
                discoveredLast
        end
    end

    local function transformText(source, instance)
        source =
            tostring(
                source
                or ""
            )

        if Flags.misc_spoof
            ~= true
        then
            return source
        end

        local first,
            last,
            full =
            currentNames()

        local display,
            username =
            currentAccountSpoofs()

        local accountSpoofEnabled =
            Flags.misc_spoof_username_enabled
                == true

        local displayEnabled =
            accountSpoofEnabled
            and display ~= ""

        local usernameEnabled =
            accountSpoofEnabled
            and username ~= ""

        local output =
            source

        if full ~= ""
            and runtime.originalRPFull
            and runtime.originalRPFull ~= ""
        then
            output =
                safeReplace(
                    output,
                    runtime.originalRPFull,
                    full
                )
        end

        local rpPath =
            instancePathLower(
                instance
            )
        local rpNameContext =
            rpPath:find(
                "name",
                1,
                true
            ) ~= nil
            or rpPath:find(
                "surname",
                1,
                true
            ) ~= nil
            or rpPath:find(
                "family",
                1,
                true
            ) ~= nil

        if runtime.originalRPFirst
            and first ~= ""
        then
            if source == runtime.originalRPFirst then
                output = first
            elseif rpNameContext then
                output =
                    safeReplace(
                        output,
                        runtime.originalRPFirst,
                        first
                    )
            end
        end

        if runtime.originalRPLast
            and last ~= ""
        then
            -- Gakuran can rebuild mixed RP text as "<spoof first> <real last>".
            -- Treat that as a name context too so Last Name has the same stable
            -- ownership as First Name instead of flashing the real surname.
            local mixedNameContext =
                rpNameContext
                or isLocalCharacterNameplateText(instance)

            if not mixedNameContext
                and first ~= ""
                and output:find(first, 1, true) ~= nil
            then
                mixedNameContext = true
            end

            if not mixedNameContext
                and runtime.originalRPFirst
                and runtime.originalRPFirst ~= ""
                and output:find(runtime.originalRPFirst, 1, true) ~= nil
            then
                mixedNameContext = true
            end

            if source == runtime.originalRPLast then
                output = last
            elseif mixedNameContext then
                output =
                    safeReplace(
                        output,
                        runtime.originalRPLast,
                        last
                    )
            end
        end

        if accountSpoofEnabled then
            if usernameEnabled then
                output =
                    replaceUsernameHandle(
                        output,
                        username
                    )
            end

            if displayEnabled
                and originalDisplayName ~= ""
            then
                if source == originalDisplayName then
                    output =
                        display
                elseif originalDisplayName
                    ~= originalUsername
                then
                    output =
                        safeReplace(
                            output,
                            originalDisplayName,
                            display
                        )
                end
            end

            if usernameEnabled
                and originalUsername ~= ""
            then
                if source == originalUsername
                    and (
                        isUsernameContext(
                            instance
                        )
                        or not displayEnabled
                    )
                then
                    output =
                        username
                elseif originalDisplayName
                    ~= originalUsername
                then
                    output =
                        safeReplace(
                            output,
                            originalUsername,
                            username
                        )
                end
            end
        end

        return output
    end

    local function isTextObject(instance)
        return instance
            and (
                instance:IsA("TextLabel")
                or instance:IsA("TextButton")
            )
    end

    local function isAccountIdentityText(
        instance
    )
        if not isTextObject(
            instance
        ) then
            return false
        end

        local value =
            ""

        local ok =
            pcall(function()
                value =
                    tostring(
                        instance.Text
                        or ""
                    )
            end)

        if not ok
            or value == ""
        then
            return false
        end

        local lower =
            string.lower(
                value
            )

        if originalUsername ~= ""
            and lower:find(
                string.lower(
                    originalUsername
                ),
                1,
                true
            )
        then
            return true
        end

        if originalDisplayName ~= ""
            and lower:find(
                string.lower(
                    originalDisplayName
                ),
                1,
                true
            )
        then
            return true
        end

        return false
    end

    function runtime.applyTextObject(instance)
        if not isTextObject(instance)
            or not instance.Parent
        then
            return
        end

        local original =
            runtime.originalTexts[
                instance
            ]

        if original == nil then
            original =
                tostring(
                    instance.Text
                    or ""
                )
            runtime.originalTexts[
                instance
            ] =
                original
        end

        local desired =
            runtime.enabled
            and transformText(
                original,
                instance
            )
            or original

        if instance.Text ~= desired then
            runtime.lastSpoofed[
                instance
            ] =
                desired

            withLocalUiIdentity(function()
                instance.Text =
                    desired
            end)
        end
    end

    function runtime.trackTextObject(instance)
        if not isTextObject(instance)
            or runtime.textConnections[
                instance
            ]
        then
            return
        end

        local initialText =
            tostring(
                instance.Text
                or ""
            )

        runtime.originalTexts[
            instance
        ] =
            initialText

        if isLocalCharacterNameplateText(
            instance
        ) then
            rememberRPName(
                initialText,
                "character-nameplate:"
                    .. instance:GetFullName()
            )
        end

        local textSignal =
            nil

        withLocalUiIdentity(function()
            textSignal =
                instance:GetPropertyChangedSignal(
                    "Text"
                )
        end)

        if not textSignal then
            return
        end

        runtime.textConnections[
            instance
        ] =
            textSignal:Connect(
                function()
                    withLocalUiIdentity(function()
                        if not instance
                            or not instance.Parent
                        then
                            return
                        end

                        local current =
                            tostring(
                                instance.Text
                                or ""
                            )

                        if runtime.lastSpoofed[
                            instance
                        ] == current
                        then
                            return
                        end

                        runtime.originalTexts[
                            instance
                        ] =
                            current

                        if isLocalCharacterNameplateText(
                            instance
                        ) then
                            rememberRPName(
                                current,
                                "character-nameplate-update:"
                                    .. instance:GetFullName()
                            )
                        end

                        runtime.applyTextObject(
                            instance
                        )
                    end)
                end
            )

        runtime.applyTextObject(
            instance
        )
    end

    local function scanRoot(root)
        if not root
            or not root.Parent
        then
            return
        end

        local descendants =
            nil

        withLocalUiIdentity(function()
            descendants =
                root:GetDescendants()
        end)

        if type(descendants)
            ~= "table"
        then
            return
        end

        for _, descendant in ipairs(
            descendants
        ) do
            runtime.trackTextObject(
                descendant
            )

            runtime.applyTextObject(
                descendant
            )
        end
    end

    local function trackRoot(root)
        if not root
            or not root.Parent
        then
            return
        end

        runtime.trackedRoots =
            runtime.trackedRoots
            or setmetatable(
                {},
                {__mode = "k"}
            )

        if runtime.trackedRoots[root] then
            scanRoot(
                root
            )
            return
        end

        runtime.trackedRoots[root] =
            true

        scanRoot(
            root
        )

        local connection =
            nil

        withLocalUiIdentity(function()
            connection =
                root.DescendantAdded:Connect(
                    function(instance)
                        withLocalUiIdentity(function()
                            runtime.trackTextObject(
                                instance
                            )
                            runtime.applyTextObject(
                                instance
                            )
                        end)

                        task.defer(function()
                            if instance
                                and instance.Parent
                            then
                                withLocalUiIdentity(function()
                                    runtime.trackTextObject(
                                        instance
                                    )
                                    runtime.applyTextObject(
                                        instance
                                    )
                                end)
                            end
                        end)

                        task.delay(
                            0.08,
                            function()
                                if runtime.enabled
                                    and instance
                                    and instance.Parent
                                then
                                    withLocalUiIdentity(function()
                                        runtime.applyTextObject(
                                            instance
                                        )
                                    end)
                                end
                            end
                        )
                    end
                )
        end)

        if connection then
            runtime.rootConnections[
                #runtime.rootConnections + 1
            ] =
                connection
        end
    end

    runtime.rescanUiRoots =
        function()
            local playerGui =
                LocalPlayer:FindFirstChildOfClass(
                    "PlayerGui"
                )

            scanRoot(
                playerGui
            )

            local character =
                LocalPlayer.Character

            if character then
                scanRoot(
                    character
                )
            end

            if runtime.robloxMenuOpen then
                scanRobloxMenuIncremental()
            end
        end

    runtime.queueUiRescan =
        function()
            if runtime.rescanQueued
                or runtime.enabled ~= true
            then
                return
            end

            runtime.rescanQueued =
                true

            task.delay(
                0.16,
                function()
                    runtime.rescanQueued =
                        false

                    if runtime.enabled then
                        runtime.rescanUiRoots()
                    end
                end
            )
        end


    local function disconnectRobloxMenuTextTracking()
        runtime.robloxMenuScanSerial +=
            1

        if runtime.robloxMenuDescendantConnection then
            pcall(function()
                runtime.robloxMenuDescendantConnection:Disconnect()
            end)
            runtime.robloxMenuDescendantConnection =
                nil
        end

        for instance in pairs(
            runtime.coreMenuTextInstances
        ) do
            local connection =
                runtime.textConnections[
                    instance
                ]

            if connection then
                pcall(function()
                    connection:Disconnect()
                end)
                runtime.textConnections[
                    instance
                ] =
                    nil
            end

            runtime.originalTexts[
                instance
            ] =
                nil
            runtime.lastSpoofed[
                instance
            ] =
                nil
            runtime.coreMenuTextInstances[
                instance
            ] =
                nil
        end
    end

    local function trackRobloxMenuIdentityText(
        instance
    )
        if not runtime.enabled
            or Flags.misc_spoof_username_enabled
                ~= true
            or not isAccountIdentityText(
                instance
            )
        then
            return
        end

        runtime.coreMenuTextInstances[
            instance
        ] =
            true

        withLocalUiIdentity(function()
            runtime.trackTextObject(
                instance
            )
            runtime.applyTextObject(
                instance
            )
        end)
    end

    local function scanRobloxMenuIncremental()
        if runtime.robloxMenuOpen
                ~= true
            or runtime.enabled
                ~= true
            or Flags.misc_spoof_username_enabled
                ~= true
        then
            return
        end

        runtime.robloxMenuScanSerial +=
            1

        local serial =
            runtime.robloxMenuScanSerial

        task.spawn(function()
            local root =
                nil

            withLocalUiIdentity(function()
                root =
                    CoreGui:FindFirstChild(
                        "RobloxGui"
                    )
                    or CoreGui
            end)

            if not root
                or not root.Parent
            then
                return
            end

            local descendants =
                nil

            withLocalUiIdentity(function()
                descendants =
                    root:GetDescendants()
            end)

            if type(descendants)
                ~= "table"
            then
                return
            end

            local processed =
                0

            for _,
                instance in ipairs(
                    descendants
                )
            do
                if runtime.robloxMenuOpen
                        ~= true
                    or runtime.robloxMenuScanSerial
                        ~= serial
                then
                    return
                end

                if instance:IsA("TextLabel")
                    or instance:IsA("TextButton")
                then
                    trackRobloxMenuIdentityText(
                        instance
                    )
                end

                processed += 1

                if processed >= 48 then
                    processed =
                        0
                    task.wait()
                end
            end
        end)
    end

    local function startRobloxMenuTracking()
        if runtime.robloxMenuOpen then
            return
        end

        runtime.robloxMenuOpen =
            true

        disconnectRobloxMenuTextTracking()

        local root =
            nil

        withLocalUiIdentity(function()
            root =
                CoreGui:FindFirstChild(
                    "RobloxGui"
                )
                or CoreGui
        end)

        if root
            and root.Parent
        then
            withLocalUiIdentity(function()
                runtime.robloxMenuDescendantConnection =
                    root.DescendantAdded:Connect(
                        function(instance)
                            if runtime.robloxMenuOpen
                                    ~= true
                                or runtime.enabled
                                    ~= true
                                or Flags.misc_spoof_username_enabled
                                    ~= true
                            then
                                return
                            end

                            if not instance:IsA("TextLabel")
                                and not instance:IsA("TextButton")
                            then
                                return
                            end

                            trackRobloxMenuIdentityText(
                                instance
                            )

                            task.delay(
                                0.06,
                                function()
                                    if runtime.robloxMenuOpen
                                        and instance
                                        and instance.Parent
                                    then
                                        trackRobloxMenuIdentityText(
                                            instance
                                        )
                                    end
                                end
                            )
                        end
                    )
            end)
        end

        scanRobloxMenuIncremental()

        task.delay(
            0.18,
            function()
                if runtime.robloxMenuOpen then
                    scanRobloxMenuIncremental()
                end
            end
        )
    end

    local function stopRobloxMenuTracking()
        if not runtime.robloxMenuOpen then
            return
        end

        runtime.robloxMenuOpen =
            false
        disconnectRobloxMenuTextTracking()
    end

    runtime.startRobloxMenuTracking =
        startRobloxMenuTracking
    runtime.stopRobloxMenuTracking =
        stopRobloxMenuTracking
    runtime.scanRobloxMenuIncremental =
        scanRobloxMenuIncremental


    local function rememberAttribute(
        instance,
        key
    )
        local current =
            instance:GetAttribute(
                key
            )

        if current == nil then
            return false
        end

        local bucket =
            runtime.originalAttributes[
                instance
            ]

        if not bucket then
            bucket =
                {}
            runtime.originalAttributes[
                instance
            ] =
                bucket
        end

        if bucket[key] == nil then
            bucket[key] = {
                exists = true,
                value = current,
            }
        end

        return true
    end

    local function applyAttribute(
        instance,
        key,
        value
    )
        if not instance
            or not instance.Parent
            or value == ""
            or not rememberAttribute(
                instance,
                key
            )
        then
            return
        end

        pcall(
            instance.SetAttribute,
            instance,
            key,
            value
        )
    end

    local function applyStringValue(
        valueObject,
        value
    )
        if not valueObject
            or not valueObject:IsA(
                "StringValue"
            )
            or value == ""
        then
            return
        end

        if runtime.originalValues[
            valueObject
        ] == nil
        then
            runtime.originalValues[
                valueObject
            ] =
                valueObject.Value
        end

        if valueObject.Value ~= value then
            valueObject.Value =
                value
        end
    end

    function runtime.applyGameNameFields()
        if runtime.enabled
            ~= true
        then
            return
        end

        local first,
            last,
            full =
            currentNames()

        runtime.discoverGameNameFields()

        local character =
            LocalPlayer.Character
        local playerData =
            character
            and character:FindFirstChild(
                "PlayerData"
            )
            or nil

        local targets = {
            LocalPlayer,
            character,
            playerData,
        }

        for _, target in ipairs(
            targets
        ) do
            if target
                and target.Parent
            then
                for _, key in ipairs({
                    "FirstName",
                    "Firstname",
                    "First",
                }) do
                    applyAttribute(
                        target,
                        key,
                        first
                    )
                end

                for _, key in ipairs({
                    "LastName",
                    "Lastname",
                    "Last",
                    "Surname",
                    "FamilyName",
                }) do
                    applyAttribute(
                        target,
                        key,
                        last
                    )
                end

                for _, key in ipairs({
                    "RPName",
                    "RoleplayName",
                    "CharacterName",
                    "FullName",
                }) do
                    applyAttribute(
                        target,
                        key,
                        full
                    )
                end

                local okAttributes,
                    attributes =
                    pcall(
                        target.GetAttributes,
                        target
                    )

                if okAttributes
                    and type(attributes)
                        == "table"
                then
                    for key, value in pairs(
                        attributes
                    ) do
                        if typeof(value)
                            == "string"
                        then
                            local kind =
                                classifyNameKey(
                                    key
                                )

                            if kind == "first" then
                                applyAttribute(
                                    target,
                                    key,
                                    first
                                )
                            elseif kind == "last" then
                                applyAttribute(
                                    target,
                                    key,
                                    last
                                )
                            elseif kind == "full" then
                                applyAttribute(
                                    target,
                                    key,
                                    full
                                )
                            end
                        end
                    end
                end

                for _, descendant in ipairs(
                    target:GetDescendants()
                ) do
                    if descendant:IsA(
                        "StringValue"
                    )
                    then
                        local kind =
                            classifyNameKey(
                                descendant.Name
                            )

                        if kind == "first" then
                            applyStringValue(
                                descendant,
                                first
                            )
                        elseif kind == "last" then
                            applyStringValue(
                                descendant,
                                last
                            )
                        elseif kind == "full" then
                            applyStringValue(
                                descendant,
                                full
                            )
                        end
                    end
                end
            end
        end
    end

    function runtime.disconnectGameNameFieldWatchers()
        for _, connection in ipairs(runtime.gameNameFieldConnections) do
            pcall(function()
                connection:Disconnect()
            end)
        end
        table.clear(runtime.gameNameFieldConnections)
        runtime.watchedPlayerData = nil
    end

    function runtime.watchGameNameFields()
        local character = LocalPlayer.Character
        local playerData = character
            and character:FindFirstChild("PlayerData")
            or nil

        if runtime.watchedPlayerData == playerData
            and playerData
            and playerData.Parent
            and #runtime.gameNameFieldConnections > 0
        then
            return
        end

        runtime.disconnectGameNameFieldWatchers()
        if runtime.enabled ~= true then
            return
        end

        if not playerData then
            return
        end

        runtime.watchedPlayerData = playerData

        -- Gakuran's authoritative RP name is Character.PlayerData.FirstName/LastName.
        -- Reassert those exact attributes whenever the game replaces them.
        for _, info in ipairs({
            {key = "FirstName", kind = "first"},
            {key = "LastName", kind = "last"},
        }) do
            if playerData:GetAttribute(info.key) ~= nil then
                local signal = playerData:GetAttributeChangedSignal(info.key)
                local connection = signal:Connect(function()
                    if runtime.enabled ~= true
                        or not playerData.Parent
                    then
                        return
                    end

                    local first, last = currentNames()
                    local desired = info.kind == "last" and last or first
                    if desired == "" then
                        return
                    end

                    if playerData:GetAttribute(info.key) ~= desired then
                        pcall(
                            playerData.SetAttribute,
                            playerData,
                            info.key,
                            desired
                        )
                        task.defer(function()
                            if runtime.enabled
                                and type(runtime.rescanUiRoots) == "function"
                            then
                                runtime.rescanUiRoots()
                            end
                        end)
                    end
                end)
                runtime.gameNameFieldConnections[
                    #runtime.gameNameFieldConnections + 1
                ] = connection
            end
        end
    end

    function runtime.enforceGakuranNameFields()
        if runtime.enabled ~= true then
            return
        end

        local character = LocalPlayer.Character
        if not character or not character.Parent then
            return
        end

        local playerData = character:FindFirstChild("PlayerData")
        if not playerData then
            return
        end

        if runtime.watchedPlayerData ~= playerData then
            runtime.watchGameNameFields()
        end

        local first, last, full = currentNames()

        if first ~= ""
            and playerData:GetAttribute("FirstName") ~= first
        then
            applyAttribute(playerData, "FirstName", first)
        end

        if last ~= ""
            and playerData:GetAttribute("LastName") ~= last
        then
            applyAttribute(playerData, "LastName", last)
        end

        if full == "" then
            return
        end

        local function enforceNameplateText(textObject)
            if not textObject
                or not textObject.Parent
                or not isTextObject(textObject)
            then
                return
            end

            if runtime.originalTexts[textObject] == nil then
                runtime.originalTexts[textObject] = tostring(textObject.Text or "")
            end

            runtime.lastSpoofed[textObject] = full
            if tostring(textObject.Text or "") ~= full then
                withLocalUiIdentity(function()
                    textObject.Text = full
                end)
            end
        end

        local billboard = character:FindFirstChild("PlayerInfoBillboard")
        if billboard then
            enforceNameplateText(billboard:FindFirstChild("Info", true))
        end

        local upperTorso = character:FindFirstChild("UpperTorso")
        local uniformGui = upperTorso
            and upperTorso:FindFirstChild("UniformNameplateGui")
        if uniformGui then
            enforceNameplateText(
                uniformGui:FindFirstChild("UniformNameplateLabel", true)
            )
        end
    end

    function runtime.restoreGameNameFields()
        for instance, values in pairs(
            runtime.originalAttributes
        ) do
            if instance
                and instance.Parent
            then
                for key, state in pairs(
                    values
                ) do
                    if state.exists then
                        pcall(
                            instance.SetAttribute,
                            instance,
                            key,
                            state.value
                        )
                    end
                end
            end
        end

        table.clear(
            runtime.originalAttributes
        )

        for valueObject, value in pairs(
            runtime.originalValues
        ) do
            if valueObject
                and valueObject.Parent
            then
                pcall(function()
                    valueObject.Value =
                        value
                end)
            end
        end

        table.clear(
            runtime.originalValues
        )
    end

    function runtime.disconnectRoots()
        for _, connection in ipairs(
            runtime.rootConnections
        ) do
            pcall(function()
                connection:Disconnect()
            end)
        end

        table.clear(
            runtime.rootConnections
        )

        if runtime.trackedRoots then
            table.clear(
                runtime.trackedRoots
            )
        end
    end

    function runtime.restoreText()
        for instance, original in pairs(
            runtime.originalTexts
        ) do
            if instance
                and instance.Parent
                and isTextObject(
                    instance
                )
            then
                withLocalUiIdentity(function()
                    instance.Text =
                        original
                end)
            end
        end

        table.clear(
            runtime.lastSpoofed
        )
    end

    function runtime.startTextTracking()
        runtime.disconnectRoots()
        runtime.discoverGameNameFields()

        local playerGui =
            LocalPlayer:FindFirstChildOfClass(
                "PlayerGui"
            )

        trackRoot(
            playerGui
        )

        local character =
            LocalPlayer.Character

        if character then
            trackRoot(
                character
            )
        end

        if runtime.robloxMenuOpen then
            scanRobloxMenuIncremental()
        end
    end

    runtime.refreshSerial =
        0

    runtime.queueRefresh =
        function()
            runtime.refreshSerial +=
                1

            local serial =
                runtime.refreshSerial

            task.delay(
                0.14,
                function()
                    if runtime.refreshSerial
                        ~= serial
                    then
                        return
                    end

                    if type(runtime.refresh)
                        == "function"
                    then
                        runtime.refresh()
                    end
                end
            )
        end

    function runtime.refresh()
        local enabled =
            Flags.misc_spoof
                == true

        if enabled
            and runtime.enabled ~= true
        then
            runtime.enabled =
                true
            runtime.startTextTracking()
        elseif not enabled
            and runtime.enabled == true
        then
            runtime.refreshSerial +=
                1
            runtime.enabled =
                false
            runtime.syncRobloxIdentityLayer()
            runtime.disconnectGameNameFieldWatchers()
            runtime.restoreText()
            runtime.restoreGameNameFields()
            runtime.disconnectRoots()
            return
        end

        runtime.enabled =
            enabled

        if not enabled then
            return
        end

        runtime.syncRobloxIdentityLayer()
        runtime.discoverGameNameFields()
        runtime.applyGameNameFields()
        runtime.watchGameNameFields()
        runtime.enforceGakuranNameFields()

        for instance in pairs(
            runtime.originalTexts
        ) do
            runtime.applyTextObject(
                instance
            )
        end

        runtime.queueUiRescan()

        if runtime.robloxMenuOpen
            and Flags.misc_spoof_username_enabled
                == true
        then
            startRobloxMenuTracking()
        end
    end

    function runtime.Unload()
        runtime.refreshSerial +=
            1
        runtime.enabled =
            false
        runtime.syncRobloxIdentityLayer()
        runtime.disconnectGameNameFieldWatchers()
        runtime.restoreText()
        runtime.restoreGameNameFields()
        runtime.disconnectRoots()

        stopRobloxMenuTracking()

        for _, field in ipairs({
            "robloxMenuOpenConnection",
            "robloxMenuCloseConnection",
            "robloxMenuPropertyConnection",
        }) do
            local connection =
                runtime[field]

            if connection then
                pcall(function()
                    connection:Disconnect()
                end)
                runtime[field] =
                    nil
            end
        end


        if runtime.gameNameEnforceConnection then
            pcall(function()
                runtime.gameNameEnforceConnection:Disconnect()
            end)
            runtime.gameNameEnforceConnection = nil
        end

        if runtime.characterConnection then
            pcall(function()
                runtime.characterConnection:Disconnect()
            end)
            runtime.characterConnection =
                nil
        end

        for _, connection in pairs(
            runtime.textConnections
        ) do
            pcall(function()
                connection:Disconnect()
            end)
        end
    end


    runtime.gameNameEnforceConnection =
        (SpoofRunService.PreRender or SpoofRunService.RenderStepped):Connect(function()
            if runtime.enabled ~= true then
                return
            end

            -- Keep Gakuran's RP fields/nameplates corrected before every rendered
            -- frame. Attribute writes are still conditional, so this only does
            -- real work when the game tries to restore the original surname.
            runtime.enforceGakuranNameFields()
        end)

    runtime.characterConnection =
        LocalPlayer.CharacterAdded:Connect(
            function()
                if runtime.enabled then
                    task.defer(
                        runtime.refresh
                    )

                    task.delay(
                        0.12,
                        function()
                            if runtime.enabled then
                                runtime.refresh()
                                runtime.queueUiRescan()
                            end
                        end
                    )
                end
            end
        )

    pcall(function()
        runtime.robloxMenuOpenConnection =
            GuiService.MenuOpened:Connect(
                function()
                    if runtime.enabled
                        and Flags.misc_spoof_username_enabled
                            == true
                    then
                        startRobloxMenuTracking()
                    else
                        runtime.robloxMenuOpen =
                            true
                    end
                end
            )
    end)

    pcall(function()
        runtime.robloxMenuCloseConnection =
            GuiService.MenuClosed:Connect(
                stopRobloxMenuTracking
            )
    end)

    pcall(function()
        runtime.robloxMenuPropertyConnection =
            GuiService:GetPropertyChangedSignal(
                "MenuIsOpen"
            ):Connect(
                function()
                    if GuiService.MenuIsOpen then
                        if runtime.enabled
                            and Flags.misc_spoof_username_enabled
                                == true
                        then
                            startRobloxMenuTracking()
                        else
                            runtime.robloxMenuOpen =
                                true
                        end
                    else
                        stopRobloxMenuTracking()
                    end
                end
            )
    end)

    return runtime
end)()

Menu._SpoofRuntime.syncRobloxIdentityLayer()
Menu._SpoofRuntime.refresh()

if Menu.on_config_loaded
    and type(
        Menu.on_config_loaded.Connect
    ) == "function"
then
    Connect(
        Menu.on_config_loaded,
        function()
            task.defer(function()
                if Menu._MiscUI.SyncSpoofControls then
                    Menu._MiscUI.SyncSpoofControls()
                end


                if Menu._PlayerModRuntime then
                    Menu._PlayerModRuntime.sync()
                end

                if Menu._SpoofRuntime then
                    Menu._SpoofRuntime.refresh()
                end
            end)
        end
    )
end

do
    local HttpService = game:GetService("HttpService")
    local ContextActionService = game:GetService("ContextActionService")
    local Runtime = Menu._OtherRuntime or {}
    Menu._OtherRuntime = Runtime

    Runtime.AutoRhythmAPI = nil
    Runtime.AutoRhythmController = nil
    Runtime.AutoRhythmSession = nil
    Runtime.AutoRhythmLoopSerial = 0
    Runtime.AutoRhythmSessionSerial = 0
    Runtime.AutoRhythmInputAction =
        "Silent.solutions.AutoRhythmInputBlock"
    Runtime.AutoRhythmScheduled =
        setmetatable({}, {__mode = "k"})

    local rhythmShared =
        env.__SilentOtherRhythm

    if type(rhythmShared) ~= "table" then
        rhythmShared = {}
        env.__SilentOtherRhythm =
            rhythmShared
    end

    if rhythmShared.spawnHookInstalled == true
        and type(hookfunction) == "function"
        and type(rhythmShared.spawnHookTarget) == "function"
        and type(rhythmShared.spawnHookOriginal) == "function"
    then
        pcall(
            hookfunction,
            rhythmShared.spawnHookTarget,
            rhythmShared.spawnHookOriginal
        )
    end

    rhythmShared.spawnHookTarget = nil
    rhythmShared.spawnHookOriginal = nil
    rhythmShared.spawnHookReplacement = nil
    rhythmShared.spawnHookVersion = nil
    rhythmShared.spawnHookInstalled = false
    rhythmShared.runtime = Runtime
    rhythmShared.flags = Flags

    function Runtime.GetOtherRawMethod(
        value,
        name
    )
        if type(value) ~= "table" then
            return nil
        end

        local direct =
            rawget(value, name)

        if type(direct) == "function" then
            return direct
        end

        local meta =
            getmetatable(value)

        if type(meta) ~= "table" then
            return nil
        end

        local fromMeta =
            rawget(meta, name)

        if type(fromMeta) == "function" then
            return fromMeta
        end

        local index =
            rawget(meta, "__index")

        if type(index) == "table" then
            local fromIndex =
                rawget(index, name)

            if type(fromIndex) == "function" then
                return fromIndex
            end
        end

        return nil
    end

    function Runtime.GetOtherFunctionUpvalues(
        fn
    )
        if type(fn) ~= "function"
            or type(getupvalues) ~= "function"
        then
            return nil
        end

        local ok, values =
            pcall(getupvalues, fn)

        if ok and type(values) == "table" then
            return values
        end

        return nil
    end

    function Runtime.IsRhythmAPI(value)
        return type(value) == "table"
            and type(
                Runtime.GetOtherRawMethod(
                    value,
                    "Get"
                )
            ) == "function"
            and type(
                Runtime.GetOtherRawMethod(
                    value,
                    "IsPlaying"
                )
            ) == "function"
            and type(
                Runtime.GetOtherRawMethod(
                    value,
                    "SetOnLanePressed"
                )
            ) == "function"
            and type(
                Runtime.GetOtherRawMethod(
                    value,
                    "StartPlay"
                )
            ) == "function"
    end

    function Runtime.IsRhythmController(
        value
    )
        if type(value) ~= "table"
            or rawget(value, "_janitor") == nil
        then
            return false
        end

        return type(
            Runtime.GetOtherRawMethod(
                value,
                "IsPlaying"
            )
        ) == "function"
            and type(
                Runtime.GetOtherRawMethod(
                    value,
                    "SetOnLanePressed"
                )
            ) == "function"
    end

    function Runtime.IsRhythmSession(value)
        if type(value) ~= "table"
            or rawget(value, "_destroyed") == true
            or type(
                rawget(value, "_liveNotes")
            ) ~= "table"
            or type(
                rawget(value, "_windows")
            ) ~= "table"
        then
            return false
        end

        return type(
            Runtime.GetOtherRawMethod(
                value,
                "_now"
            )
        ) == "function"
            and type(
                Runtime.GetOtherRawMethod(
                    value,
                    "_handleLanePress"
                )
            ) == "function"
            and type(
                Runtime.GetOtherRawMethod(
                    value,
                    "_handleLaneRelease"
                )
            ) == "function"
    end

    function Runtime.ResolveAutoRhythmController(
        forceGC
    )
        if Runtime.IsRhythmController(
            Runtime.AutoRhythmController
        ) then
            return Runtime.AutoRhythmController
        end

        if Runtime.IsRhythmController(
            rhythmShared.controller
        ) then
            Runtime.AutoRhythmController =
                rhythmShared.controller
            Runtime.AutoRhythmAPI =
                rhythmShared.api
                    or rhythmShared.controller
            return Runtime.AutoRhythmController
        end

        local api = nil
        local controller = nil

        local sharedApi =
            rhythmShared.api

        if Runtime.IsRhythmAPI(sharedApi) then
            api = sharedApi
        end

        if api then
            local getFn =
                Runtime.GetOtherRawMethod(
                    api,
                    "Get"
                )

            if getFn then
                local okGet, value =
                    pcall(
                        getFn,
                        api
                    )

                if okGet
                    and Runtime
                        .IsRhythmController(
                            value
                        )
                then
                    controller = value
                end
            end
        end

        if not controller then
            local module = nil

            pcall(function()
                local sharedFolder =
                    ReplicatedStorage
                        :FindFirstChild(
                            "Shared"
                        )
                local services =
                    sharedFolder
                    and sharedFolder
                        :FindFirstChild(
                            "Services"
                        )
                local rhythm =
                    services
                    and services
                        :FindFirstChild(
                            "RhythmService"
                        )

                module =
                    rhythm
                    and rhythm
                        :FindFirstChild(
                            "RhythmServiceClient"
                        )
            end)

            if module
                and module.Parent ~= nil
            then
                local okRequire, value =
                    pcall(
                        require,
                        module
                    )

                if okRequire
                    and Runtime
                        .IsRhythmAPI(value)
                then
                    api = value

                    local getFn =
                        Runtime
                            .GetOtherRawMethod(
                                value,
                                "Get"
                            )

                    if getFn then
                        local okGet, result =
                            pcall(
                                getFn,
                                value
                            )

                        if okGet
                            and Runtime
                                .IsRhythmController(
                                    result
                                )
                        then
                            controller =
                                result
                        end
                    end
                end
            end
        end

        local nowClock = os.clock()
        local canScanGC =
            type(getgc) == "function"
            and (
                forceGC == true
                or not rhythmShared.lastGCScan
                or nowClock
                    - rhythmShared.lastGCScan
                    >= 2
            )

        if not controller and canScanGC then
            rhythmShared.lastGCScan =
                nowClock

            local okGC, objects =
                pcall(getgc, true)

            if okGC
                and type(objects) == "table"
            then
                for _, object in ipairs(
                    objects
                ) do
                    if type(object) == "table" then
                        if not controller
                            and Runtime
                                .IsRhythmController(
                                    object
                                )
                        then
                            controller =
                                object
                        end

                        if not api
                            and Runtime
                                .IsRhythmAPI(
                                    object
                                )
                        then
                            api = object
                        end

                        if controller and api then
                            break
                        end
                    end
                end
            end
        end

        if not controller and api then
            local getFn =
                Runtime.GetOtherRawMethod(
                    api,
                    "Get"
                )

            if getFn then
                local okGet, value =
                    pcall(
                        getFn,
                        api
                    )

                if okGet
                    and Runtime
                        .IsRhythmController(
                            value
                        )
                then
                    controller = value
                end
            end
        end

        if not controller then
            return nil
        end

        Runtime.AutoRhythmController =
            controller
        Runtime.AutoRhythmAPI =
            api or controller
        rhythmShared.controller =
            controller
        rhythmShared.api =
            api or controller

        return controller
    end

    function Runtime.ResolveAutoRhythmSession(
        forceGC
    )
        local controller =
            Runtime.ResolveAutoRhythmController(
                forceGC
            )

        if not controller then
            Runtime.AutoRhythmSession = nil
            return nil
        end

        local session =
            rawget(
                controller,
                "_session"
            )

        if Runtime.IsRhythmSession(
            session
        ) then
            Runtime.AutoRhythmSession =
                session
            return session
        end

        Runtime.AutoRhythmSession = nil
        return nil
    end

    function Runtime.SetAutoRhythmInputBlocked(
        blocked
    )
        pcall(
            ContextActionService.UnbindAction,
            ContextActionService,
            Runtime.AutoRhythmInputAction
        )

        if blocked ~= true then
            return
        end

        ContextActionService
            :BindActionAtPriority(
                Runtime.AutoRhythmInputAction,
                function()
                    return Enum
                        .ContextActionResult
                        .Sink
                end,
                false,
                Enum.ContextActionPriority
                    .High.Value
                    + 100,
                Enum.KeyCode.F,
                Enum.KeyCode.J,
                Enum.KeyCode.X,
                Enum.KeyCode.C,
                Enum.KeyCode.N,
                Enum.KeyCode.M,
                Enum.KeyCode.Left,
                Enum.KeyCode.Down,
                Enum.KeyCode.Up,
                Enum.KeyCode.Right
            )
    end

    function Runtime.GetAutoRhythmOffset(
        session
    )
        local windows =
            session
            and rawget(
                session,
                "_windows"
            )
            or {}

        local perfectMs =
            tonumber(
                windows.PERFECT
            ) or 35
        local goodMs =
            tonumber(
                windows.GOOD
            ) or 70
        local okayMs =
            tonumber(
                windows.OKAY
            ) or 105
        local badMs =
            tonumber(
                windows.BAD
            ) or 140

        local accuracy =
            math.clamp(
                math.floor(
                    (
                        tonumber(
                            Flags
                                .other_auto_rhythm_accuracy
                        ) or 0
                    ) + 0.5
                ),
                0,
                10
            )

        if accuracy <= 0 then
            return 0
        end

        local severity =
            accuracy / 10

        local curvedSeverity =
            severity ^ 1.40

        local maxLateMs =
            math.max(
                1,
                badMs * 0.92
            )

        local targetMs =
            maxLateMs
            * curvedSeverity

        local variance =
            0.84
            + math.random() * 0.32

        local offsetMs =
            targetMs * variance

        if accuracy >= 10 then
            local badFloor =
                math.min(
                    badMs * 0.94,
                    math.max(
                        okayMs + 2,
                        okayMs * 1.04
                    )
                )
            local badCeiling =
                math.max(
                    badFloor,
                    badMs * 0.97
                )

            offsetMs =
                badFloor
                + math.random()
                    * (
                        badCeiling
                        - badFloor
                    )
        else
            offsetMs =
                math.min(
                    offsetMs,
                    badMs * 0.90
                )
        end

        return offsetMs * 0.001
    end

    function Runtime.GetAutoRhythmNow(
        session
    )
        local nowFn =
            Runtime.GetOtherRawMethod(
                session,
                "_now"
            )

        if not nowFn then
            return nil
        end

        local ok, value =
            pcall(
                nowFn,
                session
            )

        if ok
            and typeof(value) == "number"
        then
            return value
        end

        return nil
    end

    function Runtime.WaitForRhythmTime(
        session,
        targetAt,
        sessionSerial
    )
        while Flags.other_auto_rhythm
                == true
            and Runtime.AutoRhythmSession
                == session
            and Runtime.AutoRhythmSessionSerial
                == sessionSerial
            and Runtime.IsRhythmSession(
                session
            )
        do
            local now =
                Runtime.GetAutoRhythmNow(
                    session
                )

            if not now then
                return false
            end

            local remaining =
                targetAt - now

            if remaining <= 0 then
                return true
            end

            if remaining > 0.050 then
                task.wait(
                    math.clamp(
                        remaining - 0.020,
                        0.010,
                        0.080
                    )
                )
            else
                RunService
                    .Heartbeat:Wait()
            end
        end

        return false
    end

    function Runtime.ReleaseAutoRhythmLane(
        session,
        lane
    )
        local touch =
            rawget(
                session,
                "_laneTouchActive"
            )

        if type(touch) == "table" then
            touch[lane] = false
        end

        local releaseFn =
            Runtime.GetOtherRawMethod(
                session,
                "_handleLaneRelease"
            )

        if releaseFn then
            pcall(
                releaseFn,
                session,
                lane
            )
        end
    end

    function Runtime.ReleaseAllAutoRhythmLanes(
        session
    )
        if not Runtime.IsRhythmSession(
            session
        ) then
            return
        end

        local lanes =
            tonumber(
                rawget(
                    session,
                    "_lanes"
                )
            ) or 4

        for lane = 1, lanes do
            Runtime.ReleaseAutoRhythmLane(
                session,
                lane
            )
        end
    end

    function Runtime.ScheduleAutoRhythmNote(
        session,
        note,
        sessionSerial
    )
        if not Runtime.IsRhythmSession(
            session
        )
            or type(note) ~= "table"
            or typeof(
                rawget(note, "t")
            ) ~= "number"
            or typeof(
                rawget(note, "lane")
            ) ~= "number"
            or rawget(note, "resolved") == true
            or rawget(note, "hit") == true
        then
            return false
        end

        local scheduled =
            Runtime.AutoRhythmScheduled[
                session
            ]

        if type(scheduled) ~= "table" then
            scheduled =
                setmetatable(
                    {},
                    {__mode = "k"}
                )
            Runtime.AutoRhythmScheduled[
                session
            ] = scheduled
        end

        if scheduled[note] then
            return false
        end

        scheduled[note] = true

        task.spawn(function()
            local offset =
                Runtime.GetAutoRhythmOffset(
                    session
                )
            local hitAt =
                note.t + offset

            if not Runtime.WaitForRhythmTime(
                session,
                hitAt,
                sessionSerial
            ) then
                return
            end

            if Flags.other_auto_rhythm
                    ~= true
                or Runtime.AutoRhythmSession
                    ~= session
                or Runtime.AutoRhythmSessionSerial
                    ~= sessionSerial
                or rawget(note, "resolved")
                    == true
                or rawget(note, "hit")
                    == true
            then
                return
            end

            local lane =
                tonumber(
                    rawget(
                        note,
                        "lane"
                    )
                )

            if not lane then
                return
            end

            local touch =
                rawget(
                    session,
                    "_laneTouchActive"
                )

            if type(touch) == "table" then
                touch[lane] = true
            end

            local pressFn =
                Runtime.GetOtherRawMethod(
                    session,
                    "_handleLanePress"
                )

            if not pressFn then
                if type(touch) == "table" then
                    touch[lane] = false
                end
                return
            end

            local okPress =
                pcall(
                    pressFn,
                    session,
                    lane
                )

            if not okPress then
                if type(touch) == "table" then
                    touch[lane] = false
                end
                return
            end

            local length =
                tonumber(
                    rawget(
                        note,
                        "len"
                    )
                ) or 0

            if length > 0.01 then
                local releaseAt =
                    note.t
                    + length
                    + offset

                if Runtime.WaitForRhythmTime(
                    session,
                    releaseAt,
                    sessionSerial
                ) then
                    Runtime
                        .ReleaseAutoRhythmLane(
                            session,
                            lane
                        )
                end
            else
                task.delay(
                    0.015,
                    function()
                        if Runtime
                                .AutoRhythmSession
                                == session
                            and Runtime
                                .AutoRhythmSessionSerial
                                == sessionSerial
                        then
                            Runtime
                                .ReleaseAutoRhythmLane(
                                    session,
                                    lane
                                )
                        end
                    end
                )
            end
        end)

        return true
    end

    function Runtime.AttachAutoRhythmSession(
        session
    )
        if not Runtime.IsRhythmSession(
            session
        ) then
            return false
        end

        Runtime.AutoRhythmSession =
            session
        Runtime.AutoRhythmSessionSerial =
            (
                Runtime
                    .AutoRhythmSessionSerial
                or 0
            ) + 1

        local serial =
            Runtime.AutoRhythmSessionSerial

        Runtime.AutoRhythmScheduled[
            session
        ] =
            setmetatable(
                {},
                {__mode = "k"}
            )

        task.spawn(function()
            while Flags.other_auto_rhythm
                    == true
                and Runtime.AutoRhythmSession
                    == session
                and Runtime.AutoRhythmSessionSerial
                    == serial
                and Runtime.IsRhythmSession(
                    session
                )
            do
                local now =
                    Runtime.GetAutoRhythmNow(
                        session
                    )

                if not now then
                    break
                end

                local windows =
                    rawget(
                        session,
                        "_windows"
                    )
                    or {}
                local lateWindow =
                    (
                        tonumber(
                            windows.BAD
                        ) or 140
                    ) / 1000
                    + 0.08

                local notes =
                    rawget(
                        session,
                        "_liveNotes"
                    )

                if type(notes) == "table" then
                    for _, note in ipairs(
                        notes
                    ) do
                        if type(note) == "table"
                            and rawget(
                                note,
                                "resolved"
                            ) ~= true
                            and rawget(
                                note,
                                "hit"
                            ) ~= true
                        then
                            local noteAt =
                                tonumber(
                                    rawget(
                                        note,
                                        "t"
                                    )
                                )

                            if noteAt
                                and noteAt
                                    >= now
                                        - lateWindow
                                and noteAt
                                    <= now + 4
                            then
                                Runtime
                                    .ScheduleAutoRhythmNote(
                                        session,
                                        note,
                                        serial
                                    )
                            end
                        end
                    end
                end

                task.wait(0.05)
            end
        end)

        return true
    end

    function Runtime.SetAutoRhythmEnabled(
        enabled
    )
        Runtime.AutoRhythmLoopSerial =
            (
                Runtime
                    .AutoRhythmLoopSerial
                or 0
            ) + 1
        Runtime.AutoRhythmSessionSerial =
            (
                Runtime
                    .AutoRhythmSessionSerial
                or 0
            ) + 1

        local previousSession =
            Runtime.AutoRhythmSession

        Runtime.SetAutoRhythmInputBlocked(
            enabled == true
        )

        if enabled ~= true then
            if Runtime.IsRhythmSession(
                previousSession
            ) then
                Runtime
                    .ReleaseAllAutoRhythmLanes(
                        previousSession
                    )
            end

            Runtime.AutoRhythmSession =
                nil
            return
        end

        Runtime.AutoRhythmSession = nil

        local loopSerial =
            Runtime.AutoRhythmLoopSerial

        Runtime.ResolveAutoRhythmController(
            true
        )

        task.spawn(function()
            local lastSession = nil

            while Flags.other_auto_rhythm
                    == true
                and Runtime.AutoRhythmLoopSerial
                    == loopSerial
            do
                local session =
                    Runtime
                        .ResolveAutoRhythmSession(
                            false
                        )

                if session
                    and session ~= lastSession
                then
                    lastSession = session
                    Runtime
                        .AttachAutoRhythmSession(
                            session
                        )
                elseif not session then
                    lastSession = nil
                end

                task.wait(0.08)
            end
        end)
    end

    Runtime.BasketballAPI = nil
    Runtime.BasketballController = nil
    Runtime.BasketballUtils = nil
    Runtime.BasketballConfig = nil
    Runtime.BasketballLoopSerial = 0
    Runtime.BasketballGuarding = false
    Runtime.BasketballLastSteal = 0
    Runtime.BasketballLastBlock = 0
    Runtime.BasketballLastDribble = 0
    Runtime.BasketballDribbleSerial = 0
    Runtime.BasketballDribbleSide = 0
    Runtime.BasketballLastBlockedShot =
        setmetatable({}, {__mode = "k"})
    Runtime.BasketballModeOwned = false
    Runtime.BasketballModeRequestAt = 0
    Runtime.BasketballGreenSerial = 0
    Runtime.BasketballGreenReleased = true
    Runtime.BasketballGreenReleaseRequested =
        false

    local basketballShared =
        env.__SilentOtherBasketball

    if type(basketballShared) ~= "table" then
        basketballShared = {}
        env.__SilentOtherBasketball =
            basketballShared
    end

    if basketballShared.greenHookInstalled
            == true
        and type(hookfunction) == "function"
        and type(
            basketballShared.greenHookTarget
        ) == "function"
        and type(
            basketballShared.greenOriginal
        ) == "function"
    then
        pcall(
            hookfunction,
            basketballShared.greenHookTarget,
            basketballShared.greenOriginal
        )
    end

    basketballShared.greenHookTarget = nil
    basketballShared.greenHookReplacement = nil
    basketballShared.greenHookVersion = nil
    basketballShared.greenHookInstalled = false
    basketballShared.greenWrapper = nil
    basketballShared.runtime = Runtime
    basketballShared.flags = Flags

    function Runtime.IsBasketballController(
        value
    )
        return type(value) == "table"
            and type(
                Runtime.GetOtherRawMethod(
                    value,
                    "_sendShoot"
                )
            ) == "function"
            and type(
                Runtime.GetOtherRawMethod(
                    value,
                    "RequestShoot"
                )
            ) == "function"
            and type(
                Runtime.GetOtherRawMethod(
                    value,
                    "RequestGuard"
                )
            ) == "function"
            and type(
                Runtime.GetOtherRawMethod(
                    value,
                    "RequestSteal"
                )
            ) == "function"
            and type(
                Runtime.GetOtherRawMethod(
                    value,
                    "RequestJump"
                )
            ) == "function"
            and type(
                Runtime.GetOtherRawMethod(
                    value,
                    "RequestDribble"
                )
            ) == "function"
    end

    function Runtime.IsBasketballAPI(value)
        return Runtime
            .IsBasketballController(value)
            and type(
                Runtime.GetOtherRawMethod(
                    value,
                    "Get"
                )
            ) == "function"
    end

    function Runtime.IsBasketballConfig(value)
        return type(value) == "table"
            and type(
                rawget(
                    value,
                    "SHOT_TIMINGS"
                )
            ) == "table"
            and rawget(
                value,
                "ATTR_HOLDING_BALL"
            ) == "BasketballHoldingBall"
            and typeof(
                rawget(
                    value,
                    "SHOT_TIMING_WINDOW"
                )
            ) == "number"
    end

    function Runtime.IsBasketballUtils(value)
        return type(value) == "table"
            and type(
                Runtime.GetOtherRawMethod(
                    value,
                    "GetTeam"
                )
            ) == "function"
            and type(
                Runtime.GetOtherRawMethod(
                    value,
                    "AreOpponents"
                )
            ) == "function"
            and type(
                Runtime.GetOtherRawMethod(
                    value,
                    "IsOnCourt"
                )
            ) == "function"
            and type(
                Runtime.GetOtherRawMethod(
                    value,
                    "ShotWindow"
                )
            ) == "function"
    end

    function Runtime.HydrateBasketballDependencies(
        controller
    )
        if not controller then
            return
        end

        if Runtime.IsBasketballConfig(
            Runtime.BasketballConfig
        )
            and Runtime.IsBasketballUtils(
                Runtime.BasketballUtils
            )
        then
            return
        end

        local owners = {
            controller,
            getmetatable(
                controller
            ),
        }

        local meta =
            owners[2]

        if type(meta) == "table" then
            local index =
                rawget(
                    meta,
                    "__index"
                )

            if type(index) == "table"
                and index ~= meta
            then
                owners[#owners + 1] =
                    index
            end
        end

        local seenFunctions =
            setmetatable(
                {},
                {__mode = "k"}
            )

        for _, owner in ipairs(owners) do
            if type(owner) == "table" then
                for _, fn in pairs(owner) do
                    if type(fn) == "function"
                        and not seenFunctions[fn]
                    then
                        seenFunctions[fn] =
                            true

                        local values =
                            Runtime
                                .GetOtherFunctionUpvalues(
                                    fn
                                )

                        if type(values)
                            == "table"
                        then
                            for _, value in pairs(values) do
                                if not Runtime
                                        .BasketballConfig
                                    and Runtime
                                        .IsBasketballConfig(
                                            value
                                        )
                                then
                                    Runtime
                                        .BasketballConfig =
                                        value
                                elseif not Runtime
                                        .BasketballUtils
                                    and Runtime
                                        .IsBasketballUtils(
                                            value
                                        )
                                then
                                    Runtime
                                        .BasketballUtils =
                                        value
                                end
                            end
                        end
                    end
                end
            end

            if Runtime
                    .BasketballConfig
                and Runtime
                    .BasketballUtils
            then
                break
            end
        end

        if Runtime.BasketballConfig then
            basketballShared.config =
                Runtime.BasketballConfig
        end

        if Runtime.BasketballUtils then
            basketballShared.utils =
                Runtime.BasketballUtils
        end
    end

    function Runtime.ResolveBasketball(
        forceGC
    )
        if Runtime.IsBasketballController(
            Runtime.BasketballController
        ) then
            Runtime
                .HydrateBasketballDependencies(
                    Runtime
                        .BasketballController
                )
            return Runtime.BasketballController
        end

        if Runtime.IsBasketballController(
            basketballShared.controller
        ) then
            Runtime.BasketballController =
                basketballShared.controller
            Runtime.BasketballAPI =
                basketballShared.api
                    or basketballShared.controller

            if Runtime.IsBasketballConfig(
                basketballShared.config
            ) then
                Runtime.BasketballConfig =
                    basketballShared.config
            end

            if Runtime.IsBasketballUtils(
                basketballShared.utils
            ) then
                Runtime.BasketballUtils =
                    basketballShared.utils
            end

            Runtime
                .HydrateBasketballDependencies(
                    Runtime
                        .BasketballController
                )

            return Runtime.BasketballController
        end

        local api = nil
        local controller = nil

        if Runtime.IsBasketballAPI(
            basketballShared.api
        ) then
            api = basketballShared.api
        end

        if Runtime.IsBasketballConfig(
            basketballShared.config
        ) then
            Runtime.BasketballConfig =
                basketballShared.config
        end

        if Runtime.IsBasketballUtils(
            basketballShared.utils
        ) then
            Runtime.BasketballUtils =
                basketballShared.utils
        end

        if api then
            local getFn =
                Runtime.GetOtherRawMethod(
                    api,
                    "Get"
                )

            if getFn then
                local okGet, value =
                    pcall(
                        getFn,
                        api
                    )

                if okGet
                    and Runtime
                        .IsBasketballController(
                            value
                        )
                then
                    controller =
                        value
                end
            end
        end

        if not controller then
            local serviceModule = nil
            local utilsModule = nil
            local configModule = nil

            pcall(function()
                local sharedFolder =
                    ReplicatedStorage
                        :FindFirstChild(
                            "Shared"
                        )
                local services =
                    sharedFolder
                    and sharedFolder
                        :FindFirstChild(
                            "Services"
                        )
                local basketball =
                    services
                    and services
                        :FindFirstChild(
                            "BasketballService"
                        )

                serviceModule =
                    basketball
                    and basketball
                        :FindFirstChild(
                            "BasketballServiceClient"
                        )
                utilsModule =
                    basketball
                    and basketball
                        :FindFirstChild(
                            "BasketballServiceUtils"
                        )
                configModule =
                    basketball
                    and basketball
                        :FindFirstChild(
                            "BasketballConfig"
                        )
            end)

            if serviceModule
                and serviceModule.Parent
            then
                local okRequire, value =
                    pcall(
                        require,
                        serviceModule
                    )

                if okRequire
                    and Runtime
                        .IsBasketballAPI(
                            value
                        )
                then
                    api = value

                    local getFn =
                        Runtime
                            .GetOtherRawMethod(
                                value,
                                "Get"
                            )

                    if getFn then
                        local okGet, result =
                            pcall(
                                getFn,
                                value
                            )

                        if okGet
                            and Runtime
                                .IsBasketballController(
                                    result
                                )
                        then
                            controller =
                                result
                        end
                    end
                end
            end

            if utilsModule
                and utilsModule.Parent
            then
                local ok, value =
                    pcall(
                        require,
                        utilsModule
                    )

                if ok
                    and Runtime
                        .IsBasketballUtils(
                            value
                        )
                then
                    Runtime.BasketballUtils =
                        value
                end
            end

            if configModule
                and configModule.Parent
            then
                local ok, value =
                    pcall(
                        require,
                        configModule
                    )

                if ok
                    and Runtime
                        .IsBasketballConfig(
                            value
                        )
                then
                    Runtime.BasketballConfig =
                        value
                end
            end
        end

        local nowClock = os.clock()
        local canScanGC =
            type(getgc) == "function"
            and (
                forceGC == true
                or not basketballShared.lastGCScan
                or nowClock
                    - basketballShared.lastGCScan
                    >= 2
            )

        if not controller and canScanGC then
            basketballShared.lastGCScan =
                nowClock

            local okGC, objects =
                pcall(getgc, true)

            if okGC
                and type(objects) == "table"
            then
                for _, object in ipairs(
                    objects
                ) do
                    if type(object) == "table" then
                        if not controller
                            and Runtime
                                .IsBasketballController(
                                    object
                                )
                        then
                            controller =
                                object
                        end

                        if not api
                            and Runtime
                                .IsBasketballAPI(
                                    object
                                )
                        then
                            api = object
                        end

                        if not Runtime
                                .BasketballConfig
                            and Runtime
                                .IsBasketballConfig(
                                    object
                                )
                        then
                            Runtime
                                .BasketballConfig =
                                object
                        end

                        if not Runtime
                                .BasketballUtils
                            and Runtime
                                .IsBasketballUtils(
                                    object
                                )
                        then
                            Runtime
                                .BasketballUtils =
                                object
                        end

                        if controller
                            and api
                            and Runtime
                                .BasketballConfig
                            and Runtime
                                .BasketballUtils
                        then
                            break
                        end
                    end
                end
            end
        end

        if not controller and api then
            local getFn =
                Runtime.GetOtherRawMethod(
                    api,
                    "Get"
                )

            if getFn then
                local okGet, value =
                    pcall(
                        getFn,
                        api
                    )

                if okGet
                    and Runtime
                        .IsBasketballController(
                            value
                        )
                then
                    controller =
                        value
                end
            end
        end

        if not controller then
            return nil
        end

        Runtime.BasketballController =
            controller
        Runtime.BasketballAPI =
            api or controller
        basketballShared.controller =
            controller
        basketballShared.api =
            api or controller

        Runtime
            .HydrateBasketballDependencies(
                controller
            )

        return controller
    end

    function Runtime.GetBasketballProperties(
        controller,
        character
    )
        local properties =
            controller
            and rawget(
                controller,
                "_properties"
            )

        if typeof(properties)
                == "Instance"
            and properties.Parent ~= nil
        then
            return properties
        end

        character =
            character
            or LocalPlayer.Character

        local candidate =
            character
            and character
                :FindFirstChild(
                    "BasketballProperties"
                )

        if typeof(candidate)
            == "Instance"
        then
            return candidate
        end

        return nil
    end

    function Runtime.GetBasketballTeam(
        character
    )
        local utils =
            Runtime.BasketballUtils
        local getTeam =
            Runtime.GetOtherRawMethod(
                utils,
                "GetTeam"
            )

        if getTeam then
            local ok, team =
                pcall(
                    getTeam,
                    character
                )

            if ok then
                return team
            end
        end

        return character
            and character:GetAttribute(
                "BasketballTeam"
            )
    end

    function Runtime.AreBasketballOpponents(
        a,
        b
    )
        local utils =
            Runtime.BasketballUtils
        local areOpponents =
            Runtime.GetOtherRawMethod(
                utils,
                "AreOpponents"
            )

        if areOpponents then
            local ok, result =
                pcall(
                    areOpponents,
                    a,
                    b
                )

            if ok then
                return result == true
            end
        end

        local aTeam =
            Runtime.GetBasketballTeam(
                a
            )
        local bTeam =
            Runtime.GetBasketballTeam(
                b
            )

        if aTeam and bTeam then
            return aTeam ~= bTeam
        end

        return true
    end

    function Runtime.GetBasketballGreenHold(
        controller
    )
        local character =
            LocalPlayer.Character
        local properties =
            Runtime.GetBasketballProperties(
                controller,
                character
            )

        local replicatedTarget =
            properties
            and properties:GetAttribute(
                "ShootTarget"
            )

        if typeof(replicatedTarget)
                == "number"
            and replicatedTarget > 0
        then
            return math.clamp(
                replicatedTarget,
                0.12,
                1
            )
        end

        local config =
            Runtime.BasketballConfig
            or {}
        local timings =
            type(
                config.SHOT_TIMINGS
            ) == "table"
            and config.SHOT_TIMINGS
            or {}

        local dunkReady =
            character
            and character:GetAttribute(
                "BasketballDunkReady"
            ) == true

        local dunking =
            properties
            and properties:GetAttribute(
                "Dunking"
            ) == true

        if dunkReady or dunking then
            return math.clamp(
                tonumber(
                    timings.Dunk
                ) or 0.45,
                0.20,
                0.80
            )
        end

        local selected =
            "Jumpshot"
        local humanoid =
            character
            and character
                :FindFirstChildOfClass(
                    "Humanoid"
                )
        local animator =
            humanoid
            and humanoid
                :FindFirstChildOfClass(
                    "Animator"
                )

        if animator then
            local okTracks, tracks =
                pcall(
                    animator
                        .GetPlayingAnimationTracks,
                    animator
                )

            if okTracks
                and type(tracks) == "table"
            then
                for _, track in ipairs(
                    tracks
                ) do
                    local animation =
                        track.Animation
                    local name =
                        string.lower(
                            tostring(
                                animation
                                    and animation.Name
                                    or track.Name
                                    or ""
                            )
                        )

                    if string.find(
                        name,
                        "dunk",
                        1,
                        true
                    ) then
                        selected = "Dunk"
                        break
                    elseif string.find(
                        name,
                        "layup",
                        1,
                        true
                    ) then
                        selected = "Layup"
                        break
                    elseif string.find(
                        name,
                        "floater",
                        1,
                        true
                    ) then
                        selected = "Floater"
                        break
                    elseif string.find(
                        name,
                        "fade",
                        1,
                        true
                    ) then
                        selected = "Fade"
                        break
                    elseif string.find(
                        name,
                        "close",
                        1,
                        true
                    ) then
                        selected = "Close"
                        break
                    elseif string.find(
                        name,
                        "hook",
                        1,
                        true
                    ) then
                        selected = "Hook"
                        break
                    elseif string.find(
                        name,
                        "shot",
                        1,
                        true
                    ) then
                        selected = "Jumpshot"
                        break
                    end
                end
            end
        end

        return math.clamp(
            tonumber(
                timings[selected]
            )
                or tonumber(
                    timings.Jumpshot
                )
                or 0.50,
            0.20,
            0.80
        )
    end

    function Runtime.GetBasketballGreenTiming()
        local config =
            Runtime.BasketballConfig
            or {}

        local timingWindow =
            tonumber(
                config.SHOT_TIMING_WINDOW
            ) or 0.10

        timingWindow =
            math.clamp(
                timingWindow,
                0.035,
                0.22
            )

        local fixedSchedulerLead =
            0.0015

        return timingWindow,
            fixedSchedulerLead
    end

    function Runtime.GetBasketballGreenTargetAt(
        controller
    )
        local properties =
            Runtime.GetBasketballProperties(
                controller
            )

        if not properties
            or properties.Parent == nil
        then
            return nil
        end

        local shooting =
            properties:GetAttribute(
                "Shooting"
            )
        local target =
            properties:GetAttribute(
                "ShootTarget"
            )

        if typeof(shooting)
                == "number"
            and typeof(target)
                == "number"
            and target > 0
        then
            return shooting + target,
                shooting,
                target
        end

        return nil
    end

    function Runtime.ReleaseBasketballGreen(
        controller,
        serial,
        downstream
    )
        if Flags.other_auto_basketball
                ~= true
            or Runtime.BasketballController
                ~= controller
            or Runtime.BasketballGreenSerial
                ~= serial
            or Runtime.BasketballGreenReleased
                == true
        then
            return false
        end

        Runtime.BasketballGreenReleased =
            true
        Runtime
            .BasketballGreenReleaseRequested =
            false

        if type(downstream)
            ~= "function"
        then
            return false
        end

        local ok =
            pcall(
                downstream,
                controller,
                false
            )

        return ok == true
    end

    function Runtime.RunBasketballGreenRelease(
        controller,
        serial,
        beginServerTime,
        downstream
    )
        task.spawn(function()
            local fallbackHold =
                Runtime
                    .GetBasketballGreenHold(
                        controller
                    )
            local fallbackAt =
                beginServerTime
                + fallbackHold

            local timingWindow,
                fixedSchedulerLead =
                Runtime
                    .GetBasketballGreenTiming()

            local authoritativeAt =
                nil
            local stableTargetAt =
                nil
            local stableShooting =
                nil
            local stableCount =
                0

            local lookupDeadline =
                os.clock() + 0.48

            while Flags
                    .other_auto_basketball
                    == true
                and Runtime
                    .BasketballController
                    == controller
                and Runtime
                    .BasketballGreenSerial
                    == serial
                and Runtime
                    .BasketballGreenReleased
                    ~= true
                and os.clock()
                    <= lookupDeadline
            do
                local targetAt,
                    shooting,
                    targetDuration =
                    Runtime
                        .GetBasketballGreenTargetAt(
                            controller
                        )

                local valid =
                    typeof(targetAt) == "number"
                    and typeof(shooting) == "number"
                    and typeof(targetDuration) == "number"
                    and targetDuration > 0
                    and shooting
                        >= beginServerTime - 0.10
                    and targetAt
                        >= beginServerTime + 0.10

                if valid then
                    local sameTarget =
                        typeof(stableTargetAt)
                            == "number"
                        and math.abs(
                            stableTargetAt
                                - targetAt
                        ) <= 0.0025
                        and typeof(stableShooting)
                            == "number"
                        and math.abs(
                            stableShooting
                                - shooting
                        ) <= 0.0025

                    if sameTarget then
                        stableCount += 1
                    else
                        stableTargetAt =
                            targetAt
                        stableShooting =
                            shooting
                        stableCount =
                            1
                    end

                    if stableCount >= 2 then
                        authoritativeAt =
                            stableTargetAt
                        break
                    end
                else
                    stableTargetAt =
                        nil
                    stableShooting =
                        nil
                    stableCount =
                        0
                end

                RunService
                    .Heartbeat:Wait()
            end

            local releaseAt =
                (
                    authoritativeAt
                    or fallbackAt
                )
                - fixedSchedulerLead

            local lastObservedTarget =
                authoritativeAt

            while Flags
                    .other_auto_basketball
                    == true
                and Runtime
                    .BasketballController
                    == controller
                and Runtime
                    .BasketballGreenSerial
                    == serial
                and Runtime
                    .BasketballGreenReleased
                    ~= true
            do
                local now =
                    Workspace
                        :GetServerTimeNow()

                local targetAt,
                    shooting,
                    targetDuration =
                    Runtime
                        .GetBasketballGreenTargetAt(
                            controller
                        )

                if typeof(targetAt)
                        == "number"
                    and typeof(shooting)
                        == "number"
                    and typeof(targetDuration)
                        == "number"
                    and targetDuration > 0
                    and shooting
                        >= beginServerTime - 0.10
                    and targetAt
                        >= beginServerTime + 0.10
                then
                    if typeof(lastObservedTarget)
                            ~= "number"
                        or math.abs(
                            targetAt
                                - lastObservedTarget
                        ) > 0.0025
                    then
                        lastObservedTarget =
                            targetAt
                        releaseAt =
                            targetAt
                            - fixedSchedulerLead
                    end
                end

                local lateness =
                    now - releaseAt

                if lateness
                    > math.max(
                        0.018,
                        timingWindow * 0.30
                    )
                    and typeof(lastObservedTarget)
                        == "number"
                then
                    releaseAt =
                        lastObservedTarget
                        - fixedSchedulerLead

                    lateness =
                        now - releaseAt
                end

                if now >= releaseAt then
                    break
                end

                RunService
                    .Heartbeat:Wait()
            end

            local finalTargetAt,
                finalShooting =
                Runtime
                    .GetBasketballGreenTargetAt(
                        controller
                    )

            if typeof(finalTargetAt)
                    == "number"
                and typeof(finalShooting)
                    == "number"
                and finalShooting
                    >= beginServerTime - 0.10
            then
                local finalReleaseAt =
                    finalTargetAt
                    - fixedSchedulerLead
                local now =
                    Workspace
                        :GetServerTimeNow()

                if finalReleaseAt
                    > now + 0.001
                then
                    while Flags
                            .other_auto_basketball
                            == true
                        and Runtime
                            .BasketballController
                            == controller
                        and Runtime
                            .BasketballGreenSerial
                            == serial
                        and Runtime
                            .BasketballGreenReleased
                            ~= true
                        and Workspace
                            :GetServerTimeNow()
                            < finalReleaseAt
                    do
                        RunService
                            .Heartbeat:Wait()
                    end
                end
            end

            Runtime.ReleaseBasketballGreen(
                controller,
                serial,
                downstream
            )
        end)
    end

    function Runtime.InstallBasketballAutoGreen()
        local controller =
            Runtime.ResolveBasketball(
                true
            )

        if not Runtime.IsBasketballController(
            controller
        )
            or type(hookfunction)
                ~= "function"
        then
            return false
        end

        local canonical =
            Runtime.GetOtherRawMethod(
                controller,
                "_sendShoot"
            )

        if type(canonical)
            ~= "function"
        then
            return false
        end

        if basketballShared.greenHookInstalled
                == true
            and basketballShared.greenHookVersion
                == 8
            and basketballShared.greenHookTarget
                == canonical
        then
            return true
        end

        local downstream = nil

        local function replacement(
            self,
            began,
            ...
        )
            local state =
                env.__SilentOtherBasketball
            local activeRuntime =
                state and state.runtime
            local activeFlags =
                state and state.flags

            if not activeRuntime
                or not activeFlags
                or activeFlags
                    .other_auto_basketball
                    ~= true
                or self
                    ~= activeRuntime
                        .BasketballController
            then
                return downstream(
                    self,
                    began,
                    ...
                )
            end

            if began == true then
                activeRuntime
                    .BasketballGreenSerial =
                    (
                        activeRuntime
                            .BasketballGreenSerial
                        or 0
                    ) + 1

                local serial =
                    activeRuntime
                        .BasketballGreenSerial
                local beginServerTime =
                    Workspace
                        :GetServerTimeNow()

                activeRuntime
                    .BasketballGreenReleased =
                    false
                activeRuntime
                    .BasketballGreenReleaseRequested =
                    false

                local result =
                    downstream(
                        self,
                        true,
                        ...
                    )

                activeRuntime
                    .RunBasketballGreenRelease(
                        self,
                        serial,
                        beginServerTime,
                        downstream
                    )

                return result
            end

            activeRuntime
                .BasketballGreenReleaseRequested =
                true

            return
        end

        local hook =
            replacement

        if type(newcclosure)
            == "function"
        then
            local okClosure, closure =
                pcall(
                    newcclosure,
                    replacement
                )

            if okClosure
                and type(closure)
                    == "function"
            then
                hook = closure
            end
        end

        local okHook, previous =
            pcall(
                hookfunction,
                canonical,
                hook
            )

        if not okHook
            or type(previous)
                ~= "function"
        then
            return false
        end

        downstream = previous

        basketballShared.greenOriginal =
            previous
        basketballShared.greenHookTarget =
            canonical
        basketballShared.greenHookReplacement =
            hook
        basketballShared.greenHookVersion =
            8
        basketballShared.greenHookInstalled =
            true

        return true
    end

    function Runtime.ReleaseBasketballGuard()
        if not Runtime.BasketballGuarding then
            return
        end

        Runtime.BasketballGuarding =
            false

        local controller =
            Runtime.ResolveBasketball()
        local guardFn =
            Runtime.GetOtherRawMethod(
                controller,
                "RequestGuard"
            )

        if guardFn then
            pcall(
                guardFn,
                controller,
                false
            )
        end
    end

    function Runtime.IsBasketballHolder(
        character
    )
        if not character
            or not character.Parent
        then
            return false
        end

        if character:GetAttribute(
            "BasketballHoldingBall"
        ) == true then
            return true
        end

        local properties =
            character:FindFirstChild(
                "BasketballProperties"
            )

        return properties ~= nil
            and properties:GetAttribute(
                "HoldBall"
            ) == true
    end

    function Runtime.FindBasketballThreat(
        maxDistance
    )
        local character =
            LocalPlayer.Character
        local root =
            character
            and character
                :FindFirstChild(
                    "HumanoidRootPart"
                )

        if not root then
            return nil
        end

        local bestCharacter = nil
        local bestDistance =
            tonumber(maxDistance)
            or math.huge

        for _, player in ipairs(
            Players:GetPlayers()
        ) do
            if player ~= LocalPlayer then
                local target =
                    player.Character

                if target
                    and Runtime
                        .IsBasketballHolder(
                            target
                        )
                    and Runtime
                        .AreBasketballOpponents(
                            character,
                            target
                        )
                then
                    local targetRoot =
                        target
                        :FindFirstChild(
                            "HumanoidRootPart"
                        )
                    local humanoid =
                        target
                        :FindFirstChildOfClass(
                            "Humanoid"
                        )

                    if targetRoot
                        and humanoid
                        and humanoid.Health > 0
                    then
                        local distance =
                            (
                                targetRoot.Position
                                - root.Position
                            ).Magnitude

                        if distance
                            <= bestDistance
                        then
                            bestCharacter =
                                target
                            bestDistance =
                                distance
                        end
                    end
                end
            end
        end

        return bestCharacter,
            bestDistance
    end

    function Runtime.IsBasketballDefending(
        character
    )
        if not character
            or not character.Parent
        then
            return false
        end

        if character:GetAttribute(
                "DefenseActive"
            ) == true
            or character:GetAttribute(
                "BasketballDefenseFacing"
            ) == true
        then
            return true
        end

        local properties =
            character:FindFirstChild(
                "BasketballProperties"
            )

        if properties then
            if properties:GetAttribute(
                    "Guarding"
                ) == true
                and properties:GetAttribute(
                    "Stealing"
                ) ~= true
                and properties:GetAttribute(
                    "Jumping"
                ) ~= true
            then
                return true
            end

            if properties:GetAttribute(
                    "Blocking"
                ) == true
            then
                return true
            end
        end

        return false
    end

    function Runtime.FindBasketballDefender(
        maxDistance
    )
        local character =
            LocalPlayer.Character
        local root =
            character
            and character
                :FindFirstChild(
                    "HumanoidRootPart"
                )

        if not root
            or not Runtime
                .IsBasketballHolder(
                    character
                )
        then
            return nil
        end

        local bestCharacter = nil
        local bestDistance =
            tonumber(maxDistance)
            or 8
        local bestLocalPosition = nil

        for _, player in ipairs(
            Players:GetPlayers()
        ) do
            if player ~= LocalPlayer then
                local target =
                    player.Character
                local humanoid =
                    target
                    and target
                        :FindFirstChildOfClass(
                            "Humanoid"
                        )
                local targetRoot =
                    target
                    and target
                        :FindFirstChild(
                            "HumanoidRootPart"
                        )

                if target
                    and humanoid
                    and humanoid.Health > 0
                    and targetRoot
                    and Runtime
                        .AreBasketballOpponents(
                            character,
                            target
                        )
                    and Runtime
                        .IsBasketballDefending(
                            target
                        )
                then
                    local offset =
                        targetRoot.Position
                        - root.Position
                    local distance =
                        offset.Magnitude

                    if distance
                        <= bestDistance
                    then
                        bestCharacter =
                            target
                        bestDistance =
                            distance
                        bestLocalPosition =
                            root.CFrame
                                :PointToObjectSpace(
                                    targetRoot.Position
                                )
                    end
                end
            end
        end

        return bestCharacter,
            bestDistance,
            bestLocalPosition
    end

    function Runtime.CanAutoBasketballDribble(
        controller,
        character
    )
        if Flags
                .other_basketball_auto_dribble
                == false
            or not character
            or not character.Parent
        then
            return false
        end

        local holdingFn =
            Runtime.GetOtherRawMethod(
                controller,
                "IsHoldingBall"
            )

        if holdingFn then
            local ok, holding =
                pcall(
                    holdingFn,
                    controller
                )

            if ok and holding ~= true then
                return false
            end
        elseif not Runtime
                .IsBasketballHolder(
                    character
                )
        then
            return false
        end

        local properties =
            character:FindFirstChild(
                "BasketballProperties"
            )

        if properties then
            if typeof(
                    properties:GetAttribute(
                        "Shooting"
                    )
                ) == "number"
                or properties:GetAttribute(
                    "ShootInput"
                ) == true
                or properties:GetAttribute(
                    "Dunking"
                ) == true
                or properties:GetAttribute(
                    "Jumping"
                ) == true
                or properties:GetAttribute(
                    "Stealing"
                ) == true
            then
                return false
            end
        end

        return true
    end

    function Runtime.TriggerBasketballDribble(
        controller,
        localPosition
    )
        local requestFn =
            Runtime.GetOtherRawMethod(
                controller,
                "RequestDribble"
            )

        if not requestFn then
            return false
        end

        local now =
            os.clock()
        local config =
            Runtime.BasketballConfig
            or {}
        local inputWindow =
            tonumber(
                config
                    .DRIBBLE_DOUBLE_INPUT_DURATION
            ) or 0.20
        local cooldown =
            math.max(
                0.72,
                inputWindow + 0.48
            )

        if now
                - (
                    Runtime
                        .BasketballLastDribble
                    or 0
                )
                < cooldown
        then
            return false
        end

        Runtime.BasketballLastDribble =
            now
        Runtime.BasketballDribbleSerial =
            (
                Runtime
                    .BasketballDribbleSerial
                or 0
            ) + 1

        local serial =
            Runtime.BasketballDribbleSerial
        local side =
            typeof(localPosition)
                    == "Vector3"
                and localPosition.X
                or 0

        local firstKey

        if side > 0.65 then
            firstKey = "Z"
        elseif side < -0.65 then
            firstKey = "C"
        else
            Runtime.BasketballDribbleSide =
                (
                    Runtime
                        .BasketballDribbleSide
                    or 0
                ) + 1

            firstKey =
                Runtime.BasketballDribbleSide
                    % 2
                    == 0
                and "Z"
                or "C"
        end

        local ok =
            pcall(
                requestFn,
                controller,
                firstKey
            )

        task.delay(
            math.clamp(
                inputWindow * 0.20,
                0.025,
                0.055
            ),
            function()
                if Flags
                        .other_auto_basketball
                        ~= true
                    or Flags
                        .other_basketball_auto_dribble
                        == false
                    or Runtime
                        .BasketballController
                        ~= controller
                    or Runtime
                        .BasketballDribbleSerial
                        ~= serial
                then
                    return
                end

                pcall(
                    requestFn,
                    controller,
                    "X"
                )
            end
        )

        return ok
    end

    function Runtime.GetBasketballShotThreat(
        target
    )
        if not target
            or not target.Parent
        then
            return false
        end

        local properties =
            target:FindFirstChild(
                "BasketballProperties"
            )

        if properties then
            local shooting =
                properties:GetAttribute(
                    "Shooting"
                )
            local targetTiming =
                properties:GetAttribute(
                    "ShootTarget"
                )

            if typeof(shooting)
                == "number"
            then
                local releaseAt =
                    typeof(targetTiming)
                            == "number"
                        and targetTiming > 0
                        and (
                            shooting
                            + targetTiming
                        )
                        or (
                            shooting
                            + 0.50
                        )

                return true,
                    shooting,
                    releaseAt,
                    "shoot"
            end

            if properties:GetAttribute(
                "Dunking"
            ) == true then
                return true,
                    "dunking",
                    Workspace
                        :GetServerTimeNow(),
                    "dunk"
            end

            if properties:GetAttribute(
                "ShootInput"
            ) == true then
                return true,
                    "shoot-input",
                    Workspace
                        :GetServerTimeNow()
                        + 0.12,
                    "shoot"
            end
        end

        local humanoid =
            target
            :FindFirstChildOfClass(
                "Humanoid"
            )
        local animator =
            humanoid
            and humanoid
                :FindFirstChildOfClass(
                    "Animator"
                )

        if animator then
            local ok, tracks =
                pcall(
                    animator
                        .GetPlayingAnimationTracks,
                    animator
                )

            if ok
                and type(tracks) == "table"
            then
                for _, track in ipairs(
                    tracks
                ) do
                    local animation =
                        track.Animation
                    local name =
                        string.lower(
                            tostring(
                                animation
                                    and animation.Name
                                    or track.Name
                                    or ""
                            )
                        )

                    for _, keyword in ipairs({
                        "jumpshot",
                        "shot",
                        "fade",
                        "layup",
                        "floater",
                        "close",
                        "hook",
                        "dunk",
                    }) do
                        if string.find(
                            name,
                            keyword,
                            1,
                            true
                        ) then
                            return true,
                                name,
                                Workspace
                                    :GetServerTimeNow()
                                    + 0.10,
                                keyword
                        end
                    end
                end
            end
        end

        return false
    end

    function Runtime.ShouldBasketballBlock(
        target
    )
        local isThreat,
            token,
            releaseAt,
            kind =
            Runtime.GetBasketballShotThreat(
                target
            )

        if not isThreat then
            return false
        end

        if Runtime
            .BasketballLastBlockedShot[
                target
            ] == token
        then
            return false
        end

        if kind == "dunk" then
            Runtime
                .BasketballLastBlockedShot[
                    target
                ] = token
            return true
        end

        local now =
            Workspace
                :GetServerTimeNow()
        local untilRelease =
            tonumber(releaseAt)
                and (
                    releaseAt - now
                )
                or 0

        if untilRelease <= 0.18
            and untilRelease >= -0.08
        then
            Runtime
                .BasketballLastBlockedShot[
                    target
                ] = token
            return true
        end

        return false
    end

    function Runtime.TriggerBasketballBlock(
        controller
    )
        local jumpFn =
            Runtime.GetOtherRawMethod(
                controller,
                "RequestJump"
            )

        if not jumpFn then
            return false
        end

        local ok =
            pcall(
                jumpFn,
                controller,
                true
            )

        task.delay(
            0.12,
            function()
                if Flags
                        .other_auto_basketball
                        == true
                    and Runtime
                        .BasketballController
                        == controller
                then
                    pcall(
                        jumpFn,
                        controller,
                        false
                    )
                end
            end
        )

        return ok
    end

    function Runtime.EnsureBasketballMode(
        controller
    )
        local activeFn =
            Runtime.GetOtherRawMethod(
                controller,
                "IsActive"
            )

        if activeFn then
            local ok, active =
                pcall(
                    activeFn,
                    controller
                )

            if ok and active == true then
                return true
            end
        end

        if os.clock()
                - (
                    Runtime
                        .BasketballModeRequestAt
                    or 0
                )
                < 1
        then
            return false
        end

        local canToggleFn =
            Runtime.GetOtherRawMethod(
                controller,
                "CanToggleMode"
            )
        local requestModeFn =
            Runtime.GetOtherRawMethod(
                controller,
                "RequestMode"
            )

        if not canToggleFn
            or not requestModeFn
        then
            return false
        end

        local okCan, canToggle =
            pcall(
                canToggleFn,
                controller
            )

        if not okCan
            or canToggle ~= true
        then
            return false
        end

        Runtime.BasketballModeRequestAt =
            os.clock()
        Runtime.BasketballModeOwned =
            true

        pcall(
            requestModeFn,
            controller,
            true
        )

        return false
    end

    function Runtime.BasketballTick()
        if Flags.other_auto_basketball
            ~= true
        then
            Runtime.ReleaseBasketballGuard()
            return
        end

        local controller =
            Runtime.ResolveBasketball()

        if not controller then
            return
        end

        if not Runtime
            .EnsureBasketballMode(
                controller
            )
        then
            Runtime.ReleaseBasketballGuard()
            return
        end

        local character =
            LocalPlayer.Character

        if not character then
            Runtime.ReleaseBasketballGuard()
            return
        end

        if Runtime
                .CanAutoBasketballDribble(
                    controller,
                    character
                )
        then
            local config =
                Runtime.BasketballConfig
                or {}
            local dribbleRange =
                math.clamp(
                    tonumber(
                        config
                            .CONTEST_MAGNITUDE
                    ) or 8,
                    5,
                    12
                )
            local defender,
                _defenderDistance,
                defenderLocalPosition =
                Runtime
                    .FindBasketballDefender(
                        dribbleRange
                    )

            if defender then
                Runtime.TriggerBasketballDribble(
                    controller,
                    defenderLocalPosition
                )
            end
        end

        local defendRange =
            tonumber(
                Flags
                    .other_basketball_defend_range
            ) or 12
        local stealRange =
            tonumber(
                Flags
                    .other_basketball_steal_range
            ) or 7
        local blockRange =
            tonumber(
                Flags
                    .other_basketball_block_range
            ) or 11

        local target, distance =
            Runtime.FindBasketballThreat(
                math.max(
                    defendRange,
                    stealRange,
                    blockRange
                )
            )

        local shouldGuard =
            target ~= nil
            and distance <= defendRange
            and Flags
                .other_basketball_auto_defend
                ~= false

        if shouldGuard
                ~= Runtime
                    .BasketballGuarding
        then
            local guardFn =
                Runtime.GetOtherRawMethod(
                    controller,
                    "RequestGuard"
                )

            if guardFn then
                Runtime.BasketballGuarding =
                    shouldGuard

                pcall(
                    guardFn,
                    controller,
                    shouldGuard
                )
            end
        end

        if target
            and distance <= stealRange
            and Flags
                .other_basketball_auto_steal
                ~= false
        then
            local config =
                Runtime.BasketballConfig
                or {}
            local cooldown =
                math.max(
                    0.75,
                    tonumber(
                        config.STEAL_DEBOUNCE
                    ) or 1
                )

            if os.clock()
                    - (
                        Runtime
                            .BasketballLastSteal
                        or 0
                    )
                    >= cooldown
            then
                local stealFn =
                    Runtime.GetOtherRawMethod(
                        controller,
                        "RequestSteal"
                    )

                if stealFn then
                    Runtime
                        .BasketballLastSteal =
                        os.clock()

                    pcall(
                        stealFn,
                        controller
                    )
                end
            end
        end

        if target
            and distance <= blockRange
            and Flags
                .other_basketball_auto_block
                ~= false
            and os.clock()
                - (
                    Runtime
                        .BasketballLastBlock
                    or 0
                )
                >= 0.72
            and Runtime
                .ShouldBasketballBlock(
                    target
                )
        then
            Runtime.BasketballLastBlock =
                os.clock()

            Runtime.TriggerBasketballBlock(
                controller
            )
        end
    end

    function Runtime.SetAutoBasketballEnabled(
        enabled
    )
        Runtime.BasketballLoopSerial =
            (
                Runtime
                    .BasketballLoopSerial
                or 0
            ) + 1

        local serial =
            Runtime.BasketballLoopSerial

        if enabled ~= true then
            Runtime.ReleaseBasketballGuard()
            Runtime.BasketballDribbleSerial =
                (
                    Runtime
                        .BasketballDribbleSerial
                    or 0
                ) + 1

            local controller =
                Runtime.BasketballController
            local original =
                basketballShared.greenOriginal

            if controller
                and type(original)
                    == "function"
                and Runtime
                    .BasketballGreenReleased
                    ~= true
            then
                Runtime
                    .BasketballGreenReleased =
                    true
                Runtime
                    .BasketballGreenReleaseRequested =
                    false

                pcall(
                    original,
                    controller,
                    false
                )
            end

            if Runtime.BasketballModeOwned
                and controller
            then
                local requestModeFn =
                    Runtime.GetOtherRawMethod(
                        controller,
                        "RequestMode"
                    )

                if requestModeFn then
                    pcall(
                        requestModeFn,
                        controller,
                        false
                    )
                end
            end

            Runtime.BasketballModeOwned =
                false
            return
        end

        Runtime.BasketballController =
            nil
        Runtime.BasketballModeOwned =
            false
        Runtime.BasketballLastDribble =
            0
        Runtime.BasketballDribbleSerial =
            (
                Runtime
                    .BasketballDribbleSerial
                or 0
            ) + 1

        local controller =
            Runtime.ResolveBasketball(
                true
            )

        if not controller then
            return
        end

        Runtime.InstallBasketballAutoGreen()

        task.spawn(function()
            while Flags.other_auto_basketball
                    == true
                and Runtime
                    .BasketballLoopSerial
                    == serial
            do
                Runtime.BasketballTick()
                task.wait(0.05)
            end

            Runtime.ReleaseBasketballGuard()
        end)
    end

    Runtime.AutoWrestleService = nil
    Runtime.AutoWrestleRemotes = nil
    Runtime.AutoWrestleInstalled = false
    Runtime.AutoWrestleSessionSerial = 0
    Runtime.AutoWrestleMatchLive = false

    function Runtime.IsArmWrestlingService(value)
        if type(value) ~= "table" then
            return false
        end

        local meta = getmetatable(value)
        local api =
            type(meta) == "table"
            and meta
            or value

        return type(value._answerBubble)
                == "function"
            or type(api._answerBubble)
                == "function"
    end

    function Runtime.ResolveArmWrestlingService()
        if Runtime.IsArmWrestlingService(
            Runtime.AutoWrestleService
        ) then
            return Runtime.AutoWrestleService
        end

        local best = nil
        local bestScore = -1

        local function consider(candidate)
            if not Runtime.IsArmWrestlingService(
                candidate
            ) then
                return
            end

            local score = 1
            if type(rawget(candidate, "_bubbles"))
                == "table"
            then
                score += 4
            end
            if rawget(candidate, "_matchLive")
                == true
            then
                score += 3
            end

            if score > bestScore then
                best = candidate
                bestScore = score
            end
        end

        local module
        pcall(function()
            local sharedFolder =
                ReplicatedStorage:FindFirstChild(
                    "Shared"
                )
            local services =
                sharedFolder
                and sharedFolder:FindFirstChild(
                    "Services"
                )
            local arm =
                services
                and services:FindFirstChild(
                    "ArmWrestlingService"
                )
            module =
                arm
                and arm:FindFirstChild(
                    "ArmWrestlingServiceClient"
                )
        end)

        if module and module.Parent ~= nil then
            local ok, service =
                pcall(require, module)
            if ok then
                consider(service)
            end
        end

        if type(getloadedmodules)
            == "function"
        then
            pcall(function()
                for _, loaded in ipairs(
                    getloadedmodules()
                ) do
                    if typeof(loaded)
                            == "Instance"
                        and loaded:IsA(
                            "ModuleScript"
                        )
                        and loaded.Parent ~= nil
                        and string.find(
                            string.lower(
                                loaded.Name
                            ),
                            "armwrest",
                            1,
                            true
                        )
                    then
                        local ok, service =
                            pcall(
                                require,
                                loaded
                            )
                        if ok then
                            consider(service)
                        end
                    end
                end
            end)
        end

        if type(getgc) == "function" then
            pcall(function()
                for _, object in ipairs(
                    getgc(true)
                ) do
                    if type(object) == "table" then
                        consider(object)
                    end
                end
            end)
        end

        Runtime.AutoWrestleService =
            best

        return Runtime.AutoWrestleService
    end

    function Runtime.ResolveArmWrestlingRemotes()
        local cached = Runtime.AutoWrestleRemotes
        if cached
            and cached.SpawnBubble and cached.SpawnBubble.Parent
            and cached.ReportBubble and cached.ReportBubble.Parent
            and cached.SessionStatus and cached.SessionStatus.Parent
        then
            return cached
        end

        local remotes = ReplicatedStorage:FindFirstChild("Remotes")
        local folder = remotes and remotes:FindFirstChild("ArmWrestling")
        if not folder then
            return nil
        end

        cached = {
            SpawnBubble = folder:FindFirstChild("SpawnBubble"),
            ReportBubble = folder:FindFirstChild("ReportBubble"),
            SessionStatus = folder:FindFirstChild("SessionStatus"),
        }
        if not cached.SpawnBubble
            or not cached.ReportBubble
            or not cached.SessionStatus
        then
            return nil
        end

        Runtime.AutoWrestleRemotes = cached
        return cached
    end

    function Runtime.AnswerArmBubble(bubbleId, keyIndex, serial)
        if Flags.other_auto_wrestling ~= true
            or serial ~= Runtime.AutoWrestleSessionSerial
        then
            return false
        end

        local service = Runtime.ResolveArmWrestlingService()
        if service and service._bubbles then
            local bubble = service._bubbles[bubbleId]
            if bubble and bubble.answered ~= true then
                local ok = pcall(service._answerBubble, service, bubble, keyIndex)
                if ok then
                    return true
                end
            end
        end

        local remotes = Runtime.ResolveArmWrestlingRemotes()
        if remotes and remotes.ReportBubble then
            return pcall(
                remotes.ReportBubble.FireServer,
                remotes.ReportBubble,
                bubbleId,
                keyIndex,
                workspace:GetServerTimeNow()
            )
        end
        return false
    end

    function Runtime.ScheduleArmBubble(bubbleId, keyIndex, hitAt)
        if Flags.other_auto_wrestling ~= true then
            return
        end

        bubbleId = tonumber(bubbleId)
        keyIndex = tonumber(keyIndex)
        hitAt = tonumber(hitAt)
        if not bubbleId or not keyIndex or not hitAt then
            return
        end

        local serial = Runtime.AutoWrestleSessionSerial
        local targetAt = hitAt - 0.008
        task.spawn(function()
            while Flags.other_auto_wrestling == true
                and serial == Runtime.AutoWrestleSessionSerial
            do
                local remaining = targetAt - workspace:GetServerTimeNow()
                if remaining <= 0 then
                    break
                end
                if remaining > 0.055 then
                    task.wait(math.max(0.001, math.min(0.05, remaining - 0.035)))
                else
                    RunService.Heartbeat:Wait()
                end
            end

            if Flags.other_auto_wrestling == true
                and serial == Runtime.AutoWrestleSessionSerial
                and workspace:GetServerTimeNow() - hitAt <= 0.30
            then
                Runtime.AnswerArmBubble(bubbleId, keyIndex, serial)
            end
        end)
    end

    function Runtime.InstallAutoWrestling()
        if Runtime.AutoWrestleInstalled then
            return true
        end
        local remotes = Runtime.ResolveArmWrestlingRemotes()
        if not remotes then
            return false
        end

        Runtime.AutoWrestleInstalled = true
        Connect(remotes.SessionStatus.OnClientEvent, function(status)
            status = tostring(status or "")
            if status == "start" then
                Runtime.AutoWrestleMatchLive = true
                Runtime.AutoWrestleSessionSerial += 1
            elseif status == "end" or status == "left" then
                Runtime.AutoWrestleMatchLive = false
                Runtime.AutoWrestleSessionSerial += 1
            end
        end)

        Connect(remotes.SpawnBubble.OnClientEvent, function(
            bubbleId,
            keyIndex,
            _spawnAt,
            hitAt
        )
            if Flags.other_auto_wrestling == true then
                Runtime.AutoWrestleMatchLive = true
                Runtime.ScheduleArmBubble(bubbleId, keyIndex, hitAt)
            end
        end)
        return true
    end

    function Runtime.SetAutoWrestlingEnabled(enabled)
        Runtime.AutoWrestleSessionSerial += 1
        if enabled == true then
            Runtime.AutoWrestleService = nil
            Runtime.ResolveArmWrestlingService()
            Runtime.InstallAutoWrestling()
        end
    end

