    Runtime.ChessVisualSerial = 0
    Runtime.ChessCurrentBestMove = nil
    Runtime.ChessCurrentBestMoveFEN = nil
    Runtime.ChessStatusText = "Disabled"
    Runtime.ChessBootstrappedInitial = false

    Runtime.ChessTableId = nil
    Runtime.ChessMyColor = nil
    Runtime.ChessSeatColor = nil
    Runtime.ChessFEN = nil
    Runtime.ChessActive = false
    Runtime.ChessSolo = false
    Runtime.ChessSearchSerial = 0
    Runtime.ChessAnalysisInFlight = false
    Runtime.ChessAnalysisFEN = nil
    Runtime.ChessPendingAnalysis = false
    Runtime.ChessPendingAnalysisReason = nil
    Runtime.ChessBestMoveFolder = nil
    Runtime.ChessStockfishCache = {}
    Runtime.ChessListenersInstalled = false
