        game:GetService("CollectionService")

    Runtime.ResolveChessModules = function()
        if Runtime.ChessModules then
            return Runtime.ChessModules
        end

        local shared = ReplicatedStorage:FindFirstChild("Shared")
        local chess = shared and shared:FindFirstChild("Chess")
        if not chess then
            return nil
        end

        local ok, result = pcall(function()
            return {
                Board = require(chess:WaitForChild("Board")),
                Engine = require(chess:WaitForChild("Engine")),
                Moves = require(chess:WaitForChild("Moves")),
                Eval = require(chess:WaitForChild("Eval")),
                ChessTags = require(chess:WaitForChild("ChessTags")),
                BoardGeometry = require(chess:WaitForChild("BoardGeometry")),
            }
        end)

        if not ok or type(result) ~= "table" then
            return nil
        end

        Runtime.ChessModules = result
        return result
    end

    Runtime.ResolveChessRemotes = function()
        local cached = Runtime.ChessRemotes
        if cached and cached.Event and cached.Function
            and cached.Event.Parent and cached.Function.Parent then
            return cached
        end

        local remotes = ReplicatedStorage:FindFirstChild("Remotes")
        if not remotes then
            return nil
        end

        local event = remotes:FindFirstChild("ChessEvent")
        local func = remotes:FindFirstChild("ChessFunction")

        if not (event and event:IsA("RemoteEvent")) then
            return nil
        end
        if not (func and func:IsA("RemoteFunction")) then
            return nil
        end

        Runtime.ChessRemotes = {Event = event, Function = func}
        return Runtime.ChessRemotes
    end

    Runtime.ClearChessBestMove = function(clearRecommendation)
        if clearRecommendation ~= false then
            Runtime.ChessVisualSerial =
                (
                    Runtime.ChessVisualSerial
                    or 0
                ) + 1
        end

        if Runtime.ChessBestMoveFolder then
            pcall(function()
                Runtime.ChessBestMoveFolder:Destroy()
            end)
            Runtime.ChessBestMoveFolder = nil
        end

        if clearRecommendation ~= false then
            Runtime.ChessCurrentBestMove = nil
            Runtime.ChessCurrentBestMoveFEN = nil
        end
    end

    Runtime.GetChessBoardModel = function()
        local modules = Runtime.ResolveChessModules()
        if not modules then
            return nil
        end

        local tableId =
            Runtime.ChessTableId
            or Runtime.ChessAuthoritativeTableId

        if tableId then
            local ok, board =
                pcall(
                    modules.ChessTags.findBoard,
                    tostring(tableId)
                )

            if ok and board and board.Parent then
                return board
            end
        end

        local character =
            LocalPlayer.Character
        local humanoid =
            character
            and character:FindFirstChildOfClass(
                "Humanoid"
            )
        local seat =
            humanoid
            and humanoid.SeatPart

        if seat then
            local ok, board =
                pcall(
                    modules.ChessTags.findBoardForSeat,
                    seat
                )

            if ok and board and board.Parent then
                return board
            end
        end

        if tableId
            and Runtime.ChessCollectionService
        then
            local okTagged, tagged =
                pcall(
                    Runtime.ChessCollectionService.GetTagged,
                    Runtime.ChessCollectionService,
                    "ChessBoard"
                )

            if okTagged and type(tagged) == "table" then
                for _, board in ipairs(tagged) do
                    if board and board.Parent then
                        local id =
                            board:GetAttribute(
                                "ChessBoardID"
                            )

                        if id ~= nil
                            and tostring(id)
                                == tostring(tableId)
                        then
                            return board
                        end
                    end
                end
            end
        end

        return nil
    end

    Runtime.NormalizeChessColor = function(
        value
    )
        if value == "w"
            or value == "W"
            or value == "white"
            or value == "White"
            or value == "WHITE"
        then
            return "w"
        end

        if value == "b"
            or value == "B"
            or value == "black"
            or value == "Black"
            or value == "BLACK"
        then
            return "b"
        end

        return nil
    end

    Runtime.SeatMatchesChessSeat = function(
        seatPart,
        chessSeat
    )
        if not seatPart
            or not chessSeat
        then
            return false
        end

        if seatPart == chessSeat then
            return true
        end

        local current =
            seatPart.Parent

        for _ = 1, 5 do
            if not current then
                break
            end

            if current == chessSeat then
                return true
            end

            current =
                current.Parent
        end

        current =
            chessSeat.Parent

        for _ = 1, 5 do
            if not current then
                break
            end

            if current == seatPart then
                return true
            end

            current =
                current.Parent
        end

        return false
    end

    Runtime.GetOccupiedChessSeat = function()
        local character =
            LocalPlayer.Character
        local humanoid =
            character
            and character:FindFirstChildOfClass(
                "Humanoid"
            )

        if not humanoid then
            return nil, nil
        end

        local seat =
            humanoid.SeatPart

        if seat then
            local directId =
                seat:GetAttribute(
                    "ChessSeatID"
                )

            if directId ~= nil then
                return seat, humanoid
            end

            local modules =
                Runtime.ResolveChessModules()

            if modules then
                local okId, seatId =
                    pcall(
                        modules.ChessTags.getSeatId,
                        seat
                    )

                if okId and seatId ~= nil then
                    return seat, humanoid
                end
            end
        end

        if Runtime.ChessCollectionService then
            local okTagged, tagged =
                pcall(
                    Runtime.ChessCollectionService.GetTagged,
                    Runtime.ChessCollectionService,
                    "ChessSeat"
                )

            if okTagged and type(tagged) == "table" then
                for _, candidate in ipairs(tagged) do
                    if candidate
                        and candidate.Parent
                        and (
                            candidate:IsA("Seat")
                            or candidate:IsA("VehicleSeat")
                        )
                    then
                        local okOccupant, occupant =
                            pcall(function()
                                return candidate.Occupant
                            end)

                        if okOccupant
                            and occupant == humanoid
                        then
                            return candidate, humanoid
                        end
                    end
                end
            end
        end

        return seat, humanoid
    end

    Runtime.DetectChessSeatColor = function()
        local modules =
            Runtime.ResolveChessModules()

        if not modules then
            return nil, nil, nil
        end

        local seat, humanoid =
            Runtime.GetOccupiedChessSeat()

        Runtime.ChessPhysicalSeat =
            seat

        if not seat then
            return nil, nil, nil
        end

        local detectedTableId = nil
        local detectedColor = nil

        local function parseCurrentSeatId(
            seatId
        )
            if typeof(seatId) ~= "string" then
                return nil, nil
            end

            local tableId, side =
                seatId:match(
                    "^(.-)_(%a+)$"
                )

            if not tableId
                or tableId == ""
            then
                return nil, nil
            end

            if side == "White"
                or string.lower(side) == "white"
            then
                return tostring(tableId), "w"
            elseif side == "Black"
                or string.lower(side) == "black"
            then
                return tostring(tableId), "b"
            end

            return nil, nil
        end

        local directSeatId =
            seat:GetAttribute(
                "ChessSeatID"
            )

        if directSeatId == nil then
            local value =
                seat:FindFirstChild(
                    "ChessSeatID"
                )

            if value
                and value:IsA("ValueBase")
            then
                directSeatId =
                    value.Value
            end
        end

        detectedTableId,
            detectedColor =
            parseCurrentSeatId(
                directSeatId
            )

        local okId, seatId =
            pcall(
                modules.ChessTags.getSeatId,
                seat
            )

        if okId and seatId ~= nil then
            local okParse,
                tableId,
                color =
                pcall(
                    modules.ChessTags.parseSeatId,
                    seatId
                )

            if okParse then
                if not detectedTableId
                    and tableId ~= nil
                then
                    detectedTableId =
                        tostring(tableId)
                end

                if not detectedColor then
                    detectedColor =
                        Runtime.NormalizeChessColor(
                            color
                        )
                end
            end
        end

        if detectedTableId
            and not detectedColor
        then
            for _, candidate in ipairs({
                "w",
                "b",
            }) do
                local okSeat, chessSeat =
                    pcall(
                        modules.ChessTags.findSeatForBoard,
                        tostring(detectedTableId),
                        candidate
                    )

                if okSeat
                    and chessSeat
                    and (
                        Runtime.SeatMatchesChessSeat(
                            seat,
                            chessSeat
                        )
                        or (
                            humanoid
                            and chessSeat.Occupant
                                == humanoid
                        )
                    )
                then
                    detectedColor =
                        candidate
                    break
                end
            end
        end

        if (
            not detectedTableId
            or not detectedColor
        )
            and Runtime.ChessCollectionService
        then
            local okTagged, tagged =
                pcall(
                    Runtime.ChessCollectionService.GetTagged,
                    Runtime.ChessCollectionService,
                    "ChessSeat"
                )

            if okTagged
                and type(tagged) == "table"
            then
                for _, candidate in ipairs(tagged) do
                    local okOccupant, occupant =
                        pcall(function()
                            return candidate.Occupant
                        end)

                    if okOccupant
                        and occupant == humanoid
                    then
                        local tableId, color =
                            parseCurrentSeatId(
                                candidate:GetAttribute(
                                    "ChessSeatID"
                                )
                            )

                        detectedTableId =
                            detectedTableId
                            or tableId
                        detectedColor =
                            detectedColor
                            or color

                        if detectedTableId
                            and detectedColor
                        then
                            seat = candidate
                            Runtime.ChessPhysicalSeat =
                                candidate
                            break
                        end
                    end
                end
            end
        end

        if detectedTableId
            and Runtime.ChessTableId
            and tostring(Runtime.ChessTableId)
                ~= tostring(detectedTableId)
        then
            Runtime.ChessMyColor = nil
            Runtime.ChessSeatColor = nil
            Runtime.ChessGoesFirst = nil
            Runtime.ChessAuthoritativeFEN = nil
            Runtime.ChessAuthoritativeTableId = nil
        end

        if detectedTableId then
            Runtime.ChessTableId =
                tostring(detectedTableId)
        end

        if detectedColor then
            Runtime.ChessSeatColor =
                detectedColor
            Runtime.ChessMyColor =
                detectedColor
            Runtime.ChessGoesFirst =
                detectedColor == "w"
        end

        return detectedColor,
            detectedTableId,
            seat
    end

    Runtime.RefreshChessSeatState = function()
        local color,
            tableId,
            seat =
            Runtime
                .DetectChessSeatColor()

        Runtime.ChessPhysicalSeat =
            seat

        if tableId then
            Runtime.ChessTableId =
                tostring(tableId)
        end

        if color == "w"
            or color == "b"
        then
            Runtime.ChessSeatColor =
                color
            Runtime.ChessMyColor =
                color
            Runtime.ChessGoesFirst =
                color == "w"
            return color
        end

        return Runtime.ChessSeatColor
            or Runtime.ChessMyColor
    end

    Runtime.SetChessStatus = function(textValue)
        Runtime.ChessStatusText = tostring(textValue or "")

        if Runtime.ChessStatusLabel
            and type(Runtime.ChessStatusLabel.SetText) == "function" then
            Runtime.ChessStatusLabel:SetText(
                "Status: " .. Runtime.ChessStatusText
            )
        end
    end

    Runtime.GetChessSeatOccupancy = function()
        local modules = Runtime.ResolveChessModules()

        if not modules
            or not Runtime.ChessTableId
            or not Runtime.ChessSeatColor then
            return false, false
        end

        local mySeat = nil
        local otherSeat = nil

        local okMine, mine = pcall(
            modules.ChessTags.findSeatForBoard,
            Runtime.ChessTableId,
            Runtime.ChessSeatColor
        )

        if okMine then
            mySeat = mine
        end

        local otherColor =
            Runtime.ChessSeatColor == "w"
            and "b"
            or "w"

        local okOther, other = pcall(
            modules.ChessTags.findSeatForBoard,
            Runtime.ChessTableId,
            otherColor
        )

        if okOther then
            otherSeat = other
        end

        local function occupied(seat)
            if not seat then
                return false
            end

            local ok, occupant = pcall(function()
                return seat.Occupant
            end)

            return ok and occupant ~= nil
        end

        return occupied(mySeat), occupied(otherSeat)
    end

    Runtime.CountPhysicalChessPieces = function(board)
        if not board then
            return 0
        end

        local pieceNames = {
            King = true,
            Queen = true,
            Bishop = true,
            Knight = true,
            Rook = true,
            Pawn = true,
        }

        local count = 0

        for _, sideName in ipairs({"White", "Black"}) do
            local side = board:FindFirstChild(sideName)

            if side then
                for _, object in ipairs(side:GetDescendants()) do
                    if object:IsA("BasePart")
                        and pieceNames[object.Name] then
                        count += 1
                    end
                end
            end
        end

        return count
    end

    Runtime.BootstrapChessInitialState = function()
        Runtime.RefreshChessSeatState()

        local modules = Runtime.ResolveChessModules()

        if not modules
            or not modules.Board
            or not Runtime.ChessTableId
            or not Runtime.ChessSeatColor then
            return false
        end

        local board = Runtime.GetChessBoardModel()
        if not board then
            return false
        end

        local myOccupied, opponentOccupied =
            Runtime.GetChessSeatOccupancy()

        if not myOccupied or not opponentOccupied then
            return false
        end

        local pieceCount =
            Runtime.CountPhysicalChessPieces(board)

        if pieceCount == 32
            and (
                type(Runtime.ChessFEN) ~= "string"
                or Runtime.ChessActive ~= true
            ) then
            Runtime.ChessFEN = modules.Board.START_FEN
            Runtime.ChessActive = true
            Runtime.ChessSolo = false
            Runtime.ChessBootstrappedInitial = true

            if Runtime.ChessSeatColor == "w" then
                Runtime.SetChessStatus("White • Your turn")
            else
                Runtime.SetChessStatus("Black • Waiting for White")
            end

            return true
        end

        return false
    end

    Runtime.FindNativeChessState = function(force)
        local remotes = Runtime.ResolveChessRemotes()
        if not remotes then
            return Runtime.ChessNativeState
        end

        local function isContext(value)
            return type(value) == "table"
                and rawget(value, "RemoteFunction") == remotes.Function
                and rawget(value, "RemoteEvent") == remotes.Event
        end

        local function isChessState(value)
            if type(value) ~= "table" then
                return false
            end

            local ctx = rawget(value, "ctx")
            local mirror = rawget(value, "mirror")

            if isContext(ctx) then
                return true
            end

            return rawget(value, "legalTargets") ~= nil
                and rawget(value, "spectating") ~= nil
                and (
                    mirror ~= nil
                    or rawget(value, "tableId") ~= nil
                    or rawget(value, "seated") ~= nil
                )
        end

        local function accept(value)
            if isChessState(value) then
                Runtime.ChessNativeState = value

                local ctx = rawget(value, "ctx")
                if isContext(ctx) then
                    Runtime.ChessNativeContext = ctx
                end

                return value
            end

            if isContext(value) then
                Runtime.ChessNativeContext = value

                local chessState = rawget(value, "Chess")
                if isChessState(chessState) then
                    Runtime.ChessNativeState = chessState
                    return chessState
                end
            end

            return nil
        end

        if not force then
            local cached = accept(Runtime.ChessNativeState)
            if cached then
                return cached
            end

            if isContext(Runtime.ChessNativeContext) then
                local cachedContextState =
                    accept(rawget(Runtime.ChessNativeContext, "Chess"))

                if cachedContextState then
                    return cachedContextState
                end
            end
        end

        local function inspectFunction(fn)
            if type(fn) ~= "function" then
                return nil
            end

            local exploitGetUpvalues =
                rawget(getgenv and getgenv() or _G, "getupvalues")

            if type(exploitGetUpvalues) == "function" then
                local ok, upvalues = pcall(exploitGetUpvalues, fn)

                if ok and type(upvalues) == "table" then
                    for _, value in pairs(upvalues) do
                        local found = accept(value)
                        if found then
                            return found
                        end
                    end
                end
            end

            if debug and type(debug.getupvalue) == "function" then
                for index = 1, 40 do
                    local ok, _, value = pcall(
                        debug.getupvalue,
                        fn,
                        index
                    )

                    if not ok or value == nil then
                        break
                    end

                    local found = accept(value)
                    if found then
                        return found
                    end
                end
            end

            return nil
        end

        if type(getconnections) == "function" then
            local ok, connections = pcall(
                getconnections,
                remotes.Event.OnClientEvent
            )

            if ok and type(connections) == "table" then
                for _, connection in ipairs(connections) do
                    local fn = nil

                    pcall(function()
                        fn = connection.Function
                    end)

                    if type(fn) ~= "function" then
                        pcall(function()
                            fn = connection.Callback
                        end)
                    end

                    local found = inspectFunction(fn)
                    if found then
                        return found
                    end
                end
            end
        end

        if type(getgc) ~= "function" then
            return Runtime.ChessNativeState
        end

        local ok, objects = pcall(getgc, true)
        if not ok or type(objects) ~= "table" then
            return Runtime.ChessNativeState
        end

        for _, object in ipairs(objects) do
            if type(object) == "table" then
                local found = accept(object)
                if found then
                    return found
                end
            end
        end

        for _, object in ipairs(objects) do
            if type(object) == "function" then
                local found = inspectFunction(object)
                if found then
                    return found
                end
            end
        end

        return Runtime.ChessNativeState
    end

    Runtime.SyncChessNativeState = function(force)
        Runtime.RefreshChessSeatState()

        local native = Runtime.FindNativeChessState(force)
        if type(native) ~= "table" then
            return false
        end

        local oldFen = Runtime.ChessFEN
        local oldTableId = Runtime.ChessTableId
        local oldActive = Runtime.ChessActive

        local tableId = rawget(native, "tableId")
        if tableId ~= nil then
            Runtime.ChessTableId = tostring(tableId)
        end

        local seatColor =
            Runtime.NormalizeChessColor(
                rawget(native, "seatColor")
            )
        local myColor =
            Runtime.NormalizeChessColor(
                rawget(native, "myColor")
            )
        local yourColor =
            Runtime.NormalizeChessColor(
                rawget(native, "yourColor")
            )
        local directColor =
            Runtime.NormalizeChessColor(
                rawget(native, "color")
            )

        local resolvedColor =
            Runtime.ChessSeatColor
            or seatColor
            or yourColor
            or myColor
            or directColor

        if resolvedColor == "w"
            or resolvedColor == "b"
        then
            Runtime.ChessSeatColor =
                resolvedColor
            Runtime.ChessMyColor =
                resolvedColor
            Runtime.ChessGoesFirst =
                resolvedColor == "w"
        end

        Runtime.ChessSolo =
            rawget(native, "solo") == true

        local nativeActive =
            rawget(native, "active") == true

        Runtime.ChessActive =
            Runtime.ChessAuthoritativeFEN ~= nil
            or nativeActive

        local mirror = rawget(native, "mirror")
        local fen = nil

        if type(mirror) == "table" then
            if type(mirror.fen) == "function" then
                local okFen, result = pcall(mirror.fen, mirror)
                if okFen and type(result) == "string" then
                    fen = result
                end
            end

            if not fen and type(mirror.state) == "table" then
                local modules = Runtime.ResolveChessModules()
                if modules and modules.Board then
                    local okFen, result = pcall(
                        modules.Board.toFEN,
                        mirror.state
                    )
                    if okFen and type(result) == "string" then
                        fen = result
                    end
                end
            end
        end

        if type(Runtime.ChessAuthoritativeFEN)
            == "string"
        then
            Runtime.ChessFEN =
                Runtime.ChessAuthoritativeFEN
        elseif fen then
            Runtime.ChessFEN = fen
        elseif not Runtime.ChessActive then
            Runtime.ChessFEN = nil
        end

        if Runtime.ChessActive
            and type(Runtime.ChessFEN) == "string" then
            local side = Runtime.ChessFEN:match("^%S+%s+([wb])")
            local myColor = Runtime.ChessSeatColor or Runtime.ChessMyColor

            if side and myColor then
                if side == myColor then
                    Runtime.SetChessStatus(
                        myColor == "w"
                        and "White • Your turn"
                        or "Black • Your turn"
                    )
                else
                    Runtime.SetChessStatus(
                        myColor == "w"
                        and "White • Waiting for Black"
                        or "Black • Waiting for White"
                    )
                end
            end
        end

        return oldFen ~= Runtime.ChessFEN
            or oldTableId ~= Runtime.ChessTableId
            or oldActive ~= Runtime.ChessActive
    end

    Runtime.GetChessLiveGeometry = function(
        fen,
        forceNative
    )
        local native =
            Runtime.FindNativeChessState(
                forceNative == true
            )

        if type(native) == "table" then
            local boardView = rawget(native, "boardView")

            if type(boardView) == "table" then
                local geo = rawget(boardView, "geo")
                local board = rawget(boardView, "board")

                if geo
                    and type(geo.squareToWorld) == "function" then
                    return geo, board
                end
            end
        end

        local modules = Runtime.ResolveChessModules()
        local board = Runtime.GetChessBoardModel()

        if not modules or not board then
            return nil, board
        end

        local ok, geo = pcall(
            modules.BoardGeometry.new,
            board,
            fen
        )

        if ok and geo then
            return geo, board
        end

        return nil, board
    end

    Runtime.RefreshChessBestMoveVisual = function()
        local fen =
            Runtime.ChessCurrentBestMoveFEN
        local move =
            Runtime.ChessCurrentBestMove

        if type(fen) == "string"
            and type(move) == "table"
        then
            Runtime.ShowChessBestMove(
                fen,
                move
            )
        end
    end

    Runtime.ShowChessBestMove = function(
        fen,
        move
    )
        Runtime.ChessCurrentBestMove =
            move
        Runtime.ChessCurrentBestMoveFEN =
            fen
        Runtime.ChessVisualSerial =
            (
                Runtime.ChessVisualSerial
                or 0
            ) + 1

        local visualSerial =
            Runtime.ChessVisualSerial

        Runtime.ClearChessBestMove(false)

        if type(fen) ~= "string"
            or type(move) ~= "table"
        then
            return
        end

        local function render()
            if visualSerial
                    ~= Runtime
                        .ChessVisualSerial
                or Runtime
                    .ChessCurrentBestMove
                    ~= move
                or Runtime
                    .ChessCurrentBestMoveFEN
                    ~= fen
            then
                return true
            end

            Runtime.RefreshChessSeatState()

            local geo =
                Runtime
                    .GetChessLiveGeometry(
                        fen,
                        false
                    )

            if not geo then
                return false
            end

            local folder =
                Instance.new("Folder")
            folder.Name =
                "Silent.solutionsChessBestMove"
            folder.Parent =
                workspace
            Runtime.ChessBestMoveFolder =
                folder

            local menuColors =
                Menu.colors or {}
            local fromColor =
                typeof(menuColors.accent) == "Color3"
                and menuColors.accent
                or Color3.fromRGB(
                    224,
                    211,
                    180
                )
            local toColor =
                Color3.fromRGB(
                    92,
                    214,
                    120
                )
            local upVector =
                geo.plateCFrame
                and geo
                    .plateCFrame
                    .UpVector
                or Vector3.new(
                    0,
                    1,
                    0
                )
            local rotation =
                geo.plateCFrame
                and geo
                    .plateCFrame
                    .Rotation
                or CFrame.identity
            local cell =
                tonumber(geo.cell)
                or 1

            local function createHighlight(
                square,
                color,
                name
            )
                if type(square) ~= "number" then
                    return nil
                end

                local okWorld, world =
                    pcall(
                        geo.squareToWorld,
                        geo,
                        square
                    )

                if not okWorld
                    or typeof(world) ~= "Vector3"
                then
                    return nil
                end

                local thickness =
                    0.0015
                local epsilon =
                    0.0008

                local helper =
                    Instance.new("Part")

                helper.Name =
                    name .. "HighlightAdornee"
                helper.Anchored = true
                helper.CanCollide = false
                helper.CanTouch = false
                helper.CanQuery = false
                helper.CastShadow = false
                helper.Transparency = 1
                helper.Size =
                    Vector3.new(
                        cell * 1.000,
                        thickness,
                        cell * 1.000
                    )
                helper.CFrame =
                    CFrame.new(
                        world
                            + upVector
                                * (
                                    epsilon
                                    - thickness * 0.5
                                )
                    )
                    * rotation
                helper.Parent =
                    folder

                local fillSurface =
                    Instance.new("SurfaceGui")

                fillSurface.Name =
                    name .. "FillSurface"
                fillSurface.Adornee =
                    helper
                fillSurface.Face =
                    Enum.NormalId.Top
                fillSurface.AlwaysOnTop =
                    false
                fillSurface.LightInfluence =
                    0
                fillSurface.SizingMode =
                    Enum.SurfaceGuiSizingMode.FixedSize
                fillSurface.CanvasSize =
                    Vector2.new(
                        192,
                        192
                    )
                fillSurface.Parent =
                    helper

                pcall(function()
                    fillSurface.ZOffset = 0
                end)

                pcall(function()
                    fillSurface.ZIndexBehavior =
                        Enum.ZIndexBehavior.Global
                end)

                local RunService =
                    game:GetService(
                        "RunService"
                    )

                local fill =
                    Instance.new("Frame")

                fill.Name =
                    name .. "Fill"
                fill.AnchorPoint =
                    Vector2.new(
                        0.5,
                        0.5
                    )
                fill.Position =
                    UDim2.fromScale(
                        0.5,
                        0.5
                    )
                fill.Size =
                    UDim2.fromScale(
                        0.958,
                        0.958
                    )
                fill.BorderSizePixel =
                    0
                fill.BackgroundColor3 =
                    Color3.new(
                        1,
                        1,
                        1
                    )
                fill.BackgroundTransparency =
                    0.08
                fill.ZIndex =
                    20
                fill.Parent =
                    fillSurface

                local gradient =
                    Instance.new("UIGradient")

                gradient.Name =
                    name .. "AnimatedGradient"

                local softenedBlack =
                    Color3.fromRGB(
                        0,
                        0,
                        0
                    ):Lerp(
                        color,
                        0.18
                    )

                gradient.Color =
                    ColorSequence.new({
                        ColorSequenceKeypoint.new(
                            0,
                            softenedBlack
                        ),
                        ColorSequenceKeypoint.new(
                            0.38,
                            color
                        ),
                        ColorSequenceKeypoint.new(
                            0.68,
                            color:Lerp(
                                Color3.new(
                                    1,
                                    1,
                                    1
                                ),
                                0.12
                            )
                        ),
                        ColorSequenceKeypoint.new(
                            1,
                            softenedBlack
                        ),
                    })
                gradient.Transparency =
                    NumberSequence.new({
                        NumberSequenceKeypoint.new(
                            0,
                            0.24
                        ),
                        NumberSequenceKeypoint.new(
                            0.30,
                            0.12
                        ),
                        NumberSequenceKeypoint.new(
                            0.50,
                            0.06
                        ),
                        NumberSequenceKeypoint.new(
                            0.70,
                            0.12
                        ),
                        NumberSequenceKeypoint.new(
                            1,
                            0.24
                        ),
                    })
                gradient.Rotation =
                    0
                gradient.Offset =
                    Vector2.new(
                        0.34,
                        0
                    )
                gradient.Parent =
                    fill

                task.spawn(function()
                    local elapsed =
                        0

                    local orbitRadius =
                        0.23
                    local orbitAngularSpeed =
                        1.10
                    local rotationSpeed =
                        34

                    local phaseOffset =
                        name == "From"
                        and 0
                        or math.pi * 0.42

                    while helper
                        and helper.Parent
                        and fill
                        and fill.Parent
                        and gradient
                        and gradient.Parent
                    do
                        local dt =
                            RunService.Heartbeat:Wait()

                        elapsed +=
                            tonumber(dt)
                            or 0

                        local angle =
                            elapsed
                                * orbitAngularSpeed
                                * math.pi
                                * 2
                            + phaseOffset

                        gradient.Offset =
                            Vector2.new(
                                math.cos(angle)
                                    * orbitRadius,
                                math.sin(angle)
                                    * orbitRadius
                            )

                        gradient.Rotation =
                            (elapsed
                                * rotationSpeed)
                            % 360
                    end
                end)

                return helper
            end

            local fromPart =
                createHighlight(
                    move.from,
                    fromColor,
                    "From"
                )

            local toPart =
                createHighlight(
                    move.to,
                    toColor,
                    "To"
                )

            if not fromPart
                or not toPart
            then
                Runtime
                    .ClearChessBestMove(
                        false
                    )
                return false
            end

            return true
        end

        if render() then
            return
        end

        task.spawn(function()
            for _ = 1, 5 do
                task.wait(0.10)

                if visualSerial
                        ~= Runtime
                            .ChessVisualSerial
                then
                    return
                end

                Runtime
                    .ClearChessBestMove(
                        false
                    )

                if render() then
                    return
                end
            end
        end)
    end

    Runtime.ChessIsOurTurn = function(fen)
        if not Runtime.ChessActive then
            return false
        end

        if Runtime.ChessSolo then
            return true
        end

        if type(fen) ~= "string" then
            return false
        end

        local side = fen:match("^%S+%s+([wb])")

        Runtime.RefreshChessSeatState()

        local myColor = Runtime.ChessSeatColor or Runtime.ChessMyColor

        if myColor ~= "w" and myColor ~= "b" then
            Runtime.SyncChessNativeState(false)
            myColor = Runtime.ChessSeatColor or Runtime.ChessMyColor
        end

        if myColor == "w" or myColor == "b" then
            Runtime.ChessGoesFirst = myColor == "w"
        end

        return side ~= nil
            and myColor ~= nil
            and side == myColor
    end

    Runtime.ChessNormalizeMove = function(fen, uci)
        local modules = Runtime.ResolveChessModules()
        if not modules or type(fen) ~= "string" or type(uci) ~= "string" then
            return nil
        end

        uci = uci:gsub("%s+", ""):lower()
        if #uci < 4 then return nil end

        local fromName = uci:sub(1, 2)
        local toName = uci:sub(3, 4)
        local promo = #uci >= 5 and uci:sub(5, 5) or nil

        local okState, state = pcall(modules.Board.fromFEN, fen)
        if not okState or not state then return nil end

        local okFrom, from = pcall(modules.Board.squareFromName, fromName)
        local okTo, to = pcall(modules.Board.squareFromName, toName)
        if not okFrom or not okTo then return nil end

        local okMoves, legal = pcall(modules.Moves.legal, state)
        if not okMoves or type(legal) ~= "table" then return nil end

        for _, move in ipairs(legal) do
            if move.from == from and move.to == to then
                local movePromo = move.promo and tostring(move.promo):lower() or nil
                if not movePromo or not promo or movePromo == promo then
                    return move
                end
            end
        end

        return nil
    end

    Runtime.GetChessRequestFunction = function()
        local env = getgenv and getgenv() or _G

        local candidate = env and env.request
        if type(candidate) == "function" then return candidate end

        candidate = env and env.http_request
        if type(candidate) == "function" then return candidate end

        local synTable = env and env.syn
        if type(synTable) == "table" and type(synTable.request) == "function" then
            return synTable.request
        end

        local httpTable = env and env.http
        if type(httpTable) == "table" and type(httpTable.request) == "function" then
            return httpTable.request
        end

        return nil
    end

    Runtime.ChessStockfishBestMove = function(fen, serial)
        local cached = Runtime.ChessStockfishCache[fen]
        if type(cached) == "string" then
            return Runtime.ChessNormalizeMove(fen, cached), "Stockfish 18"
        end

        local requestFn = Runtime.GetChessRequestFunction()
        if not requestFn then return nil, "http-unavailable" end

        local body = HttpService:JSONEncode({
            fen = fen,
            variants = 1,
            depth = math.clamp(math.floor(tonumber(Flags.other_chess_depth or Runtime.ChessStockfishDepth) or 18), 8, 18),
            maxThinkingTime = math.clamp(math.floor(tonumber(Flags.other_chess_think_ms or Runtime.ChessStockfishThinkMs) or 100), 20, 100),
        })

        local ok, response = pcall(requestFn, {
            Url = "https://chess-api.com/v1",
            Method = "POST",
            Headers = {
                ["Content-Type"] = "application/json",
                ["Accept"] = "application/json",
            },
            Body = body,
        })

        if serial ~= Runtime.ChessSearchSerial then return nil, "cancelled" end
        if not ok then return nil, "request-failed" end

        local status = type(response) == "table"
            and tonumber(response.StatusCode or response.Status or response.status)
            or 200
        local responseBody = type(response) == "table"
            and (response.Body or response.body or response.ResponseBody)
            or response

        if status and (status < 200 or status >= 300) then
            return nil, "http-" .. tostring(status)
        end
        if type(responseBody) ~= "string" then return nil, "empty-response" end

        local decodeOk, data = pcall(HttpService.JSONDecode, HttpService, responseBody)
        if not decodeOk or type(data) ~= "table" then return nil, "decode-failed" end

        local uci = data.move or data.lan
        if type(uci) ~= "string" then return nil, "no-move" end

        local move = Runtime.ChessNormalizeMove(fen, uci)
        if not move then return nil, "invalid-move" end

        Runtime.ChessStockfishCache[fen] = uci
        return move, "Stockfish 18"
    end

    Runtime.ChessLocalBestMove = function(fen, serial)
        local modules = Runtime.ResolveChessModules()
        if not modules or type(fen) ~= "string" then return nil, "local-unavailable" end

        local okState, state = pcall(modules.Board.fromFEN, fen)
        if not okState or not state then return nil, "bad-fen" end

        local rootMoves = modules.Moves.legal(state)
        if type(rootMoves) ~= "table" or #rootMoves == 0 then return nil, "no-legal-moves" end

        local material = modules.Eval.MATERIAL or {p=100,n=320,b=330,r=500,q=900,k=20000}
        local INF = 100000000
        local MATE = 1000000
        local startClock = os.clock()
        local timeLimit = 0.18
        local maxDepth = 3
        local nodes = 0
        local aborted = false

        local function shouldAbort()
            return serial ~= Runtime.ChessSearchSerial or os.clock() - startClock >= timeLimit
        end

        local function moveOrderScore(move)
            local score = 0
            local captured = state.squares[move.to]
            if move.flag == "ep" then
                captured = state.side == "w" and "p" or "P"
            end
            if captured then score += (material[captured:lower()] or 0) * 12 end

            local mover = state.squares[move.from]
            if mover and captured then score -= material[mover:lower()] or 0 end
            if move.promo then score += (material[tostring(move.promo):lower()] or 0) * 10 end
            if move.flag == "castle" then score += 180 end

            local file = move.to % 8
            local rank = math.floor(move.to / 8)
            score += 12 - math.abs(file - 3.5) - math.abs(rank - 3.5)
            return score
        end

        local function orderMoves(moves)
            table.sort(moves, function(a, b)
                return moveOrderScore(a) > moveOrderScore(b)
            end)
        end

        local function negamax(depth, alpha, beta, ply)
            nodes += 1
            if nodes % 128 == 0 and shouldAbort() then
                aborted = true
                return 0
            end

            local legal = modules.Moves.legal(state)
            if #legal == 0 then
                if modules.Moves.inCheck(state, state.side) then return -MATE + ply end
                return 0
            end

            if depth <= 0 then
                local score = modules.Eval.score(state)
                return state.side == "w" and score or -score
            end

            orderMoves(legal)
            local best = -INF

            for _, move in ipairs(legal) do
                local _, undo = modules.Moves.make(state, move)
                local value = -negamax(depth - 1, -beta, -alpha, ply + 1)
                modules.Moves.unmake(state, move, undo)

                if aborted then return 0 end
                if value > best then best = value end
                if value > alpha then alpha = value end
                if alpha >= beta then break end
            end

            return best
        end

        local bestCompleted = rootMoves[1]
        orderMoves(rootMoves)

        for depth = 1, maxDepth do
            if shouldAbort() then break end

            local depthBest = nil
            local depthScore = -INF
            local alpha = -INF
            local beta = INF
            aborted = false

            for _, move in ipairs(rootMoves) do
                local _, undo = modules.Moves.make(state, move)
                local value = -negamax(depth - 1, -beta, -alpha, 1)
                modules.Moves.unmake(state, move, undo)

                if aborted then break end
                if value > depthScore then
                    depthScore = value
                    depthBest = move
                end
                if value > alpha then alpha = value end
            end

            if not aborted and depthBest then
                bestCompleted = depthBest
                table.sort(rootMoves, function(a, b)
                    if a == bestCompleted then return true end
                    if b == bestCompleted then return false end
                    return moveOrderScore(a) > moveOrderScore(b)
                end)
            else
                break
            end
        end

        return bestCompleted, "Local fallback"
    end

    Runtime.ScheduleChessAnalysis = function(reason)
        local authoritativeFen =
            Runtime.ChessAuthoritativeFEN

        local authoritativeMoveEvent =
            reason == "move-made"
            or reason == "move-made-pending"

        if not authoritativeMoveEvent then
            Runtime.SyncChessNativeState(false)
            Runtime.BootstrapChessInitialState()
        end

        if type(authoritativeFen) == "string" then
            Runtime.ChessAuthoritativeFEN =
                authoritativeFen
            Runtime.ChessFEN =
                authoritativeFen
            Runtime.ChessActive =
                true
        end

        local fen =
            Runtime.ChessAuthoritativeFEN
            or Runtime.ChessFEN

        if not Runtime.ChessAutoEnabled then
            Runtime.SetChessStatus("Disabled")
            Runtime.ClearChessBestMove()
            return
        end

        if not Runtime.ChessActive
            or type(fen) ~= "string"
        then
            Runtime.SetChessStatus(
                "Waiting for game state"
            )
            Runtime.ClearChessBestMove()
            return
        end

        if not Runtime.ChessIsOurTurn(fen) then
            local myColor =
                Runtime.ChessSeatColor
                or Runtime.ChessMyColor

            Runtime.SetChessStatus(
                myColor == "b"
                and "Black • Waiting for White"
                or "White • Waiting for Black"
            )

            Runtime.ChessSearchSerial += 1
            Runtime.ChessPendingAnalysis = false
            Runtime.ChessPendingAnalysisReason = nil
            Runtime.ClearChessBestMove()
            return
        end

        if Runtime.ChessAnalysisInFlight then
            if Runtime.ChessAnalysisFEN == fen then
                return
            end

            Runtime.ChessSearchSerial += 1
            Runtime.ChessPendingAnalysis = true
            Runtime.ChessPendingAnalysisReason =
                reason or "new-position"
            return
        end

        if Runtime.ChessCurrentBestMoveFEN == fen
            and type(
                Runtime.ChessCurrentBestMove
            ) == "table"
            and reason ~= "depth-change"
        then
            Runtime.RefreshChessBestMoveVisual()
            Runtime.SetChessStatus(
                "Suggestion ready"
            )
            return
        end

        Runtime.ChessSearchSerial += 1
        local serial =
            Runtime.ChessSearchSerial

        Runtime.ChessAnalysisInFlight =
            true
        Runtime.ChessAnalysisFEN =
            fen
        Runtime.ChessPendingAnalysis =
            false
        Runtime.ChessPendingAnalysisReason =
            nil

        Runtime.ClearChessBestMove()

        Runtime.SetChessStatus(
            "Thinking..."
        )

        task.spawn(function()
            local startedAt =
                os.clock()

            local MIN_THINK_TIME =
                0.40

            local function finishAnalysis()
                if Runtime.ChessAnalysisFEN
                    == fen
                then
                    Runtime.ChessAnalysisInFlight =
                        false
                    Runtime.ChessAnalysisFEN =
                        nil
                end

                if Runtime.ChessPendingAnalysis
                    and Runtime.ChessAutoEnabled
                then
                    local pendingReason =
                        Runtime.ChessPendingAnalysisReason
                        or "pending"

                    Runtime.ChessPendingAnalysis =
                        false
                    Runtime.ChessPendingAnalysisReason =
                        nil

                    task.defer(
                        Runtime.ScheduleChessAnalysis,
                        pendingReason
                    )
                end
            end

            pcall(function()
                if serial
                        ~= Runtime.ChessSearchSerial
                    or not Runtime.ChessAutoEnabled
                    or Runtime.ChessFEN ~= fen
                then
                    return
                end

                local localMove,
                    localSource =
                    Runtime.ChessLocalBestMove(
                        fen,
                        serial
                    )

                if serial
                        ~= Runtime.ChessSearchSerial
                    or Runtime.ChessFEN ~= fen
                then
                    return
                end

                local finalMove =
                    localMove
                local finalSource =
                    localSource
                local usedStockfish =
                    false

                if Runtime.ChessEngineMode
                    == "Stockfish 18"
                then
                    Runtime.SetChessStatus(
                        "Stockfish thinking..."
                    )

                    local stockfishMove,
                        stockfishSource =
                        Runtime.ChessStockfishBestMove(
                            fen,
                            serial
                        )

                    if serial
                            ~= Runtime.ChessSearchSerial
                        or Runtime.ChessFEN ~= fen
                    then
                        return
                    end

                    if stockfishMove then
                        finalMove =
                            stockfishMove
                        finalSource =
                            stockfishSource
                        usedStockfish =
                            true
                    end
                end

                if not finalMove then
                    Runtime.SetChessStatus(
                        "Engine failed: "
                        .. tostring(finalSource)
                    )
                    return
                end

                local elapsed =
                    os.clock() - startedAt

                if elapsed < MIN_THINK_TIME then
                    task.wait(
                        MIN_THINK_TIME - elapsed
                    )
                end

                if serial
                        ~= Runtime.ChessSearchSerial
                    or Runtime.ChessFEN ~= fen
                    or not Runtime.ChessAutoEnabled
                then
                    return
                end

                Runtime.ShowChessBestMove(
                    fen,
                    finalMove
                )

                Runtime.SetChessStatus(
                    usedStockfish
                    and "Stockfish suggestion ready"
                    or "Suggestion ready"
                )
            end)

            finishAnalysis()
        end)
    end

    Runtime.HandleChessEvent = function(eventName, payload)
        if type(eventName) ~= "string" then return end

        if eventName == "Chess_YouAre" then
            if type(payload) == "table" then
                local color =
                    Runtime.NormalizeChessColor(
                        payload.color
                        or payload.yourColor
                        or payload.seatColor
                    )

                if color then
                    Runtime.ChessSeatColor =
                        color
                    Runtime.ChessMyColor =
                        color
                    Runtime.ChessGoesFirst =
                        color == "w"
                end
            end
            return
        end

        if eventName == "Chess_SeatUpdate" then
            if type(payload) ~= "table" then return end

            if payload.tableId ~= nil then
                Runtime.ChessTableId =
                    tostring(payload.tableId)
            end

            local seatUpdateColor =
                Runtime.NormalizeChessColor(
                    payload.yourColor
                    or payload.seatColor
                    or payload.color
                )

            if seatUpdateColor then
                Runtime.ChessSeatColor =
                    seatUpdateColor
                Runtime.ChessMyColor =
                    seatUpdateColor
                Runtime.ChessGoesFirst =
                    seatUpdateColor == "w"
            end

            if payload.state == "waiting" then
                Runtime.ChessActive = false
                Runtime.ChessFEN = nil
                Runtime.ChessAuthoritativeFEN = nil
                Runtime.ChessAuthoritativeTableId =
                    payload.tableId ~= nil
                    and tostring(payload.tableId)
                    or Runtime.ChessTableId
                Runtime.ChessSearchSerial += 1
                Runtime.ClearChessBestMove()
            end
            return
        end

        if eventName == "Chess_GameStart" then
            if type(payload) ~= "table" then return end
            Runtime.RefreshChessSeatState()

            local hasLocalSeatContext =
                Runtime.ChessPhysicalSeat ~= nil
                or (
                    Runtime.ChessTableId ~= nil
                    and Runtime.ChessSeatColor ~= nil
                )

            if not hasLocalSeatContext then
                return
            end

            if Runtime.ChessTableId and payload.tableId ~= nil
                and tostring(payload.tableId) ~= tostring(Runtime.ChessTableId) then
                return
            end

            Runtime.ChessTableId = payload.tableId ~= nil and tostring(payload.tableId) or Runtime.ChessTableId

            local payloadColor =
                Runtime.NormalizeChessColor(
                    payload.yourColor
                    or payload.seatColor
                    or payload.color
                )

            if payloadColor then
                Runtime.ChessSeatColor =
                    payloadColor
                Runtime.ChessMyColor =
                    payloadColor
                Runtime.ChessGoesFirst =
                    payloadColor == "w"
            end

            Runtime.ChessAuthoritativeFEN =
                payload.fen
            Runtime.ChessAuthoritativeTableId =
                payload.tableId ~= nil
                and tostring(payload.tableId)
                or Runtime.ChessTableId
            Runtime.ChessFEN =
                payload.fen
            Runtime.ChessSolo =
                payload.solo == true
            Runtime.ChessActive =
                type(payload.fen) == "string"
            Runtime.ChessBootstrappedInitial =
                false

            Runtime.ScheduleChessAnalysis("game-start")

            task.spawn(function()
                for retry = 1, 8 do
                    task.wait(0.10)

                    if not Runtime.ChessAutoEnabled
                        or not Runtime.ChessActive then
                        return
                    end

                    Runtime.SyncChessNativeState(false)

                    if type(Runtime.ChessFEN) == "string"
                        and Runtime.ChessIsOurTurn(Runtime.ChessFEN) then
                        Runtime.ScheduleChessAnalysis(
                            "game-start-retry-" .. tostring(retry)
                        )
                        return
                    end
                end
            end)

            return
        end

        if eventName == "Chess_MoveMade" then
            if type(payload) ~= "table" or type(payload.fen) ~= "string" then return end

            local hasLocalSeatContext =
                Runtime.ChessPhysicalSeat ~= nil
                or (
                    Runtime.ChessTableId ~= nil
                    and Runtime.ChessSeatColor ~= nil
                )

            if not hasLocalSeatContext then
                return
            end

            if Runtime.ChessTableId and payload.tableId ~= nil
                and tostring(payload.tableId) ~= tostring(Runtime.ChessTableId) then
                return
            end

            Runtime.ChessTableId =
                payload.tableId ~= nil
                and tostring(payload.tableId)
                or Runtime.ChessTableId
            Runtime.ChessAuthoritativeTableId =
                Runtime.ChessTableId
            Runtime.ChessAuthoritativeFEN =
                payload.fen
            Runtime.ChessFEN =
                payload.fen
            Runtime.ChessActive = true

            Runtime.ScheduleChessAnalysis("move-made")

            task.delay(0.10, function()
                if Runtime.ChessAutoEnabled
                    and Runtime.ChessActive
                    and Runtime.ChessAuthoritativeFEN
                        == payload.fen
                    and Runtime.ChessCurrentBestMoveFEN
                        == payload.fen
                    and Runtime.ChessCurrentBestMove
                then
                    Runtime.RefreshChessBestMoveVisual()
                end
            end)

            return
        end

        if eventName == "Chess_GameEnd" then
            if type(payload) == "table" and Runtime.ChessTableId and payload.tableId ~= nil
                and tostring(payload.tableId) ~= tostring(Runtime.ChessTableId) then
                return
            end

            Runtime.ChessActive = false
            Runtime.ChessAuthoritativeFEN = nil
            Runtime.ChessAuthoritativeTableId = nil
            Runtime.SetChessStatus("Game ended")
            Runtime.ChessSearchSerial += 1
            Runtime.ClearChessBestMove()
        end
    end

    Runtime.InstallChessListeners = function()
        if Runtime.ChessListenersInstalled then
            return Runtime.ResolveChessRemotes() ~= nil
        end

        local remotes = Runtime.ResolveChessRemotes()
        if not remotes then return false end

        Runtime.ChessListenersInstalled = true
        Connect(remotes.Event.OnClientEvent, function(eventName, payload)
            Runtime.HandleChessEvent(eventName, payload)
        end)

        local function watchCharacter(character)
            local humanoid = character and character:FindFirstChildOfClass("Humanoid")
            if not humanoid then humanoid = character and character:WaitForChild("Humanoid", 8) end

            if humanoid then
                Connect(humanoid:GetPropertyChangedSignal("SeatPart"), function()
                    Runtime.RefreshChessSeatState()

                    if humanoid.SeatPart then
                        task.spawn(function()
                            for _ = 1, 8 do
                                task.wait(0.08)

                                if not humanoid.Parent
                                    or not humanoid.SeatPart
                                then
                                    return
                                end

                                local color =
                                    Runtime
                                        .RefreshChessSeatState()

                                Runtime
                                    .SyncChessNativeState(
                                        false
                                    )

                                if color == "w"
                                    or color == "b"
                                then
                                    return
                                end
                            end
                        end)
                    end

                    if not humanoid.SeatPart then
                        Runtime.ChessActive = false
                        Runtime.ChessFEN = nil
                        Runtime.ChessAuthoritativeFEN = nil
                        Runtime.ChessAuthoritativeTableId = nil
                        Runtime.ChessPhysicalSeat = nil
                        Runtime.ChessMyColor = nil
                        Runtime.ChessSeatColor = nil
                        Runtime.ChessGoesFirst = nil
                        Runtime.ChessTableId = nil
                        Runtime.ChessSearchSerial += 1
                        Runtime.ClearChessBestMove()
                    end
                end)
            end
        end

        if LocalPlayer.Character then task.spawn(watchCharacter, LocalPlayer.Character) end
        Connect(LocalPlayer.CharacterAdded, watchCharacter)
        Runtime.RefreshChessSeatState()
        return true
    end

    Runtime.ResolveChessModules()
    Runtime.InstallChessListeners()
    Runtime.RefreshChessSeatState()
    Runtime.SyncChessNativeState(true)

    Runtime.ChessAutoEnabled =
        Flags.other_chess_engine == true

    function Runtime.SetChessEnabled(enabled)
        Runtime.ChessAutoEnabled = enabled == true
        Runtime.ChessStockfishDepth = math.clamp(
            math.floor(tonumber(Flags.other_chess_depth) or 18),
            8,
            18
        )
        Runtime.ChessStockfishThinkMs = math.clamp(
            math.floor(tonumber(Flags.other_chess_think_ms) or 100),
            20,
            100
        )
        Runtime.ChessSearchSerial += 1

        if Runtime.ChessAutoEnabled then
            Runtime.SetChessStatus("Detecting chess table")
            Runtime.ResolveChessModules()
            Runtime.InstallChessListeners()
            Runtime.RefreshChessSeatState()
            Runtime.SyncChessNativeState(true)
            Runtime.BootstrapChessInitialState()
            if Runtime.ChessFEN and Runtime.ChessActive then
                Runtime.ScheduleChessAnalysis("enabled")
            end

            task.spawn(function()
                for retry = 1, 12 do
                    task.wait(0.10)
                    if Flags.other_chess_engine ~= true then
                        return
                    end
                    Runtime.SyncChessNativeState(false)
                    Runtime.BootstrapChessInitialState()
                    if Runtime.ChessActive and type(Runtime.ChessFEN) == "string" then
                        if Runtime.ChessIsOurTurn(Runtime.ChessFEN) then
                            Runtime.ScheduleChessAnalysis("enable-retry-" .. retry)
                        end
                        return
                    end
                end
            end)
        else
            Runtime.ChessSearchSerial += 1
            Runtime.ChessPendingAnalysis = false
            Runtime.ChessPendingAnalysisReason = nil
            Runtime.SetChessStatus("Disabled")
            Runtime.ClearChessBestMove()
        end
    end

    ;(function()
        Runtime.Connect4Modules = nil
        Runtime.Connect4Remotes = nil
        Runtime.Connect4NativeState = nil
        Runtime.Connect4ListenersInstalled = false
        Runtime.Connect4Enabled =
            Flags.other_connect4_engine == true
        Runtime.Connect4TableId = nil
        Runtime.Connect4MyColor = nil
        Runtime.Connect4SeatColor = nil
        Runtime.Connect4PhysicalSeat = nil
        Runtime.Connect4Active = false
        Runtime.Connect4Solo = false
        Runtime.Connect4Snapshot = nil
        Runtime.Connect4BestColumn = nil
        Runtime.Connect4BestRow = nil
        Runtime.Connect4EventColor = nil
        Runtime.Connect4BestMoveFolder = nil
        Runtime.Connect4SearchSerial = 0
        Runtime.Connect4VisualSerial = 0
        Runtime.Connect4LastPositionKey = nil
        Runtime.Connect4LastAnalysisAt = 0
        Runtime.Connect4DetectedContextKey = nil
        Runtime.Connect4LastDetectionPoll = 0
        Runtime.Connect4NativeNextScanAt = 0
        Runtime.Connect4SearchInFlight = false
        Runtime.Connect4PendingAnalysis = false
        Runtime.Connect4PendingAnalysisReason = nil
        Runtime.Connect4PulseTween = nil
        Runtime.Connect4MarkerColor =
            typeof(Flags.other_connect4_color) == "Color3"
            and Flags.other_connect4_color
            or Color3.fromRGB(152, 140, 113)

        local BEST_MOVE_ELO = 1800
        local VISUAL_FOLDER_NAME =
            "SilentConnect4BestMove"
        local TweenService =
            game:GetService("TweenService")
        local Lighting =
            game:GetService("Lighting")
        local NATIVE_HOVER_FALLBACK = {
            RestTransparency = 0.48,
            PulseTransparency = 0.70,
            FadeIn = 0.14,
            FadeOut = 0.10,
            PulsePeriod = 1.15,
            ScaleFrom = 0.78,
            LightBrightness = 0.22,
            LightRange = 1.35,
        }

        local function getNativeHoverConfig()
            local modules =
                Runtime.Connect4Modules

            local config =
                modules
                and modules.Config

            if not config then
                local shared =
                    ReplicatedStorage:FindFirstChild(
                        "Shared"
                    )

                local configFolder =
                    shared
                    and shared:FindFirstChild(
                        "Config"
                    )

                local configModule =
                    configFolder
                    and configFolder:FindFirstChild(
                        "ConnectFourConfig"
                    )

                if configModule then
                    local ok, value =
                        pcall(
                            require,
                            configModule
                        )

                    if ok
                        and type(value) == "table"
                    then
                        config =
                            value

                        if modules then
                            modules.Config =
                                value
                        end
                    end
                end
            end

            local hover =
                type(config) == "table"
                and config.ColumnHover
                or nil

            if type(hover) ~= "table" then
                return NATIVE_HOVER_FALLBACK
            end

            return {
                RestTransparency =
                    tonumber(
                        hover.RestTransparency
                    )
                    or NATIVE_HOVER_FALLBACK.RestTransparency,
                PulseTransparency =
                    tonumber(
                        hover.PulseTransparency
                    )
                    or NATIVE_HOVER_FALLBACK.PulseTransparency,
                FadeIn =
                    tonumber(
                        hover.FadeIn
                    )
                    or NATIVE_HOVER_FALLBACK.FadeIn,
                FadeOut =
                    tonumber(
                        hover.FadeOut
                    )
                    or NATIVE_HOVER_FALLBACK.FadeOut,
                PulsePeriod =
                    tonumber(
                        hover.PulsePeriod
                    )
                    or NATIVE_HOVER_FALLBACK.PulsePeriod,
                ScaleFrom =
                    tonumber(
                        hover.ScaleFrom
                    )
                    or NATIVE_HOVER_FALLBACK.ScaleFrom,
                LightBrightness =
                    tonumber(
                        hover.LightBrightness
                    )
                    or NATIVE_HOVER_FALLBACK.LightBrightness,
                LightRange =
                    tonumber(
                        hover.LightRange
                    )
                    or NATIVE_HOVER_FALLBACK.LightRange,
            }
        end

        local function colorLuminance(color)
            if typeof(color) ~= "Color3" then
                return 0.5
            end

            return math.clamp(
                color.R * 0.2126
                    + color.G * 0.7152
                    + color.B * 0.0722,
                0,
                1
            )
        end

        local function getAdaptiveGlow()
            local brightness =
                tonumber(Lighting.Brightness)
                or 1

            local exposure =
                tonumber(
                    Lighting.ExposureCompensation
                )
                or 0

            local ambient =
                colorLuminance(
                    Lighting.Ambient
                )

            local outdoor =
                colorLuminance(
                    Lighting.OutdoorAmbient
                )

            local sceneLight =
                math.clamp(
                    brightness / 3.0
                        + ambient * 0.42
                        + outdoor * 0.28
                        + exposure * 0.16,
                    0,
                    1
                )

            local glowBrightness =
                0.055
                + sceneLight * 0.105

            local glowRangeScale =
                1.12
                + sceneLight * 0.36

            return {
                brightness = math.clamp(
                    glowBrightness,
                    0.055,
                    0.16
                ),
                rangeScale = math.clamp(
                    glowRangeScale,
                    1.12,
                    1.48
                ),
            }
        end

        local function getMarkerColor()
            local cached =
                Runtime.Connect4MarkerColor

            if typeof(cached) == "Color3" then
                return cached
            end

            local value =
                Flags.other_connect4_color

            if typeof(value) == "Color3" then
                Runtime.Connect4MarkerColor =
                    value
                return value
            end

            local fallback =
                Color3.fromRGB(
                    152,
                    140,
                    113
                )

            Runtime.Connect4MarkerColor =
                fallback

            return fallback
        end

        local function normalizeColor(value)
            if value == "y"
                or value == "r"
            then
                return value
            end

            local lower =
                string.lower(
                    tostring(value or "")
                )

            if lower == "yellow"
                or lower == "y"
            then
                return "y"
            end

            if lower == "red"
                or lower == "r"
            then
                return "r"
            end

            return nil
        end

        local function resolveModules()
            if Runtime.Connect4Modules then
                return Runtime.Connect4Modules
            end

            local shared =
                ReplicatedStorage:FindFirstChild(
                    "Shared"
                )

            local folder =
                shared
                and shared:FindFirstChild(
                    "ConnectFour"
                )

            if not folder then
                return nil
            end

            local ok, modules =
                pcall(function()
                    return {
                        Board = require(
                            folder:WaitForChild(
                                "Board"
                            )
                        ),
                        Bot = require(
                            folder:WaitForChild(
                                "Bot"
                            )
                        ),
                        Tags = require(
                            folder:WaitForChild(
                                "ConnectFourTags"
                            )
                        ),
                        Engine = require(
                            folder:WaitForChild(
                                "Engine"
                            )
                        ),
                    }
                end)

            if not ok
                or type(modules) ~= "table"
                or type(modules.Board) ~= "table"
                or type(modules.Bot) ~= "table"
                or type(modules.Tags) ~= "table"
                or type(modules.Engine) ~= "table"
            then
                return nil
            end

            Runtime.Connect4Modules =
                modules

            return modules
        end

        local function resolveRemotes()
            local cached =
                Runtime.Connect4Remotes

            if cached
                and cached.Event
                and cached.Function
                and cached.Event.Parent
                and cached.Function.Parent
            then
                return cached
            end

            local remotes =
                ReplicatedStorage:FindFirstChild(
                    "Remotes"
                )

            local event =
                remotes
                and remotes:FindFirstChild(
                    "ConnectFourEvent"
                )

            local func =
                remotes
                and remotes:FindFirstChild(
                    "ConnectFourFunction"
                )

            if not (
                event
                and event:IsA("RemoteEvent")
                and func
                and func:IsA("RemoteFunction")
            ) then
                return nil
            end

            Runtime.Connect4Remotes = {
                Event = event,
                Function = func,
            }

            return Runtime.Connect4Remotes
        end

        local function parseSeatId(seatId)
            local modules =
                resolveModules()

            if modules
                and type(
                    modules.Tags.parseSeatId
                ) == "function"
            then
                local ok,
                    tableId,
                    color =
                    pcall(
                        modules.Tags.parseSeatId,
                        seatId
                    )

                if ok
                    and tableId ~= nil
                then
                    return tostring(tableId),
                        normalizeColor(color)
                end
            end

            if typeof(seatId) ~= "string" then
                return nil, nil
            end

            local tableId, side =
                seatId:match(
                    "^(.-)_(%a+)$"
                )

            if not tableId
                or tableId == ""
            then
                return nil, nil
            end

            return tostring(tableId),
                normalizeColor(side)
        end

        local function getLocalSeat()
            local character =
                LocalPlayer.Character

            local humanoid =
                character
                and character:FindFirstChildOfClass(
                    "Humanoid"
                )

            if not humanoid then
                return nil, nil
            end

            local seat =
                humanoid.SeatPart

            if seat then
                local seatId =
                    seat:GetAttribute(
                        "ConnectFourSeatID"
                    )

                if seatId ~= nil then
                    return seat, humanoid
                end

                local modules =
                    resolveModules()

                if modules then
                    local ok, value =
                        pcall(
                            modules.Tags.getSeatId,
                            seat
                        )

                    if ok
                        and value ~= nil
                    then
                        return seat, humanoid
                    end
                end
            end

            local okTagged, tagged =
                pcall(
                    game:GetService(
                        "CollectionService"
                    ).GetTagged,
                    game:GetService(
                        "CollectionService"
                    ),
                    "ConnectFourSeat"
                )

            if okTagged
                and type(tagged) == "table"
            then
                for _, candidate in ipairs(tagged) do
                    if candidate
                        and candidate.Parent
                        and (
                            candidate:IsA("Seat")
                            or candidate:IsA(
                                "VehicleSeat"
                            )
                        )
                    then
                        local okOccupant, occupant =
                            pcall(function()
                                return candidate.Occupant
                            end)

                        if okOccupant
                            and occupant == humanoid
                        then
                            return candidate,
                                humanoid
                        end
                    end
                end
            end

            return seat, humanoid
        end

        local resolveNativeState
        local detectCurrentContext

        local function refreshSeatState()
            local seat =
                select(
                    1,
                    getLocalSeat()
                )

            Runtime.Connect4PhysicalSeat =
                seat

            if not seat then
                return Runtime.Connect4SeatColor,
                    Runtime.Connect4TableId
            end

            local seatId =
                seat:GetAttribute(
                    "ConnectFourSeatID"
                )

            if seatId == nil then
                local value =
                    seat:FindFirstChild(
                        "ConnectFourSeatID"
                    )

                if value
                    and value:IsA(
                        "ValueBase"
                    )
                then
                    seatId = value.Value
                end
            end

            local tableId, color =
                parseSeatId(seatId)

            if not tableId then
                local modules =
                    resolveModules()

                if modules then
                    local ok, id =
                        pcall(
                            modules.Tags.getSeatId,
                            seat
                        )

                    if ok then
                        tableId, color =
                            parseSeatId(id)
                    end
                end
            end

            if tableId then
                Runtime.Connect4TableId =
                    tostring(tableId)
            end

            if color then
                Runtime.Connect4SeatColor =
                    color

                Runtime.Connect4MyColor =
                    color
            end

            return color, tableId
        end

        local function resolveMyColor()
            local detectedColor =
                select(
                    1,
                    detectCurrentContext()
                )

            if detectedColor then
                return detectedColor
            end

            local eventColor =
                normalizeColor(
                    Runtime.Connect4EventColor
                )

            if eventColor then
                Runtime.Connect4MyColor =
                    eventColor
                return eventColor
            end

            local native =
                resolveNativeState
                and resolveNativeState()
                or nil

            if native then
                local nativeColor =
                    normalizeColor(
                        rawget(native, "seatColor")
                    )
                    or normalizeColor(
                        rawget(native, "myColor")
                    )

                if nativeColor then
                    Runtime.Connect4MyColor =
                        nativeColor
                    return nativeColor
                end
            end

            return normalizeColor(
                Runtime.Connect4MyColor
            )
        end

        local function looksLikeNativeState(value)
            if type(value) ~= "table" then
                return false
            end

            return type(
                rawget(value, "spectating")
            ) == "table"
                and type(
                    rawget(value, "seated")
                ) == "boolean"
                and type(
                    rawget(value, "active")
                ) == "boolean"
                and type(
                    rawget(value, "solo")
                ) == "boolean"
                and type(
                    rawget(
                        value,
                        "gamepadCursor"
                    )
                ) == "boolean"
                and type(
                    rawget(
                        value,
                        "keyboardCursor"
                    )
                ) == "boolean"
                and rawget(value, "ctx")
                    ~= nil
        end

        local function nativeStateScore(
            value
        )
            if not looksLikeNativeState(value) then
                return -math.huge
            end

            local score = 0

            if rawget(value, "seated") == true then
                score += 120
            end

            if rawget(value, "active") == true then
                score += 100
            end

            if rawget(value, "tableId") ~= nil then
                score += 85
            end

            if normalizeColor(
                rawget(value, "myColor")
            ) then
                score += 70
            end

            if normalizeColor(
                rawget(value, "seatColor")
            ) then
                score += 55
            end

            if type(
                rawget(value, "mirror")
            ) == "table"
            then
                score += 70
            end

            local boardView =
                rawget(value, "boardView")

            if type(boardView) == "table" then
                score += 30

                if typeof(
                    rawget(boardView, "board")
                ) == "Instance"
                then
                    score += 35
                end
            end

            return score
        end

        resolveNativeState = function(forceRescan)
            local cached =
                Runtime.Connect4NativeState

            local now =
                os.clock()

            if looksLikeNativeState(cached)
                and forceRescan ~= true
            then
                return cached
            end

            if looksLikeNativeState(cached)
                and now
                    < (
                        Runtime.Connect4NativeNextScanAt
                        or 0
                    )
            then
                return cached
            end

            if type(getgc) ~= "function" then
                return cached
            end

            Runtime.Connect4NativeNextScanAt =
                now + 3.0

            local ok, objects =
                pcall(getgc, true)

            if not ok
                or type(objects) ~= "table"
            then
                return cached
            end

            local best =
                looksLikeNativeState(cached)
                and cached
                or nil

            local bestScore =
                best
                and nativeStateScore(best)
                or -math.huge

            for _, object in ipairs(objects) do
                if type(object) == "table" then
                    local score =
                        nativeStateScore(
                            object
                        )

                    if score > bestScore then
                        best =
                            object
                        bestScore =
                            score
                    end
                end
            end

            Runtime.Connect4NativeState =
                best

            return best
        end

        local function snapshotFromMirror(
            mirror
        )
            if type(mirror) ~= "table" then
                return nil
            end

            local modules =
                resolveModules()

            if not modules then
                return nil
            end

            if type(
                modules.Engine.snapshot
            ) == "function"
            then
                local ok, snapshot =
                    pcall(
                        modules.Engine.snapshot,
                        mirror
                    )

                if ok
                    and type(snapshot)
                        == "table"
                then
                    return snapshot
                end
            end

            local state =
                rawget(mirror, "state")

            if type(state) == "table"
                and type(
                    modules.Board.serialize
                ) == "function"
            then
                local ok, snapshot =
                    pcall(
                        modules.Board.serialize,
                        state
                    )

                if ok
                    and type(snapshot)
                        == "table"
                then
                    return snapshot
                end
            end

            return nil
        end

        detectCurrentContext = function()
            local physicalColor,
                physicalTableId =
                refreshSeatState()

            local native =
                resolveNativeState(false)

            local nativeTableId =
                native
                and rawget(
                    native,
                    "tableId"
                )
                or nil

            if physicalTableId
                and nativeTableId
                and tostring(physicalTableId)
                    ~= tostring(nativeTableId)
            then
                native =
                    resolveNativeState(true)

                nativeTableId =
                    native
                    and rawget(
                        native,
                        "tableId"
                    )
                    or nil
            end

            local nativeColor =
                native
                and (
                    normalizeColor(
                        rawget(
                            native,
                            "seatColor"
                        )
                    )
                    or normalizeColor(
                        rawget(
                            native,
                            "myColor"
                        )
                    )
                )
                or nil

            local nativeSeated =
                native
                and rawget(
                    native,
                    "seated"
                ) == true

            if native
                and nativeTableId == nil
            then
                local boardView =
                    rawget(
                        native,
                        "boardView"
                    )

                local board =
                    type(boardView) == "table"
                    and rawget(
                        boardView,
                        "board"
                    )
                    or nil

                local modules =
                    resolveModules()

                if typeof(board) == "Instance"
                    and modules
                    and type(
                        modules.Tags.getBoardId
                    ) == "function"
                then
                    local okId, boardId =
                        pcall(
                            modules.Tags.getBoardId,
                            board
                        )

                    if okId
                        and boardId ~= nil
                    then
                        nativeTableId =
                            tostring(boardId)
                    end
                end
            end

            local finalTableId =
                physicalTableId
                or (
                    nativeSeated
                    and nativeTableId
                    or nil
                )
                or Runtime.Connect4TableId

            local finalColor =
                physicalColor
                or (
                    nativeSeated
                    and nativeColor
                    or nil
                )
                or normalizeColor(
                    Runtime.Connect4EventColor
                )
                or normalizeColor(
                    Runtime.Connect4MyColor
                )

            if finalTableId ~= nil then
                Runtime.Connect4TableId =
                    tostring(finalTableId)
            end

            if finalColor then
                Runtime.Connect4MyColor =
                    finalColor

                if physicalColor then
                    Runtime.Connect4SeatColor =
                        physicalColor
                end
            end

            return finalColor,
                Runtime.Connect4TableId,
                native
        end

        local function syncNativeState()
            local _,
                _,
                detectedNative =
                detectCurrentContext()

            local native =
                detectedNative
                or resolveNativeState()

            if not native then
                return false
            end

            local tableId =
                rawget(
                    native,
                    "tableId"
                )

            if tableId ~= nil
                and (
                    rawget(
                        native,
                        "seated"
                    ) == true
                    or Runtime.Connect4TableId == nil
                )
            then
                Runtime.Connect4TableId =
                    tostring(tableId)
            end

            local myColor =
                normalizeColor(
                    rawget(
                        native,
                        "myColor"
                    )
                )

            local seatColor =
                normalizeColor(
                    rawget(
                        native,
                        "seatColor"
                    )
                )

            local physicalColor =
                Runtime.Connect4PhysicalSeat
                and Runtime.Connect4SeatColor
                or nil

            if physicalColor then
                Runtime.Connect4MyColor =
                    physicalColor
            else
                if seatColor then
                    Runtime.Connect4SeatColor =
                        seatColor
                end

                Runtime.Connect4MyColor =
                    normalizeColor(
                        Runtime.Connect4EventColor
                    )
                    or seatColor
                    or myColor
                    or Runtime.Connect4MyColor
            end

            Runtime.Connect4Active =
                rawget(
                    native,
                    "active"
                ) == true

            Runtime.Connect4Solo =
                rawget(
                    native,
                    "solo"
                ) == true

            local snapshot =
                snapshotFromMirror(
                    rawget(
                        native,
                        "mirror"
                    )
                )

            if snapshot then
                Runtime.Connect4Snapshot =
                    snapshot
            end

            return true
        end

        local function getBoardModel()
            local modules =
                resolveModules()

            if not modules then
                return nil
            end

            detectCurrentContext()

            local native =
                resolveNativeState()

            if native then
                local boardView =
                    rawget(
                        native,
                        "boardView"
                    )

                local nativeBoard =
                    type(boardView) == "table"
                    and rawget(
                        boardView,
                        "board"
                    )
                    or nil

                if typeof(nativeBoard)
                        == "Instance"
                    and nativeBoard.Parent
                then
                    return nativeBoard
                end
            end

            local tableId =
                Runtime.Connect4TableId

            if tableId then
                local ok, board =
                    pcall(
                        modules.Tags.findBoard,
                        tostring(tableId)
                    )

                if ok
                    and board
                    and board.Parent
                then
                    return board
                end
            end

            local seat =
                Runtime.Connect4PhysicalSeat
                or select(
                    1,
                    getLocalSeat()
                )

            if seat then
                local ok, board =
                    pcall(
                        modules.Tags.findBoardForSeat,
                        seat
                    )

                if ok
                    and board
                    and board.Parent
                then
                    return board
                end
            end

            return nil
        end

        local function positionKey(snapshot)
            if type(snapshot) ~= "table" then
                return nil
            end

            local grid =
                snapshot.grid

            if type(grid) ~= "table" then
                return nil
            end

            local pieces = {
                tostring(snapshot.turn or ""),
                "|",
            }

            for row = 1, 6 do
                local rowData =
                    grid[row]

                for col = 1, 8 do
                    pieces[#pieces + 1] =
                        tostring(
                            type(rowData)
                                == "table"
                                and rowData[col]
                                or 0
                        )
                end
            end

            return table.concat(pieces)
        end

        local function clearVisual(
            clearRecommendation
        )
            Runtime.Connect4VisualSerial += 1

            if Runtime.Connect4PulseTween then
                pcall(function()
                    Runtime.Connect4PulseTween:Cancel()
                end)

                Runtime.Connect4PulseTween =
                    nil
            end

            local hover =
                getNativeHoverConfig()

            local fadeOutTime =
                math.max(
                    0.01,
                    tonumber(hover.FadeOut)
                        or 0.10
                )

            local folder =
                Runtime.Connect4BestMoveFolder

            Runtime.Connect4BestMoveFolder =
                nil

            if folder
                and folder.Parent
            then
                local serial =
                    Runtime.Connect4VisualSerial

                pcall(function()
                    folder.Name =
                        VISUAL_FOLDER_NAME
                        .. "_Fading_"
                        .. tostring(serial)
                end)

                local marker =
                    folder:FindFirstChild(
                        "BestMoveCircle",
                        true
                    )

                local light =
                    marker
                    and marker:FindFirstChild(
                        "CircleGlow"
                    )

                if marker
                    and marker:IsA("BasePart")
                then
                    pcall(function()
                        TweenService:Create(
                            marker,
                            TweenInfo.new(
                                fadeOutTime,
                                Enum.EasingStyle.Quad,
                                Enum.EasingDirection.InOut
                            ),
                            {
                                Transparency = 1,
                            }
                        ):Play()
                    end)

                    for _, child in ipairs(
                        marker:GetDescendants()
                    ) do
                        if child:IsA("Decal")
                            or child:IsA("Texture")
                        then
                            pcall(function()
                                TweenService:Create(
                                    child,
                                    TweenInfo.new(
                                        fadeOutTime,
                                        Enum.EasingStyle.Quad,
                                        Enum.EasingDirection.InOut
                                    ),
                                    {
                                        Transparency = 1,
                                    }
                                ):Play()
                            end)
                        end
                    end
                end

                if light
                    and light:IsA("PointLight")
                then
                    pcall(function()
                        TweenService:Create(
                            light,
                            TweenInfo.new(
                                fadeOutTime,
                                Enum.EasingStyle.Quad,
                                Enum.EasingDirection.Out
                            ),
                            {
                                Brightness = 0,
                            }
                        ):Play()
                    end)
                end

                task.delay(
                    fadeOutTime + 0.04,
                    function()
                        if folder
                            and folder.Parent
                        then
                            pcall(function()
                                folder:Destroy()
                            end)
                        end
                    end
                )
            end

            if clearRecommendation ~= false then
                Runtime.Connect4BestColumn =
                    nil
                Runtime.Connect4BestRow =
                    nil
            end
        end

        local function showBestDrop(
            column,
            row
        )
            if Flags.other_connect4_engine
                    ~= true
            then
                return false
            end

            column =
                tonumber(column)
            row =
                tonumber(row)

            local currentFolder =
                Runtime.Connect4BestMoveFolder

            if currentFolder
                and currentFolder.Parent
                and currentFolder:GetAttribute(
                    "Connect4Column"
                ) == column
                and currentFolder:GetAttribute(
                    "Connect4Row"
                ) == row
            then
                local marker =
                    currentFolder:FindFirstChild(
                        "BestMoveCircle",
                        true
                    )

                local color =
                    getMarkerColor()

                if marker
                    and marker:IsA("BasePart")
                then
                    marker.Color =
                        color

                    local light =
                        marker:FindFirstChild(
                            "CircleGlow"
                        )

                    if light
                        and light:IsA("PointLight")
                    then
                        light.Color =
                            color
                    end
                end

                return true
            end

            clearVisual(false)

            if not column
                or column < 1
                or column > 8
                or not row
                or row < 1
                or row > 6
            then
                return false
            end

            local board =
                getBoardModel()

            if not board then
                return false
            end

            local old =
                board:FindFirstChild(
                    VISUAL_FOLDER_NAME
                )

            if old then
                pcall(function()
                    old:Destroy()
                end)
            end

            local selection =
                board:FindFirstChild(
                    "Selection",
                    true
                )

            local columnPart =
                selection
                and selection:FindFirstChild(
                    tostring(column)
                )

            local diskTemplate =
                board:FindFirstChild(
                    "Disk",
                    true
                )

            if not (
                columnPart
                and columnPart:IsA("BasePart")
                and diskTemplate
                and diskTemplate:IsA("BasePart")
            ) then
                return false
            end

            local modules =
                resolveModules()

            if not modules
                or type(
                    modules.Board.computeDropCFrame
                ) ~= "function"
            then
                return false
            end

            local okCFrame, dropCFrame =
                pcall(
                    modules.Board.computeDropCFrame,
                    diskTemplate.CFrame,
                    diskTemplate.Size.Y,
                    column,
                    row,
                    columnPart
                )

            if not okCFrame
                or typeof(dropCFrame) ~= "CFrame"
            then
                return false
            end

            local folder =
                Instance.new("Folder")

            folder.Name =
                VISUAL_FOLDER_NAME
            folder:SetAttribute(
                "Connect4Column",
                column
            )
            folder:SetAttribute(
                "Connect4Row",
                row
            )
            folder.Parent =
                board

            Runtime.Connect4BestMoveFolder =
                folder

            local marker =
                diskTemplate:Clone()

            marker.Name =
                "BestMoveCircle"

            for _, child in ipairs(
                marker:GetDescendants()
            ) do
                if child:IsA("ClickDetector")
                    or child:IsA("ProximityPrompt")
                    or child:IsA("SurfaceGui")
                    or child:IsA("BillboardGui")
                    or child:IsA("Decal")
                    or child:IsA("Texture")
                    or child:IsA("SurfaceAppearance")
                    or child:IsA("ParticleEmitter")
                    or child:IsA("Trail")
                    or child:IsA("Beam")
                    or child:IsA("PointLight")
                    or child:IsA("SpotLight")
                    or child:IsA("SurfaceLight")
                then
                    child:Destroy()
                end
            end

            marker.Anchored = true
            marker.CanCollide = false
            marker.CanTouch = false
            marker.CanQuery = false
            marker.CastShadow = false
            local markerColor =
                getMarkerColor()

            marker.Color =
                markerColor
            marker.Material =
                Enum.Material.Neon
            marker.Transparency =
                1

            local finalMarkerSize =
                Vector3.new(
                    math.max(
                        0.006,
                        diskTemplate.Size.X * 0.72
                    ),
                    diskTemplate.Size.Y * 0.82,
                    diskTemplate.Size.Z * 0.82
                )

            local hover =
                getNativeHoverConfig()

            local scaleFrom =
                math.clamp(
                    tonumber(
                        hover.ScaleFrom
                    ) or 0.78,
                    0.10,
                    1
                )

            marker.Size =
                Vector3.new(
                    finalMarkerSize.X
                        * scaleFrom,
                    finalMarkerSize.Y
                        * scaleFrom,
                    finalMarkerSize.Z
                        * scaleFrom
                )

            marker.CFrame =
                dropCFrame
            marker.Parent =
                folder

            local light =
                Instance.new("PointLight")

            light.Name =
                "CircleGlow"
            light.Color =
                markerColor
            local adaptiveGlow =
                getAdaptiveGlow()

            local fadeInTime =
                math.max(
                    0.01,
                    tonumber(hover.FadeIn)
                        or 0.14
                )

            local restTransparency =
                math.clamp(
                    tonumber(
                        hover.RestTransparency
                    ) or 0.48,
                    0,
                    1
                )

            local pulseTransparency =
                math.clamp(
                    tonumber(
                        hover.PulseTransparency
                    ) or 0.70,
                    0,
                    1
                )

            local pulsePeriod =
                math.max(
                    0.10,
                    tonumber(
                        hover.PulsePeriod
                    ) or 1.15
                )

            light.Brightness =
                0
            light.Range =
                math.max(
                    finalMarkerSize.Y,
                    finalMarkerSize.Z
                )
                * adaptiveGlow.rangeScale
            light.Shadows =
                false
            light.Parent =
                marker

            pcall(function()
                TweenService:Create(
                    marker,
                    TweenInfo.new(
                        fadeInTime,
                        Enum.EasingStyle.Quad,
                        Enum.EasingDirection.Out
                    ),
                    {
                        Transparency =
                            restTransparency,
                        Size =
                            finalMarkerSize,
                    }
                ):Play()
            end)

            pcall(function()
                TweenService:Create(
                    light,
                    TweenInfo.new(
                        fadeInTime,
                        Enum.EasingStyle.Quad,
                        Enum.EasingDirection.Out
                    ),
                    {
                        Brightness =
                            adaptiveGlow.brightness,
                    }
                ):Play()
            end)

            task.delay(
                fadeInTime,
                function()
                    if Runtime.Connect4BestMoveFolder
                            ~= folder
                        or not marker.Parent
                        or Flags.other_connect4_engine
                            ~= true
                    then
                        return
                    end

                    local pulseTween

                    local ok, tween =
                        pcall(
                            TweenService.Create,
                            TweenService,
                            marker,
                            TweenInfo.new(
                                pulsePeriod * 0.5,
                                Enum.EasingStyle.Sine,
                                Enum.EasingDirection.InOut,
                                -1,
                                true
                            ),
                            {
                                Transparency =
                                    pulseTransparency,
                            }
                        )

                    if ok and tween then
                        pulseTween =
                            tween

                        Runtime.Connect4PulseTween =
                            pulseTween

                        pulseTween:Play()
                    end
                end
            )

            return true
        end

        local function updateVisualColor(
            color
        )
            if typeof(color) == "Color3" then
                Runtime.Connect4MarkerColor =
                    color
            else
                color =
                    getMarkerColor()
            end

            local folder =
                Runtime.Connect4BestMoveFolder

            local marker =
                folder
                and folder:FindFirstChild(
                    "BestMoveCircle",
                    true
                )

            if marker
                and marker:IsA("BasePart")
            then
                marker.Color =
                    color

                local light =
                    marker:FindFirstChild(
                        "CircleGlow"
                    )

                if light
                    and light:IsA("PointLight")
                then
                    light.Color =
                        color
                end

                return true
            end

            return false
        end

        local function updateVisualLighting(
            instant
        )
            local folder =
                Runtime.Connect4BestMoveFolder

            local marker =
                folder
                and folder:FindFirstChild(
                    "BestMoveCircle",
                    true
                )

            if not (
                marker
                and marker:IsA("BasePart")
            ) then
                return false
            end

            local light =
                marker:FindFirstChild(
                    "CircleGlow"
                )

            local adaptive =
                getAdaptiveGlow()

            if light
                and light:IsA("PointLight")
            then
                light.Range =
                    math.max(
                        marker.Size.Y,
                        marker.Size.Z
                    )
                    * adaptive.rangeScale

                if instant == true then
                    light.Brightness =
                        adaptive.brightness
                else
                    pcall(function()
                        TweenService:Create(
                            light,
                            TweenInfo.new(
                                0.18,
                                Enum.EasingStyle.Quad,
                                Enum.EasingDirection.InOut
                            ),
                            {
                                Brightness =
                                    adaptive.brightness,
                            }
                        ):Play()
                    end)
                end
            end

            return true
        end

        local function refreshVisual()
            updateVisualColor(
                getMarkerColor()
            )
            updateVisualLighting(false)

            if Runtime.Connect4BestColumn
                and Runtime.Connect4BestRow
            then
                return showBestDrop(
                    Runtime.Connect4BestColumn,
                    Runtime.Connect4BestRow
                )
            end

            clearVisual(false)
            return false
        end

        local function ourTurn(state)
            if type(state) ~= "table" then
                return false, nil
            end

            local turn =
                normalizeColor(
                    state.turn
                )

            if not turn then
                return false, nil
            end

            if Runtime.Connect4Solo then
                return Runtime.Connect4Active,
                    turn
            end

            local myColor =
                resolveMyColor()

            return Runtime.Connect4Active
                    and myColor ~= nil
                    and turn == myColor,
                myColor
        end

        local function analyze(reason)
            if Flags.other_connect4_engine
                ~= true
            then
                return
            end

            syncNativeState()

            if not Runtime.Connect4Active then
                clearVisual()
                return
            end

            local snapshot =
                Runtime.Connect4Snapshot

            if type(snapshot) ~= "table" then
                clearVisual()
                return
            end

            local modules =
                resolveModules()

            if not modules then
                clearVisual()
                return
            end

            local okState, state =
                pcall(
                    modules.Board.deserialize,
                    snapshot
                )

            if not okState
                or type(state) ~= "table"
            then
                clearVisual()
                return
            end

            local isOurTurn,
                searchColor =
                ourTurn(state)

            if not isOurTurn
                or not searchColor
            then
                Runtime.Connect4SearchSerial += 1
                Runtime.Connect4BestColumn =
                    nil
                Runtime.Connect4BestRow =
                    nil
                clearVisual(false)
                return
            end

            local key =
                positionKey(snapshot)

            if key
                and key
                    == Runtime.Connect4LastPositionKey
                and Runtime.Connect4BestColumn
                and Runtime.Connect4BestRow
            then
                refreshVisual()
                return
            end

            if Runtime.Connect4SearchInFlight then
                Runtime.Connect4PendingAnalysis =
                    true
                Runtime.Connect4PendingAnalysisReason =
                    reason or "pending"
                return
            end

            Runtime.Connect4SearchSerial += 1
            local serial =
                Runtime.Connect4SearchSerial

            Runtime.Connect4SearchInFlight =
                true
            Runtime.Connect4PendingAnalysis =
                false
            Runtime.Connect4PendingAnalysisReason =
                nil

            Runtime.Connect4LastAnalysisAt =
                os.clock()

            task.spawn(function()
                local function finishSearch()
                    Runtime.Connect4SearchInFlight =
                        false

                    if Runtime.Connect4PendingAnalysis
                        and Flags.other_connect4_engine
                            == true
                    then
                        local pendingReason =
                            Runtime.Connect4PendingAnalysisReason
                            or "pending"

                        Runtime.Connect4PendingAnalysis =
                            false
                        Runtime.Connect4PendingAnalysisReason =
                            nil

                        task.defer(
                            analyze,
                            pendingReason
                        )
                    end
                end

                local okWorker, workerError =
                    pcall(function()
                        local okPick, column =
                            pcall(
                                modules.Bot.pickColumn,
                                state,
                                searchColor,
                                BEST_MOVE_ELO
                            )

                        if not okPick
                            or serial
                                ~= Runtime.Connect4SearchSerial
                            or Flags.other_connect4_engine
                                ~= true
                        then
                            return
                        end

                        if key
                            and positionKey(
                                Runtime.Connect4Snapshot
                            ) ~= key
                        then
                            Runtime.Connect4PendingAnalysis =
                                true
                            Runtime.Connect4PendingAnalysisReason =
                                "position-changed"
                            return
                        end

                        column =
                            tonumber(column)

                        if not column
                            or column < 1
                            or column > 8
                        then
                            Runtime.Connect4BestColumn =
                                nil
                            Runtime.Connect4BestRow =
                                nil
                            clearVisual(false)
                            return
                        end

                        local height =
                            tonumber(
                                state.heights
                                and state.heights[column]
                            ) or 0

                        local row =
                            (tonumber(
                                modules.Board.ROWS
                            ) or 6)
                            - height

                        if row < 1
                            or row > 6
                        then
                            Runtime.Connect4BestColumn =
                                nil
                            Runtime.Connect4BestRow =
                                nil
                            clearVisual(false)
                            return
                        end

                        Runtime.Connect4BestColumn =
                            column
                        Runtime.Connect4BestRow =
                            row
                        Runtime.Connect4LastPositionKey =
                            key

                        showBestDrop(
                            column,
                            row
                        )

                        task.delay(
                            0.55,
                            function()
                                if Flags.other_connect4_engine
                                        == true
                                    and Runtime.Connect4BestColumn
                                        == column
                                    and Runtime.Connect4BestRow
                                        == row
                                    and serial
                                        == Runtime.Connect4SearchSerial
                                then
                                    showBestDrop(
                                        column,
                                        row
                                    )
                                end
                            end
                        )
                    end)

                finishSearch()
            end)
        end

        local function sameTable(
            payloadTableId
        )
            if payloadTableId == nil
                or Runtime.Connect4TableId == nil
            then
                return false
            end

            return tostring(payloadTableId)
                == tostring(
                    Runtime.Connect4TableId
                )
        end

        local function handleEvent(
            eventName,
            payload
        )
            if eventName
                == "ConnectFour_YouAre"
            then
                if type(payload) == "table" then
                    local color =
                        normalizeColor(
                            payload.color
                        )

                    if color then
                        Runtime.Connect4EventColor =
                            color

                        if not Runtime.Connect4PhysicalSeat
                            or not Runtime.Connect4SeatColor
                        then
                            Runtime.Connect4MyColor =
                                color
                        end
                    end
                end

                return
            end

            if eventName
                == "ConnectFour_SeatUpdate"
            then
                if type(payload) ~= "table" then
                    return
                end

                Runtime.Connect4TableId =
                    payload.tableId ~= nil
                    and tostring(
                        payload.tableId
                    )
                    or Runtime.Connect4TableId

                local payloadColor =
                    normalizeColor(
                        payload.yourColor
                    )

                if payloadColor then
                    Runtime.Connect4EventColor =
                        payloadColor
                end

                refreshSeatState()

                if not Runtime.Connect4SeatColor
                    and payloadColor
                then
                    Runtime.Connect4MyColor =
                        payloadColor
                end

                if payload.state == "waiting" then
                    Runtime.Connect4Active =
                        false
                    Runtime.Connect4Snapshot =
                        nil
                    Runtime.Connect4SearchSerial += 1
                    clearVisual()
                end

                return
            end

            if eventName
                == "ConnectFour_GameStart"
            then
                if type(payload) ~= "table"
                    or type(payload.board)
                        ~= "table"
                then
                    return
                end

                refreshSeatState()

                if Runtime.Connect4TableId
                    and payload.tableId ~= nil
                    and not sameTable(
                        payload.tableId
                    )
                then
                    return
                end

                if not Runtime.Connect4TableId
                    and not Runtime.Connect4PhysicalSeat
                then
                    return
                end

                if payload.tableId ~= nil then
                    Runtime.Connect4TableId =
                        tostring(
                            payload.tableId
                        )
                end

                Runtime.Connect4Solo =
                    payload.solo == true
                Runtime.Connect4Active =
                    true
                Runtime.Connect4Snapshot =
                    payload.board

                analyze("game-start")
                return
            end

            if eventName
                == "ConnectFour_DropMade"
            then
                if type(payload) ~= "table"
                    or type(payload.board)
                        ~= "table"
                then
                    return
                end

                refreshSeatState()

                if not sameTable(
                    payload.tableId
                ) then
                    return
                end

                Runtime.Connect4Active =
                    true
                Runtime.Connect4Snapshot =
                    payload.board
                Runtime.Connect4SearchSerial += 1
                clearVisual()

                analyze("drop-made")
                return
            end

            if eventName
                == "ConnectFour_GameEnd"
            then
                if type(payload) == "table"
                    and Runtime.Connect4TableId
                    and payload.tableId ~= nil
                    and not sameTable(
                        payload.tableId
                    )
                then
                    return
                end

                Runtime.Connect4Active =
                    false
                Runtime.Connect4Snapshot =
                    nil
                Runtime.Connect4SearchSerial += 1
                clearVisual()
            end
        end

        local function installListeners()
            if Runtime.Connect4ListenersInstalled then
                return resolveRemotes() ~= nil
            end

            local remotes =
                resolveRemotes()

            if not remotes then
                return false
            end

            Runtime.Connect4ListenersInstalled =
                true

            Connect(
                remotes.Event.OnClientEvent,
                function(eventName, payload)
                    handleEvent(
                        eventName,
                        payload
                    )
                end
            )

            local function watchCharacter(
                character
            )
                local humanoid =
                    character
                    and character
                        :FindFirstChildOfClass(
                            "Humanoid"
                        )

                if not humanoid
                    and character
                then
                    humanoid =
                        character:WaitForChild(
                            "Humanoid",
                            8
                        )
                end

                if not humanoid then
                    return
                end

                Connect(
                    humanoid
                        :GetPropertyChangedSignal(
                            "SeatPart"
                        ),
                    function()
                        refreshSeatState()
                        syncNativeState()

                        local seat =
                            humanoid.SeatPart

                        if not seat
                            or seat:GetAttribute(
                                "ConnectFourSeatID"
                            ) == nil
                        then
                            local modules =
                                resolveModules()

                            local isConnect4Seat =
                                false

                            if seat and modules then
                                local ok, id =
                                    pcall(
                                        modules.Tags.getSeatId,
                                        seat
                                    )

                                isConnect4Seat =
                                    ok
                                    and id ~= nil
                            end

                            if not isConnect4Seat then
                                Runtime.Connect4PhysicalSeat =
                                    nil
                                Runtime.Connect4TableId =
                                    nil
                                Runtime.Connect4MyColor =
                                    nil
                                Runtime.Connect4SeatColor =
                                    nil
                                Runtime.Connect4EventColor =
                                    nil
                                Runtime.Connect4Active =
                                    false
                                Runtime.Connect4Snapshot =
                                    nil
                                Runtime.Connect4SearchSerial += 1
                                clearVisual()
                                return
                            end
                        end

                        if Flags.other_connect4_engine
                            == true
                        then
                            task.spawn(function()
                                for _ = 1, 10 do
                                    task.wait(0.10)

                                    if Flags.other_connect4_engine
                                        ~= true
                                    then
                                        return
                                    end

                                    syncNativeState()

                                    if Runtime.Connect4Active
                                        and type(
                                            Runtime.Connect4Snapshot
                                        ) == "table"
                                    then
                                        analyze(
                                            "seat-sync"
                                        )
                                        return
                                    end
                                end
                            end)
                        end
                    end
                )
            end

            if LocalPlayer.Character then
                task.spawn(
                    watchCharacter,
                    LocalPlayer.Character
                )
            end

            Connect(
                LocalPlayer.CharacterAdded,
                watchCharacter
            )

            return true
        end

        Runtime.ResolveConnect4Modules =
            resolveModules
        Runtime.ResolveConnect4Remotes =
            resolveRemotes
        Runtime.RefreshConnect4SeatState =
            refreshSeatState
        Runtime.DetectConnect4Context =
            detectCurrentContext
        Runtime.ResolveConnect4MyColor =
            resolveMyColor
        Runtime.SyncConnect4NativeState =
            syncNativeState
        Runtime.ClearConnect4BestMove =
            clearVisual
        Runtime.UpdateConnect4BestMoveColor =
            updateVisualColor
        Runtime.UpdateConnect4BestMoveLighting =
            updateVisualLighting
        Runtime.RefreshConnect4BestMoveVisual =
            refreshVisual
        Runtime.ScheduleConnect4Analysis =
            analyze
        Runtime.HandleConnect4Event =
            handleEvent
        Runtime.InstallConnect4Listeners =
            installListeners

        Runtime.SetConnect4Enabled =
            function(enabled)
                Runtime.Connect4Enabled =
                    enabled == true

                Runtime.Connect4SearchSerial += 1

                if not Runtime.Connect4Enabled then
                    Runtime.Connect4SearchSerial += 1
                    Runtime.Connect4PendingAnalysis =
                        false
                    Runtime.Connect4PendingAnalysisReason =
                        nil
                    clearVisual()
                    return
                end

                resolveModules()
                installListeners()
                refreshSeatState()
                syncNativeState()

                if Runtime.Connect4Active
                    and type(
                        Runtime.Connect4Snapshot
                    ) == "table"
                then
                    analyze("enabled")
                else
                    task.spawn(function()
                        for retry = 1, 15 do
                            task.wait(0.10)

                            if Flags.other_connect4_engine
                                ~= true
                            then
                                return
                            end

                            syncNativeState()

                            if Runtime.Connect4Active
                                and type(
                                    Runtime.Connect4Snapshot
                                ) == "table"
                            then
                                analyze(
                                    "enable-retry-"
                                    .. tostring(retry)
                                )
                                return
                            end
                        end
                    end)
                end
            end

        resolveModules()
        installListeners()
        detectCurrentContext()
        syncNativeState()

        local pollAccumulator = 0

        Connect(
            RunService.Heartbeat,
            function(dt)
                if Flags.other_connect4_engine
                    ~= true
                then
                    pollAccumulator = 0
                    return
                end

                pollAccumulator +=
                    tonumber(dt) or 0

                if pollAccumulator < 0.50 then
                    return
                end

                pollAccumulator = 0

                local oldTable =
                    Runtime.Connect4TableId
                local oldColor =
                    Runtime.Connect4MyColor
                local oldKey =
                    positionKey(
                        Runtime.Connect4Snapshot
                    )

                syncNativeState()

                local newKey =
                    positionKey(
                        Runtime.Connect4Snapshot
                    )

                local contextChanged =
                    tostring(oldTable or "")
                        ~= tostring(
                            Runtime.Connect4TableId
                            or ""
                        )
                    or oldColor
                        ~= Runtime.Connect4MyColor

                if Runtime.Connect4Active
                    and type(
                        Runtime.Connect4Snapshot
                    ) == "table"
                    and (
                        contextChanged
                        or newKey ~= oldKey
                        or (
                            Runtime.Connect4BestColumn
                                == nil
                            and Runtime.Connect4SearchInFlight
                                ~= true
                        )
                    )
                then
                    analyze(
                        contextChanged
                        and "context-refresh"
                        or "state-refresh"
                    )
                end
            end
        )

        local function onLightingChanged()
            if Flags.other_connect4_engine
                    == true
                and type(
                    Runtime.UpdateConnect4BestMoveLighting
                ) == "function"
            then
                Runtime.UpdateConnect4BestMoveLighting(
                    false
                )
            end
        end

        for _, propertyName in ipairs({
            "Brightness",
            "Ambient",
            "OutdoorAmbient",
            "ExposureCompensation",
            "ClockTime",
        }) do
            pcall(function()
                Connect(
                    Lighting:GetPropertyChangedSignal(
                        propertyName
                    ),
                    onLightingChanged
                )
            end)
        end

        if Runtime.Connect4Enabled
            and Runtime.Connect4Active
            and type(
                Runtime.Connect4Snapshot
            ) == "table"
        then
            analyze("initial")
        end
    end)()

    Connect(Menu._OtherUI.AutoRhythm["on_toggle_change"], function(v)
        Runtime.SetAutoRhythmEnabled(v == true)
    end)
    Connect(Menu._OtherUI.AutoBasketball["on_toggle_change"], function(v)
        Runtime.SetAutoBasketballEnabled(v == true)
    end)
    Connect(Menu._OtherUI.AutoWrestling["on_toggle_change"], function(v)
        Runtime.SetAutoWrestlingEnabled(v == true)
    end)
    Connect(Menu._OtherUI.ChessEngine["on_toggle_change"], function(v)
        Runtime.SetChessEnabled(v == true)
    end)
    Connect(Menu._OtherUI.Connect4Engine["on_toggle_change"], function(v)
        Runtime.SetConnect4Enabled(v == true)
    end)
    Connect(
        Menu._OtherUI.Connect4Engine[
            "on_color_change"
        ],
        function(color)
            Runtime.Connect4MarkerColor =
                color

            if type(
                Runtime.UpdateConnect4BestMoveColor
            ) == "function"
            then
                Runtime.UpdateConnect4BestMoveColor(
                    color
                )
            end
        end
    )
    Connect(Menu._OtherUI.ChessDepth["on_slider_change"], function(v)
        Runtime.ChessStockfishDepth = math.clamp(math.floor(tonumber(v) or 18), 8, 18)
        if Flags.other_chess_engine == true and Runtime.ChessFEN then
            Runtime.ScheduleChessAnalysis("depth-change")
        end
    end)
    Connect(Menu._OtherUI.ChessThinkTime["on_slider_change"], function(v)
        Runtime.ChessStockfishThinkMs = math.clamp(math.floor(tonumber(v) or 100), 20, 100)
    end)
    task.defer(function()
        if Flags.other_auto_rhythm == true then
            Runtime.SetAutoRhythmEnabled(true)
        end
        if Flags.other_auto_basketball == true then
            Runtime.SetAutoBasketballEnabled(true)
        end
        if Flags.other_auto_wrestling == true then
            Runtime.SetAutoWrestlingEnabled(true)
        end
        if Flags.other_chess_engine == true then
            Runtime.SetChessEnabled(true)
        end
    end)
end

do
    local previous = Menu._SoundRuntime
    if previous and type(previous.shutdown) == "function" then
        pcall(previous.shutdown)
    end

    local Runtime = {}
    Menu._SoundRuntime = Runtime

    Runtime.folder = "SilentSolutions/Gakuran/sounds"
    Runtime.connections = {}
    Runtime.characterConnection = nil
    Runtime.boundCharacter = nil
    Runtime.preloadBusy = {}
    Runtime.assetCache = {
        Hit = {},
        Parry = {},
        Dodge = {},
    }
    Runtime.lastOutcomeKey = {
        Hit = nil,
        Parry = nil,
    }
    Runtime.lastOutcomeAt = {
        Hit = 0,
        Parry = 0,
    }
    Runtime.lastDodgeAt = 0

    Runtime.assets = {
        Hit = {
            ["AGPA 2"] = {
                File = "agpa2.mp3",
                Url = "https://raw.githubusercontent.com/O1sSfh78hJ/1/refs/heads/main/HITSOUNDS/agpa2.mp3",
            },
            ["Connect Pacanoff"] = {
                File = "connectpacanoff.mp3",
                Url = "https://raw.githubusercontent.com/O1sSfh78hJ/1/refs/heads/main/HITSOUNDS/connectpacanoff.mp3",
            },
            ["Punch Impact"] = {
                File = "universfield-punch-impact-hit-567196.mp3",
                Url = "https://raw.githubusercontent.com/O1sSfh78hJ/1/refs/heads/main/HITSOUNDS/universfield-punch-impact-hit-567196.mp3",
            },
            ["Stapler"] = {
                File = "stapler.wav",
                Url = "https://raw.githubusercontent.com/O1sSfh78hJ/1/refs/heads/main/HITSOUNDS/stapler.wav",
            },
        },
        Parry = {
            ["Copper Bell"] = {
                File = "copperbell.wav",
                Url = "https://raw.githubusercontent.com/O1sSfh78hJ/1/refs/heads/main/HITSOUNDS/copperbell.wav",
            },
            ["Bird Chirping"] = {
                File = "bird_chirping_for_DH_psalms_audio.mp3",
                Url = "https://raw.githubusercontent.com/O1sSfh78hJ/1/refs/heads/main/HITSOUNDS/bird%20chirping%20for%20DH%20_%20psalms%20audio.mp3",
            },
        },
        Dodge = {
            ["AGPA 1"] = {
                File = "agpa1.mp3",
                Url = "https://raw.githubusercontent.com/O1sSfh78hJ/1/refs/heads/main/HITSOUNDS/agpa1.mp3",
            },
        },
    }

    Runtime.enabled = function(kind)
        if Flags.visual_sounds_master ~= true then
            return false
        end

        if kind == "Parry" then
            return Flags.visual_parry_sounds == true
        elseif kind == "Dodge" then
            return Flags.visual_dodge_sounds == true
        end

        return Flags.visual_hit_sounds == true
    end

    Runtime.selection = function(kind)
        local value

        if kind == "Parry" then
            value = Flags.visual_parry_sound_selection
        elseif kind == "Dodge" then
            value = Flags.visual_dodge_sound_selection
        else
            value = Flags.visual_hit_sound_selection
        end

        if type(value) == "table" then
            value = value[1]
        end

        if type(value) ~= "string" or value == "" then
            if kind == "Parry" then
                return "Copper Bell"
            elseif kind == "Dodge" then
                return "AGPA 1"
            end
            return "AGPA 2"
        end

        return value
    end

    Runtime.volume = function(kind)
        local value

        if kind == "Parry" then
            value = Flags.visual_parry_sound_volume
        elseif kind == "Dodge" then
            value = Flags.visual_dodge_sound_volume
        else
            value = Flags.visual_hit_sound_volume
        end

        return math.clamp(
            (tonumber(value) or 100) / 100,
            0,
            2
        )
    end

    Runtime.ensureFolder = function()
        if type(isfolder) == "function" then
            local ok, exists = pcall(isfolder, Runtime.folder)
            if ok and exists == true then
                return true
            end
        end

        if type(makefolder) ~= "function" then
            return false
        end

        if type(isfolder) == "function" then
            local okRoot, rootExists = pcall(isfolder, "SilentSolutions/Gakuran")
            if not okRoot or rootExists ~= true then
                pcall(makefolder, "SilentSolutions/Gakuran")
            end
        else
            pcall(makefolder, "SilentSolutions/Gakuran")
        end

        pcall(makefolder, Runtime.folder)

        if type(isfolder) == "function" then
            local checkOk, exists = pcall(isfolder, Runtime.folder)
            return checkOk and exists == true
        end

        return true
    end

    Runtime.cacheLocalAsset = function(kind, selection, path)
        local assetFunction =
            type(getcustomasset) == "function"
                and getcustomasset
            or (
                type(getsynasset) == "function"
                    and getsynasset
                or nil
            )

        if type(assetFunction) ~= "function" then
            return nil
        end

        local ok, asset = pcall(assetFunction, path)
        if not ok or type(asset) ~= "string" or asset == "" then
            return nil
        end

        Runtime.assetCache[kind] =
            Runtime.assetCache[kind] or {}
        Runtime.assetCache[kind][selection] = asset

        return asset
    end

    Runtime.ensureKind = function(kind)
        local group = Runtime.assets[kind]
        if type(group) ~= "table" then
            return false
        end

        if not Runtime.ensureFolder() then
            return false
        end

        local ready = true

        for selection, data in pairs(group) do
            local path =
                Runtime.folder
                .. "/"
                .. tostring(data.File)

            local exists = false

            if type(isfile) == "function" then
                local ok, value = pcall(isfile, path)
                exists = ok and value == true
            end

            if not exists then
                local okDownload, body =
                    pcall(function()
                        return game:HttpGet(data.Url)
                    end)

                if okDownload
                    and type(body) == "string"
                    and #body > 128
                    and type(writefile) == "function"
                then
                    local okWrite = pcall(writefile, path, body)
                    exists = okWrite
                end
            end

            if exists then
                Runtime.cacheLocalAsset(
                    kind,
                    selection,
                    path
                )
            else
                ready = false
            end
        end

        return ready
    end

    Runtime.requestPreload = function(kind)
        if Runtime.preloadBusy[kind] == true then
            return
        end

        Runtime.preloadBusy[kind] = true

        task.spawn(function()
            pcall(Runtime.ensureKind, kind)
            Runtime.preloadBusy[kind] = nil
        end)
    end

    Runtime.getCachedAsset = function(kind, selection)
        local cache = Runtime.assetCache[kind]
        local cached =
            cache
            and cache[selection]

        if type(cached) == "string"
            and cached ~= ""
        then
            return cached
        end

        local group = Runtime.assets[kind]
        local data =
            group
            and group[selection]

        if not data then
            return nil
        end

        local path =
            Runtime.folder
            .. "/"
            .. tostring(data.File)

        local exists = false
        if type(isfile) == "function" then
            local ok, value = pcall(isfile, path)
            exists = ok and value == true
        end

        if not exists then
            Runtime.requestPreload(kind)
            return nil
        end

        return Runtime.cacheLocalAsset(
            kind,
            selection,
            path
        )
    end

    Runtime.play = function(kind)
        kind = tostring(kind or "Hit")

        if not Runtime.enabled(kind) then
            return false
        end

        local selection = Runtime.selection(kind)
        local asset =
            Runtime.getCachedAsset(
                kind,
                selection
            )

        if not asset then
            return false
        end

        local sound = Instance.new("Sound")
        sound.Name =
            kind == "Parry"
                and "SilentSolutionsParrySound"
            or kind == "Dodge"
                and "SilentSolutionsDodgeSound"
            or "SilentSolutionsHitSound"
        sound.SoundId = asset
        sound.Volume = Runtime.volume(kind)
        sound.Parent = game:GetService("SoundService")

        local endedConnection
        endedConnection =
            sound.Ended:Connect(function()
                if endedConnection then
                    endedConnection:Disconnect()
                    endedConnection = nil
                end

                if sound and sound.Parent then
                    sound:Destroy()
                end
            end)

        local okPlay = pcall(sound.Play, sound)

        if not okPlay then
            if endedConnection then
                endedConnection:Disconnect()
            end

            sound:Destroy()
            return false
        end

        task.delay(10, function()
            if sound and sound.Parent then
                pcall(sound.Destroy, sound)
            end
        end)

        return true
    end

    Runtime.playWhenReady = function(kind)
        kind = tostring(kind or "Hit")

        if not Runtime.enabled(kind) then
            return
        end

        task.spawn(function()
            if not Runtime.enabled(kind) then
                return
            end

            local selection =
                Runtime.selection(kind)
            local asset =
                Runtime.getCachedAsset(
                    kind,
                    selection
                )

            if not asset then
                pcall(
                    Runtime.ensureKind,
                    kind
                )
            end

            if Runtime.enabled(kind) then
                Runtime.play(kind)
            end
        end)
    end

    Runtime.isLocalActor = function(value)
        local character = LocalPlayer.Character

        if value == LocalPlayer
            or (character and value == character)
        then
            return true
        end

        if typeof(value) == "Instance" then
            if value:IsA("Player") then
                return value == LocalPlayer
            elseif value:IsA("Model") then
                return character ~= nil
                    and value == character
            end
        end

        local name = tostring(value or "")
        if name == "" then
            return false
        end

        return name == tostring(LocalPlayer.Name)
            or name == tostring(LocalPlayer.DisplayName)
            or (
                character
                and name == tostring(character.Name)
            )
    end

    Runtime.playDeduped = function(kind, key, window)
        local now = os.clock()
        local oldKey = Runtime.lastOutcomeKey[kind]
        local oldAt =
            tonumber(
                Runtime.lastOutcomeAt[kind]
            ) or 0

        if oldKey == key
            and now - oldAt < (window or 0.12)
        then
            return
        end

        Runtime.lastOutcomeKey[kind] = key
        Runtime.lastOutcomeAt[kind] = now

        Runtime.playWhenReady(kind)
    end

    Runtime.handleCombatOutcome = function(
        eventName,
        attacker,
        defender
    )
        eventName = tostring(eventName or "")

        if eventName == "M1Hit"
            or eventName == "M2Hit"
        then
            if not Runtime.enabled("Hit")
                or not Runtime.isLocalActor(attacker)
                or Runtime.isLocalActor(defender)
            then
                return
            end

            Runtime.playDeduped(
                "Hit",
                eventName
                    .. "|"
                    .. tostring(attacker)
                    .. "|"
                    .. tostring(defender),
                0.12
            )

            return
        end

        if eventName == "M1PerfectBlocked"
            or eventName == "M2PerfectBlocked"
        then
            if not Runtime.enabled("Parry")
                or not Runtime.isLocalActor(defender)
            then
                return
            end

            Runtime.playDeduped(
                "Parry",
                eventName
                    .. "|"
                    .. tostring(attacker)
                    .. "|"
                    .. tostring(defender),
                0.12
            )
        end
    end

    Runtime.connect = function(signal, callback)
        local connection = signal:Connect(callback)
        Runtime.connections[#Runtime.connections + 1] =
            connection
        return connection
    end

    Runtime.installCombatListeners = function()
        local shared =
            ReplicatedStorage:FindFirstChild("Shared")
        local network =
            shared
            and shared:FindFirstChild("Network")

        if not network then
            return
        end

        local broadcast =
            network:FindFirstChild(
                "CombatBroadcastURE"
            )

        if broadcast
            and (
                broadcast:IsA("UnreliableRemoteEvent")
                or broadcast:IsA("RemoteEvent")
            )
        then
            Runtime.connect(
                broadcast.OnClientEvent,
                function(eventName, attacker, defender)
                    task.defer(
                        Runtime.handleCombatOutcome,
                        eventName,
                        attacker,
                        defender
                    )
                end
            )
        end

        local cosmetic =
            network:FindFirstChild(
                "CombatClientRemoteEvent"
            )

        if cosmetic
            and cosmetic:IsA("RemoteEvent")
        then
            Runtime.connect(
                cosmetic.OnClientEvent,
                function(eventName, ...)
                    if eventName
                        ~= "CombatPairCosmetic"
                    then
                        return
                    end

                    local args = table.pack(...)

                    task.defer(
                        Runtime.handleCombatOutcome,
                        args[1],
                        args[2],
                        args[3]
                    )
                end
            )
        end
    end

    Runtime.onAutoDodgeCommitted = function()
        if not Runtime.enabled("Dodge") then
            return
        end

        local now = os.clock()

        if now
            - (
                tonumber(
                    Runtime.lastDodgeAt
                ) or 0
            )
            < 0.10
        then
            return
        end

        Runtime.lastDodgeAt = now

        Runtime.playWhenReady("Dodge")
    end

    Runtime.shutdown = function()
        for index = #Runtime.connections, 1, -1 do
            local connection =
                Runtime.connections[index]

            if connection then
                pcall(
                    connection.Disconnect,
                    connection
                )
            end

            Runtime.connections[index] = nil
        end

    end

    Runtime.ensureFolder()

    Runtime.installCombatListeners()

    if Flags.visual_sounds_master == true then
        if Flags.visual_hit_sounds == true then
            Runtime.requestPreload("Hit")
        end
        if Flags.visual_parry_sounds == true then
            Runtime.requestPreload("Parry")
        end
        if Flags.visual_dodge_sounds == true then
            Runtime.requestPreload("Dodge")
        end
    end
end

local CombatSystemClient = ReplicatedStorage:WaitForChild("CombatSystemClient")
local CombatFolder = CombatSystemClient:WaitForChild("Combat")

local CombatConfig = require(ReplicatedStorage.Shared.Config.CombatConfig)

do
    local originalGetStyleCQCRing =
        CombatConfig.GetStyleCQCRing

    if type(originalGetStyleCQCRing) == "function"
        and rawget(env, "__SilentCQCConfigWrapped") ~= true
    then
        CombatConfig.GetStyleCQCRing = function(style, ...)
            local config = originalGetStyleCQCRing(style, ...)

            if tostring(style):lower() == "cqc"
                and type(config) == "table"
            then
                config.Debug = false
            end

            return config
        end

        rawset(env, "__SilentCQCConfigWrapped", true)
    end

    pcall(function()
        if type(CombatConfig.GetStyleCQCRing) == "function" then
            local ringConfig = CombatConfig.GetStyleCQCRing("cqc")
            if type(ringConfig) == "table" then
                ringConfig.Debug = false
            end
        end
    end)

    if type(getloadedmodules) == "function" then
        local okModules, loadedModules = pcall(getloadedmodules)
        if okModules and type(loadedModules) == "table" then
            for _, moduleScript in ipairs(loadedModules) do
                if typeof(moduleScript) == "Instance"
                    and moduleScript:IsA("ModuleScript")
                    and moduleScript.Name == "CQCVfx"
                    and moduleScript.Parent ~= nil
                then
                    local okModule, moduleValue = pcall(require, moduleScript)
                    if okModule then
                        local seen = {}
                        local function disableDebug(value, depth)
                            depth = depth or 0
                            if depth > 5 then
                                return
                            end

                            local valueType = type(value)
                            if valueType == "table" then
                                if seen[value] then
                                    return
                                end
                                seen[value] = true

                                if rawget(value, "Debug") ~= nil then
                                    rawset(value, "Debug", false)
                                end
                                if rawget(value, "debug") ~= nil then
                                    rawset(value, "debug", false)
                                end
                                if rawget(value, "DEBUG") ~= nil then
                                    rawset(value, "DEBUG", false)
                                end

                                for _, child in pairs(value) do
                                    disableDebug(child, depth + 1)
                                end
                            elseif valueType == "function" then
                                local getUps = getupvalues
                                    or (debug and debug.getupvalues)
                                if type(getUps) == "function" then
                                    local okUps, ups = pcall(getUps, value)
                                    if okUps and type(ups) == "table" then
                                        for _, up in pairs(ups) do
                                            disableDebug(up, depth + 1)
                                        end
                                    end
                                end
                            end
                        end

                        disableDebug(moduleValue, 0)
                    end
                    break
                end
            end
        end
    end
end

local CombatAnimationUtils = require(ReplicatedStorage.Shared.Utils.CombatAnimationUtils)
local CombatStepUtils = require(ReplicatedStorage.Shared.Utils.CombatStepUtils)

local function requireLoadedModuleByName(name)
    local direct = ReplicatedStorage:FindFirstChild(name, true)

    if direct and direct:IsA("ModuleScript") then
        local ok, result = pcall(require, direct)

        if ok then
            return result, direct
        end
    end

    if type(getloadedmodules) == "function" then
        local ok, modules = pcall(getloadedmodules)

        if ok and type(modules) == "table" then
            for _, moduleScript in ipairs(modules) do
                if typeof(moduleScript) == "Instance"
                    and moduleScript:IsA("ModuleScript")
                    and moduleScript.Parent ~= nil
                    and moduleScript.Name == name
                then
                    local okDescendant, inGame = pcall(
                        moduleScript.IsDescendantOf,
                        moduleScript,
                        game
                    )

                    if okDescendant and inGame == true then
                        local requireOk, result = pcall(require, moduleScript)

                        if requireOk then
                            return result, moduleScript
                        end
                    end
                end
            end
        end
    end

    return nil, nil
end

local CombatUtils, CombatUtilsModule = requireLoadedModuleByName("CombatUtils")

if type(CombatUtils) ~= "table" then
    CombatUtils = {
        GetCharacterHeight = function(character)
            local humanoid = character and character:FindFirstChildOfClass("Humanoid")

            if humanoid then
                return humanoid.HipHeight + 5
            end

            local root = character and (
                character:FindFirstChild("HumanoidRootPart")
                or character.PrimaryPart
            )

            if root then
                return root.Size.Y + 3
            end

            return nil
        end,

        GetAttackSpeedMultiplier = function()
            return 1
        end,
    }
end

local DEBUG_ROOT = "SilentSolutions/Gakuran"
local DEBUG_FOLDER = DEBUG_ROOT .. "/debug"
local DEBUG_LATEST = DEBUG_FOLDER .. "/autoparry_debug_latest.txt"

local debugLines = {}
local debugEventCounts = {}
Menu._AutoParryDebugOpponents =
    Menu._AutoParryDebugOpponents or {}
Menu._AutoParryLocalAttackDebug =
    Menu._AutoParryLocalAttackDebug
    or {
        style = "",
        manualM1Count = 0,
        manualM2Count = 0,
        scriptedM1Count = 0,
        scriptedM2Count = 0,
        lastManualAttack = "",
        lastManualAttackAt = 0,
        lastManualM1At = 0,
        lastManualM2At = 0,
        scriptedType = "",
        scriptedSource = "",
        scriptedUntil = 0,
    }
local buildAutoParryDebugExtra = nil
local debugStart = os.clock()
local debugSequence = 0
local MAX_DEBUG_LINES = 9000

Menu._APDebugBufferState = {
    head = 1,
    count = 0,
}

Menu._APDebugFieldKeyCache =
    Menu._APDebugFieldKeyCache
    or {}

Menu._APDebugPushLine = function(line)
    local state = Menu._APDebugBufferState

    if state.count < MAX_DEBUG_LINES then
        local index =
            ((state.head + state.count - 2) % MAX_DEBUG_LINES) + 1
        debugLines[index] = line
        state.count += 1
        return
    end

    debugLines[state.head] = line
    state.head = (state.head % MAX_DEBUG_LINES) + 1
end

Menu._APDebugSnapshot = function()
    local state = Menu._APDebugBufferState
    local snapshot =
        table.create and table.create(state.count)
        or {}

    for offset = 0, state.count - 1 do
        local index =
            ((state.head + offset - 2) % MAX_DEBUG_LINES) + 1
        snapshot[#snapshot + 1] = debugLines[index]
    end

    return snapshot
end

local function ensureFolder(path)
    if type(isfolder) == "function" and isfolder(path) then
        return true
    end

    if type(makefolder) ~= "function" then
        return false
    end

    local ok = pcall(makefolder, path)

    return ok or (type(isfolder) == "function" and isfolder(path))
end

local function debugValue(value)
    local kind = typeof(value)

    if kind == "Vector3" then
        return string.format("(%.3f,%.3f,%.3f)", value.X, value.Y, value.Z)
    end

    if kind == "CFrame" then
        local p = value.Position
        return string.format("CFrame(%.3f,%.3f,%.3f)", p.X, p.Y, p.Z)
    end

    if kind == "Instance" then
        local ok, name = pcall(value.GetFullName, value)
        return ok and name or tostring(value)
    end

    return tostring(value)
end

local function debugLog(eventName, fields, force)
    if not force and Flags.ap_enable ~= true then
        return
    end

    if type(fields) == "table" then
        if eventName == "PARRY_PRESS" and fields.accepted == true then
            autoParryDebugUi.attemptSerial =
                (tonumber(autoParryDebugUi.attemptSerial) or 0) + 1
            fields.attemptId = autoParryDebugUi.attemptSerial
            fields.pressClock = os.clock()
        end
        local ownerNameForDebug =
            tostring(fields.owner or "")
        local localAttackDebug =
            Menu._AutoParryLocalAttackDebug

        if ownerNameForDebug ~= "" then
            if fields.myStyle == nil
                and localAttackDebug
                and tostring(localAttackDebug.style or "") ~= ""
            then
                fields.myStyle =
                    tostring(localAttackDebug.style)
            end

            if type(Menu._GetAutoParryFacingDebug)
                == "function"
                and fields.facingOpponent == nil
            then
                local okFacing, facing =
                    pcall(
                        Menu._GetAutoParryFacingDebug,
                        ownerNameForDebug
                    )

                if okFacing
                    and type(facing) == "table"
                then
                    fields.facingOpponent =
                        facing.facingOpponent
                    fields.facingDot =
                        facing.facingDot
                    fields.facingAngle =
                        facing.facingAngle
                    fields.attackerFacingOpponent =
                        facing.attackerFacingOpponent
                    fields.attackerFacingDot =
                        facing.attackerFacingDot
                    fields.attackerFacingAngle =
                        facing.attackerFacingAngle
                end
            end

            if localAttackDebug then
                local lastManualAt =
                    tonumber(
                        localAttackDebug.lastManualAttackAt
                    ) or 0
                local manualAge =
                    os.clock() - lastManualAt

                if lastManualAt > 0
                    and manualAge >= 0
                    and manualAge <= 1
                then
                    fields.manualAttackRecent =
                        tostring(
                            localAttackDebug.lastManualAttack
                                or ""
                        )
                    fields.manualAttackAge =
                        manualAge
                end
            end
        end
    end

    if type(fields) == "table"
        and tostring(fields.owner or "") ~= ""
        and tostring(fields.owner or "")
            ~= tostring(LocalPlayer and LocalPlayer.Name or "")
    then
        local ownerName = tostring(fields.owner)
        local opponents = Menu._AutoParryDebugOpponents
        local opponent =
            opponents[ownerName]
            or {
                name = ownerName,
                style = "",
                events = 0,
                firstSeenAt = os.clock(),
                lastSeenAt = os.clock(),
                lastDistance = nil,
                closestDistance = nil,
                farthestDistance = nil,
                height = nil,
                localHeight = nil,
                heightDiff = nil,
            }

        opponents[ownerName] = opponent
        opponent.events =
            (tonumber(opponent.events) or 0) + 1
        opponent.lastSeenAt = os.clock()

        if tostring(fields.style or "") ~= "" then
            opponent.style = tostring(fields.style)
        end

        local fieldDistance = tonumber(fields.distance)
        if fieldDistance then
            opponent.lastDistance = fieldDistance
            opponent.closestDistance =
                opponent.closestDistance
                    and math.min(
                        opponent.closestDistance,
                        fieldDistance
                    )
                    or fieldDistance
            opponent.farthestDistance =
                opponent.farthestDistance
                    and math.max(
                        opponent.farthestDistance,
                        fieldDistance
                    )
                    or fieldDistance
        end

        local fieldHeightDiff = tonumber(fields.heightDiff)
        if fieldHeightDiff then
            opponent.heightDiff = fieldHeightDiff
        end

        if fields.facingOpponent ~= nil then
            opponent.lastFacingOpponent =
                fields.facingOpponent == true
            opponent.lastFacingDot =
                tonumber(fields.facingDot)
            opponent.lastFacingAngle =
                tonumber(fields.facingAngle)
            opponent.lastFacingAt =
                os.clock()
        end

        if fields.attackerFacingOpponent ~= nil then
            opponent.lastAttackerFacingOpponent =
                fields.attackerFacingOpponent == true
            opponent.lastAttackerFacingDot =
                tonumber(fields.attackerFacingDot)
            opponent.lastAttackerFacingAngle =
                tonumber(fields.attackerFacingAngle)
        end

        if eventName == "ANIM_ATTACK"
            or eventName == "PREDICT_ANIM"
        then
            local fightingSpeed =
                tonumber(
                    fields.visualTrackSpeed
                        or fields.rawTrackSpeed
                        or fields.trackSpeed
                )

            if fightingSpeed
                and fightingSpeed >= 0.2
                and fightingSpeed <= 3
            then
                opponent.lastFightingSpeed =
                    fightingSpeed
                opponent.maxFightingSpeed =
                    math.max(
                        tonumber(
                            opponent.maxFightingSpeed
                        ) or fightingSpeed,
                        fightingSpeed
                    )
                opponent.speedSampleCount =
                    (tonumber(
                        opponent.speedSampleCount
                    ) or 0) + 1
                opponent.speedSampleSum =
                    (tonumber(
                        opponent.speedSampleSum
                    ) or 0) + fightingSpeed
            end

            local combatSpeed =
                tonumber(
                    fields.combatTimelineSpeed
                        or fields.ownerAttackSpeed
                )

            if combatSpeed
                and combatSpeed >= 0.2
                and combatSpeed <= 3
            then
                opponent.lastCombatTimelineSpeed =
                    combatSpeed
            end

            if fields.speedDesynced == true then
                opponent.speedDesyncObserved =
                    true
                opponent.lastSpeedDesyncAt =
                    os.clock()
            end
        end

        if eventName == "AP_HAKARI_STOP_DESYNC" then
            opponent.lifecycleDesyncObserved = true
            opponent.lastLifecycleDesyncAt = os.clock()
        end

        if eventName == "AP_BREAKER_DETECTED"
            or eventName == "RESOLVER_AP_BREAKER_BAIT"
            or eventName == "AP_BREAKER_TIMELINE_ANCHOR"
        then
            opponent.autoParryBreakerObserved = true
            opponent.lastAutoParryBreakerAt = os.clock()
            if eventName == "RESOLVER_AP_BREAKER_BAIT" then
                opponent.autoParryBreakerBaits =
                    (tonumber(opponent.autoParryBreakerBaits) or 0) + 1
            end
        end

        local sampleNow = os.clock()

        if sampleNow
            >= (
                tonumber(opponent.nextLiveSampleAt)
                or 0
            )
        then
            opponent.nextLiveSampleAt =
                sampleNow + 0.15

            local ownerPlayer =
                Players:FindFirstChild(ownerName)
            local ownerCharacter =
                ownerPlayer and ownerPlayer.Character or nil
            local localCharacter =
                LocalPlayer and LocalPlayer.Character or nil

            if ownerCharacter and ownerCharacter.Parent then
                local okHeight, ownerHeight = pcall(
                    CombatUtils.GetCharacterHeight,
                    ownerCharacter
                )

                if okHeight and tonumber(ownerHeight) then
                    opponent.height = tonumber(ownerHeight)
                end

                local ownerRoot =
                    ownerCharacter:FindFirstChild("HumanoidRootPart")
                    or ownerCharacter.PrimaryPart
                local localRoot =
                    localCharacter
                    and (
                        localCharacter:FindFirstChild("HumanoidRootPart")
                        or localCharacter.PrimaryPart
                    )
                    or nil

                if ownerRoot and localRoot then
                    local liveDistance =
                        (ownerRoot.Position - localRoot.Position).Magnitude
                    opponent.lastDistance = liveDistance
                    opponent.closestDistance =
                        opponent.closestDistance
                            and math.min(
                                opponent.closestDistance,
                                liveDistance
                            )
                            or liveDistance
                    opponent.farthestDistance =
                        opponent.farthestDistance
                            and math.max(
                                opponent.farthestDistance,
                                liveDistance
                            )
                            or liveDistance
                end
            end

            if localCharacter and localCharacter.Parent then
                local okLocalHeight, localHeight = pcall(
                    CombatUtils.GetCharacterHeight,
                    localCharacter
                )

                if okLocalHeight and tonumber(localHeight) then
                    opponent.localHeight = tonumber(localHeight)

                    if opponent.height then
                        opponent.heightDiff =
                            opponent.height - opponent.localHeight
                    end
                end
            end
        end
    end

    debugSequence = debugSequence + 1
    debugEventCounts[eventName] = (debugEventCounts[eventName] or 0) + 1

    local parts = {
        string.format("[%06d +%.6f] %s", debugSequence, os.clock() - debugStart, tostring(eventName))
    }

    if type(fields) == "table" then
        local fieldCount = 0

        for _ in pairs(fields) do
            fieldCount += 1
        end

        local cacheKey =
            tostring(eventName)
                .. ":"
                .. tostring(fieldCount)
        local keys =
            Menu._APDebugFieldKeyCache[
                cacheKey
            ]

        if not keys then
            keys = {}

            for key in pairs(fields) do
                keys[#keys + 1] =
                    tostring(key)
            end

            table.sort(keys)
            Menu._APDebugFieldKeyCache[
                cacheKey
            ] = keys
        end

        for _, key in ipairs(keys) do
            local value =
                fields[key]

            if value ~= nil then
                parts[#parts + 1] =
                    key
                        .. "="
                        .. debugValue(value)
            end
        end
    end

    Menu._APDebugPushLine(
        table.concat(parts, " | ")
    )



    if eventName == "SERVER_HITBOX_CONFIRM" and type(fields) == "table" then
        local errorSeconds = tonumber(fields.predictedContactError)
        local nowAccuracy = os.clock()
        local matchedIndex = nil

        for index = #autoParryDebugUi.pendingParries, 1, -1 do
            local attempt = autoParryDebugUi.pendingParries[index]
            local age = nowAccuracy - (tonumber(attempt.at) or 0)

            if age > 1.5 then
                table.remove(autoParryDebugUi.pendingParries, index)
            elseif not matchedIndex
                and tostring(attempt.owner or "") == tostring(fields.owner or "")
                and tostring(attempt.attack or "") == tostring(fields.attack or "")
                and (
                    tostring(attempt.swingId or "") == ""
                    or tostring(fields.swingId or "") == ""
                    or tostring(attempt.swingId) == tostring(fields.swingId)
                )
            then
                matchedIndex = index
            end
        end

        for index = #autoParryDebugUi.recentServerAccuracy, 1, -1 do
            if nowAccuracy - (tonumber(autoParryDebugUi.recentServerAccuracy[index].at) or 0) > 1.5 then
                table.remove(autoParryDebugUi.recentServerAccuracy, index)
            end
        end

        if errorSeconds then
            local threshold = math.clamp(
                tonumber(CombatConfig.Block.PerfectBlockWindow) or 0.125,
                0.07,
                0.20
            )
            local authoritativeHit = math.abs(errorSeconds) <= threshold
            autoParryDebugUi.lastErrorMs = errorSeconds * 1000

            if matchedIndex then
                table.remove(autoParryDebugUi.pendingParries, matchedIndex)

                if not authoritativeHit then
                    setAutoParryDebugStatus("timing miss", 0.9)
                end
            else
                autoParryDebugUi.recentServerAccuracy[#autoParryDebugUi.recentServerAccuracy + 1] = {
                    at = nowAccuracy,
                    owner = fields.owner,
                    attack = fields.attack,
                    swingId = fields.swingId,
                    hit = authoritativeHit,
                }
            end
        end
    end

    if eventName == "PARRY_PRESS" and type(fields) == "table" then
        if fields.accepted == true then
            local nowAccuracy = os.clock()

            autoParryDebugUi.accuracySamples += 1
            autoParryDebugUi.pendingSuccessfulParries[#autoParryDebugUi.pendingSuccessfulParries + 1] = {
                at = nowAccuracy,
                attemptId = fields.attemptId,
                owner = fields.owner,
                attack = fields.attack,
                swingId = fields.swingId,
                source = fields.source,
                style = fields.style,
                animationName = fields.animationName,
                distance = fields.distance,
                predictedContactIn = fields.predictedContactIn,
            }

            refreshAutoParryDebugAccuracy()
            setAutoParryDebugStatus("parry " .. tostring(fields.attack or "attack"), 0.75)
        else
            setAutoParryDebugStatus("parry retry", 0.65)
        end
    elseif eventName == "AUTOPUNISH_PARRY_CONFIRMED"
        or eventName == "AUTOPUNISH_PARRY_STUN"
    then
        local nowAccuracy = os.clock()

        if nowAccuracy - (tonumber(autoParryDebugUi.lastSuccessAt) or 0) > 0.12 then
            local matchedIndex = nil

            for index = #autoParryDebugUi.pendingSuccessfulParries, 1, -1 do
                local attempt = autoParryDebugUi.pendingSuccessfulParries[index]
                if nowAccuracy - (tonumber(attempt.at) or 0) > 2.0 then
                    table.remove(autoParryDebugUi.pendingSuccessfulParries, index)
                elseif not matchedIndex then
                    matchedIndex = index
                end
            end

            if matchedIndex then
                table.remove(autoParryDebugUi.pendingSuccessfulParries, matchedIndex)
                autoParryDebugUi.accuracyHits += 1
                autoParryDebugUi.lastSuccessAt = nowAccuracy
                refreshAutoParryDebugAccuracy()
            end
        end

        setAutoParryDebugStatus("parry success", 0.8)
    elseif eventName == "SERVER_EARLY_CORRECTION" then
        setAutoParryDebugStatus("timing correction", 0.85)
    elseif eventName == "PREDICT_SERVER_FALLBACK" then
        setAutoParryDebugStatus("server fallback", 0.8)
    elseif eventName == "BOXING_COUNTER_FIRE" then
        setAutoParryDebugStatus("boxing counter", 0.85)
    elseif eventName == "AUTOPUNISH_M1" then
        setAutoParryDebugStatus("autopunish M1", 0.85)
    elseif eventName == "AUTOPUNISH_M2" then
        setAutoParryDebugStatus("autopunish M2", 0.85)
    elseif eventName == "DODGE_SPECIAL_COMMIT" and type(fields) == "table" then
        local kind = tostring(fields.kind or "")
        if kind == "wrestling_antigrab" then
            setAutoParryDebugStatus("wrestling anti-grab", 0.9)
        elseif kind == "kure_antigrab" then
            setAutoParryDebugStatus("kure M2 dodge", 0.9)
        elseif kind == "hakari_double_read" then
            setAutoParryDebugStatus("hakari double read", 0.9)
        else
            setAutoParryDebugStatus("anti-grab", 0.9)
        end
    elseif eventName == "DODGE_COMMIT" then
        setAutoParryDebugStatus("dodge", 0.8)
    elseif eventName == "MODULE_FAIL" then
        setAutoParryDebugStatus("module issue", 1.5)
    end
end

Menu._ScriptRuntime:Track(
    UserInputService.InputBegan:Connect(function(input, gameProcessedEvent)
        local inputType = input and input.UserInputType
        local attackType = inputType == Enum.UserInputType.MouseButton1
                and "M1"
            or inputType == Enum.UserInputType.MouseButton2
                and "M2"
            or nil

        if not attackType then
            return
        end

        local state = Menu._AutoParryLocalAttackDebug
        local nowInput = os.clock()
        local character = LocalPlayer and LocalPlayer.Character

        if gameProcessedEvent ~= true and state then
            state.lastManualAttack = attackType
            state.lastManualAttackAt = nowInput
            if attackType == "M1" then
                state.manualM1Count = (tonumber(state.manualM1Count) or 0) + 1
                state.lastManualM1At = nowInput
            else
                state.manualM2Count = (tonumber(state.manualM2Count) or 0) + 1
                state.lastManualM2At = nowInput
            end
        end

        if gameProcessedEvent ~= true
            and attackType == "M2"
            and Flags.ap_auto_face == true
            and Menu._AutoFaceRuntime
            and type(Menu._AutoFaceRuntime.lockNearestForLocalM2) == "function"
        then
            pcall(Menu._AutoFaceRuntime.lockNearestForLocalM2)
        end

        -- Main322: manual AP Breaker priming happens only when the
        -- game's CombatRemoteClient accepts the corresponding attack path.

        debugLog("LOCAL_INPUT_EDGE", {
            attack = attackType,
