local function getCharacter()
    return LocalPlayer.Character
end

local function getRoot(character)
    if not character then
        return nil
    end

    return character:FindFirstChild("HumanoidRootPart")
        or character.PrimaryPart
end

local function getCombatType(character)
    if not character then
        return "Base"
    end

    local data = character:FindFirstChild("PlayerData")
    local combatType = data and data:GetAttribute("CombatType")

    if typeof(combatType) ~= "string" or combatType == "" then
        return "Base"
    end

    return combatType
end

local moduleCache = {}

local function getCombatModule(name)
    local character = getCharacter()
    local combatType = getCombatType(character)
    local key = combatType .. "/" .. name

    if moduleCache[key] ~= nil then
        return moduleCache[key] or nil
    end

    local folder = CombatFolder:FindFirstChild(combatType) or CombatFolder:FindFirstChild("Base")
    local moduleScript = folder and folder:FindFirstChild(name)

    if not moduleScript or not moduleScript:IsA("ModuleScript") then
        moduleCache[key] = false
        return nil
    end

    local ok, module = pcall(require, moduleScript)

    if not ok or type(module) ~= "table" then
        moduleCache[key] = false

        debugLog("MODULE_FAIL", {
            module = name,
            combatType = combatType,
            error = module,
        })

        return nil
    end

    moduleCache[key] = module
    return module
end

local function ensureEquipped()
    local character = getCharacter()

    if not character then
        return false, "no_character"
    end

    if character:GetAttribute("Equip") == true then
        return true, "already_equipped"
    end

    return false, "not_equipped"
end

local pingSamples = {
    _count = 0,
    _index = 0,
}
local pingAccumulator = 0

local function readStatsPing()
    local ok, result = pcall(function()
        local network = Stats:FindFirstChild("Network")
        local serverStats = network and network:FindFirstChild("ServerStatsItem")
        local item = serverStats and serverStats:FindFirstChild("Data Ping")

        if not item then
            return nil
        end

        local value

        if type(item.GetValue) == "function" then
            value = item:GetValue()
        end

        if typeof(value) == "number" and value > 0 then
            return value / 1000
        end

        if type(item.GetValueString) == "function" then
            local valueString = item:GetValueString()
            local number = tonumber(string.match(valueString or "", "[%d%.]+"))

            if number and number > 0 then
                return number / 1000
            end
        end

        return nil
    end)

    return ok and result or nil
end

local function readBestPing()
    local playerPing
    local ok = pcall(function()
        playerPing = LocalPlayer:GetNetworkPing()
    end)

    if not ok
        or typeof(playerPing) ~= "number"
        or playerPing <= 0
        or playerPing ~= playerPing
    then
        playerPing = nil
    end

    local statsPing = readStatsPing()
    local selected

    if not playerPing and not statsPing then
        selected = 0.05
    elseif not playerPing then
        selected = statsPing
    elseif not statsPing then
        selected = playerPing
    else
        local lower =
            math.min(
                playerPing,
                statsPing
            )
        local upper =
            math.max(
                playerPing,
                statsPing
            )

        if upper > lower * 1.35 then
            selected = lower
        else
            selected =
                (
                    playerPing
                    + statsPing
                ) * 0.5
        end
    end

    selected =
        math.clamp(
            tonumber(selected) or 0.05,
            0.005,
            1.5
        )

    Menu._APPingSourceSnapshot = {
        player =
            playerPing,
        stats =
            statsPing,
        selected =
            selected,
    }

    return selected
end

local function pushPingSample()
    pingSamples._index =
        (pingSamples._index % 24) + 1
    pingSamples[pingSamples._index] =
        readBestPing()
    pingSamples._count =
        math.min(
            pingSamples._count + 1,
            24
        )
end

for _ = 1, 4 do
    pushPingSample()
end

local function medianPing()
    if pingSamples._count == 0 then
        return math.min(readBestPing(), 0.5)
    end

    local copy =
        table.create and table.create(pingSamples._count)
        or {}

    for index = 1, pingSamples._count do
        copy[index] = pingSamples[index]
    end

    table.sort(copy)

    local count = #copy
    local middle = math.floor((count + 1) / 2)

    local median

    if count % 2 == 0 then
        median = (copy[middle] + copy[middle + 1]) * 0.5
    else
        median = copy[middle]
    end

    return math.min(median, 0.5)
end




