    }, true)
end)

local function getUplink()
    local ping = medianPing()



    local up = math.clamp(ping * 1.0 + 0.008, 0.010, 0.500)

    if ping < 0.090 then
        up = up + 0.030 * (1 - ping / 0.090)
    end

    return ping, up
end

local frameTimes =
    table.create and table.create(60)
    or {}
frameTimes._count = 0
frameTimes._index = 0
local lastFrameDt = 1 / 60

local function updateFrameStats(dt)
    lastFrameDt = dt
    frameTimes._index =
        (frameTimes._index % 60) + 1
    frameTimes[frameTimes._index] =
        dt
    frameTimes._count =
        math.min(
            frameTimes._count + 1,
            60
        )
end

local function framePeak()
    local peak = lastFrameDt

    for index = 1, frameTimes._count do
        if frameTimes[index] > peak then
            peak = frameTimes[index]
        end
    end

    return peak
end

local function predictionWindow()
    local pwin = tonumber(CombatConfig.Block.PerfectBlockWindow) or 0.125
    local pmin = 0.05
    local edge = 0.006






    local rawPeak = framePeak()
    local peak = math.min(rawPeak, 0.050)
    local frame = math.min(math.max(lastFrameDt, 1 / 240), 0.050)
    local q = math.max(frame, peak * 0.75)
    local target = math.clamp(
        pwin / 2 + q / 2,
        math.max(pmin, 0.055),
        math.min(pwin - edge, 0.095)
    )

    local lowFps =
        rawPeak >= 1 / 45

    local schedulerPeak =
        lowFps
        and math.min(rawPeak, 0.075)
        or peak

    local lowFpsMultiplier =
        rawPeak >= 1 / 18
        and 1.45
        or 1.25

    local schedulerMargin =
        lowFps
        and 0.006
        or 0

    local want =
        math.max(
            frame * 0.5,
            schedulerPeak
                * (
                    lowFps
                    and lowFpsMultiplier
                    or 0.50
                )
                + schedulerMargin
        )

    local lookahead =
        lowFps
        and math.min(want, 0.090)
        or math.min(want, 0.045)

    return target, lookahead, pwin
end

local function flat(vector)
    return Vector3.new(vector.X, 0, vector.Z)
end

local function angleBetweenFlat(a, b)
    a = flat(a)
    b = flat(b)

    if a.Magnitude <= 0.0001 or b.Magnitude <= 0.0001 then
        return 0
    end

    local dot = math.clamp(a.Unit:Dot(b.Unit), -1, 1)
    return math.deg(math.acos(dot))
end

local function getWorkspaceCharacterByName(name)
    if typeof(name) ~= "string" or name == "" then
        return nil
    end

    local playersFolder = Workspace:FindFirstChild("Players")
    local npcsFolder = Workspace:FindFirstChild("NPCs")

    return (playersFolder and playersFolder:FindFirstChild(name))
        or (npcsFolder and npcsFolder:FindFirstChild(name))
end

local function nearestOwner(hitbox)
    local bestCharacter
    local bestDistance = math.huge

    for _, folderName in ipairs({"Players", "NPCs"}) do
        local folder = Workspace:FindFirstChild(folderName)

        if folder then
            for _, character in ipairs(folder:GetChildren()) do
                local root = getRoot(character)

                if root then
                    local distance = (root.Position - hitbox.Position).Magnitude

                    if distance < bestDistance then
                        bestDistance = distance
                        bestCharacter = character
                    end
                end
            end
        end
    end

    if bestDistance <= 10 then
        return bestCharacter, bestDistance
    end

    return nil, bestDistance
end

local function resolveOwner(threat)



    local ownerValue = threat.hitbox and threat.hitbox:FindFirstChild("Owner")

    if ownerValue and ownerValue:IsA("StringValue") and ownerValue.Value ~= "" then
        threat.ownerName = ownerValue.Value
        threat.owner = getWorkspaceCharacterByName(ownerValue.Value)
        threat.ownerSource = "explicit"
        return threat.owner
    end

    if threat.owner and threat.owner.Parent then
        return threat.owner
    end

    local character, distance = nearestOwner(threat.hitbox)
    threat.owner = character
    threat.ownerResolveDistance = distance

    if character then
        threat.ownerName = character.Name
        threat.ownerSource = "nearest"
    end

    return threat.owner
end

local function refreshAttackName(threat)
    local value = threat.hitbox:FindFirstChild("AttackName")

    if value and value:IsA("StringValue") and value.Value ~= "" then
        threat.attackName = value.Value
    end
end

local function normalizeCombatStyleKey(style)
    if typeof(style) ~= "string" then
        return "default"
    end

    local value = string.lower(style)
        :gsub("^%s+", "")
        :gsub("%s+$", "")

    if value == "" then
        return "default"
    end

    local compact = value:gsub("[%s_%-]", "")

    if compact == "kickboxing" then
        return "kickboxing"
    elseif compact == "kyokushin"
        or compact == "kyokushinkarate"
    then
        return "kyokushin"
    elseif compact == "cqc"
        or compact == "closequarterscombat"
    then
        return "cqc"
    elseif compact == "wingchun" then
        return "wingchun"
    elseif compact == "muaythai" then
        return "muaythai"
    end

    return value
end

