local AggressiveAutoParryStyles = {
    hakari = true,
    muaythai = true,
    karate = true,
    kickboxing = true,
    kyokushin = true,
    cqc = true,
    ali = true,
}

local function isAggressiveAutoParryStyle(style)
    return AggressiveAutoParryStyles[
        normalizeCombatStyleKey(style)
    ] == true
end

local function getVerifiedStyleDelay(style, attackType, combo)
    local profile = VerifiedStyleProfiles[normalizeCombatStyleKey(style)]
    if not profile then
        return nil
    end

    if attackType == "M1" then
        local index = math.clamp(math.floor(tonumber(combo) or 1), 1, 4)
        return math.max(0, profile.m1Base + (profile.m1Offsets[index] or 0))
    elseif attackType == "M2" then
        return profile.m2Delay
    end

    return nil
end

Menu._CharacterCombatStyleCache =
    Menu._CharacterCombatStyleCache or setmetatable({}, {__mode = "k"})

local function getStyle(character)
    if not character then
        return "default"
    end

    local containers = {
        character:FindFirstChild("PlayerData"),
        character,
    }
    for _, container in ipairs(containers) do
        if container then
            for _, attribute in ipairs({
                "CombatStyle",
                "CombatType",
                "FightingStyle",
                "Style",
            }) do
                local value = container:GetAttribute(attribute)
                if typeof(value) == "string" and value ~= "" then
                    local resolved = normalizeCombatStyleKey(value)
                    Menu._CharacterCombatStyleCache[character] = resolved
                    return resolved
                end
            end
        end
    end

    local ok, style = pcall(
        CombatAnimationUtils.GetCombatStyleForCharacter,
        character
    )

    if not ok or typeof(style) ~= "string" or style == "" then
        return Menu._CharacterCombatStyleCache[character] or "default"
    end

    style = normalizeCombatStyleKey(style)
    Menu._CharacterCombatStyleCache[character] = style
    return style
end


do
    -- Compact Shift Lock replacement runtime.
    --
    -- Exact game implementation confirmed from SmoothShiftLock:
    --   PlayerGui.ShiftLockIcon.Icon
    --   rbxassetid://101606061017053
    --
    -- Do not touch MouseIconEnabled, PlayerMouse.Icon,
    -- OverrideMouseIconBehavior, InteractionCursor, CameraUtils, or getgc.
    -- The game already owns normal cursor visibility correctly. We only remove
    -- its dedicated ShiftLockIcon GUI only for custom modes and draw the
    -- selected replacement/panel. Regular preserves the game's own icon.

    local ShiftlockUserInputService = game:GetService("UserInputService")
    local ShiftlockPlayers = game:GetService("Players")
    local ShiftlockWorkspace = game:GetService("Workspace")
    local ShiftlockCoreGui = game:GetService("CoreGui")
    local ShiftlockReplicatedStorage = game:GetService("ReplicatedStorage")
    local ShiftlockLocalPlayer = ShiftlockPlayers.LocalPlayer

    local SHIFTLOCK_HEART_DATA = base64_decode("")
    local SHIFTLOCK_HEART_OVERLAY_DATA = base64_decode("")

    local FONT_PRESETS = {
        ["smallest pixel 7"] = {
            face = Font.fromEnum(Enum.Font.Code),
            size = 10,
            y = 0,
        },
        ["Segoe UI"] = {
            face = Font.fromEnum(Enum.Font.SourceSans),
            size = 12,
            y = -1,
        },
        ["Made Bold"] = {
            face = Font.fromEnum(Enum.Font.GothamBold),
            size = 11,
            y = -1,
        },
    }

    local Core = {
        iconEnabled = false,
        iconStyle = "Tsundere",
        panelEnabled = false,
        locked = false,
        font = "smallest pixel 7",
        connections = {},
        iconHeart = nil,
        iconHeartOverlay = nil,
        iconHeartVisible = false,
        iconPulseSerial = 0,
        iconLogo = nil,
        iconLogoFrames = nil,
        iconLogoVisible = false,
        iconLogoSerial = 0,
        panelGui = nil,
        silentText = nil,
        privateText = nil,
        heart = nil,
        heartOverlay = nil,
        panelVisible = false,
        pulseSerial = 0,
        destroyed = false,
    }

    local function disconnectAll()
        for _, connection in ipairs(Core.connections) do
            pcall(function()
                connection:Disconnect()
            end)
        end
        Core.connections = {}
    end

    local function connect(signal, callback)
        local ok, connection = pcall(function()
            return signal:Connect(callback)
        end)
        if ok and connection then
            Core.connections[#Core.connections + 1] = connection
        end
        return connection
    end

    local function getPlayerGui()
        return ShiftlockLocalPlayer
            and ShiftlockLocalPlayer:FindFirstChildOfClass("PlayerGui")
    end

    local function getUiParent()
        if type(gethui) == "function" then
            local ok, result = pcall(gethui)
            if ok and typeof(result) == "Instance" then
                return result
            end
        end
        return ShiftlockCoreGui
    end

    local function normalizeFont(value)
        if type(value) == "table" then
            for _, name in ipairs({
                "smallest pixel 7",
                "Segoe UI",
                "Made Bold",
                "smallest_pixel-7",
            }) do
                if value[name] == true then
                    value = name
                    break
                end
            end
            if type(value) == "table" then
                value = value[1] or value.value or value.Value
            end
        end

        value = tostring(value or "")
        if value == "smallest_pixel-7" then
            value = "smallest pixel 7"
        elseif value == "Verdana" then
            value = "Segoe UI"
        end

        if FONT_PRESETS[value] then
            return value
        end
        return "smallest pixel 7"
    end

    local function normalizeIconStyle(value)
        if type(value) == "table" then
            for _, name in ipairs({
                "Regular",
                "Heart",
                "Tsundere",
                "tsundere",
                "Logo",
                "Dot",
            }) do
                if value[name] == true then
                    value = name
                    break
                end
            end
            if type(value) == "table" then
                value = value[1] or value.value or value.Value
            end
        end

        value = tostring(value or "Tsundere")
        if value == "Regular" then
            return "Regular"
        end
        if value == "Heart" then
            return "Heart"
        end
        if value == "tsundere"
            or value == "Logo"
            or value == "Dot"
        then
            return "Tsundere"
        end
        return "Tsundere"
    end

    local function accentColor()
        local colors = Menu.colors
        if type(colors) == "table" and typeof(colors.accent) == "Color3" then
            return colors.accent
        end
        return Color3.fromRGB(224, 211, 180)
    end

    local function drawingNew(className, properties)
        local library = rawget(getgenv(), "Drawing")
        if library == nil then
            pcall(function()
                library = Drawing
            end)
        end
        if not library or type(library.new) ~= "function" then
            return nil
        end

        local ok, object = pcall(library.new, className)
        if not ok or not object then
            return nil
        end

        for property, value in pairs(properties or {}) do
            pcall(function()
                object[property] = value
            end)
        end
        return object
    end

    local function destroyDrawing(object)
        if object then
            pcall(function()
                object:Destroy()
            end)
        end
    end

    local SmoothShiftLock = nil

    local function getSmoothShiftLock()
        if type(SmoothShiftLock) == "table" then
            return SmoothShiftLock
        end

        local packages = ShiftlockReplicatedStorage:FindFirstChild("Packages")
        local module = packages and packages:FindFirstChild("SmoothShiftLock")
        if not module or not module:IsA("ModuleScript") then
            return nil
        end

        local ok, result = pcall(require, module)
        if ok and type(result) == "table" then
            SmoothShiftLock = result
            return result
        end
        return nil
    end

    local function setGameShiftLockIconVisible(visible)
        local playerGui = getPlayerGui()
        if not playerGui then
            return false
        end

        local gui = playerGui:FindFirstChild("ShiftLockIcon")
        if not gui then
            return false
        end

        -- Never destroy/reparent the game's native icon. SmoothShiftLock can
        -- touch the same ScreenGui on the same frame, and racing :Destroy()
        -- against that code produces the "parent ... to NULL" warning.
        pcall(function()
            gui.Enabled = visible == true
        end)
        return true
    end

    local function hideGameShiftLockIcon()
        setGameShiftLockIconVisible(false)
    end

    local function ensureGameShiftLockIcon()
        if Core.locked ~= true then
            return
        end

        -- Prefer restoring the existing native GUI in-place. This avoids
        -- forcing SmoothShiftLock to recreate an object we intentionally hid.
        if setGameShiftLockIconVisible(true) then
            return
        end

        local playerGui = getPlayerGui()
        if not playerGui then
            return
        end

        -- Only recreate if the game itself already removed the native GUI.
        local smooth = getSmoothShiftLock()
        if smooth and type(smooth.ToggleShiftLock) == "function" then
            pcall(function()
                smooth:ToggleShiftLock(true)
            end)
        end

        task.defer(function()
            setGameShiftLockIconVisible(true)
        end)
    end

    local function updateLockState()
        local behavior = ShiftlockUserInputService.MouseBehavior
        if behavior == Enum.MouseBehavior.LockCenter then
            Core.locked = true
        elseif behavior == Enum.MouseBehavior.Default then
            Core.locked = false
        end
        -- LockCurrentPosition is the RMB handoff seen in the live trace.
        -- Preserve the current latch so RMB never hides the replacement.
    end

    local function createIconHeart()
        if Core.iconHeart and Core.iconHeartOverlay then
            return true
        end

        destroyDrawing(Core.iconHeart)
        destroyDrawing(Core.iconHeartOverlay)

        Core.iconHeart = drawingNew("Image", {
            Data = SHIFTLOCK_HEART_DATA,
            Color = accentColor(),
            Transparency = 1,
            Visible = false,
            ZIndex = 10000,
            Position = Vector2.new(0, 0),
            Size = Vector2.new(9, 9),
        })

        Core.iconHeartOverlay = drawingNew("Image", {
            Data = SHIFTLOCK_HEART_OVERLAY_DATA,
            Color = accentColor(),
            Transparency = 0,
            Visible = false,
            ZIndex = 9999,
            Position = Vector2.new(0, 0),
            Size = Vector2.new(9, 9),
        })

        return Core.iconHeart ~= nil and Core.iconHeartOverlay ~= nil
    end

    local function updateIconHeart()
        if not createIconHeart() then
            return
        end

        local camera = ShiftlockWorkspace.CurrentCamera
        if not camera then
            return
        end

        local base = camera.ViewportSize * 0.5 - Vector2.new(4.5, 4.5)
        Core.iconHeart.Position = base
        Core.iconHeartOverlay.Position = base
        Core.iconHeart.Color = accentColor()
        Core.iconHeartOverlay.Color = accentColor()
    end

    local function setIconHeartVisible(visible)
        visible = visible == true
        Core.iconHeartVisible = visible

        if visible and createIconHeart() then
            updateIconHeart()
            pcall(function()
                Core.iconHeart.Visible = true
                Core.iconHeartOverlay.Visible = true
            end)
        else
            Core.iconPulseSerial += 1
            if Core.iconHeart then
                pcall(function()
                    Core.iconHeart.Visible = false
                end)
            end
            if Core.iconHeartOverlay then
                pcall(function()
                    Core.iconHeartOverlay.Visible = false
                    Core.iconHeartOverlay.Transparency = 0
                    Core.iconHeartOverlay.Size = Vector2.new(9, 9)
                end)
            end
        end
    end

    local function pulseIconHeart()
        if Core.iconHeartVisible ~= true
            or not Core.iconHeart
            or not Core.iconHeartOverlay
        then
            return
        end

        Core.iconPulseSerial += 1
        local serial = Core.iconPulseSerial
        local heart = Core.iconHeart
        local overlay = Core.iconHeartOverlay
        local base = heart.Position

        heart.Color = accentColor()
        overlay.Color = accentColor()
        overlay.Position = base
        overlay.Size = Vector2.new(9, 9)
        overlay.Transparency = 0.35
        overlay.Visible = true

        task.spawn(function()
            local started = os.clock()
            local duration = 0.45
            while Core.iconHeartVisible == true
                and serial == Core.iconPulseSerial
                and os.clock() - started < duration
            do
                local alpha = math.clamp((os.clock() - started) / duration, 0, 1)
                local size = 9 + 15 * alpha
                pcall(function()
                    overlay.Size = Vector2.new(size, size)
                    overlay.Position = base - Vector2.new(
                        (size - 9) * 0.5,
                        (size - 9) * 0.5
                    )
                    overlay.Transparency = 0.35 * (1 - alpha)
                end)
                task.wait(1 / 30)
            end

            if serial == Core.iconPulseSerial and overlay then
                pcall(function()
                    overlay.Transparency = 0
                    overlay.Size = Vector2.new(9, 9)
                    overlay.Position = heart.Position
                end)
            end
        end)
    end

    local function startIconHeartPulseLoop()
        Core.iconPulseSerial += 1
        local serial = Core.iconPulseSerial

        task.spawn(function()
            while Core.iconHeartVisible == true
                and serial == Core.iconPulseSerial
                and Core.destroyed ~= true
            do
                task.wait(0.8)
                if Core.iconHeartVisible == true
                    and serial == Core.iconPulseSerial
                then
                    pulseIconHeart()
                    serial = Core.iconPulseSerial
                end
            end
        end)
    end

    local function getTsundereFrames()
        if type(Core.iconLogoFrames) == "table"
            and #Core.iconLogoFrames > 0
        then
            return Core.iconLogoFrames
        end

        local encodedFrames = Menu._silent_main_logo_frames
        if type(encodedFrames) ~= "table" or #encodedFrames == 0 then
            return nil
        end

        local decodedFrames = {}
        for _, frame in ipairs(encodedFrames) do
            if type(frame) == "string" and frame ~= "" then
                local ok, decoded = pcall(base64_decode, frame)
                if ok and type(decoded) == "string" and decoded ~= "" then
                    decodedFrames[#decodedFrames + 1] = decoded
                end
            end
        end

        if #decodedFrames == 0 then
            return nil
        end

        Core.iconLogoFrames = decodedFrames
        return decodedFrames
    end

    local function createIconLogo()
        if Core.iconLogo then
            return true
        end

        local frames = getTsundereFrames()
        if type(frames) ~= "table" or type(frames[1]) ~= "string" then
            return false
        end

        Core.iconLogo = drawingNew("Image", {
            Data = frames[1],
            Color = accentColor(),
            Transparency = 1,
            Visible = false,
            ZIndex = 10000,
            Position = Vector2.new(0, 0),
            Size = Vector2.new(17, 18),
        })

        return Core.iconLogo ~= nil
    end

    local function updateIconLogo()
        if not createIconLogo() then
            return
        end

        local camera = ShiftlockWorkspace.CurrentCamera
        if not camera then
            return
        end

        local size = Core.iconLogo.Size
        Core.iconLogo.Position = camera.ViewportSize * 0.5 - size * 0.5
        Core.iconLogo.Color = accentColor()
    end

    local function setIconLogoVisible(visible)
        visible = visible == true
        Core.iconLogoVisible = visible

        if visible and createIconLogo() then
            updateIconLogo()
            pcall(function()
                Core.iconLogo.Visible = true
            end)
        else
            Core.iconLogoSerial += 1
            if Core.iconLogo then
                pcall(function()
                    Core.iconLogo.Visible = false
                end)
            end
        end
    end

    local function startIconLogoAnimation()
        Core.iconLogoSerial += 1
        local serial = Core.iconLogoSerial

        task.spawn(function()
            local frameIndex = 1
            local frames = getTsundereFrames()
            local durations = Menu._silent_main_logo_durations

            while Core.iconLogoVisible == true
                and serial == Core.iconLogoSerial
                and Core.destroyed ~= true
            do
                if not Core.iconLogo or type(frames) ~= "table" or #frames == 0 then
                    break
                end

                frameIndex = ((frameIndex - 1) % #frames) + 1
                local frame = frames[frameIndex]
                if type(frame) == "string" and frame ~= "" then
                    pcall(function()
                        Core.iconLogo.Data = frame
                        Core.iconLogo.Color = accentColor()
                    end)
                end

                local delayTime = 0.1
                if type(durations) == "table" then
                    delayTime = tonumber(durations[frameIndex]) or delayTime
                end
                task.wait(math.max(0.03, delayTime))
                frameIndex += 1
            end
        end)
    end

    local function createPanel()
        if Core.panelGui
            and Core.panelGui.Parent
            and Core.silentText
            and Core.privateText
            and Core.heart
            and Core.heartOverlay
        then
            return true
        end

        if Core.panelGui then
            pcall(function()
                Core.panelGui:Destroy()
            end)
        end
        destroyDrawing(Core.heart)
        destroyDrawing(Core.heartOverlay)

        local gui = Instance.new("ScreenGui")
        gui.Name = "SilentShiftlockPanel"
        gui.ResetOnSpawn = false
        gui.IgnoreGuiInset = true
        gui.DisplayOrder = 2147483000
        gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
        gui.Parent = getUiParent()

        local function makeText(name, value)
            local label = Instance.new("TextLabel")
            label.Name = name
            label.BackgroundTransparency = 1
            label.BorderSizePixel = 0
            label.Text = value
            label.TextColor3 = Color3.fromRGB(230, 230, 230)
            label.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
            label.TextStrokeTransparency = 0
            label.TextXAlignment = Enum.TextXAlignment.Left
            label.TextYAlignment = Enum.TextYAlignment.Center
            label.TextWrapped = false
            label.RichText = false
            label.Visible = false
            label.ZIndex = 2
            label.Size = UDim2.fromOffset(100, 18)
            label.Parent = gui
            return label
        end

        Core.panelGui = gui
        Core.silentText = makeText("Silent", "Silent")
        Core.privateText = makeText("Private", "private")


        Core.heart = drawingNew("Image", {
            Data = SHIFTLOCK_HEART_DATA,
            Color = accentColor(),
            Transparency = 1,
            Visible = false,
            ZIndex = 2,
            Position = Vector2.new(0, 0),
            Size = Vector2.new(9, 9),
        })

        Core.heartOverlay = drawingNew("Image", {
            Data = SHIFTLOCK_HEART_OVERLAY_DATA,
            Color = accentColor(),
            Transparency = 0,
            Visible = false,
            ZIndex = 1,
            Position = Vector2.new(0, 0),
            Size = Vector2.new(9, 9),
        })

        return Core.heart ~= nil
            and Core.heartOverlay ~= nil
    end

    local function applyPanelFont()
        if not Core.silentText or not Core.privateText then
            return FONT_PRESETS["smallest pixel 7"]
        end

        Core.font = normalizeFont(Core.font)
        local preset = FONT_PRESETS[Core.font]
            or FONT_PRESETS["smallest pixel 7"]

        for _, label in ipairs({Core.silentText, Core.privateText}) do
            pcall(function()
                label.FontFace = preset.face
                label.TextSize = preset.size
            end)
        end

        return preset
    end

    local function getActiveIconFootprint(camera)
        if Core.iconStyle == "Regular" then
            local playerGui = getPlayerGui()
            local gui = playerGui and playerGui:FindFirstChild("ShiftLockIcon")
            local icon = gui and gui:FindFirstChild("Icon")
            if icon and icon:IsA("GuiObject") then
                local absolute = icon.AbsoluteSize
                if absolute.X > 0 and absolute.Y > 0 then
                    return absolute
                end

                local size = icon.Size
                return Vector2.new(
                    math.max(1, size.X.Offset + camera.ViewportSize.X * size.X.Scale),
                    math.max(1, size.Y.Offset + camera.ViewportSize.Y * size.Y.Scale)
                )
            end

            -- Exact SmoothShiftLock desktop fallback. Mobile/native variants
            -- are picked up automatically from AbsoluteSize when they exist.
            return Vector2.new(64, 64)
        end

        if Core.iconStyle == "Heart" then
            -- The base heart is 9x9, but its pulse overlay expands to 24x24.
            -- Reserve the full pulse footprint so the panel never clips it.
            return Vector2.new(24, 24)
        end

        if Core.iconStyle == "Tsundere" then
            if Core.iconLogo then
                local ok, size = pcall(function()
                    return Core.iconLogo.Size
                end)
                if ok and typeof(size) == "Vector2" then
                    return size
                end
            end
            return Vector2.new(17, 18)
        end

        return Vector2.new(0, 0)
    end

    local function updatePanelPosition()
        if not createPanel() then
            return
        end

        local camera = ShiftlockWorkspace.CurrentCamera
        if not camera then
            return
        end

        local preset = applyPanelFont()
        local silentBounds = Core.silentText.TextBounds
        local privateBounds = Core.privateText.TextBounds

        if silentBounds.X <= 0 then
            silentBounds = Vector2.new(preset.size * 3.05, preset.size + 2)
        end
        if privateBounds.X <= 0 then
            privateBounds = Vector2.new(preset.size * 3.25, preset.size + 2)
        end

        local center = camera.ViewportSize * 0.5
        local iconSize = getActiveIconFootprint(camera)

        -- Keep the panel directly beside the active Shift Lock icon. The
        -- icon footprint is resolved live for Regular, Heart, or Tsundere,
        -- so the panel always begins just beyond the icon's right edge.
        local gap = 2
        local panelLeft
        local panelCenterY

        if Core.iconStyle == "Regular" then
            -- SmoothShiftLock's native 64x64 image contains substantial
            -- transparent padding around the visible ring. Use the visible
            -- portion of that footprint so the panel sits beside the ring,
            -- not beside the transparent image bounds.
            local visibleWidth = math.max(18, iconSize.X * 0.375)
            panelLeft = center.X + visibleWidth * 0.5 + gap
            panelCenterY = center.Y + 9 + (preset.y or 0)
        elseif Core.iconStyle == "Tsundere" then
            -- Keep Tsundere tightly beside the panel with a 1px gap.
            panelLeft = center.X + iconSize.X * 0.5 + 1
            panelCenterY = center.Y + 11 + (preset.y or 0)
        elseif Core.iconStyle == "Heart" then
            -- Pull Heart's panel 4px closer than its previous position and
            -- lower it by 1px without affecting Regular or Tsundere.
            panelLeft = center.X + iconSize.X * 0.5 + gap - 4
            panelCenterY = center.Y + 7 + (preset.y or 0)
        else
            panelLeft = center.X + iconSize.X * 0.5 + gap
            panelCenterY = center.Y + 6 + (preset.y or 0)
        end

        local textPosition = Vector2.new(
            panelLeft,
            panelCenterY - 9
        )
        local heartPosition = Vector2.new(
            panelLeft + silentBounds.X + 3,
            panelCenterY - 4.5
        )
        local privatePosition = Vector2.new(
            heartPosition.X + 12,
            panelCenterY - 9
        )

        Core.silentText.Position = UDim2.fromOffset(
            math.floor(textPosition.X + 0.5),
            math.floor(textPosition.Y + 0.5)
        )
        Core.silentText.Size = UDim2.fromOffset(
            math.max(1, math.ceil(silentBounds.X + 4)),
            18
        )

        Core.privateText.Position = UDim2.fromOffset(
            math.floor(privatePosition.X + 0.5),
            math.floor(privatePosition.Y + 0.5)
        )
        Core.privateText.Size = UDim2.fromOffset(
            math.max(1, math.ceil(privateBounds.X + 4)),
            18
        )

        Core.heart.Position = heartPosition
        Core.heartOverlay.Position = heartPosition
        Core.heart.Color = accentColor()
        Core.heartOverlay.Color = accentColor()
    end

    local function setPanelObjectsVisible(visible)
        visible = visible == true
        Core.panelVisible = visible

        if Core.silentText then
            Core.silentText.Visible = visible
        end
        if Core.privateText then
            Core.privateText.Visible = visible
        end
        for _, object in ipairs({Core.heart}) do
            if object then
                pcall(function()
                    object.Visible = visible
                end)
            end
        end
        if Core.heartOverlay then
            pcall(function()
                Core.heartOverlay.Visible = visible
                if not visible then
                    Core.heartOverlay.Transparency = 0
                end
            end)
        end
    end

    local function pulseHeart()
        if Core.panelVisible ~= true or not Core.heart or not Core.heartOverlay then
            return
        end

        Core.pulseSerial += 1
        local serial = Core.pulseSerial
        local heart = Core.heart
        local overlay = Core.heartOverlay
        local base = heart.Position

        heart.Color = accentColor()
        overlay.Color = accentColor()
        overlay.Position = base
        overlay.Size = Vector2.new(9, 9)
        overlay.Transparency = 0.35
        overlay.Visible = true

        task.spawn(function()
            local started = os.clock()
            local duration = 0.45
            while Core.panelVisible == true
                and serial == Core.pulseSerial
                and os.clock() - started < duration
            do
                local alpha = math.clamp((os.clock() - started) / duration, 0, 1)
                local size = 9 + 15 * alpha
                pcall(function()
                    overlay.Size = Vector2.new(size, size)
                    overlay.Position = base - Vector2.new((size - 9) * 0.5, (size - 9) * 0.5)
                    overlay.Transparency = 0.35 * (1 - alpha)
                end)
                task.wait(1 / 30)
            end

            if serial == Core.pulseSerial and overlay then
                pcall(function()
                    overlay.Transparency = 0
                    overlay.Size = Vector2.new(9, 9)
                    overlay.Position = heart.Position
                end)
            end
        end)
    end

    local function startPulseLoop()
        Core.pulseSerial += 1
        local serial = Core.pulseSerial

        task.spawn(function()
            while Core.panelVisible == true
                and serial == Core.pulseSerial
                and Core.destroyed ~= true
            do
                task.wait(0.8)
                if Core.panelVisible == true
                    and serial == Core.pulseSerial
                then
                    pulseHeart()
                    serial = Core.pulseSerial
                end
            end
        end)
    end

    local function refresh()
        updateLockState()

        local useNative = Core.iconEnabled ~= true
            or Core.iconStyle == "Regular"

        if useNative then
            if Core.iconEnabled
                and Core.iconStyle == "Regular"
                and Core.locked ~= true
            then
                -- SilentUI temporarily releases LockCenter while its menu is
                -- open. Hide the native ring too so every Shift Lock icon
                -- mode follows the same visibility behavior.
                hideGameShiftLockIcon()
            else
                ensureGameShiftLockIcon()
            end
        else
            hideGameShiftLockIcon()
        end

        local showReplacement = Core.iconEnabled
            and Core.locked
            and Core.iconStyle ~= "Regular"
        local showHeart = showReplacement and Core.iconStyle == "Heart"
        local showTsundere = showReplacement and Core.iconStyle == "Tsundere"

        local wasIconHeartVisible = Core.iconHeartVisible
        setIconHeartVisible(showHeart)
        if showHeart and not wasIconHeartVisible then
            startIconHeartPulseLoop()
        end

        local wasIconLogoVisible = Core.iconLogoVisible
        setIconLogoVisible(showTsundere)
        if showTsundere and not wasIconLogoVisible then
            startIconLogoAnimation()
        end

        local showPanel = Core.iconEnabled
            and Core.panelEnabled
            and Core.locked

        if showPanel then
            local wasVisible = Core.panelVisible
            if createPanel() then
                updatePanelPosition()
                setPanelObjectsVisible(true)
                if not wasVisible then
                    startPulseLoop()
                end
                task.defer(function()
                    if Core.panelVisible then
                        pcall(updatePanelPosition)
                    end
                end)
            end
        elseif Core.panelVisible then
            Core.pulseSerial += 1
            setPanelObjectsVisible(false)
        end
    end

    local function installSignals()
        disconnectAll()

        connect(
            ShiftlockUserInputService:GetPropertyChangedSignal("MouseBehavior"),
            refresh
        )

        local playerGui = getPlayerGui()
        if playerGui then
            connect(playerGui.ChildAdded, function(child)
                if child.Name == "ShiftLockIcon" and Core.iconEnabled then
                    -- ChildAdded is the exact creation point used by
                    -- SmoothShiftLock:SetLockIcon(true). Regular leaves the
                    -- game's own GUI alone; custom modes hide only that GUI.
                    Core.locked = true
                    if Core.iconStyle ~= "Regular" then
                        pcall(function()
                            child.Enabled = false
                        end)
                    end
                    task.defer(refresh)
                end
            end)
        end

        local camera = ShiftlockWorkspace.CurrentCamera
        if camera then
            connect(camera:GetPropertyChangedSignal("ViewportSize"), function()
                if Core.iconHeartVisible then
                    updateIconHeart()
                end
                if Core.iconLogoVisible then
                    updateIconLogo()
                end
                if Core.panelVisible then
                    updatePanelPosition()
                end
            end)
        end

        connect(ShiftlockWorkspace:GetPropertyChangedSignal("CurrentCamera"), function()
            -- Rebuild lightweight signals only when Roblox replaces the camera.
            installSignals()
            refresh()
        end)
    end

    local ShiftlockIconRuntime = {}
    local ShiftlockHUDRuntime = {}

    Menu._ShiftlockIconRuntime = ShiftlockIconRuntime
    Menu._ShiftlockHUDRuntime = ShiftlockHUDRuntime

    function ShiftlockIconRuntime.setEnabled(enabled)
        Core.iconEnabled = enabled == true

        if not Core.iconEnabled then
            setIconHeartVisible(false)
            setIconLogoVisible(false)
            if Core.panelVisible then
                Core.pulseSerial += 1
                setPanelObjectsVisible(false)
            end
        end

        refresh()
    end

    function ShiftlockIconRuntime.setStyle(value)
        Core.iconStyle = normalizeIconStyle(value)
        refresh()
        if Core.panelVisible then
            updatePanelPosition()
            task.defer(updatePanelPosition)
        end
    end

    function ShiftlockHUDRuntime.setEnabled(enabled)
        Core.panelEnabled = enabled == true
        refresh()
    end

    function ShiftlockHUDRuntime.setFont(value)
        Core.font = normalizeFont(value)
        applyPanelFont()
        if Core.panelVisible then
            updatePanelPosition()
            task.defer(updatePanelPosition)
        end
    end

    function ShiftlockIconRuntime.Unload()
        Core.iconEnabled = false
        Core.panelEnabled = false
        Core.pulseSerial += 1
        setIconHeartVisible(false)
        setIconLogoVisible(false)
        setPanelObjectsVisible(false)
        updateLockState()
        ensureGameShiftLockIcon()
    end

    function ShiftlockHUDRuntime.Unload()
        Core.panelEnabled = false
        Core.pulseSerial += 1
        setPanelObjectsVisible(false)
    end

    local function unloadAll()
        if Core.destroyed then
            return
        end
        Core.iconEnabled = false
        updateLockState()
        ensureGameShiftLockIcon()
        Core.destroyed = true
        disconnectAll()
        Core.pulseSerial += 1
        destroyDrawing(Core.iconHeart)
        destroyDrawing(Core.iconHeartOverlay)
        destroyDrawing(Core.iconLogo)
        destroyDrawing(Core.heart)
        destroyDrawing(Core.heartOverlay)
        Core.iconHeart = nil
        Core.iconHeartOverlay = nil
        Core.iconLogo = nil
        Core.iconLogoFrames = nil
        Core.heart = nil
        Core.heartOverlay = nil
        if Core.panelGui then
            pcall(function()
                Core.panelGui:Destroy()
            end)
        end
        Core.panelGui = nil
        Core.silentText = nil
        Core.privateText = nil
    end

    if Menu._ScriptRuntime
        and type(Menu._ScriptRuntime.AddCleanup) == "function"
    then
        Menu._ScriptRuntime:AddCleanup(unloadAll)
    end

    Core.font = normalizeFont(Flags.visual_shiftlock_panel_font)
    Core.iconStyle = normalizeIconStyle(Flags.visual_shiftlock_icon_style)
    Core.iconEnabled = Flags.visual_shiftlock_icon == true
    Core.panelEnabled = Flags.visual_shiftlock_hud == true
    updateLockState()
    installSignals()
    refresh()
end



do
    local IndicatorTweenService = game:GetService("TweenService")
    local IndicatorRowTweenInfo = TweenInfo.new(
        0.18,
        Enum.EasingStyle.Quart,
        Enum.EasingDirection.Out
    )
    local IndicatorRuntime = {
        enabled = false,
        side = "Right",

        gui = nil,
        panel = nil,
        body = nil,
        healthFill = nil,
        healthSurface = nil,
        healthWipeOverlay = nil,
        healthAccent = nil,
        cooldownRow = nil,
        cooldownFill = nil,
        styleValue = nil,
        statusValue = nil,
        headerIcon = nil,
        headerIconFallback = nil,

        character = nil,
        connections = {},
        heartbeatConnection = nil,

        width = 118,
        baseHeight = 67,
        cooldownHeight = 83,
        stableScreenPosition = nil,
        positionUpdatedAt = 0,
        desiredStatusVisible = false,
        desiredCooldownVisible = false,
        rowTransitionSerial = 0,

        themeRefs = nil,
        healthTrack = nil,
        cooldownTrack = nil,

        cooldownStartedAt = 0,
        cooldownEndAt = 0,
        cooldownDuration = 0,
        cooldownSawState = false,
        cooldownLastRatio = 1,
        learnedCooldown = {},
        iconAsset = nil,
        cachedStyleKey = "default",
        cachedStyleName = "Default",
        cachedStyleColor = nil,
        styleRefreshAt = 0,
    }

    Menu._IndicatorRuntime = IndicatorRuntime

    local function disconnectCharacter()
        for _, connection in ipairs(IndicatorRuntime.connections) do
            pcall(function()
                connection:Disconnect()
            end)
        end
        IndicatorRuntime.connections = {}
    end

    local function getUiParent()
        local keybindGui = Menu._keybind_gui
        if typeof(keybindGui) == "Instance" and keybindGui.Parent then
            return keybindGui.Parent
        end

        if type(gethui) == "function" then
            local ok, result = pcall(gethui)
            if ok and typeof(result) == "Instance" then
                return result
            end
        end

        return game:GetService("CoreGui")
    end

    local function findKeybindTextTemplate()
        local keybindGui = Menu._keybind_gui
        if typeof(keybindGui) ~= "Instance" then
            return nil
        end

        for _, descendant in ipairs(keybindGui:GetDescendants()) do
            if descendant:IsA("TextLabel")
                and string.lower(tostring(descendant.Text)) == "hotkeys"
            then
                return descendant
            end
        end

        return keybindGui:FindFirstChildWhichIsA("TextLabel", true)
    end

    local function findKeybindRowTextTemplate()
        local keybindGui = Menu._keybind_gui
        if typeof(keybindGui) ~= "Instance" then
            return nil
        end

        local best
        local bestScore = -math.huge
        for _, descendant in ipairs(keybindGui:GetDescendants()) do
            if descendant:IsA("TextLabel")
                and string.lower(tostring(descendant.Text)) == "enable"
            then
                local score = 0
                if descendant.Visible ~= false then
                    score += 4
                end
                if descendant.AbsoluteSize.X > 0 and descendant.AbsoluteSize.Y > 0 then
                    score += 4
                end
                local transparency = tonumber(descendant.TextTransparency) or 0
                score += math.max(0, 1 - transparency) * 3

                local current = descendant.Parent
                local hiddenAncestor = false
                while current and current ~= keybindGui do
                    if current:IsA("GuiObject") and current.Visible == false then
                        hiddenAncestor = true
                        break
                    end
                    current = current.Parent
                end
                if hiddenAncestor then
                    score -= 8
                end

                if score > bestScore then
                    best = descendant
                    bestScore = score
                end
            end
        end

        return best or findKeybindTextTemplate()
    end

    local function findKeybindHeaderIconTemplate(titleTemplate)
        if not titleTemplate or not titleTemplate.Parent then
            return nil
        end

        local roots = {titleTemplate.Parent}
        if titleTemplate.Parent.Parent then
            roots[#roots + 1] = titleTemplate.Parent.Parent
        end

        local best
        local bestDistance = math.huge
        for _, root in ipairs(roots) do
            for _, descendant in ipairs(root:GetDescendants()) do
                if (descendant:IsA("ImageLabel") or descendant:IsA("ImageButton"))
                    and descendant.Visible ~= false
                    and descendant.AbsoluteSize.X > 0
                    and descendant.AbsoluteSize.Y > 0
                    and descendant.AbsoluteSize.X <= 18
                    and descendant.AbsoluteSize.Y <= 18
                then
                    local distance = math.abs(
                        (descendant.AbsolutePosition.X + descendant.AbsoluteSize.X)
                            - titleTemplate.AbsolutePosition.X
                    )
                    if distance < bestDistance then
                        best = descendant
                        bestDistance = distance
                    end
                end
            end
        end

        return best
    end

    local function applyKeybindFont(label, template)
        if not label or not label:IsA("TextLabel") then
            return
        end

        label.BackgroundTransparency = 1
        label.BorderSizePixel = 0
        label.TextSize = 12
        label.TextColor3 = Color3.fromRGB(197, 197, 197)
        label.TextStrokeTransparency = 1
        label.RichText = false

        if template then
            pcall(function()
                label.FontFace = template.FontFace
            end)
            pcall(function()
                label.Font = template.Font
            end)
            label.TextSize = template.TextSize
            label.TextColor3 = template.TextColor3
            label.TextTransparency = template.TextTransparency
            label.TextStrokeColor3 = template.TextStrokeColor3
            label.TextStrokeTransparency = template.TextStrokeTransparency
            label.LineHeight = template.LineHeight
        else
            label.Font = Enum.Font.SourceSans
        end
    end

    local function corner(object, radius)
        local ui = Instance.new("UICorner")
        ui.CornerRadius = UDim.new(0, radius)
        ui.Parent = object
        return ui
    end

    local function createText(parent, template, textValue, x, y, width, alignment)
        local label = Instance.new("TextLabel")
        label.Text = tostring(textValue or "")
        label.Position = UDim2.fromOffset(x, y)
        label.Size = UDim2.fromOffset(width, 14)
        label.TextXAlignment = alignment or Enum.TextXAlignment.Left
        label.TextYAlignment = Enum.TextYAlignment.Center
        label.ZIndex = 5
        label.Parent = parent
        applyKeybindFont(label, template)
        return label
    end

    local function currentStyleRaw(character)
        if not character then
            return "default"
        end

        for _, attribute in ipairs({"CombatStyle", "FightingStyle", "Style"}) do
            local value = character:GetAttribute(attribute)
            if typeof(value) == "string" and value ~= "" then
                return normalizeCombatStyleKey(value)
            end
        end

        local data = character:FindFirstChild("PlayerData")
        if data then
            for _, attribute in ipairs({"CombatStyle", "FightingStyle", "Style"}) do
                local value = data:GetAttribute(attribute)
                if typeof(value) == "string" and value ~= "" then
                    return normalizeCombatStyleKey(value)
                end
            end
        end

        local cached = IndicatorRuntime.cachedStyleKey
        if type(cached) == "string" and cached ~= "" then
            return cached
        end

        return "default"
    end

    local styleNames = {
        boxing = "Boxing",
        wingchun = "Wing Chun",
        ["wing chun"] = "Wing Chun",
        ali = "Ali",
        hakari = "Hakari",
        kure = "Kure",
        wrestling = "Wrestling",
        capoeira = "Capoeira",
        muaythai = "Muay Thai",
        ["muay thai"] = "Muay Thai",
        striker = "Striker",
        kickboxing = "Kickboxing",
        ["kick boxing"] = "Kickboxing",
        kick_boxing = "Kickboxing",
        kyokushin = "Kyokushin",
        kyokushinkarate = "Kyokushin",
        ["kyokushin karate"] = "Kyokushin",
        cqc = "CQC",
        closequarterscombat = "CQC",
        ["close quarters combat"] = "CQC",
        basic = "Basic",
        default = "Default",
    }

    local function styleName(character)
        local style = currentStyleRaw(character)
        if styleNames[style] then
            return styleNames[style]
        end

        style = string.gsub(style, "_", " ")
        return string.upper(string.sub(style, 1, 1)) .. string.sub(style, 2)
    end

    local function refreshIndicatorStyle(character, force)
        local now = os.clock()
        if force ~= true and now < (IndicatorRuntime.styleRefreshAt or 0) then
            return IndicatorRuntime.cachedStyleName or "Default"
        end
        IndicatorRuntime.styleRefreshAt = now + 0.75

        local styleKey

        if character then
            for _, attribute in ipairs({"CombatStyle", "FightingStyle", "Style"}) do
                local okAttribute, value = pcall(
                    character.GetAttribute,
                    character,
                    attribute
                )
                if okAttribute and typeof(value) == "string" and value ~= "" then
                    styleKey = normalizeCombatStyleKey(value)
                    break
                end
            end
        end

        if not styleKey then
            local okStyle, resolved = pcall(function()
                if type(CombatAnimationUtils.GetPlayerCombatStyle) == "function" then
                    return CombatAnimationUtils.GetPlayerCombatStyle(LocalPlayer)
                end
                return getStyle(character)
            end)

            if okStyle and typeof(resolved) == "string" and resolved ~= "" then
                styleKey = normalizeCombatStyleKey(resolved)
            end
        end

        if styleKey then
            IndicatorRuntime.cachedStyleKey = styleKey
            IndicatorRuntime.cachedStyleName = styleNames[styleKey]
                or (string.upper(string.sub(styleKey, 1, 1)) .. string.sub(styleKey, 2))

            if type(
                Menu._GetFightingStyleRarityColor
            ) == "function"
            then
                local okColor,
                    styleColor =
                    pcall(
                        Menu._GetFightingStyleRarityColor,
                        character,
                        styleKey
                    )

                if okColor
                    and typeof(styleColor)
                        == "Color3"
                then
                    IndicatorRuntime.cachedStyleColor =
                        styleColor
                end
            end
        end

        return IndicatorRuntime.cachedStyleName or "Default"
    end

    local function isAttacking(character)
        return character:GetAttribute("CombatAttacking") == true
            or character:GetAttribute("M1") == true
            or character:GetAttribute("M1Hold") == true
            or character:GetAttribute("PendingM1") == true
            or character:GetAttribute("M2") == true
            or character:GetAttribute("PendingM2") == true
    end

    local function statusName(character)
        if not character then
            return nil
        end

        if character:GetAttribute("Stunned") == true
            or character:GetAttribute("Parried") == true
            or character:GetAttribute("Ragdoll") == true
        then
            return "Stunned"
        end

        if isAttacking(character) then
            return "Attacking"
        end

        if character:GetAttribute("Equip") == true
            or character:GetAttribute("FightingStance") == true
            or character:GetAttribute("InCombat") == true
        then
            return "Combat"
        end

        return nil
    end

    local function validCooldownDuration(value)
        return typeof(value) == "number" and value >= 0.20 and value <= 30
    end

    local function normalizedRemaining(value, now)
        if typeof(value) ~= "number" or value <= 0 then
            return nil
        end

        if value <= 30 then
            return value
        end

        now = now or os.clock()
        local remaining = value - now
        if remaining > 0 and remaining <= 30 then
            return remaining
        end

        return nil
    end

    function IndicatorRuntime.resolveCooldownDuration(character)
        local style = currentStyleRaw(character)

        if type(CombatConfig.GetStyleM2Cooldown) == "function" then
            local ok, duration = pcall(CombatConfig.GetStyleM2Cooldown, style)
            if ok and validCooldownDuration(duration) then
                return duration
            end
        end

        local styleConfig
        pcall(function()
            styleConfig = CombatConfig.GetStyleConfig(style)
        end)
        if type(styleConfig) == "table" and validCooldownDuration(styleConfig.M2Cooldown) then
            return styleConfig.M2Cooldown
        end

        local learned = IndicatorRuntime.learnedCooldown[style]
        if validCooldownDuration(learned) then
            return learned
        end

        local defaultM2 = type(CombatConfig.M2) == "table" and CombatConfig.M2.Cooldown or nil
        if validCooldownDuration(defaultM2) then
            return defaultM2
        end

        return 3.0
    end

    function IndicatorRuntime.getCooldownState(character, now)
        now = now or os.clock()

        local remaining = normalizedRemaining(
            character:GetAttribute("M2CooldownRemaining"),
            now
        )
        if remaining then
            return true, remaining, "remaining"
        end

        local cooldown = character:GetAttribute("M2Cooldown")
        if cooldown == true then
            return true, nil, "boolean"
        end

        local numeric = normalizedRemaining(cooldown, now)
        if numeric then
            return true, numeric, "numeric"
        end

        return false, nil, "none"
    end

    local function indicatorRowScale(row)
        if not row then
            return nil
        end
        local scale = row:FindFirstChild("DynamicRowScale")
        if not scale then
            scale = Instance.new("UIScale")
            scale.Name = "DynamicRowScale"
            scale.Scale = 1
            scale.Parent = row
        end
        return scale
    end

    local function tweenIndicator(instance, goal)
        if not instance or not instance.Parent then
            return
        end
        pcall(function()
            IndicatorTweenService:Create(
                instance,
                IndicatorRowTweenInfo,
                goal
            ):Play()
        end)
    end

    function IndicatorRuntime.layoutRows(showStatus, showCooldown, animated)
        showStatus = showStatus == true
        showCooldown = showCooldown == true

        if not IndicatorRuntime.panel then
            return
        end

        local cooldownWasVisible = IndicatorRuntime.cooldownRow
            and IndicatorRuntime.cooldownRow.Visible == true
        local statusWasVisible = IndicatorRuntime.statusRow
            and IndicatorRuntime.statusRow.Visible == true

        if IndicatorRuntime.cooldownRow and showCooldown then
            IndicatorRuntime.cooldownRow.Visible = true
            if animated and not cooldownWasVisible then
                local scale = indicatorRowScale(IndicatorRuntime.cooldownRow)
                if scale then
                    scale.Scale = 0.86
                    tweenIndicator(scale, {Scale = 1})
                end
            end
            if animated then
                tweenIndicator(
                    IndicatorRuntime.cooldownRow,
                    {Position = UDim2.fromOffset(0, 36)}
                )
            else
                IndicatorRuntime.cooldownRow.Position = UDim2.fromOffset(0, 36)
            end
        end

        if IndicatorRuntime.styleRow then
            local position = UDim2.fromOffset(0, showCooldown and 52 or 36)
            if animated then
                tweenIndicator(IndicatorRuntime.styleRow, {Position = position})
            else
                IndicatorRuntime.styleRow.Position = position
            end
        end

        if IndicatorRuntime.statusRow and showStatus then
            IndicatorRuntime.statusRow.Visible = true
            if animated and not statusWasVisible then
                local scale = indicatorRowScale(IndicatorRuntime.statusRow)
                if scale then
                    scale.Scale = 0.86
                    tweenIndicator(scale, {Scale = 1})
                end
            end
            local position = UDim2.fromOffset(0, showCooldown and 68 or 52)
            if animated then
                tweenIndicator(IndicatorRuntime.statusRow, {Position = position})
            else
                IndicatorRuntime.statusRow.Position = position
            end
        end

        local height
        if showCooldown then
            height = showStatus and IndicatorRuntime.cooldownHeight or IndicatorRuntime.baseHeight
        else
            height = showStatus and IndicatorRuntime.baseHeight or 51
        end

        local panelSize = UDim2.fromOffset(IndicatorRuntime.width, height)
        if animated then
            tweenIndicator(IndicatorRuntime.panel, {Size = panelSize})
        else
            IndicatorRuntime.panel.Size = panelSize
        end

        IndicatorRuntime.rowTransitionSerial += 1
        local serial = IndicatorRuntime.rowTransitionSerial
        local function finishHide(row, shouldShow)
            if not row or shouldShow then
                return
            end
            local scale = indicatorRowScale(row)
            if animated and scale then
                tweenIndicator(scale, {Scale = 0.86})
            end
            task.delay(animated and 0.18 or 0, function()
                if IndicatorRuntime.rowTransitionSerial ~= serial then
                    return
                end
                if row and row.Parent then
                    row.Visible = false
                    local currentScale = indicatorRowScale(row)
                    if currentScale then
                        currentScale.Scale = 1
                    end
                end
            end)
        end
        finishHide(IndicatorRuntime.cooldownRow, showCooldown)
        finishHide(IndicatorRuntime.statusRow, showStatus)
    end

    function IndicatorRuntime.setCooldownVisible(visible)
        visible = visible == true
        if IndicatorRuntime.desiredCooldownVisible == visible then
            return
        end
        IndicatorRuntime.desiredCooldownVisible = visible
        IndicatorRuntime.layoutRows(
            IndicatorRuntime.desiredStatusVisible,
            visible,
            true
        )
    end

    function IndicatorRuntime.setStatusVisible(visible)
        visible = visible == true
        if IndicatorRuntime.desiredStatusVisible == visible then
            return
        end
        IndicatorRuntime.desiredStatusVisible = visible
        IndicatorRuntime.layoutRows(
            visible,
            IndicatorRuntime.desiredCooldownVisible,
            true
        )
    end

    function IndicatorRuntime.beginCooldown(character, exactRemaining)
        character = character or LocalPlayer.Character
        if not character or not character.Parent then
            return
        end

        local now = os.clock()
        local duration = IndicatorRuntime.resolveCooldownDuration(character)
        local remaining = normalizedRemaining(exactRemaining, now)

        IndicatorRuntime.cooldownStartedAt = now
        IndicatorRuntime.cooldownDuration = math.max(duration, remaining or 0.20)
        IndicatorRuntime.cooldownEndAt = now + (remaining or duration)
        IndicatorRuntime.cooldownSawState = true
        IndicatorRuntime.cooldownLastRatio = math.clamp(
            (remaining or duration) / math.max(IndicatorRuntime.cooldownDuration, 0.20),
            0,
            1
        )
        IndicatorRuntime.setCooldownVisible(true)
    end

    local function resolveKeybindIconAsset()
        if IndicatorRuntime.iconAsset then
            return IndicatorRuntime.iconAsset
        end

        local data = Menu._keybind_header_icon_data
        local assetFunction = getcustomasset or getsynasset
        if type(data) ~= "string"
            or data == ""
            or type(writefile) ~= "function"
            or type(delfile) ~= "function"
            or type(assetFunction) ~= "function"
        then
            return nil
        end

        local root = "SilentSolutions"
        if type(isfolder) == "function" and type(makefolder) == "function" and not isfolder(root) then
            pcall(makefolder, root)
        end

        local legacyPath = root .. "/indicator_keybind_header.png"
        if type(isfile) == "function" and isfile(legacyPath) then
            pcall(delfile, legacyPath)
        end

        local guidService = game:GetService("HttpService")
        local path = root
            .. "/.__indicator_keybind_header_"
            .. guidService:GenerateGUID(false)
            .. ".png"
        local okWrite = pcall(writefile, path, data)
        if not okWrite then
            return nil
        end

        local okAsset, asset = pcall(assetFunction, path)
        pcall(delfile, path)
        if okAsset and type(asset) == "string" and asset ~= "" then
            IndicatorRuntime.iconAsset = asset
            return asset
        end

        return nil
    end

