    function IndicatorRuntime.applyTheme()
        local refs = IndicatorRuntime.themeRefs
        if not refs then
            return
        end

        local colors = Menu.colors or {}
        local function themed(name, fallback)
            local value = colors[name]
            if typeof(value) == "Color3" then
                return value
            end
            return fallback
        end

        local border = themed("border", Color3.fromRGB(24, 25, 24))
        local background = themed("background", Color3.fromRGB(0, 0, 0))
        local textColor = themed("keybind_text", themed("active_text", Color3.fromRGB(197, 197, 197)))
        local inactive = themed("inactive_text", Color3.fromRGB(75, 72, 72))
        local accent = themed("accent", Color3.fromRGB(224, 211, 180))
        local success = themed("success", Color3.fromRGB(171, 160, 135))
        local section = themed("section", Color3.fromRGB(6, 6, 6))
        local risk = themed("risk", themed("error", Color3.fromRGB(104, 67, 61)))

        for _, object in ipairs(refs.borders) do
            if object and object.Parent then
                object.BackgroundColor3 = border
            end
        end

        for _, object in ipairs(refs.backgrounds) do
            if object and object.Parent then
                object.BackgroundColor3 = background
            end
        end

        for _, object in ipairs(refs.texts) do
            if object and object.Parent then
                object.TextColor3 = textColor
            end
        end

        for _, object in ipairs(IndicatorRuntime.bodyTexts or {}) do
            if object and object.Parent then
                object.TextTransparency = 0
                object.Visible = true
            end
        end

        for _, object in ipairs(refs.accents) do
            if object and object.Parent then
                object.BackgroundColor3 = accent
            end
        end

        for _, object in ipairs(refs.tracks) do
            if object and object.Parent then
                object.BackgroundColor3 = border
            end
        end

        if IndicatorRuntime.headerIcon and IndicatorRuntime.headerIcon.Parent then
            IndicatorRuntime.headerIcon.ImageColor3 = accent
        end
        if IndicatorRuntime.headerIconFallback and IndicatorRuntime.headerIconFallback.Parent then
            IndicatorRuntime.headerIconFallback.TextColor3 = accent
        end
        IndicatorRuntime.healthAccent =
            accent
        if IndicatorRuntime.cooldownFill then
            IndicatorRuntime.cooldownFill.BackgroundColor3 =
                Color3.fromRGB(
                    170,
                    132,
                    178
                )
        end
        if IndicatorRuntime.styleValue then
            IndicatorRuntime.styleValue.TextColor3 =
                typeof(
                    IndicatorRuntime.cachedStyleColor
                ) == "Color3"
                and IndicatorRuntime.cachedStyleColor
                or textColor
        end

        if IndicatorRuntime.statusValue then
            local status = tostring(IndicatorRuntime.statusValue.Text or "")
            if status == "Stunned" then
                IndicatorRuntime.statusValue.TextColor3 = risk
            elseif status == "Attacking" then
                IndicatorRuntime.statusValue.TextColor3 = accent
            elseif status == "Combat" then
                IndicatorRuntime.statusValue.TextColor3 = success
            else
                IndicatorRuntime.statusValue.TextColor3 = inactive
            end
        end
    end

    function IndicatorRuntime.bindCharacter(character)
        disconnectCharacter()
        IndicatorRuntime.character = character
        IndicatorRuntime.stableScreenPosition = nil
        IndicatorRuntime.positionUpdatedAt = 0
        IndicatorRuntime.cooldownStartedAt = 0
        IndicatorRuntime.cooldownEndAt = 0
        IndicatorRuntime.cooldownDuration = 0
        IndicatorRuntime.cooldownSawState = false
        IndicatorRuntime.cooldownLastRatio = 1
        IndicatorRuntime.setStatusVisible(false)
        IndicatorRuntime.setCooldownVisible(false)
        IndicatorRuntime.styleRefreshAt = 0
        IndicatorRuntime.cachedStyleColor = nil
        pcall(refreshIndicatorStyle, character, true)

        if not character then
            return
        end

        local function watch(attribute, callback)
            local connection = character:GetAttributeChangedSignal(attribute):Connect(callback)
            IndicatorRuntime.connections[#IndicatorRuntime.connections + 1] = connection
        end

        watch("M2Cooldown", function()
            local now = os.clock()
            local active, remaining = IndicatorRuntime.getCooldownState(character, now)
            if active then
                IndicatorRuntime.beginCooldown(character, remaining)
            end
        end)

        watch("M2CooldownRemaining", function()
            local now = os.clock()
            local active, remaining = IndicatorRuntime.getCooldownState(character, now)
            if active and IndicatorRuntime.cooldownStartedAt <= 0 then
                IndicatorRuntime.beginCooldown(character, remaining)
            end
        end)

        local active, remaining = IndicatorRuntime.getCooldownState(character, os.clock())
        if active then
            IndicatorRuntime.beginCooldown(character, remaining)
        end
    end

    function IndicatorRuntime.updateCooldown(character, now)
        local active, exactRemaining = IndicatorRuntime.getCooldownState(character, now)

        if not active then
            if IndicatorRuntime.cooldownSawState and IndicatorRuntime.cooldownStartedAt > 0 then
                local measured = now - IndicatorRuntime.cooldownStartedAt
                if validCooldownDuration(measured) then
                    IndicatorRuntime.learnedCooldown[currentStyleRaw(character)] = measured
                end
            end

            IndicatorRuntime.cooldownStartedAt = 0
            IndicatorRuntime.cooldownEndAt = 0
            IndicatorRuntime.cooldownDuration = 0
            IndicatorRuntime.cooldownSawState = false
            IndicatorRuntime.cooldownLastRatio = 1
            IndicatorRuntime.setCooldownVisible(false)
            return
        end

        if IndicatorRuntime.cooldownStartedAt <= 0 then
            IndicatorRuntime.beginCooldown(character, exactRemaining)
        end

        IndicatorRuntime.cooldownSawState = true
        local duration = math.max(
            IndicatorRuntime.resolveCooldownDuration(character),
            IndicatorRuntime.cooldownDuration,
            0.20
        )
        local remaining

        if exactRemaining then
            remaining = math.clamp(exactRemaining, 0, duration)
            IndicatorRuntime.cooldownEndAt = now + exactRemaining
        else
            remaining = math.max(0, IndicatorRuntime.cooldownEndAt - now)
            if remaining <= 0 then
                remaining = 0.01
            end
        end

        IndicatorRuntime.setCooldownVisible(true)
        local ratio = math.clamp(remaining / duration, 0, 1)
        ratio = math.min(ratio, tonumber(IndicatorRuntime.cooldownLastRatio) or 1)
        IndicatorRuntime.cooldownLastRatio = ratio

        if IndicatorRuntime.cooldownFill then
            IndicatorRuntime.cooldownFill.AnchorPoint = Vector2.new(0, 0)
            IndicatorRuntime.cooldownFill.Position = UDim2.fromOffset(0, 0)
            IndicatorRuntime.cooldownFill.Size = UDim2.new(
                ratio,
                0,
                1,
                0
            )
        end
    end

    function IndicatorRuntime.updateInfo(character, now)
        local humanoid = character:FindFirstChildOfClass("Humanoid")
        if not humanoid then
            return
        end

        local health = math.clamp(
            humanoid.Health / math.max(humanoid.MaxHealth, 1),
            0,
            1
        )

        local displayedHealth = tonumber(
            IndicatorRuntime.displayedHealth
        ) or health
        displayedHealth += (health - displayedHealth) * 0.18
        if math.abs(displayedHealth - health) < 0.002 then
            displayedHealth = health
        end
        IndicatorRuntime.displayedHealth = displayedHealth

        if IndicatorRuntime.healthFill then
            IndicatorRuntime.healthFill.Size = UDim2.new(
                displayedHealth,
                0,
                1,
                0
            )
        end

        if IndicatorRuntime.healthSurface
            and IndicatorRuntime.healthGradient
        then
            local accent =
                typeof(
                    IndicatorRuntime.healthAccent
                ) == "Color3"
                and IndicatorRuntime.healthAccent
                or Color3.fromRGB(
                    224,
                    211,
                    180
                )

            local black =
                Color3.fromRGB(
                    0,
                    0,
                    0
                )

            local lowHealthBlack = math.clamp(
                (0.50 - displayedHealth) / 0.50,
                0,
                1
            )
            lowHealthBlack = lowHealthBlack
                * lowHealthBlack
                * (3 - 2 * lowHealthBlack)
            local clockNow = tonumber(now) or os.clock()
            local breathe = (math.sin(clockNow * 4.8) + 1) * 0.5
            local base = accent:Lerp(black, lowHealthBlack)
            local edge = base:Lerp(black, 0.72)
            local shoulder = base:Lerp(
                black,
                0.28 + 0.10 * (1 - breathe)
            )
            local highlight = base:Lerp(
                accent,
                (0.14 + 0.10 * breathe) * (1 - lowHealthBlack)
            )

            IndicatorRuntime.healthSurface.BackgroundColor3 = base
            IndicatorRuntime.healthGradient.Color = ColorSequence.new({
                ColorSequenceKeypoint.new(0, edge),
                ColorSequenceKeypoint.new(0.23, shoulder),
                ColorSequenceKeypoint.new(0.5, highlight),
                ColorSequenceKeypoint.new(0.77, shoulder),
                ColorSequenceKeypoint.new(1, edge),
            })
            IndicatorRuntime.healthGradient.Offset = Vector2.new(
                math.sin(clockNow * 2.8) * 0.14,
                0
            )

            if IndicatorRuntime.statusValue
                and IndicatorRuntime.statusGradient
            then
                IndicatorRuntime.statusGradient.Color = ColorSequence.new({
                    ColorSequenceKeypoint.new(
                        0,
                        Color3.fromRGB(148, 148, 148)
                    ),
                    ColorSequenceKeypoint.new(
                        0.28,
                        Color3.fromRGB(218, 218, 218)
                    ),
                    ColorSequenceKeypoint.new(
                        0.5,
                        Color3.fromRGB(255, 255, 255)
                    ),
                    ColorSequenceKeypoint.new(
                        0.72,
                        Color3.fromRGB(218, 218, 218)
                    ),
                    ColorSequenceKeypoint.new(
                        1,
                        Color3.fromRGB(148, 148, 148)
                    ),
                })
                IndicatorRuntime.statusGradient.Offset = Vector2.new(
                    math.sin(clockNow * 3.4) * 0.18,
                    0
                )
            end

            if IndicatorRuntime.healthWipeOverlay then
                IndicatorRuntime.healthWipeOverlay.Visible = false
            end
        end

        if IndicatorRuntime.styleValue then
            local displayStyle = IndicatorRuntime.cachedStyleName or "Default"
            local okStyle, refreshed = pcall(
                refreshIndicatorStyle,
                character,
                false
            )
            if okStyle and type(refreshed) == "string" and refreshed ~= "" then
                displayStyle = refreshed
            end

            pcall(function()
                IndicatorRuntime.styleValue.Text = displayStyle
            end)
        end
        local nextStatus = statusName(character)
        if IndicatorRuntime.statusValue then
            IndicatorRuntime.statusValue.Text = nextStatus or ""
        end
        IndicatorRuntime.setStatusVisible(nextStatus ~= nil and nextStatus ~= "")

        IndicatorRuntime.updateCooldown(character, now)
        IndicatorRuntime.applyTheme()
    end

    local function stableBodyScreenEdge(torso, camera, side)
        local halfTorso = math.max(0.75, torso.Size.X * 0.5)
        local shoulderClearance = halfTorso + math.max(0.90, torso.Size.X * 0.60)
        local sign = side == "Left" and -1 or 1
        local edgePoint = torso.Position
            + camera.CFrame.RightVector * shoulderClearance * sign
        local projected = camera:WorldToViewportPoint(edgePoint)

        if projected.Z <= 0 then
            return nil
        end

        return projected.X
    end

    function IndicatorRuntime.updatePosition(character)
        local panel = IndicatorRuntime.panel
        if not panel then
            return
        end

        local camera = Workspace.CurrentCamera
        local torso = character and (
            character:FindFirstChild("UpperTorso")
            or character:FindFirstChild("Torso")
            or character:FindFirstChild("HumanoidRootPart")
        )

        if not camera or not torso or not torso:IsA("BasePart") then
            panel.Visible = false
            IndicatorRuntime.stableScreenPosition = nil
            IndicatorRuntime.positionUpdatedAt = 0
            return
        end

        local torsoPoint, onScreen = camera:WorldToViewportPoint(
            torso.Position + Vector3.new(0, 0.10, 0)
        )
        if torsoPoint.Z <= 0 or onScreen ~= true then
            panel.Visible = false
            IndicatorRuntime.stableScreenPosition = nil
            IndicatorRuntime.positionUpdatedAt = 0
            return
        end

        local panelHeight = panel.AbsoluteSize.Y > 0
            and panel.AbsoluteSize.Y
            or (IndicatorRuntime.cooldownRow and IndicatorRuntime.cooldownRow.Visible
                and IndicatorRuntime.cooldownHeight
                or IndicatorRuntime.baseHeight)

        -- Indicator Side maps directly to the selected side:
        -- Left -> left of the character, Right -> right of the character.
        -- Both sides use the same projected shoulder clearance + gap so the
        -- panel sits symmetrically instead of one side feeling farther away.
        local placementSide =
            IndicatorRuntime.side

        local edgeX = stableBodyScreenEdge(
            torso,
            camera,
            placementSide
        ) or torsoPoint.X

        local gap = 7
        local targetX
        if placementSide == "Left" then
            targetX =
                edgeX
                - IndicatorRuntime.width
                - gap
        else
            targetX =
                edgeX
                + gap
        end

        local targetY = torsoPoint.Y - panelHeight * 0.5
        local viewport = camera.ViewportSize

        targetX = math.clamp(
            targetX,
            4,
            math.max(4, viewport.X - IndicatorRuntime.width - 4)
        )
        targetY = math.clamp(
            targetY,
            4,
            math.max(4, viewport.Y - panelHeight - 4)
        )

        local clockNow = os.clock()
        local previous = IndicatorRuntime.stableScreenPosition
        local nextPosition

        if previous then
            if math.abs(targetX - previous.X) < 0.75 then
                targetX = previous.X
            end
            if math.abs(targetY - previous.Y) < 0.75 then
                targetY = previous.Y
            end

            local lastAt = tonumber(IndicatorRuntime.positionUpdatedAt) or clockNow
            local dt = math.clamp(clockNow - lastAt, 0, 0.10)
            local alpha = 1 - math.exp(-14 * dt)
            nextPosition = previous:Lerp(Vector2.new(targetX, targetY), alpha)
        else
            nextPosition = Vector2.new(targetX, targetY)
        end

        IndicatorRuntime.positionUpdatedAt = clockNow
        IndicatorRuntime.stableScreenPosition = nextPosition

        panel.Position = UDim2.fromOffset(
            math.floor(nextPosition.X + 0.5),
            math.floor(nextPosition.Y + 0.5)
        )
        panel.Visible = true
    end

    function IndicatorRuntime.step()
        if not IndicatorRuntime.enabled then
            return
        end
        if not IndicatorRuntime.ensureGui() then
            return
        end

        local character = LocalPlayer.Character
        if not character or not character.Parent then
            if IndicatorRuntime.panel then
                IndicatorRuntime.panel.Visible = false
            end
            IndicatorRuntime.stableScreenPosition = nil
            IndicatorRuntime.positionUpdatedAt = 0
            return
        end

        if IndicatorRuntime.character ~= character then
            IndicatorRuntime.bindCharacter(character)
        end

        local now = os.clock()
        local okInfo = pcall(
            IndicatorRuntime.updateInfo,
            character,
            now
        )
        local okPosition = pcall(
            IndicatorRuntime.updatePosition,
            character
        )

        if not okInfo or not okPosition then
            return
        end
    end

    function IndicatorRuntime.setSide(value)
        if type(value) == "table" then
            value = value[1] or value.value or value.Value
        end

        local normalized = string.lower(tostring(value or "Right"))
        local nextSide = normalized == "left" and "Left" or "Right"

        if IndicatorRuntime.side ~= nextSide then
            IndicatorRuntime.side = nextSide
            IndicatorRuntime.stableScreenPosition = nil
            IndicatorRuntime.positionUpdatedAt = 0
        else
            IndicatorRuntime.side = nextSide
        end
    end

    function IndicatorRuntime.setEnabled(enabled)
        IndicatorRuntime.enabled =
            enabled == true

        if IndicatorRuntime.enabled then
            IndicatorRuntime.ensureGui()
            IndicatorRuntime.setSide(
                Flags.visual_player_indicator_side
                    or "Right"
            )

            if not IndicatorRuntime.heartbeatConnection then
                IndicatorRuntime.heartbeatAccumulator =
                    0

                IndicatorRuntime.heartbeatConnection =
                    RunService.Heartbeat:Connect(function(dt)
                        local fps =
                            math.clamp(
                                tonumber(
                                    Flags.visual_esp_fps
                                ) or 60,
                                15,
                                240
                            )
                        local interval =
                            1 / fps

                        IndicatorRuntime.heartbeatAccumulator =
                            (
                                IndicatorRuntime.heartbeatAccumulator
                                or 0
                            )
                            + math.max(
                                tonumber(dt) or 0,
                                0
                            )

                        if IndicatorRuntime.heartbeatAccumulator
                            < interval
                        then
                            return
                        end

                        IndicatorRuntime.heartbeatAccumulator =
                            IndicatorRuntime.heartbeatAccumulator
                            % interval

                        IndicatorRuntime.step()
                    end)
            end
        else
            if IndicatorRuntime.heartbeatConnection then
                pcall(function()
                    IndicatorRuntime.heartbeatConnection:Disconnect()
                end)
                IndicatorRuntime.heartbeatConnection =
                    nil
            end

            if IndicatorRuntime.panel then
                IndicatorRuntime.panel.Visible =
                    false
                IndicatorRuntime.stableScreenPosition =
                    nil
                IndicatorRuntime.positionUpdatedAt =
                    0
                IndicatorRuntime.heartbeatAccumulator =
                    0
            end
        end
    end

    function IndicatorRuntime.shutdown()
        IndicatorRuntime.enabled = false
        disconnectCharacter()

        if IndicatorRuntime.heartbeatConnection then
            pcall(function()
                IndicatorRuntime.heartbeatConnection:Disconnect()
            end)
            IndicatorRuntime.heartbeatConnection = nil
        end

        if IndicatorRuntime.gui then
            pcall(function()
                IndicatorRuntime.gui:Destroy()
            end)
        end

        IndicatorRuntime.gui = nil
        IndicatorRuntime.panel = nil
        IndicatorRuntime.body = nil
        IndicatorRuntime.healthFill = nil
        IndicatorRuntime.healthSurface = nil
        IndicatorRuntime.healthGradient = nil
        IndicatorRuntime.healthWipeOverlay = nil
        IndicatorRuntime.displayedHealth = nil
        IndicatorRuntime.healthAccent = nil
        IndicatorRuntime.healthTrack = nil
        IndicatorRuntime.cooldownRow = nil
        IndicatorRuntime.styleRow = nil
        IndicatorRuntime.statusRow = nil
        IndicatorRuntime.cooldownFill = nil
        IndicatorRuntime.cooldownTrack = nil
        IndicatorRuntime.styleValue = nil
        IndicatorRuntime.statusValue = nil
        IndicatorRuntime.bodyTexts = nil
        IndicatorRuntime.headerIcon = nil
        IndicatorRuntime.headerIconFallback = nil
        IndicatorRuntime.themeRefs = nil
        IndicatorRuntime.stableScreenPosition = nil
        IndicatorRuntime.positionUpdatedAt = 0
    end

    IndicatorRuntime.setSide(Flags.visual_player_indicator_side or "Right")
    IndicatorRuntime.setEnabled(Flags.visual_player_indicator == true)
end

local function getSpeedMultiplier(owner)
    if not owner then
        return 1
    end

    local okHeight, height = pcall(CombatUtils.GetCharacterHeight, owner)

    if not okHeight or typeof(height) ~= "number" then
        return 1
    end

    local okSpeed, speed = pcall(CombatUtils.GetAttackSpeedMultiplier, height)

    if not okSpeed or typeof(speed) ~= "number" or speed <= 0 then
        return 1
    end

    return speed
end

