local function autoPunishFlagNumber(flagName, fallback, minimum, maximum)
    local value = tonumber(Flags[flagName]) or fallback
    return math.clamp(value, minimum, maximum)
end

local function getAutoPunishComboMode()
    local value = Flags.ap_auto_punish_combo_mode
    if type(value) == "table" then
        value = value[1]
    end
    return value == "Follow" and "Follow" or "Fixed"
end

local function getAutoPunishFixedComboHit()
    return math.clamp(
        math.floor(autoPunishFlagNumber("ap_auto_punish_fixed_combo_hit", 1, 1, 4) + 0.0001),
        1,
        4
    )
end

local function getAutoPunishM1Rate()
