end

local function isAutoPunishActive()
    return Flags.ap_enable == true and Flags.ap_auto_punish == true
end

local function isAutoPunishTargetStunned(character)
    if not character or not character.Parent then
        return false
    end

    if character:GetAttribute("Stunned") == true then
        return true
    end

    local value = character:FindFirstChild("Stunned")
    return value and value:IsA("BoolValue") and value.Value == true or false
end

local function getAutoPunishDistance(target)
    local character = getCharacter()
    local myRoot = getRoot(character)
    local targetRoot = getRoot(target)
    if not myRoot or not targetRoot then
        return math.huge
    end
    return flat(targetRoot.Position - myRoot.Position).Magnitude
end

local function getCompatUpvalue(func, index)
    if type(func) ~= "function" then
        return nil
    end

    local getter = getupvalue or (debug and debug.getupvalue)
    if type(getter) ~= "function" then
        return nil
    end

    local result = table.pack(pcall(getter, func, index))
    if result[1] ~= true then
        return nil
    end



    if result.n >= 3 then
        return result[3]
    end
    return result[2]
end

local function setCompatUpvalue(func, index, value)
    if type(func) ~= "function" then
        return false
    end

    local setter = setupvalue or (debug and debug.setupvalue)
    if type(setter) ~= "function" then
        return false
    end

    return pcall(setter, func, index, value)
end

local function resolveAutoPunishTryM1()
    local module = getCombatModule("M1")
    if not module or type(module.OnM1Activated) ~= "function" then
        autoPunishTryM1Module = nil
        autoPunishTryM1 = nil
        return nil
    end

    if autoPunishTryM1Module == module and type(autoPunishTryM1) == "function" then
        return autoPunishTryM1
    end

    local candidate = getCompatUpvalue(module.OnM1Activated, 1)
    if type(candidate) == "function" then
        autoPunishTryM1Module = module
        autoPunishTryM1 = candidate
        return candidate
    end

    autoPunishTryM1Module = module
    autoPunishTryM1 = nil
    return nil
end

local function releaseAutoPunishConfirmedBlock(character, expectedGuardSerial)
    character = character or getCharacter()

    local activeGuard = Menu._apCurrentBlock
    if expectedGuardSerial ~= nil
        and type(activeGuard) == "table"
        and tonumber(activeGuard.serial) ~= tonumber(expectedGuardSerial)
    then
        debugLog("AUTOPUNISH_GUARD_RELEASE_SKIP", {
            expectedSerial = expectedGuardSerial,
            activeSerial = activeGuard.serial or "",
            activeOwner = activeGuard.owner or "",
            activeAttack = activeGuard.attack or "",
            age = os.clock() - (tonumber(activeGuard.startedAt) or os.clock()),
        }, true)
        return false
    end

    if Menu._apBlockActive == true
        and type(Menu._releaseAutoBlockForDodge) == "function"
    then
        pcall(Menu._releaseAutoBlockForDodge)
    end

    if not character or not character.Parent then
        return true
    end

    if character:GetAttribute("Blocking") == true
        or character:GetAttribute("PerfectBlocking") == true
    then
        activeGuard = Menu._apCurrentBlock
        if expectedGuardSerial ~= nil
            and type(activeGuard) == "table"
            and tonumber(activeGuard.serial) ~= tonumber(expectedGuardSerial)
        then
            return false
        end

        local blockModule = getCombatModule("Block")
        if type(blockModule) == "table"
            and type(blockModule.Unblock) == "function"
        then
            pcall(blockModule.Unblock)
        end
    end

    return true
end


