                            game
                        )
                        if okDescendant and inGame == true then
                            module = candidate
                            break
                        end
                    end
                end
            end)
        end

        if not module then
            return nil
        end

        local usable = false
        pcall(function()
            usable = module:IsA("ModuleScript")
                and module.Parent ~= nil
                and module:IsDescendantOf(game)
        end)
        if not usable then
            return nil
        end

        local okRequire, movementUtils = pcall(require, module)
        if okRequire and type(movementUtils) == "table" then
            shared.sourceNoSlowdownMovementUtils = movementUtils
            return movementUtils
        end

        return nil
    end

    runtime.noSlowdownShouldRestore = function(character)
        if Flags.misc_no_slowdown ~= true
            or not character
            or not character.Parent
        then
            return false
        end

        if character:GetAttribute("Ragdoll") == true
            or character:GetAttribute("Downed") == true
        then
            return false
        end

        if Flags.misc_no_slowdown_attack ~= false
            and (
                character:GetAttribute("M1") == true
                or character:GetAttribute("M2") == true
                or character:GetAttribute("M1Hold") == true
                or character:GetAttribute("PendingM1") == true
                or character:GetAttribute("PendingM2") == true
                or character:GetAttribute("CombatAttacking") == true
            )
        then
            return true
        end

        if Flags.misc_no_slowdown_block ~= false
            and (
                character:GetAttribute("Blocking") == true
                or character:GetAttribute("PerfectBlocking") == true
            )
        then
            return true
        end

        if Flags.misc_no_slowdown_get_hit ~= false
            and (
                character:GetAttribute("Stunned") == true
                or character:GetAttribute("CantAnything") == true
                or character:GetAttribute("GuardBroken") == true
                or character:GetAttribute("Parried") == true
                or character:GetAttribute("GrappleWinnerStun") == true
            )
        then
            return true
        end

        return false
    end

    runtime.readNoSlowdownBaseSpeed = function(character, humanoid)
        local configured = math.clamp(
            tonumber(Flags.misc_no_slowdown_restore_speed) or 0,
            0,
            25
        )

        if configured > 0 then
            return configured
        end

        local movementUtils = runtime.resolveNoSlowdownMovementUtils()
        if movementUtils
            and type(movementUtils.GetBaseWalkSpeed) == "function"
        then
            local okBase, baseSpeed = pcall(
                movementUtils.GetBaseWalkSpeed,
                character,
                humanoid
            )

            if okBase
                and typeof(baseSpeed) == "number"
                and baseSpeed > 0
            then
                return math.clamp(baseSpeed, 1, 25)
            end
        end

        local attrSpeed = character
            and character:GetAttribute("BaseWalkSpeed")
        if typeof(attrSpeed) == "number" and attrSpeed > 0 then
            return math.clamp(attrSpeed, 1, 25)
        end

        if humanoid
            and typeof(humanoid.WalkSpeed) == "number"
            and humanoid.WalkSpeed > 3
            and humanoid.WalkSpeed <= 25
            and not runtime.noSlowdownShouldRestore(character)
        then
            return humanoid.WalkSpeed
        end

        return math.clamp(
            tonumber(runtime.noSlowdownLastDefaultSpeed) or 12,
            1,
            25
        )
    end

    runtime.refreshNoSlowdownBaseline = function()
        local character = LocalPlayer.Character
        local humanoid = character
            and character:FindFirstChildOfClass("Humanoid")

        if not character or not humanoid then
            return nil
        end

        local speed = runtime.readNoSlowdownBaseSpeed(
            character,
            humanoid
        )

        if typeof(speed) == "number" and speed > 0 then
            runtime.noSlowdownBaselineSpeed = speed
            runtime.noSlowdownLastDefaultSpeed = speed
        end

        return runtime.noSlowdownBaselineSpeed
    end

    runtime.getNoSlowdownRestoreSpeed = function(character, humanoid)
        local configured = math.clamp(
            tonumber(Flags.misc_no_slowdown_restore_speed) or 0,
            0,
            25
        )
        if configured > 0 then
            return configured
        end

        if runtime.noSlowdownBoundCharacter ~= character
            or runtime.noSlowdownBaselineSpeed == nil
        then
            runtime.refreshNoSlowdownBaseline()
        end

        return math.clamp(
            tonumber(runtime.noSlowdownBaselineSpeed)
                or tonumber(runtime.noSlowdownLastDefaultSpeed)
                or 12,
            1,
            25
        )
    end

    runtime.enforceNoSlowdown = function(reason)
        if runtime.noSlowdownApplying == true
            or Flags.misc_no_slowdown ~= true
        then
            return false
        end

        local character = LocalPlayer.Character
        local humanoid = character
            and character:FindFirstChildOfClass("Humanoid")

        if not character
            or not humanoid
            or humanoid.Health <= 0
            or humanoid.Sit
            or not runtime.noSlowdownShouldRestore(character)
        then
            return false
        end

        local restoreSpeed =
            runtime.getNoSlowdownRestoreSpeed(character, humanoid)

        if typeof(restoreSpeed) ~= "number" or restoreSpeed <= 0 then
            return false
        end

        if humanoid.WalkSpeed + 0.01 >= restoreSpeed then
            return false
        end

        runtime.noSlowdownApplying = true

        pcall(function()
            humanoid.WalkSpeed = restoreSpeed
        end)

        runtime.noSlowdownApplying = false

        debugLog("NO_SLOWDOWN_RESTORE", {
            reason = reason or "",
            speed = restoreSpeed,
            attack = Flags.misc_no_slowdown_attack ~= false,
            block = Flags.misc_no_slowdown_block ~= false,
            getHit = Flags.misc_no_slowdown_get_hit ~= false,
        })

        return true
    end

    runtime.queueNoSlowdownEnforce = function(reason)
        if runtime.noSlowdownQueued == true
            or Flags.misc_no_slowdown ~= true
        then
            return
        end

        runtime.noSlowdownQueued = true
        task.defer(function()
            runtime.noSlowdownQueued = false
            runtime.enforceNoSlowdown(reason)
        end)
    end

    runtime.installNoSlowdown = function()
        shared.flags = Flags
        shared.runtime = runtime

        local movementUtils = runtime.resolveNoSlowdownMovementUtils()
        if type(movementUtils) ~= "table"
            or type(movementUtils.SetSpeed) ~= "function"
        then
            return false
        end

        if shared.sourceNoSlowdownDirectWrapperInstalled == true
            and shared.sourceNoSlowdownDirectMovementUtils == movementUtils
        then
            return true
        end

        local downstream =
            type(shared.sourceNoSlowdownOriginalSetSpeed) == "function"
                and shared.sourceNoSlowdownOriginalSetSpeed
                or movementUtils.SetSpeed

        shared.sourceNoSlowdownDirectOriginalSetSpeed = downstream
        shared.sourceNoSlowdownDirectMovementUtils = movementUtils

        local function wrappedSetSpeed(humanoid, speed, ...)
            local current = environment.__SilentMiscHooks
            local currentRuntime = current and current.runtime
            local flags = current and current.flags

            if flags
                and flags.misc_no_slowdown == true
                and currentRuntime
                and typeof(humanoid) == "Instance"
                and humanoid:IsA("Humanoid")
                and humanoid.Parent == LocalPlayer.Character
                and currentRuntime.noSlowdownShouldRestore(
                    LocalPlayer.Character
                )
            then
                local restoreSpeed =
                    currentRuntime.getNoSlowdownRestoreSpeed(
                        LocalPlayer.Character,
                        humanoid
                    )

                if typeof(speed) == "number"
                    and speed < restoreSpeed
                then
                    speed = restoreSpeed
                end
            end

            return downstream(humanoid, speed, ...)
        end

        movementUtils.SetSpeed = wrappedSetSpeed
        shared.sourceNoSlowdownDirectWrapper = wrappedSetSpeed
        shared.sourceNoSlowdownDirectWrapperInstalled = true

        return true
    end

    runtime.disconnectNoSlowdownSignals = function()
        if runtime.NoSlowdownCharacterAddedConnection then
            pcall(function()
                runtime.NoSlowdownCharacterAddedConnection:Disconnect()
            end)
            runtime.NoSlowdownCharacterAddedConnection = nil
        end

        for _, connection in ipairs(runtime.noSlowdownConnections) do
            pcall(function()
                connection:Disconnect()
            end)
        end
        table.clear(runtime.noSlowdownConnections)

        runtime.noSlowdownBoundCharacter = nil
        runtime.noSlowdownBoundHumanoid = nil
        runtime.noSlowdownQueued = false
    end

    runtime.bindNoSlowdownCharacter = function(character)
        for _, connection in ipairs(runtime.noSlowdownConnections) do
            pcall(function()
                connection:Disconnect()
            end)
        end
        table.clear(runtime.noSlowdownConnections)

        runtime.noSlowdownBoundCharacter = character
        runtime.noSlowdownBoundHumanoid = nil
        runtime.noSlowdownBaselineSpeed = nil

        if not character or not character.Parent then
            return
        end

        local humanoid = character:FindFirstChildOfClass("Humanoid")
        if not humanoid then
            return
        end

        runtime.noSlowdownBoundHumanoid = humanoid
        runtime.refreshNoSlowdownBaseline()

        local watchedAttributes = {
            "M1",
            "M2",
            "M1Hold",
            "PendingM1",
            "PendingM2",
            "CombatAttacking",
            "Blocking",
            "PerfectBlocking",
            "Stunned",
            "CantAnything",
            "GuardBroken",
            "Parried",
            "GrappleWinnerStun",
            "Ragdoll",
            "Downed",
        }

        for _, attributeName in ipairs(watchedAttributes) do
            runtime.noSlowdownConnections[#runtime.noSlowdownConnections + 1] =
                character:GetAttributeChangedSignal(attributeName):Connect(
                    function()
                        if Flags.misc_no_slowdown ~= true then
                            return
                        end

                        if runtime.noSlowdownShouldRestore(character) then
                            runtime.queueNoSlowdownEnforce(
                                "attr_" .. attributeName
                            )
                        elseif humanoid.WalkSpeed > 3
                            and humanoid.WalkSpeed <= 25
                        then
                            runtime.noSlowdownLastDefaultSpeed =
                                humanoid.WalkSpeed
                            runtime.noSlowdownBaselineSpeed =
                                runtime.readNoSlowdownBaseSpeed(
                                    character,
                                    humanoid
                                )
                        end
                    end
                )
        end

        runtime.noSlowdownConnections[#runtime.noSlowdownConnections + 1] =
            humanoid:GetPropertyChangedSignal("WalkSpeed"):Connect(function()
                if runtime.noSlowdownApplying == true
                    or Flags.misc_no_slowdown ~= true
                then
                    return
                end

                if runtime.noSlowdownShouldRestore(character) then
                    runtime.queueNoSlowdownEnforce("walkspeed_changed")
                elseif humanoid.WalkSpeed > 3
                    and humanoid.WalkSpeed <= 25
                then
                    runtime.noSlowdownLastDefaultSpeed =
                        humanoid.WalkSpeed
                end
            end)

        runtime.queueNoSlowdownEnforce("character_bound")
    end

    runtime.refreshNoSlowdown = function(enabled)
        if runtime.NoSlowdownHeartbeatConnection then
            pcall(function()
                runtime.NoSlowdownHeartbeatConnection:Disconnect()
            end)
            runtime.NoSlowdownHeartbeatConnection = nil
        end

        if enabled ~= true then
            runtime.disconnectNoSlowdownSignals()
            return
        end

        runtime.installNoSlowdown()

        if not runtime.NoSlowdownCharacterAddedConnection then
            runtime.NoSlowdownCharacterAddedConnection =
                LocalPlayer.CharacterAdded:Connect(function(character)
                    if Flags.misc_no_slowdown == true then
                        task.defer(
                            runtime.bindNoSlowdownCharacter,
                            character
                        )
                    end
                end)
        end

        runtime.bindNoSlowdownCharacter(LocalPlayer.Character)
    end

    runtime.noSlowdownStep = function()
        runtime.enforceNoSlowdown("compat_step")
    end

    runtime.noDelayLastCharacter = nil
    runtime.noDelayM1WasActive = false
    runtime.noDelayComboSerial = 0
    runtime.noDelayM1Ids = {}
    runtime.noDelayM1IdsCharacter = nil

    runtime.getNoDelayAnimationSpeed = function()
        return math.clamp(
            tonumber(Flags.misc_no_delay_animation_speed) or 1.50,
            1,
            3
        )
    end

    runtime.getNoDelayTimeScale = function()
        if Flags.misc_no_delay ~= true then
            return 1
        end
        return 1 / runtime.getNoDelayAnimationSpeed()
    end

    runtime.rebuildNoDelayM1Ids = function(character)
        runtime.noDelayM1Ids = {}
        runtime.noDelayM1IdsCharacter = character

        if not character then
            return
        end

        local folder
        pcall(function()
            folder = CombatAnimationUtils.GetCombatAnimsFolderForCharacter(
                character
            )
        end)

        if not folder then
            return
        end

        for _, object in ipairs(folder:GetDescendants()) do
            if object:IsA("Animation") then
                local compact = string.lower(object.Name or "")
                    :gsub("[%s_%-%#]", "")
                if compact == "1stm1"
                    or compact == "2ndm1"
                    or compact == "3rdm1"
                    or compact == "4thm1"
                then
                    local id = tostring(object.AnimationId or ""):match("%d+")
                    if id then
                        runtime.noDelayM1Ids[id] = true
                    end
                end
            end
        end
    end

    runtime.isNoDelayM1Track = function(track)
        if not track or not track.Animation then
            return false
        end

        local character = LocalPlayer.Character
        if runtime.noDelayM1IdsCharacter ~= character then
            runtime.rebuildNoDelayM1Ids(character)
        end

        local id = tostring(track.Animation.AnimationId or ""):match("%d+")
        if id and runtime.noDelayM1Ids[id] == true then
            return true
        end

        local name = string.lower(
            tostring(track.Animation.Name or track.Name or "")
        ):gsub("[%s_%-%#]", "")

        return name == "1stm1"
            or name == "2ndm1"
            or name == "3rdm1"
            or name == "4thm1"
    end

    runtime.applyNoDelayTrack = function(track)
        if Flags.misc_no_delay ~= true
            or not runtime.isNoDelayM1Track(track)
        then
            return
        end

        local speed = runtime.getNoDelayAnimationSpeed()
        pcall(function()
            track:AdjustSpeed(speed)
        end)
    end

    runtime.resetNoDelayTracks = function()
        local character = LocalPlayer.Character
        local humanoid = character
            and character:FindFirstChildOfClass("Humanoid")
        local animator = humanoid
            and humanoid:FindFirstChildOfClass("Animator")

        if not animator then
            return
        end

        for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
            if runtime.isNoDelayM1Track(track) then
                pcall(function()
                    track:AdjustSpeed(1)
                end)
            end
        end
    end

    runtime.resolveNoDelayTryM1 = function()
        local module = getCombatModule("M1")
        if type(module) ~= "table"
            or type(module.OnM1Activated) ~= "function"
        then
            return nil
        end

        local candidate = getCompatUpvalue(module.OnM1Activated, 1)
        return type(candidate) == "function" and candidate or nil
    end

    runtime.scheduleNoDelayComboReset = function()
        runtime.noDelayComboSerial += 1
        local serial = runtime.noDelayComboSerial
        local resetDelay = 1.55 * runtime.getNoDelayTimeScale()

        task.delay(resetDelay, function()
            if serial ~= runtime.noDelayComboSerial
                or Flags.misc_no_delay ~= true
            then
                return
            end

            local character = LocalPlayer.Character
            if character and (
                character:GetAttribute("M1") == true
                or character:GetAttribute("PendingM1") == true
                or character:GetAttribute("M1Hold") == true
            ) then
                return
            end

            local tryM1 = runtime.resolveNoDelayTryM1()
            if type(tryM1) == "function" then
                local currentCombo = getCompatUpvalue(tryM1, 9)
                if typeof(currentCombo) == "number" then
                    pcall(setCompatUpvalue, tryM1, 9, 0)
                end
            end
        end)
    end

    runtime.noDelayStep = function()
        if Flags.misc_no_delay ~= true then
            runtime.noDelayM1WasActive = false
            return
        end

        local character = LocalPlayer.Character
        if not character then
            return
        end

        if runtime.noDelayLastCharacter ~= character then
            runtime.noDelayLastCharacter = character
            runtime.noDelayM1WasActive = false
            runtime.noDelayComboSerial += 1
            runtime.rebuildNoDelayM1Ids(character)
        end

        local humanoid = character:FindFirstChildOfClass("Humanoid")
        local animator = humanoid
            and humanoid:FindFirstChildOfClass("Animator")

        if animator then
            for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
                runtime.applyNoDelayTrack(track)
            end
        end

        local m1Active =
            character:GetAttribute("M1") == true
            or character:GetAttribute("PendingM1") == true

        if m1Active and not runtime.noDelayM1WasActive then
            runtime.scheduleNoDelayComboReset()
        end

        runtime.noDelayM1WasActive = m1Active
    end

    runtime.installNoDelay = function()
        if Flags.misc_no_delay ~= true then
            if runtime.NoDelayHeartbeatConnection then
                pcall(function()
                    runtime.NoDelayHeartbeatConnection:Disconnect()
                end)
                runtime.NoDelayHeartbeatConnection =
                    nil
            end

            runtime.noDelayComboSerial += 1
            runtime.resetNoDelayTracks()
            runtime.noDelayM1WasActive = false
            return true
        end

        runtime.noDelayStep()

        if not runtime.NoDelayHeartbeatConnection then
            runtime.NoDelayHeartbeatConnection =
                RunService.Heartbeat:Connect(function()
                    runtime.noDelayStep()
                end)
        end

        return true
    end

    runtime.installInfiniteStamina = function()
        shared.flags = Flags
        shared.localPlayer = LocalPlayer

        if shared.staminaHookInstalled == true then
            return true
        end

        if type(hookmetamethod) ~= "function"
            or type(getnamecallmethod) ~= "function"
        then
            return false
        end

        shared.staminaWrapper = function(self, ...)
            local current = environment.__SilentMiscHooks
            local flags = current and current.flags

            if flags
                and flags.misc_infinite_stamina == true
                and getnamecallmethod() == "GetAttribute"
                and current.localPlayer
                and self == current.localPlayer.Character
                and select(1, ...) == "Stamina"
            then
                return 100
            end

            return current.oldNamecall(self, ...)
        end

        if type(newcclosure) == "function" then
            shared.staminaWrapper = newcclosure(shared.staminaWrapper)
        end

        local ok, old = pcall(
            hookmetamethod,
            game,
            "__namecall",
            shared.staminaWrapper
        )

        if not ok or type(old) ~= "function" then
            return false
        end

        shared.oldNamecall = old
        shared.staminaHookInstalled = true
        return true
    end

    runtime.installNoBlur = function()
        shared.flags = Flags

        if type(shared.screenEffects) ~= "table" then
            shared.screenEffects = select(
                1,
                requireLoadedModuleByName("ScreenEffects")
            )
        end

        if type(shared.screenEffects) ~= "table"
            or type(shared.screenEffects.SetBlur) ~= "function"
        then
            return false
        end

        if shared.blurHookInstalled == true
            and shared.blurHookVersion ~= 19
        then
            if type(shared.originalSetBlur) == "function" then
                pcall(function()
                    shared.screenEffects.SetBlur = shared.originalSetBlur
                end)
            end
            if type(shared.originalClearBlur) == "function" then
                pcall(function()
                    shared.screenEffects.ClearBlur = shared.originalClearBlur
                end)
            end
            shared.blurHookInstalled = false
        end

        if shared.blurHookInstalled == true
            and shared.blurHookVersion == 19
        then
            return true
        end

        shared.suppressedBlurRequests =
            shared.suppressedBlurRequests or {}
        shared.originalSetBlur = shared.screenEffects.SetBlur
        shared.originalClearBlur = shared.screenEffects.ClearBlur

        shared.screenEffects.SetBlur = function(key, ...)
            local current = environment.__SilentMiscHooks
            local flags = current and current.flags
            local instantRespawnSuppress =
                current
                and current.instantRespawnTransitionActive == true
                and os.clock()
                    < (
                        tonumber(
                            current.instantRespawnBlurSuppressUntil
                        ) or 0
                    )

            if flags and flags.misc_no_blur == true then
                if key ~= nil then
                    current.suppressedBlurRequests =
                        current.suppressedBlurRequests or {}
                    current.suppressedBlurRequests[key] = {
                        at = os.clock(),
                        args = table.pack(...),
                    }
                end

                if type(current.originalClearBlur) == "function" then
                    pcall(current.originalClearBlur, key, 0)
                end
                return
            end

            if instantRespawnSuppress then
                local keyName = tostring(key)
                local character = LocalPlayer.Character
                local newlyDowned = character
                    and character:GetAttribute("Downed") == true
                local deathBlur =
                    keyName == "HealthGripped"
                    or keyName == "Death"
                    or keyName == "DeathUI"
                    or keyName == "RestartMyHeart"
                    or (keyName == "HealthDowned" and not newlyDowned)

                if deathBlur then
                    if type(current.originalClearBlur) == "function" then
                        pcall(current.originalClearBlur, key, 0)
                    end
                    return
                end
            end

            return current.originalSetBlur(key, ...)
        end

        if type(shared.originalClearBlur) == "function" then
            shared.screenEffects.ClearBlur = function(key, ...)
                local current = environment.__SilentMiscHooks
                if current and current.suppressedBlurRequests and key ~= nil then
                    current.suppressedBlurRequests[key] = nil
                end
                return current.originalClearBlur(key, ...)
            end
        end

        shared.blurHookInstalled = true
        shared.blurHookVersion = 19
        return true
    end

    runtime.restoreSuppressedBlur = function()
        if Flags.misc_no_blur == true
            or shared.instantRespawnTransitionActive == true
            or type(shared.originalSetBlur) ~= "function"
        then
            return
        end

        local requests = shared.suppressedBlurRequests
        if type(requests) ~= "table" then
            return
        end

        local now = os.clock()
        local character = LocalPlayer.Character
        local downed = character
            and character:GetAttribute("Downed") == true

        for key, request in pairs(requests) do
            requests[key] = nil

            local age = now - (tonumber(request and request.at) or 0)
            local persistentState = downed
                and tostring(key) == "HealthDowned"

            if (age >= 0 and age <= 1.15) or persistentState then
                local args = request and request.args
                if type(args) == "table" then
                    pcall(
                        shared.originalSetBlur,
                        key,
                        table.unpack(args, 1, args.n or #args)
                    )
                end
            end
        end
    end

    runtime.forceNoBlur = function()
        if Flags.misc_no_blur ~= true then
            return
        end

        if type(shared.originalClearBlur) == "function" then
            for _, key in ipairs({
                "HealthHit",
                "HealthDowned",
                "HealthGripped",
                "GlassesMissing",
                "__Impact",
            }) do
                pcall(shared.originalClearBlur, key, 0)
            end
        end

        local blur = game:GetService("Lighting"):FindFirstChild("ScreenEffectsBlur")
        if blur and blur:IsA("BlurEffect") then
            blur.Size = 0
            blur.Enabled = false
        end
    end

    runtime.clearInstantRespawnBlur = function()
        if shared.instantRespawnTransitionActive ~= true then
            return
        end

        shared.instantRespawnBlurSuppressUntil =
            math.max(
                tonumber(shared.instantRespawnBlurSuppressUntil) or 0,
                os.clock() + 0.85
            )

        runtime.installNoBlur()

        local clearBlur =
            shared.originalClearBlur
            or (
                type(shared.screenEffects) == "table"
                and shared.screenEffects.ClearBlur
                or nil
            )

        if type(clearBlur) == "function" then
            for _, key in ipairs({
                "HealthDowned",
                "HealthGripped",
                "Death",
                "DeathUI",
                "RestartMyHeart",
            }) do
                pcall(clearBlur, key, 0)
            end
        end

        pcall(function()
            local blur =
                game:GetService("Lighting"):FindFirstChild(
                    "ScreenEffectsBlur"
                )

            if blur and blur:IsA("BlurEffect") then
                blur.Size = 0
                blur.Enabled = false
            end
        end)
    end

    runtime.NoBlurRenderName =
        "SilentMiscIsolatedNoBlurV19"

    runtime.refreshBlur = function(enabled)
        runtime.installNoBlur()

        pcall(function()
            RunService:UnbindFromRenderStep(
                runtime.NoBlurRenderName
            )
        end)

        if enabled == true then
            runtime.forceNoBlur()

            RunService:BindToRenderStep(
                runtime.NoBlurRenderName,
                Enum.RenderPriority.Last.Value + 130,
                function()
                    runtime.forceNoBlur()
                end
            )
        else
            task.defer(runtime.restoreSuppressedBlur)
        end
    end

    runtime.instantRespawnController = nil
    runtime.instantRespawnModule = nil
    runtime.instantRespawnOriginalStartDeath = nil
    runtime.instantRespawnHookInstalled = false
    runtime.instantRespawnLastAttempt = 0
    runtime.instantRespawnRetrySerial = 0
    runtime.instantRespawnBoundCharacter = nil
    runtime.instantRespawnDeathScreenActive = false
    runtime.instantRespawnDeathGui = nil
    runtime.instantRespawnDeathGuiConnections =
        runtime.instantRespawnDeathGuiConnections
        or {}
    runtime.instantRespawnScreenLastTrigger = 0

    runtime.hideInstantRespawnPresentation = function(controller)
        pcall(function()
            runtime.clearInstantRespawnBlur()
        end)

        if controller and controller._pulseTween then
            pcall(function()
                controller._pulseTween:Cancel()
                controller._pulseTween = nil
            end)
        end

        if controller and controller._gui then
            pcall(function()
                controller._gui.Enabled = false
            end)
        end

        if controller and controller._main then
            pcall(function()
                controller._main.Visible = false
            end)
        end

        if controller and controller._light then
            pcall(function()
                controller._light.Active = false
                controller._light.BackgroundTransparency = 1
            end)
        end

        if controller and type(controller._clearEffects) == "function" then
            pcall(controller._clearEffects, controller)
        end

        pcall(function()
            local playerGui = LocalPlayer:FindFirstChildOfClass("PlayerGui")
            local deathGui = playerGui
                and playerGui:FindFirstChild("DeathUI")
            if deathGui and deathGui:IsA("ScreenGui") then
                deathGui.Enabled = false
            end
        end)

        pcall(function()
            local camera = workspace.CurrentCamera
            local effect = camera
                and camera:FindFirstChild("DeathColorCorrection")
            if effect then
                effect:Destroy()
            end
        end)

        local heartGui =
            runtime.instantRespawnDeathGui

        if heartGui
            and heartGui.Parent
        then
            pcall(function()
                if heartGui:IsA("ScreenGui") then
                    heartGui.Enabled =
                        false
                elseif heartGui:IsA("GuiObject") then
                    heartGui.Visible =
                        false
                end
            end)
        end
    end

    local function normalizeInstantRespawnUiText(value)
        return tostring(
            value
            or ""
        ):lower():gsub(
            "[^%a%d]",
            ""
        )
    end

    runtime.isRestartMyHeartText =
        function(instance)
            if not instance
                or not instance.Parent
            then
                return false
            end

            local nameKey =
                normalizeInstantRespawnUiText(
                    instance.Name
                )

            if nameKey:find(
                "restartmyheart",
                1,
                true
            ) then
                return true
            end

            if instance:IsA("TextLabel")
                or instance:IsA("TextButton")
            then
                local textKey =
                    normalizeInstantRespawnUiText(
                        instance.Text
                    )

                if textKey:find(
                    "restartmyheart",
                    1,
                    true
                ) then
                    return true
                end
            end

            return false
        end

    runtime.getInstantRespawnScreenGui =
        function(instance)
            local cursor =
                instance

            while cursor do
                if cursor:IsA("ScreenGui") then
                    return cursor
                end

                cursor =
                    cursor.Parent
            end

            return nil
        end

    runtime.hideRestartMyHeartScreen =
        function(gui)
            gui =
                gui
                or runtime.instantRespawnDeathGui

            if not gui
                or not gui.Parent
            then
                return
            end

            runtime.instantRespawnDeathGui =
                gui

            pcall(function()
                if gui:IsA("ScreenGui") then
                    gui.Enabled =
                        false
                elseif gui:IsA("GuiObject") then
                    gui.Visible =
                        false
                end
            end)
        end

    runtime.bindRestartMyHeartScreenGuard =
        function(gui)
            if not gui
                or not gui.Parent
            then
                return
            end

            runtime.instantRespawnDeathGui =
                gui

            runtime.instantRespawnDeathGuiBound =
                runtime.instantRespawnDeathGuiBound
                or setmetatable(
                    {},
                    {__mode = "k"}
                )

            if runtime.instantRespawnDeathGuiBound[
                gui
            ] then
                return
            end

            runtime.instantRespawnDeathGuiBound[
                gui
            ] =
                true

            local signal =
                gui:IsA("ScreenGui")
                and gui:GetPropertyChangedSignal(
                    "Enabled"
                )
                or (
                    gui:IsA("GuiObject")
                    and gui:GetPropertyChangedSignal(
                        "Visible"
                    )
                    or nil
                )

            if signal then
                local connection =
                    signal:Connect(function()
                        if Flags.misc_instant_respawn
                                ~= true
                        then
                            return
                        end

                        local shown =
                            gui:IsA("ScreenGui")
                            and gui.Enabled
                            or (
                                gui:IsA("GuiObject")
                                and gui.Visible
                                or false
                            )

                        if shown then
                            runtime.instantRespawnDeathScreenActive =
                                true
                            runtime.hideRestartMyHeartScreen(
                                gui
                            )

                            local now =
                                os.clock()

                            if now
                                - (
                                    runtime.instantRespawnScreenLastTrigger
                                    or 0
                                )
                                > 0.12
                            then
                                runtime.instantRespawnScreenLastTrigger =
                                    now
                                runtime.beginInstantRespawnRetry(
                                    "restart_my_heart_reopened"
                                )
                            end
                        end
                    end)

                runtime.instantRespawnDeathGuiConnections[
                    #runtime.instantRespawnDeathGuiConnections + 1
                ] =
                    connection
            end
        end

    runtime.noteRestartMyHeartScreen =
        function(instance, reason)
            if Flags.misc_instant_respawn
                    ~= true
                or not runtime.isRestartMyHeartText(
                    instance
                )
            then
                return false
            end

            local gui =
                runtime.getInstantRespawnScreenGui(
                    instance
                )

            if not gui then
                return false
            end

            runtime.instantRespawnDeathScreenActive =
                true
            runtime.instantRespawnDeathGui =
                gui

            runtime.bindRestartMyHeartScreenGuard(
                gui
            )
            runtime.hideRestartMyHeartScreen(
                gui
            )

            local now =
                os.clock()

            if now
                - (
                    runtime.instantRespawnScreenLastTrigger
                    or 0
                )
                > 0.12
            then
                runtime.instantRespawnScreenLastTrigger =
                    now
                task.defer(
                    runtime.beginInstantRespawnRetry,
                    reason
                        or "restart_my_heart"
                )
            end

            return true
        end

    runtime.inspectInstantRespawnGui =
        function(instance)
            if not instance
                or not instance.Parent
            then
                return
            end

            if runtime.noteRestartMyHeartScreen(
                instance,
                "restart_my_heart_ui"
            )
            then
                return
            end

            if instance:IsA("ScreenGui")
                or instance:IsA("Frame")
            then
                local ok,
                    descendants =
                    pcall(
                        instance.GetDescendants,
                        instance
                    )

                if ok
                    and type(descendants)
                        == "table"
                then
                    for _, descendant in ipairs(
                        descendants
                    ) do
                        if runtime.noteRestartMyHeartScreen(
                            descendant,
                            "restart_my_heart_subtree"
                        ) then
                            return
                        end
                    end
                end
            end
        end

    runtime.resolveInstantRespawnRemote = function()
        local controller = runtime.instantRespawnController
        local remote = controller and controller._spawnRemote

        if remote
            and typeof(remote) == "Instance"
            and remote:IsA("RemoteEvent")
            and remote.Parent ~= nil
        then
            return remote
        end

        local remotes = ReplicatedStorage:FindFirstChild("Remotes")
        remote = remotes and remotes:FindFirstChild("SpawnRequest")

        if remote and remote:IsA("RemoteEvent") then
            if controller then
                controller._spawnRemote = remote
            end
            return remote
        end

        return nil
    end

    runtime.resolveInstantRespawnController = function()
        local cached = runtime.instantRespawnController
        if type(cached) == "table" then
            return cached
        end

        local module
        pcall(function()
            local sharedStorage = ReplicatedStorage:FindFirstChild("Shared")
            local services =
                sharedStorage and sharedStorage:FindFirstChild("Services")
            local spawnService =
                services and services:FindFirstChild("SpawnService")
            local candidate =
                spawnService
                and spawnService:FindFirstChild("SpawnServiceClient")

            if candidate
                and candidate:IsA("ModuleScript")
                and candidate.Parent ~= nil
            then
                module = candidate
            end
        end)

        if not module and type(getloadedmodules) == "function" then
            pcall(function()
                for _, candidate in ipairs(getloadedmodules()) do
                    if typeof(candidate) == "Instance"
                        and candidate:IsA("ModuleScript")
                        and candidate.Parent ~= nil
                        and candidate.Name == "SpawnServiceClient"
                    then
                        local okDescendant, inGame = pcall(
                            candidate.IsDescendantOf,
                            candidate,
                            game
                        )
                        if okDescendant and inGame == true then
                            module = candidate
                            break
                        end
                    end
                end
            end)
        end

        if not module then
            return nil
        end

        local usable = false
        pcall(function()
            usable = module:IsA("ModuleScript")
                and module.Parent ~= nil
                and module:IsDescendantOf(game)
        end)
        if not usable then
            return nil
        end

        local okRequire, controller = pcall(require, module)
        if not okRequire or type(controller) ~= "table" then
            return nil
        end

        runtime.instantRespawnModule = module
        runtime.instantRespawnController = controller

        return controller
    end

    runtime.isInstantRespawnDead = function()
        if runtime.instantRespawnDeathScreenActive
            == true
        then
            return true
        end

        local controller = runtime.instantRespawnController

        if controller
            and type(controller._isLocalPlayerDead) == "function"
        then
            local okDead, dead =
                pcall(controller._isLocalPlayerDead, controller)
            if okDead then
                return dead == true
            end
        end

        local character = LocalPlayer.Character
        if not character or not character.Parent then
            return false
        end

        if character:GetAttribute("Dead") == true then
            return true
        end

        local humanoid = character:FindFirstChildOfClass("Humanoid")
        return humanoid ~= nil and humanoid.Health <= 0
    end

    runtime.fireInstantRespawnRequest = function(reason)
        if Flags.misc_instant_respawn ~= true then
            return false
        end

        if runtime.isInstantRespawnDead() ~= true then
            return false
        end

        local now = os.clock()
        if now - (runtime.instantRespawnLastAttempt or 0) < 0.08 then
            return false
        end

        local remote = runtime.resolveInstantRespawnRemote()
        if not remote then
            return false
        end

        runtime.instantRespawnLastAttempt = now
        shared.instantRespawnTransitionActive = true
        shared.instantRespawnBlurSuppressUntil = math.max(
            tonumber(shared.instantRespawnBlurSuppressUntil) or 0,
            now + 0.85
        )

        local controller = runtime.instantRespawnController
        if controller then
            controller._busy = false
            controller._clicks = 7
            controller._dead = true
        end

        runtime.hideInstantRespawnPresentation(controller)

        local okFire = pcall(remote.FireServer, remote)

        task.defer(function()
            if Flags.misc_instant_respawn == true then
                runtime.clearInstantRespawnBlur()
            end
        end)

        debugLog("INSTANT_RESPAWN_REQUEST", {
            reason = reason or "",
            fired = okFire == true,
            character = LocalPlayer.Character
                and LocalPlayer.Character.Name
                or "",
        }, true)

        return okFire == true
    end

    runtime.beginInstantRespawnRetry = function(reason)
        runtime.instantRespawnRetrySerial =
            (runtime.instantRespawnRetrySerial or 0) + 1

        local serial = runtime.instantRespawnRetrySerial
        local startingCharacter = LocalPlayer.Character

        task.spawn(function()
            runtime.fireInstantRespawnRequest(reason)

            for _, delaySeconds in ipairs({
                0.18,
                0.34,
                0.62,
            }) do
                task.wait(delaySeconds)

                if Flags.misc_instant_respawn ~= true
                    or runtime.instantRespawnRetrySerial ~= serial
                    or LocalPlayer.Character ~= startingCharacter
                    or runtime.isInstantRespawnDead() ~= true
                then
                    return
                end

                runtime.fireInstantRespawnRequest("retry")
            end
        end)
    end

    runtime.installInstantRespawnHook = function()
        if runtime.instantRespawnHookInstalled == true then
            return true
        end

        local controller = runtime.resolveInstantRespawnController()
        if not controller then
            return false
        end

        local meta = getmetatable(controller)
        local canonicalStartDeath =
            meta and meta._startDeath
            or controller._startDeath

        if type(canonicalStartDeath) ~= "function" then
            return false
        end

        runtime.instantRespawnOriginalStartDeath =
            canonicalStartDeath

        rawset(controller, "_startDeath", nil)

        rawset(controller, "_startDeath", function(self, ...)
            if Flags.misc_instant_respawn == true
                and self == runtime.instantRespawnController
            then
                self._dead = true
                runtime.hideInstantRespawnPresentation(self)
                runtime.beginInstantRespawnRetry("start_death")
                return
            end

            return runtime.instantRespawnOriginalStartDeath(
                self,
                ...
            )
        end)

        runtime.instantRespawnHookInstalled = true
        return true
    end

    runtime.removeInstantRespawnHook = function()
        local controller = runtime.instantRespawnController

        if controller and runtime.instantRespawnHookInstalled then
            rawset(controller, "_startDeath", nil)
        end

        runtime.instantRespawnHookInstalled = false
    end

    runtime.disconnectInstantRespawnSignals = function()
        for _, field in ipairs({
            "InstantRespawnCharacterAddedConnection",
            "InstantRespawnCharacterDeadConnection",
            "InstantRespawnHumanoidDiedConnection",
            "InstantRespawnGuiAddedConnection",
        }) do
            local connection = runtime[field]
            if connection then
                pcall(function()
                    connection:Disconnect()
                end)
                runtime[field] = nil
            end
        end

        if runtime.instantRespawnDeathGuiConnections then
            for _, connection in ipairs(
                runtime.instantRespawnDeathGuiConnections
            ) do
                pcall(function()
                    connection:Disconnect()
                end)
            end

            table.clear(
                runtime.instantRespawnDeathGuiConnections
            )
        end

        if runtime.instantRespawnDeathGuiBound then
            table.clear(
                runtime.instantRespawnDeathGuiBound
            )
        end

        runtime.instantRespawnBoundCharacter = nil
        runtime.instantRespawnDeathScreenActive = false
        runtime.instantRespawnDeathGui = nil
    end

    runtime.bindInstantRespawnCharacter = function(character)
        if runtime.InstantRespawnCharacterDeadConnection then
            pcall(function()
                runtime.InstantRespawnCharacterDeadConnection:Disconnect()
            end)
            runtime.InstantRespawnCharacterDeadConnection = nil
        end

        if runtime.InstantRespawnHumanoidDiedConnection then
            pcall(function()
                runtime.InstantRespawnHumanoidDiedConnection:Disconnect()
            end)
            runtime.InstantRespawnHumanoidDiedConnection = nil
        end

        runtime.instantRespawnBoundCharacter = character

        if not character or not character.Parent then
            return
        end

        runtime.InstantRespawnCharacterDeadConnection =
            character:GetAttributeChangedSignal("Dead"):Connect(function()
                if Flags.misc_instant_respawn == true
                    and character:GetAttribute("Dead") == true
                then
                    runtime.beginInstantRespawnRetry("dead_attribute")
                end
            end)

        local humanoid = character:FindFirstChildOfClass("Humanoid")
        if humanoid then
            runtime.InstantRespawnHumanoidDiedConnection =
                humanoid.Died:Connect(function()
                    if Flags.misc_instant_respawn == true then
                        task.defer(function()
                            if Flags.misc_instant_respawn == true then
                                runtime.beginInstantRespawnRetry(
                                    "humanoid_died"
                                )
                            end
                        end)
                    end
                end)
        end

        if character:GetAttribute("Dead") == true then
            task.defer(runtime.beginInstantRespawnRetry, "already_dead")
        end
    end

    runtime.bindInstantRespawnSignals = function()
        runtime.disconnectInstantRespawnSignals()

        runtime.InstantRespawnCharacterAddedConnection =
            LocalPlayer.CharacterAdded:Connect(function(character)
                runtime.instantRespawnRetrySerial =
                    (runtime.instantRespawnRetrySerial or 0) + 1
                runtime.instantRespawnLastAttempt = 0
                runtime.instantRespawnDeathScreenActive =
                    false

                local wasInstantRespawnTransition =
                    shared.instantRespawnTransitionActive == true

                local controller = runtime.instantRespawnController
                if controller then
                    controller._dead = false
                    controller._busy = false
                    controller._clicks = 0
                    controller._respawnInFlight = false
                end

                runtime.hideInstantRespawnPresentation(controller)

                if wasInstantRespawnTransition then
                    shared.instantRespawnBlurSuppressUntil = math.max(
                        tonumber(shared.instantRespawnBlurSuppressUntil) or 0,
                        os.clock() + 1.65
                    )

                    for _, delaySeconds in ipairs({
                        0,
                        0.05,
                        0.15,
                        0.35,
                        0.70,
                        1.10,
                        1.50,
                    }) do
                        task.delay(delaySeconds, function()
                            if Flags.misc_instant_respawn == true
                                and LocalPlayer.Character == character
                                and shared.instantRespawnTransitionActive == true
                            then
                                local deadAgain = character:GetAttribute("Dead") == true
                                local downedAgain = character:GetAttribute("Downed") == true
                                if deadAgain or downedAgain then
                                    shared.instantRespawnTransitionActive = false
                                    shared.instantRespawnBlurSuppressUntil = 0
                                    return
                                end
                                runtime.clearInstantRespawnBlur()
                            end
                        end)
                    end

                    task.delay(1.68, function()
                        if LocalPlayer.Character == character then
                            shared.instantRespawnTransitionActive = false
                            shared.instantRespawnBlurSuppressUntil = 0
                        end
                    end)
                end

                if Flags.misc_instant_respawn == true then
                    runtime.bindInstantRespawnCharacter(character)
                end
            end)

        local playerGui =
            LocalPlayer:FindFirstChildOfClass(
                "PlayerGui"
            )

        if playerGui then
            local ok,
                descendants =
                pcall(
                    playerGui.GetDescendants,
                    playerGui
                )

            if ok
                and type(descendants)
                    == "table"
            then
                for _, descendant in ipairs(
                    descendants
                ) do
                    if runtime.noteRestartMyHeartScreen(
                        descendant,
                        "restart_my_heart_already_open"
                    ) then
                        break
                    end
                end
            end

            runtime.InstantRespawnGuiAddedConnection =
                playerGui.DescendantAdded:Connect(
                    function(instance)
                        runtime.inspectInstantRespawnGui(
                            instance
                        )

                        task.defer(function()
                            if Flags.misc_instant_respawn == true
                                and instance
                                and instance.Parent
                            then
                                runtime.inspectInstantRespawnGui(
                                    instance
                                )
                            end
                        end)

                        task.delay(
                            0.08,
                            function()
                                if Flags.misc_instant_respawn == true
                                    and instance
                                    and instance.Parent
                                then
                                    runtime.inspectInstantRespawnGui(
                                        instance
                                    )
                                end
                            end
                        )
                    end
                )
        end

        runtime.bindInstantRespawnCharacter(
            LocalPlayer.Character
        )
    end

    runtime.refreshInstantRespawn = function(enabled)
        runtime.instantRespawnRetrySerial =
            (runtime.instantRespawnRetrySerial or 0) + 1

        if enabled == true then
            runtime.bindInstantRespawnSignals()

            task.defer(function()
                if Flags.misc_instant_respawn ~= true then
                    return
                end

                runtime.resolveInstantRespawnController()
                runtime.installInstantRespawnHook()

                if runtime.isInstantRespawnDead() == true then
                    runtime.beginInstantRespawnRetry("enabled_while_dead")
                end
            end)
        else
            shared.instantRespawnTransitionActive = false
            shared.instantRespawnBlurSuppressUntil = 0
            runtime.hideInstantRespawnPresentation(
                runtime.instantRespawnController
            )
            runtime.disconnectInstantRespawnSignals()
            runtime.removeInstantRespawnHook()

            local controller = runtime.instantRespawnController
            if controller then
                controller._dead = false
                controller._busy = false
                controller._clicks = 0
                controller._respawnInFlight = false
            end
        end
    end

    runtime.autoHealVoidY = 1000000
    runtime.autoHealRetryDelay = 4.0
    runtime.autoHealLastAttempt = 0
    runtime.autoHealSerial = 0
    runtime.autoHealInFlight = false
    runtime.autoHealBoundCharacter = nil
    runtime.autoHealBoundHumanoid = nil

    -- Return-position state is separate from autoHealSerial because
    -- bindAutoHealCharacter advances that serial as soon as CharacterAdded fires.
    runtime.autoHealReturnToken = tonumber(runtime.autoHealReturnToken) or 0
    runtime.autoHealReturnCFrame = nil
    runtime.autoHealReturnPending = false
    runtime.autoHealReturnSourceCharacter = nil
    runtime.autoHealReturnNeedsGroundRecovery = false

    runtime.autoHealOverlayDrawingNew = function(className, properties)
        local library = rawget(getgenv(), "Drawing")
        if library == nil then
            pcall(function()
                library = Drawing
            end)
        end

        if not library or type(library.new) ~= "function" then
            return nil
        end

        local ok, object = pcall(library.new, className)
        if not ok or not object then
            return nil
        end

        for property, value in pairs(properties or {}) do
            pcall(function()
                object[property] = value
            end)
        end

        return object
    end

    runtime.autoHealOverlayDestroyDrawing = function(object)
        if object then
            pcall(function()
                object:Destroy()
            end)
        end
    end

    runtime.autoHealPrivacyImageData =
        type(runtime.autoHealPrivacyImageData) == "string"
            and runtime.autoHealPrivacyImageData
            or base64_decode([[

            ]])
    runtime.autoHealPrivacyBackdrop = nil
    runtime.autoHealPrivacyImage = nil
    runtime.autoHealPrivacyVisible = false

    runtime.destroyAutoHealPrivacyOverlay = function()
        runtime.autoHealPrivacyVisible = false

        if runtime.autoHealPrivacyBackdrop then
            pcall(function()
                runtime.autoHealOverlayDestroyDrawing(
                    runtime.autoHealPrivacyBackdrop
                )
            end)
            runtime.autoHealPrivacyBackdrop = nil
        end

        if runtime.autoHealPrivacyImage then
            pcall(function()
                runtime.autoHealOverlayDestroyDrawing(
                    runtime.autoHealPrivacyImage
                )
            end)
            runtime.autoHealPrivacyImage = nil
        end
    end

    runtime.createAutoHealPrivacyOverlay = function()
        if runtime.autoHealPrivacyBackdrop
            and runtime.autoHealPrivacyImage
        then
            return true
        end

        if type(runtime.autoHealPrivacyImageData) ~= "string"
            or runtime.autoHealPrivacyImageData == ""
        then
            return false
        end

        if not runtime.autoHealPrivacyBackdrop then
            runtime.autoHealPrivacyBackdrop =
                runtime.autoHealOverlayDrawingNew("Square", {
                Filled = true,
                Color = Color3.new(0, 0, 0),
                Transparency = 1,
                Visible = false,
                ZIndex = 1000000,
                Position = Vector2.new(0, 0),
                Size = Vector2.new(1, 1),
            })
        end

        if not runtime.autoHealPrivacyImage then
            runtime.autoHealPrivacyImage =
                runtime.autoHealOverlayDrawingNew("Image", {
                Data = runtime.autoHealPrivacyImageData,
                Color = Color3.new(1, 1, 1),
                Transparency = 1,
                Visible = false,
                ZIndex = 1000001,
                Position = Vector2.new(0, 0),
                Size = Vector2.new(1, 1),
            })
        end

        if not runtime.autoHealPrivacyBackdrop
            or not runtime.autoHealPrivacyImage
        then
            runtime.destroyAutoHealPrivacyOverlay()
            return false
        end

        return true
    end

    runtime.updateAutoHealPrivacyOverlay = function()
        if runtime.autoHealPrivacyVisible ~= true then
            return false
        end

        if runtime.createAutoHealPrivacyOverlay() ~= true then
            return false
        end

        local camera = Workspace.CurrentCamera
        if not camera then
            return false
        end

        local viewport = camera.ViewportSize
        local backdrop = runtime.autoHealPrivacyBackdrop
        local image = runtime.autoHealPrivacyImage

        if not backdrop or not image then
            return false
        end

        local width = math.floor(math.max(360, viewport.X * 0.34))
        local height = math.floor(width * (384 / 960))
        local maxHeight = math.floor(viewport.Y * 0.28)

        if height > maxHeight then
            height = maxHeight
            width = math.floor(height * (960 / 384))
        end

        local size = Vector2.new(width, height)

        pcall(function()
            backdrop.Position = Vector2.new(0, 0)
            backdrop.Size = viewport
            backdrop.Visible = true
        end)

        pcall(function()
            image.Size = size
            image.Position = viewport * 0.5 - size * 0.5
            image.Visible = true
        end)

        return true
    end

    runtime.setAutoHealPrivacyOverlayVisible = function(visible)
        visible = visible == true
        runtime.autoHealPrivacyVisible = visible

        if visible ~= true then
            if runtime.autoHealPrivacyBackdrop then
                pcall(function()
                    runtime.autoHealPrivacyBackdrop.Visible = false
                end)
            end

            if runtime.autoHealPrivacyImage then
                pcall(function()
                    runtime.autoHealPrivacyImage.Visible = false
                end)
            end

            return false
        end

        return runtime.updateAutoHealPrivacyOverlay()
    end

    runtime.autoHealRestoreCombatMode = false
    runtime.autoHealCombatToggleKey =
        runtime.autoHealCombatToggleKey
        or Enum.KeyCode.T
    runtime.autoHealLastKeyboardInput = nil
    runtime.autoHealLastKeyboardInputAt = 0

    runtime.sendAutoHealCombatKey = function(
        keyCode,
        method
    )
        if typeof(keyCode) ~= "EnumItem"
            or keyCode.EnumType ~= Enum.KeyCode
            or keyCode == Enum.KeyCode.Unknown
        then
            return false
        end

        method =
            tostring(method or "virtual")

        if method == "virtual" then
            local vim
            pcall(function()
                vim =
                    game:GetService(
                        "VirtualInputManager"
                    )
            end)

            if vim
                and type(vim.SendKeyEvent)
                    == "function"
            then
                local okDown =
                    pcall(
                        vim.SendKeyEvent,
                        vim,
                        true,
                        keyCode,
                        false,
                        game
                    )

                task.wait(0.035)

                local okUp =
                    pcall(
                        vim.SendKeyEvent,
                        vim,
                        false,
                        keyCode,
                        false,
                        game
                    )

                return okDown and okUp
            end

            return false
        end

        local virtualKey =
            keyCode == Enum.KeyCode.T and 0x54
            or keyCode == Enum.KeyCode.R and 0x52
            or keyCode == Enum.KeyCode.F and 0x46
            or keyCode == Enum.KeyCode.G and 0x47
            or nil

        if virtualKey
            and type(keypress) == "function"
            and type(keyrelease) == "function"
        then
            local okDown =
                pcall(
                    keypress,
                    virtualKey
                )

            task.wait(0.035)

            local okUp =
                pcall(
                    keyrelease,
                    virtualKey
                )

            return okDown and okUp
        end

        return false
    end

    runtime.bindAutoHealCombatObserver = function(character)
        if runtime.AutoHealCombatEquipConnection then
            pcall(function()
                runtime.AutoHealCombatEquipConnection:Disconnect()
            end)
            runtime.AutoHealCombatEquipConnection = nil
        end

        if not character or not character.Parent then
            return
        end

        runtime.AutoHealCombatEquipConnection =
            character:GetAttributeChangedSignal("Equip")
                :Connect(function()
                    -- Learn the user's actual combat-mode key whenever possible.
                    -- The keyboard input arrives immediately before Equip changes.
                    local now = os.clock()
                    local key =
                        runtime.autoHealLastKeyboardInput
                    local age =
                        now
                        - (
                            tonumber(
                                runtime.autoHealLastKeyboardInputAt
                            ) or 0
                        )

                    if character:GetAttribute("Equip") == true
                        and typeof(key) == "EnumItem"
                        and key.EnumType == Enum.KeyCode
                        and key ~= Enum.KeyCode.Unknown
                        and age >= 0
                        and age <= 0.75
                    then
                        runtime.autoHealCombatToggleKey = key
                    end
                end)
    end

    runtime.ensureAutoHealCombatObserver = function()
        if not runtime.AutoHealCombatInputConnection then
            runtime.AutoHealCombatInputConnection =
                UserInputService.InputBegan:Connect(
                    function(input, processed)
                        if processed == true
                            or not input
                            or input.UserInputType
                                ~= Enum.UserInputType.Keyboard
                        then
                            return
                        end

                        local key = input.KeyCode
                        if key
                            and key ~= Enum.KeyCode.Unknown
                        then
                            runtime.autoHealLastKeyboardInput = key
                            runtime.autoHealLastKeyboardInputAt =
                                os.clock()
                        end
                    end
                )
        end

        local character = LocalPlayer.Character

        if character
            and character.Parent
        then
            runtime.bindAutoHealCombatObserver(
                character
            )
        end
    end

    runtime.restoreAutoHealCombatMode = function(character)
        if runtime.autoHealRestoreCombatMode ~= true then
            return true
        end

        if not character
            or not character.Parent
        then
            return false
        end

        local deadline =
            os.clock() + 4.75
        local humanoid

        local function isReady()
            if LocalPlayer.Character ~= character
                or not character.Parent
            then
                return false
            end

            humanoid =
                character
                    :FindFirstChildOfClass(
                        "Humanoid"
                    )

            if not humanoid
                or not humanoid.Parent
                or humanoid.Health <= 0
                or LocalPlayer:GetAttribute(
                    "Dead"
                ) == true
                or character:GetAttribute(
                    "Dead"
                ) == true
                or character:GetAttribute(
                    "Downed"
                ) == true
                or character:GetAttribute(
                    "Ragdoll"
                ) == true
                or character:GetAttribute(
                    "Stunned"
                ) == true
                or character:GetAttribute(
                    "RpCombatLocked"
                ) == true
                or character:GetAttribute(
                    "Greenzone"
                ) == true
            then
                return false
            end

            -- Spawn input/controllers are not consistently ready on the exact
            -- CharacterAdded frame. PlayerData is a reliable local readiness
            -- signal in this game.
            if not character:FindFirstChild(
                "PlayerData"
            ) then
                return false
            end

            return true
        end

        while os.clock() < deadline
            and not isReady()
        do
            task.wait(0.025)
        end

        if not isReady() then
            runtime.autoHealRestoreCombatMode =
                false
            return false
        end

        if character:GetAttribute("Equip")
            == true
        then
            runtime.autoHealRestoreCombatMode =
                false
            return true
        end

        local key =
            runtime.autoHealCombatToggleKey

        if typeof(key) ~= "EnumItem"
            or key.EnumType ~= Enum.KeyCode
            or key == Enum.KeyCode.Unknown
        then
            key = Enum.KeyCode.T
        end

        -- Gakuran's default combat-stance key is T. If we have not observed a
        -- confirmed custom key in this session, always use T rather than a
        -- random recently pressed key.
        if key ~= Enum.KeyCode.T
            and (
                tonumber(
                    runtime.autoHealLastKeyboardInputAt
                ) or 0
            ) <= 0
        then
            key = Enum.KeyCode.T
        end

        local attempt = 0

        while os.clock() < deadline do
            if not isReady() then
                task.wait(0.035)
                continue
            end

            if character:GetAttribute(
                "Equip"
            ) == true
            then
                runtime.autoHealRestoreCombatMode =
                    false

                debugLog(
                    "AUTO_HEAL_COMBAT_RESTORE",
                    {
                        restored = true,
                        key = key.Name,
                        attempts = attempt,
                    },
                    true
                )

                return true
            end

            attempt += 1

            -- First use Roblox's own input injector. Check the Equip attribute
            -- before trying the executor path so a successful press can never
            -- be followed by a second press that toggles combat back off.
            runtime.sendAutoHealCombatKey(
                key,
                "virtual"
            )

            local virtualDeadline =
                os.clock() + 0.22

            while os.clock()
                < virtualDeadline
            do
                if character:GetAttribute(
                    "Equip"
                ) == true
                then
                    runtime.autoHealRestoreCombatMode =
                        false

                    debugLog(
                        "AUTO_HEAL_COMBAT_RESTORE",
                        {
                            restored = true,
                            method = "virtual",
                            key = key.Name,
                            attempts = attempt,
                        },
                        true
                    )

                    return true
                end

                task.wait(0.015)
            end

            runtime.sendAutoHealCombatKey(
                key,
                "executor"
            )

            local executorDeadline =
                os.clock() + 0.24

            while os.clock()
                < executorDeadline
            do
                if character:GetAttribute(
                    "Equip"
                ) == true
                then
                    runtime.autoHealRestoreCombatMode =
                        false

                    debugLog(
                        "AUTO_HEAL_COMBAT_RESTORE",
                        {
                            restored = true,
                            method = "executor",
                            key = key.Name,
                            attempts = attempt,
                        },
                        true
                    )

                    return true
                end

                task.wait(0.015)
            end

            task.wait(0.08)
        end

        debugLog(
            "AUTO_HEAL_COMBAT_RESTORE",
            {
                restored = false,
                key = key.Name,
                attempts = attempt,
                equip =
                    character:GetAttribute(
                        "Equip"
                    ) == true,
                greenzone =
                    character:GetAttribute(
                        "Greenzone"
                    ) == true,
                locked =
                    character:GetAttribute(
                        "RpCombatLocked"
                    ) == true,
            },
            true
        )

        runtime.autoHealRestoreCombatMode =
            false

        return character:GetAttribute(
            "Equip"
        ) == true
    end

    runtime.resolveAutoHealReturnCFrame = function(
        character,
        humanoid,
        root,
        savedCFrame
    )
        if typeof(savedCFrame) ~= "CFrame" then
            return nil
        end

        if runtime.autoHealReturnNeedsGroundRecovery ~= true then
            return savedCFrame
        end

        local savedPosition = savedCFrame.Position
        local look = savedCFrame.LookVector
        local flatLook = Vector3.new(
            look.X,
            0,
            look.Z
        )

        if flatLook.Magnitude < 0.01 then
            local currentLook =
                root
                and root.CFrame.LookVector
                or Vector3.new(0, 0, -1)

            flatLook = Vector3.new(
                currentLook.X,
                0,
                currentLook.Z
            )
        end

        if flatLook.Magnitude < 0.01 then
            flatLook = Vector3.new(0, 0, -1)
        else
            flatLook = flatLook.Unit
        end

        local params = RaycastParams.new()
        params.FilterType =
            Enum.RaycastFilterType.Exclude
        params.IgnoreWater = false
        params.FilterDescendantsInstances = {
            character,
        }

        -- The saved root can be partially below the map while Downed/Ragdoll is
        -- active. Raycast vertically through that X/Z and rebuild a standing
        -- root position from the actual floor instead of restoring the buried
        -- ragdoll CFrame.
        local origin =
            savedPosition
            + Vector3.new(0, 18, 0)
        local result =
            Workspace:Raycast(
                origin,
                Vector3.new(0, -90, 0),
                params
            )

        local safePosition

        if result then
            local hipHeight =
                tonumber(humanoid and humanoid.HipHeight)
                or 2
            local rootHalfHeight =
                (
                    root
                    and root.Size
                    and tonumber(root.Size.Y)
                    or 2
                ) * 0.5

            -- Extra clearance avoids immediately intersecting the floor while
            -- the replacement rig is still transitioning out of GettingUp.
            local standClearance =
                math.max(
                    2.75,
                    hipHeight
                        + rootHalfHeight
                        + 0.65
                )

            safePosition = Vector3.new(
                savedPosition.X,
                result.Position.Y
                    + standClearance,
                savedPosition.Z
            )
        else
            -- Conservative fallback if the map uses non-queryable floor parts.
            safePosition =
                savedPosition
                + Vector3.new(0, 4.5, 0)
        end

        return CFrame.lookAt(
            safePosition,
            safePosition + flatLook
        )
    end

    runtime.restoreAutoHealPosition = function(character)
        if runtime.autoHealReturnPending ~= true
            or typeof(runtime.autoHealReturnCFrame) ~= "CFrame"
            or not character
        then
            return false
        end

        local token = runtime.autoHealReturnToken
        local savedReturnCFrame =
            runtime.autoHealReturnCFrame

        task.spawn(function()
            local deadline = os.clock() + 8
            local humanoid
            local root

            -- Move back as soon as the replacement rig is usable. Do not wait
            -- for the rest of the spawn UI/controller pipeline.
            while os.clock() < deadline do
                if runtime.autoHealReturnPending ~= true
                    or runtime.autoHealReturnToken ~= token
                    or LocalPlayer.Character ~= character
                    or not character.Parent
                then
                    return
                end

                humanoid =
                    character:FindFirstChildOfClass("Humanoid")
                root =
                    character:FindFirstChild("HumanoidRootPart")
                    or character.PrimaryPart

                if humanoid
                    and humanoid.Parent
                    and humanoid.Health > 0
                    and root
                    and root.Parent
                then
                    break
                end

                task.wait(0.01)
            end

            if not humanoid
                or not root
                or not root.Parent
                or runtime.autoHealReturnPending ~= true
                or runtime.autoHealReturnToken ~= token
                or LocalPlayer.Character ~= character
            then
                return
            end

            local returnCFrame =
                runtime.resolveAutoHealReturnCFrame(
                    character,
                    humanoid,
                    root,
                    savedReturnCFrame
                )
                or savedReturnCFrame

            local function forceStanding()
                if not humanoid
                    or not humanoid.Parent
                then
                    return
                end

                pcall(function()
                    humanoid.Sit = false
                    humanoid.PlatformStand = false
                    humanoid.AutoRotate = true
                end)

                pcall(
                    humanoid.ChangeState,
                    humanoid,
                    Enum.HumanoidStateType.GettingUp
                )
            end

            local function restoreOnce()
                if runtime.autoHealReturnPending ~= true
                    or runtime.autoHealReturnToken ~= token
                    or LocalPlayer.Character ~= character
                    or not character.Parent
                    or not root.Parent
                then
                    return false
                end

                forceStanding()

                pcall(function()
                    root.AssemblyLinearVelocity = Vector3.zero
                    root.AssemblyAngularVelocity = Vector3.zero
                end)

                local moved = pcall(function()
                    character:PivotTo(returnCFrame)
                end)

                if not moved then
                    moved = pcall(function()
                        root.CFrame = returnCFrame
                    end)
                end

                forceStanding()
                return moved == true
            end

            -- Restore immediately, then briefly keep ownership while the game's
            -- spawn/seat placement code finishes writing to the new character.
            restoreOnce()

            for _, delaySeconds in ipairs({
                0.03,
                0.06,
                0.10,
                0.16,
                0.24,
            }) do
                task.wait(delaySeconds)

                if runtime.autoHealReturnPending ~= true
                    or runtime.autoHealReturnToken ~= token
                    or LocalPlayer.Character ~= character
                then
                    return
                end

                restoreOnce()
            end

            forceStanding()

            task.defer(function()
                if humanoid
                    and humanoid.Parent
                    and humanoid.Sit == true
                then
                    pcall(function()
                        humanoid.Sit = false
                        humanoid.PlatformStand = false
                        humanoid:ChangeState(
                            Enum.HumanoidStateType.GettingUp
                        )
                    end)
                end
            end)

            if runtime.autoHealReturnToken == token then
                runtime.autoHealReturnPending = false
                runtime.autoHealReturnCFrame = nil
                runtime.autoHealReturnSourceCharacter = nil
                runtime.autoHealReturnNeedsGroundRecovery = false

                runtime.bindAutoHealCombatObserver(
                    character
                )

                if runtime.autoHealRestoreCombatMode == true then
                    runtime.restoreAutoHealCombatMode(
                        character
                    )
                end

                runtime.setAutoHealPrivacyOverlayVisible(false)

                task.defer(function()
                    if Flags.misc_auto_heal == true
                        and LocalPlayer.Character == character
                        and type(runtime.checkAutoHeal) == "function"
                    then
                        runtime.checkAutoHeal(
                            "post_restore"
                        )
                    end
                end)
            end
        end)

        return true
    end

    runtime.disconnectAutoHealSignals = function()
        for _, field in ipairs({
            "AutoHealCharacterAddedConnection",
            "AutoHealHealthConnection",
            "AutoHealHeartbeatConnection",
            "AutoHealCombatInputConnection",
            "AutoHealCombatEquipConnection",
        }) do
            local connection = runtime[field]
            if connection then
                pcall(function()
                    connection:Disconnect()
                end)
                runtime[field] = nil
            end
        end

        runtime.autoHealSerial =
            (runtime.autoHealSerial or 0) + 1
        runtime.autoHealInFlight = false
        runtime.autoHealBoundCharacter = nil
        runtime.autoHealBoundHumanoid = nil
        runtime.autoHealReturnPending = false
        runtime.autoHealReturnCFrame = nil
        runtime.autoHealReturnSourceCharacter = nil
        runtime.autoHealReturnNeedsGroundRecovery = false
        runtime.autoHealRestoreCombatMode = false
        runtime.destroyAutoHealPrivacyOverlay()
    end

    runtime.getAutoHealThreshold = function()
        return math.clamp(
            tonumber(Flags.misc_auto_heal_below) or 20,
            10,
            50
        )
    end

    runtime.triggerAutoHeal = function(reason)
        if Flags.misc_auto_heal ~= true then
            return false
        end

        local character = LocalPlayer.Character
        if not character or not character.Parent then
            return false
        end

        local humanoid =
            character:FindFirstChildOfClass("Humanoid")
        local root =
            character:FindFirstChild("HumanoidRootPart")
            or character.PrimaryPart

        if not humanoid
            or not root
            or humanoid.Health <= 0
        then
            return false
        end

        if runtime.autoHealInFlight == true
            and runtime.autoHealBoundCharacter == character
        then
            return false
        end

        local now = os.clock()
        if now - (runtime.autoHealLastAttempt or 0) < 0.45 then
            return false
        end

        runtime.autoHealLastAttempt = now
        runtime.autoHealInFlight = true
        runtime.autoHealBoundCharacter = character
        runtime.autoHealBoundHumanoid = humanoid
        runtime.autoHealSerial =
            (runtime.autoHealSerial or 0) + 1

        local serial = runtime.autoHealSerial

        -- Capture once per heal attempt before the original R2 void teleport.
        runtime.autoHealReturnToken =
            (runtime.autoHealReturnToken or 0) + 1
        runtime.autoHealReturnCFrame = root.CFrame
        runtime.autoHealReturnPending = true
        runtime.autoHealReturnSourceCharacter = character

        local humanoidState =
            humanoid:GetState()

        runtime.autoHealReturnNeedsGroundRecovery =
            character:GetAttribute("Downed") == true
            or character:GetAttribute("Ragdoll") == true
            or humanoid.PlatformStand == true
            or humanoidState
                == Enum.HumanoidStateType.Ragdoll
            or humanoidState
                == Enum.HumanoidStateType.FallingDown
            or humanoidState
                == Enum.HumanoidStateType.Physics

        runtime.autoHealRestoreCombatMode =
            character:GetAttribute("Equip") == true

        runtime.setAutoHealPrivacyOverlayVisible(true)

        local startPosition = root.Position
        local startRotation = root.CFrame.Rotation

        local function moveToHealVoid(y)
            if Flags.misc_auto_heal ~= true
                or runtime.autoHealSerial ~= serial
                or LocalPlayer.Character ~= character
                or not character.Parent
                or not root.Parent
            then
                return false
            end

            pcall(function()
                root.AssemblyLinearVelocity = Vector3.zero
                root.AssemblyAngularVelocity = Vector3.zero
            end)

            local target =
                CFrame.new(
                    startPosition.X,
                    tonumber(y) or runtime.autoHealVoidY,
                    startPosition.Z
                )
                * startRotation

            local moved = pcall(function()
                character:PivotTo(target)
            end)

            if not moved then
                moved = pcall(function()
                    root.CFrame = target
                end)
            end

            return moved == true
        end

        local moved =
            moveToHealVoid(runtime.autoHealVoidY)

        if moved ~= true then
            runtime.autoHealInFlight = false
            runtime.autoHealReturnPending = false
            runtime.autoHealReturnCFrame = nil
            runtime.autoHealReturnSourceCharacter = nil
            runtime.autoHealReturnNeedsGroundRecovery = false
            runtime.autoHealRestoreCombatMode = false
            runtime.setAutoHealPrivacyOverlayVisible(false)
            return false
        end

        -- A second pulse keeps the character inside the game's upper void
        -- even if movement replication/controller code nudges the first teleport.
        task.delay(0.12, function()
            if runtime.autoHealInFlight == true
                and runtime.autoHealSerial == serial
                and LocalPlayer.Character == character
            then
                moveToHealVoid(
                    runtime.autoHealVoidY + 25000
                )
            end
        end)

        -- CharacterAdded normally clears the in-flight state after the void
        -- respawns us. If the game does not respawn for any reason, unlock and
        -- allow another threshold check instead of permanently wedging Auto Heal.
        task.delay(runtime.autoHealRetryDelay, function()
            if runtime.autoHealSerial ~= serial
                or LocalPlayer.Character ~= character
            then
                return
            end

            runtime.autoHealInFlight = false

            if runtime.autoHealReturnPending == true
                and runtime.autoHealReturnSourceCharacter == character
                and typeof(runtime.autoHealReturnCFrame) == "CFrame"
                and root
                and root.Parent
                and character.Parent
            then
                pcall(function()
                    root.AssemblyLinearVelocity = Vector3.zero
                    root.AssemblyAngularVelocity = Vector3.zero

                    local retryCFrame =
                        runtime.resolveAutoHealReturnCFrame(
                            character,
                            humanoid,
                            root,
                            runtime.autoHealReturnCFrame
                        )
                        or runtime.autoHealReturnCFrame

                    character:PivotTo(
                        retryCFrame
                    )

                    humanoid.Sit = false
                    humanoid.PlatformStand = false
                    humanoid.AutoRotate = true
                    humanoid:ChangeState(
                        Enum.HumanoidStateType.GettingUp
                    )
                end)

                runtime.autoHealReturnPending = false
                runtime.autoHealReturnCFrame = nil
                runtime.autoHealReturnSourceCharacter = nil
                runtime.autoHealReturnNeedsGroundRecovery = false
                runtime.autoHealRestoreCombatMode = false
            end

            runtime.setAutoHealPrivacyOverlayVisible(false)

            if Flags.misc_auto_heal == true
                and type(runtime.checkAutoHeal) == "function"
            then
                runtime.checkAutoHeal("void_retry")
            end
        end)

        debugLog("AUTO_HEAL_VOID", {
            reason = reason or "",
            health = humanoid.Health,
            maxHealth = humanoid.MaxHealth,
            threshold = runtime.getAutoHealThreshold(),
            y = runtime.autoHealVoidY,
        }, true)

        return true
    end

    runtime.checkAutoHeal = function(reason)
        if Flags.misc_auto_heal ~= true
            or runtime.autoHealInFlight == true
        then
            return false
        end

        local character = LocalPlayer.Character
        if not character or not character.Parent then
            return false
        end

        -- During the short replacement-character return window, Gakuran can
        -- expose a partially initialized Humanoid health value. Do not treat
        -- that transient spawn value as fresh damage and start another heal.
        if runtime.autoHealReturnPending == true
            and runtime.autoHealReturnSourceCharacter ~= character
        then
            return false
        end

        local humanoid =
            character:FindFirstChildOfClass("Humanoid")

        if not humanoid
            or humanoid.Health <= 0
            or humanoid.MaxHealth <= 0
        then
            return false
        end

        local healthPercent =
            (humanoid.Health / humanoid.MaxHealth) * 100
        local threshold =
            runtime.getAutoHealThreshold()

        if healthPercent < threshold then
            return runtime.triggerAutoHeal(
                reason or "threshold"
            )
        end

        return false
    end

    runtime.bindAutoHealCharacter = function(character)
        if runtime.AutoHealHealthConnection then
            pcall(function()
                runtime.AutoHealHealthConnection:Disconnect()
            end)
            runtime.AutoHealHealthConnection = nil
        end

        runtime.autoHealSerial =
            (runtime.autoHealSerial or 0) + 1
        runtime.autoHealInFlight = false
        runtime.autoHealBoundCharacter = character
        runtime.autoHealBoundHumanoid = nil

        if Flags.misc_auto_heal ~= true
            or not character
            or not character.Parent
        then
            return
        end

        local bindSerial = runtime.autoHealSerial

        task.defer(function()
            if Flags.misc_auto_heal ~= true
                or runtime.autoHealSerial ~= bindSerial
                or LocalPlayer.Character ~= character
                or not character.Parent
            then
                return
            end

            local humanoid =
                character:FindFirstChildOfClass("Humanoid")

            if not humanoid then
                local ok, result = pcall(
                    character.WaitForChild,
                    character,
                    "Humanoid",
                    5
                )

                if ok
                    and result
                    and result:IsA("Humanoid")
                then
                    humanoid = result
                end
            end

            if not humanoid
                or runtime.autoHealSerial ~= bindSerial
                or LocalPlayer.Character ~= character
            then
                return
            end

            -- Re-resolve once immediately before connecting. Some Gakuran
            -- spawn paths replace the Humanoid during the same CharacterAdded
            -- window.
            local currentHumanoid =
                character:FindFirstChildOfClass("Humanoid")

            if currentHumanoid
                and currentHumanoid ~= humanoid
            then
                humanoid = currentHumanoid
            end

            runtime.autoHealBoundHumanoid = humanoid

            runtime.AutoHealHealthConnection =
                humanoid.HealthChanged:Connect(function()
                    if Flags.misc_auto_heal == true
                        and LocalPlayer.Character == character
                        and runtime.autoHealBoundHumanoid == humanoid
                    then
                        runtime.checkAutoHeal(
                            "health_changed"
                        )
                    end
                end)

            task.defer(function()
                if Flags.misc_auto_heal == true
                    and runtime.autoHealSerial == bindSerial
                    and LocalPlayer.Character == character
                then
                    runtime.checkAutoHeal(
                        "character_bound"
                    )
                end
            end)
        end)
    end

    runtime.ensureAutoHealHeartbeat = function()
        if runtime.AutoHealHeartbeatConnection then
            return
        end

        local lastCheck = 0

        runtime.AutoHealHeartbeatConnection =
            RunService.Heartbeat:Connect(function()
                if Flags.misc_auto_heal ~= true then
                    return
                end

                if runtime.autoHealPrivacyVisible == true then
                    runtime.updateAutoHealPrivacyOverlay()
                end

                local now = os.clock()
                if now - lastCheck < 0.025 then
                    return
                end
                lastCheck = now

                local character = LocalPlayer.Character
                if not character or not character.Parent then
                    return
                end

                local humanoid =
                    character:FindFirstChildOfClass("Humanoid")

                -- CharacterAdded is not enough for this game: the active
                -- Humanoid can be replaced/refreshed during spawn setup. If our
                -- binding points at an old Humanoid, rebuild it automatically.
                local needsRebind =
                    runtime.autoHealBoundCharacter ~= character
                    or (
                        runtime.autoHealBoundHumanoid ~= nil
                        and runtime.autoHealBoundHumanoid ~= humanoid
                    )
                    or (
                        runtime.autoHealBoundHumanoid ~= nil
                        and not runtime.autoHealBoundHumanoid.Parent
                    )

                if needsRebind then
                    runtime.bindAutoHealCharacter(character)
                    return
                end

                -- If a bind is already in progress for this character,
                -- autoHealBoundHumanoid is intentionally nil. Do not repeatedly
                -- restart it; the deferred binder will finish on its own.
                if runtime.autoHealBoundCharacter == character
                    and runtime.autoHealBoundHumanoid == nil
                then
                    return
                end

                if runtime.autoHealInFlight ~= true then
                    runtime.checkAutoHeal(
                        "heartbeat"
                    )
                end
            end)
    end

    runtime.refreshAutoHeal = function(enabled)
        enabled = enabled == true

        if enabled then
            runtime.ensureAutoHealHeartbeat()
            runtime.ensureAutoHealCombatObserver()

            if not runtime.AutoHealCharacterAddedConnection then
                runtime.AutoHealCharacterAddedConnection =
                    LocalPlayer.CharacterAdded:Connect(
                        function(character)
                            runtime.bindAutoHealCombatObserver(
                                character
                            )

                            runtime.restoreAutoHealPosition(
                                character
                            )

                            runtime.bindAutoHealCharacter(
                                character
                            )
                        end
                    )
            end

            if runtime.autoHealBoundCharacter
                ~= LocalPlayer.Character
                or runtime.autoHealBoundHumanoid == nil
            then
                runtime.bindAutoHealCharacter(
                    LocalPlayer.Character
                )
            else
                runtime.checkAutoHeal(
                    "refresh"
                )
            end
        else
            runtime.disconnectAutoHealSignals()
        end
    end

    runtime.refresh = function()
        shared.flags = Flags
        shared.runtime = runtime
        shared.localPlayer = LocalPlayer

        runtime.installInfiniteStamina()
        runtime.refreshNoSlowdown(
            Flags.misc_no_slowdown == true
        )
        runtime.installNoDelay()
        runtime.refreshBlur(
            Flags.misc_no_blur == true
        )

        if Flags.misc_instant_respawn == true then
            runtime.refreshInstantRespawn(true)
        else
            runtime.removeInstantRespawnHook()
        end

        runtime.refreshAutoHeal(
            Flags.misc_auto_heal == true
        )
    end

    runtime.shutdown = function()
        if runtime.NoDelayHeartbeatConnection then
            pcall(function()
                runtime.NoDelayHeartbeatConnection:Disconnect()
            end)
            runtime.NoDelayHeartbeatConnection = nil
        end

        if type(runtime.resetNoDelayTracks) == "function" then
            pcall(runtime.resetNoDelayTracks)
        end
        if type(runtime.disconnectNoSlowdownSignals) == "function" then
            pcall(runtime.disconnectNoSlowdownSignals)
        end
        if type(runtime.disconnectInstantRespawnSignals) == "function" then
            pcall(runtime.disconnectInstantRespawnSignals)
        end
        if type(runtime.disconnectAutoHealSignals) == "function" then
            pcall(runtime.disconnectAutoHealSignals)
        end

        if type(runtime.destroyAutoHealPrivacyOverlay) == "function" then
            pcall(runtime.destroyAutoHealPrivacyOverlay)
        end
        if type(runtime.removeInstantRespawnHook) == "function" then
            pcall(runtime.removeInstantRespawnHook)
        end

        if shared.runtime == runtime then
            shared.flags = {}
            shared.runtime = nil
        end
    end

    runtime.refreshNoSlowdown(
        Flags.misc_no_slowdown == true
    )
    runtime.installNoDelay()
    runtime.installInfiniteStamina()
    runtime.refreshBlur(
        Flags.misc_no_blur == true
    )

    if Flags.misc_instant_respawn == true then
        runtime.refreshInstantRespawn(true)
    end

    runtime.refreshAutoHeal(
        Flags.misc_auto_heal == true
    )



    runtime.refreshBlur(
        Flags.misc_no_blur == true
    )
end

local function canAutoPunishM1(character)
    if not character or not character.Parent then
        return false
    end
    if character:GetAttribute("Equip") ~= true then return false end
    if character:GetAttribute("SpecTimeSlowed") == true then return false end
    if character:GetAttribute("Downed") == true then return false end
    if character:GetAttribute("Ragdoll") == true then return false end
    if character:GetAttribute("Stunned") == true then return false end
    if character:GetAttribute("GrappleWinnerStun") == true then return false end
    if character:GetAttribute("Grappling") == true then return false end
    if character:GetAttribute("GuardBroken") == true then return false end
    if character:GetAttribute("CantAnything") == true
        and character:GetAttribute("CombatRecovery") ~= true then
        return false
    end
    if character:GetAttribute("CombatAttacking") == true then return false end
    if character:GetAttribute("M2") == true then return false end
    if character:GetAttribute("PendingM2") == true then return false end
    if character:GetAttribute("M1") == true then return false end
    if character:GetAttribute("M1Hold") == true then return false end
    if character:GetAttribute("PendingM1") == true then return false end
    if character:GetAttribute("M1Cooldown") == true then return false end
    if character:GetAttribute("ParryAttackLockout") == true then return false end
    if character:GetAttribute("BlockAttackLockout") == true then return false end
    if character:GetAttribute("Blocking") == true then return false end
    if character:GetAttribute("PerfectBlocking") == true then return false end
    if character:GetAttribute("Greenzone") == true then return false end
    if character:GetAttribute("RpCombatLocked") == true then return false end

    local humanoid = character:FindFirstChildOfClass("Humanoid")
    return humanoid ~= nil and humanoid.Health > 0
end

local function canAutoPunishM2(character)
    if not character or not character.Parent then
        return false
    end
    if character:GetAttribute("Equip") ~= true then return false end
    if character:GetAttribute("SpecTimeSlowed") == true then return false end
    if character:GetAttribute("Downed") == true then return false end
    if character:GetAttribute("Ragdoll") == true then return false end
    if character:GetAttribute("Stunned") == true then return false end
    if character:GetAttribute("GrappleWinnerStun") == true then return false end
    if character:GetAttribute("Grappling") == true then return false end
    if character:GetAttribute("GuardBroken") == true then return false end
    if character:GetAttribute("CantAnything") == true
        and character:GetAttribute("CombatRecovery") ~= true then
        return false
    end
    if character:GetAttribute("CombatAttacking") == true then return false end
    if character:GetAttribute("M2Cooldown") == true then return false end
    if character:GetAttribute("Blocking") == true then return false end
    if character:GetAttribute("PerfectBlocking") == true then return false end
    if character:GetAttribute("ParryAttackLockout") == true then return false end
    if character:GetAttribute("BlockAttackLockout") == true then return false end
    if character:GetAttribute("Greenzone") == true then return false end
    if character:GetAttribute("RpCombatLocked") == true then return false end

    local humanoid = character:FindFirstChildOfClass("Humanoid")
    return humanoid ~= nil and humanoid.Health > 0
end

local function isAutoPunishTargetAttacking(target)
    if not target or not target.Parent then
        return false
    end

    return target:GetAttribute("CombatAttacking") == true
        or target:GetAttribute("M1") == true
        or target:GetAttribute("M1Hold") == true
        or target:GetAttribute("PendingM1") == true
        or target:GetAttribute("M2") == true
        or target:GetAttribute("PendingM2") == true
end

local function getAutoPunishProjectedM1Distance(target)
    local character = getCharacter()
    local myRoot = getRoot(character)
    local targetRoot = getRoot(target)

    if not myRoot or not targetRoot then
        return math.huge, math.huge
    end

    local currentDelta = flat(targetRoot.Position - myRoot.Position)
    local currentDistance = currentDelta.Magnitude



    local horizon = tonumber(CombatConfig.M1.DefaultHitboxDelay) or 0.32

    pcall(function()
        local style = getStyle(character)
        local speed = getSpeedMultiplier(character)
        if os.clock() >= autoPunishComboResetAt then
            autoPunishComboMirror = 0
        end

        local combo = getAutoPunishComboMode() == "Fixed"
            and getAutoPunishFixedComboHit()
            or math.clamp((autoPunishComboMirror % 4) + 1, 1, 4)

        local delay = CombatConfig.GetScaledStyleM1HitboxDelay(
            style,
            combo,
            speed
        )

        if typeof(delay) == "number" then
            horizon = delay
        end
    end)

    horizon = math.clamp(horizon, 0.10, 0.55)
    local relativeVelocity =
        flat(targetRoot.AssemblyLinearVelocity)
        - flat(myRoot.AssemblyLinearVelocity)
    local projectedDistance =
        (currentDelta + relativeVelocity * horizon).Magnitude

    return currentDistance, projectedDistance
end

local function isAutoPunishM1Reachable(target)
    if not target or not target.Parent then
        return false, math.huge, math.huge
    end

    local reach = getAutoPunishM1Reach()
    local currentDistance, projectedDistance =
        getAutoPunishProjectedM1Distance(target)
    local effectiveReach = reach + 0.45

    return math.min(currentDistance, projectedDistance) <= effectiveReach,
        currentDistance,
        projectedDistance
end

AutoPunishRuntime.isParryM1LandingReady = function(target)
    if not target or not target.Parent then
        return false, math.huge, math.huge
    end

    local reach = getAutoPunishM1Reach()
    local currentDistance, projectedDistance =
        getAutoPunishProjectedM1Distance(target)

    local effectiveReach = reach + 1.10
    return currentDistance <= effectiveReach,
        currentDistance,
        projectedDistance
end

AutoPunishRuntime.getFacingDot = function(target)
    local character = getCharacter()
    local myRoot = getRoot(character)
    local targetRoot = getRoot(target)
    if not myRoot or not targetRoot then
        return -1
    end

    local direction = flat(targetRoot.Position - myRoot.Position)
    local look = flat(myRoot.CFrame.LookVector)
    if direction.Magnitude <= 0.05 then
        return 1
    end
    if look.Magnitude <= 0.05 then
        return -1
    end

    return math.clamp(look.Unit:Dot(direction.Unit), -1, 1)
end

AutoPunishRuntime.requestFaceLock = function(target, duration, reason)
    if Flags.ap_auto_face ~= true
        or not target
        or not target.Parent
        or (Menu._IsFriendlyCharacter and Menu._IsFriendlyCharacter(target))
    then
        return false
    end

    local runtime = Menu and Menu._AutoFaceRuntime
    local lockTarget = runtime and runtime.lockTarget
    if type(lockTarget) ~= "function" then
        return false
    end

    local ok, accepted = pcall(
        lockTarget,
        target,
        math.max(0.10, tonumber(duration) or 0.50),
        reason or "autopunish"
    )
    return ok and accepted == true
end

AutoPunishRuntime.getImpactFaceDuration =
    function(character, attackType, combo)
        if not character
            or not character.Parent
        then
            return 0.42, 0.30
        end

        local style =
            getStyle(character)
        local speed =
            getSpeedMultiplier(character)
        local delay =
            attackType == "M2"
                and (
                    tonumber(
                        CombatConfig.M2
                            .DefaultHitboxDelay
                    )
                    or 0.30
                )
                or (
                    tonumber(
                        CombatConfig.M1
                            .DefaultHitboxDelay
                    )
                    or 0.32
                )

        if attackType == "M1" then
            local selectedCombo =
                math.clamp(
                    math.floor(
                        tonumber(combo)
                            or 1
                    ),
                    1,
                    4
                )

            pcall(function()
                local value =
                    CombatConfig
                        .GetScaledStyleM1HitboxDelay(
                            style,
                            selectedCombo,
                            speed
                        )

                if typeof(value)
                    == "number"
                then
                    delay =
                        math.max(
                            0,
                            value
                        )
                end
            end)
        else
            local variant =
                nil

            pcall(function()
                variant =
                    CombatStepUtils
                        .ResolveM2VariantId(
                            style,
                            character
                        )
            end)

            local doubleWindow =
                style == "hakari"
                and character:GetAttribute(
                    "HakariM2DoubleWindow"
                ) == true

            pcall(function()
                local base =
                    CombatConfig
                        .GetStyleM2HitboxDelay(
                            style,
                            doubleWindow,
                            variant
                        )

                if typeof(base)
                    == "number"
                then
                    delay =
                        math.max(
                            0,
                            base
                        )
                end
            end)

            pcall(function()
                local value =
                    CombatConfig
                        .GetScaledHitboxDelay(
                            delay,
                            speed
                        )

                if typeof(value)
                    == "number"
                then
                    delay =
                        math.max(
                            0,
                            value
                        )
                end
            end)
        end

        delay =
            math.clamp(
                tonumber(delay) or 0.30,
                0.08,
                0.70
            )

        local duration =
            math.clamp(
                delay + 0.14,
                0.28,
                0.84
            )

        return duration,
            delay
    end

AutoPunishRuntime.holdFaceThroughImpact =
    function(
        target,
        attackType,
        combo,
        purpose
    )
        if Flags.ap_auto_face ~= true
            or not target
            or not target.Parent
        then
            return false
        end

        local character =
            getCharacter()
        local duration,
            impactDelay =
                AutoPunishRuntime
                    .getImpactFaceDuration(
                        character,
                        attackType,
                        combo
                    )
        local now =
            os.clock()
        local untilAt =
            now + duration
        local hardUntilAt =
            now
            + math.clamp(
                duration + 0.40,
                0.68,
                1.20
            )

        if AutoPunishRuntime
                .impactFaceTarget
                == target
        then
            AutoPunishRuntime
                .impactFaceUntil =
                math.max(
                    tonumber(
                        AutoPunishRuntime
                            .impactFaceUntil
                    ) or 0,
                    untilAt
                )
            AutoPunishRuntime
                .impactFaceHardUntil =
                math.max(
                    tonumber(
                        AutoPunishRuntime
                            .impactFaceHardUntil
                    ) or 0,
                    hardUntilAt
                )
        else
            AutoPunishRuntime
                .impactFaceTarget =
                target
            AutoPunishRuntime
                .impactFaceUntil =
                untilAt
            AutoPunishRuntime
                .impactFaceHardUntil =
                hardUntilAt
        end

        AutoPunishRuntime
            .impactFaceAttack =
            attackType
        AutoPunishRuntime
            .impactFacePurpose =
            purpose
        AutoPunishRuntime
            .impactFaceLandedAt =
            nil
        AutoPunishRuntime
            .impactFaceDelay =
            impactDelay

        local impactReason
        if purpose == "cqc-m2-cancel" then
            impactReason = "cqc-m2-cancel-impact"
        elseif attackType == "M2" then
            impactReason = "parry-punish-m2-impact"
        else
            impactReason = "parry-punish-m1-impact"
        end

        AutoPunishRuntime.requestFaceLock(
            target,
            duration,
            impactReason
        )

        debugLog(
            "AUTOPUNISH_FACE_IMPACT_HOLD",
            {
                target =
                    target.Name,
                attack =
                    attackType
                    or "",
                combo =
                    combo
                    or "",
                purpose =
                    purpose
                    or "",
                impactDelayMs =
                    math.floor(
                        impactDelay
                            * 1000
                        + 0.5
                    ),
                holdMs =
                    math.floor(
                        duration
                            * 1000
                        + 0.5
                    ),
            },
            true
        )

        return true
    end

AutoPunishRuntime.observeLocalImpactHitbox =
    function(hitbox, attackType, observedAt)
        if Flags.ap_auto_face ~= true
            or not hitbox
            or not hitbox.Parent
            or not hitbox:IsA("BasePart")
        then
            return false
        end

        local target =
            AutoPunishRuntime
                .impactFaceTarget

        if not target
            or not target.Parent
            or tostring(
                AutoPunishRuntime
                    .impactFaceAttack
                or ""
            ) ~= tostring(
                attackType
                or ""
            )
        then
            return false
        end

        local targetRoot =
            getRoot(target)

        if not targetRoot then
            return false
        end

        local localPoint =
            hitbox.CFrame
                :PointToObjectSpace(
                    targetRoot.Position
                )
        local rootRadius =
            math.max(
                targetRoot.Size.X,
                targetRoot.Size.Z
            ) * 0.5
        local rootHalfY =
            targetRoot.Size.Y * 0.5
        local cushion =
            0.55
        local landed =
            math.abs(localPoint.X)
                <= hitbox.Size.X * 0.5
                    + rootRadius
                    + cushion
            and math.abs(localPoint.Z)
                <= hitbox.Size.Z * 0.5
                    + rootRadius
                    + cushion
            and math.abs(localPoint.Y)
                <= hitbox.Size.Y * 0.5
                    + rootHalfY
                    + cushion

        if not landed then
            return false
        end

        local now =
            tonumber(observedAt)
            or os.clock()

        AutoPunishRuntime
            .impactFaceLandedAt =
            now
        AutoPunishRuntime
            .impactFaceUntil =
            now + 0.045
        AutoPunishRuntime
            .impactFaceHardUntil =
            now + 0.045

        debugLog(
            "AUTOPUNISH_FACE_LAND_CONFIRM",
            {
                target =
                    target.Name,
                attack =
                    attackType
                    or "",
                swingId =
                    hitbox:GetAttribute(
                        "VictimSwingId"
                    )
                    or "",
                hitboxDistance =
                    flat(
                        hitbox.Position
                        - targetRoot.Position
                    ).Magnitude,
            },
            true
        )

        return true
    end

AutoPunishRuntime.isImpactFaceHoldActive =
    function(target, now)
        now =
            tonumber(now)
            or os.clock()

        local held =
            AutoPunishRuntime
                .impactFaceTarget
        local untilAt =
            tonumber(
                AutoPunishRuntime
                    .impactFaceUntil
            ) or 0
        local hardUntil =
            tonumber(
                AutoPunishRuntime
                    .impactFaceHardUntil
            ) or untilAt

        if held
            and held == target
            and held.Parent
            and AutoPunishRuntime
                .impactFaceLandedAt
                == nil
            and now > untilAt
            and now <= hardUntil
        then
            local character =
                getCharacter()
            local attack =
                tostring(
                    AutoPunishRuntime
                        .impactFaceAttack
                    or ""
                )
            local attackStillActive =
                character
                and (
                    (
                        attack == "M1"
                        and (
                            character:GetAttribute("M1") == true
                            or character:GetAttribute("M1Hold") == true
                            or character:GetAttribute("PendingM1") == true
                        )
                    )
                    or (
                        attack == "M2"
                        and (
                            character:GetAttribute("M2") == true
                            or character:GetAttribute("PendingM2") == true
                        )
                    )
                )
                or false

            if attackStillActive then
                untilAt =
                    math.min(
                        hardUntil,
                        now + 0.05
                    )
                AutoPunishRuntime
                    .impactFaceUntil =
                    untilAt
            end
        end

        if not held
            or held ~= target
            or not held.Parent
            or now > untilAt
        then
            if held == target
                or now > untilAt
            then
                AutoPunishRuntime
                    .impactFaceTarget =
                    nil
                AutoPunishRuntime
                    .impactFaceUntil =
                    0
                AutoPunishRuntime
                    .impactFaceHardUntil =
                    0
                AutoPunishRuntime
                    .impactFaceLandedAt =
                    nil
                AutoPunishRuntime
                    .impactFaceAttack =
                    nil
                AutoPunishRuntime
                    .impactFacePurpose =
                    nil
            end

            return false
        end

        local humanoid =
            held:FindFirstChildOfClass(
                "Humanoid"
            )

        if humanoid
            and humanoid.Health <= 0
        then
            return false
        end

        if held:GetAttribute(
            "Downed"
        ) == true
        then
            return false
        end

        return true
    end

AutoPunishRuntime.isFaceReady = function(target)
    if Flags.ap_auto_face ~= true then
        return true, 1
    end

    local dot = AutoPunishRuntime.getFacingDot(target)
    local distance = getAutoPunishDistance(target)
    local requiredDot = distance <= 4.25 and 0.91 or 0.96
    return dot >= requiredDot, dot
end

local function waitForAutoPunishM1Ready(character, target, purpose, timeout)
    local startedAt = os.clock()
    local normalWindow = math.max(0, tonumber(timeout) or 0)
    local exactOnce = purpose == "punish-once"
    local parryPunish =
        purpose == "punish"
        or exactOnce
    local deadline = startedAt + normalWindow
    local stunDeadline = purpose == "punish"
        and startedAt + math.max(normalWindow, 0.60)
        or deadline
    local hardDeadline = parryPunish
        and startedAt + math.max(normalWindow, 0.72)
        or deadline

    repeat
        if not character or not character.Parent then
            return false, "local_missing"
        end

        if parryPunish then
            if not isAutoPunishActive()
                or Flags.ap_auto_punish_after_parry ~= true
            then
                return false, "disabled"
            end





        end

        local ready = canAutoPunishM1(character)
        local reachable, distance, projectedDistance
        if purpose == "test" then
            reachable = true
            distance = 0
            projectedDistance = 0
        elseif parryPunish then
            AutoPunishRuntime.requestFaceLock(
                target,
                0.75,
                purpose == "punish-once"
                    and "parry-punish-once-m1"
                    or "parry-punish-m1"
            )
            reachable, distance, projectedDistance =
                AutoPunishRuntime.isParryM1LandingReady(target)
            if exactOnce then
                reachable = true
            end
        else
            reachable, distance, projectedDistance =
                isAutoPunishM1Reachable(target)
        end

        local faceReady = true
        if parryPunish then
            faceReady = AutoPunishRuntime.isFaceReady(target)
            if exactOnce then
                faceReady = true
            end
        end

        if ready and reachable and faceReady then
            return true, "ready", distance, projectedDistance
        end

        local clockNow = os.clock()
        if clockNow >= deadline then



            local stillStunned =
                purpose == "punish"
                and target
                and target.Parent
                and isAutoPunishTargetStunned(target)

            local closeSafeGrace =
                parryPunish
                and target
                and target.Parent
                and not isAutoPunishTargetAttacking(target)
                and distance <= math.min(
                    getAutoPunishM1Reach(),
                    4.75
                )

            if not ready
                and clockNow < hardDeadline
                and (
                    (stillStunned and clockNow < stunDeadline)
                    or closeSafeGrace
                )
            then
                deadline = math.min(
                    hardDeadline,
                    clockNow + 0.045
                )
            else
                if not ready then
                    return false, "not_ready", distance, projectedDistance
                end
                return false, "range", distance, projectedDistance
            end
        end

        RunService.Heartbeat:Wait()
    until false
end

local function getAutoPunishFollowCombo()
    if os.clock() >= autoPunishComboResetAt then
        autoPunishComboMirror = 0
    end

    return autoPunishComboMirror % 4 + 1
end

local function noteAutoPunishM1Combo(mode, selectedHit)
    selectedHit = math.clamp(
        math.floor(tonumber(selectedHit) or 1),
        1,
        4
    )

    autoPunishComboMirror = selectedHit
    autoPunishComboResetAt = os.clock()
        + (tonumber(CombatConfig.ClientPredict.M1.ComboResetTime) or 1.55)
end

local function confirmAutoPunishM1Start(character, before, timeout)
    local deadline = os.clock() + math.max(0.025, tonumber(timeout) or 0.10)

    repeat
        local started =
            (before.m1 ~= true and character:GetAttribute("M1") == true)
            or (before.pending ~= true and character:GetAttribute("PendingM1") == true)
            or (before.combat ~= true and character:GetAttribute("CombatAttacking") == true)
            or (before.cooldown ~= true and character:GetAttribute("M1Cooldown") == true)

        if started then
            return true
        end

        if os.clock() >= deadline or not character.Parent then
            break
        end
        RunService.Heartbeat:Wait()
    until false

    return false
end

local function markAutoParryScriptedAttack(attackType, source)
    local marker = Menu and Menu._MarkAutoParryScriptedAttack
    if type(marker) == "function" then
        local ok, fired = pcall(marker, attackType, source)
        return ok and fired == true
    end
    return false
end

local function isWingChunCounterStanceActive(target)
    if not target or not target.Parent then
        return false
    end

    local runtime = Menu and Menu._WingChunPostM2Runtime
    local isActive = runtime and runtime.isCounterActive
    if type(isActive) == "function" then
        local ok, active = pcall(isActive, target)
        if ok and active == true then
            return true
        end
    end

    if normalizeCombatStyleKey(getStyle(target)) ~= "wingchun" then
        return false
    end

    return target:GetAttribute("M2") == true
        or target:GetAttribute("PendingM2") == true
        or target:GetAttribute("M2CounterStance") == true
end

local function logAutoPunishWingChunCounterGate(target, attackType, purpose)
    debugLog("AUTOPUNISH_COUNTER_STANCE_GATE", {
        target = target and target.Name or "",
        attack = attackType or "",
        purpose = purpose or "",
        reason = "wingchun_counter_active",
    }, true)
end

local function fireAutoPunishM1(target, forceRate, purpose, confirmedGuardSerial)
    local exactOnce = purpose == "punish-once"
    local cqcM2Cancel = purpose == "cqc-m2-cancel"
    local parryPunish =
        purpose == "punish"
        or exactOnce

    if purpose ~= "test" and Flags.ap_auto_punish ~= true then
        return false
    end

    if target
        and Menu._IsFriendlyCharacter
        and Menu._IsFriendlyCharacter(target)
    then
        return false
    end

    local character = getCharacter()
    if not character or not character.Parent or character:GetAttribute("Equip") ~= true then
        debugLog("AUTOPUNISH_M1_SKIP", {
            purpose = purpose or "unknown",
            reason = "combat_off",
        })
        return false
    end

    if target and isWingChunCounterStanceActive(target) then
        logAutoPunishWingChunCounterGate(target, "M1", purpose)
        return false
    end

    local interval = 1 / getAutoPunishM1Rate()
    local now = os.clock()
    if forceRate ~= true and now - autoPunishLastM1At < interval then
        return false
    end

    if cqcM2Cancel then
        local currentDistance = getAutoPunishDistance(target)
        local nativeReach = getAutoPunishM1Reach() + 1.10
        local interceptStartReach = math.max(nativeReach, 16.5)

        if currentDistance > interceptStartReach then
            debugLog("AUTOPUNISH_M1_SKIP", {
                purpose = purpose,
                reason = "cqc_m2_intercept_range",
                target = target and target.Name or "",
                distance = currentDistance,
                reach = interceptStartReach,
                nativeReach = nativeReach,
            })
            return false
        end

        if target then
            AutoPunishRuntime.requestFaceLock(
                target,
                0.16,
                "cqc-m2-cancel"
            )

            if Flags.ap_auto_face == true then
                local faceRuntime = Menu and Menu._AutoFaceRuntime
                local faceNow = faceRuntime and faceRuntime.faceNow
                if type(faceNow) == "function" then
                    pcall(faceNow, target)
                end
            end
        end

        local comboEnabled = true
        local mode = getAutoPunishComboMode()

        local character = getCharacter()
        local desiredHit = 1
        local fastestDelay = math.huge
        if character and character.Parent then
            for candidate = 1, 4 do
                local _, delay =
                    AutoPunishRuntime.getImpactFaceDuration(
                        character,
                        "M1",
                        candidate
                    )
                delay = tonumber(delay) or math.huge
                if delay < fastestDelay then
                    fastestDelay = delay
                    desiredHit = candidate
                end
            end
        end
        if fastestDelay == math.huge then
            desiredHit = getAutoPunishFixedComboHit()
            fastestDelay = 0
        end

        local tryM1 = resolveAutoPunishTryM1()

        if type(tryM1) ~= "function" then
            debugLog("AUTOPUNISH_M1_FAIL", {
                purpose = purpose,
                method = "cqc-m2-immediate-native-tryM1",
                reason = "combo_control_unavailable",
                target = target and target.Name or "",
            })
            return false
        end

        local originalCombo = tonumber(getCompatUpvalue(tryM1, 9))
        if comboEnabled and not setCompatUpvalue(tryM1, 9, desiredHit - 1) then
            debugLog("AUTOPUNISH_M1_FAIL", {
                purpose = purpose,
                method = "cqc-m2-immediate-native-tryM1",
                reason = "combo_setup_failed",
                comboMode = mode,
                combo = desiredHit or "",
                target = target and target.Name or "",
            })
            return false
        end

        local breakerPrimed = markAutoParryScriptedAttack(
            "M1",
            "autopunish-cqc-m2-immediate"
        )

        if breakerPrimed
            and Menu._APBreakerRuntime
            and type(Menu._APBreakerRuntime.waitForCommitWindow) == "function"
        then
            Menu._APBreakerRuntime.waitForCommitWindow(
                "M1",
                "autopunish-cqc-m2-immediate"
            )
        end

        local ok, result = pcall(tryM1)
        if not (ok and result == true) then
            if comboEnabled and originalCombo ~= nil then
                setCompatUpvalue(tryM1, 9, originalCombo)
            end

            debugLog("AUTOPUNISH_M1_FAIL", {
                purpose = purpose,
                method = "cqc-m2-immediate-native-tryM1",
                reason = ok and "tryM1_rejected" or "tryM1_error",
                comboMode = mode,
                combo = desiredHit or "",
                target = target and target.Name or "",
                distance = currentDistance,
            })
            return false
        end

        autoPunishLastM1At = os.clock()

        if target then
            AutoPunishRuntime.requestFaceLock(
                target,
                math.clamp((tonumber(fastestDelay) or 0.20) + 0.10, 0.22, 0.42),
                "cqc-m2-cancel"
            )
        end

        noteAutoPunishM1Combo(mode, desiredHit)

        debugLog("AUTOPUNISH_M1", {
            purpose = purpose,
            method = "cqc-m2-immediate-native-tryM1",
            comboMode = mode,
            combo = desiredHit or tonumber(getCompatUpvalue(tryM1, 9)) or "",
            comboBefore = originalCombo or "",
            comboAfter = tonumber(getCompatUpvalue(tryM1, 9)) or "",
            target = target and target.Name or "",
            distance = currentDistance,
            immediate = true,
            interceptStart = currentDistance > nativeReach,
            nativeReach = nativeReach,
            interceptStartReach = interceptStartReach,
            fastestHitDelayMs = math.floor((tonumber(fastestDelay) or 0) * 1000 + 0.5),
        }, true)

        return true
    end

    if parryPunish and Flags.ap_auto_punish_reliable == true then
        local tryM1 = resolveAutoPunishTryM1()
        if type(tryM1) == "function" then
            local comboEnabled = true
            local mode = comboEnabled and getAutoPunishComboMode() or "Native"
            local fixedHit = comboEnabled and getAutoPunishFixedComboHit() or nil
            local desiredHit = comboEnabled
                and (mode == "Fixed" and fixedHit or getAutoPunishFollowCombo())
                or nil
            local originalCombo = tonumber(getCompatUpvalue(tryM1, 9))
            local lockout = 0.15
            pcall(function()
                local configured = CombatConfig.ClientPredict.M1.LocalParryAttackLockoutSeconds
                if typeof(configured) == "number" then
                    lockout = math.clamp(configured, 0.05, 0.40)
                end
            end)

            local startedAt = os.clock()

            local retryWindow =
                purpose == "punish-once"
                and math.max(
                    AUTO_PUNISH_M1_READY_WINDOW,
                    lockout + 0.26
                )
                or math.max(
                    0.56,
                    lockout + 0.36
                )

            local deadline =
                startedAt
                + retryWindow
            local nextAttemptAt = startedAt
            local sawTargetStun =
                purpose == "punish"
                and isAutoPunishTargetStunned(target)
                or false
            local lastReason = "native_not_ready_timeout"
            local lastFacingDot = 1
            local lastLandingReady = false
            local lastFaceReady = false

            AutoPunishRuntime.requestFaceLock(
                target,
                0.85,
                purpose == "punish-once"
                    and "parry-punish-once-m1"
                    or "parry-punish-m1"
            )

            repeat
                if not isAutoPunishActive()
                    or Flags.ap_auto_punish_after_parry ~= true
                    or not character.Parent
                    or not target
                    or not target.Parent
                    or (Menu._IsFriendlyCharacter and Menu._IsFriendlyCharacter(target))
                then
                    lastReason = "cancelled"
                    break
                end

                if isWingChunCounterStanceActive(target) then
                    lastReason = "target_wingchun_counter_stance"
                    logAutoPunishWingChunCounterGate(target, "M1", purpose)
                    break
                end

                releaseAutoPunishConfirmedBlock(character, confirmedGuardSerial)
                local faceLockAccepted = AutoPunishRuntime.requestFaceLock(
                    target,
                    0.85,
                    purpose == "punish-once"
                        and "parry-punish-once-m1"
                        or "parry-punish-m1"
                )
                if exactOnce
                    and Flags.ap_auto_face == true
                    and not faceLockAccepted
                then
                    lastReason = "face_lock_wait"
                    task.wait(0.012)
                    continue
                end

                local clockNow = os.clock()
                local observedLandingReady, currentDistance, projectedDistance =
                    AutoPunishRuntime.isParryM1LandingReady(target)
                local observedFaceReady, facingDot =
                    AutoPunishRuntime.isFaceReady(target)
                local landingReady = observedLandingReady
                local faceReady = observedFaceReady
                lastFacingDot = facingDot
                lastLandingReady = observedLandingReady
                lastFaceReady = observedFaceReady

                if exactOnce then
                    lastReason = "native_not_ready_timeout"
                elseif not landingReady then
                    lastReason = "landing_window_missed"
                elseif not faceReady then
                    lastReason = "facing_wait"
                else
                    lastReason = "native_not_ready_timeout"
                end

                if sawTargetStun
                    and clockNow - startedAt >= 0.10
                    and not isAutoPunishTargetStunned(target)
                then
                    lastReason = "target_recovered"
                    break
                end

                if landingReady and faceReady and clockNow >= nextAttemptAt then
                    nextAttemptAt = clockNow + 0.025

                    local faceRuntime = Menu and Menu._AutoFaceRuntime
                    local faceNow = faceRuntime and faceRuntime.faceNow
                    local finalFaceApplied = false
                    if Flags.ap_auto_face == true and type(faceNow) == "function" then
                        local okFace, applied = pcall(faceNow, target)
                        finalFaceApplied = okFace and applied == true
                    end
                    local finalFaceReady, finalFacingDot =
                        AutoPunishRuntime.isFaceReady(target)
                    lastFacingDot = finalFacingDot
                    if not finalFaceReady then
                        lastReason = "final_facing_reclaimed"
                        RunService.Heartbeat:Wait()
                        continue
                    end

                    if comboEnabled
                        and not setCompatUpvalue(tryM1, 9, desiredHit - 1)
                    then
                        lastReason = "combo_control_unavailable"
                        break
                    end

                    local breakerPrimed = markAutoParryScriptedAttack(
                        "M1",
                        "autopunish-native:" .. tostring(purpose)
                    )

                    if breakerPrimed
                        and Menu._APBreakerRuntime
                        and type(Menu._APBreakerRuntime.waitForCommitWindow) == "function"
                    then
                        Menu._APBreakerRuntime.waitForCommitWindow(
                            "M1",
                            "autopunish-native:" .. tostring(purpose)
                        )
                    end

                    local ok, result = pcall(tryM1)
                    if ok and result == true then
                        autoPunishLastM1At = os.clock()

                        AutoPunishRuntime
                            .holdFaceThroughImpact(
                                target,
                                "M1",
                                desiredHit,
                                purpose
                            )

                        if comboEnabled then
                            noteAutoPunishM1Combo(mode, desiredHit)
                        end

                        debugLog("AUTOPUNISH_M1", {
                            purpose = purpose,
                            method = "native-tryM1",
                            comboMode = mode,
                            combo = desiredHit
                                or tonumber(getCompatUpvalue(tryM1, 9))
                                or "",
                            comboBefore = originalCombo or "",
                            comboAfter = tonumber(getCompatUpvalue(tryM1, 9)) or "",
                            target = target.Name,
                            distance = currentDistance,
                            projectedDistance = projectedDistance,
                            facingDot = facingDot,
                            waitedMs = math.floor((os.clock() - startedAt) * 1000 + 0.5),
                            parryLockoutMs = math.floor(lockout * 1000 + 0.5),
                            retryWindowMs = math.floor(retryWindow * 1000 + 0.5),
                            trigger = exactOnce
                                and "exact-local-perfect-blocked"
                                or "confirmed-parry",
                            observedLandingReady = observedLandingReady,
                            observedFaceReady = observedFaceReady,
                            finalFaceApplied = finalFaceApplied,
                            finalFacingDot = finalFacingDot,
                        }, true)
                        return true
                    end
                end

                if clockNow >= deadline then
                    break
                end
                RunService.Heartbeat:Wait()
            until false

            if comboEnabled and originalCombo ~= nil then
                setCompatUpvalue(tryM1, 9, originalCombo)
            end

            debugLog("AUTOPUNISH_M1_FAIL", {
                purpose = purpose,
                method = "native-tryM1",
                reason = lastReason,
                comboMode = mode,
                combo = desiredHit or "",
                target = target and target.Name or "",
                distance = target and getAutoPunishDistance(target) or "",
                facingDot = lastFacingDot,
                trigger = exactOnce
                    and "exact-local-perfect-blocked"
                    or "confirmed-parry",
                observedLandingReady = lastLandingReady,
                observedFaceReady = lastFaceReady,
            }, true)

            return false
        end
    end

    local readyWindow = parryPunish
        and AUTO_PUNISH_M1_READY_WINDOW
        or 0.075
    local ready, readyReason, readyDistance, projectedDistance =
        waitForAutoPunishM1Ready(
            character,
            target,
            purpose,
            readyWindow
        )

    if not ready then
        debugLog("AUTOPUNISH_M1_SKIP", {
            purpose = purpose or "unknown",
            reason = readyReason or "not_ready",
            target = target and target.Name or "",
            distance = readyDistance or "",
            projectedDistance = projectedDistance or "",
            reach = getAutoPunishM1Reach(),
        })
        return false
    end

    local module = getCombatModule("M1")
    if not module then
        return false
    end

    local comboEnabled = true
    local mode = comboEnabled and getAutoPunishComboMode() or "Native"
    local fixedHit = comboEnabled and getAutoPunishFixedComboHit() or nil
    local desiredHit = comboEnabled
        and (mode == "Fixed" and fixedHit or getAutoPunishFollowCombo())
        or nil
    local tryM1 = resolveAutoPunishTryM1()
    local method = comboEnabled
        and (mode == "Fixed" and "fixed-tryM1" or "follow-tryM1")
        or "native-tryM1"

    if type(tryM1) ~= "function" then
        debugLog("AUTOPUNISH_M1_FAIL", {
            purpose = purpose or "unknown",
            method = "combo-tryM1",
            reason = "combo_control_unavailable",
            comboMode = mode,
            combo = desiredHit,
            target = target and target.Name or "",
        })
        return false
    end

    local originalCombo = tonumber(getCompatUpvalue(tryM1, 9))
    if comboEnabled and not setCompatUpvalue(tryM1, 9, desiredHit - 1) then
        debugLog("AUTOPUNISH_M1_FAIL", {
            purpose = purpose or "unknown",
            method = "combo-tryM1",
            reason = "combo_setup_failed",
            comboMode = mode,
            combo = desiredHit or "",
            target = target and target.Name or "",
        })
        return false
    end

    if target then
        local faceReason = cqcM2Cancel
            and "cqc-m2-cancel"
            or "autopunish-m1"
        local faceDuration = cqcM2Cancel and 0.16 or 0.55
        local faceLocked = AutoPunishRuntime.requestFaceLock(
            target,
            faceDuration,
            faceReason
        )
        if Flags.ap_auto_face == true and not faceLocked then
            if comboEnabled and originalCombo ~= nil then
                setCompatUpvalue(tryM1, 9, originalCombo)
            end
            debugLog("AUTOPUNISH_M1_SKIP", {
                purpose = purpose or "unknown",
                reason = "face_lock_owned_by_higher_priority",
                target = target.Name,
            })
            return false
        end

        if cqcM2Cancel and Flags.ap_auto_face == true then
            local faceRuntime = Menu and Menu._AutoFaceRuntime
            local faceNow = faceRuntime and faceRuntime.faceNow
            if type(faceNow) == "function" then
                pcall(faceNow, target)
            end
        end
    end

    if target and isWingChunCounterStanceActive(target) then
        if comboEnabled and originalCombo ~= nil then
            setCompatUpvalue(tryM1, 9, originalCombo)
        end
        logAutoPunishWingChunCounterGate(target, "M1", purpose)
        return false
    end

    if target
        and Menu._IsFriendlyCharacter
        and Menu._IsFriendlyCharacter(target)
    then
        if comboEnabled and originalCombo ~= nil then
            setCompatUpvalue(tryM1, 9, originalCombo)
        end
        return false
    end

    local breakerPrimed = markAutoParryScriptedAttack(
        "M1",
        "autopunish:" .. tostring(purpose or "unknown")
    )

    if breakerPrimed
        and Menu._APBreakerRuntime
        and type(Menu._APBreakerRuntime.waitForCommitWindow) == "function"
    then
        Menu._APBreakerRuntime.waitForCommitWindow(
            "M1",
            "autopunish:" .. tostring(purpose or "unknown")
        )
    end

    local ok, result = pcall(tryM1)
    if not (ok and result == true) then
        if comboEnabled and originalCombo ~= nil then
            setCompatUpvalue(tryM1, 9, originalCombo)
        end

        debugLog("AUTOPUNISH_M1_FAIL", {
            purpose = purpose or "unknown",
            method = method,
            reason = ok and "tryM1_rejected" or "tryM1_error",
            comboMode = mode,
            combo = desiredHit,
            target = target and target.Name or "",
        })
        return false
    end

    autoPunishLastM1At = os.clock()

    if target then
        AutoPunishRuntime
            .holdFaceThroughImpact(
                target,
                "M1",
                desiredHit,
                purpose
            )
    end

    if comboEnabled then
        noteAutoPunishM1Combo(mode, desiredHit)
    end

    debugLog("AUTOPUNISH_M1", {
        purpose = purpose or "unknown",
        method = method,
        comboMode = mode,
        combo = desiredHit
            or tonumber(getCompatUpvalue(tryM1, 9))
            or "",
        comboBefore = originalCombo or "",
        comboAfter = tonumber(getCompatUpvalue(tryM1, 9)) or "",
        target = target and target.Name or "",
        distance = target and getAutoPunishDistance(target) or 0,
        readyWindowMs = math.floor(
            (parryPunish
                and AUTO_PUNISH_M1_READY_WINDOW
                or 0.075) * 1000 + 0.5
        ),
    }, true)

    return true
end

local CQC_M2_CANCEL_WINDOW = 0.50
local CQC_M2_CANCEL_RETRY = 0.008
local CQC_M2_RING_SEQUENCE_TTL = 4.25

local function tryCqcM2M1Cancel(threat, now)
    if not threat
        or threat.attackType ~= "M2"
        or normalizeCombatStyleKey(tostring(
            threat.style or getStyle(threat.owner) or ""
        )) ~= "cqc"
    then
        return false
    end

    threat.lastReject = "cqc_m2_interrupt_only"

    if threat.source ~= "cqc_ring" and threat.source ~= "animation" then
        return false
    end

    if threat.source == "animation" then
        local ringStartedAt = threat.owner and cqcRingActivationAt[threat.owner]
        local referenceNow = tonumber(now) or os.clock()
        if ringStartedAt
            and referenceNow >= ringStartedAt
            and referenceNow - ringStartedAt <= CQC_M2_RING_SEQUENCE_TTL
        then
            threat.lastReject = "cqc_m2_ring_already_handled"
            if threat.cqcM2RingDuplicateLogged ~= true then
                threat.cqcM2RingDuplicateLogged = true
                debugLog("CQC_M2_ANIMATION_CANCEL_SKIPPED_RING", {
                    owner = threat.ownerName
                        or (threat.owner and threat.owner.Name)
                        or "",
                    ringAge = referenceNow - ringStartedAt,
                    source = threat.source or "",
                }, true)
            end
            return true
        end
    end

    if threat.cqcM2CancelCommitted == true then
        return true
    end

    if threat.cqcM2CancelWorkerStarted == true then
        return false
    end
    threat.cqcM2CancelWorkerStarted = true

    local startedAt = tonumber(threat.cqcRingStartedAt)
        or tonumber(threat.animationStartedAt)
        or tonumber(threat.createdAt)
        or tonumber(now)
        or os.clock()

    local initialTarget = threat.owner or resolveOwner(threat)
    local initialCharacter = getCharacter()

    debugLog("CQC_M2_AUTOPUNISH_ARMED", {
        owner = threat.ownerName
            or (initialTarget and initialTarget.Name)
            or "",
        source = threat.source or "",
        window = CQC_M2_CANCEL_WINDOW,
        autoPunish = Flags.ap_auto_punish == true,
        autoParry = Flags.ap_enable == true,
        combatEnabled = initialCharacter
            and initialCharacter.Parent
            and initialCharacter:GetAttribute("Equip") == true
            or false,
        distance = initialTarget
            and initialTarget.Parent
            and getAutoPunishDistance(initialTarget)
            or "",
    }, true)

    task.spawn(function()
        local lastGate = "armed"
        local lastRetryLog = 0
        local attemptCount = 0

        while threat
            and threat.cqcM2CancelCommitted ~= true
            and os.clock() - startedAt < CQC_M2_CANCEL_WINDOW
        do
            local clockNow = os.clock()
            local age = math.max(0, clockNow - startedAt)
            local remaining = math.max(
                0,
                CQC_M2_CANCEL_WINDOW - age
            )

            local target = threat.owner or resolveOwner(threat)
            local character = getCharacter()

            if Flags.ap_auto_punish ~= true then
                lastGate = "autopunish_disabled"
                break
            end

            if not target or not target.Parent then
                lastGate = "target_missing"
                break
            end

            if not character or not character.Parent then
                lastGate = "local_missing"
                RunService.Heartbeat:Wait()
                continue
            end

            if character:GetAttribute("Equip") ~= true then
                lastGate = "combat_disabled"
                RunService.Heartbeat:Wait()
                continue
            end

            if character:GetAttribute("Blocking") == true
                or character:GetAttribute("PerfectBlocking") == true
                or Menu._apBlockActive == true
            then
                local activeGuard = Menu._apCurrentBlock
                local guardOwner =
                    type(activeGuard) == "table"
                    and activeGuard.owner
                    or nil

                if guardOwner and guardOwner ~= target then
                    lastGate = "other_defense_active"
                    RunService.Heartbeat:Wait()
                    continue
                end

                releaseAutoPunishConfirmedBlock(character, nil)
            end

            if Flags.ap_auto_face == true then
                AutoPunishRuntime.requestFaceLock(
                    target,
                    0.16,
                    "cqc-m2-cancel"
                )

                local faceRuntime = Menu and Menu._AutoFaceRuntime
                local faceNow = faceRuntime and faceRuntime.faceNow
                if type(faceNow) == "function" then
                    pcall(faceNow, target)
                end
            end

            attemptCount += 1
            debugLog("CQC_M2_AUTOPUNISH_TRIGGER", {
                owner = threat.ownerName or target.Name or "",
                age = age,
                remaining = remaining,
                distance = getAutoPunishDistance(target),
                attempt = attemptCount,
                purpose = "cqc-m2-cancel",
            }, true)

            local ok, fired = pcall(
                fireAutoPunishM1,
                target,
                true,
                "cqc-m2-cancel",
                nil
            )

            if ok and fired == true then
                local committedAt = os.clock()
                threat.cqcM2CancelCommitted = true
                threat.cqcM2CancelCommittedAt = committedAt
                threat.cqcM2CancelLastGate = "autopunish_committed"

                debugLog("CQC_M2_AUTOPUNISH_CANCEL", {
                    owner = threat.ownerName or target.Name or "",
                    committedAge = math.max(0, committedAt - startedAt),
                    committedWithinWindow =
                        committedAt - startedAt
                        <= CQC_M2_CANCEL_WINDOW,
                    distance = getAutoPunishDistance(target),
                    attempts = attemptCount,
                    method = "AutoPunish.fireAutoPunishM1",
                }, true)
                return
            end

            lastGate = ok
                and "autopunish_not_fired"
                or "autopunish_error"
            threat.cqcM2CancelLastGate = lastGate

            local retryNow = os.clock()
            if retryNow - lastRetryLog >= 0.05 then
                lastRetryLog = retryNow
                debugLog("CQC_M2_AUTOPUNISH_RETRY", {
                    owner = threat.ownerName or target.Name or "",
                    age = math.max(0, retryNow - startedAt),
                    remaining = math.max(
                        0,
                        CQC_M2_CANCEL_WINDOW
                            - (retryNow - startedAt)
                    ),
                    reason = lastGate,
                    distance = getAutoPunishDistance(target),
                    attempts = attemptCount,
                }, true)
            end

            task.wait(CQC_M2_CANCEL_RETRY)
        end

        threat.cqcM2CancelLastGate = lastGate

        debugLog("CQC_M2_CANCEL_WINDOW_END", {
            owner = threat.ownerName
                or (
                    threat.owner
                    and threat.owner.Name
                )
                or "",
            age = math.max(0, os.clock() - startedAt),
            result = threat.cqcM2CancelCommitted == true
                and "autopunish_m1_committed"
                or "no_cancel",
            lastGate = lastGate,
            attempts = attemptCount,
        }, true)
    end)

    return false
end

local function fireAutoPunishM2(target, purpose, commitContext)
    purpose = purpose or "punish"
    local isWhileStunnedPunish = purpose == "punish"
    local isExactOncePunish = purpose == "punish-once"
    local isParryPunish = isWhileStunnedPunish or isExactOncePunish

    if not isAutoPunishActive() then
        return false
    end

    if not isParryPunish then
        return false
    end

    local character = getCharacter()
    if not character or not character.Parent
        or character:GetAttribute("Equip") ~= true
    then
        return false
    end

    if not target or not target.Parent then
        return false
    end

    if Menu._IsFriendlyCharacter and Menu._IsFriendlyCharacter(target) then
        return false
    end

    if isWingChunCounterStanceActive(target) then
        logAutoPunishWingChunCounterGate(target, "M2", purpose)
        return false
    end

    if os.clock() - autoPunishLastM2At < AUTO_PUNISH_M2_ATTEMPT_GAP then
        return false
    end

    local module = getCombatModule("M2")
    if not module or type(module.OnM2Activated) ~= "function" then
        return false
    end

    if isParryPunish then
        local startedAt = os.clock()
        local reliable = Flags.ap_auto_punish_reliable == true
        local deadline = startedAt + (reliable and 0.52 or 0.08)
        local nextAttemptAt = startedAt
        local attempts = 0
        local sawTargetStun = isWhileStunnedPunish
            and isAutoPunishTargetStunned(target)
            or false
        local lastReason = "m2_not_ready_timeout"
        local lastFacingDot = 1
        local landingRange = getAutoPunishM2Range() + 0.65

        AutoPunishRuntime.requestFaceLock(
            target,
            1.00,
            isExactOncePunish
                and "parry-punish-once-m2"
                or "parry-punish-m2"
        )

        repeat
            if not isAutoPunishActive()
                or Flags.ap_auto_punish_after_parry ~= true
                or not character.Parent
                or not target.Parent
                or (Menu._IsFriendlyCharacter and Menu._IsFriendlyCharacter(target))
            then
                return false
            end

            releaseAutoPunishConfirmedBlock(
                character,
                type(commitContext) == "table"
                    and commitContext.guardSerial
                    or nil
            )
            AutoPunishRuntime.requestFaceLock(
            target,
            1.00,
            isExactOncePunish
                and "parry-punish-once-m2"
                or "parry-punish-m2"
        )

            local now = os.clock()
            local distance = getAutoPunishDistance(target)
            local landingReady = distance <= landingRange
            local faceReady, facingDot = AutoPunishRuntime.isFaceReady(target)
            lastFacingDot = facingDot

            if not landingReady then
                lastReason = "landing_window_missed"
            elseif not faceReady then
                lastReason = "facing_wait"
            else
                lastReason = "m2_not_ready_timeout"
            end

            if isWhileStunnedPunish
                and sawTargetStun
                and now - startedAt >= 0.10
                and not isAutoPunishTargetStunned(target)
            then
                lastReason = "target_recovered"
                break
            end

            if landingReady
                and faceReady
                and now >= nextAttemptAt
                and character:GetAttribute("M2Cooldown") ~= true
            then
                nextAttemptAt = now + 0.035
                attempts += 1

                local beforeReady = getCompatUpvalue(
                    module.OnM2Activated,
                    2
                )
                local before = {
                    m2 = character:GetAttribute("M2"),
                    pending = character:GetAttribute("PendingM2"),
                    combat = character:GetAttribute("CombatAttacking"),
                    cooldown = character:GetAttribute("M2Cooldown"),
                }

                local breakerPrimed = markAutoParryScriptedAttack(
                    "M2",
                    "autopunish:" .. purpose
                )

                if breakerPrimed
                    and Menu._APBreakerRuntime
                    and type(Menu._APBreakerRuntime.waitForCommitWindow) == "function"
                then
                    Menu._APBreakerRuntime.waitForCommitWindow(
                        "M2",
                        "autopunish:" .. purpose
                    )
                end

                local ok = pcall(module.OnM2Activated)
                local afterReady = getCompatUpvalue(
                    module.OnM2Activated,
                    2
                )

                local accepted = ok and (
                    (beforeReady == true and afterReady == false)
                    or (before.m2 ~= true and character:GetAttribute("M2") == true)
                    or (before.pending ~= true and character:GetAttribute("PendingM2") == true)
                    or (before.combat ~= true and character:GetAttribute("CombatAttacking") == true)
                    or (before.cooldown ~= true and character:GetAttribute("M2Cooldown") == true)
                )

                if accepted then
                    autoPunishLastM2At = os.clock()
                    AutoPunishRuntime
                        .holdFaceThroughImpact(
                            target,
                            "M2",
                            nil,
                            purpose
                        )

                    debugLog("AUTOPUNISH_M2", {
                        purpose = purpose,
                        target = target.Name,
                        distance = distance,
                        facingDot = facingDot,
                        waitedMs = math.floor(
                            (os.clock() - startedAt) * 1000 + 0.5
                        ),
                        readyEdge = beforeReady == true
                            and afterReady == false,
                    }, true)
                    return true
                end
            end

            if now >= deadline or (not reliable and attempts >= 1) then
                break
            end
            RunService.Heartbeat:Wait()
        until false

        debugLog("AUTOPUNISH_M2_FAIL", {
            purpose = purpose,
            target = target.Name,
            distance = getAutoPunishDistance(target),
            facingDot = lastFacingDot,
            reason = lastReason,
        }, true)
        return false
    end

end

AutoPunishRuntime.firePostWingChun = function(target)
    if not isAutoPunishActive() then
        return false, "autopunish_off"
    end
    if Flags.ap_auto_punish_prefer_m2 ~= true then
        return false, "prefer_m2_off"
    end
    if not target or not target.Parent
        or (Menu._IsFriendlyCharacter and Menu._IsFriendlyCharacter(target))
        or normalizeCombatStyleKey(getStyle(target)) ~= "wingchun"
    then
        return false, "invalid_target"
    end

    local character = getCharacter()
    if not canAutoPunishM2(character) then
        return false, "m2_not_ready"
    end

    local distance = getAutoPunishDistance(target)
    if distance > getAutoPunishM2Range() + 0.65 then
        return false, "range"
    end

    local module = getCombatModule("M2")
    if not module or type(module.OnM2Activated) ~= "function" then
        return false, "module"
    end

    AutoPunishRuntime.requestFaceLock(
        target,
        0.70,
        "wingchun-post-m2"
    )

    local deadline = os.clock() + 0.42
    local nextAttemptAt = 0
    repeat
        if not isAutoPunishActive()
            or Flags.ap_auto_punish_prefer_m2 ~= true
            or not target.Parent
            or not character.Parent
            or (Menu._IsFriendlyCharacter and Menu._IsFriendlyCharacter(target))
        then
            return false, "cancelled"
        end

        distance = getAutoPunishDistance(target)
        if distance > getAutoPunishM2Range() + 0.65 then
            return false, "range"
        end

        local now = os.clock()
        if now >= nextAttemptAt and canAutoPunishM2(character) then
            nextAttemptAt = now + 0.035
            AutoPunishRuntime.requestFaceLock(
                target,
                0.70,
                "wingchun-post-m2"
            )

            local faceReady = true
            if Flags.ap_auto_face == true then
                faceReady = select(1, AutoPunishRuntime.isFaceReady(target)) == true
            end

            if faceReady then
                local beforeReady = getCompatUpvalue(module.OnM2Activated, 2)
                local before = {
                    m2 = character:GetAttribute("M2"),
                    pending = character:GetAttribute("PendingM2"),
                    combat = character:GetAttribute("CombatAttacking"),
                    cooldown = character:GetAttribute("M2Cooldown"),
                }

                local breakerPrimed =
                    markAutoParryScriptedAttack("M2", "wingchun-post-m2")

                if breakerPrimed
                    and Menu._APBreakerRuntime
                    and type(Menu._APBreakerRuntime.waitForCommitWindow) == "function"
                then
                    Menu._APBreakerRuntime.waitForCommitWindow(
                        "M2",
                        "wingchun-post-m2"
                    )
                end

                local ok = pcall(module.OnM2Activated)
                local afterReady = getCompatUpvalue(module.OnM2Activated, 2)
                local accepted = ok and (
                    (beforeReady == true and afterReady == false)
                    or (before.m2 ~= true and character:GetAttribute("M2") == true)
                    or (before.pending ~= true and character:GetAttribute("PendingM2") == true)
                    or (before.combat ~= true and character:GetAttribute("CombatAttacking") == true)
                    or (before.cooldown ~= true and character:GetAttribute("M2Cooldown") == true)
                )

                if accepted then
                    autoPunishLastM2At = os.clock()
                    AutoPunishRuntime.holdFaceThroughImpact(
                        target,
                        "M2",
                        nil,
                        "wingchun-post-m2"
                    )
                    debugLog("AUTOPUNISH_WINGCHUN_POST_M2", {
                        target = target.Name,
                        distance = distance,
                        preferM2 = true,
                    }, true)
                    return true, "M2"
                end
            end
        end

        RunService.Heartbeat:Wait()
    until os.clock() >= deadline

    return false, "m2_not_ready"
end

local function recordAutoPunishParryAttempt(threat, context)
    if not isAutoPunishActive()
        or Flags.ap_auto_punish_after_parry ~= true
    then
        return
    end

    local target = threat and (threat.owner or resolveOwner(threat))
        or (context and context.owner)
    if not target or not target.Parent then
        return
    end
    if Menu._IsFriendlyCharacter and Menu._IsFriendlyCharacter(target) then
        return
    end

    autoPunishRecentParryAttempts[target] = {
        at = os.clock(),
        attackType = threat and threat.attackType or nil,
        source = threat and threat.source or "",
        swingId = threat and threat.swingId or "",
        threat = threat,
        wasStunned =
            isAutoPunishTargetStunned(
                target
            ),
        wasParried =
            target:GetAttribute(
                "Parried"
            ) == true,
        localPerfectBlockConfirmed =
            false,
        localPerfectBlockConfirmedAt =
            nil,
        guardSerial =
            threat and threat.apBlockSerial or nil,
    }
end

local function startAutoPunishStunChain(target, attackType)
    if AutoPunishRuntime.getParryPunishMode() ~= "While Stunned"
        or not target
        or not target.Parent
        or (Menu._IsFriendlyCharacter and Menu._IsFriendlyCharacter(target))
    then
        return false
    end

    if autoPunishStunChains[target] then
        return true
    end

    local token = {}
    autoPunishStunChains[target] = token

    task.spawn(function()
        debugLog("AUTOPUNISH_STUN_CHAIN_START", {
            target = target.Name,
            attack = attackType or "",
            mode = "While Stunned",
        }, true)

        local observeUntil = os.clock() + 0.45
        while autoPunishStunChains[target] == token
            and isAutoPunishActive()
            and Flags.ap_auto_punish_after_parry == true
            and AutoPunishRuntime.getParryPunishMode() == "While Stunned"
            and target.Parent
            and not isAutoPunishTargetStunned(target)
            and os.clock() < observeUntil
        do
            RunService.Heartbeat:Wait()
        end

        local sawStun = isAutoPunishTargetStunned(target)

        while autoPunishStunChains[target] == token
            and isAutoPunishActive()
            and Flags.ap_auto_punish_after_parry == true
            and AutoPunishRuntime.getParryPunishMode() == "While Stunned"
            and target.Parent
            and isAutoPunishTargetStunned(target)
        do
            local humanoid = target:FindFirstChildOfClass("Humanoid")
            if humanoid and humanoid.Health <= 0 then
                break
            end
            if target:GetAttribute("Downed") == true then
                break
            end

            AutoPunishRuntime.requestFaceLock(
                target,
                0.70,
                "stun-chain"
            )

            local okM1, fired = pcall(
                fireAutoPunishM1,
                target,
                false,
                "punish"
            )

            if okM1 and fired == true then
                AutoPunishRuntime.requestFaceLock(
                    target,
                    0.55,
                    "stun-chain-impact"
                )
            end

            RunService.Heartbeat:Wait()
        end

        if autoPunishStunChains[target] == token then
            autoPunishStunChains[target] = nil
        end

        debugLog("AUTOPUNISH_STUN_CHAIN_END", {
            target = target and target.Name or "",
            attack = attackType or "",
            mode = "While Stunned",
            sawStun = sawStun,
            stillStunned = target and target.Parent
                and isAutoPunishTargetStunned(target)
                or false,
        }, true)
    end)

    return true
end

local function chooseExactOncePunishAttack(target)
    local character = getCharacter()
    if not character or not character.Parent or not target or not target.Parent then
        return "M1", "missing_character_or_target"
    end

    if Flags.ap_auto_punish_prefer_m2 ~= true then
        return "M1", "prefer_m2_off"
    end

    local distance = getAutoPunishDistance(target)
    local landingRange = getAutoPunishM2Range() + 0.65
    if distance > landingRange then
        return "M1", "m2_out_of_range"
    end

    if character:GetAttribute("M2Cooldown") == true then
        return "M1", "m2_cooldown"
    end

    local module = getCombatModule("M2")
    if not module or type(module.OnM2Activated) ~= "function" then
        return "M1", "m2_module_unavailable"
    end

    local internalReady = getCompatUpvalue(module.OnM2Activated, 2)
    if internalReady == false then
        return "M1", "m2_internal_not_ready"
    end

    return "M2", "prefer_m2_ready"
end

local function queueAutoPunishConfirmedParry(
    target,
    attackType,
    attempt,
    confirmationProof
)
    if not isAutoPunishActive()
        or Flags.ap_auto_punish_after_parry ~= true
        or not target
        or not target.Parent
    then
        return
    end

    local mode = AutoPunishRuntime.getParryPunishMode()
    local modeSerial =
        tonumber(AutoPunishRuntime.parryModeSerial) or 0

    if type(attempt) == "table" then
        if attempt.punishQueued == true then
            debugLog("AUTOPUNISH_CONFIRM_DUPLICATE", {
                target = target.Name,
                attack = attackType or "",
                proof = confirmationProof or "",
                mode = mode,
            })
            return
        end

        attempt.punishQueued = true
        attempt.punishMode = mode
        attempt.punishModeSerial = modeSerial
    end

    if mode == "Once" then
        local exactLocalProof =
            confirmationProof
                == "local-perfect-blocked"
            and type(attempt)
                == "table"
            and attempt.localPerfectBlockConfirmed
                == true

        if not exactLocalProof then
            if type(attempt) == "table" then
                attempt.punishQueued = nil
            end

            debugLog(
                "AUTOPUNISH_ONCE_CONFIRM_REJECT",
                {
                    target =
                        target.Name,
                    attack =
                        attackType
                        or "",
                    proof =
                        confirmationProof
                        or "",
                    source =
                        attempt
                        and attempt.source
                        or "",
                    localPerfectBlock =
                        attempt
                        and attempt.localPerfectBlockConfirmed
                        == true
                        or false,
                    wasStunned =
                        attempt
                        and attempt.wasStunned
                        == true
                        or false,
                    wasParried =
                        attempt
                        and attempt.wasParried
                        == true
                        or false,
                    reason =
                        "exact_local_successful_parry_required",
                },
                true
            )

            return
        end
    end

    if mode == "Once" then
        autoPunishStunChains[target] = nil
        end

    local previousPunish = autoPunishLastPunishAtByTarget[target] or 0
    if mode ~= "Once" and os.clock() - previousPunish < 0.25 then
        if type(attempt) == "table" then
            attempt.punishQueued = nil
        end
        return
    end
    if mode ~= "Once" then
        autoPunishLastPunishAtByTarget[target] = os.clock()
    end

    debugLog("AUTOPUNISH_PARRY_CONFIRMED", {
        target = target.Name,
        attack = attackType or "",
        source = attempt and attempt.source or "",
        swingId = attempt and attempt.swingId or "",
        proof = confirmationProof or "",
        mode = mode,
        confirmAge = attempt and (os.clock() - (attempt.at or os.clock())) or 0,
    }, true)

    local onceAttack = "M1"
    local onceChoiceReason = "not_once"
    if mode == "Once" then
        onceAttack, onceChoiceReason = chooseExactOncePunishAttack(target)
    end

    if Flags.ap_auto_face == true then
        local faceBridgeNow =
            os.clock()

        AutoPunishRuntime
            .impactFaceTarget =
            target
        AutoPunishRuntime
            .impactFaceUntil =
            math.max(
                tonumber(
                    AutoPunishRuntime
                        .impactFaceUntil
                ) or 0,
                faceBridgeNow + 0.55
            )
        AutoPunishRuntime
            .impactFaceHardUntil =
            math.max(
                tonumber(
                    AutoPunishRuntime
                        .impactFaceHardUntil
                ) or 0,
                faceBridgeNow + 0.65
            )
        AutoPunishRuntime
            .impactFaceAttack =
            mode == "Once"
                and onceAttack
                or "M1"
        AutoPunishRuntime
            .impactFacePurpose =
            "parry-confirm-bridge"
        AutoPunishRuntime
            .impactFaceLandedAt =
            nil

        AutoPunishRuntime.requestFaceLock(
            target,
            1.10,
            "parry-punish"
        )
    end

    task.spawn(function()
        if not isAutoPunishActive()
            or AutoPunishRuntime.getParryPunishMode() ~= mode
            or (tonumber(AutoPunishRuntime.parryModeSerial) or 0)
                ~= modeSerial
        then
            return
        end

        local replicatedStun =
            mode == "While Stunned"
            and isAutoPunishTargetStunned(target)
            or false

        AutoPunishRuntime.requestFaceLock(target, 1.10, "parry-punish")

        releaseAutoPunishConfirmedBlock(
            getCharacter(),
            attempt and attempt.guardSerial or nil
        )

        if mode == "Once" then
            debugLog("AUTOPUNISH_ONCE_EXACT_PARRY_TRIGGER", {
                target = target.Name,
                attack = attackType or "",
                source = attempt and attempt.source or "",
                proof = confirmationProof or "local-perfect-blocked",
                action = onceAttack == "M2"
                    and "one-native-m2"
                    or "one-native-m1",
                chosen = onceAttack,
                choiceReason = onceChoiceReason,
                stunnedNow = isAutoPunishTargetStunned(target),
                stunUsedForEligibility = false,
            }, true)
        else
            debugLog("AUTOPUNISH_PARRY_STUN", {
                target = target.Name,
                attack = attackType or "",
                source = attempt and attempt.source or "",
                proof = replicatedStun
                    and "replicated-stunned"
                    or (confirmationProof or "perfect-blocked"),
            }, true)
        end

        local fired = false
        local runtimeError = nil

        if AutoPunishRuntime.getParryPunishMode() ~= mode
            or (tonumber(AutoPunishRuntime.parryModeSerial) or 0)
                ~= modeSerial
        then
            return
        end

        local committedAttack = nil

        if mode == "Once" and onceAttack == "M2" then
            local okM2, resultM2 = pcall(
                fireAutoPunishM2,
                target,
                "punish-once",
                {
                    guardSerial = attempt and attempt.guardSerial or nil,
                }
            )
            if not okM2 then
                runtimeError = resultM2
            elseif resultM2 == true then
                fired = true
                committedAttack = "M2"
            end
        end

        if not fired then
            local okM1, resultM1 = pcall(
                fireAutoPunishM1,
                target,
                false,
                mode == "Once" and "punish-once" or "punish",
                attempt and attempt.guardSerial or nil
            )
            if not okM1 then
                runtimeError = runtimeError or resultM1
            elseif resultM1 == true then
                fired = true
                committedAttack = "M1"
            end
        end

        if runtimeError ~= nil then
            debugLog("AUTOPUNISH_RUNTIME_ERROR", {
                target = target.Name,
                attack = attackType or "",
                source = attempt and attempt.source or "",
                mode = mode,
                error = tostring(runtimeError),
            }, true)
        end

        if fired then
            if mode == "Once" and type(attempt) == "table" then
                attempt.onceConsumed = true
            end

            AutoPunishRuntime.requestFaceLock(
                target,
                committedAttack == "M2" and 0.70 or 0.45,
                committedAttack == "M2"
                    and "parry-punish-m2-impact"
                    or "parry-punish-m1-impact"
            )
            debugLog("AUTOPUNISH_PUNISH_COMMIT", {
                target = target.Name,
                parriedAttack = attackType or "",
                chosen = committedAttack or "",
                mode = mode,
                distance = getAutoPunishDistance(target),
                facingDot = AutoPunishRuntime.getFacingDot(target),
                trigger = mode == "Once"
                    and "exact-local-perfect-blocked"
                    or "while-stunned",
                stunUsedForEligibility = mode ~= "Once",
            }, true)
        else
            debugLog("AUTOPUNISH_PUNISH_NOT_FIRED", {
                target = target.Name,
                attack = attackType or "",
                source = attempt and attempt.source or "",
                mode = mode,
                distance = getAutoPunishDistance(target),
                facingDot = AutoPunishRuntime.getFacingDot(target),
            }, true)
        end

        if mode == "While Stunned"
            and AutoPunishRuntime.getParryPunishMode() == "While Stunned"
            and (tonumber(AutoPunishRuntime.parryModeSerial) or 0)
                == modeSerial
        then
            startAutoPunishStunChain(target, attackType)
        else
            autoPunishStunChains[target] = nil
                end
    end)
end

local function checkAutoPunishReplicatedConfirm(target, attempt, now)
    if not isAutoPunishActive()
        or Flags.ap_auto_punish_after_parry ~= true
        or not target
        or not target.Parent
        or type(attempt) ~= "table"
    then
        return false
    end

    now = now or os.clock()
    local age = now - (tonumber(attempt.at) or 0)
    if age < 0.010 or age > AUTO_PUNISH_EXACT_PARRY_MATCH_WINDOW then
        return false
    end

    local stunnedNow = isAutoPunishTargetStunned(target)
    local parriedNow = target:GetAttribute("Parried") == true
    local newStun = attempt.wasStunned ~= true and stunnedNow
    local newParried = attempt.wasParried ~= true and parriedNow
    local mode = AutoPunishRuntime.getParryPunishMode()

    if mode == "Once" then
        return false
    end

    if not newStun and not newParried then
        return false
    end

    autoPunishRecentParryAttempts[target] = nil
    local proof = newParried
        and "replicated-parried"
        or "replicated-stunned"

    debugLog("AUTOPUNISH_REPLICATED_CONFIRM", {
        target = target.Name,
        attack = attempt.attackType or "",
        age = age,
        stunned = stunnedNow,
        parried = parriedNow,
        proof = proof,
        mode = mode,
    }, true)

    queueAutoPunishConfirmedParry(
        target,
        attempt.attackType,
        attempt,
        proof
    )
    return true
end

local function resolveAutoPunishActor(value)
    if typeof(value) == "Instance" then
        if value:IsA("Model") then
            return value
        end

        if value:IsA("Player") then
            return value.Character
        end

        local model = value:FindFirstAncestorOfClass("Model")
        if model then
            return model
        end
    end

    if typeof(value) == "number" then
        local ok, player = pcall(Players.GetPlayerByUserId, Players, value)
        if ok and player then
            return player.Character
        end
    end

    local name = tostring(value or "")
    if name == "" then
        return nil
    end

    local character = getWorkspaceCharacterByName(name)
    if character then
        return character
    end

    local player = Players:FindFirstChild(name)
    if player and player:IsA("Player") then
        return player.Character
    end

    for _, candidate in ipairs(Players:GetPlayers()) do
        if tostring(candidate.DisplayName) == name then
            return candidate.Character
        end
    end

    return nil
end

local function findAutoPunishParryAttempt(attacker)
    local resolved = resolveAutoPunishActor(attacker)
    if resolved then
        local direct = autoPunishRecentParryAttempts[resolved]
        if direct then
            return resolved, direct
        end
    end

    local wantedName = resolved and resolved.Name or tostring(attacker or "")
    if wantedName == "" then
        return nil, nil
    end

    for target, attempt in pairs(autoPunishRecentParryAttempts) do
        if target
            and target.Parent
            and tostring(target.Name) == wantedName
        then
            return target, attempt
        end
    end

    return nil, nil
end

local function isAutoPunishLocalActor(value)
    local localCharacter = getCharacter()
    if not localCharacter then
        return false
    end

    local resolved = resolveAutoPunishActor(value)
    if resolved then
        return resolved == localCharacter
    end

    local name = tostring(value or "")
    return name == tostring(LocalPlayer.Name)
        or name == tostring(LocalPlayer.DisplayName)
        or name == tostring(localCharacter.Name)
end

local function onAutoPunishPerfectBlocked(attackType, attacker, blocker, proof)
    if not isAutoPunishActive()
        or Flags.ap_auto_punish_after_parry ~= true
        or not isAutoPunishLocalActor(blocker)
    then
        return
    end

    local mode =
        AutoPunishRuntime.getParryPunishMode()

    if mode == "Once"
        and proof ~= "LocalPerfectBlockedHook"
    then
        debugLog(
            "AUTOPUNISH_CONFIRM_SKIP",
            {
                attack =
                    attackType
                    or "",
                attacker =
                    tostring(
                        attacker
                        or ""
                    ),
                blocker =
                    tostring(
                        blocker
                        or ""
                    ),
                proof =
                    proof
                    or "",
                reason =
                    "once_waiting_for_local_perfectblocked_hook",
            }
        )
        return
    end

    local target, attempt = findAutoPunishParryAttempt(attacker)
    local localCharacter = getCharacter()
    if not target
        or not attempt
        or not target.Parent
        or target == localCharacter
    then
        debugLog("AUTOPUNISH_CONFIRM_SKIP", {
            attack = attackType or "",
            attacker = tostring(attacker or ""),
            blocker = tostring(blocker or ""),
            proof = proof or "",
            reason = "no_recent_parry_attempt",
        })
        return
    end

    local age = os.clock() - (tonumber(attempt.at) or 0)
    if age < 0 or age > AUTO_PUNISH_EXACT_PARRY_MATCH_WINDOW then
        autoPunishRecentParryAttempts[target] = nil
        return
    end

    if attempt.attackType
        and attackType
        and attempt.attackType ~= attackType
    then
        return
    end

    if mode == "Once"
        and (
            attempt.wasStunned == true
            or attempt.wasParried == true
        )
    then
        autoPunishRecentParryAttempts[target] =
            nil

        debugLog(
            "AUTOPUNISH_ONCE_CONFIRM_REJECT",
            {
                target =
                    target.Name,
                attack =
                    attackType
                    or "",
                proof =
                    proof
                    or "",
                reason =
                    attempt.wasParried == true
                    and "target_already_parried_before_attempt"
                    or "target_already_stunned_before_attempt",
            },
            true
        )

        return
    end

    if proof == "LocalPerfectBlockedHook" then
        attempt.localPerfectBlockConfirmed =
            true
        attempt.localPerfectBlockConfirmedAt =
            os.clock()
    end

    autoPunishRecentParryAttempts[target] = nil

    debugLog("AUTOPUNISH_SERVER_CONFIRM", {
        target = target.Name,
        attack = attackType or "",
        age = age,
        proof = proof or "perfect-blocked",
    }, true)

    queueAutoPunishConfirmedParry(
        target,
        attackType,
        attempt,
        proof == "LocalPerfectBlockedHook"
            and "local-perfect-blocked"
            or "perfect-blocked"
    )
end

local function installAutoPunishBroadcastListener()
    local shared = ReplicatedStorage:FindFirstChild("Shared")
    local network = shared and shared:FindFirstChild("Network")
    if not network then
        debugLog("AUTOPUNISH_OUTCOME_LISTENERS", {
            installed = false,
            reason = "Network_missing",
        }, true)
        return false
    end

    local installedAny = false

    if not (autoPunishBroadcastConnection
        and autoPunishBroadcastConnection.Connected)
    then
        local broadcast = network:FindFirstChild("CombatBroadcastURE")
        if broadcast
            and (broadcast:IsA("UnreliableRemoteEvent")
                or broadcast:IsA("RemoteEvent"))
        then
            local ok, connection = pcall(function()
                return broadcast.OnClientEvent:Connect(function(eventName, attacker, defender)
                    if Flags.ap_auto_punish ~= true
                        or Flags.ap_auto_punish_after_parry ~= true
                    then
                        return
                    end

                    local attackType
                    if eventName == "M1PerfectBlocked" then
                        attackType = "M1"
                    elseif eventName == "M2PerfectBlocked" then
                        attackType = "M2"
                    else
                        return
                    end

                    task.defer(
                        onAutoPunishPerfectBlocked,
                        attackType,
                        attacker,
                        defender,
                        "CombatBroadcastURE"
                    )
                end)
            end)

            if ok and connection then
                autoPunishBroadcastConnection = connection
                installedAny = true
            end
        end
    else
        installedAny = true
    end

    if not (autoPunishCosmeticConnection
        and autoPunishCosmeticConnection.Connected)
    then
        local cosmetic = network:FindFirstChild("CombatClientRemoteEvent")
        if cosmetic and cosmetic:IsA("RemoteEvent") then
            local ok, connection = pcall(function()
                return cosmetic.OnClientEvent:Connect(function(eventName, ...)
                    if Flags.ap_auto_punish ~= true
                        or Flags.ap_auto_punish_after_parry ~= true
                        or eventName ~= "CombatPairCosmetic"
                    then
                        return
                    end

                    local args = table.pack(...)
                    local outcome = tostring(args[1] or "")
                    local attackType
                    if outcome == "M1PerfectBlocked" then
                        attackType = "M1"
                    elseif outcome == "M2PerfectBlocked" then
                        attackType = "M2"
                    else
                        return
                    end

                    task.defer(
                        onAutoPunishPerfectBlocked,
                        attackType,
                        args[2],
                        args[3],
                        "CombatClientRemoteEvent"
                    )
                end)
            end)

            if ok and connection then
                autoPunishCosmeticConnection = connection
                installedAny = true
            end
        end
    else
        installedAny = true
    end

    debugLog("AUTOPUNISH_OUTCOME_LISTENERS", {
        installed = installedAny,
        broadcast = autoPunishBroadcastConnection ~= nil,
        cosmetic = autoPunishCosmeticConnection ~= nil,
    }, true)

    return installedAny
end

local function restoreAutoPunishParryHooks()
    if autoPunishBroadcastConnection then
        pcall(function()
            autoPunishBroadcastConnection:Disconnect()
        end)
        autoPunishBroadcastConnection = nil
    end

    if autoPunishCosmeticConnection then
        pcall(function()
            autoPunishCosmeticConnection:Disconnect()
        end)
        autoPunishCosmeticConnection = nil
    end

    for module, info in pairs(autoPunishParryHooks) do
        if type(module) == "table"
            and type(info) == "table"
            and module.PerfectBlocked == info.wrapper
            and type(info.original) == "function"
        then
            pcall(function()
                module.PerfectBlocked = info.original
            end)
        end
    end
    table.clear(autoPunishParryHooks)

    local env = (getgenv and getgenv()) or _G
    if rawget(env, "__SilentUIAutoPunishParryHooks") == autoPunishParryHookRegistry then
        pcall(function()
            rawset(env, "__SilentUIAutoPunishParryHooks", nil)
        end)
    end
    autoPunishParryHookRegistry = nil
end

local function cleanupPreviousAutoPunishParryHooks()
    local env = (getgenv and getgenv()) or _G
    local previous = rawget(env, "__SilentUIAutoPunishParryHooks")
    if type(previous) ~= "table" then
        return
    end

    for module, info in pairs(previous) do
        if type(module) == "table"
            and type(info) == "table"
            and module.PerfectBlocked == info.wrapper
            and type(info.original) == "function"
        then
            pcall(function()
                module.PerfectBlocked = info.original
            end)
        end
    end

    pcall(function()
        rawset(env, "__SilentUIAutoPunishParryHooks", nil)
    end)
end

local function installAutoPunishParryHooks()
    local broadcastInstalled = installAutoPunishBroadcastListener()
    cleanupPreviousAutoPunishParryHooks()
    table.clear(autoPunishParryHooks)

    local installed = 0
    local registry = {}

    for _, attackType in ipairs({"M1", "M2"}) do
        local module = getCombatModule(attackType)
        local original = module and module.PerfectBlocked

        if type(module) == "table" and type(original) == "function" then
            local wrapper
            wrapper = function(attacker, blocker, ...)
                local results = table.pack(original(attacker, blocker, ...))

                if blocker == getCharacter() then
                    task.defer(
                        onAutoPunishPerfectBlocked,
                        attackType,
                        attacker,
                        blocker,
                        "LocalPerfectBlockedHook"
                    )
                end

                return table.unpack(results, 1, results.n)
            end

            local ok = pcall(function()
                module.PerfectBlocked = wrapper
            end)

            if ok and module.PerfectBlocked == wrapper then
                local info = {
                    original = original,
                    wrapper = wrapper,
                    attackType = attackType,
                }
                autoPunishParryHooks[module] = info
                registry[module] = info
                installed += 1
            end
        end
    end

    autoPunishParryHookRegistry = registry
    local env = (getgenv and getgenv()) or _G
    pcall(function()
        rawset(env, "__SilentUIAutoPunishParryHooks", registry)
    end)

    debugLog("AUTOPUNISH_PARRY_HOOKS", {
        installed = installed,
        exact = installed == 2,
        broadcast = broadcastInstalled == true,
    }, true)

    return installed
end


    AutoPunishRuntime.recordParryAttempt = recordAutoPunishParryAttempt
    AutoPunishRuntime.installHooks = installAutoPunishParryHooks
    AutoPunishRuntime.restoreHooks = restoreAutoPunishParryHooks
    AutoPunishRuntime.fireM1 = fireAutoPunishM1
    AutoPunishRuntime.fireM2 = fireAutoPunishM2
    AutoPunishRuntime.tryCqcM2M1Cancel = tryCqcM2M1Cancel
    AutoPunishRuntime.getDistance = getAutoPunishDistance
    AutoPunishRuntime.cqcM2CancelWindow = CQC_M2_CANCEL_WINDOW
    AutoPunishRuntime.cqcM2RingSequenceTtl = CQC_M2_RING_SEQUENCE_TTL
    AutoPunishRuntime.recentParryAttempts = autoPunishRecentParryAttempts
    AutoPunishRuntime.stunChains = autoPunishStunChains
    AutoPunishRuntime.parryHooks = autoPunishParryHooks
    AutoPunishRuntime.matchWindow = AUTO_PUNISH_EXACT_PARRY_MATCH_WINDOW
    AutoPunishRuntime.installBroadcast = installAutoPunishBroadcastListener
    AutoPunishRuntime.checkReplicatedConfirm = checkAutoPunishReplicatedConfirm

    AutoPunishRuntime.getComboMode = getAutoPunishComboMode
    AutoPunishRuntime.getFixedComboHit = getAutoPunishFixedComboHit
    AutoPunishRuntime.getFollowCombo = getAutoPunishFollowCombo

    installAutoPunishParryHooks()
    AutoPunishRuntime.resetCombo = function()
        autoPunishComboMirror = 0
        autoPunishComboResetAt = 0
    end
end

Menu._AliCounterRuntime =
    Menu._AliCounterRuntime or {}

do
    local Runtime =
        Menu._AliCounterRuntime

    Runtime.pendingTarget = nil
    Runtime.pendingThreat = nil
    Runtime.pendingUntil = 0
    Runtime.lastEvasiveAt = 0
    Runtime.lastConfirmedAt = 0
    Runtime.m2Serial =
        tonumber(Runtime.m2Serial) or 0
    Runtime.faceSerial =
        tonumber(Runtime.faceSerial) or 0
    Runtime.rightVariantBridgeSerial =
        tonumber(Runtime.rightVariantBridgeSerial) or 0
    Runtime.rightVariantBridgeActive = false
    Runtime.rightVariantBridgeUntil = 0
    Runtime.rightVariantBridgeRestoreDirection = nil
    Runtime.rightVariantCommitUntil = 0
    Runtime.rightVariantCommitKeyHeld = false

    function Runtime.isEnabled()
        return Flags.ap_enable == true
            and Flags.ap_ali_counter == true
    end

    function Runtime.isEvasiveEnabled()
        return Runtime.isEnabled()
            and Flags.ap_ali_evasive_counter == true
    end

    function Runtime.isDodgeAbuseEnabled()
        return Runtime.isEnabled()
            and Flags.ap_ali_dodge_abuse == true
    end

    function Runtime.getRange()
        return math.clamp(
            tonumber(
                Flags.ap_ali_counter_range
            ) or 7.5,
            3,
            14
        )
    end

    function Runtime.getRotationHold()
        return math.clamp(
            tonumber(
                Flags.ap_ali_rotation_hold
            ) or 750,
            200,
            1400
        ) / 1000
    end

    function Runtime.getM2Variant()
        local value =
            Flags.ap_ali_dodge_abuse_m2

        if type(value) == "table" then
            value = value[1]
        end

        value =
            tostring(
                value or "Left"
            )

        if value == "Right" then
            return "Right"
        end

        return "Left"
    end

    function Runtime.getCompatUpvalue(
        func,
        index
    )
        if type(func) ~= "function" then
            return nil
        end

        local getter =
            getupvalue
            or (
                debug
                and debug.getupvalue
            )

        if type(getter) ~= "function" then
            return nil
        end

        local result =
            table.pack(
                pcall(
                    getter,
                    func,
                    index
                )
            )

        if result[1] ~= true then
            return nil
        end

        if result.n >= 3 then
            return result[3]
        end

        return result[2]
    end

    function Runtime.shouldOwnThreat(
        threat,
        context
    )
        if not Runtime.isEvasiveEnabled()
            or not Runtime.getLocalAli()
            or not threat
            or threat.expired == true
            or threat.fired == true
        then
            return false
        end

        local evasiveOwner = threat.owner
            or (context and context.owner)
        if evasiveOwner
            and Menu._IsFriendlyCharacter
            and Menu._IsFriendlyCharacter(evasiveOwner)
        then
            return false
        end

        if Runtime.isBoxingM2ParryOnly(
            threat
        ) then
            return false
        end

        if threat.attackType ~= "M1"
            and threat.attackType ~= "M2"
        then
            return false
        end

        local distance =
            tonumber(
                context
                and context.distance
            )

        if not distance then
            local character =
                Runtime.getLocalAli()
            local root =
                getRoot(character)
            local ownerRoot =
                getRoot(threat.owner)

            if not root or not ownerRoot then
                return false
            end

            distance =
                flat(
                    ownerRoot.Position
                        - root.Position
                ).Magnitude
        end

        return distance
            <= Runtime.getRange()
    end

    function Runtime.getLocalAli()
        local character =
            getCharacter()

        if not character
            or not character.Parent
            or character:GetAttribute("Equip") ~= true
            or getStyle(character) ~= "ali"
        then
            return nil
        end

        return character
    end

    function Runtime.isBoxingM2ParryOnly(threat)
        return Runtime.isEnabled()
            and Runtime.getLocalAli() ~= nil
            and threat ~= nil
            and threat.attackType == "M2"
            and tostring(
                threat.style
                    or getStyle(threat.owner)
            ) == "boxing"
    end

    function Runtime.cancel()
        Runtime.pendingTarget = nil
        Runtime.pendingThreat = nil
        Runtime.pendingUntil = 0
        Runtime.m2Serial += 1
        Runtime.faceSerial += 1
        Runtime.fSerial =
            (tonumber(Runtime.fSerial) or 0)
            + 1
        Runtime.fPulseUntil = 0
        Runtime.chainUntil = 0
        Runtime.rightVariantCommitUntil = 0

        if type(
            Runtime.releaseVariantKeys
        ) == "function"
        then
            Runtime.releaseVariantKeys()
        end

        if type(
            Runtime.sendKey
        ) == "function"
        then
            Runtime.sendKey(
                Enum.KeyCode.F,
                false
            )
        end
    end

    function Runtime.faceTarget(
        target,
        holdSeconds,
        source
    )
        local character =
            Runtime.getLocalAli()
        local root =
            getRoot(character)
        local targetRoot =
            getRoot(target)

        if not character
            or not root
            or not targetRoot
        then
            return false
        end

        Runtime.faceSerial += 1

        local serial =
            Runtime.faceSerial
        local hold =
            math.clamp(
                tonumber(holdSeconds)
                    or Runtime.getRotationHold(),
                0.20,
                1.40
            )
        local humanoid =
            character:FindFirstChildOfClass(
                "Humanoid"
            )
        local savedAutoRotate =
            humanoid
            and humanoid.AutoRotate
            or nil

        if humanoid then
            pcall(function()
                humanoid.AutoRotate = false
            end)
        end

        task.spawn(function()
            local deadline =
                os.clock() + hold

            while serial
                    == Runtime.faceSerial
                and os.clock() < deadline
                and Runtime.isEnabled()
                and character.Parent
                and root.Parent
                and target
                and target.Parent
                and targetRoot.Parent
            do
                local delta =
                    flat(
                        targetRoot.Position
                            - root.Position
                    )

                if delta.Magnitude > 0.05 then
                    local position =
                        root.Position
                    local wanted =
                        CFrame.lookAt(
                            position,
                            position
                                + delta.Unit,
                            Vector3.yAxis
                        )

                    pcall(function()
                        root.CFrame =
                            root.CFrame:Lerp(
                                wanted,
                                0.58
                            )
                    end)
                end

                RunService.Heartbeat:Wait()
            end

            if serial == Runtime.faceSerial
                and humanoid
                and humanoid.Parent
                and savedAutoRotate ~= nil
            then
                pcall(function()
                    humanoid.AutoRotate =
                        savedAutoRotate
                end)
            end
        end)

        debugLog(
            "ALI_COUNTER_ROTATION",
            {
                target =
                    target.Name,
                holdMs =
                    math.floor(
                        hold * 1000 + 0.5
                    ),
                source =
                    source or "",
            },
            true
        )

        return true
    end

    function Runtime.getM2Readiness(character)
        character =
            character
            or Runtime.getLocalAli()

        if not character then
            return false, "character_missing"
        end

        local module =
            getCombatModule("M2")

        if not module
            or type(module.OnM2Activated) ~= "function"
        then
            return false, "m2_module"
        end

        local now = os.clock()
        local internalReady =
            Runtime.getCompatUpvalue(
                module.OnM2Activated,
                2
            )

        if internalReady == false then
            return false,
                "internal_cooldown"
        end

        local lockNames = {
            "parry_internal",
            "block_internal",
            "attempt_internal",
        }

        for index = 4, 6 do
            local lockUntil =
                tonumber(
                    Runtime.getCompatUpvalue(
                        module.OnM2Activated,
                        index
                    )
                )

            if lockUntil
                and now < lockUntil
            then
                return false,
                    lockNames[index - 3]
            end
        end

        if character:GetAttribute("M2Cooldown")
            == true
        then
            return false, "m2_cooldown"
        end

        for _, state in ipairs({
            "CombatAttacking",
            "GuardBroken",
            "Stunned",
            "Ragdoll",
            "Blocking",
            "ParryAttackLockout",
            "BlockAttackLockout",
            "GrappleWinnerStun",
            "Grappling",
            "Greenzone",
            "RpCombatLocked",
        }) do
            if character:GetAttribute(state)
                == true
            then
                return false,
                    string.lower(state)
            end
        end

        if character:GetAttribute("CantAnything")
            == true
            and character:GetAttribute(
                "CombatRecovery"
            ) ~= true
        then
            return false, "cant_anything"
        end

        if character:GetAttribute("Equip")
            == false
        then
            return false, "not_equipped"
        end

        local humanoid =
            character:FindFirstChildOfClass(
                "Humanoid"
            )

        if not humanoid
            or humanoid.Health <= 0
        then
            return false, "dead"
        end

        return true, "ready", module
    end

    function Runtime.canEvasive(character)
        if not character
            or not character.Parent
        then
            return false, "local_missing"
        end

        if getStyle(character) ~= "ali" then
            return false, "local_style"
        end

        if character:GetAttribute("Equip") ~= true then
            return false, "not_equipped"
        end

        for _, state in ipairs({
            "CounterLocked",
            "SpecTimeSlowed",
            "IFRAMECD",
            "Stunned",
            "GuardBroken",
            "Grappling",
            "Ragdoll",
            "Blocking",
            "CombatAttacking",
            "Greenzone",
            "RpCombatLocked",
            "Downed",
        }) do
            if character:GetAttribute(state) == true then
                return false, string.lower(state)
            end
        end

        if character:GetAttribute("CantAnything") == true
            and character:GetAttribute("CombatRecovery") ~= true
        then
            return false, "cant_anything"
        end

        local module =
            getCombatModule("Evasive")

        if not module
            or type(module.Evasive) ~= "function"
        then
            return false, "evasive_module"
        end

        return true, nil, module
    end

    function Runtime.sendKey(
        keyCode,
        down
    )
        local virtualKey =
            keyCode == Enum.KeyCode.W
                and 0x57
            or keyCode == Enum.KeyCode.A
                and 0x41
            or keyCode == Enum.KeyCode.S
                and 0x53
            or keyCode == Enum.KeyCode.D
                and 0x44
            or keyCode == Enum.KeyCode.F
                and 0x46
            or nil

        if virtualKey then
            if down
                and type(keypress) == "function"
            then
                local ok =
                    pcall(
                        keypress,
                        virtualKey
                    )

                if ok then
                    Runtime.inputBackend =
                        "keypress"
                    return true
                end
            elseif not down
                and type(keyrelease) == "function"
            then
                local ok =
                    pcall(
                        keyrelease,
                        virtualKey
                    )

                if ok then
                    Runtime.inputBackend =
                        "keypress"
                    return true
                end
            end
        end

        local vim = nil

        pcall(function()
            vim =
                game:GetService(
                    "VirtualInputManager"
                )
        end)

        if vim
            and type(vim.SendKeyEvent)
                == "function"
        then
            local ok =
                pcall(
                    vim.SendKeyEvent,
                    vim,
                    down == true,
                    keyCode,
                    false,
                    game
                )

            if ok then
                Runtime.inputBackend =
                    "VirtualInputManager"
                return true
            end
        end

        Runtime.inputBackend =
            "none"
        return false
    end

    function Runtime.releaseVariantKeys()
        Runtime.sendKey(
            Enum.KeyCode.A,
            false
        )
        Runtime.sendKey(
            Enum.KeyCode.D,
            false
        )

        if Runtime.rightVariantCommitKeyHeld
            == true
        then
            Runtime.sendKey(
                Enum.KeyCode.S,
                false
            )
            Runtime.rightVariantCommitKeyHeld =
                false
        end
    end

    function Runtime.pressVariantKey(
        variant
    )
        local keyCode =
            variant == "Right"
                and Enum.KeyCode.D
                or Enum.KeyCode.A
        local opposite =
            variant == "Right"
                and Enum.KeyCode.A
                or Enum.KeyCode.D

        Runtime.sendKey(
            opposite,
            false
        )

        return Runtime.sendKey(
            keyCode,
            true
        )
    end

    function Runtime.holdRightVariantNow(
        character,
        humanoid,
        strongCommit
    )
        character =
            character
            or Runtime.getLocalAli()

        if not character
            or not character.Parent
        then
            return false, nil, nil, false
        end

        humanoid =
            humanoid
            or character:FindFirstChildOfClass(
                "Humanoid"
            )

        local root =
            getRoot(character)

        if not humanoid
            or not root
        then
            return false, nil, nil, false
        end

        Runtime.sendKey(
            Enum.KeyCode.A,
            false
        )

        local commitActive =
            strongCommit == true
            or os.clock()
                <= (
                    tonumber(
                        Runtime.rightVariantCommitUntil
                    ) or 0
                )

        if commitActive then
            Runtime.rightVariantCommitKeyHeld =
                Runtime.sendKey(
                    Enum.KeyCode.S,
                    true
                )
                or Runtime.rightVariantCommitKeyHeld
                == true
        elseif Runtime.rightVariantCommitKeyHeld
            == true
        then
            Runtime.sendKey(
                Enum.KeyCode.S,
                false
            )
            Runtime.rightVariantCommitKeyHeld =
                false
        end

        local keyHeld =
            Runtime.sendKey(
                Enum.KeyCode.D,
                true
            )

        local direction =
            flat(
                root.CFrame.RightVector
            )

        if commitActive then
            direction =
                flat(
                    root.CFrame.RightVector
                        - root.CFrame.LookVector
                            * 0.72
                )
        end

        if direction.Magnitude > 0.05 then
            pcall(
                humanoid.Move,
                humanoid,
                direction.Unit,
                false
            )
        end

        local degreeOk,
            degrees =
            pcall(
                CombatStepUtils.GetMoveDegrees,
                character
            )
        local resolvedOk,
            resolved =
            pcall(
                CombatStepUtils.ResolveM2VariantId,
                "ali",
                character
            )

        return keyHeld,
            resolvedOk and resolved or nil,
            degreeOk and degrees or nil,
            commitActive
    end

    function Runtime.startRightVariantBridge(
        restoreDirection,
        duration
    )
        local now =
            os.clock()

        if typeof(restoreDirection)
            == "Vector3"
            and typeof(
                Runtime.rightVariantBridgeRestoreDirection
            ) ~= "Vector3"
        then
            Runtime.rightVariantBridgeRestoreDirection =
                restoreDirection
        end

        Runtime.rightVariantBridgeUntil =
            math.max(
                tonumber(
                    Runtime.rightVariantBridgeUntil
                ) or 0,
                now
                    + math.max(
                        0.35,
                        tonumber(duration)
                            or 2.40
                    )
            )

        if Runtime.rightVariantBridgeActive
            == true
        then
            return true
        end

        Runtime.rightVariantBridgeSerial += 1
        local serial =
            Runtime.rightVariantBridgeSerial
        Runtime.rightVariantBridgeActive =
            true

        local character =
            Runtime.getLocalAli()
        local humanoid =
            character
            and character:FindFirstChildOfClass(
                "Humanoid"
            )
        local keyHeld,
            resolved,
            degrees =
            Runtime.holdRightVariantNow(
                character,
                humanoid
            )

        debugLog(
            "ALI_RIGHT_VARIANT_BRIDGE_START",
            {
                keyHeld = keyHeld,
                resolved =
                    resolved or "",
                moveDegrees =
                    degrees or "",
                duration =
                    math.max(
                        0,
                        Runtime.rightVariantBridgeUntil
                            - now
                    ),
            },
            true
        )

        task.spawn(function()
            while Runtime.rightVariantBridgeActive
                == true
                and serial
                    == Runtime.rightVariantBridgeSerial
                and os.clock()
                    <= (
                        tonumber(
                            Runtime.rightVariantBridgeUntil
                        ) or 0
                    )
            do
                local liveCharacter =
                    Runtime.getLocalAli()
                local liveHumanoid =
                    liveCharacter
                    and liveCharacter:FindFirstChildOfClass(
                        "Humanoid"
                    )

                if not liveCharacter
                    or not liveCharacter.Parent
                    or not liveHumanoid
                then
                    break
                end

                Runtime.holdRightVariantNow(
                    liveCharacter,
                    liveHumanoid
                )

                RunService.RenderStepped:Wait()
            end
        end)

        return true
    end

    function Runtime.stopRightVariantBridge(
        restoreDirection
    )
        local storedDirection =
            Runtime.rightVariantBridgeRestoreDirection

        Runtime.rightVariantBridgeSerial += 1
        Runtime.rightVariantBridgeActive =
            false
        Runtime.rightVariantBridgeUntil = 0
        Runtime.rightVariantBridgeRestoreDirection =
            nil
        Runtime.rightVariantCommitUntil = 0

        Runtime.releaseVariantKeys()

        local character =
            Runtime.getLocalAli()
        local humanoid =
            character
            and character:FindFirstChildOfClass(
                "Humanoid"
            )
        local direction =
            typeof(restoreDirection)
                == "Vector3"
                and restoreDirection
                or storedDirection

        if humanoid
            and typeof(direction) == "Vector3"
        then
            pcall(
                humanoid.Move,
                humanoid,
                direction,
                false
            )
        end
    end

    function Runtime.fireDodgeAbuseF(
        target,
        options
    )
        if not Runtime.isDodgeAbuseEnabled()
            or not Runtime.getLocalAli()
        then
            return false
        end

        local fastRightDirect =
            type(options) == "table"
            and options.fastRightDirect == true

        Runtime.fSerial =
            (tonumber(Runtime.fSerial) or 0)
            + 1

        local serial =
            Runtime.fSerial

        task.spawn(function()
            local character =
                Runtime.getLocalAli()

            if serial ~= Runtime.fSerial
                or not character
                or not character.Parent
            then
                return
            end

            local root =
                getRoot(character)
            local humanoid =
                character:FindFirstChildOfClass(
                    "Humanoid"
                )
            local blockModule =
                getCombatModule("Block")

            if not root
                or not humanoid
                or not blockModule
                or type(blockModule.Block)
                    ~= "function"
                or type(blockModule.Unblock)
                    ~= "function"
            then
                debugLog(
                    "ALI_DODGE_ABUSE_F_FAIL",
                    {
                        target =
                            target
                            and target.Name
                            or "",
                        reason =
                            "f_requirements",
                    },
                    true
                )
                return
            end

            if Menu._apBlockActive == true
                and type(
                    Menu._releaseAutoBlockForDodge
                ) == "function"
            then
                pcall(
                    Menu._releaseAutoBlockForDodge
                )
            end

            local variant =
                Runtime.getM2Variant()
            local bridgeOriginalDirection =
                variant == "Right"
                and typeof(
                    Runtime.rightVariantBridgeRestoreDirection
                ) == "Vector3"
                and Runtime.rightVariantBridgeRestoreDirection
                or humanoid.MoveDirection

            if variant == "Right" then
                Runtime.startRightVariantBridge(
                    bridgeOriginalDirection,
                    2.20
                )
                Runtime.holdRightVariantNow(
                    character,
                    humanoid
                )
            end

            local function holdRightVariant()
                if variant ~= "Right"
                    or not character.Parent
                then
                    return false
                end

                local keyHeld =
                    Runtime.holdRightVariantNow(
                        character,
                        humanoid
                    )

                return keyHeld
            end

            if variant == "Right" then
                holdRightVariant()
            else
                Runtime.releaseVariantKeys()
            end

            Runtime.sendKey(
                Enum.KeyCode.F,
                false
            )
            Runtime.fPulseUntil = 0

            local function hardBlocked()
                if not character.Parent
                    or character:GetAttribute(
                        "Equip"
                    ) ~= true
                    or character:GetAttribute(
                        "GuardBroken"
                    ) == true
                    or character:GetAttribute(
                        "Grappling"
                    ) == true
                    or character:GetAttribute(
                        "Ragdoll"
                    ) == true
                    or character:GetAttribute(
                        "Downed"
                    ) == true
                then
                    return true
                end

                return false
            end

            local function bufferedBlockWindow()
                return character:GetAttribute(
                    "ParryWindowDisabled"
                ) ~= true
                    and character:GetAttribute(
                        "GuardBroken"
                    ) ~= true
                    and (
                        character:GetAttribute(
                            "Stunned"
                        ) == true
                        or character:GetAttribute(
                            "CantAnything"
                        ) == true
                    )
                    and character:GetAttribute(
                        "ParryBuffered"
                    ) == true
            end

            local armed = false
            local armMethod = ""
            local armAttempts = 0
            local physicalF = false
            Runtime.chainUntil =
                math.max(
                    tonumber(
                        Runtime.chainUntil
                    ) or 0,
                    os.clock() + 1.75
                )

            local armDeadline =
                os.clock()
                    + (
                        fastRightDirect
                        and 0.36
                        or 0.82
                    )

            while serial == Runtime.fSerial
                and Runtime.isDodgeAbuseEnabled()
                and character.Parent
                and os.clock() <= armDeadline
                and not armed
            do
                if hardBlocked() then
                    break
                end

                if variant == "Right" then
                    holdRightVariant()
                end

                if character:GetAttribute(
                    "Blocking"
                ) == true
                    or character:GetAttribute(
                        "PerfectBlocking"
                    ) == true
                then
                    armed = true
                    armMethod =
                        "already-blocking"
                    break
                end

                if character:GetAttribute(
                    "BlockCooldown"
                ) == true
                then
                    RunService.Heartbeat:Wait()
                    continue
                end

                armAttempts += 1

                physicalF =
                    Runtime.sendKey(
                        Enum.KeyCode.F,
                        true
                    )
                    or physicalF

                local physicalUntil =
                    os.clock()
                        + (
                            fastRightDirect
                            and 0.018
                            or 0.050
                        )

                while serial == Runtime.fSerial
                    and character.Parent
                    and os.clock()
                        <= physicalUntil
                do
                    if character:GetAttribute(
                        "Blocking"
                    ) == true
                        or character:GetAttribute(
                            "PerfectBlocking"
                        ) == true
                    then
                        armed = true
                        armMethod =
                            "physical-F"
                        break
                    end

                    RunService.Heartbeat:Wait()
                end

                if armed then
                    break
                end

                Runtime.sendKey(
                    Enum.KeyCode.F,
                    false
                )

                if character:GetAttribute(
                    "BlockCooldown"
                ) ~= true
                    and not hardBlocked()
                then
                    local bufferedBefore =
                        bufferedBlockWindow()
                    local blockOk =
                        pcall(
                            blockModule.Block
                        )

                    if blockOk then
                        local directUntil =
                            os.clock()
                                + (
                                    fastRightDirect
                                    and 0.045
                                    or 0.075
                                )

                        while serial
                                == Runtime.fSerial
                            and character.Parent
                            and os.clock()
                                <= directUntil
                        do
                            if character:GetAttribute(
                                "Blocking"
                            ) == true
                                or character:GetAttribute(
                                    "PerfectBlocking"
                                ) == true
                            then
                                armed = true
                                armMethod =
                                    "Block.Block"
                                break
                            end

                            if bufferedBefore
                                or bufferedBlockWindow()
                            then
                                armed = true
                                armMethod =
                                    "buffered-F"
                                break
                            end

                            RunService.Heartbeat:Wait()
                        end
                    end
                end

                if not armed then
                    RunService.Heartbeat:Wait()
                end
            end

            if not armed then
                Runtime.sendKey(
                    Enum.KeyCode.F,
                    false
                )
                Runtime.fPulseUntil = 0

                if variant == "Right" then
                    Runtime.stopRightVariantBridge(
                        bridgeOriginalDirection
                    )
                else
                    Runtime.releaseVariantKeys()
                    pcall(
                        humanoid.Move,
                        humanoid,
                        bridgeOriginalDirection,
                        false
                    )
                end

                debugLog(
                    "ALI_DODGE_ABUSE_F_FAIL",
                    {
                        target =
                            target
                            and target.Name
                            or "",
                        reason =
                            character:GetAttribute(
                                "BlockCooldown"
                            ) == true
                            and "block_cooldown"
                            or "block_not_armed",
                        attempts =
                            armAttempts,
                        inputBackend =
                            Runtime.inputBackend
                            or "",
                        blocking =
                            character:GetAttribute(
                                "Blocking"
                            ) == true,
                        perfectBlocking =
                            character:GetAttribute(
                                "PerfectBlocking"
                            ) == true,
                        stunned =
                            character:GetAttribute(
                                "Stunned"
                            ) == true,
                        cantAnything =
                            character:GetAttribute(
                                "CantAnything"
                            ) == true,
                        parryBuffered =
                            character:GetAttribute(
                                "ParryBuffered"
                            ) == true,
                        parryWindowDisabled =
                            character:GetAttribute(
                                "ParryWindowDisabled"
                            ) == true,
                    },
                    true
                )

                Runtime.chainUntil = 0
                return
            end

            Runtime.fPulseUntil =
                os.clock() + 0.34

            local dodgeSide =
                variant == "Right"
                and "Right"
                or "Left"
            local animationName =
                "BlockHitDodge"
                .. dodgeSide
            local originalDirection =
                bridgeOriginalDirection
            local animations =
                ReplicatedStorage:FindFirstChild(
                    "Animations"
                )
            local combatAnimations =
                animations
                and animations:FindFirstChild(
                    "Combat"
                )
            local aliAnimations =
                combatAnimations
                and combatAnimations:FindFirstChild(
                    "AliAnims"
                )
            local dodgeAnimation =
                aliAnimations
                and aliAnimations:FindFirstChild(
                    animationName
                )
            local animationPlayed =
                false
            local animationMethod =
                ""
            local dodgeTrack = nil

            local packages =
                ReplicatedStorage:FindFirstChild(
                    "Packages"
                )
            local handlerModule =
                packages
                and packages:FindFirstChild(
                    "AnimationHandler"
                )

            if dodgeAnimation
                and handlerModule
                and handlerModule:IsA(
                    "ModuleScript"
                )
            then
                local handlerOk,
                    handler =
                    pcall(
                        require,
                        handlerModule
                    )

                if handlerOk
                    and type(handler) == "table"
                    and type(
                        handler.StopAnim
                    ) == "function"
                    and type(
                        handler.LoadAnim
                    ) == "function"
                then
                    pcall(
                        handler.StopAnim,
                        character,
                        "EHit",
                        nil,
                        0
                    )

                    local playOk,
                        track =
                        pcall(
                            handler.LoadAnim,
                            character,
                            "EHit",
                            dodgeAnimation,
                            nil,
                            false
                        )

                    if playOk and track then
                        animationPlayed = true
                        animationMethod =
                            "AnimationHandler"
                        dodgeTrack = track
                    end
                end
            end

            if not animationPlayed
                and dodgeAnimation
            then
                local animator =
                    humanoid:FindFirstChildOfClass(
                        "Animator"
                    )

                if animator then
                    local playOk,
                        track =
                        pcall(
                            animator.LoadAnimation,
                            animator,
                            dodgeAnimation
                        )

                    if playOk and track then
                        pcall(function()
                            track.Priority =
                                Enum.AnimationPriority.Action4
                            track:Play(
                                0.015,
                                1,
                                1
                            )
                        end)

                        animationPlayed = true
                        animationMethod =
                            "Animator"
                        dodgeTrack = track
                    end
                end
            end

            local dodgeStarted =
                os.clock()
            local dodgeDuration =
                variant == "Right"
                and (
                    fastRightDirect
                    and 0.125
                    or 0.18
                )
                or 0.16

            while serial == Runtime.fSerial
                and Runtime.isDodgeAbuseEnabled()
                and character.Parent
                and os.clock()
                    - dodgeStarted
                    < dodgeDuration
            do
                root =
                    getRoot(character)

                if not root then
                    break
                end

                if variant == "Right" then
                    holdRightVariant()
                end

                local dodgeDirection =
                    variant == "Right"
                    and flat(
                        root.CFrame.RightVector
                    )
                    or -flat(
                        root.CFrame.RightVector
                    )

                if dodgeDirection.Magnitude
                    > 0.05
                then
                    pcall(
                        humanoid.Move,
                        humanoid,
                        dodgeDirection.Unit,
                        false
                    )
                end

                if not fastRightDirect
                    and armMethod ~= "buffered-F"
                    and character:GetAttribute(
                        "Blocking"
                    ) ~= true
                    and character:GetAttribute(
                        "PerfectBlocking"
                    ) ~= true
                then
                    local rearmOk =
                        character:GetAttribute(
                            "BlockCooldown"
                        ) ~= true
                        and not hardBlocked()

                    if rearmOk then
                        pcall(
                            blockModule.Block
                        )
                    end
                end

                RunService.RenderStepped:Wait()
            end

            Runtime.sendKey(
                Enum.KeyCode.F,
                false
            )

            local releasedByInput =
                false
            local releaseUntil =
                os.clock()
                    + (
                        fastRightDirect
                        and 0.018
                        or 0.050
                    )

            while character.Parent
                and os.clock() <= releaseUntil
            do
                if character:GetAttribute(
                    "Blocking"
                ) ~= true
                then
                    releasedByInput = true
                    break
                end

                RunService.Heartbeat:Wait()
            end

            if character:GetAttribute(
                "Blocking"
            ) == true
            then
                pcall(
                    blockModule.Unblock
                )
            end

            if fastRightDirect
                and dodgeTrack
            then
                pcall(function()
                    dodgeTrack:Stop(0.025)
                end)
            end

            Runtime.fPulseUntil = 0

            if variant == "Right" then
                holdRightVariant()
            else
                pcall(
                    humanoid.Move,
                    humanoid,
                    Vector3.zero,
                    false
                )
            end

            debugLog(
                "ALI_DODGE_ABUSE_F",
                {
                    target =
                        target
                        and target.Name
                        or "",
                    input =
                        "F",
                    variant =
                        variant,
                    dodgeSide =
                        dodgeSide,
                    dodgeDuration =
                        dodgeDuration,
                    armMethod =
                        armMethod,
                    armAttempts =
                        armAttempts,
                    buffered =
                        armMethod
                            == "buffered-F",
                    physicalInput =
                        physicalF,
                    inputBackend =
                        Runtime.inputBackend
                        or "",
                    animation =
                        animationName,
                    animationPlayed =
                        animationPlayed,
                    animationMethod =
                        animationMethod,
                    releasedByInput =
                        releasedByInput,
                    sequence =
                        variant == "Right"
                        and "D_HOLD>F_DODGE>D_HOLD>M2"
                        or "F_DODGE>NEUTRAL>M2",
                    serverConfirmed =
                        true,
                    fastRightDirect =
                        fastRightDirect,
                },
                true
            )

            if serial ~= Runtime.fSerial
                or not character.Parent
                or not Runtime.isDodgeAbuseEnabled()
            then
                if variant == "Right" then
                    Runtime.stopRightVariantBridge(
                        originalDirection
                    )
                else
                    Runtime.releaseVariantKeys()
                    pcall(
                        humanoid.Move,
                        humanoid,
                        originalDirection,
                        false
                    )
                end

                Runtime.chainUntil = 0
                return
            end

            Runtime.fireConfirmedM2(
                target,
                originalDirection,
                {
                    fastRightDirect =
                        fastRightDirect,
                }
            )
        end)

        return true
    end

    function Runtime.fireConfirmedM2(
        target,
        restoreDirection,
        options
    )
        if not Runtime.isDodgeAbuseEnabled()
            or not Runtime.getLocalAli()
        then
            return false
        end

        local fastRightDirect =
            type(options) == "table"
            and options.fastRightDirect == true

        Runtime.m2Serial += 1
        local serial = Runtime.m2Serial

        Runtime.chainUntil =
            math.max(
                tonumber(Runtime.chainUntil)
                    or 0,
                os.clock() + 1.45
            )

        debugLog(
            "ALI_M2_CHAIN_START",
            {
                target =
                    target
                    and target.Name
                    or "",
                variant =
                    Runtime.getM2Variant(),
            },
            true
        )

        task.spawn(function()
            local ok, err =
                xpcall(
                    function()
                        local character =
                            Runtime.getLocalAli()

                        if not character then
                            error("character_missing")
                        end

                        local humanoid =
                            character:FindFirstChildOfClass(
                                "Humanoid"
                            )

                        if not humanoid then
                            error("humanoid_missing")
                        end

                        local variant =
                            Runtime.getM2Variant()
                        local originalDirection =
                            typeof(restoreDirection) == "Vector3"
                            and restoreDirection
                            or humanoid.MoveDirection
                        local deadline =
                            os.clock() + 1.25
                        local attempts = 0
                        local lastGate = ""
                        local lastResolved = nil
                        local lastDegrees = nil
                        local observedVariant = nil
                        local fired = false

                        local function holdRightForM2(
                            strongCommit
                        )
                            if variant ~= "Right"
                                or not character.Parent
                            then
                                return false
                            end

                            local keyHeld =
                                Runtime.holdRightVariantNow(
                                    character,
                                    humanoid,
                                    strongCommit
                                )

                            return keyHeld
                        end

                        if variant == "Right" then
                            holdRightForM2()
                        else
                            Runtime.releaseVariantKeys()
                        end

                        while serial
                                == Runtime.m2Serial
                            and Runtime.isDodgeAbuseEnabled()
                            and character.Parent
                            and os.clock() <= deadline
                        do
                            if variant == "Right" then
                                holdRightForM2()
                            end

                            local pendingNow =
                                character:GetAttribute(
                                    "PendingM2"
                                ) == true
                            local m2Now =
                                character:GetAttribute("M2")
                                    == true

                            if pendingNow or m2Now then
                                fired = true
                                observedVariant =
                                    character:GetAttribute(
                                        "M2VariantId"
                                    )
                                lastGate =
                                    variant == "Right"
                                        and observedVariant ~= nil
                                        and observedVariant ~= "Right"
                                    and "already_started_wrong_variant"
                                    or "already_started"

                                local degreeOk,
                                    degrees =
                                    pcall(
                                        CombatStepUtils.GetMoveDegrees,
                                        character
                                    )

                                if degreeOk then
                                    lastDegrees = degrees
                                end

                                local resolvedOk,
                                    resolved =
                                    pcall(
                                        CombatStepUtils.ResolveM2VariantId,
                                        "ali",
                                        character
                                    )

                                if resolvedOk then
                                    lastResolved = resolved
                                end

                                debugLog(
                                    "ALI_DODGE_ABUSE_M2_ADOPT",
                                    {
                                        target =
                                            target
                                            and target.Name
                                            or "",
                                        variant = variant,
                                        resolved =
                                            lastResolved or "",
                                        observed =
                                            observedVariant or "",
                                        moveDegrees =
                                            lastDegrees or "",
                                        pendingM2 = pendingNow,
                                        m2 = m2Now,
                                    },
                                    true
                                )
                                break
                            end

                            local ready,
                                gate,
                                module =
                                Runtime.getM2Readiness(
                                    character
                                )

                            lastGate = gate or ""

                            if not ready then
                                task.wait(0.02)
                                continue
                            end

                            if variant == "Right" then
                                Runtime.rightVariantCommitUntil =
                                    math.max(
                                        tonumber(
                                            Runtime.rightVariantCommitUntil
                                        ) or 0,
                                        os.clock()
                                            + (
                                                fastRightDirect
                                                and 0.42
                                                or 0.30
                                            )
                                    )

                                local keyHeld =
                                    holdRightForM2(
                                        fastRightDirect
                                    )
                                local consecutive = 0
                                local primeRequired =
                                    fastRightDirect
                                    and 2
                                    or 4
                                local primeUntil =
                                    math.min(
                                        deadline,
                                        os.clock()
                                            + (
                                                fastRightDirect
                                                and 0.16
                                                or 0.24
                                            )
                                    )

                                while serial
                                        == Runtime.m2Serial
                                    and character.Parent
                                    and os.clock() <= primeUntil
                                    and consecutive < primeRequired
                                do
                                    local root =
                                        getRoot(character)

                                    if not root then
                                        break
                                    end

                                    keyHeld =
                                        holdRightForM2(
                                            fastRightDirect
                                        )
                                        or keyHeld

                                    RunService.Heartbeat:Wait()

                                    local degreeOk,
                                        degrees =
                                        pcall(
                                            CombatStepUtils.GetMoveDegrees,
                                            character
                                        )

                                    if degreeOk then
                                        lastDegrees = degrees
                                    end

                                    local resolvedOk,
                                        resolved =
                                        pcall(
                                            CombatStepUtils.ResolveM2VariantId,
                                            "ali",
                                            character
                                        )

                                    if resolvedOk then
                                        lastResolved = resolved
                                    end

                                    local degreeValue =
                                        tonumber(lastDegrees)
                                    local commitMarginOk =
                                        not fastRightDirect
                                        or (
                                            degreeValue ~= nil
                                            and (
                                                degreeValue >= 105
                                                or degreeValue <= -125
                                            )
                                        )

                                    if lastResolved == "Right"
                                        and commitMarginOk
                                    then
                                        consecutive += 1
                                    else
                                        consecutive = 0
                                    end

                                    debugLog(
                                        "ALI_M2_VARIANT_PRIME",
                                        {
                                            target =
                                                target
                                                and target.Name
                                                or "",
                                            wanted =
                                                "Right",
                                            resolved =
                                                lastResolved
                                                or "",
                                            moveDegrees =
                                                lastDegrees
                                                or "",
                                            consecutive =
                                                consecutive,
                                            keyHeld =
                                                keyHeld,
                                            inputBackend =
                                                Runtime.inputBackend
                                                or "",
                                            moveDirection =
                                                tostring(
                                                    humanoid.MoveDirection
                                                ),
                                            strongCommit =
                                                fastRightDirect,
                                        },
                                        true
                                    )
                                end

                                if lastResolved ~= "Right"
                                    or consecutive < 2
                                then
                                    lastGate =
                                        "right_not_resolved"
                                    holdRightForM2(
                                        fastRightDirect
                                    )
                                    task.wait(0.02)
                                    continue
                                end
                            else
                                Runtime.releaseVariantKeys()
                                pcall(
                                    humanoid.Move,
                                    humanoid,
                                    Vector3.zero,
                                    false
                                )
                                RunService.Heartbeat:Wait()
                            end

                            local readyNow,
                                gateNow,
                                moduleNow =
                                Runtime.getM2Readiness(
                                    character
                                )

                            if not readyNow
                                or not moduleNow
                            then
                                lastGate =
                                    gateNow or ""
                                task.wait(0.02)
                                continue
                            end

                            attempts += 1

                            if type(
                                Menu._MarkAutoParryScriptedAttack
                            ) == "function"
                            then
                                markAutoParryScriptedAttack(
                                    "M2",
                                    "ali-dodge-abuse"
                                )
                            end

                            if variant == "Right" then
                                holdRightForM2(
                                    fastRightDirect
                                )
                            end

                            local beforeInternal =
                                Runtime.getCompatUpvalue(
                                    moduleNow.OnM2Activated,
                                    2
                                )
                            local beforePending =
                                character:GetAttribute(
                                    "PendingM2"
                                )
                            local beforeM2 =
                                character:GetAttribute("M2")
                            local beforeCombat =
                                character:GetAttribute(
                                    "CombatAttacking"
                                )

                            local beforeResolvedOk,
                                beforeResolved =
                                pcall(
                                    CombatStepUtils.ResolveM2VariantId,
                                    "ali",
                                    character
                                )

                            local callOk,
                                result =
                                pcall(
                                    moduleNow.OnM2Activated
                                )

                            local afterInternal =
                                Runtime.getCompatUpvalue(
                                    moduleNow.OnM2Activated,
                                    2
                                )

                            local internalEdge =
                                beforeInternal == true
                                and afterInternal == false
                            local attributeEdge =
                                character:GetAttribute(
                                    "PendingM2"
                                ) ~= beforePending
                                or character:GetAttribute("M2")
                                    ~= beforeM2
                                or character:GetAttribute(
                                    "CombatAttacking"
                                ) ~= beforeCombat

                            fired =
                                callOk
                                and (
                                    internalEdge
                                    or attributeEdge
                                )

                            debugLog(
                                fired
                                    and "ALI_DODGE_ABUSE_M2"
                                    or "ALI_DODGE_ABUSE_RETRY",
                                {
                                    target =
                                        target
                                        and target.Name
                                        or "",
                                    variant =
                                        variant,
                                    resolvedBefore =
                                        beforeResolvedOk
                                        and beforeResolved
                                        or "",
                                    moveDegrees =
                                        lastDegrees or "",
                                    internalBefore =
                                        tostring(beforeInternal),
                                    internalAfter =
                                        tostring(afterInternal),
                                    internalEdge =
                                        internalEdge,
                                    attributeEdge =
                                        attributeEdge,
                                    attempts =
                                        attempts,
                                    result =
                                        callOk
                                        and ""
                                        or tostring(result),
                                },
                                true
                            )

                            if fired then
                                break
                            end

                            task.wait(0.02)
                        end

                        if fired
                            and variant == "Right"
                        then
                            local holdUntil =
                                os.clock()
                                    + (
                                        fastRightDirect
                                        and 0.26
                                        or 0.30
                                    )

                            while serial
                                    == Runtime.m2Serial
                                and character.Parent
                                and os.clock() < holdUntil
                            do
                                holdRightForM2(
                                    fastRightDirect
                                )

                                local liveVariant =
                                    character:GetAttribute(
                                        "M2VariantId"
                                    )
                                local pendingNow =
                                    character:GetAttribute(
                                        "PendingM2"
                                    ) == true
                                local m2Now =
                                    character:GetAttribute(
                                        "M2"
                                    ) == true

                                if liveVariant ~= nil
                                    and (
                                        pendingNow
                                        or m2Now
                                    )
                                then
                                    observedVariant =
                                        liveVariant
                                    break
                                end

                                RunService.RenderStepped:Wait()
                            end
                        elseif fired then
                            observedVariant =
                                character:GetAttribute(
                                    "M2VariantId"
                                )
                        end

                        if fired then
                            local liveVariant =
                                character:GetAttribute(
                                    "M2VariantId"
                                )

                            if liveVariant ~= nil then
                                observedVariant = liveVariant
                            end
                        end

                        if variant == "Right" then
                            Runtime.rightVariantCommitUntil =
                                0
                            Runtime.stopRightVariantBridge(
                                originalDirection
                            )
                        else
                            Runtime.releaseVariantKeys()
                            pcall(
                                humanoid.Move,
                                humanoid,
                                originalDirection,
                                false
                            )
                        end

                        Runtime.chainUntil = 0

                        debugLog(
                            fired
                                and "ALI_M2_SERVER_VARIANT"
                                or "ALI_DODGE_ABUSE_FAIL",
                            {
                                target =
                                    target
                                    and target.Name
                                    or "",
                                wanted =
                                    variant,
                                resolved =
                                    lastResolved or "",
                                observed =
                                    observedVariant or "",
                                attempts =
                                    attempts,
                                lastGate =
                                    lastGate,
                                fastRightDirect =
                                    fastRightDirect,
                                reason =
                                    not fired
                                    and "m2_not_activated"
                                    or (
                                        variant == "Right"
                                        and observedVariant ~= nil
                                        and observedVariant ~= "Right"
                                        and "wrong_variant"
                                        or ""
                                    ),
                            },
                            true
                        )
                    end,
                    function(errorValue)
                        return tostring(errorValue)
                    end
                )

            if not ok then
                local variant =
                    Runtime.getM2Variant()

                if variant == "Right" then
                    Runtime.stopRightVariantBridge(
                        restoreDirection
                    )
                else
                    Runtime.releaseVariantKeys()

                    local character =
                        Runtime.getLocalAli()
                    local humanoid =
                        character
                        and character:FindFirstChildOfClass(
                            "Humanoid"
                        )

                    if humanoid
                        and typeof(restoreDirection)
                            == "Vector3"
                    then
                        pcall(
                            humanoid.Move,
                            humanoid,
                            restoreDirection,
                            false
                        )
                    end
                end

                Runtime.chainUntil = 0

                debugLog(
                    "ALI_M2_CHAIN_ERROR",
                    {
                        target =
                            target
                            and target.Name
                            or "",
                        error =
                            tostring(err),
                    },
                    true
                )
            end
        end)

        return true
    end

    function Runtime.try(
        threat,
        prediction,
        context,
        now
    )
        now =
            tonumber(now) or os.clock()

        if not Runtime.isEvasiveEnabled()
            or not threat
            or threat.expired == true
            or threat.fired == true
        then
            return false
        end

        local evasiveOwner = threat.owner
            or (context and context.owner)
        if evasiveOwner
            and Menu._IsFriendlyCharacter
            and Menu._IsFriendlyCharacter(evasiveOwner)
        then
            return false
        end

        if Runtime.isBoxingM2ParryOnly(
            threat
        ) then
            if threat.aliBoxingM2Logged
                ~= true
            then
                threat.aliBoxingM2Logged =
                    true

                debugLog(
                    "ALI_COUNTER_BOXING_M2_PARRY",
                    {
                        owner =
                            threat.ownerName
                            or "",
                        distance =
                            context
                            and context.distance
                            or "",
                    },
                    true
                )
            end

            return false
        end

        if threat.attackType ~= "M1"
            and threat.attackType ~= "M2"
        then
            return false
        end

        if threat.track
            and threat.serverConfirmed ~= true
            and threat.track.IsPlaying == false
        then
            return false
        end

        local character =
            Runtime.getLocalAli()

        if not character then
            return false
        end

        local distance =
            tonumber(
                context
                and context.distance
            )

        if not distance then
            local root =
                getRoot(character)
            local ownerRoot =
                getRoot(threat.owner)

            if root and ownerRoot then
                distance =
                    flat(
                        ownerRoot.Position
                            - root.Position
                    ).Magnitude
            else
                distance =
                    math.huge
            end
        end

        if distance
            > Runtime.getRange()
        then
            return false
        end

        if threat.aliCounterCommitted
            == true
        then
            return true
        end

        if threat.aliCounterPending
            == true
        then
            if now
                <= (
                    tonumber(
                        threat.aliCounterPendingUntil
                    ) or 0
                )
            then
                return true
            end

            threat.aliCounterPending =
                false
        end

        if threat.aliCounterAttempted
            == true
        then
            return false
        end

        if Runtime.isDodgeAbuseEnabled()
        then
            local chainUntil =
                tonumber(Runtime.chainUntil) or 0

            if now < chainUntil then
                if threat.aliM2GateReason
                    ~= "chain_active"
                then
                    threat.aliM2GateReason =
                        "chain_active"

                    debugLog(
                        "ALI_COUNTER_M2_GATE",
                        {
                            attack =
                                threat.attackType
                                or "",
                            owner =
                                threat.ownerName
                                or "",
                            reason =
                                "chain_active",
                            remaining =
                                chainUntil - now,
                        },
                        true
                    )
                end

                return false
            end

            local m2Ready,
                m2Reason =
                Runtime.getM2Readiness(
                    character
                )

            if not m2Ready then
                if threat.aliM2GateReason
                    ~= m2Reason
                then
                    threat.aliM2GateReason =
                        m2Reason

                    debugLog(
                        "ALI_COUNTER_M2_GATE",
                        {
                            attack =
                                threat.attackType
                                or "",
                            owner =
                                threat.ownerName
                                or "",
                            reason =
                                m2Reason or "",
                            m2Cooldown =
                                character:GetAttribute(
                                    "M2Cooldown"
                                ) == true,
                        },
                        true
                    )
                end

                threat.aliCounterPending =
                    false
                threat.aliCounterAttempted =
                    false

                return false
            end

            threat.aliM2GateReason = nil
        end

        local contactAbs =
            tonumber(
                prediction
                and prediction.contactAbs
            ) or now
        local contactIn =
            contactAbs - now
        local up =
            math.max(
                0,
                tonumber(
                    prediction
                    and prediction.up
                ) or 0
            )
        local triggerLead =
            math.clamp(
                0.105
                    + math.min(
                        up * 0.65,
                        0.095
                    ),
                0.105,
                0.285
            )

        local allowed, reason, module =
            Runtime.canEvasive(
                character
            )

        if not allowed then
            if threat.aliCounterGateReason
                ~= reason
            then
                threat.aliCounterGateReason =
                    reason

                debugLog(
                    "ALI_COUNTER_GATE",
                    {
                        attack =
                            threat.attackType
                            or "",
                        owner =
                            threat.ownerName
                            or "",
                        style =
                            threat.style
                            or "",
                        reason =
                            reason or "",
                        distance =
                            distance,
                        contactIn =
                            contactIn,
                    },
                    true
                )
            end

            return false
        end

        if contactIn < -0.035 then
            return false
        end

        if contactIn > triggerLead then
            local ownershipLead =
                math.max(
                    0.32,
                    triggerLead + 0.10
                )

            if contactIn <= ownershipLead then
                if threat.aliCounterOwnedLogged
                    ~= true
                then
                    threat.aliCounterOwnedLogged =
                        true

                    debugLog(
                        "ALI_COUNTER_OWNED",
                        {
                            attack =
                                threat.attackType
                                or "",
                            owner =
                                threat.ownerName
                                or "",
                            style =
                                threat.style
                                or "",
                            distance =
                                distance,
                            contactIn =
                                contactIn,
                            triggerLead =
                                triggerLead,
                            ownershipLead =
                                ownershipLead,
                        },
                        true
                    )
                end

                return true
            end

            return false
        end

        if Menu._apBlockActive == true
            and type(
                Menu._releaseAutoBlockForDodge
            ) == "function"
        then
            pcall(
                Menu._releaseAutoBlockForDodge
            )
        end

        local humanoid =
            character:FindFirstChildOfClass(
                "Humanoid"
            )
        local root =
            getRoot(character)
        local ownerRoot =
            context
            and context.ownerRoot
            or getRoot(threat.owner)

        if not humanoid
            or not root
        then
            return false
        end

        local originalDirection =
            humanoid.MoveDirection
        local direction = nil
        local evasiveVariant =
            Runtime.getM2Variant()

        if evasiveVariant == "Right" then
            Runtime.startRightVariantBridge(
                originalDirection,
                2.40
            )

            local keyHeld,
                resolved,
                moveDegrees =
                Runtime.holdRightVariantNow(
                    character,
                    humanoid
                )

            debugLog(
                "ALI_RIGHT_VARIANT_PRE_CHAIN",
                {
                    owner =
                        threat.ownerName or "",
                    keyHeld =
                        keyHeld,
                    resolved =
                        resolved or "",
                    moveDegrees =
                        moveDegrees or "",
                    mode =
                        Runtime.isDodgeAbuseEnabled()
                        and "direct_f_right"
                        or "evasive",
                },
                true
            )

            if Runtime.isDodgeAbuseEnabled() then
                threat.aliCounterAttempted =
                    true
                threat.aliCounterPending =
                    false
                threat.aliCounterCommitted =
                    true
                threat.fired =
                    true
                threat.firedAt =
                    now

                Runtime.pendingTarget =
                    nil
                Runtime.pendingThreat =
                    nil
                Runtime.pendingUntil = 0

                Runtime.faceTarget(
                    threat.owner,
                    math.max(
                        Runtime.getRotationHold(),
                        1.20
                    ),
                    "right-direct-chain"
                )

                local fLead = 0.112
                local waitBeforeF =
                    math.max(
                        0,
                        contactIn - fLead
                    )

                debugLog(
                    "ALI_RIGHT_DIRECT_CHAIN",
                    {
                        owner =
                            threat.ownerName or "",
                        attack =
                            threat.attackType or "",
                        contactIn =
                            contactIn,
                        fLead =
                            fLead,
                        waitBeforeF =
                            waitBeforeF,
                        gameEvasiveCounterVariant =
                            "Left",
                    },
                    true
                )

                task.delay(
                    waitBeforeF,
                    function()
                        if not character.Parent
                            or not Runtime.isDodgeAbuseEnabled()
                            or Runtime.getM2Variant() ~= "Right"
                        then
                            Runtime.stopRightVariantBridge(
                                originalDirection
                            )
                            Runtime.chainUntil = 0
                            return
                        end

                        local keyHeldNow,
                            resolvedNow,
                            degreesNow =
                            Runtime.holdRightVariantNow(
                                character,
                                humanoid
                            )

                        debugLog(
                            "ALI_RIGHT_DIRECT_F_FIRE",
                            {
                                owner =
                                    threat.ownerName or "",
                                keyHeld =
                                    keyHeldNow,
                                resolved =
                                    resolvedNow or "",
                                moveDegrees =
                                    degreesNow or "",
                                contactInAtSchedule =
                                    contactIn,
                            },
                            true
                        )

                        Runtime.fireDodgeAbuseF(
                            threat.owner,
                            {
                                fastRightDirect =
                                    true,
                            }
                        )
                    end
                )

                return true
            end
        end

        if ownerRoot then
            local toward =
                flat(
                    ownerRoot.Position
                        - root.Position
                )

            if toward.Magnitude > 0.05 then
                toward =
                    toward.Unit

                local right =
                    Vector3.new(
                        -toward.Z,
                        0,
                        toward.X
                    )

                direction =
                    evasiveVariant == "Right"
                    and right
                    or -right
            end
        end

        if not direction
            or direction.Magnitude <= 0.05
        then
            local right =
                flat(
                    root.CFrame.RightVector
                )

            direction =
                evasiveVariant == "Right"
                and right
                or -right
        end

        if evasiveVariant == "Right" then
            direction =
                flat(
                    root.CFrame.RightVector
                )
        end

        if direction.Magnitude > 0.05 then
            direction =
                direction.Unit

            pcall(
                humanoid.Move,
                humanoid,
                direction,
                false
            )
        end

        threat.aliCounterAttempted =
            true
        threat.aliCounterPending =
            true
        threat.aliCounterPendingUntil =
            now + 0.18
        Runtime.pendingTarget =
            threat.owner
        Runtime.pendingThreat =
            threat
        Runtime.pendingUntil =
            now + 1.0
        Runtime.lastEvasiveAt =
            now

        local ok, errorValue =
            pcall(
                module.Evasive
            )

        if evasiveVariant ~= "Right" then
            task.delay(
                0.12,
                function()
                    if humanoid
                        and humanoid.Parent
                    then
                        pcall(
                            humanoid.Move,
                            humanoid,
                            originalDirection,
                            false
                        )
                    end
                end
            )
        end

        if not ok then
            threat.aliCounterPending =
                false
            Runtime.pendingTarget =
                nil
            Runtime.pendingThreat =
                nil
            Runtime.pendingUntil = 0

            if evasiveVariant == "Right" then
                Runtime.stopRightVariantBridge(
                    originalDirection
                )
            end

            debugLog(
                "ALI_COUNTER_FAIL",
                {
                    attack =
                        threat.attackType
                        or "",
                    owner =
                        threat.ownerName
                        or "",
                    reason =
                        tostring(errorValue),
                },
                true
            )

            return false
        end

        Runtime.faceTarget(
            threat.owner,
            Runtime.getRotationHold(),
            "evasive-attempt"
        )

        debugLog(
            "ALI_COUNTER_EVASIVE",
            {
                attack =
                    threat.attackType or "",
                owner =
                    threat.ownerName or "",
                style =
                    threat.style or "",
                distance =
                    distance,
                contactIn =
                    contactIn,
                triggerLead =
                    triggerLead,
                rotationHoldMs =
                    math.floor(
                        Runtime.getRotationHold()
                            * 1000
                            + 0.5
                    ),
                dodgeAbuse =
                    Runtime.isDodgeAbuseEnabled(),
                evasiveDirection =
                    direction
                    and tostring(
                        direction
                    )
                    or "",
                evasiveVariant =
                    evasiveVariant,
                evasiveMode =
                    "selected-lateral",
            },
            true
        )

        task.spawn(function()
            local deadline =
                os.clock() + 0.18
            local activated = false
            local confirmation = ""

            while os.clock() < deadline
                and character.Parent
            do
                if character:GetAttribute(
                    "IFRAMES"
                ) == true
                then
                    activated = true
                    confirmation =
                        "IFRAMES"
                    break
                end

                if character:GetAttribute(
                    "IFRAMECD"
                ) == true
                then
                    activated = true
                    confirmation =
                        "IFRAMECD"
                    break
                end

                RunService.Heartbeat:Wait()
            end

            if activated then
                threat.aliCounterCommitted =
                    true
                threat.aliCounterPending =
                    false
                threat.fired = true
                threat.firedAt =
                    os.clock()

                debugLog(
                    "ALI_COUNTER_COMMIT",
                    {
                        attack =
                            threat.attackType
                            or "",
                        owner =
                            threat.ownerName
                            or "",
                        confirmation =
                            confirmation,
                    },
                    true
                )
            else
                threat.aliCounterPending =
                    false

                if evasiveVariant == "Right" then
                    Runtime.stopRightVariantBridge(
                        originalDirection
                    )
                end

                debugLog(
                    "ALI_COUNTER_NO_ACTIVATION",
                    {
                        attack =
                            threat.attackType
                            or "",
                        owner =
                            threat.ownerName
                            or "",
                    },
                    true
                )
            end
        end)

        return true
    end

    function Runtime.installBroadcast()
        local env =
            getgenv and getgenv()
            or _G
        local old =
            env.SilentSolutionsAliCounterBroadcastConnection

        if old then
            pcall(function()
                old:Disconnect()
            end)

            env.SilentSolutionsAliCounterBroadcastConnection =
                nil
        end

        local shared =
            ReplicatedStorage:FindFirstChild(
                "Shared"
            )
        local network =
            shared
            and shared:FindFirstChild(
                "Network"
            )
        local broadcast =
            network
            and network:FindFirstChild(
                "CombatBroadcastURE"
            )

        if not broadcast
            or (
                not broadcast:IsA(
                    "UnreliableRemoteEvent"
                )
                and not broadcast:IsA(
                    "RemoteEvent"
                )
            )
        then
            debugLog(
                "ALI_COUNTER_LISTENER_FAIL",
                {
                    reason =
                        "CombatBroadcastURE",
                },
                true
            )
            return false
        end

        env.SilentSolutionsAliCounterBroadcastConnection =
            broadcast.OnClientEvent:Connect(
                function(
                    eventName,
                    actorName
                )
                    if eventName
                        ~= "StyleEvasiveCounter"
                    then
                        return
                    end

                    local character =
                        getCharacter()

                    if not character
                        or not character.Parent
                    then
                        return
                    end

                    if actorName
                            ~= LocalPlayer.Name
                        and actorName
                            ~= character.Name
                    then
                        return
                    end

                    local now =
                        os.clock()
                    Runtime.lastConfirmedAt =
                        now

                    local target =
                        Runtime.pendingTarget

                    if now
                        > (
                            tonumber(
                                Runtime.pendingUntil
                            ) or 0
                        )
                    then
                        target = nil
                    end

                    local pendingThreat =
                        Runtime.pendingThreat

                    if pendingThreat
                        and target
                    then
                        pendingThreat.aliCounterCommitted =
                            true
                        pendingThreat.aliCounterPending =
                            false
                        pendingThreat.fired =
                            true
                        pendingThreat.firedAt =
                            now
                    end

                    debugLog(
                        "ALI_COUNTER_CONFIRMED",
                        {
                            target =
                                target
                                and target.Name
                                or "",
                            dodgeAbuse =
                                Runtime.isDodgeAbuseEnabled(),
                            variant =
                                Runtime.getM2Variant(),
                            confirmAge =
                                now
                                - (
                                    tonumber(
                                        Runtime.lastEvasiveAt
                                    ) or now
                                ),
                        },
                        true
                    )

                    if target
                        and target.Parent
                    then
                        if Runtime.isDodgeAbuseEnabled()
                            and Runtime.getM2Variant()
                                == "Right"
                        then
                            local liveCharacter =
                                Runtime.getLocalAli()
                            local liveHumanoid =
                                liveCharacter
                                and liveCharacter:FindFirstChildOfClass(
                                    "Humanoid"
                                )
                            local keyHeld,
                                resolved,
                                moveDegrees =
                                Runtime.holdRightVariantNow(
                                    liveCharacter,
                                    liveHumanoid
                                )

                            debugLog(
                                "ALI_RIGHT_VARIANT_CONFIRMED",
                                {
                                    target =
                                        target.Name,
                                    keyHeld =
                                        keyHeld,
                                    resolved =
                                        resolved or "",
                                    moveDegrees =
                                        moveDegrees or "",
                                },
                                true
                            )
                        end

                        Runtime.faceTarget(
                            target,
                            Runtime.getRotationHold(),
                            "server-confirmed"
                        )

                        if Runtime.isDodgeAbuseEnabled()
                        then
                            Runtime.fireDodgeAbuseF(
                                target
                            )
                        end
                    end

                    Runtime.pendingTarget =
                        nil
                    Runtime.pendingThreat =
                        nil
                    Runtime.pendingUntil = 0
                end
            )

        return true
    end

    Runtime.installBroadcast()
end

local BoxingCounterRuntime = {}

do
    local boxingCounterHandledUntil = setmetatable({}, {__mode = "k"})
    local boxingCounterLastAttemptAt = 0
    local BOXING_COUNTER_ATTEMPT_GAP = 0.20
    local BOXING_COUNTER_INPUT_SAFETY = 0.006
    local BOXING_COUNTER_LATE_SAFETY = 0.004
    local BOXING_COUNTER_POST_CONTACT_HOLD = 0.14




    local function boxingCounterGetUpvalue(func, index)
        if type(func) ~= "function" then
            return nil
        end

        local getter = getupvalue or (debug and debug.getupvalue)
        if type(getter) ~= "function" then
            return nil
        end

        local result = table.pack(pcall(getter, func, index))
        if result[1] ~= true then
            return nil
        end

        if result.n >= 3 then
            return result[3]
        end
        return result[2]
    end

    local function boxingCounterDistance(target)
        local character = getCharacter()
        local myRoot = getRoot(character)
        local targetRoot = getRoot(target)

        if not myRoot or not targetRoot then
            return math.huge
        end

        return flat(targetRoot.Position - myRoot.Position).Magnitude
    end

    local function boxingCounterNumber(flagName, fallback, minimum, maximum)
        local value = tonumber(Flags[flagName]) or fallback
        return math.clamp(value, minimum, maximum)
    end

    local function getBoxingCounterRange()
        return boxingCounterNumber("ap_boxing_counter_range", 8, 3, 14)
    end

    local function getBoxingCounterLeadSeconds()
        return boxingCounterNumber("ap_boxing_counter_lead", 25, 0, 240) / 1000
    end

    local function getLocalBoxingCounterStyle(character)
        local characterStyle = getStyle(character)
        if characterStyle ~= "default" then
            return characterStyle
        end

        local ok, style = pcall(
            CombatAnimationUtils.GetPlayerCombatStyle,
            LocalPlayer
        )
        if ok and typeof(style) == "string" and style ~= "" then
            return string.lower(style:gsub("^%s+", ""):gsub("%s+$", ""))
        end

        return getStyle(character)
    end

    local function logBoxingCounterGate(threat, reason, extra)
        if not threat then
            return
        end

        local key = tostring(reason or "unknown")
        if threat.boxingCounterGateReason == key then
            return
        end
        threat.boxingCounterGateReason = key

        local data = {
            attack = threat.attackType or "",
            target = threat.ownerName or (threat.owner and threat.owner.Name) or "",
            enemyStyle = threat.style or "",
            source = threat.source or "",
            reason = key,
        }

        if type(extra) == "table" then
            for k, v in pairs(extra) do
                data[k] = v
            end
        end

        debugLog("BOXING_COUNTER_GATE", data)
    end

    local function isBoxingCounterEnabled()



        return Flags.ap_enable == true
            and (boxingCounterEnabled == true or Flags.ap_boxing_counter == true)
    end

    local function boxingM2StillHasIFrames()
        local ok, value = pcall(
            CombatConfig.GetStyleBoolean,
            "boxing",
            "M2GrantsIFrames",
            false
        )
        return ok and value == true
    end

    local function hasActiveBoxingEHit(character)
        if not character then
            return false
        end

        local packages = ReplicatedStorage:FindFirstChild("Packages")
        local moduleScript = packages and packages:FindFirstChild("AnimationHandler")
        if not moduleScript or not moduleScript:IsA("ModuleScript") then
            return false
        end

        local okRequire, handler = pcall(require, moduleScript)
        if not okRequire or type(handler) ~= "table" or type(handler.GetAnims) ~= "function" then
            return false
        end

        local okAnims, anims = pcall(handler.GetAnims, character, "EHit")
        return okAnims and type(anims) == "table" and next(anims) ~= nil
    end

    local function getBoxingM2InternalReadyIn(module)
        if not module or type(module.OnM2Activated) ~= "function" then
            return math.huge, "m2_module"
        end

        local activate = module.OnM2Activated
        local internalReady = boxingCounterGetUpvalue(activate, 2)
        if internalReady == false then
            return math.huge, "m2_internal_cooldown"
        end

        local now = os.clock()
        local readyIn = 0
        local lockReason = nil



        for index = 4, 6 do
            local lockUntil = boxingCounterGetUpvalue(activate, index)
            if typeof(lockUntil) == "number" and lockUntil > now then
                local remaining = lockUntil - now
                if remaining > readyIn then
                    readyIn = remaining
                    lockReason = index == 4 and "parry_lockout"
                        or (index == 5 and "block_lockout" or "attempt_lockout")
                end
            end
        end

        return readyIn, lockReason
    end

    local function getBoxingCounterEligibility(character, reservePhase)
        if not character or not character.Parent then
            return false, "no_character"
        end

        if not isBoxingCounterEnabled() then
            return false, "disabled"
        end

        if getLocalBoxingCounterStyle(character) ~= "boxing" then
            return false, "local_style"
        end

        if character:GetAttribute("Equip") == false then
            return false, "not_equipped"
        end

        if not boxingM2StillHasIFrames() then
            return false, "boxing_m2_no_iframes"
        end

        if character:GetAttribute("M2") == true
            or character:GetAttribute("PendingM2") == true
        then
            return false, "m2_busy"
        end

        if character:GetAttribute("M2Cooldown") == true then
            return false, "m2_cooldown"
        end

        local humanoid = character:FindFirstChildOfClass("Humanoid")
        if not humanoid or humanoid.Health <= 0 then
            return false, "dead"
        end

        local module = getCombatModule("M2")
        if not module or type(module.OnM2Activated) ~= "function" then
            return false, "m2_module"
        end

        local readyIn, readyReason = getBoxingM2InternalReadyIn(module)
        if readyIn == math.huge then
            return false, readyReason or "m2_internal_cooldown", module, readyIn
        end





        if reservePhase ~= true then
            if character:GetAttribute("SpecTimeSlowed") == true then
                return false, "spec_time_slowed", module, readyIn
            end
            if character:GetAttribute("GuardBroken") == true then
                return false, "guard_broken", module, readyIn
            end
            if character:GetAttribute("Stunned") == true then
                return false, "stunned", module, readyIn
            end
            if character:GetAttribute("Ragdoll") == true then
                return false, "ragdoll", module, readyIn
            end
            if character:GetAttribute("GrappleWinnerStun") == true then
                return false, "grapple_winner_stun", module, readyIn
            end
            if character:GetAttribute("Grappling") == true then
                return false, "grappling", module, readyIn
            end
            if character:GetAttribute("Greenzone") == true then
                return false, "greenzone", module, readyIn
            end
            if character:GetAttribute("RpCombatLocked") == true then
                return false, "rp_combat_locked", module, readyIn
            end
            if character:GetAttribute("CantAnything") == true
                and character:GetAttribute("CombatRecovery") ~= true
            then
                return false, "cant_anything", module, readyIn
            end
            if hasActiveBoxingEHit(character) then
                return false, "ehit", module, readyIn
            end
        end

        return true, readyReason, module, readyIn
    end

    local function preemptBoxingCounterM1(character)
        if not character or not character.Parent then
            return
        end

        if character:GetAttribute("M1") == true
            or character:GetAttribute("M1Hold") == true
            or character:GetAttribute("PendingM1") == true
            or character:GetAttribute("CombatAttacking") == true
        then
            local m1Module = getCombatModule("M1")
            if m1Module and type(m1Module.Hold) == "function" then
                pcall(m1Module.Hold, "Stop")
            end
        end
    end

    local function prepareBoxingCounterInput(character)
        if not character or not character.Parent then
            return false, "no_character"
        end



        if character:GetAttribute("Blocking") == true
            or character:GetAttribute("PerfectBlocking") == true
        then
            local blockModule = getCombatModule("Block")
            if not blockModule or type(blockModule.Unblock) ~= "function" then
                return false, "block_module"
            end

            pcall(blockModule.Unblock)
        end




        if character:GetAttribute("M1") == true
            or character:GetAttribute("M1Hold") == true
            or character:GetAttribute("PendingM1") == true
        then
            local m1Module = getCombatModule("M1")
            if m1Module and type(m1Module.Hold) == "function" then
                pcall(m1Module.Hold, "Stop")
            end
        end

        return true
    end

    local function canStartBoxingCounterNow(character, module)
        if character:GetAttribute("SpecTimeSlowed") == true then
            return false, "spec_time_slowed"
        end
        if character:GetAttribute("M2Cooldown") == true then
            return false, "m2_cooldown"
        end
        if character:GetAttribute("CombatAttacking") == true then
            return false, "combat_attacking"
        end
        if character:GetAttribute("GuardBroken") == true then
            return false, "guard_broken"
        end
        if character:GetAttribute("CantAnything") == true
            and character:GetAttribute("CombatRecovery") ~= true
        then
            return false, "cant_anything"
        end
        if character:GetAttribute("Stunned") == true then
            return false, "stunned"
        end
        if character:GetAttribute("Ragdoll") == true then
            return false, "ragdoll"
        end
        if character:GetAttribute("Blocking") == true then
            return false, "blocking"
        end
        if character:GetAttribute("ParryAttackLockout") == true then
            return false, "parry_attack_lockout"
        end
        if character:GetAttribute("BlockAttackLockout") == true then
            return false, "block_attack_lockout"
        end
        if character:GetAttribute("GrappleWinnerStun") == true then
            return false, "grapple_winner_stun"
        end
        if character:GetAttribute("Grappling") == true then
            return false, "grappling"
        end
        if hasActiveBoxingEHit(character) then
            return false, "ehit"
        end
        if character:GetAttribute("Equip") == false then
            return false, "not_equipped"
        end
        if character:GetAttribute("Greenzone") == true then
            return false, "greenzone"
        end
        if character:GetAttribute("RpCombatLocked") == true then
            return false, "rp_combat_locked"
        end

        local readyIn, readyReason = getBoxingM2InternalReadyIn(module)
        if readyIn == math.huge then
            return false, readyReason or "m2_internal_cooldown"
        end
        if readyIn > 0.003 then
            return false, readyReason or "m2_lockout"
        end

        return true
    end

    local function fireBoxingCounterM2(target, threat, prediction)
        local character = getCharacter()
        local eligible, reason, module = getBoxingCounterEligibility(character, false)
        if not eligible then
            return false, reason
        end

        if os.clock() - boxingCounterLastAttemptAt < BOXING_COUNTER_ATTEMPT_GAP then
            return false, "attempt_gap"
        end

        local prepared, prepareReason = prepareBoxingCounterInput(character)
        if not prepared then
            return false, prepareReason
        end




        local handoffDeadline = os.clock() + 0.060
        while os.clock() < handoffDeadline
            and (
                character:GetAttribute("CombatAttacking") == true
                or character:GetAttribute("Blocking") == true
                or character:GetAttribute("ParryAttackLockout") == true
                or character:GetAttribute("BlockAttackLockout") == true
            ) do
            RunService.Heartbeat:Wait()
        end

        local canStart, startReason = canStartBoxingCounterNow(character, module)
        if not canStart then
            return false, startReason
        end

        local beforeInternalReady = boxingCounterGetUpvalue(module.OnM2Activated, 2)
        local before = {
            m2 = character:GetAttribute("M2"),
            pending = character:GetAttribute("PendingM2"),
            combat = character:GetAttribute("CombatAttacking"),
            cooldown = character:GetAttribute("M2Cooldown"),
        }

        boxingCounterLastAttemptAt = os.clock()
        local breakerPrimed = markAutoParryScriptedAttack(
            "M2",
            "boxing_counter"
        )

        if breakerPrimed
            and Menu._APBreakerRuntime
            and type(Menu._APBreakerRuntime.waitForCommitWindow) == "function"
        then
            Menu._APBreakerRuntime.waitForCommitWindow(
                "M2",
                "boxing_counter"
            )
        end

        local ok, err = pcall(module.OnM2Activated)
        if not ok then
            return false, "activate_error:" .. tostring(err)
        end



        local afterInternalReady = boxingCounterGetUpvalue(module.OnM2Activated, 2)
        local internalReadyEdge = beforeInternalReady == true
            and afterInternalReady == false

        local cooldown = character:GetAttribute("M2Cooldown")
        local attributeEdge =
            (before.m2 ~= true and character:GetAttribute("M2") == true)
            or (before.pending ~= true and character:GetAttribute("PendingM2") == true)
            or (before.combat ~= true and character:GetAttribute("CombatAttacking") == true)
            or (
                before.cooldown ~= true
                and (
                    cooldown == true
                    or (typeof(cooldown) == "number" and cooldown > 0)
                )
            )

        if not internalReadyEdge and not attributeEdge then
            return false, "no_start"
        end

        debugLog("BOXING_COUNTER_FIRE", {
            attack = threat and threat.attackType or "",
            target = target and target.Name or "",
            enemyStyle = threat and threat.style or "",
            source = threat and threat.source or "",
            distance = target and boxingCounterDistance(target) or 0,
            counterRange = getBoxingCounterRange(),
            counterLeadMs = math.floor(getBoxingCounterLeadSeconds() * 1000 + 0.5),
            networkLeadMs = threat and math.floor((threat.boxingCounterNetworkLead or 0) * 1000 + 0.5) or 0,
            effectiveLeadMs = threat and math.floor((threat.boxingCounterEffectiveLead or 0) * 1000 + 0.5) or 0,
            internalReadyEdge = internalReadyEdge,
            attributeEdge = attributeEdge,
            contactIn = prediction and math.max(
                0,
                (prediction.contactAbs or os.clock()) - os.clock()
            ) or 0,
        }, true)

        return true
    end

    local boxingCounterLastStateKey = nil

    local function tryBoxingCounter(threat, prediction, context, now)
        local stateKey = tostring(Flags.ap_enable == true)
            .. ":" .. tostring(Flags.ap_boxing_counter == true)
            .. ":" .. tostring(boxingCounterEnabled == true)
        if stateKey ~= boxingCounterLastStateKey then
            boxingCounterLastStateKey = stateKey
            debugLog("BOXING_COUNTER_STATE", {
                autoParry = Flags.ap_enable == true,
                flag = Flags.ap_boxing_counter == true,
                runtimeEnabled = boxingCounterEnabled == true,
                active = isBoxingCounterEnabled(),
                mode = "M2_ONLY",
            }, true)
        end

        if not isBoxingCounterEnabled()
            or not threat
            or threat.expired == true
            or threat.attackType ~= "M2"
        then
            return false
        end

        now = now or os.clock()

        if now < (threat.boxingCounterRetryAt or 0) then
            return false
        end

        local target = threat.owner or resolveOwner(threat)
        if not target or not target.Parent then
            return false
        end

        local handledUntil = boxingCounterHandledUntil[target] or 0
        if handledUntil > now then
            return threat.boxingCounterCommitted == true
        end

        if threat.boxingCounterCommitted == true then
            return now <= (threat.boxingCounterHoldUntil or now)
        end


        local styleConfig
        pcall(function()
            styleConfig = CombatConfig.GetStyleConfig(
                threat.style or getStyle(target)
            )
        end)

        if threat.attackType == "M2"
            and styleConfig
            and styleConfig.M2RequiresCounterHit == true
        then
            if threat.boxingCounterSkipLogged ~= true then
                threat.boxingCounterSkipLogged = true
                debugLog("BOXING_COUNTER_SKIP", {
                    attack = threat.attackType,
                    target = target.Name,
                    enemyStyle = threat.style or "",
                    reason = "target_counter_stance",
                })
            end
            return false
        end

        local localCharacter = getCharacter()
        local eligible, readyReason, _, readyIn =
            getBoxingCounterEligibility(localCharacter, true)

        if not eligible then
            logBoxingCounterGate(threat, readyReason or "not_ready", {
                localStyle = localCharacter
                    and getLocalBoxingCounterStyle(localCharacter)
                    or "",
                equip = localCharacter
                    and localCharacter:GetAttribute("Equip")
                    or nil,
                m2 = localCharacter
                    and localCharacter:GetAttribute("M2")
                    or nil,
                pendingM2 = localCharacter
                    and localCharacter:GetAttribute("PendingM2")
                    or nil,
                m2Cooldown = localCharacter
                    and localCharacter:GetAttribute("M2Cooldown")
                    or nil,
                readyIn = readyIn,
            })
            return false
        end

        local distance = context and context.distance or boxingCounterDistance(target)
        local contactAbs = tonumber(prediction and prediction.contactAbs) or now
        local contactIn = math.max(0, contactAbs - now)
        local closing = math.max(0, tonumber(prediction and prediction.closing) or 0)
        local projectedDistance = math.max(0, distance - closing * contactIn)
        local counterRange = getBoxingCounterRange()

        if distance > counterRange and projectedDistance > counterRange then
            return false
        end

        local userLead = getBoxingCounterLeadSeconds()
        local networkLead = math.clamp(
            math.max(0, tonumber(prediction and prediction.up) or 0),
            0,
            0.18
        )
        local normalParryLead = math.max(
            0,
            tonumber(prediction and prediction.target) or 0
        ) + math.max(
            0,
            tonumber(prediction and prediction.lookahead) or 0
        )




        local effectiveLead = userLead
            + networkLead
            + normalParryLead
            + BOXING_COUNTER_INPUT_SAFETY
        local fireAt = contactAbs - effectiveLead
        local latestServerSafeAt =
            contactAbs - networkLead - BOXING_COUNTER_LATE_SAFETY

        if typeof(readyIn) == "number"
            and readyIn > math.max(0, fireAt - now) + 0.010
        then
            logBoxingCounterGate(threat, readyReason or "m2_lockout", {
                readyIn = readyIn,
                fireIn = fireAt - now,
                contactIn = contactIn,
            })
            return false
        end

        if now > latestServerSafeAt then
            if threat.boxingCounterLateLogged ~= true then
                threat.boxingCounterLateLogged = true
                debugLog("BOXING_COUNTER_SKIP", {
                    attack = threat.attackType,
                    target = target.Name,
                    enemyStyle = threat.style or "",
                    source = threat.source or "",
                    reason = "late_for_server",
                    contactIn = contactIn,
                    networkLead = networkLead,
                })
            end
            return false
        end


        threat.boxingCounterFireAt = fireAt
        threat.boxingCounterContactAbs = contactAbs
        threat.boxingCounterLatestServerSafeAt = latestServerSafeAt
        threat.boxingCounterNetworkLead = networkLead
        threat.boxingCounterNormalParryLead = normalParryLead
        threat.boxingCounterEffectiveLead = effectiveLead
        threat.boxingCounterPrediction = prediction

        if threat.boxingCounterTaskArmed == true then

            return false
        end

        threat.boxingCounterTaskArmed = true
        threat.boxingCounterGateReason = nil

        debugLog("BOXING_COUNTER_ARM", {
            attack = threat.attackType,
            target = target.Name,
            enemyStyle = threat.style or "",
            source = threat.source or "",
            distance = distance,
            projectedDistance = projectedDistance,
            counterRange = counterRange,
            counterLeadMs = math.floor(userLead * 1000 + 0.5),
            normalParryLeadMs = math.floor(normalParryLead * 1000 + 0.5),
            networkLeadMs = math.floor(networkLead * 1000 + 0.5),
            effectiveLeadMs = math.floor(effectiveLead * 1000 + 0.5),
            contactIn = contactIn,
            fireIn = fireAt - now,
            readyIn = readyIn,
        })

        task.spawn(function()
            while threat.boxingCounterTaskArmed == true do
                if not isBoxingCounterEnabled()
                    or not target.Parent
                    or threat.expired == true
                then
                    threat.boxingCounterTaskArmed = false
                    return
                end

                if threat.boxingCounterCommitted == true then
                    threat.boxingCounterTaskArmed = false
                    return
                end



                if threat.fired == true then
                    debugLog("BOXING_COUNTER_SKIP", {
                        attack = threat.attackType,
                        target = target.Name,
                        enemyStyle = threat.style or "",
                        source = threat.source or "",
                        reason = "ap_fallback_already_fired",
                    })
                    threat.boxingCounterTaskArmed = false
                    return
                end

                local scheduledAt = tonumber(threat.boxingCounterFireAt) or os.clock()
                local untilFire = scheduledAt - os.clock()




                if untilFire <= 0.09
                    and threat.boxingCounterPreempted ~= true
                then
                    threat.boxingCounterPreempted = true
                    preemptBoxingCounterM1(getCharacter())

                    debugLog("BOXING_COUNTER_PREP", {
                        attack = threat.attackType,
                        target = target.Name,
                        enemyStyle = threat.style or "",
                        source = threat.source or "",
                        fireIn = untilFire,
                    })
                end

                if os.clock() >= scheduledAt then
                    break
                end

                RunService.Heartbeat:Wait()
            end

            threat.boxingCounterTaskArmed = false

            if threat.expired == true
                or threat.fired == true
                or threat.attackType ~= "M2"
                or not isBoxingCounterEnabled()
                or not target.Parent
            then
                return
            end

            local fireNow = os.clock()
            local safeUntil = tonumber(threat.boxingCounterLatestServerSafeAt)
                or fireNow




            local liveDistance = boxingCounterDistance(target)
            while liveDistance > getBoxingCounterRange()
                and os.clock() < safeUntil
                and target.Parent
                and threat.fired ~= true
            do
                RunService.Heartbeat:Wait()
                liveDistance = boxingCounterDistance(target)
            end

            if threat.fired == true then
                return
            end

            if liveDistance > getBoxingCounterRange() then
                debugLog("BOXING_COUNTER_SKIP", {
                    attack = threat.attackType,
                    target = target.Name,
                    enemyStyle = threat.style or "",
                    source = threat.source or "",
                    reason = "fire_range",
                    distance = liveDistance,
                    counterRange = getBoxingCounterRange(),
                })
                return
            end

            if os.clock() > safeUntil then
                debugLog("BOXING_COUNTER_SKIP", {
                    attack = threat.attackType,
                    target = target.Name,
                    enemyStyle = threat.style or "",
                    source = threat.source or "",
                    reason = "fire_late",
                    lateBy = os.clock() - safeUntil,
                })
                return
            end

            if os.clock() - boxingCounterLastAttemptAt < BOXING_COUNTER_ATTEMPT_GAP then
                debugLog("BOXING_COUNTER_SKIP", {
                    attack = threat.attackType,
                    target = target.Name,
                    enemyStyle = threat.style or "",
                    source = threat.source or "",
                    reason = "attempt_gap",
                    remaining = BOXING_COUNTER_ATTEMPT_GAP
                        - (os.clock() - boxingCounterLastAttemptAt),
                })
                return
            end

            preemptBoxingCounterM1(getCharacter())

            local char = getCharacter()
            debugLog("BOXING_COUNTER_FIRE_ATTEMPT", {
                attack = threat.attackType,
                target = target.Name,
                enemyStyle = threat.style or "",
                source = threat.source or "",
                distance = liveDistance,
                localStyle = char and getLocalBoxingCounterStyle(char) or "",
                equip = char and char:GetAttribute("Equip") or nil,
                m1 = char and char:GetAttribute("M1") or nil,
                pendingM1 = char and char:GetAttribute("PendingM1") or nil,
                combatAttacking = char and char:GetAttribute("CombatAttacking") or nil,
                blocking = char and char:GetAttribute("Blocking") or nil,
                stunned = char and char:GetAttribute("Stunned") or nil,
                ragdoll = char and char:GetAttribute("Ragdoll") or nil,
                cantAnything = char and char:GetAttribute("CantAnything") or nil,
                combatRecovery = char and char:GetAttribute("CombatRecovery") or nil,
                m2Cooldown = char and char:GetAttribute("M2Cooldown") or nil,
                contactIn = math.max(
                    0,
                    (tonumber(threat.boxingCounterContactAbs) or os.clock())
                        - os.clock()
                ),
            }, true)

            local fired, reason = fireBoxingCounterM2(
                target,
                threat,
                threat.boxingCounterPrediction or prediction
            )

            if not fired then
                local failedChar = getCharacter()
                local _, lockReason, _, lockReadyIn =
                    getBoxingCounterEligibility(failedChar, false)

                threat.boxingCounterRetryAt = os.clock() + 0.055

                debugLog("BOXING_COUNTER_FAIL", {
                    attack = threat.attackType,
                    target = target.Name,
                    enemyStyle = threat.style or "",
                    source = threat.source or "",
                    reason = reason or lockReason or "unknown",
                    secondaryReason = lockReason or "",
                    readyIn = lockReadyIn,
                    distance = boxingCounterDistance(target),
                    localStyle = failedChar
                        and getLocalBoxingCounterStyle(failedChar)
                        or "",
                    equip = failedChar and failedChar:GetAttribute("Equip") or nil,
                    m1 = failedChar and failedChar:GetAttribute("M1") or nil,
                    pendingM1 = failedChar
                        and failedChar:GetAttribute("PendingM1")
                        or nil,
                    combatAttacking = failedChar
                        and failedChar:GetAttribute("CombatAttacking")
                        or nil,
                    cantAnything = failedChar
                        and failedChar:GetAttribute("CantAnything")
                        or nil,
                    combatRecovery = failedChar
                        and failedChar:GetAttribute("CombatRecovery")
                        or nil,
                    blocking = failedChar
                        and failedChar:GetAttribute("Blocking")
                        or nil,
                    parryAttackLockout = failedChar
                        and failedChar:GetAttribute("ParryAttackLockout")
                        or nil,
                    blockAttackLockout = failedChar
                        and failedChar:GetAttribute("BlockAttackLockout")
                        or nil,
                    stunned = failedChar
                        and failedChar:GetAttribute("Stunned")
                        or nil,
                    ragdoll = failedChar
                        and failedChar:GetAttribute("Ragdoll")
                        or nil,
                    guardBroken = failedChar
                        and failedChar:GetAttribute("GuardBroken")
                        or nil,
                    ehit = failedChar and hasActiveBoxingEHit(failedChar) or false,
                    m2 = failedChar and failedChar:GetAttribute("M2") or nil,
                    pendingM2 = failedChar
                        and failedChar:GetAttribute("PendingM2")
                        or nil,
                    m2Cooldown = failedChar
                        and failedChar:GetAttribute("M2Cooldown")
                        or nil,
                }, true)
                return
            end

            local contact = tonumber(threat.boxingCounterContactAbs) or os.clock()
            local holdUntil = math.max(
                os.clock() + 0.08,
                contact + BOXING_COUNTER_POST_CONTACT_HOLD
            )

            threat.boxingCounterCommitted = true
            threat.boxingCounterHoldUntil = holdUntil
            threat.fired = true
            threat.firedAt = os.clock()
            boxingCounterHandledUntil[target] = holdUntil + 0.20

            debugLog("BOXING_COUNTER_COMMIT", {
                attack = threat.attackType,
                target = target.Name,
                enemyStyle = threat.style or "",
                source = threat.source or "",
                holdFor = math.max(0, holdUntil - os.clock()),
                contactIn = math.max(0, contact - os.clock()),
            }, true)
        end)



        return false
    end

    BoxingCounterRuntime.try = tryBoxingCounter
    BoxingCounterRuntime.isEnabled = isBoxingCounterEnabled
    BoxingCounterRuntime.getRange = getBoxingCounterRange
    BoxingCounterRuntime.firePostWingChun = function(target)
        if not isBoxingCounterEnabled()
            or not target
            or not target.Parent
        then
            return false, "disabled"
        end

        local distance = boxingCounterDistance(target)
        if distance > getBoxingCounterRange() then
            return false, "range"
        end

        local threat = {
            source = "wingchun_post_m2",
            serverConfirmed = true,
            attackType = "M2",
            owner = target,
            ownerName = target.Name,
            style = "wingchun",
            createdAt = os.clock(),
            counterStance = false,
        }

        local now = os.clock()
        local prediction = {
            contactAbs = now,
            ping = 0,
            up = 0,
            target = 0,
            lookahead = 0,
        }

        debugLog("BOXING_COUNTER_FIRE_ATTEMPT", {
            attack = "M2",
            target = target.Name,
            enemyStyle = "wingchun",
            source = "wingchun_post_m2",
            distance = distance,
            postCounterWindow = true,
        }, true)

        local fired, reason = fireBoxingCounterM2(
            target,
            threat,
            prediction
        )

        if fired then
            boxingCounterHandledUntil[target] = os.clock() + 0.32
            debugLog("BOXING_COUNTER_COMMIT", {
                attack = "M2",
                target = target.Name,
                enemyStyle = "wingchun",
                source = "wingchun_post_m2",
                postCounterWindow = true,
            }, true)
            return true, "M2"
        end

        debugLog("BOXING_COUNTER_FAIL", {
            attack = "M2",
            target = target.Name,
            enemyStyle = "wingchun",
            source = "wingchun_post_m2",
            postCounterWindow = true,
            reason = reason or "unknown",
            distance = distance,
        }, true)

        return false, reason or "unknown"
    end
    BoxingCounterRuntime.getDebugSnapshot = function()
        local character = getCharacter()
        local snapshot = {
            active = isBoxingCounterEnabled(),
            range = getBoxingCounterRange(),
            leadMs = math.floor(getBoxingCounterLeadSeconds() * 1000 + 0.5),
            character = character,
        }

        if character then
            snapshot.style = getLocalBoxingCounterStyle(character)
            snapshot.ehit = hasActiveBoxingEHit(character)

            local module = getCombatModule("M2")
            snapshot.module = module ~= nil
            if module and type(module.OnM2Activated) == "function" then
                snapshot.internalReady = boxingCounterGetUpvalue(module.OnM2Activated, 2)
                snapshot.readyIn, snapshot.readyReason =
                    getBoxingM2InternalReadyIn(module)

                local now = os.clock()
                for index = 4, 6 do
                    local value = boxingCounterGetUpvalue(module.OnM2Activated, index)
                    snapshot["lock" .. tostring(index)] = value
                    snapshot["lock" .. tostring(index) .. "Remaining"] =
                        typeof(value) == "number"
                            and math.max(0, value - now)
                            or nil
                end
            end
        end

        return snapshot
    end
end

buildAutoParryDebugExtra = function()
    local lines = {
        "[LOCAL COMBAT STATE]",
    }

    local character = getCharacter()
    if not character or not character.Parent then
        lines[#lines + 1] = "Character: nil"
        lines[#lines + 1] = ""
        return lines
    end

    local humanoid = character:FindFirstChildOfClass("Humanoid")
    local snapshot = {}
    if type(BoxingCounterRuntime.getDebugSnapshot) == "function" then
        local okSnapshot, result = pcall(BoxingCounterRuntime.getDebugSnapshot)
        if okSnapshot and type(result) == "table" then
            snapshot = result
        else
            snapshot.snapshotError = tostring(result)
        end
    end

    local localAttackDebug =
        Menu._AutoParryLocalAttackDebug or {}
    local currentMyStyle = tostring(getStyle(character) or snapshot.style)
    localAttackDebug.style =
        currentMyStyle

    lines[#lines + 1] = "Character: " .. tostring(character.Name)
    lines[#lines + 1] = "Style: " .. currentMyStyle
    lines[#lines + 1] = "MyFightingStyle: " .. currentMyStyle
    lines[#lines + 1] = "ManualM1Count: "
        .. tostring(localAttackDebug.manualM1Count or 0)
    lines[#lines + 1] = "ManualM2Count: "
        .. tostring(localAttackDebug.manualM2Count or 0)
    lines[#lines + 1] = "ScriptedM1Count: "
        .. tostring(localAttackDebug.scriptedM1Count or 0)
    lines[#lines + 1] = "ScriptedM2Count: "
        .. tostring(localAttackDebug.scriptedM2Count or 0)
    lines[#lines + 1] = "LastManualAttack: "
        .. tostring(localAttackDebug.lastManualAttack or "")

