        )
    lines[#lines + 1] = "Health: " .. tostring(humanoid and humanoid.Health or "nil")

    local stateAttrs = {
        "Equip",
        "M1",
        "M1Hold",
        "PendingM1",
        "M1Cooldown",
        "M2",
        "PendingM2",
        "M2Cooldown",
        "IFRAMES",
        "IFRAMECD",
        "EvasiveCooldownRemaining",
        "OutnumberedEvasiveGrant",
        "CounterLocked",
        "CombatAttacking",
        "Blocking",
        "PerfectBlocking",
        "CantAnything",
        "CombatRecovery",
        "Stunned",
        "Ragdoll",
        "GuardBroken",
        "Downed",
        "ParryAttackLockout",
        "BlockAttackLockout",
        "Grappling",
        "GrappleWinnerStun",
        "SpecTimeSlowed",
        "Greenzone",
        "RpCombatLocked",
    }

    for _, attr in ipairs(stateAttrs) do
        lines[#lines + 1] =
