    lines[#lines + 1] = "BoxingEHitActive: " .. tostring(snapshot.ehit == true)
    lines[#lines + 1] = ""
    lines[#lines + 1] = "[OPPONENTS FOUGHT]"

    local opponentNames = {}
    for ownerName in pairs(Menu._AutoParryDebugOpponents) do
