        lines[#lines + 1] =
            "  LifecycleDesyncObserved: "
            .. tostring(
                opponent
                and opponent.lifecycleDesyncObserved
                == true
            )
        lines[#lines + 1] =
            "  AutoParryBreakerObserved: "
            .. tostring(
                opponent
                and opponent.autoParryBreakerObserved
                == true
            )
        lines[#lines + 1] =
            "  AutoParryBreakerBaits: "
            .. tostring(
                opponent
                and tonumber(opponent.autoParryBreakerBaits)
                or 0
            )
        lines[#lines + 1] =
            "  HeightStuds: "
            .. (
                height
                and string.format("%.3f", height)
                or "unknown"
            )
        lines[#lines + 1] =
            "  HeightDifferenceStuds: "
            .. (
                heightDiff
                and string.format("%+.3f", heightDiff)
                or "unknown"
            )
        lines[#lines + 1] =
            "  DistanceNowStuds: "
            .. (
                distanceNow
                and string.format("%.3f", distanceNow)
                or "unavailable"
            )
        lines[#lines + 1] =
            "  LastObservedDistanceStuds: "
            .. (
                opponent
                and tonumber(opponent.lastDistance)
                and string.format(
                    "%.3f",
                    tonumber(opponent.lastDistance)
                )
                or "unknown"
            )
        lines[#lines + 1] =
            "  ClosestObservedDistanceStuds: "
            .. (
                opponent
                and tonumber(opponent.closestDistance)
                and string.format(
                    "%.3f",
                    tonumber(opponent.closestDistance)
                )
                or "unknown"
            )
        lines[#lines + 1] =
            "  FarthestObservedDistanceStuds: "
            .. (
                opponent
                and tonumber(opponent.farthestDistance)
                and string.format(
                    "%.3f",
                    tonumber(opponent.farthestDistance)
                )
                or "unknown"
            )
        lines[#lines + 1] =
            "  CombatEventsObserved: "
            .. tostring(
                opponent
                and opponent.events
                or 0
            )
        lines[#lines + 1] =
            "  LastFacingOpponent: "
            .. tostring(
                opponent
                and opponent.lastFacingOpponent
            )
        lines[#lines + 1] =
            "  LastFacingDot: "
            .. tostring(
                opponent
                and opponent.lastFacingDot
                or ""
            )
        lines[#lines + 1] =
            "  LastFacingAngleDeg: "
            .. tostring(
                opponent
                and opponent.lastFacingAngle
                and string.format(
                    "%.2f",
                    opponent.lastFacingAngle
                )
                or ""
            )
        lines[#lines + 1] =
            "  LastAttackerFacingMe: "
            .. tostring(
                opponent
                and opponent.lastAttackerFacingOpponent
            )
        lines[#lines + 1] =
            "  LastAttackerFacingDot: "
            .. tostring(
                opponent
                and opponent.lastAttackerFacingDot
                or ""
            )
        lines[#lines + 1] =
            "  LastAttackerFacingAngleDeg: "
            .. tostring(
                opponent
                and opponent.lastAttackerFacingAngle
                and string.format(
                    "%.2f",
                    opponent.lastAttackerFacingAngle
                )
                or ""
