                and math.floor(dodgeSnapshot.iframeDuration * 1000 + 0.5)
                or ""
        )
    lines[#lines + 1] = "SourceDashDurationMs: "
        .. tostring(
            dodgeSnapshot.dashDuration
                and math.floor(dodgeSnapshot.dashDuration * 1000 + 0.5)
                or ""
        )
    lines[#lines + 1] = "SnapshotError: "
        .. tostring(dodgeSnapshot.snapshotError or "")
    lines[#lines + 1] = ""

    return lines
end

local boxingCounterRuntimeLastError = ""
local boxingCounterRuntimeLastErrorAt = 0

local function tryBoxingCounterSafe(threat, prediction, context, now)
    local handler = BoxingCounterRuntime.try
    if type(handler) ~= "function" then
        return false
    end

    local ok, result = pcall(handler, threat, prediction, context, now)
    if not ok then
        local errorText = tostring(result)
        local clockNow = os.clock()

        if errorText ~= boxingCounterRuntimeLastError
            or clockNow - boxingCounterRuntimeLastErrorAt >= 1
        then
            boxingCounterRuntimeLastError = errorText
            boxingCounterRuntimeLastErrorAt = clockNow

            debugLog("BOXING_COUNTER_RUNTIME_ERROR", {
                error = errorText,
                attack = threat and threat.attackType or "",
                owner = threat and threat.ownerName or "",
                style = threat and threat.style or "",
                source = threat and threat.source or "",
            }, true)
        end



        return false
    end

    return result == true
end

Menu._DodgeRuntime = Menu._DodgeRuntime or {}

do
    local DodgeRuntime = Menu._DodgeRuntime

    local SOURCE_IFRAME_DURATION =
        math.max(0.05, tonumber(CombatConfig.Evasive.IFrameDuration) or 0.30)
    local SOURCE_DASH_DURATION =
        math.max(0.05, tonumber(CombatConfig.Evasive.DashDuration) or 0.20)
    local SOURCE_SERVER_CONFIRM =
        math.max(
            0.05,
            tonumber(
                CombatConfig.ClientPredict
                    and CombatConfig.ClientPredict.Evasive
                    and CombatConfig.ClientPredict.Evasive.ServerConfirmTimeout
            ) or 0.18
        )

    local function beginEvasiveAnimationYield()
        if Flags.misc_animations ~= true then
            return nil
        end

        local playerModRuntime = Menu._PlayerModRuntime
        if not playerModRuntime
            or type(playerModRuntime.beginEvasiveAnimationSuppression) ~= "function"
        then
            return nil
        end

        local hold = math.max(
            SOURCE_IFRAME_DURATION,
            SOURCE_DASH_DURATION
        ) + 0.085

        local ok, serial = pcall(
            playerModRuntime.beginEvasiveAnimationSuppression,
            hold
        )

        if ok then
            return serial
        end

        return nil
    end

    local function endEvasiveAnimationYield(serial)
        if serial == nil then
            return
        end

        local playerModRuntime = Menu._PlayerModRuntime
        if playerModRuntime
            and type(playerModRuntime.endEvasiveAnimationSuppression) == "function"
        then
            pcall(
                playerModRuntime.endEvasiveAnimationSuppression,
                serial
            )
        end
    end

    DodgeRuntime.lastAttemptAt = DodgeRuntime.lastAttemptAt or 0
    DodgeRuntime.shutdownRequested = false
    DodgeRuntime.specialReservations = DodgeRuntime.specialReservations or {}
    DodgeRuntime.specialResourceGuard =
        DodgeRuntime.specialResourceGuard
        or {
            untilAt = 0,
            ownerName = "",
            kind = "",
        }
    DodgeRuntime.inputLockSerial = DodgeRuntime.inputLockSerial or 0
    Menu._DodgeInputCAS = Menu._DodgeInputCAS
        or game:GetService("ContextActionService")

    DodgeRuntime.lockAutomaticDirection = function(character, direction)
        DodgeRuntime.inputLockSerial += 1
        local serial = DodgeRuntime.inputLockSerial
        local actionName = "SilentSolutionsAutoDodgeDirection"

        if DodgeRuntime.inputLockConnection then
            DodgeRuntime.inputLockConnection:Disconnect()
            DodgeRuntime.inputLockConnection = nil
        end

        if DodgeRuntime.inputLockControls then
            pcall(
                DodgeRuntime.inputLockControls.Enable,
                DodgeRuntime.inputLockControls
            )
            DodgeRuntime.inputLockControls = nil
        end

        pcall(function()
            Menu._DodgeInputCAS:UnbindAction(actionName)
        end)

        pcall(function()
            Menu._DodgeInputCAS:BindActionAtPriority(
                actionName,
                function()
                    return Enum.ContextActionResult.Sink
                end,
                false,
                10000,
                Enum.KeyCode.W,
                Enum.KeyCode.A,
                Enum.KeyCode.S,
                Enum.KeyCode.D,
                Enum.KeyCode.Up,
                Enum.KeyCode.Down,
                Enum.KeyCode.Left,
                Enum.KeyCode.Right,
                Enum.KeyCode.Thumbstick1,
                Enum.KeyCode.DPadUp,
                Enum.KeyCode.DPadDown,
                Enum.KeyCode.DPadLeft,
                Enum.KeyCode.DPadRight
            )
        end)

        pcall(function()
            local playerModule =
                require(
                    LocalPlayer.PlayerScripts:WaitForChild(
                        "PlayerModule",
                        0.05
                    )
                )
            local controls = playerModule:GetControls()

            if controls then
                controls:Disable()
                DodgeRuntime.inputLockControls = controls
            end
        end)

        local humanoid = character
            and character:FindFirstChildOfClass("Humanoid")
        local forcedDirection =
            typeof(direction) == "Vector3"
            and direction.Magnitude > 0.05
            and direction.Unit
            or Vector3.new(0, 0, -1)

        local function forceDirection()
            if serial ~= DodgeRuntime.inputLockSerial then
                return
            end

            if humanoid
                and humanoid.Parent
                and character
                and character.Parent
            then
                pcall(
                    humanoid.Move,
                    humanoid,
                    forcedDirection,
                    false
                )
            end
        end

        forceDirection()

        DodgeRuntime.inputLockConnection =
            RunService.PreSimulation:Connect(forceDirection)

        return serial
    end

    DodgeRuntime.unlockAutomaticDirection = function(serial)
        if serial ~= DodgeRuntime.inputLockSerial then
            return
        end

        if DodgeRuntime.inputLockConnection then
            DodgeRuntime.inputLockConnection:Disconnect()
            DodgeRuntime.inputLockConnection = nil
        end

        if DodgeRuntime.inputLockControls then
            pcall(
                DodgeRuntime.inputLockControls.Enable,
                DodgeRuntime.inputLockControls
            )
            DodgeRuntime.inputLockControls = nil
        end

        pcall(function()
            Menu._DodgeInputCAS:UnbindAction(
                "SilentSolutionsAutoDodgeDirection"
            )
        end)
    end

    DodgeRuntime.reserveSpecial = function(ownerName, kind, contactAbs)
        ownerName = tostring(ownerName or "")
        if ownerName == "" then
            return
        end

        local now = os.clock()
        DodgeRuntime.specialReservations[ownerName] = {
            kind = tostring(kind or ""),
            untilAt = math.max(now + 0.12, (tonumber(contactAbs) or now) + 0.12),
        }
    end

    DodgeRuntime.guardSpecialResource = function(
        ownerName,
        kind,
        contactAbs
    )
        local now = os.clock()
        local guard = DodgeRuntime.specialResourceGuard
        local untilAt = math.max(
            now + 0.10,
            (tonumber(contactAbs) or now) + 0.10
        )
        local changed =
            tostring(guard.ownerName or "") ~= tostring(ownerName or "")
            or tostring(guard.kind or "") ~= tostring(kind or "")

        guard.untilAt = math.max(
            tonumber(guard.untilAt) or 0,
            untilAt
        )
        guard.ownerName = tostring(ownerName or "")
        guard.kind = tostring(kind or "")

        if changed then
            debugLog("DODGE_SPECIAL_RESOURCE_GUARD", {
                owner = guard.ownerName,
                kind = guard.kind,
                holdFor = math.max(0, guard.untilAt - now),
            }, true)
        end
    end

    DodgeRuntime.getSpecialResourceGuard = function(now)
        now = now or os.clock()

        local guard = DodgeRuntime.specialResourceGuard
        if not guard
            or now >= (tonumber(guard.untilAt) or 0)
        then
            if guard then
                guard.untilAt = 0
                guard.ownerName = ""
                guard.kind = ""
            end
            return nil
        end

        return guard
    end

    DodgeRuntime.getSpecialReservation = function(threat, now)
        if not threat or threat.attackType ~= "M2" then
            return nil
        end

        local ownerName = tostring(threat.ownerName or "")
        if ownerName == "" and threat.owner then
            ownerName = tostring(threat.owner.Name or "")
        end

        local reservation = DodgeRuntime.specialReservations[ownerName]
        if not reservation then
            return nil
        end

        now = now or os.clock()
        if now >= (tonumber(reservation.untilAt) or 0) then
            DodgeRuntime.specialReservations[ownerName] = nil
            return nil
        end

        return reservation
    end

    DodgeRuntime.preparePriorityHandoff = function(character)
        if not character or not character.Parent then
            return
        end

        if Menu._apBlockActive == true
            and type(Menu._releaseAutoBlockForDodge) == "function"
        then
            pcall(Menu._releaseAutoBlockForDodge)
        end

        if character:GetAttribute("M1") == true
            or character:GetAttribute("M1Hold") == true
            or character:GetAttribute("PendingM1") == true
        then
            local module = getCombatModule("M1")
            if module and type(module.Hold) == "function" then
                pcall(module.Hold, "Stop")
            end
        end
    end

    local function dodgeNumber(flag, fallback, minimum, maximum)
        local value = tonumber(Flags[flag])
        if value == nil then
            value = fallback
        end
        return math.clamp(value, minimum, maximum)
    end

    local function autoIFrameWindowMs()
        local value = math.floor(
            math.clamp(SOURCE_IFRAME_DURATION * 1000, 120, 500) + 0.5
        )

        Flags.dodge_auto_iframe_window = true
        Flags.dodge_iframe_window = value
        DodgeRuntime.autoIFrameWindowMs = value

        return value
    end

    DodgeRuntime.getAutoIFrameWindowMs = autoIFrameWindowMs
    autoIFrameWindowMs()

    local function dodgeEnabled()
        return Flags.dodge_enable == true
            and DodgeRuntime.shutdownRequested ~= true
    end

    local function selectedInMustDodgeList(label)
        local value = Flags.dodge_must_dodge_list

        if type(value) ~= "table" then
            return false
        end

        if value[label] == true then
            return true
        end

        local wanted = string.lower(tostring(label or ""))

        for key, selected in pairs(value) do
            local keyText = string.lower(tostring(key or ""))
            local selectedText = string.lower(tostring(selected or ""))

            if selected == true and keyText == wanted then
                return true
            end

            if selectedText == wanted then
                return true
            end

            if keyText == wanted
                and selected ~= false
                and selected ~= nil
            then
                return true
            end
        end

        return false
    end

    local function styleDisplayName(style)
        local names = {
            ali = "Ali",
            basic = "Basic",
            boxing = "Boxing",
            capoeira = "Capoeira",
            cqc = "CQC",
            closequarterscombat = "CQC",
            ["close quarters combat"] = "CQC",
            hakari = "Hakari",
            karate = "Karate",
            kickboxing = "Kickboxing",
            ["kick boxing"] = "Kickboxing",
            kyokushin = "Kyokushin",
            kyokushinkarate = "Kyokushin",
            ["kyokushin karate"] = "Kyokushin",
            kure = "Kure",
            muaythai = "Muay Thai",
            slugger = "Slugger",
            striker = "Striker",
            wingchun = "Wing Chun",
            wrestling = "Wrestling",
        }

        local key = normalizeCombatStyleKey(tostring(style or ""))
        return names[key]
            or tostring(style or "Unknown")
    end

    local function getMustDodgeLabel(threat)
        if not threat or threat.attackType ~= "M2" then
            return nil
        end

        local style = string.lower(tostring(
            threat.style or getStyle(threat.owner) or ""
        ))
        if style == "cqc" then
            return nil
        end

        return styleDisplayName(threat.style or getStyle(threat.owner)) .. " M2"
    end

    local function getStatesFolderBlockReason(character)
        local states = character and character:FindFirstChild("States")
        if not states then
            return nil
        end

        local beingCarried = states:FindFirstChild("BeingCarried")
        if beingCarried
            and beingCarried:IsA("ObjectValue")
            and beingCarried.Value ~= nil
        then
            return "being_carried"
        end

        local beingGripped = states:FindFirstChild("BeingGripped")
        if beingGripped
            and beingGripped:IsA("ObjectValue")
            and beingGripped.Value ~= nil
        then
            return "being_gripped"
        end

        return nil
    end



    local function canParryNow(character)
        if not character or not character.Parent then
            return false, "local_missing"
        end

        if character:GetAttribute("Equip") ~= true then
            return false, "not_equipped"
        end
        if character:GetAttribute("Ragdoll") == true then
            return false, "ragdoll"
        end
        if character:GetAttribute("GuardBroken") == true then
            return false, "guard_broken"
        end
        if character:GetAttribute("Downed") == true then
            return false, "downed"
        end

        local carryReason = getStatesFolderBlockReason(character)
        if carryReason then
            return false, carryReason
        end

        if character:GetAttribute("BlockCooldown") == true then
            return false, "block_cooldown"
        end
        if character:GetAttribute("ParryAttackLockout") == true then
            return false, "parry_attack_lockout"
        end
        if character:GetAttribute("BlockAttackLockout") == true then
            return false, "block_attack_lockout"
        end
        if character:GetAttribute("SpecTimeSlowed") == true then
            return false, "spec_time_slowed"
        end
        if character:GetAttribute("Grappling") == true then
            return false, "grappling"
        end
        if character:GetAttribute("Greenzone") == true
            or character:GetAttribute("RpCombatLocked") == true
            or character:GetAttribute("StaffModPeaceMode") == true
        then
            return false, "combat_locked"
        end

        local parried = character:GetAttribute("Parried") == true
        if character:GetAttribute("CantAnything") == true and not parried then
            return false, "cant_anything"
        end
        if character:GetAttribute("Stunned") == true and not parried then
            return false, "stunned"
        end

        local blockModule = getCombatModule("Block")
        if not blockModule or type(blockModule.Block) ~= "function" then
            return false, "block_module"
        end

        return true
    end



    local function canDodgeNow(character, allowPriorityPreempt)
        if not character or not character.Parent then
            return false, "local_missing"
        end

        if character:GetAttribute("Equip") ~= true then
            return false, "combat_disabled"
        end

        if character:GetAttribute("CounterLocked") == true then
            return false, "counter_locked"
        end
        if character:GetAttribute("SpecTimeSlowed") == true then
            return false, "spec_time_slowed"
        end

        local outnumberedGrant =
            character:GetAttribute("OutnumberedEvasiveGrant") == true

        if not outnumberedGrant then
            if character:GetAttribute("IFRAMECD") == true then
                return false, "iframe_cooldown"
            end
            if character:GetAttribute("Stunned") == true then
                return false, "stunned"
            end
            if character:GetAttribute("GuardBroken") == true then
                return false, "guard_broken"
            end
            if character:GetAttribute("Grappling") == true then
                return false, "grappling"
            end
            if character:GetAttribute("CantAnything") == true
                and character:GetAttribute("CombatRecovery") ~= true
                and allowPriorityPreempt ~= true
            then
                return false, "cant_anything"
            end
        end

        if character:GetAttribute("Ragdoll") == true then
            return false, "ragdoll"
        end
        if character:GetAttribute("Blocking") == true then
            return false, "blocking"
        end
        if character:GetAttribute("CombatAttacking") == true
            and allowPriorityPreempt ~= true
        then
            return false, "combat_attacking"
        end
        if character:GetAttribute("Greenzone") == true
            or character:GetAttribute("RpCombatLocked") == true
        then
            return false, "combat_locked"
        end
        if character:GetAttribute("Downed") == true then
            return false, "downed"
        end

        local module = getCombatModule("Evasive")
        if not module or type(module.Evasive) ~= "function" then
            return false, "evasive_module"
        end

        if type(module.IsDashActive) == "function" then
            local ok, active = pcall(module.IsDashActive)
            if ok and active == true then
                return false, "dash_active", module
            end
        end

        return true, nil, module
    end

    DodgeRuntime.isServerAntiGrabThreat = function(threat)
        if not threat
            or threat.serverConfirmed ~= true
            or threat.attackType ~= "M2"
        then
            return false
        end

        local style = string.lower(
            tostring(
                threat.style
                or getStyle(threat.owner)
                or ""
            )
        )

        if style == "wrestling"
            and Flags.dodge_wrestling_antigrab == true
        then
            return true, "wrestling_antigrab"
        end

        if style == "kure"
            and Flags.dodge_kure_antigrab == true
        then
            return true, "kure_antigrab"
        end

        return false
    end

    DodgeRuntime.getExplicitSpecialIntent = function(threat)
        if not threat then
            return nil
        end

        if threat.attackType ~= "M2" then
            return nil
        end

        local style = string.lower(
            tostring(
                threat.style
                or getStyle(threat.owner)
                or ""
            )
        )

        if style == "hakari"
            and Flags.dodge_hakari_double_read == true
        then
            return "hakari_double_read", "Hakari M2"
        elseif style == "wrestling"
            and Flags.dodge_wrestling_antigrab == true
        then
            return "wrestling_antigrab", "Wrestling M2"
        elseif style == "kure"
            and Flags.dodge_kure_antigrab == true
        then
            return "kure_antigrab", "Kure M2"
        end

        return nil
    end

    DodgeRuntime.isExplicitSpecialThreat = function(threat)
        return DodgeRuntime.getExplicitSpecialIntent(threat) ~= nil
    end

    DodgeRuntime.isIntentEnabled = function(intent)
        if intent == "hakari_double_read" then
            return Flags.dodge_hakari_double_read == true
        elseif intent == "wrestling_antigrab" then
            return Flags.dodge_wrestling_antigrab == true
        elseif intent == "kure_antigrab" then
            return Flags.dodge_kure_antigrab == true
        end

        return dodgeEnabled()
    end

    local function getDodgeIntent(threat)
        if not threat
            or (threat.attackType ~= "M1" and threat.attackType ~= "M2")
        then
            return false
        end

        if threat.counterStance == true and threat.serverConfirmed ~= true then
            return false
        end

        local normalizedThreatStyle = normalizeCombatStyleKey(
            tostring(threat.style or getStyle(threat.owner) or "")
        )
        if normalizedThreatStyle == "cqc"
            and threat.attackType == "M2"
        then
            return false
        end

        if Flags.dodge_if_cant_parry == true
            and threat.dodgeRearEmergency == true
        then
            return true,
                "cant_parry_rear",
                threat.dodgeRearReason or "rear_attack"
        end

        local serverAntiGrab, serverAntiGrabKind =
            DodgeRuntime.isServerAntiGrabThreat(threat)

        if serverAntiGrab then
            if threat.serverAntiGrabLogged ~= true then
                threat.serverAntiGrabLogged = true
                debugLog("DODGE_SPECIAL_SERVER_RESCUE", {
                    attack = threat.attackType or "",
                    owner = threat.ownerName or "",
                    style = threat.style or "",
                    kind = serverAntiGrabKind or "",
                    source = threat.source or "",
                }, true)
            end

            return true,
                serverAntiGrabKind,
                "active_grab_hitbox"
        end

        local explicitKind, explicitDetail =
            DodgeRuntime.getExplicitSpecialIntent(threat)

        if explicitKind then
            if threat.explicitSpecialLogged ~= true then
                threat.explicitSpecialLogged = true
                debugLog("DODGE_EXPLICIT_SPECIAL", {
                    attack = threat.attackType or "",
                    owner = threat.ownerName or "",
                    style = threat.style or "",
                    source = threat.source or "",
                    kind = explicitKind,
                    detail = explicitDetail or "",
                    serverConfirmed = threat.serverConfirmed == true,
                }, true)
            end

            return true, explicitKind, explicitDetail
        end

        local label = getMustDodgeLabel(threat)
        if label and selectedInMustDodgeList(label) then
            return true, "must_dodge", label
        end





        if Flags.dodge_if_cant_parry == true then
            local resourceGuard =
                DodgeRuntime.getSpecialResourceGuard(os.clock())

            if resourceGuard then
                if threat.dodgeSpecialResourcePreserveLogged ~= true then
                    threat.dodgeSpecialResourcePreserveLogged = true
                    debugLog("DODGE_SPECIAL_RESOURCE_PRESERVE", {
                        attack = threat.attackType or "",
                        owner = threat.ownerName or "",
                        style = threat.style or "",
                        reservedFor = resourceGuard.ownerName or "",
                        reservedKind = resourceGuard.kind or "",
                        remaining = math.max(
                            0,
                            (tonumber(resourceGuard.untilAt) or os.clock())
                                - os.clock()
                        ),
                    }, true)
                end

                return false
            end

            local canParry, reason = canParryNow(getCharacter())
            if not canParry then
                return true, "cant_parry", reason
            end
        end

        return false
    end

    local function getDodgeDirection(threat, context, requestedSpeed)
        local character = context and context.character or getCharacter()
        local myRoot = context and context.myRoot or getRoot(character)
        local owner = context and context.owner
            or (threat and (threat.owner or resolveOwner(threat)))
        local ownerRoot = context and context.ownerRoot or getRoot(owner)

        local baseDirection

        if myRoot and ownerRoot then
            local away = flat(myRoot.Position - ownerRoot.Position)
            if away.Magnitude > 0.05 then
                baseDirection = away.Unit
            end
        end

        if not baseDirection and myRoot then
            local back = -flat(myRoot.CFrame.LookVector)
            if back.Magnitude > 0.05 then
                baseDirection = back.Unit
            end
        end

        baseDirection = baseDirection or Vector3.new(0, 0, -1)

        if not myRoot then
            return baseDirection, {
                score = 0,
                floorSafe = true,
                wallClearance = 0,
                playerClearance = 0,
            }
        end

        local nearbyRoots = {}
        local ignore = {character}

        for _, player in ipairs(Players:GetPlayers()) do
            local otherCharacter = player.Character

            if otherCharacter then
                ignore[#ignore + 1] = otherCharacter
            end

            if player ~= LocalPlayer then
                local otherRoot = getRoot(otherCharacter)
                local otherHumanoid = otherCharacter
                    and otherCharacter:FindFirstChildOfClass("Humanoid")

                if otherRoot
                    and otherHumanoid
                    and otherHumanoid.Health > 0
                    and flat(otherRoot.Position - myRoot.Position).Magnitude <= 22
                then
                    nearbyRoots[#nearbyRoots + 1] = {
                        root = otherRoot,
                        character = otherCharacter,
                        isPrimary = ownerRoot ~= nil and otherRoot == ownerRoot,
                    }
                end
            end
        end

        local rayParams = RaycastParams.new()
        rayParams.FilterType = Enum.RaycastFilterType.Exclude
        rayParams.FilterDescendantsInstances = ignore
        rayParams.IgnoreWater = false

        local dashDistance = math.clamp(
            (tonumber(requestedSpeed) or 30) * 0.17,
            4.0,
            8.0
        )

        local currentFloor = Workspace:Raycast(
            myRoot.Position + Vector3.new(0, 1.5, 0),
            Vector3.new(0, -7.0, 0),
            rayParams
        )
        local currentFloorY = currentFloor
            and currentFloor.Position.Y
            or myRoot.Position.Y - 3

        local candidates = {}

        for index = 0, 11 do
            local angle = math.rad(index * 30)
            local cosine = math.cos(angle)
            local sine = math.sin(angle)
            local rotated = Vector3.new(
                baseDirection.X * cosine - baseDirection.Z * sine,
                0,
                baseDirection.X * sine + baseDirection.Z * cosine
            )

            if rotated.Magnitude > 0.05 then
                candidates[#candidates + 1] = rotated.Unit
            end
        end

        local bestDirection = baseDirection
        local bestScore = -math.huge
        local bestMeta = {
            score = -math.huge,
            floorSafe = false,
            wallClearance = 0,
            playerClearance = 0,
        }

        for _, candidate in ipairs(candidates) do
            local score = 0
            local projected =
                myRoot.Position + candidate * dashDistance
            local pathOrigin =
                myRoot.Position + Vector3.new(0, 1.55, 0)

            local wallHit = Workspace:Raycast(
                pathOrigin,
                candidate * (dashDistance + 0.8),
                rayParams
            )

            local wallClearance = wallHit
                and (wallHit.Position - pathOrigin).Magnitude
                or dashDistance + 0.8

            if wallHit then
                local ratio = wallClearance
                    / math.max(dashDistance, 0.01)

                if ratio < 0.62 then
                    score -= 70 + (0.62 - ratio) * 75
                elseif ratio < 0.90 then
                    score -= 24 + (0.90 - ratio) * 30
                else
                    score -= 5
                end
            else
                score += 9
            end

            local floorHit = Workspace:Raycast(
                projected + Vector3.new(0, 4.0, 0),
                Vector3.new(0, -11.0, 0),
                rayParams
            )

            local floorSafe = floorHit ~= nil

            if floorHit then
                local floorDelta =
                    floorHit.Position.Y - currentFloorY

                if floorDelta < -5.0 then
                    score -= 65 + math.abs(floorDelta + 5) * 4
                    floorSafe = false
                elseif floorDelta < -3.0 then
                    score -= 20
                elseif floorDelta > 4.5 then
                    score -= 22
                else
                    score += 12
                end

                if floorHit.Instance
                    and floorHit.Instance.CanCollide == false
                then
                    score -= 18
                end
            else
                score -= 95
            end

            local minimumPlayerClearance = math.huge

            for _, entry in ipairs(nearbyRoots) do
                local root = entry.root
                local velocity = flat(root.AssemblyLinearVelocity)
                local predictedRoot =
                    root.Position + velocity * 0.16
                local separation =
                    flat(projected - predictedRoot).Magnitude

                minimumPlayerClearance =
                    math.min(minimumPlayerClearance, separation)

                local otherCharacter = entry.character
                local attacking = otherCharacter
                    and (
                        otherCharacter:GetAttribute("CombatAttacking") == true
                        or otherCharacter:GetAttribute("M1") == true
                        or otherCharacter:GetAttribute("M2") == true
                    )

                if entry.isPrimary then
                    score += math.min(separation, 15) * 2.15

                    if separation < 4.2 then
                        score -= (4.2 - separation) * 15
                    end
                else
                    local weight = attacking and 1.20 or 0.72
                    score += math.min(separation, 12) * weight

                    if separation < 4.3 then
                        score -= (
                            (4.3 - separation)
                            * (attacking and 11 or 7)
                        )
                    end
                end
            end

            if minimumPlayerClearance == math.huge then
                minimumPlayerClearance = 20
            end

            score += candidate:Dot(baseDirection) * 2.6

            local forwardProbe = Workspace:Raycast(
                projected + Vector3.new(0, 1.5, 0),
                candidate * 2.0,
                rayParams
            )

            if not forwardProbe then
                score += 2.5
            else
                score -= 7
            end

            if floorSafe
                and wallClearance >= dashDistance * 0.90
                and minimumPlayerClearance >= 4.0
            then
                score += 16
            end

            if score > bestScore then
                bestScore = score
                bestDirection = candidate
                bestMeta = {
                    score = score,
                    floorSafe = floorSafe,
                    wallClearance = wallClearance,
                    playerClearance = minimumPlayerClearance,
                    dashDistance = dashDistance,
                }
            end
        end

        return bestDirection, bestMeta
    end

    local function applyRequestedDashMotion(threat, context, requestedSpeed)
        local character = context and context.character or getCharacter()
        local root = context and context.myRoot or getRoot(character)
        if not root then
            return false
        end

        local deadline = os.clock() + 0.065
        local linearVelocity = root:FindFirstChild("EvasiveDashLinearVelocity")

        while not linearVelocity and os.clock() < deadline do
            RunService.Heartbeat:Wait()
            if not root.Parent then
                return false
            end
            linearVelocity = root:FindFirstChild("EvasiveDashLinearVelocity")
        end

        if not linearVelocity or not linearVelocity:IsA("LinearVelocity") then
            return false
        end

        local direction = threat and threat.dodgeChosenDirection
        local directionMeta = threat and threat.dodgeChosenDirectionMeta

        if typeof(direction) ~= "Vector3"
            or direction.Magnitude <= 0.05
        then
            direction, directionMeta =
                getDodgeDirection(threat, context, requestedSpeed)
        end

        local speed = math.clamp(requestedSpeed, 10, 90)
        local maintainFor = math.min(SOURCE_DASH_DURATION, 0.19)
        local maintainStartedAt = os.clock()
        local maintainUntil = maintainStartedAt + maintainFor

        repeat
            if not root.Parent then
                break
            end




            if threat
                and threat.fired == true
                and threat.dodgeCommitted ~= true
            then
                break
            end

            pcall(function()
                if linearVelocity.Parent then
                    linearVelocity.VectorVelocity = direction * speed
                end
            end)

            if not linearVelocity.Parent then
                break
            end

            RunService.Heartbeat:Wait()
        until os.clock() >= maintainUntil

        debugLog("DODGE_MOTION", {
            owner = threat and threat.ownerName or "",
            attack = threat and threat.attackType or "",
            style = threat and threat.style or "",
            speed = speed,
            direction = direction,
            safeScore = directionMeta and directionMeta.score or "",
            floorSafe = directionMeta
                and directionMeta.floorSafe == true
                or false,
            wallClearance = directionMeta
                and directionMeta.wallClearance
                or "",
            playerClearance = directionMeta
                and directionMeta.playerClearance
                or "",
            dashDistance = directionMeta
                and directionMeta.dashDistance
                or "",
            maintainedFor = math.max(0, os.clock() - maintainStartedAt),
        }, true)

        return true
    end

    local function commitExistingIFrames(threat, prediction, reason)
        local now = os.clock()
        local contactAbs = tonumber(prediction and prediction.contactAbs) or now
        local contactIn = math.max(0, contactAbs - now)



        if contactIn > SOURCE_IFRAME_DURATION + 0.04 then
            return false
        end

        threat.dodgeCommitted = true
        threat.dodgeTaskArmed = false
        threat.dodgeAttemptPending = false
        threat.fired = true
        threat.firedAt = now

        debugLog("DODGE_COMMIT", {
            attack = threat.attackType or "",
            owner = threat.ownerName or "",
            style = threat.style or "",
            source = threat.source or "",
            reason = reason or "existing_iframes",
            contactIn = contactIn,
        }, true)

        return true
    end

    local function fireDodge(threat, prediction, context, intent, intentDetail)
        local now = os.clock()
        local character = context and context.character or getCharacter()

        if not character or not character.Parent then
            return false, "local_missing"
        end

        if character:GetAttribute("IFRAMES") == true then
            return commitExistingIFrames(
                threat,
                prediction,
                "already_iframed"
            ), "already_iframed"
        end





        if intent == "cant_parry" then
            if Menu._apBlockActive == true
                or character:GetAttribute("Blocking") == true
                or character:GetAttribute("PerfectBlocking") == true
            then
                return false, "parry_active"
            end

            local parryRecovered = canParryNow(character)
            if parryRecovered then
                return false, "parry_recovered"
            end

            -- Main322: AP itself is intentionally untouched. The rescue bug was
            -- in Dodge: threat.fired only means AP attempted/committed a threat;
            -- it does NOT prove Blocking/PerfectBlocking actually armed. When AP
            -- cannot parry (block cooldown/lockout/etc.), keep the dodge alive.
            local hardUnavailable =
                intentDetail == "block_cooldown"
                or intentDetail == "parry_attack_lockout"
                or intentDetail == "block_attack_lockout"
                or intentDetail == "guardbroken"
                or intentDetail == "stunned"
                or intentDetail == "cant_anything"

            if Flags.ap_enable == true
                and context
                and context.armReady == true
                and not hardUnavailable
            then
                local contactAbs = tonumber(
                    prediction and prediction.contactAbs
                ) or now
                local graceDeadline = contactAbs - 0.085
                local waited = false

                while os.clock() < graceDeadline
                    and character.Parent
                do
                    waited = true

                    if Menu._apBlockActive == true
                        or character:GetAttribute("Blocking") == true
                        or character:GetAttribute("PerfectBlocking") == true
                    then
                        return false, "parry_active"
                    end

                    if canParryNow(character) then
                        debugLog("DODGE_AP_GRACE_RECOVERED", {
                            attack = threat.attackType or "",
                            owner = threat.ownerName or "",
                            style = threat.style or "",
                            detail = intentDetail or "",
                            waitedMs = math.floor((os.clock() - now) * 1000 + 0.5),
                        }, true)
                        return false, "parry_recovered"
                    end

                    RunService.Heartbeat:Wait()
                end

                if waited then
                    debugLog("DODGE_AP_GRACE_EXHAUSTED", {
                        attack = threat.attackType or "",
                        owner = threat.ownerName or "",
                        style = threat.style or "",
                        detail = intentDetail or "",
                        apThreatFired = threat.fired == true,
                        waitedMs = math.floor((os.clock() - now) * 1000 + 0.5),
                        contactIn = math.max(0, contactAbs - os.clock()),
                    }, true)
                end
                now = os.clock()
            elseif hardUnavailable then
                debugLog("DODGE_AP_FAIL_RESCUE", {
                    attack = threat.attackType or "",
                    owner = threat.ownerName or "",
                    style = threat.style or "",
                    detail = intentDetail or "",
                    apThreatFired = threat.fired == true,
                    reason = "hard_parry_unavailable",
                    contactIn = math.max(
                        0,
                        (tonumber(prediction and prediction.contactAbs) or now)
                            - os.clock()
                    ),
                }, true)
            end
        end

        local specialAntiGrabIntent =
            intent == "wrestling_antigrab"
            or intent == "kure_antigrab"
            or intent == "hakari_double_read"

        local priorityIntent = intent == "must_dodge"
            or intent == "cant_parry_rear"
            or specialAntiGrabIntent

        local attemptGap = (intent == "cant_parry_rear" and 0.040)
            or (priorityIntent and 0.065 or 0.115)
        if now - (DodgeRuntime.lastAttemptAt or 0) < attemptGap then
            return false, "attempt_gap"
        end

        if priorityIntent then
            DodgeRuntime.preparePriorityHandoff(character)

            local contactAbs = tonumber(prediction and prediction.contactAbs) or now
            local handoffDeadline = math.min(now + 0.075, contactAbs - 0.045)

            while os.clock() < handoffDeadline
                and character.Parent
                and (
                    Menu._apBlockActive == true
                    or character:GetAttribute("Blocking") == true
                    or character:GetAttribute("CombatAttacking") == true
                    or (
                        specialAntiGrabIntent ~= true
                        and character:GetAttribute("CantAnything") == true
                        and character:GetAttribute("CombatRecovery") ~= true
                    )
                )
            do
                DodgeRuntime.preparePriorityHandoff(character)
                RunService.Heartbeat:Wait()
            end
        end

        local allowed, reason, module = canDodgeNow(
            character,
            priorityIntent
        )
        if not allowed then
            return false, reason
        end

        DodgeRuntime.lastAttemptAt = now
        threat.dodgeAttemptPending = true
        threat.dodgeAttemptStartedAt = os.clock()

        local contactAbsForPriority =
            tonumber(prediction and prediction.contactAbs) or threat.dodgeAttemptStartedAt
        threat.dodgePriorityUntil = math.min(
            threat.dodgeAttemptStartedAt + 0.110,
            contactAbsForPriority - 0.055
        )

        local reactionMs = dodgeNumber("dodge_reaction", 100, 40, 300)
        local requestedWindowMs =
            autoIFrameWindowMs()
        local requestedSpeed = dodgeNumber("dodge_speed", 30, 10, 90)

        debugLog("DODGE_FIRE_ATTEMPT", {
            attack = threat.attackType or "",
            owner = threat.ownerName or "",
            style = threat.style or "",
            source = threat.source or "",
            intent = intent or "",
            detail = intentDetail or "",
            reactionMs = reactionMs,
            iframeWindowMs = requestedWindowMs,
            sourceIFrameMs = math.floor(SOURCE_IFRAME_DURATION * 1000 + 0.5),
            speed = requestedSpeed,
            distance = context and context.distance or "",
            contactIn = math.max(
                0,
                (tonumber(prediction and prediction.contactAbs) or now) - now
            ),
        }, true)

        local chosenDirection, chosenDirectionMeta =
            getDodgeDirection(threat, context, requestedSpeed)

        threat.dodgeChosenDirection = chosenDirection
        threat.dodgeChosenDirectionMeta = chosenDirectionMeta

        local directionLockSerial = nil
        local isolateUserDirection =
            intent == "cant_parry"
            or intent == "cant_parry_rear"
            or intent == "must_dodge"
            or intent == "wrestling_antigrab"
            or intent == "kure_antigrab"
            or intent == "hakari_double_read"

        if isolateUserDirection then
            directionLockSerial =
                DodgeRuntime.lockAutomaticDirection(
                    character,
                    chosenDirection
                )

            local humanoid =
                character:FindFirstChildOfClass("Humanoid")

            if humanoid then
                pcall(
                    humanoid.Move,
                    humanoid,
                    chosenDirection,
                    false
                )
            end
        end

        if isolateUserDirection then
            debugLog("DODGE_DIRECTION_LOCK", {
                attack = threat.attackType or "",
                owner = threat.ownerName or "",
                style = threat.style or "",
                intent = intent or "",
                direction = chosenDirection,
                safeScore = chosenDirectionMeta
                    and chosenDirectionMeta.score
                    or "",
                playerClearance = chosenDirectionMeta
                    and chosenDirectionMeta.playerClearance
                    or "",
                wallClearance = chosenDirectionMeta
                    and chosenDirectionMeta.wallClearance
                    or "",
            }, true)
        end

        local iframeConfirmed = character:GetAttribute("IFRAMES") == true




        local activationConfirmed = iframeConfirmed
        local iframeConnection
        local cooldownConnection
        local motionStarted = false
        local automaticDodgeSoundPlayed = false

        local function notifyAutomaticDodgeSound()
            if automaticDodgeSoundPlayed then
                return
            end

            automaticDodgeSoundPlayed = true

            local soundRuntime =
                Menu._SoundRuntime

            if soundRuntime
                and type(
                    soundRuntime.onAutoDodgeCommitted
                ) == "function"
            then
                task.defer(
                    soundRuntime.onAutoDodgeCommitted
                )
            end
        end

        local function startRequestedMotion(phase)
            if motionStarted then
                return
            end

            motionStarted = true

            task.spawn(function()
                local motionOk, motionApplied = pcall(
                    applyRequestedDashMotion,
                    threat,
                    context,
                    requestedSpeed
                )
            end)
        end

        local function startConfirmedMotion()
            notifyAutomaticDodgeSound()
            startRequestedMotion("confirmed")
        end

        if not iframeConfirmed then
            iframeConnection = character:GetAttributeChangedSignal("IFRAMES")
                :Connect(function()
                    if character:GetAttribute("IFRAMES") == true then
                        iframeConfirmed = true
                        activationConfirmed = true
                        startConfirmedMotion()
                    end
                end)
        end

        if not activationConfirmed then
            cooldownConnection =
                character:GetAttributeChangedSignal("IFRAMECD")
                    :Connect(function()
                        if character:GetAttribute("IFRAMECD") == true then
                            activationConfirmed = true
                            startConfirmedMotion()
                        end
                    end)
        end

        if isolateUserDirection then
            local humanoid =
                character:FindFirstChildOfClass("Humanoid")

            if humanoid then
                pcall(
                    humanoid.Move,
                    humanoid,
                    chosenDirection,
                    false
                )
            end
        end

        local animationYieldSerial =
            beginEvasiveAnimationYield()

        if animationYieldSerial ~= nil then
            debugLog("DODGE_ANIMATION_YIELD", {
                attack = threat.attackType or "",
                owner = threat.ownerName or "",
                style = threat.style or "",
                intent = intent or "",
                holdMs = math.floor(
                    (math.max(
                        SOURCE_IFRAME_DURATION,
                        SOURCE_DASH_DURATION
                    ) + 0.085) * 1000 + 0.5
                ),
            }, true)
        end

        local ok, errorValue = pcall(module.Evasive)

        if directionLockSerial then
            task.delay(
                math.min(SOURCE_DASH_DURATION + 0.04, 0.24),
                function()
                    DodgeRuntime.unlockAutomaticDirection(
                        directionLockSerial
                    )
                end
            )
        end

        if not ok then
            endEvasiveAnimationYield(
                animationYieldSerial
            )
            if directionLockSerial then
                DodgeRuntime.unlockAutomaticDirection(
                    directionLockSerial
                )
            end
            if iframeConnection then
                iframeConnection:Disconnect()
            end
            if cooldownConnection then
                cooldownConnection:Disconnect()
            end
            threat.dodgeAttemptPending = false
            return false, "evasive_error:" .. tostring(errorValue)
        end

        if isolateUserDirection then
            debugLog("DODGE_EARLY_MOTION", {
                owner = threat.ownerName or "",
                speed = requestedSpeed,
                direction = chosenDirection,
                iframeConfirmed = iframeConfirmed == true,
                activationConfirmed = activationConfirmed == true,
            }, true)
            startRequestedMotion("post_evasive_call")
        end

        if iframeConfirmed or activationConfirmed then
            startConfirmedMotion()
        end











        local confirmWait = character:GetAttribute("OutnumberedEvasiveGrant") == true
            and 1.20
            or math.max(SOURCE_SERVER_CONFIRM, 0.60)
        local contactAbs =
            tonumber(prediction and prediction.contactAbs) or os.clock()
        local deadline = os.clock() + confirmWait
        local minimumConfirmUntil = os.clock()
            + (priorityIntent and 0.14 or 0.06)






        local fallbackRescueIntent =
            intent == "cant_parry"

        while os.clock() < deadline
            and not iframeConfirmed
            and (
                priorityIntent
                or fallbackRescueIntent
                or threat.fired ~= true
            )
            and character.Parent
        do
            if character:GetAttribute("IFRAMES") == true then
                iframeConfirmed = true
                activationConfirmed = true
                break
            end

            if character:GetAttribute("IFRAMECD") == true then
                activationConfirmed = true
                startConfirmedMotion()
            end

            if activationConfirmed then
                deadline = math.max(
                    deadline,
                    math.min(contactAbs - 0.045, os.clock() + 0.12)
                )
            elseif priorityIntent
                and contactAbs - os.clock() <= 0.085
                and os.clock() >= minimumConfirmUntil
            then
                break
            end

            RunService.Heartbeat:Wait()
        end

        if iframeConnection then
            iframeConnection:Disconnect()
        end
        if cooldownConnection then
            cooldownConnection:Disconnect()
        end

        threat.dodgeAttemptPending = false

        if threat.fired == true
            and not iframeConfirmed
            and intent ~= "cant_parry"
        then
            return false, "ap_fallback"
        end

        if iframeConfirmed
            or activationConfirmed
            or character:GetAttribute("IFRAMES") == true
            or character:GetAttribute("IFRAMECD") == true
        then
            threat.dodgeCommitted = true
            threat.dodgeTaskArmed = false
            threat.fired = true
            threat.firedAt = os.clock()

            startConfirmedMotion()

            debugLog("DODGE_COMMIT", {
                attack = threat.attackType or "",
                owner = threat.ownerName or "",
                style = threat.style or "",
                source = threat.source or "",
                intent = intent or "",
                detail = intentDetail or "",
                confirmation = iframeConfirmed
                    and "IFRAMES"
                    or "IFRAMECD",
                activationConfirmed = activationConfirmed,
                confirmWait = confirmWait,
                contactIn = math.max(
                    0,
                    (tonumber(prediction and prediction.contactAbs) or os.clock())
                        - os.clock()
                ),
            }, true)

            return true
        end

        threat.dodgeActivationConfirmed = activationConfirmed == true




        if not activationConfirmed then
            DodgeRuntime.lastAttemptAt = math.min(
                DodgeRuntime.lastAttemptAt or 0,
                os.clock() - 0.080
            )
        end

        return false, activationConfirmed
            and "iframe_not_confirmed_after_activation"
            or "iframe_not_confirmed"
    end

    function DodgeRuntime.try(threat, prediction, context, now)
        if not threat
            or threat.expired == true
            or threat.fired == true
        then
            return false
        end

        local dodgeOwner = threat.owner
        if not dodgeOwner and threat.hitbox then
            dodgeOwner = resolveOwner(threat)
        end
        if dodgeOwner
            and Menu._IsFriendlyCharacter
            and Menu._IsFriendlyCharacter(dodgeOwner)
        then
            threat.dodgeTaskArmed = false
            threat.dodgeAttemptPending = false
            threat.dodgeDispatching = false
            return false
        end

        if Menu._AliCounterRuntime
            and type(
                Menu._AliCounterRuntime.isBoxingM2ParryOnly
            ) == "function"
            and Menu._AliCounterRuntime.isBoxingM2ParryOnly(
                threat
            )
        then
            threat.dodgeTaskArmed = false
            threat.dodgeAttemptPending = false
            threat.dodgeDispatching = false
            return false
        end

        if Menu._AliCounterRuntime
            and type(
                Menu._AliCounterRuntime.shouldOwnThreat
            ) == "function"
            and Menu._AliCounterRuntime.shouldOwnThreat(
                threat,
                context
            )
        then
            threat.dodgeTaskArmed = false
            threat.dodgeAttemptPending = false
            threat.dodgeDispatching = false

            if threat.aliGenericDodgeSuppressedLogged
                ~= true
            then
                threat.aliGenericDodgeSuppressedLogged =
                    true

                debugLog(
                    "ALI_COUNTER_DODGE_SUPPRESS",
                    {
                        attack =
                            threat.attackType
                            or "",
                        owner =
                            threat.ownerName
                            or "",
                        style =
                            threat.style
                            or "",
                        reason =
                            "ali_evasive_owns",
                    },
                    true
                )
            end

            return false
        end

        if not threat
            or threat.expired == true
            or threat.fired == true
        then
            return false
        end

        local explicitIntent =
            DodgeRuntime.getExplicitSpecialIntent(threat)

        if not dodgeEnabled() and not explicitIntent then
            return false
        end

        if context and context.boxingCounterM2Only == true then
            return false
        end

        now = now or os.clock()

        if now < (threat.dodgeRetryAt or 0) then
            return false
        end

        if threat.dodgeCommitted == true then
            return true
        end

        local shouldDodge, intent, detail = getDodgeIntent(threat)
        if not shouldDodge then
            return false
        end

        local character = context and context.character or getCharacter()
        if character and character:GetAttribute("IFRAMES") == true then
            if commitExistingIFrames(threat, prediction, "existing_iframes") then
                return true
            end
        end

        local apBlockActive = Menu._apBlockActive == true
            or (character and character:GetAttribute("Blocking") == true)
        local parryAvailable, parryUnavailableReason = canParryNow(character)
        local rearDodgePriority = intent == "cant_parry_rear"
        if (apBlockActive or parryAvailable)
            and not rearDodgePriority
        then
            threat.dodgeTaskArmed = false
            threat.dodgeAttemptPending = false
            threat.dodgeDispatching = false

            local policyReason = apBlockActive
                and "ap_block_active"
                or "ap_ready"
            if threat.dodgeApFirstReason ~= policyReason then
                threat.dodgeApFirstReason = policyReason
                debugLog("DODGE_AP_FIRST", {
                    attack = threat.attackType or "",
                    owner = threat.ownerName or "",
                    style = threat.style or "",
                    source = threat.source or "",
                    intent = intent or "",
                    detail = detail or "",
                    reason = policyReason,
                    parryUnavailableReason = parryUnavailableReason or "",
                }, true)
            end
            return false
        end

        threat.dodgeApFirstReason = nil

        local requestedWindow =
            autoIFrameWindowMs() / 1000
        local effectiveWindow = math.min(
            requestedWindow,
            SOURCE_IFRAME_DURATION
        )
        local reaction =
            dodgeNumber("dodge_reaction", 100, 40, 300) / 1000
        local uplink = math.clamp(
            math.max(0, tonumber(prediction and prediction.up) or 0),
            0,
            0.18
        )

        local contactAbs = tonumber(prediction and prediction.contactAbs) or now
        local contactIn = contactAbs - now

        if contactIn < -0.025 then
            return false
        end



        local specialAntiGrabIntent =
            intent == "wrestling_antigrab"
            or intent == "kure_antigrab"
            or intent == "hakari_double_read"

        local hardDodgeIntent =
            intent == "must_dodge"
            or intent == "cant_parry_rear"
            or specialAntiGrabIntent

        local maxLead = math.max(0.05, effectiveWindow - 0.025)
        local lead = math.clamp(
            reaction + uplink + 0.012,
            0.05,
            maxLead
        )

        if hardDodgeIntent then
            lead = math.max(
                lead,
                math.min(
                    maxLead,
                    math.max(0.18, effectiveWindow - 0.055)
                )
            )
        end

        if intent == "cant_parry_rear" then
            lead = maxLead
        end

        local fireAt = contactAbs - lead

        threat.dodgeFireAt = fireAt
        threat.dodgeContactAbs = contactAbs
        threat.dodgeIntent = intent
        threat.dodgeIntentDetail = detail
        threat.dodgePrediction = prediction
        threat.dodgeContext = context

        if threat.dodgeTaskArmed == true
            or threat.dodgeAttemptPending == true
            or threat.dodgeDispatching == true
        then
            return false
        end

        local priorityIntent = intent == "must_dodge"
            or intent == "cant_parry_rear"
            or specialAntiGrabIntent
        local allowed, gateReason = canDodgeNow(
            character,
            priorityIntent
        )

        if not allowed
            and priorityIntent
            and gateReason == "blocking"
            and Menu._apBlockActive == true
        then
            allowed = true
            gateReason = nil
        end

        if not allowed then
            if threat.dodgeGateReason ~= gateReason then
                threat.dodgeGateReason = gateReason
                debugLog("DODGE_GATE", {
                    attack = threat.attackType or "",
                    owner = threat.ownerName or "",
                    style = threat.style or "",
                    source = threat.source or "",
                    intent = intent or "",
                    detail = detail or "",
                    reason = gateReason or "",
                    contactIn = contactIn,
                }, true)
            end
            return false
        end

        threat.dodgeGateReason = nil
        threat.dodgeTaskArmed = true

        if (
            intent == "cant_parry"
            or intent == "cant_parry_rear"
        ) and threat.dodgeFallbackPolicyLogged ~= true
        then
            threat.dodgeFallbackPolicyLogged = true
            debugLog("DODGE_POLICY", {
                attack = threat.attackType or "",
                owner = threat.ownerName or "",
                style = threat.style or "",
                source = threat.source or "",
                intent = intent,
                policy = intent == "cant_parry_rear"
                    and "REAR_ATTACK_ONLY"
                    or "FORCED_LIST_ONLY",
            }, true)
        end

        debugLog("DODGE_ARM", {
            attack = threat.attackType or "",
            owner = threat.ownerName or "",
            style = threat.style or "",
            source = threat.source or "",
            intent = intent or "",
            detail = detail or "",
            distance = context and context.distance or "",
            contactIn = contactIn,
            fireIn = fireAt - now,
            reactionMs = math.floor(reaction * 1000 + 0.5),
            networkLeadMs = math.floor(uplink * 1000 + 0.5),
            requestedIFrameMs = math.floor(requestedWindow * 1000 + 0.5),
            effectiveIFrameMs = math.floor(effectiveWindow * 1000 + 0.5),
        }, true)

        task.spawn(function()
            while threat.dodgeTaskArmed == true do
                if not DodgeRuntime.isIntentEnabled(intent)
                    or threat.expired == true
                    or (
                        threat.fired == true
                        and intent ~= "cant_parry"
                    )
                    or (
                        intent == "cant_parry_rear"
                        and threat.dodgeRearEmergency ~= true
                    )
                then
                    threat.dodgeTaskArmed = false
                    return
                end

                if threat.track
                    and threat.serverConfirmed ~= true
                    and threat.track.IsPlaying == false
                then
                    threat.dodgeTaskArmed = false
                    debugLog("DODGE_CANCEL", {
                        attack = threat.attackType or "",
                        owner = threat.ownerName or "",
                        style = threat.style or "",
                        reason = "animation_stopped",
                    }, true)
                    return
                end

                local scheduledAt = tonumber(threat.dodgeFireAt) or os.clock()
                if os.clock() >= scheduledAt then
                    break
                end

                RunService.Heartbeat:Wait()
            end

            threat.dodgeTaskArmed = false

            if threat.expired == true
                or (
                    threat.fired == true
                    and intent ~= "cant_parry"
                )
                or not DodgeRuntime.isIntentEnabled(intent)
            then
                return
            end

            threat.dodgeDispatching = true

            local currentContext = threat.dodgeContext or context
            local currentPrediction = threat.dodgePrediction or prediction

            local committed, reason = fireDodge(
                threat,
                currentPrediction,
                currentContext,
                threat.dodgeIntent,
                threat.dodgeIntentDetail
            )

            threat.dodgeDispatching = false

            if not committed then
                local retryDelay =
                    (threat.dodgeIntent == "cant_parry_rear" and 0.040)
                    or 0.065
                threat.dodgeRetryAt = os.clock() + retryDelay

                local eventName = (
                    reason == "ap_fallback"
                    or reason == "parry_recovered"
                    or reason == "parry_active"
                ) and "DODGE_CANCEL"
                    or "DODGE_FAIL"

                debugLog(eventName, {
                    attack = threat.attackType or "",
                    owner = threat.ownerName or "",
                    style = threat.style or "",
                    source = threat.source or "",
                    intent = threat.dodgeIntent or "",
                    detail = threat.dodgeIntentDetail or "",
                    reason = reason or "unknown",
                    activationConfirmed =
                        threat.dodgeActivationConfirmed == true,
                    contactIn = math.max(
                        0,
                        (tonumber(threat.dodgeContactAbs) or os.clock())
                            - os.clock()
                    ),
                }, true)
            end
        end)


        return false
    end

    function DodgeRuntime.queuePassiveTry(
        threat,
        prediction,
        context,
        now
    )
        if not threat
            or threat.dodgePassiveQueued == true
            or threat.dodgeTaskArmed == true
            or threat.dodgeAttemptPending == true
            or threat.dodgeDispatching == true
            or threat.dodgeCommitted == true
            or threat.fired == true
        then
            return false
        end

        threat.dodgePassiveQueued = true

        task.defer(function()
            threat.dodgePassiveQueued = false

            if not dodgeEnabled()
                or threat.expired == true
                or threat.fired == true
            then
                return
            end

            pcall(
                DodgeRuntime.try,
                threat,
                prediction,
                context,
                now
            )
        end)

        return true
    end

    function DodgeRuntime.isMustDodgeThreat(threat)
        local label = getMustDodgeLabel(threat)
        return label ~= nil and selectedInMustDodgeList(label)
    end

    function DodgeRuntime.isForced(threat)
        if DodgeRuntime.getSpecialReservation(threat, os.clock()) then
            return true
        end

        if not threat then
            return false
        end

        local intent = threat.dodgeIntent
        local priorityIntent = intent == "must_dodge"
            or intent == "cant_parry_rear"
            or intent == "wrestling_antigrab"
            or intent == "kure_antigrab"
            or intent == "hakari_double_read"

        return priorityIntent
            and (
                threat.dodgeTaskArmed == true
                or threat.dodgeAttemptPending == true
                or threat.dodgeDispatching == true
            )
            or false
    end

    function DodgeRuntime.shouldSuppressParry(threat, prediction, now)
        now = now or os.clock()

        if Menu._AliCounterRuntime
            and type(
                Menu._AliCounterRuntime.isBoxingM2ParryOnly
            ) == "function"
            and Menu._AliCounterRuntime.isBoxingM2ParryOnly(
                threat
            )
        then
            return false
        end

        local specialReservation = DodgeRuntime.getSpecialReservation(threat, now)
        if specialReservation then
            local specialContact = tonumber(
                threat and threat.dodgeContactAbs
                    or (prediction and prediction.contactAbs)
            ) or now
            return specialContact - now > 0.055
        end

        if not threat or threat.dodgeCommitted == true then
            return false
        end

        local intent = threat.dodgeIntent
        if intent ~= "must_dodge"
            and intent ~= "cant_parry_rear"
            and intent ~= "wrestling_antigrab"
            and intent ~= "kure_antigrab"
            and intent ~= "hakari_double_read"
        then
            return false
        end

        if threat.dodgeTaskArmed ~= true
            and threat.dodgeAttemptPending ~= true
            and threat.dodgeDispatching ~= true
        then
            return false
        end

        local contactAbs = tonumber(
            threat.dodgeContactAbs
                or (prediction and prediction.contactAbs)
        ) or now
        local contactIn = contactAbs - now
        local fireAt = tonumber(threat.dodgeFireAt) or now

        if contactIn <= 0.055 then
            return false
        end

        if threat.dodgeAttemptPending == true then
            local priorityUntil = tonumber(threat.dodgePriorityUntil)
                or ((tonumber(threat.dodgeAttemptStartedAt) or now) + 0.110)
            return now <= priorityUntil
        end

        return threat.dodgeTaskArmed == true
            and now >= fireAt - 0.015
    end






    DodgeRuntime.special = DodgeRuntime.special or {}
    local Special = DodgeRuntime.special

    Special.watched = Special.watched or setmetatable({}, { __mode = "k" })
    Special.serial = Special.serial or setmetatable({}, { __mode = "k" })
    Special.animationIds = Special.animationIds or {}
    Special.started = Special.started == true

    function Special.animationKey(value)
        return tostring(value or ""):match("(%d+)") or ""
    end

    function Special.refreshAnimationIds()
        table.clear(Special.animationIds)




        Special.animationIds.wrestling_antigrab = "73748315742870"
        Special.animationIds.kure_antigrab = "88619229552579"
        Special.animationIds.hakari_double_read = "102961997518914"
        Special.animationIds.hakari_m2 = "103359839046574"

        local animations = ReplicatedStorage:FindFirstChild("Animations")
        local combat = animations and animations:FindFirstChild("Combat")
        if not combat then
            return
        end

        local specs = {
            wrestling_antigrab = { "WrestlingAnims", "M2" },
            kure_antigrab = { "KureAnims", "M2" },
            hakari_double_read = { "HakariAnims", "MomentumM2" },
        }

        for kind, spec in pairs(specs) do
            local folder = combat:FindFirstChild(spec[1])
            local animation = folder and folder:FindFirstChild(spec[2])
            if animation and animation:IsA("Animation") then
                local id = Special.animationKey(animation.AnimationId)
                if id ~= "" then
                    Special.animationIds[kind] = id
                end
            end
        end

        local hakariFolder = combat:FindFirstChild("HakariAnims")
        local hakariM2 = hakariFolder and hakariFolder:FindFirstChild("M2")
        if hakariM2 and hakariM2:IsA("Animation") then
            local id = Special.animationKey(hakariM2.AnimationId)
            if id ~= "" then
                Special.animationIds.hakari_m2 = id
            end
        end
    end

    function Special.kindEnabled(kind)
        if kind == "wrestling_antigrab" then
            return Flags.dodge_wrestling_antigrab == true
        elseif kind == "kure_antigrab" then
            return Flags.dodge_kure_antigrab == true
        elseif kind == "hakari_double_read" then
            return Flags.dodge_hakari_double_read == true
        end

        return false
    end

    function Special.classify(character, track)
        if not character or not track then
            return nil
        end

        if next(Special.animationIds) == nil then
            Special.refreshAnimationIds()
        end

        local animation = track.Animation
        local id = Special.animationKey(animation and animation.AnimationId)
        if id == "" then
            return nil
        end

        local style = string.lower(tostring(getStyle(character) or ""))

        if style == "wrestling"
            and id == Special.animationIds.wrestling_antigrab
        then
            return "wrestling_antigrab", style, id
        end

        if style == "kure"
            and id == Special.animationIds.kure_antigrab
        then
            return "kure_antigrab", style, id
        end

        if style == "hakari"
            and id == Special.animationIds.hakari_double_read
        then



            return "hakari_double_read", style, id
        end

        return nil
    end

    function Special.hitTimeline(character, style, kind)
        local variant
        pcall(function()
            variant = CombatStepUtils.ResolveM2VariantId(style, character)
        end)

        local isHakariMomentum = kind == "hakari_double_read"
        local baseDelay = tonumber(CombatConfig.M2.DefaultHitboxDelay) or 0.30

        pcall(function()
            local value = CombatConfig.GetStyleM2HitboxDelay(
                style,
                isHakariMomentum,
                variant
            )
            if typeof(value) == "number" then
                baseDelay = math.max(0, value)
            end
        end)



        local timeline = baseDelay
        pcall(function()
            local value = CombatConfig.GetScaledHitboxDelay(baseDelay, 1)
            if typeof(value) == "number" then
                timeline = value
            end
        end)

        return math.max(0.05, timeline), variant
    end

    function Special.getContext(owner, remaining, style, kind)
        local character = getCharacter()
        local myRoot = getRoot(character)
        local ownerRoot = getRoot(owner)

        if not character or not myRoot or not ownerRoot then
            return nil, "roots"
        end

        local humanoid = character:FindFirstChildOfClass("Humanoid")
        if not humanoid or humanoid.Health <= 0 then
            return nil, "local_dead"
        end

        local ownerHumanoid = owner:FindFirstChildOfClass("Humanoid")
        if not ownerHumanoid or ownerHumanoid.Health <= 0 then
            return nil, "owner_dead"
        end

        local horizonCap =
            kind == "hakari_double_read"
                and 0.42
                or (
                    kind == "wrestling_antigrab"
                    and 0.48
                    or 0.40
                )

        local horizon = math.clamp(
            math.max(0, tonumber(remaining) or 0),
            0,
            horizonCap
        )
        local ownerVelocity = flat(ownerRoot.AssemblyLinearVelocity)
        local localVelocity = flat(myRoot.AssemblyLinearVelocity)
        local currentFlatDelta =
            flat(myRoot.Position - ownerRoot.Position)
        local currentDistance = currentFlatDelta.Magnitude
        local movementClosing = 0

        if currentDistance > 0.05 then
            movementClosing =
                (ownerVelocity - localVelocity)
                    :Dot(currentFlatDelta.Unit)
        end

        local moveDirection = flat(humanoid.MoveDirection)
        if moveDirection.Magnitude > 0.05
            and currentDistance > 0.05
        then
            local intendedVelocity =
                moveDirection.Unit
                * math.clamp(
                    tonumber(humanoid.WalkSpeed) or 16,
                    0,
                    32
                )
            local intendedClosing =
                (ownerVelocity - intendedVelocity)
                    :Dot(currentFlatDelta.Unit)

            if intendedClosing > movementClosing + 0.35 then
                localVelocity = intendedVelocity
                movementClosing = intendedClosing
            end
        end

        local ownerPosition = ownerRoot.Position + ownerVelocity * horizon
        local localPosition = myRoot.Position + localVelocity * horizon
        local delta = localPosition - ownerPosition
        local flatDelta = flat(delta)
        local distance = flatDelta.Magnitude

        local look = flat(ownerRoot.CFrame.LookVector)
        if look.Magnitude < 0.001 then
            return nil, "owner_facing"
        end
        look = look.Unit

        local right = Vector3.new(-look.Z, 0, look.X)
        local forward = flatDelta:Dot(look)
        local lateral = math.abs(flatDelta:Dot(right))
        local facingDot = distance > 0.05 and look:Dot(flatDelta.Unit) or 1

        local forwardOffset = tonumber(CombatConfig.M2.DefaultHitboxForwardOffset) or 3
        pcall(function()
            local value = CombatConfig.GetStyleHitboxForwardOffset(style, "M2")
            if typeof(value) == "number" then
                forwardOffset = math.max(0, value)
            end
        end)

        local stepForward = 0
        pcall(function()
            local value = CombatConfig.GetStyleM2StepForwardStuds(style)
            if typeof(value) == "number" then
                stepForward = math.max(0, value)
            end
        end)




        local grabOffset = 0
        if kind == "wrestling_antigrab" or kind == "kure_antigrab" then
            pcall(function()
                local styleConfig = CombatConfig.GetStyleConfig(style)
                local value = styleConfig and styleConfig.M2GrabTargetForwardOffset
                if typeof(value) == "number" then
                    grabOffset = math.max(0, value)
                end
            end)
        end

        local centerOffset = math.max(forwardOffset, grabOffset)
        local hitboxHalf = 2.05
        local localRadius = math.max(myRoot.Size.X, myRoot.Size.Z) * 0.5
        local cushion = 0.70
        local forwardReach = centerOffset
            + stepForward
            + hitboxHalf
            + localRadius
            + cushion
        local lateralReach = hitboxHalf + localRadius + cushion





        local verticalReach = 3.45 + myRoot.Size.Y * 0.5 + cushion

        local radialReach
        if kind == "wrestling_antigrab" then
            radialReach = math.max(9.4, forwardReach + 1.35)
        elseif kind == "kure_antigrab" then
            radialReach = math.max(8.6, forwardReach + 1.15)
        elseif kind == "hakari_double_read" then
            radialReach = math.max(10.0, forwardReach + 1.70)
        else
            radialReach = math.max(6.2, forwardReach + 0.35)
        end

        local dangerous = math.abs(delta.Y) <= verticalReach
            and distance <= radialReach
            and (
                kind == "wrestling_antigrab"
                or kind == "kure_antigrab"
                or facingDot >= -0.20
                or distance <= 3.5
            )

        local relativeVelocity = ownerVelocity - localVelocity
        local closing = movementClosing
        if distance > 0.05 then
            closing = math.max(
                closing,
                relativeVelocity:Dot(flatDelta.Unit)
            )
        end

        local walkingInto =
            closing >= 1.0
            and distance < currentDistance - 0.10

        if walkingInto
            and (
                kind == "wrestling_antigrab"
                or kind == "kure_antigrab"
            )
        then
            local walkInBoost = math.clamp(
                closing * math.max(0, horizon) * 0.45,
                0,
                1.60
            )
            radialReach += walkInBoost
            dangerous =
                math.abs(delta.Y) <= verticalReach
                and distance <= radialReach
        end

        return {
            character = character,
            myRoot = myRoot,
            owner = owner,
            ownerRoot = ownerRoot,
            distance = distance,
            currentDistance = currentDistance,
            dangerous = dangerous,
            walkingInto = walkingInto,
            forward = forward,
            lateral = lateral,
            facingDot = facingDot,
            vertical = math.abs(delta.Y),
            forwardReach = forwardReach,
            lateralReach = lateralReach,
            verticalReach = verticalReach,
            closing = closing,
            predictedFor = horizon,
        }
    end

    function Special.schedule(character, track, kind, style, animationId)
        if not Special.kindEnabled(kind) then
            return
        end

        Special.serial[character] = (Special.serial[character] or 0) + 1
        local serial = Special.serial[character]

        task.spawn(function()
            local hitTL, variant = Special.hitTimeline(character, style, kind)
            local threat = {
                source = "dodge_special",
                track = track,
                owner = character,
                ownerName = character.Name,
                attackType = "M2",
                style = style,
                variant = variant,
                createdAt = os.clock(),
                specialKind = kind,
            }
            local armedLogged = false
            local lastGate

            debugLog("DODGE_SPECIAL_TRACK", {
                owner = character.Name,
                style = style,
                kind = kind,
                animationId = animationId or "",
                hitTL = hitTL,
                variant = variant or "",
            }, true)

            while Special.serial[character] == serial
                and character.Parent
                and track.IsPlaying
                and Special.kindEnabled(kind)
            do
                local trackTime = math.max(0, tonumber(track.TimePosition) or 0)
                local trackSpeed = tonumber(track.Speed) or 1
                local ownerSpeed = getSpeedMultiplier(character)

                if typeof(ownerSpeed) ~= "number"
                    or ownerSpeed < 0.20
                    or ownerSpeed > 3
                then
                    ownerSpeed = 1
                end

                if trackSpeed < 0.20 or trackSpeed > 3 then
                    trackSpeed = ownerSpeed
                elseif math.abs(trackSpeed - 1) <= 0.025
                    and math.abs(ownerSpeed - 1) > 0.015
                then
                    trackSpeed = ownerSpeed
                end

                local remaining = (hitTL - trackTime) / trackSpeed
                if remaining < -0.055 then
                    break
                end

                local _, uplink = getUplink()
                uplink = math.clamp(math.max(0, tonumber(uplink) or 0), 0, 0.18)
                local reaction = dodgeNumber("dodge_reaction", 100, 40, 300) / 1000
                local requestedWindow = autoIFrameWindowMs() / 1000
                local effectiveWindow = math.min(requestedWindow, SOURCE_IFRAME_DURATION)
                local lead = math.clamp(
                    reaction + uplink + 0.012,
                    0.095,
                    math.max(0.095, effectiveWindow - 0.025)
                )

                if kind == "wrestling_antigrab" then
                    lead = math.max(lead, 0.255)
                elseif kind == "kure_antigrab" then
                    lead = math.max(lead, 0.220)
                elseif kind == "hakari_double_read" then
                    lead = math.max(lead, 0.245)
                end

                lead = math.min(
                    lead,
                    math.max(0.095, effectiveWindow - 0.025)
                )

                local context, contextReason = Special.getContext(
                    character,
                    remaining,
                    style,
                    kind
                )
                local activeLead = lead

                if context
                    and context.walkingInto == true
                    and (
                        kind == "wrestling_antigrab"
                        or kind == "kure_antigrab"
                    )
                then
                    activeLead = math.max(
                        activeLead,
                        math.min(
                            effectiveWindow - 0.020,
                            0.275
                        )
                    )
                end

                if context then
                    local guardRadius =
                        kind == "hakari_double_read"
                            and 12.0
                            or (
                                kind == "wrestling_antigrab"
                                and 11.5
                                or 10.5
                            )
                    local guardWindow =
                        kind == "wrestling_antigrab"
                            and 0.50
                            or (
                                kind == "hakari_double_read"
                                and 0.48
                                or 0.40
                            )

                    if remaining >= 0
                        and remaining <= guardWindow
                        and context.distance <= guardRadius
                    then
                        DodgeRuntime.guardSpecialResource(
                            character.Name,
                            kind,
                            os.clock() + remaining
                        )

                        local verticalAllowance =
                            context.vertical
                            <= (context.verticalReach + 1.25)

                        if verticalAllowance
                            and (
                                kind == "wrestling_antigrab"
                                or kind == "kure_antigrab"
                                or context.facingDot >= -0.15
                                or context.closing >= 1.0
                            )
                        then
                            context.dangerous = true
                        end

                        if threat.specialNearLogged ~= true then
                            threat.specialNearLogged = true
                            debugLog("DODGE_SPECIAL_NEAR", {
                                owner = character.Name,
                                style = style,
                                kind = kind,
                                distance = context.distance,
                                facingDot = context.facingDot,
                                closing = context.closing,
                                vertical = context.vertical,
                                remaining = remaining,
                                dangerous = context.dangerous == true,
                            }, true)
                        end
                    end

                    local latchRadius =
                        kind == "hakari_double_read"
                            and 10.2
                            or (
                                kind == "wrestling_antigrab"
                                and 9.4
                                or 8.3
                            )

                    if armedLogged
                        and context.dangerous ~= true
                        and remaining >= -0.025
                        and context.distance <= latchRadius
                    then
                        context.dangerous = true
                    end
                end

                if context and context.dangerous then
                    local contactAbs = os.clock() + math.max(0, remaining)
                    DodgeRuntime.reserveSpecial(character.Name, kind, contactAbs)

                    if remaining <= activeLead + 0.095 then
                        DodgeRuntime.preparePriorityHandoff(context.character)
                    end

                    if not armedLogged then
                        armedLogged = true
                        debugLog("DODGE_SPECIAL_ARM", {
                            owner = character.Name,
                            style = style,
                            kind = kind,
                            distance = context.distance,
                            forward = context.forward,
                            lateral = context.lateral,
                            facingDot = context.facingDot,
                            vertical = context.vertical,
                            contactIn = math.max(0, remaining),
                            lead = activeLead,
                            walkIn = context.walkingInto == true,
                            hitTL = hitTL,
                        }, true)
                    end

                    if remaining <= activeLead then
                        local prediction = {
                            contactAbs = os.clock() + math.max(0, remaining),
                            up = uplink,
                        }

                        local committed, reason = fireDodge(
                            threat,
                            prediction,
                            context,
                            kind,
                            kind == "hakari_double_read"
                                and "MomentumM2"
                                or "M2Grab"
                        )

                        if committed then
                            DodgeRuntime.specialReservations[character.Name] = nil
                            debugLog("DODGE_SPECIAL_COMMIT", {
                                owner = character.Name,
                                style = style,
                                kind = kind,
                                distance = context.distance,
                                contactIn = math.max(0, remaining),
                            }, true)
                            return
                        end

                        if lastGate ~= reason then
                            lastGate = reason
                            debugLog("DODGE_SPECIAL_GATE", {
                                owner = character.Name,
                                style = style,
                                kind = kind,
                                reason = reason or "unknown",
                                distance = context.distance,
                                contactIn = math.max(0, remaining),
                            }, true)
                        end




                        if remaining <= 0.030
                            or threat.dodgeAttemptPending == true
                        then
                            break
                        end

                        task.wait(0.020)
                    elseif remaining - activeLead > 0.020 then
                        task.wait(
                            math.min(
                                0.020,
                                remaining - activeLead - 0.010
                            )
                        )
                    else
                        RunService.Heartbeat:Wait()
                    end
                else
                    if contextReason and lastGate ~= contextReason then
                        lastGate = contextReason
                    end

                    if remaining > 0.060 then
                        task.wait(0.020)
                    else
                        RunService.Heartbeat:Wait()
                    end
                end
            end

            DodgeRuntime.specialReservations[character.Name] = nil

            if armedLogged and threat.dodgeCommitted ~= true then
                debugLog("DODGE_SPECIAL_END", {
                    owner = character.Name,
                    style = style,
                    kind = kind,
                    fired = threat.fired == true,
                    activationConfirmed = threat.dodgeActivationConfirmed == true,
                }, true)
            end
        end)
    end

    function Special.watchCharacter(character)
        if DodgeRuntime.shutdownRequested == true
            or not character
            or Special.watched[character]
            or character == getCharacter()
            or character.Name == LocalPlayer.Name
        then
            return
        end

        Special.watched[character] = true

        task.spawn(function()
            local humanoid = character:FindFirstChildOfClass("Humanoid")
                or character:WaitForChild("Humanoid", 10)
            if DodgeRuntime.shutdownRequested == true
                or not humanoid
                or not character.Parent
            then
                return
            end

            local animator = humanoid:FindFirstChildOfClass("Animator")
                or humanoid:WaitForChild("Animator", 10)
            if DodgeRuntime.shutdownRequested == true
                or not animator
            then
                return
            end

            Menu._ScriptRuntime:Track(
                animator.AnimationPlayed:Connect(function(track)
                    local kind, style, id = Special.classify(character, track)
                    if kind and Special.kindEnabled(kind) then
                        Special.schedule(character, track, kind, style, id)
                    end
                end)
            )

            for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
                local kind, style, id = Special.classify(character, track)
                if kind and Special.kindEnabled(kind) then
                    task.defer(Special.schedule, character, track, kind, style, id)
                end
            end
        end)
    end

    function Special.watchFolder(folder)
        if DodgeRuntime.shutdownRequested == true
            or not folder
        then
            return
        end

        for _, character in ipairs(folder:GetChildren()) do
            Special.watchCharacter(character)
        end

        Menu._ScriptRuntime:Track(
            folder.ChildAdded:Connect(function(character)
                Special.watchCharacter(character)
            end)
        )
    end

    function Special.start()
        if Special.started then
            return
        end
        Special.started = true
        Special.refreshAnimationIds()

        Special.watchFolder(Workspace:FindFirstChild("Players"))
        Special.watchFolder(Workspace:FindFirstChild("NPCs"))

        Menu._ScriptRuntime:Track(
            Workspace.ChildAdded:Connect(function(child)
                if child.Name == "Players" or child.Name == "NPCs" then
                    Special.watchFolder(child)
                end
            end)
        )

        debugLog("DODGE_SPECIAL_READY", {
            wrestling = Special.animationIds.wrestling_antigrab or "",
            kure = Special.animationIds.kure_antigrab or "",
            hakariMomentum = Special.animationIds.hakari_double_read or "",
        }, true)
    end

    Special.start()

    function DodgeRuntime.shutdown()
        DodgeRuntime.shutdownRequested = true
        DodgeRuntime.unlockAutomaticDirection(
            DodgeRuntime.inputLockSerial
        )
        table.clear(DodgeRuntime.specialReservations)
        DodgeRuntime.specialResourceGuard.untilAt = 0
        DodgeRuntime.specialResourceGuard.ownerName = ""
        DodgeRuntime.specialResourceGuard.kind = ""
    end

    function DodgeRuntime.reset()
        DodgeRuntime.shutdownRequested = false
        DodgeRuntime.unlockAutomaticDirection(
            DodgeRuntime.inputLockSerial
        )
        table.clear(DodgeRuntime.specialReservations)
        DodgeRuntime.specialResourceGuard.untilAt = 0
        DodgeRuntime.specialResourceGuard.ownerName = ""
        DodgeRuntime.specialResourceGuard.kind = ""
    end

    function DodgeRuntime.getDebugSnapshot()
        local character = getCharacter()
        local module = getCombatModule("Evasive")
        local active = false

        if module and type(module.IsDashActive) == "function" then
            local ok, result = pcall(module.IsDashActive)
            active = ok and result == true
        end

        return {
            enabled = dodgeEnabled(),
            iframeDuration = SOURCE_IFRAME_DURATION,
            dashDuration = SOURCE_DASH_DURATION,
            sourceServerConfirm = SOURCE_SERVER_CONFIRM,
            dashActive = active,
            iframe = character and character:GetAttribute("IFRAMES") == true or false,
            iframeCooldown = character and character:GetAttribute("IFRAMECD") == true or false,
            cooldownRemaining = character
                and character:GetAttribute("EvasiveCooldownRemaining")
                or nil,
            outnumberedGrant = character
                and character:GetAttribute("OutnumberedEvasiveGrant") == true
                or false,
        }
    end
end


local localWorkspaceCharacterName = LocalPlayer.Name






local function getThreatHitTimeline(threat)
    local owner = threat.owner
    local style = threat.style or getStyle(owner)

    threat.style = style

    if threat.attackType == "M1" then
        local combo = math.clamp(tonumber(threat.combo) or 1, 1, 4)
        threat.combo = combo

        local ok, timeline = pcall(
            CombatConfig.GetScaledStyleM1HitboxDelay,
            style,
            combo,
            1
        )

        if ok and typeof(timeline) == "number" then
            return math.max(0.05, timeline)
        end

        local verified = getVerifiedStyleDelay(style, "M1", combo)
        if typeof(verified) == "number" then
            return math.max(0.05, verified)
        end

        return tonumber(CombatConfig.M1.DefaultHitboxDelay) or 0.32
    end

    local hakariDouble = style == "hakari"
        and (
            threat.hakariMomentum == true
            or (
                threat.hakariMomentum == nil
                and owner
                and owner:GetAttribute("HakariM2DoubleWindow") == true
            )
        )

    local variant = threat.variant

    if variant == nil then
        local okVariant, resolvedVariant = pcall(
            CombatStepUtils.ResolveM2VariantId,
            style,
            owner
        )

        if okVariant then
            variant = resolvedVariant
        end

        threat.variant = variant
    end

    local okBase, baseDelay = pcall(
        CombatConfig.GetStyleM2HitboxDelay,
        style,
        hakariDouble,
        variant
    )

    if not okBase or typeof(baseDelay) ~= "number" then
        baseDelay = getVerifiedStyleDelay(style, "M2")
            or tonumber(CombatConfig.M2.DefaultHitboxDelay)
            or 0.30
    end

    local okTimeline, timeline = pcall(
        CombatConfig.GetScaledHitboxDelay,
        baseDelay,
        1
    )

    if okTimeline and typeof(timeline) == "number" then
        return math.max(0.05, timeline)
    end

    return math.max(0.05, baseDelay)
end

local function passesThreatFilters(threat)
    local character = getCharacter()
    local myRoot = getRoot(character)

    if not character or not myRoot then
        return false, "local_missing"
    end

    local owner = threat.owner or resolveOwner(threat)
    local attackType = threat.attackType
    local style = threat.style or getStyle(owner)
    local ownerRoot = getRoot(owner)

    if attackType == "M2"
        and normalizeCombatStyleKey(tostring(style or "")) == "cqc"
    then
        return false, "cqc_m2_interrupt_only"
    end

    if owner and owner.Name == localWorkspaceCharacterName then
        return false, "own_attack"
    end

    local targetPosition

    if ownerRoot then
        targetPosition = ownerRoot.Position
    elseif threat.hitbox and threat.hitbox.Parent then
        targetPosition = threat.hitbox.Position
    else
        return false, "owner_missing"
    end

    local delta = targetPosition - myRoot.Position
    local flatDistance = flat(delta).Magnitude
    local maxRange = AUTO_PARRY_RANGE
    local rescueProofReason =
        tostring(threat.resolverProofReason or "")
    local rescueContactAbs =
        tonumber(threat.expectedContactAbs)
    local kyokushinM2VerifiedTracking =
        style == "kyokushin"
        and attackType == "M2"
        and threat.source == "animation"
        and threat.fired ~= true
        and rescueContactAbs ~= nil
        and os.clock() <= rescueContactAbs + 0.080
        and flatDistance <= AUTO_PARRY_TRACK_RANGE
        and (
            threat.serverConfirmed == true
            or rescueProofReason == "replicated-M2"
            or rescueProofReason == "m2-cooldown-edge"
            or rescueProofReason == "combat-token-type"
            or rescueProofReason == "combat-token-edge"
        )
    local resolverStoppedTracking =
        threat.source == "animation"
        and threat.serverConfirmed ~= true
        and threat.resolverStoppedTrackHandoff == true
        and threat.fired ~= true
        and rescueContactAbs ~= nil
        and os.clock()
            <= rescueContactAbs + 0.36
        and flatDistance
            <= AUTO_PARRY_TRACK_RANGE

    local animationTracking =
        (
            threat.source == "animation"
            and threat.serverConfirmed ~= true
            and threat.track
            and threat.track.IsPlaying ~= false
            and flatDistance <= AUTO_PARRY_TRACK_RANGE
        )
        or kyokushinM2VerifiedTracking
        or resolverStoppedTracking
    local armReady = false
    local effectiveReachForContext = nil

    local serverHitboxPhysical = false
    local serverHitboxDistance = math.huge

    if threat.serverConfirmed == true
        and threat.hitbox
        and threat.hitbox.Parent
        and threat.hitbox:IsA("BasePart")
    then
        local hitbox = threat.hitbox
        local localPoint = hitbox.CFrame:PointToObjectSpace(myRoot.Position)
        local rootRadius = math.max(myRoot.Size.X, myRoot.Size.Z) * 0.5
        local rootHalfY = myRoot.Size.Y * 0.5
        local cushion = 0.70

        serverHitboxDistance =
            flat(hitbox.Position - myRoot.Position).Magnitude

        serverHitboxPhysical =
            math.abs(localPoint.X)
                <= hitbox.Size.X * 0.5 + rootRadius + cushion
            and math.abs(localPoint.Z)
                <= hitbox.Size.Z * 0.5 + rootRadius + cushion
            and math.abs(localPoint.Y)
                <= hitbox.Size.Y * 0.5 + rootHalfY + cushion
    end

    if flatDistance > maxRange
        and not serverHitboxPhysical
        and not animationTracking
    then
        return false, "range"
    end

    local maxHeight = AUTO_PARRY_MAX_HEIGHT_DIFF

    if math.abs(delta.Y) > maxHeight and not serverHitboxPhysical then
        return false, "height"
    end







    if ownerRoot and (threat.attackType == "M1" or threat.attackType == "M2") then
        local defaultOffset = attackType == "M2"
            and tonumber(CombatConfig.M2.DefaultHitboxForwardOffset)
            or tonumber(CombatConfig.M1.DefaultHitboxForwardOffset)
        local forwardOffset = defaultOffset or (attackType == "M2" and 3 or 4)

        pcall(function()
            local value = CombatConfig.GetStyleHitboxForwardOffset(style, attackType)
            if typeof(value) == "number" then
                forwardOffset = math.max(0, value)
            end
        end)

        local stepForward = 0
        if attackType == "M2" then
            pcall(function()
                local value = CombatConfig.GetStyleM2StepForwardStuds(style)
                if typeof(value) == "number" then
                    stepForward = math.max(0, value)
                end
            end)
        else
            pcall(function()
                local value = CombatConfig.GetStyleM1StepForwardStuds(
                    style,
                    math.clamp(math.floor(tonumber(threat.combo) or 1), 1, 4)
                )
                if typeof(value) == "number" then
                    stepForward = math.max(0, value)
                end
            end)
        end

        local hitboxHalf = 2.05
        if threat.hitbox and threat.hitbox.Parent and threat.hitbox:IsA("BasePart") then
            hitboxHalf = math.max(threat.hitbox.Size.X, threat.hitbox.Size.Z) * 0.5
        end

        local localRadius = math.max(myRoot.Size.X, myRoot.Size.Z) * 0.5
        local toLocal = flat(myRoot.Position - ownerRoot.Position)
        local ownerVelocity = flat(ownerRoot.AssemblyLinearVelocity)
        local ownerLook =
            flat(ownerRoot.CFrame.LookVector)
        local ownerFacingDot = -1

        if toLocal.Magnitude > 0.1
            and ownerLook.Magnitude > 0.1
        then
            ownerFacingDot =
                math.clamp(
                    ownerLook.Unit:Dot(
                        toLocal.Unit
                    ),
                    -1,
                    1
                )
        end

        local ownerFacingAngle =
            math.deg(
                math.acos(
                    math.clamp(
                        ownerFacingDot,
                        -1,
                        1
                    )
                )
            )

        if threat.apInitialOwnerFacingDot == nil then
            threat.apInitialOwnerFacingDot =
                ownerFacingDot
            threat.apInitialOwnerFacingAngle =
                ownerFacingAngle
        end

        local facingSampleAt = os.clock()
        local previousOwnerFacingDot =
            tonumber(
                threat.apPreviousOwnerFacingDot
            )
        local previousOwnerFacingAt =
            tonumber(
                threat.apPreviousOwnerFacingAt
            ) or facingSampleAt
        local ownerFacingGainRate = 0

        if previousOwnerFacingDot ~= nil then
            local facingDt =
                math.max(
                    facingSampleAt
                        - previousOwnerFacingAt,
                    1 / 240
                )
            ownerFacingGainRate =
                (
                    ownerFacingDot
                    - previousOwnerFacingDot
                ) / facingDt
        end

        threat.apPreviousOwnerFacingDot =
            ownerFacingDot
        threat.apPreviousOwnerFacingAt =
            facingSampleAt
        threat.apCurrentOwnerFacingDot =
            ownerFacingDot
        threat.apCurrentOwnerFacingAngle =
            ownerFacingAngle
        threat.apCurrentOwnerFacingGainRate =
            ownerFacingGainRate
        threat.apMinOwnerFacingDot =
            math.min(
                tonumber(
                    threat.apMinOwnerFacingDot
                ) or ownerFacingDot,
                ownerFacingDot
            )
        threat.apMaxOwnerFacingGainRate =
            math.max(
                tonumber(
                    threat.apMaxOwnerFacingGainRate
                ) or ownerFacingGainRate,
                ownerFacingGainRate
            )




        if attackType == "M2" and style == "capoeira" then
            ownerVelocity = Vector3.zero
        end

        local relativeVelocity =
            ownerVelocity - flat(myRoot.AssemblyLinearVelocity)
        local closing = 0
        if toLocal.Magnitude > 0.1 then
            closing = relativeVelocity:Dot(toLocal.Unit)
        end

        local distanceSampleAt = os.clock()
        local previousDistance =
            tonumber(threat.apPreviousFlatDistance)
        local previousDistanceAt =
            tonumber(threat.apPreviousFlatDistanceAt)
                or distanceSampleAt
        local measuredClosing = 0

        if previousDistance ~= nil then
            local distanceDt =
                distanceSampleAt - previousDistanceAt

            if distanceDt >= 1 / 240
                and distanceDt <= 0.12
            then
                measuredClosing =
                    math.clamp(
                        (
                            previousDistance
                            - flatDistance
                        ) / distanceDt,
                        -40,
                        40
                    )
            end
        end

        threat.apPreviousFlatDistance =
            flatDistance
        threat.apPreviousFlatDistanceAt =
            distanceSampleAt

        local previousMeasuredClosing =
            tonumber(
                threat.apMeasuredClosing
            ) or 0

        if measuredClosing > 0 then
            threat.apMeasuredClosing =
                math.max(
                    measuredClosing,
                    previousMeasuredClosing * 0.72
                )
        else
            threat.apMeasuredClosing =
                math.max(
                    0,
                    previousMeasuredClosing * 0.72
                )
        end

        local motionHorizon = 0.12

        if threat.source == "animation"
            and threat.serverConfirmed ~= true
            and threat.track
        then
            local trackTime = math.max(
                0,
                tonumber(threat.track.TimePosition) or 0
            )
            local hitTL = math.max(
                0,
                tonumber(threat.hitTL) or getThreatHitTimeline(threat)
            )
            local visualTrackSpeed =
                tonumber(threat.track.Speed) or 1
            local combatTrackSpeed =
                tonumber(
                    threat.speedMultiplier
                        or getSpeedMultiplier(owner)
                ) or 1

            if visualTrackSpeed < 0.2
                or visualTrackSpeed > 3
            then
                visualTrackSpeed = 1
            end

            if combatTrackSpeed < 0.2
                or combatTrackSpeed > 3
            then
                combatTrackSpeed = 1
            end

            local trackSpeed =
                visualTrackSpeed
            local timingTrackTime =
                trackTime

            if visualTrackSpeed >= 1.15
                and visualTrackSpeed
                    > combatTrackSpeed + 0.10
            then
                trackSpeed =
                    combatTrackSpeed
                local animationStartedAt =
                    tonumber(
                        threat.animationStartedAt
                    ) or threat.createdAt
                timingTrackTime =
                    math.max(
                        0,
                        (
                            os.clock()
                            - animationStartedAt
                        ) * trackSpeed
                    )
            end

            local remaining = math.max(
                0,
                (
                    hitTL
                    - timingTrackTime
                ) / math.max(
                    trackSpeed,
                    0.2
                )
            )


            threat.apReachTimelineRemaining =
                remaining



            if attackType == "M2" and style == "boxing" then
                remaining += 0.145
            end

            local horizonMax = 0.12
            local ownerAttackSpeed =
                tonumber(threat.speedMultiplier)
                or getSpeedMultiplier(owner)
            local aggressiveStyle =
                isAggressiveAutoParryStyle(style)
            local shortFast =
                aggressiveStyle
                and ownerAttackSpeed >= 1.035





            if closing >= 24 then
                horizonMax = aggressiveStyle and 0.205 or 0.17
            elseif closing >= 14 then
                horizonMax = aggressiveStyle and 0.180 or 0.145
            end

            if shortFast then
                horizonMax = math.max(
                    horizonMax,
                    attackType == "M2" and 0.195 or 0.180
                )
            end

            motionHorizon = math.clamp(
                remaining + 0.035,
                0.035,
                horizonMax
            )
        end

        local ownerAttackSpeed =
            tonumber(threat.speedMultiplier)
            or getSpeedMultiplier(owner)
        local aggressiveStyle =
            isAggressiveAutoParryStyle(style)
        local shortFast =
            aggressiveStyle
            and ownerAttackSpeed >= 1.035

        local motionAllowanceCap = closing >= 24
            and (aggressiveStyle and 4.35 or 3.75)
            or (
                closing >= 14
                and (aggressiveStyle and 3.65 or 3.0)
                or (shortFast and 3.15 or 2.5)
            )

        local motionAllowance = math.clamp(
            math.max(0, closing) * motionHorizon,
            0,
            motionAllowanceCap
        )

        local aggressiveReachPad = 0
        if shortFast then
            aggressiveReachPad = 0.45
        elseif aggressiveStyle and closing >= 14 then
            aggressiveReachPad = 0.25
        end

        local effectiveReach = math.min(
            AUTO_PARRY_RANGE,
            forwardOffset
                + stepForward
                + hitboxHalf
                + localRadius
                + 1.75
                + aggressiveReachPad
                + motionAllowance
                + (
                    style == "kyokushin"
                    and attackType == "M2"
                    and threat.source == "animation"
                    and (
                        threat.serverConfirmed == true
                        or rescueProofReason == "replicated-M2"
                        or rescueProofReason == "m2-cooldown-edge"
                        or rescueProofReason == "combat-token-type"
                        or rescueProofReason == "combat-token-edge"
                    )
                    and 2.85
                    or 0
                )
        )

        effectiveReachForContext = effectiveReach

        local armSlack =
            attackType == "M2"
                and 1.75
                or 1.55

        if style == "boxing"
            or style == "capoeira"
            or style == "kure"
            or style == "wrestling"
            or style == "kyokushin"
            or style == "cqc"
        then
            armSlack += 0.10
        end

        local armThreshold = math.min(
            AUTO_PARRY_RANGE,
            effectiveReach + armSlack
        )

        local approachReady = false
        local approachProjection = 0
        local projectedContactDistance =
            flatDistance
        local projectionClosing =
            math.max(
                0,
                closing,
                tonumber(
                    threat.apMeasuredClosing
                ) or 0
            )

        if threat.source == "animation"
            and threat.serverConfirmed ~= true
            and threat.track
            and threat.track.IsPlaying ~= false
            and projectionClosing >= 5.5
            and ownerFacingDot >= 0.30
        then
            local reachRemaining =
                tonumber(
                    threat.apReachTimelineRemaining
                ) or 0
            local approachHorizon =
                math.clamp(
                    reachRemaining + 0.075,
                    motionHorizon,
                    0.24
                )
            local extraHorizon =
                math.max(
                    0,
                    approachHorizon
                    - motionHorizon
                )

            approachProjection =
                math.clamp(
                    projectionClosing
                    * extraHorizon,
                    0,
                    2.35
                )
            projectedContactDistance =
                flatDistance
                - approachProjection

            approachReady =
                approachProjection >= 0.20
                and projectedContactDistance
                    <= armThreshold + 0.30

            if approachReady
                and threat.apApproachArmLogged
                    ~= true
            then
                threat.apApproachArmLogged = true
                debugLog("AP_APPROACH_ARM", {
                    attack =
                        threat.attackType or "",
                    owner =
                        threat.ownerName or "",
                    style = style,
                    combo =
                        threat.combo or 0,
                    distance =
                        flatDistance,
                    effectiveReach =
                        effectiveReach,
                    armThreshold =
                        armThreshold,
                    assemblyClosing =
                        closing,
                    measuredClosing =
                        tonumber(
                            threat.apMeasuredClosing
                        ) or 0,
                    projectionClosing =
                        projectionClosing,
                    motionHorizon =
                        motionHorizon,
                    reachRemaining =
                        reachRemaining,
                    approachProjection =
                        approachProjection,
                    projectedContactDistance =
                        projectedContactDistance,
                    attackerFacingDot =
                        ownerFacingDot,
                    attackerFacingAngle =
                        ownerFacingAngle,
                }, true)
            end
        end

        local clockNow = os.clock()
        local redirectActive = false
        local redirectCandidate = false
        local redirectThreshold = armThreshold

        if attackType == "M1"
            and threat.source == "animation"
            and threat.serverConfirmed ~= true
            and threat.track
        then
            local redirectTrackTime =
                math.max(
                    0,
                    tonumber(
                        threat.track.TimePosition
                    ) or 0
                )
            local redirectHitTL =
                math.max(
                    0,
                    tonumber(threat.hitTL)
                        or getThreatHitTimeline(
                            threat
                        )
                )
            local visualRedirectSpeed =
                tonumber(threat.track.Speed) or 1
            local combatRedirectSpeed =
                tonumber(
                    threat.speedMultiplier
                        or getSpeedMultiplier(owner)
                ) or 1

            if visualRedirectSpeed < 0.2
                or visualRedirectSpeed > 3
            then
                visualRedirectSpeed = 1
            end

            if combatRedirectSpeed < 0.2
                or combatRedirectSpeed > 3
            then
                combatRedirectSpeed = 1
            end

            local redirectSpeed =
                visualRedirectSpeed
            local timingRedirectTrackTime =
                redirectTrackTime

            if visualRedirectSpeed >= 1.15
                and visualRedirectSpeed
                    > combatRedirectSpeed + 0.10
            then
                redirectSpeed =
                    combatRedirectSpeed
                local animationStartedAt =
                    tonumber(
                        threat.animationStartedAt
                    ) or threat.createdAt
                timingRedirectTrackTime =
                    math.max(
                        0,
                        (
                            clockNow
                            - animationStartedAt
                        ) * redirectSpeed
                    )
            end

            local redirectRemaining =
                (
                    redirectHitTL
                    - timingRedirectTrackTime
                ) / math.max(
                    redirectSpeed,
                    0.2
                )
            local initialFacingDot =
                tonumber(
                    threat.apInitialOwnerFacingDot
                ) or ownerFacingDot
            local minimumFacingDot =
                math.min(
                    initialFacingDot,
                    tonumber(
                        threat.apMinOwnerFacingDot
                    ) or initialFacingDot
                )
            local facingGain =
                ownerFacingDot
                - minimumFacingDot
            local maxFacingGainRate =
                math.max(
                    ownerFacingGainRate,
                    tonumber(
                        threat.apMaxOwnerFacingGainRate
                    ) or 0
                )
            local measuredTurnRate =
                tonumber(
                    threat.turnRate
                ) or 0

            redirectThreshold =
                math.min(
                    AUTO_PARRY_RANGE,
                    effectiveReach + 5.75
                )

            redirectCandidate =
                minimumFacingDot <= 0.55
                and redirectRemaining >= -0.18
                and redirectRemaining <= 0.50
                and flatDistance
                    <= redirectThreshold

            local airPunchRedirect =
                minimumFacingDot <= 0.10
                and ownerFacingDot >= 0.08
                and facingGain >= 0.28

            local lateSnapRedirect =
                minimumFacingDot <= 0.55
                and ownerFacingDot >= 0.30
                and facingGain >= 0.22
                and redirectRemaining <= 0.30

            local lastMomentRedirect =
                minimumFacingDot <= 0.65
                and ownerFacingDot >= 0.42
                and facingGain >= 0.18
                and redirectRemaining <= 0.16

            local fastTurn =
                maxFacingGainRate >= 0.55
                or measuredTurnRate >= 0.75

            local kureSnapPrearm =
                style == "kure"
                and attackType == "M1"
                and redirectCandidate
                and redirectRemaining <= 0.26
                and flatDistance
                    <= math.min(
                        AUTO_PARRY_RANGE,
                        effectiveReach + 2.75
                    )
                and ownerFacingDot >= -0.48
                and facingGain >= 0.08
                and maxFacingGainRate >= 2.0

            local redirectDetected =
                redirectCandidate
                and fastTurn
                and (
                    airPunchRedirect
                    or lateSnapRedirect
                    or lastMomentRedirect
                    or kureSnapPrearm
                )

            if redirectDetected then
                if kureSnapPrearm then
                    threat.apKureSnapPrearm = true
                end
                threat.apRedirectUntil =
                    math.max(
                        tonumber(
                            threat.apRedirectUntil
                        ) or 0,
                        clockNow
                            + math.clamp(
                                redirectRemaining
                                    + 0.16,
                                0.16,
                                0.48
                            )
                    )
                threat.apRedirectThreshold =
                    math.max(
                        tonumber(
                            threat.apRedirectThreshold
                        ) or 0,
                        redirectThreshold
                    )

                if threat.apRedirectLogged
                    ~= true
                then
                    threat.apRedirectLogged = true
                    debugLog(
                        "AP_REDIRECT_AIM",
                        {
                            attack =
                                threat.attackType
                                or "",
                            owner =
                                threat.ownerName
                                or "",
                            style = style,
                            combo =
                                threat.combo or 0,
                            distance =
                                flatDistance,
                            effectiveReach =
                                effectiveReach,
                            redirectThreshold =
                                redirectThreshold,
                            initialAttackerFacingDot =
                                initialFacingDot,
                            minimumAttackerFacingDot =
                                minimumFacingDot,
                            attackerFacingDot =
                                ownerFacingDot,
                            attackerFacingAngle =
                                ownerFacingAngle,
                            facingGain =
                                facingGain,
                            facingGainRate =
                                ownerFacingGainRate,
                            maxFacingGainRate =
                                maxFacingGainRate,
                            turnRate =
                                measuredTurnRate,
                            remaining =
                                redirectRemaining,
                            visualSpeed =
                                visualRedirectSpeed,
                            combatSpeed =
                                combatRedirectSpeed,
                            kureSnapPrearm =
                                kureSnapPrearm == true,
                        },
                        true
                    )
                end
            end

            local activeRedirectThreshold =
                tonumber(
                    threat.apRedirectThreshold
                ) or redirectThreshold

            local redirectFacingReady =
                ownerFacingDot >= 0.05
                or (
                    style == "kure"
                    and attackType == "M1"
                    and threat.apKureSnapPrearm == true
                    and ownerFacingDot >= -0.48
                )

            redirectActive =
                clockNow
                    <= (
                        tonumber(
                            threat.apRedirectUntil
                        ) or 0
                    )
                and redirectFacingReady
                and flatDistance
                    <= math.min(
                        AUTO_PARRY_RANGE,
                        activeRedirectThreshold
                            + 0.35
                    )

            if redirectActive
                and threat.apRedirectUseLogged
                    ~= true
            then
                threat.apRedirectUseLogged = true
                debugLog(
                    "AP_REDIRECT_ARM",
                    {
                        attack =
                            threat.attackType
                            or "",
                        owner =
                            threat.ownerName
                            or "",
                        style = style,
                        combo =
                            threat.combo or 0,
                        distance =
                            flatDistance,
                        effectiveReach =
                            effectiveReach,
                        redirectThreshold =
                            activeRedirectThreshold,
                        attackerFacingDot =
                            ownerFacingDot,
                        attackerFacingAngle =
                            ownerFacingAngle,
                    },
                    true
                )
            end
        end

        if threat.source == "animation"
            and threat.serverConfirmed ~= true
            and closing >= 12
            and flatDistance <= effectiveReach
        then
            local latchFor = 0.12

            if threat.track then
                local trackTime = math.max(
                    0,
                    tonumber(threat.track.TimePosition) or 0
                )
                local hitTL = math.max(
                    0,
                    tonumber(threat.hitTL) or getThreatHitTimeline(threat)
                )
                local speed = tonumber(threat.track.Speed) or 1
                if speed < 0.2 or speed > 3 then
                    speed = 1
                end

                latchFor = math.clamp(
                    (hitTL - trackTime) / math.max(speed, 0.2) + 0.09,
                    0.10,
                    0.36
                )
            end

            threat.apReachLatchedUntil = math.max(
                tonumber(threat.apReachLatchedUntil) or 0,
                clockNow + latchFor
            )
            threat.apReachLatchedDistance = flatDistance
            threat.apReachLatchedEffective = effectiveReach
            threat.apReachLatchedClosing = closing

            if threat.apReachLatchLogged ~= true then
                threat.apReachLatchLogged = true
                debugLog("AP_REACH_LATCH", {
                    attack = threat.attackType or "",
                    owner = threat.ownerName or "",
                    style = style,
                    combo = threat.combo or 0,
                    distance = flatDistance,
                    effectiveReach = effectiveReach,
                    closing = closing,
                    latchMs = math.floor(latchFor * 1000 + 0.5),
                }, true)
            end
        end

        local latched =
            threat.source == "animation"
            and threat.serverConfirmed ~= true
            and clockNow
                <= (tonumber(threat.apReachLatchedUntil) or 0)
            and flatDistance <= AUTO_PARRY_RANGE
            and flatDistance <= effectiveReach + 3.0
            and closing > -18

        local matchedServerOwnerPad =
            threat.attackType == "M1"
                and 2.35
                or 1.65
        local matchedServerNearArm =
            threat.serverConfirmed == true
            and threat.hitbox
            and threat.hitbox.Parent
            and serverHitboxDistance < math.huge
            and serverHitboxDistance
                <= armThreshold + 0.60
            and flatDistance
                <= armThreshold + matchedServerOwnerPad

        local liveArmReady =
            serverHitboxPhysical
            or matchedServerNearArm
            or flatDistance <= armThreshold
            or latched
            or redirectActive
            or approachReady

        if liveArmReady
            and threat.source == "animation"
            and threat.serverConfirmed ~= true
            and threat.track
        then
            local commitFor = 0.18
            local commitTrackTime = math.max(
                0,
                tonumber(threat.track.TimePosition) or 0
            )
            local commitHitTL = math.max(
                0,
                tonumber(threat.hitTL)
                    or getThreatHitTimeline(threat)
            )
            local commitSpeed =
                tonumber(threat.track.Speed) or 1

            if commitSpeed < 0.2
                or commitSpeed > 3
            then
                commitSpeed = 1
            end

            commitFor = math.clamp(
                (
                    commitHitTL - commitTrackTime
                ) / math.max(commitSpeed, 0.2)
                    + 0.13,
                0.14,
                0.55
            )

            threat.apArmCommittedUntil =
                math.max(
                    tonumber(
                        threat.apArmCommittedUntil
                    ) or 0,
                    clockNow + commitFor
                )
            threat.apArmCommittedThreshold =
                math.max(
                    tonumber(
                        threat.apArmCommittedThreshold
                    ) or 0,
                    armThreshold
                )

            if threat.apArmCommitLogged ~= true then
                threat.apArmCommitLogged = true
                debugLog("AP_ARM_COMMIT", {
                    attack =
                        threat.attackType or "",
                    owner =
                        threat.ownerName or "",
                    style = style,
                    combo = threat.combo or 0,
                    distance = flatDistance,
                    effectiveReach =
                        effectiveReach,
                    armSlack = armSlack,
                    armThreshold =
                        armThreshold,
                    commitMs =
                        math.floor(
                            commitFor
                            * 1000
                            + 0.5
                        ),
                }, true)
            end
        end

        local committedThreshold =
            tonumber(
                threat.apArmCommittedThreshold
            ) or armThreshold
        local commitDistancePad =
            closing >= -4
                and 2.0
                or 0.75

        local armCommitted =
            threat.source == "animation"
            and threat.serverConfirmed ~= true
            and clockNow
                <= (
                    tonumber(
                        threat.apArmCommittedUntil
                    ) or 0
                )
            and flatDistance
                <= math.min(
                    AUTO_PARRY_RANGE,
                    committedThreshold
                        + commitDistancePad
                )

        armReady =
            liveArmReady
            or armCommitted

        if armCommitted
            and not liveArmReady
            and threat.apArmCommitUseLogged
                ~= true
        then
            threat.apArmCommitUseLogged = true
            debugLog("AP_ARM_COMMIT_USE", {
                attack =
                    threat.attackType or "",
                owner =
                    threat.ownerName or "",
                style = style,
                combo = threat.combo or 0,
                distance = flatDistance,
                effectiveReach =
                    effectiveReach,
                armSlack = armSlack,
                armThreshold =
                    armThreshold,
                committedThreshold =
                    committedThreshold,
                commitDistancePad =
                    commitDistancePad,
                closing = closing,
                remainingMs =
                    math.max(
                        0,
                        math.floor(
                            (
                                (
                                    tonumber(
                                        threat.apArmCommittedUntil
                                    ) or clockNow
                                )
                                - clockNow
                            )
                            * 1000
                            + 0.5
                        )
                    ),
            }, true)
        end

        threat.apCurrentArmSlack =
            armSlack
        threat.apCurrentArmThreshold =
            armThreshold
        threat.apCurrentArmCommitted =
            armCommitted
        threat.apCurrentRedirectActive =
            redirectActive
        threat.apCurrentRedirectCandidate =
            redirectCandidate
        threat.apCurrentApproachReady =
            approachReady
        threat.apCurrentApproachProjection =
            approachProjection
        threat.apCurrentProjectedContactDistance =
            projectedContactDistance
        threat.apCurrentProjectionClosing =
            projectionClosing
        threat.apCurrentOwnerFacingDot =
            ownerFacingDot
        threat.apCurrentOwnerFacingAngle =
            ownerFacingAngle

        if not armReady
            and not animationTracking
        then
            return false, "reach"
        end

        if latched
            and flatDistance > effectiveReach
            and threat.apReachLatchUseLogged ~= true
        then
            threat.apReachLatchUseLogged = true
            debugLog("AP_REACH_LATCH_USE", {
                attack = threat.attackType or "",
                owner = threat.ownerName or "",
                style = style,
                combo = threat.combo or 0,
                distance = flatDistance,
                effectiveReach = effectiveReach,
                closing = closing,
                latchedDistance = threat.apReachLatchedDistance or "",
                latchedEffective = threat.apReachLatchedEffective or "",
                latchedClosing = threat.apReachLatchedClosing or "",
                remainingMs = math.max(
                    0,
                    math.floor(
                        (
                            (tonumber(threat.apReachLatchedUntil) or clockNow)
                            - clockNow
                        ) * 1000 + 0.5
                    )
                ),
            }, true)
        end
    end

    if serverHitboxPhysical then
        armReady = true
    end

    if serverHitboxPhysical
        and threat.serverPhysicalReachLogged ~= true
    then
        threat.serverPhysicalReachLogged = true
        debugLog("SERVER_ACTIVE_HITBOX_REACH", {
            attack = threat.attackType or "",
            owner = threat.ownerName or "",
            style = threat.style or "",
            source = threat.source or "",
            ownerDistance = flatDistance,
            hitboxDistance = serverHitboxDistance,
        }, true)
    end

    return true, nil, {
        character = character,
        myRoot = myRoot,
        owner = owner,
        ownerRoot = ownerRoot,
        distance = flatDistance,
        heightDiff = math.abs(delta.Y),
        serverHitboxDistance = serverHitboxDistance,
        serverHitboxPhysical = serverHitboxPhysical,
        tracking = animationTracking,
        armReady = armReady,
        effectiveReach = effectiveReachForContext,
        armSlack =
            threat.apCurrentArmSlack,
        armThreshold =
            threat.apCurrentArmThreshold,
        armCommitted =
            threat.apCurrentArmCommitted == true,
        redirectActive =
            threat.apCurrentRedirectActive == true,
        redirectCandidate =
            threat.apCurrentRedirectCandidate == true,
        approachReady =
            threat.apCurrentApproachReady == true,
        approachProjection =
            threat.apCurrentApproachProjection,
        projectedContactDistance =
            threat.apCurrentProjectedContactDistance,
        projectionClosing =
            threat.apCurrentProjectionClosing,
        attackerFacingDot =
            threat.apCurrentOwnerFacingDot,
        attackerFacingAngle =
            threat.apCurrentOwnerFacingAngle,
        trackRange = AUTO_PARRY_TRACK_RANGE,
    }
end

local function getMotionLead(context, threat)
    local ownerRoot = context.ownerRoot
    local myRoot = context.myRoot

    if not ownerRoot or not myRoot then
        return 0, 0
    end

    local myVelocity = flat(myRoot.AssemblyLinearVelocity)
    local attackerVelocity = flat(ownerRoot.AssemblyLinearVelocity)




    if threat
        and threat.attackType == "M2"
        and (threat.style or getStyle(threat.owner)) == "capoeira"
    then
        attackerVelocity = Vector3.zero
    end

    local relative = attackerVelocity - myVelocity
    local direction = flat(myRoot.Position - ownerRoot.Position)
    local closing = 0

    if direction.Magnitude > 0.1 then
        closing = relative:Dot(direction.Unit)
    end

    local velLead = closing <= 0 and 0
        or math.clamp(closing / 22, 0, 1) * 0.045

    return velLead, closing
end

local function computeLiveOverlapDelay(threat, context)
    local hitbox = threat.hitbox

    if not hitbox or not hitbox.Parent or not hitbox:IsA("BasePart") then
        local velLead, closing = getMotionLead(context, threat)
        return 0, velLead, closing, 0
    end

    local myRoot = context.myRoot
    local localPoint = hitbox.CFrame:PointToObjectSpace(myRoot.Position)
    local size = hitbox.Size
    local halfW = size.X * 0.5
    local halfD = size.Z * 0.5
    local halfH = size.Y * 0.5 + 1.5

    if math.abs(localPoint.Y) > halfH then
        local velLead, closing = getMotionLead(context, threat)
        return 0.040, velLead, closing, math.abs(localPoint.X)
    end

    local side = math.abs(localPoint.X)
    local depth = localPoint.Z
    local gapSide = side - halfW
    local gapDepth = math.abs(depth) - halfD

    if gapSide < 0.75 then
        gapSide = 0
    end

    if gapDepth < 0.75 then
        gapDepth = 0
    end

    local velLead, closing = getMotionLead(context, threat)
    local dist2d = math.max(context.distance, 0.1)
    local omega = math.max(threat.turnRate or 0, 0)
    local dRot = omega > 0.05 and (gapSide / dist2d) / omega or 0.15
    local dApp = closing > 0.5 and gapDepth / closing or 0.15
    local overlapDelay = math.min(math.max(dRot, dApp), 0.040)

    return overlapDelay, velLead, closing, side
end

local animationThreats = {}
local serverFallbackThreats = {}

Menu._APHitboxProfiles =
    Menu._APHitboxProfiles
    or {}

Menu._AutoFaceRuntime = Menu._AutoFaceRuntime or {}
do
    local Runtime = Menu._AutoFaceRuntime
    local AUTO_FACE_RENDER_BIND = "Gakuran.AutoFace.RenderOwner"
    local PRIMARY_ACQUIRE_RANGE = 13.5
    local PRIMARY_MEMORY_SECONDS = 0.34
    local CROWD_EMERGENCY_ETA = 0.185
    local CROWD_MIN_TARGET_HOLD = 0.095
    local COMBO_BRIDGE_SECONDS = 0
    local CROWD_SWITCH_ETA_ADVANTAGE = 0.035
    local CROWD_SWITCH_SCORE_ADVANTAGE = 1.05
    local DEFENSE_COMMIT_ETA = 0.420
    local DEFENSE_COMMIT_POST_CONTACT = 0.075
    local DEFENSE_SWITCH_ETA_ADVANTAGE = 0.028

    -- Auto Face may begin before the replicated hitbox exists, but the AP
    -- envelope must stay close to the actual strike lane. These are deliberately
    -- lenient at point-blank range so side/rear close attacks still get faced.
    local AP_ONLY_CURRENT_RANGE_SLACK = 0.65
    local AP_ONLY_PROJECTED_RANGE_SLACK = 0.40

    -- Auto Face is intentionally stricter than AutoParry's own acquisition
    -- envelope. AP may track farther out, but yaw ownership should only begin
    -- when the attack is close enough to be a credible visual threat.
    local AUTOFACE_AP_ONLY_M1_CURRENT_CAP = 10.75
    local AUTOFACE_AP_ONLY_M2_CURRENT_CAP = 11.75

    -- A learned miss is only trusted away from point-blank range. This avoids
    -- the R12 regression where very close attacks were rejected too early.
    local AUTOFACE_MATURE_MISS_SAMPLES = 5
    local AUTOFACE_MATURE_MISS_DISTANCE = 6.75

    -- At genuinely far visual range we can trust a learned miss sooner. This
    -- rejects the remaining 10+ stud AP-only yaw steals without applying R12's
    -- old close-range hard veto.
    local AUTOFACE_FAR_MISS_SAMPLES = 3
    local AUTOFACE_FAR_MISS_DISTANCE = 9.25

    -- Once the real server hitbox for this swing is observed missing, prevent
    -- the looser AP envelope from stealing yaw again for the tail of that swing.
    local AUTOFACE_LIVE_MISS_QUARANTINE = 0.22

    -- Replicated hitboxes can move across the local overlap boundary between
    -- adjacent frames. Keep the exact same genuinely-physical hitbox for a few
    -- frames. Use owner distance, not hitbox-center distance: several real
    -- hitboxes have centers >8 studs away even while their extents overlap us.
    local AUTOFACE_PHYSICAL_HIT_GRACE = 0.065
    local AUTOFACE_PHYSICAL_GRACE_MAX_OWNER_DISTANCE =
        PRIMARY_ACQUIRE_RANGE + 1.0

    local function isTrustedAutoFaceLearnedMiss(
        hitboxModel,
        hitboxSamples,
        distance
    )
        if hitboxModel ~= "learned-server-hitbox" then
            return false
        end

        hitboxSamples =
            tonumber(hitboxSamples) or 0
        distance =
            tonumber(distance) or math.huge

        if distance >= AUTOFACE_FAR_MISS_DISTANCE then
            return hitboxSamples
                >= AUTOFACE_FAR_MISS_SAMPLES
        end

        return distance
                >= AUTOFACE_MATURE_MISS_DISTANCE
            and hitboxSamples
                >= AUTOFACE_MATURE_MISS_SAMPLES
    end

    if type(Runtime.shutdown) == "function" then
        pcall(Runtime.shutdown)
    elseif Runtime.connection then
        pcall(function()
            Runtime.connection:Disconnect()
        end)
        Runtime.connection = nil
    end
    pcall(function()
        RunService:UnbindFromRenderStep(AUTO_FACE_RENDER_BIND)
    end)

    Runtime.humanoid = nil
    Runtime.savedAutoRotate = nil
    Runtime.lockedTarget = nil
    Runtime.lockUntil = 0
    Runtime.lockReason = nil
    Runtime.lockPriority = 0
    Runtime.lockAcquiredAt = 0
    Runtime.lockImpactEta = math.huge
    Runtime.lastLockRejectKey = nil
    Runtime.lastLockRejectAt = 0
    Runtime.stickyTarget = nil
    Runtime.stickyUntil = 0
    Runtime.stickyScore = nil
    Runtime.lastFacingTarget = nil
    Runtime.lastDesiredYaw = nil
    Runtime.lastReportedTarget = nil
    Runtime.lastReportedMode = nil
    Runtime.faceNow = nil
    Runtime.primaryTarget = nil
    Runtime.primaryUntil = 0
    Runtime.selectedAt = 0
    Runtime.activeCandidateCount = 0
    Runtime.defenseTarget = nil
    Runtime.defenseUntil = 0
    Runtime.defenseImpactEta = math.huge
    Runtime.defenseHintTarget = nil
    Runtime.defenseHintUntil = 0
    Runtime.defenseHintImpactEta = math.huge
    Runtime.currentTarget = nil
    Runtime.currentMeta = nil
    Runtime.currentEvidenceAt = 0
    Runtime.verifiedHoldTarget = nil
    Runtime.verifiedHoldUntil = 0
    Runtime.verifiedHoldMeta = nil
    Runtime.renderBound = false
    Runtime.ownedRoot = nil
    Runtime.lastAppliedYaw = nil
    Runtime.lastRenderAt = nil
    Runtime.writingCFrame = false
    Runtime.rotationGuardInstalled =
        Runtime.rotationGuardInstalled
        == true

    local function isAutoFaceCombatEnabled()
        local character = getCharacter()
        return character ~= nil
            and character.Parent ~= nil
            and character:GetAttribute("Equip") == true
    end

    Runtime.isCombatEnabled = isAutoFaceCombatEnabled

    local function installAutoFaceRotationGuard()
        if Runtime.rotationGuardInstalled == true then
            return true
        end

        if type(hookmetamethod) ~= "function" then
            return false
        end

        local oldNewIndex

        local wrapper =
            function(object, key, value)
                if key == "CFrame"
                    and typeof(value) == "CFrame"
                    and object == Runtime.ownedRoot
                    and Runtime.writingCFrame ~= true
                    and Flags.ap_enable == true
                    and Flags.ap_auto_face == true
                    and isAutoFaceCombatEnabled()
                    and Runtime.currentTarget
                    and Runtime.currentTarget.Parent
                    and os.clock()
                        - (tonumber(Runtime.currentEvidenceAt) or 0)
                        <= 0.18
                then
                    local desiredYaw =
                        tonumber(
                            Runtime.lastAppliedYaw
                        )

                    if desiredYaw == nil then
                        desiredYaw =
                            tonumber(
                                Runtime.lastDesiredYaw
                            )
                    end

                    if desiredYaw == nil then
                        local root =
                            Runtime.ownedRoot
                        local targetRoot =
                            getRoot(
                                Runtime.currentTarget
                            )

                        if root
                            and root.Parent
                            and targetRoot
                            and targetRoot.Parent
                        then
                            local direction =
                                flat(
                                    targetRoot.Position
                                    - value.Position
                                )

                            if direction.Magnitude > 0.05 then
                                desiredYaw =
                                    math.atan2(
                                        -direction.Unit.X,
                                        -direction.Unit.Z
                                    )
                            end
                        end
                    end

                    if desiredYaw ~= nil then
                        local forced =
                            CFrame.new(
                                value.Position
                            )
                            * CFrame.Angles(
                                0,
                                desiredYaw,
                                0
                            )

                        return oldNewIndex(
                            object,
                            key,
                            forced
                        )
                    end
                end

                return oldNewIndex(
                    object,
                    key,
                    value
                )
            end

        if type(newcclosure) == "function" then
            wrapper =
                newcclosure(
                    wrapper
                )
        end

        local ok, result =
            pcall(function()
                oldNewIndex =
                    hookmetamethod(
                        game,
                        "__newindex",
                        wrapper
                    )

                return oldNewIndex
            end)

        if not ok
            or type(result) ~= "function"
        then
            return false
        end

        Runtime.rotationGuardInstalled =
            true
        Runtime.rotationGuardOldNewIndex =
            result

        return true
    end

    local function writeOwnedYaw(root, yaw)
        if not root
            or not root.Parent
            or type(yaw) ~= "number"
        then
            return false
        end

        Runtime.ownedRoot =
            root
        Runtime.lastAppliedYaw =
            yaw
        Runtime.writingCFrame =
            true

        local ok =
            pcall(function()
                root.CFrame =
                    CFrame.new(
                        root.Position
                    )
                    * CFrame.Angles(
                        0,
                        yaw,
                        0
                    )
            end)

        Runtime.writingCFrame =
            false

        return ok
    end

    installAutoFaceRotationGuard()

    local function releaseRotation()
        Runtime.ownedRoot = nil
        Runtime.lastAppliedYaw = nil
        Runtime.lastRenderAt = nil
        Runtime.writingCFrame = false

        if Runtime.humanoid and Runtime.humanoid.Parent
            and Runtime.savedAutoRotate ~= nil
        then
            pcall(function()
                Runtime.humanoid.AutoRotate = Runtime.savedAutoRotate
            end)
        end
        Runtime.humanoid = nil
        Runtime.savedAutoRotate = nil
    end

    local function ownAutoRotate(humanoid)
        installAutoFaceRotationGuard()

        if Runtime.humanoid ~= humanoid then
            releaseRotation()
            Runtime.humanoid = humanoid
            Runtime.savedAutoRotate = humanoid.AutoRotate
        end
        if humanoid.AutoRotate ~= false then
            humanoid.AutoRotate = false
        end
    end

    local function clearTargetLock()
        Runtime.lockedTarget = nil
        Runtime.lockUntil = 0
        Runtime.lockReason = nil
        Runtime.lockPriority = 0
        Runtime.lockAcquiredAt = 0
        Runtime.lockImpactEta = math.huge
    end

    Runtime.clearTargetLock = clearTargetLock

    local function clearDefenseHint()
        Runtime.defenseHintTarget = nil
        Runtime.defenseHintUntil = 0
        Runtime.defenseHintImpactEta = math.huge
    end

    Runtime.clearDefenseHint = clearDefenseHint

    Runtime.setDefenseHint = function(target, duration, impactEta)
        if not isAutoFaceCombatEnabled()
            or not target
            or not target.Parent
            or target == getCharacter()
            or (Menu._IsFriendlyCharacter and Menu._IsFriendlyCharacter(target))
        then
            return false
        end

        local now = os.clock()
        local eta = tonumber(impactEta) or math.huge
        local current = Runtime.defenseHintTarget
        local currentUsable = current
            and current.Parent
            and now <= (tonumber(Runtime.defenseHintUntil) or 0)

        if currentUsable
            and current ~= target
            and eta + 0.025
                >= (tonumber(Runtime.defenseHintImpactEta) or math.huge)
        then
            return false
        end

        Runtime.defenseHintTarget = target
        Runtime.defenseHintImpactEta = eta
        Runtime.defenseHintUntil = now + math.clamp(
            tonumber(duration) or 0.24,
            0.08,
            0.34
        )
        return true
    end

    local function getLockPriority(reason)
        reason = string.lower(tostring(reason or "external"))

        if string.find(reason, "parry-defense-fire", 1, true) then
            return 130
        end
        if string.find(reason, "cqc-m2-cancel", 1, true) then
            return 126
        end
        if string.find(reason, "parry-defense-prearm", 1, true)
            or string.find(reason, "parry-defense", 1, true)
        then
            return 120
        end
        if string.find(reason, "parry-punish-once", 1, true) then
            return 100
        end
        if string.find(reason, "parry-punish", 1, true)
            and string.find(reason, "impact", 1, true)
        then
            return 92
        end
        if string.find(reason, "parry-punish", 1, true) then
            return 86
        end
        if string.find(reason, "stun-chain", 1, true)
            and string.find(reason, "impact", 1, true)
        then
            return 82
        end
        if string.find(reason, "stun-chain", 1, true) then
            return 78
        end
        if string.find(reason, "local-ali-right-m2", 1, true) then
            return 80
        end
        if string.find(reason, "local-m2", 1, true) then
            return 72
        end
        if string.find(reason, "wingchun-counter", 1, true) then
            return 74
        end
        if string.find(reason, "interrupt", 1, true) then
            return 64
        end
        if string.find(reason, "autopunish", 1, true) then
            return 52
        end

        return 40
    end

    local function getLockMaxDuration(reason)
        reason = string.lower(tostring(reason or "external"))

        if string.find(reason, "parry-defense-fire", 1, true) then
            return 0.060
        end
        if string.find(reason, "cqc-m2-cancel", 1, true) then
            return 0.16
        end
        if string.find(reason, "parry-defense-prearm", 1, true) then
            return 0.24
        end
        if string.find(reason, "parry-defense", 1, true) then
            return 0.12
        end
        if string.find(reason, "parry-punish-once", 1, true) then
            return 0.38
        end
        if string.find(reason, "parry-punish", 1, true)
            and string.find(reason, "impact", 1, true)
        then
            return 0.84
        end
        if string.find(reason, "parry-punish", 1, true) then
            return 0.42
        end
        if string.find(reason, "stun-chain", 1, true) then
            return 0.30
        end
        if string.find(reason, "interrupt", 1, true) then
            return 0.36
        end
        if string.find(reason, "local-ali-right-m2", 1, true) then
            return 0.84
        end
        if string.find(reason, "local-m2", 1, true) then
            return 0.66
        end
        if string.find(reason, "wingchun-counter", 1, true) then
            return 0.46
        end

        return 0.55
    end

    local function currentLockIsUsable(now)
        local target = Runtime.lockedTarget
        if not target
            or not target.Parent
            or target == getCharacter()
            or now > (tonumber(Runtime.lockUntil) or 0)
            or (Menu._IsFriendlyCharacter and Menu._IsFriendlyCharacter(target))
        then
            return false
        end

        local humanoid = target:FindFirstChildOfClass("Humanoid")
        return (not humanoid or humanoid.Health > 0)
            and target:GetAttribute("Downed") ~= true
            and getRoot(target) ~= nil
    end

    Runtime.lockTarget = function(target, duration, reason, options)
        if not isAutoFaceCombatEnabled()
            or not target
            or not target.Parent
            or target == getCharacter()
            or (Menu._IsFriendlyCharacter and Menu._IsFriendlyCharacter(target))
        then
            return false
        end

        local now = os.clock()
        local incomingReason = reason or "external"
        local lockOptions = type(options) == "table" and options or {}
        local incomingDefenseFire =
            string.find(
                string.lower(tostring(incomingReason)),
                "parry-defense-fire",
                1,
                true
            ) ~= nil
        local requestedDuration = math.max(
            incomingDefenseFire and 0.025 or 0.10,
            tonumber(duration) or 0.50
        )
        local untilAt = now + math.min(
            requestedDuration,
            getLockMaxDuration(incomingReason)
        )
        local incomingPriority = getLockPriority(incomingReason)
        local forceReplace = lockOptions.forceReplace == true
            or incomingDefenseFire

        if Runtime.lockedTarget ~= target
            and currentLockIsUsable(now)
            and not forceReplace
            and incomingPriority <= (tonumber(Runtime.lockPriority) or 0)
        then
            local rejectKey = tostring(Runtime.lockedTarget.Name)
                .. ">"
                .. tostring(target.Name)
                .. "|"
                .. tostring(incomingReason)
            if Runtime.lastLockRejectKey ~= rejectKey
                or now - (tonumber(Runtime.lastLockRejectAt) or 0) >= 0.25
            then
                Runtime.lastLockRejectKey = rejectKey
                Runtime.lastLockRejectAt = now
                debugLog("AUTOFACE_LOCK_REJECT", {
                    locked = Runtime.lockedTarget.Name,
                    lockedReason = Runtime.lockReason or "",
                    lockedPriority = Runtime.lockPriority or 0,
                    requested = target.Name,
                    requestedReason = incomingReason,
                    requestedPriority = incomingPriority,
                    remaining = math.max(
                        0,
                        (tonumber(Runtime.lockUntil) or now) - now
                    ),
                }, true)
            end
            return false
        end

        if Runtime.lockedTarget == target then
            Runtime.lockUntil = math.max(
                tonumber(Runtime.lockUntil) or 0,
                untilAt
            )

            local currentReasonLower =
                string.lower(
                    tostring(
                        Runtime.lockReason
                        or ""
                    )
                )
            local incomingReasonLower =
                string.lower(
                    tostring(
                        incomingReason
                    )
                )
            local defenseToPunishImpact =
                string.find(
                    currentReasonLower,
                    "parry-defense",
                    1,
                    true
                ) ~= nil
                and string.find(
                    incomingReasonLower,
                    "parry-punish",
                    1,
                    true
                ) ~= nil
                and string.find(
                    incomingReasonLower,
                    "impact",
                    1,
                    true
                ) ~= nil

            if incomingPriority
                    >= (
                        tonumber(
                            Runtime.lockPriority
                        ) or 0
                    )
                or defenseToPunishImpact
            then
                Runtime.lockPriority =
                    incomingPriority
                Runtime.lockReason =
                    incomingReason
            end
        else
            Runtime.lockedTarget = target
            Runtime.lockUntil = untilAt
            Runtime.lockReason = incomingReason
            Runtime.lockPriority = incomingPriority
            Runtime.lockAcquiredAt = now
            Runtime.selectedAt = now
        end
        Runtime.lockImpactEta =
            tonumber(lockOptions.impactEta) or math.huge

        Runtime.stickyTarget = target
        Runtime.stickyUntil = math.max(
            tonumber(Runtime.stickyUntil) or 0,
            untilAt
        )
        local primaryChanged = Runtime.primaryTarget ~= target
        Runtime.primaryTarget = target
        Runtime.primaryUntil = primaryChanged
            and (untilAt + 0.30)
            or math.max(
                tonumber(Runtime.primaryUntil) or 0,
                untilAt + 0.30
            )

        local faceNow = Runtime.faceNow
        if lockOptions.snapNow ~= false
            and type(faceNow) == "function"
        then
            pcall(faceNow, target)
        end
        return true
    end

    local function targetCanBeFaced(target, root, maxDistance)
        if not target or not target.Parent then
            return false
        end
        if Menu._IsFriendlyCharacter and Menu._IsFriendlyCharacter(target) then
            return false
        end

        local humanoid = target:FindFirstChildOfClass("Humanoid")
        if humanoid and humanoid.Health <= 0 then
            return false
        end
        if target:GetAttribute("Downed") == true then
            return false
        end

        local targetRoot = getRoot(target)
        if not targetRoot then
            return false
        end

        if root then
            local distance = flat(targetRoot.Position - root.Position).Magnitude
            if distance <= 0.05
                or distance > (tonumber(maxDistance) or 40)
            then
                return false
            end
        end

        return true
    end

    local function findLocalM2FaceTarget(root, maxDistance)
        local localCharacter = getCharacter()
        if not localCharacter or not root then
            return nil
        end

        local function usable(target)
            return target
                and target ~= localCharacter
                and targetCanBeFaced(target, root, maxDistance)
        end

        for _, preferred in ipairs({
            Runtime.currentTarget,
            Runtime.lockedTarget,
            Runtime.stickyTarget,
            Runtime.primaryTarget,
        }) do
            if usable(preferred) then
                return preferred
            end
        end

        local bestTarget
        local bestScore = math.huge
        for _, player in ipairs(Players:GetPlayers()) do
            if player ~= LocalPlayer then
                local target = player.Character
                local targetRoot = getRoot(target)
                if usable(target) and targetRoot then
                    local delta = flat(targetRoot.Position - root.Position)
                    local distance = delta.Magnitude
                    local facing = flat(root.CFrame.LookVector)
                    local dot = 0
                    if distance > 0.05 and facing.Magnitude > 0.05 then
                        dot = facing.Unit:Dot(delta.Unit)
                    end

                    local score = distance - math.max(0, dot) * 1.15
                    if score < bestScore then
                        bestScore = score
                        bestTarget = target
                    end
                end
            end
        end

        return bestTarget
    end

    Runtime.lockNearestForLocalM2 = function()
        if Flags.ap_auto_face ~= true
            or not isAutoFaceCombatEnabled()
        then
            return false
        end

        local character = getCharacter()
        local root = getRoot(character)
        if not character
            or not root
            or character:GetAttribute("Equip") ~= true
        then
            return false
        end

        local style = string.lower(tostring(getStyle(character) or ""))
        local variant = nil
        if style == "ali" then
            pcall(function()
                variant = CombatStepUtils.ResolveM2VariantId("ali", character)
            end)
        end

        local target = findLocalM2FaceTarget(
            root,
            style == "ali" and 15.5 or 13.5
        )
        if not target then
            return false
        end

        task.defer(function()
            if Flags.ap_auto_face ~= true
                or not isAutoFaceCombatEnabled()
                or not target.Parent
                or not character.Parent
                or character:GetAttribute("Equip") ~= true
            then
                return
            end

            local resolvedVariant = variant
            if style == "ali" then
                pcall(function()
                    resolvedVariant = CombatStepUtils.ResolveM2VariantId(
                        "ali",
                        character
                    ) or resolvedVariant
                end)
            end

            local isAliRight = style == "ali"
                and string.lower(tostring(resolvedVariant or "")) == "right"
            local reason = isAliRight
                and "local-ali-right-m2"
                or "local-m2"
            local duration = isAliRight and 0.84 or 0.62

            Runtime.lockTarget(
                target,
                duration,
                reason,
                {
                    forceReplace = false,
                    snapNow = true,
                    impactEta = isAliRight and 0.67 or 0.53,
                }
            )

            debugLog("AUTOFACE_LOCAL_M2_LOCK", {
                target = target.Name,
                style = style,
                variant = resolvedVariant or "",
                rightAli = isAliRight,
                duration = duration,
            }, true)
        end)

        return true
    end

    local function threatOwner(threat)
        if not threat
            or threat.expired == true
            or threat.autoFaceEndedAt ~= nil
        then
            return nil
        end
        local owner = threat.owner or resolveOwner(threat)
        local localCharacter = getCharacter()
        if not owner or not owner.Parent or owner == localCharacter then
            return nil
        end
        if Menu._IsFriendlyCharacter and Menu._IsFriendlyCharacter(owner) then
            return nil
        end
        if threat.attackType ~= "M1" and threat.attackType ~= "M2" then
            return nil
        end
        return owner
    end

    local function isThreatStillActive(threat, owner, now)
        if not threat
            or not owner
            or threat.expired == true
            or threat.autoFaceEndedAt ~= nil
        then
            return false
        end

        local hitbox = threat.hitbox
        if hitbox and hitbox.Parent then
            return true
        end

        local track = threat.track
        if track ~= nil then
            local ok, playing = pcall(function()
                return track.IsPlaying
            end)

            if ok and playing == true then
                return true
            end

            local handoffUntil =
                tonumber(
                    threat.trackStopHandoffUntil
                ) or 0

            if now <= handoffUntil then
                return true
            end

            return false
        end

        if threat.source == "server_hitbox" then
            return false
        end

        if owner:GetAttribute("CombatAttacking") == true
            or owner:GetAttribute("M1") == true
            or owner:GetAttribute("M1Hold") == true
            or owner:GetAttribute("PendingM1") == true
            or owner:GetAttribute("M2") == true
            or owner:GetAttribute("PendingM2") == true
        then
            return true
        end

        local expectedContact =
            tonumber(
                threat.expectedContactAbs
            )

        if expectedContact
            and now <= expectedContact + 0.11
        then
            return true
        end

        return now - (tonumber(threat.createdAt) or now) <= 0.20
    end

    local function getThreatFacingDot(ownerRoot, root)
        local toLocal = flat(root.Position - ownerRoot.Position)
        local ownerLook = flat(ownerRoot.CFrame.LookVector)
        if toLocal.Magnitude <= 0.05 then
            return 1
        end
        if ownerLook.Magnitude <= 0.05 then
            return -1
        end
        return ownerLook.Unit:Dot(toLocal.Unit)
    end

    local function getThreatEta(threat, now)
        local hitTL = tonumber(threat and threat.hitTL)
        if not hitTL then
            return 0.35
        end

        local trackTime
        local track = threat and threat.track
        if track ~= nil then
            pcall(function()
                trackTime = tonumber(track.TimePosition)
            end)
        end

        if trackTime == nil then
            trackTime = math.max(
                0,
                now - (tonumber(threat.createdAt) or now)
            )
        end

        local timelineSpeed = math.max(
            0.05,
            tonumber(threat.combatTimelineSpeed)
                or tonumber(threat.ownerAttackSpeed)
                or tonumber(threat.speedMultiplier)
                or 1
        )

        return math.max(0, (hitTL - trackTime) / timelineSpeed)
    end

    local function isServerHitboxTouchingLocal(threat, root)
        local hitbox = threat and threat.hitbox
        if not hitbox
            or not hitbox.Parent
            or not hitbox:IsA("BasePart")
        then
            return false
        end

        local localPoint = hitbox.CFrame:PointToObjectSpace(root.Position)
        local rootRadius = math.max(root.Size.X, root.Size.Z) * 0.5
        local rootHalfY = root.Size.Y * 0.5
        local cushion = 0.70

        return math.abs(localPoint.X)
                <= hitbox.Size.X * 0.5 + rootRadius + cushion
            and math.abs(localPoint.Z)
                <= hitbox.Size.Z * 0.5 + rootRadius + cushion
            and math.abs(localPoint.Y)
                <= hitbox.Size.Y * 0.5 + rootHalfY + cushion
    end

    local function hasLiveServerHitbox(threat)
        local hitbox = threat and threat.hitbox
        return hitbox ~= nil
            and hitbox.Parent ~= nil
            and hitbox:IsA("BasePart")
    end

    Runtime.getThreatHitboxProfile =
        function(threat)
            if not threat then
                return nil, ""
            end

            local style =
                string.lower(
                    tostring(
                        threat.style
                        or ""
                    )
                )
            local attack =
                tostring(
                    threat.attackType
                    or ""
                )
            local combo =
                math.floor(
                    tonumber(
                        threat.combo
                    ) or 0
                )
            local variant =
                string.lower(
                    tostring(
                        threat.variant
                        or ""
                    )
                )

            local exactKey =
                style
                .. "|"
                .. attack
                .. "|"
                .. tostring(combo)
                .. "|"
                .. variant

            local genericKey =
                style
                .. "|"
                .. attack
                .. "|*"

            local profile =
                Menu._APHitboxProfiles[
                    exactKey
                ]
                or Menu._APHitboxProfiles[
                    genericKey
                ]

            if style == "kickboxing"
                and attack == "M2"
            then
                return nil,
                    "kickboxing|M2|swept"
            end

            return profile,
                profile
                    and (
                        profile.key
                        or exactKey
                    )
                    or ""
        end

    Runtime.projectThreatHitbox =
        function(
            threat,
            ownerRoot,
            root,
            now,
            eta,
            armThreshold
        )
            if not threat
                or not ownerRoot
                or not ownerRoot.Parent
                or not root
                or not root.Parent
            then
                return false, {
                    model = "missing-root",
                }
            end

            local actual =
                isServerHitboxTouchingLocal(
                    threat,
                    root
                )

            if actual then
                return true, {
                    model =
                        "live-server-hitbox",
                    physical = true,
                    eta = 0,
                    lateral = 0,
                    depth = 0,
                    vertical = 0,
                }
            end

            eta =
                math.clamp(
                    tonumber(eta)
                        or 0.35,
                    0,
                    0.46
                )

            if eta > 0.43 then
                return false, {
                    model =
                        "too-early",
                    eta = eta,
                }
            end

            local profile, profileKey =
                Runtime.getThreatHitboxProfile(
                    threat
                )

            local ownerVelocity =
                ownerRoot.AssemblyLinearVelocity
            local localVelocity =
                root.AssemblyLinearVelocity

            local projectedOwnerPosition =
                ownerRoot.Position
                + ownerVelocity * eta
            local projectedLocalPosition =
                root.Position
                + localVelocity * eta

            local ownerRotation =
                ownerRoot.CFrame
                - ownerRoot.Position

            local projectedOwnerCFrame =
                CFrame.new(
                    projectedOwnerPosition
                )
                * ownerRotation

            if threat.apCurrentRedirectActive
                    == true
            then
                local aim =
                    Vector3.new(
                        projectedLocalPosition.X,
                        projectedOwnerPosition.Y,
                        projectedLocalPosition.Z
                    )
                    - projectedOwnerPosition

                if aim.Magnitude > 0.05 then
                    projectedOwnerCFrame =
                        CFrame.lookAt(
                            projectedOwnerPosition,
                            projectedOwnerPosition
                                + aim.Unit
                        )
                end
            end

            local predictedCFrame
            local predictedSize
            local model

            if type(profile) == "table"
                and typeof(
                    profile.relativeCFrame
                ) == "CFrame"
                and typeof(
                    profile.size
                ) == "Vector3"
            then
                predictedCFrame =
                    projectedOwnerCFrame
                    * profile.relativeCFrame
                predictedSize =
                    profile.size
                model =
                    "learned-server-hitbox"
            else
                local threshold =
                    math.clamp(
                        tonumber(
                            armThreshold
                        )
                            or (
                                threat.attackType
                                    == "M2"
                                and 10.5
                                or 10
                            ),
                        6,
                        15
                    )

                local forwardOffset =
                    math.clamp(
                        threshold * 0.36,
                        2.25,
                        4.85
                    )

                local kickboxingM2 =
                    threat.style == "kickboxing"
                    and threat.attackType == "M2"

                predictedSize =
                    kickboxingM2
                    and Vector3.new(
                        4.05,
                        7.15,
                        4.05
                    )
                    or (
                        threat.attackType
                                == "M2"
                            and Vector3.new(
                                4.35,
                                6.65,
                                4.35
                            )
                            or Vector3.new(
                                4.05,
                                4.20,
                                4.05
                            )
                    )

                if kickboxingM2 then
                    forwardOffset =
                        math.clamp(
                            forwardOffset + 0.45,
                            2.70,
                            5.20
                        )
                end

                predictedCFrame =
                    projectedOwnerCFrame
                    * CFrame.new(
                        0,
                        0,
                        -forwardOffset
                    )
                model =
                    kickboxingM2
                    and "kickboxing-m2-sweep"
                    or "estimated-hitbox"
            end

            local point =
                predictedCFrame
                    :PointToObjectSpace(
                        projectedLocalPosition
                    )

            local rootRadius =
                math.max(
                    root.Size.X,
                    root.Size.Z
                ) * 0.5
            local rootHalfY =
                root.Size.Y * 0.5

            local localCharacter =
                getCharacter()
            local bodyHalfY =
                rootHalfY

            if localCharacter
                and localCharacter.Parent
            then
                pcall(function()
                    local _, bodySize =
                        localCharacter:GetBoundingBox()
                    bodyHalfY =
                        math.clamp(
                            bodySize.Y * 0.42,
                            rootHalfY,
                            3.55
                        )
                end)
            end

            local cushion =
                model
                    == "learned-server-hitbox"
                and 0.82
                or 1.02

            local halfX =
                predictedSize.X * 0.5
                + rootRadius
                + cushion
            local halfY =
                predictedSize.Y * 0.5
                + bodyHalfY
                + cushion
            local halfZ =
                predictedSize.Z * 0.5
                + rootRadius
                + cushion

            local horizontalHit =
                math.abs(point.X)
                    <= halfX
                and math.abs(point.Z)
                    <= halfZ
            local verticalGap =
                math.abs(point.Y)
                - halfY

            local hit =
                horizontalHit
                and verticalGap <= 0

            local kickboxingM2Sweep =
                threat.style == "kickboxing"
                and threat.attackType == "M2"

            if not hit
                and kickboxingM2Sweep
                and horizontalHit
            then
                local toLocal =
                    flat(
                        projectedLocalPosition
                        - projectedOwnerPosition
                    )
                local attackerFacingDot = -1

                if toLocal.Magnitude > 0.05 then
                    local attackerLook =
                        flat(
                            projectedOwnerCFrame.LookVector
                        )
                    if attackerLook.Magnitude > 0.05 then
                        attackerFacingDot =
                            attackerLook.Unit:Dot(
                                toLocal.Unit
                            )
                    end
                end

                local committed =
                    threat.apCurrentArmCommitted == true
                    or threat.apCurrentApproachReady == true
                    or threat.serverConfirmed == true

                if committed
                    and verticalGap <= 3.65
                    and attackerFacingDot >= 0.05
                    and toLocal.Magnitude
                        <= armThreshold + 1.35
                then
                    hit = true
                    model =
                        "kickboxing-m2-swept-hitbox"
                end
            end

            return hit, {
                model = model,
                profileKey =
                    profileKey,
                kickboxingM2Sweep =
                    kickboxingM2Sweep == true,
                profileSamples =
                    profile
                    and (
                        tonumber(
                            profile.samples
                        ) or 0
                    )
                    or 0,
                physical = false,
                eta = eta,
                lateral =
                    math.abs(point.X)
                    - halfX,
                vertical =
                    math.abs(point.Y)
                    - halfY,
                depth =
                    math.abs(point.Z)
                    - halfZ,
                predictedSize =
                    predictedSize,
            }
        end

    Runtime.isThreatProjectedToHit =
        function(threat)
            if not threat
                or threat.expired == true
            then
                return false, {
                    model = "expired",
                }
            end

            local owner =
                threatOwner(
                    threat
                )
            local character =
                getCharacter()
            local root =
                getRoot(
                    character
                )
            local ownerRoot =
                getRoot(
                    owner
                )

            if not owner
                or not root
                or not ownerRoot
            then
                return false, {
                    model = "missing-root",
                }
            end

            local now =
                os.clock()
            local eta =
                getThreatEta(
                    threat,
                    now
                )
            local armThreshold =
                math.clamp(
                    tonumber(
                        threat.apCurrentArmThreshold
                    )
                        or (
                            threat.attackType
                                == "M2"
                            and 10.5
                            or 10
                        ),
                    6,
                    15
                )

            return Runtime.projectThreatHitbox(
                threat,
                ownerRoot,
                root,
                now,
                eta,
                armThreshold
            )
        end

    Runtime.isAPCommittedThreatPath =
        function(threat, owner, root, now)
            if not threat
                or threat.expired == true
                or not owner
                or not owner.Parent
                or not root
                or not root.Parent
            then
                return false, nil
            end

            if threat.attackType ~= "M1"
                and threat.attackType ~= "M2"
            then
                return false, nil
            end

            local ownerRoot =
                getRoot(owner)

            if not ownerRoot then
                return false, nil
            end

            now =
                tonumber(now)
                or os.clock()

            local eta =
                getThreatEta(
                    threat,
                    now
                )

            if eta > 0.46 then
                return false, nil
            end

            local committed =
                threat.apCurrentArmCommitted
                    == true
                or threat.apCurrentApproachReady
                    == true
                or threat.apCurrentRedirectActive
                    == true
                or threat.serverConfirmed
                    == true

            if not committed then
                return false, nil
            end

            local armThreshold =
                math.clamp(
                    tonumber(
                        threat.apCurrentArmThreshold
                    )
                        or (
                            threat.attackType
                                == "M2"
                            and 10.5
                            or 10
                        ),
                    6,
                    15
                )

            local currentDistance =
                flat(
                    ownerRoot.Position
                    - root.Position
                ).Magnitude

            local projectedDistance =
                tonumber(
                    threat.apCurrentProjectedContactDistance
                )

            if projectedDistance == nil then
                local relativeVelocity =
                    flat(
                        ownerRoot.AssemblyLinearVelocity
                        - root.AssemblyLinearVelocity
                    )
                local toOwner =
                    flat(
                        ownerRoot.Position
                        - root.Position
                    )
                local closing = 0

                if toOwner.Magnitude > 0.05 then
                    closing =
                        -relativeVelocity:Dot(
                            toOwner.Unit
                        )
                end

                local horizon =
                    math.clamp(
                        eta + 0.06,
                        0.08,
                        0.32
                    )

                projectedDistance =
                    math.max(
                        0,
                        currentDistance
                        - math.max(
                            0,
                            closing
                        ) * horizon
                    )
            end

            local verticalDifference =
                math.abs(
                    ownerRoot.Position.Y
                    - root.Position.Y
                )
            local verticalAllowance =
                threat.attackType == "M2"
                    and 6.25
                    or 4.65

            local distanceAllowance =
                armThreshold
                + (
                    threat.attackType == "M2"
                    and 1.05
                    or 0.80
                )

            local reachable =
                projectedDistance
                    <= distanceAllowance
                and verticalDifference
                    <= verticalAllowance

            if not reachable then
                return false, {
                    model =
                        "ap-committed-path",
                    eta = eta,
                    distance =
                        currentDistance,
                    projectedDistance =
                        projectedDistance,
                    armThreshold =
                        armThreshold,
                    verticalDifference =
                        verticalDifference,
                    reachable =
                        false,
                }
            end

            return true, {
                model =
                    "ap-committed-path",
                eta = eta,
                distance =
                    currentDistance,
                projectedDistance =
                    projectedDistance,
                armThreshold =
                    armThreshold,
                verticalDifference =
                    verticalDifference,
                reachable =
                    true,
            }
        end

    Runtime.isThreatPathVerified =
        function(threat)
            if not threat then
                return false, nil
            end

            local owner =
                threatOwner(threat)
            local character =
                getCharacter()
            local root =
                getRoot(character)

            if not owner
                or not root
            then
                return false, nil
            end

            if hasLiveServerHitbox(threat)
                and not isServerHitboxTouchingLocal(
                    threat,
                    root
                )
            then
                return false, {
                    model = "live-server-hitbox-miss",
                    authoritative = true,
                    physical = false,
                }
            end

            local hitboxHit =
                false
            local hitboxMeta =
                nil

            if type(
                Runtime.isThreatProjectedToHit
            ) == "function"
            then
                local ok,
                    result,
                    meta =
                        pcall(
                            Runtime.isThreatProjectedToHit,
                            threat
                        )

                if ok then
                    hitboxHit =
                        result == true
                    hitboxMeta =
                        meta
                end
            end

            if hitboxHit then
                return true,
                    hitboxMeta
            end

            local hitboxSamples =
                hitboxMeta
                and (
                    tonumber(
                        hitboxMeta.profileSamples
                    ) or 0
                )
                or 0
            local hitboxModel =
                hitboxMeta
                and tostring(
                    hitboxMeta.model or ""
                )
                or ""

            local apHit,
                apMeta =
                    Runtime.isAPCommittedThreatPath(
                        threat,
                        owner,
                        root,
                        os.clock()
                    )

            if apHit then
                local ownerRoot =
                    getRoot(owner)
                local distance =
                    apMeta
                    and tonumber(apMeta.distance)
                    or (
                        ownerRoot
                        and flat(
                            ownerRoot.Position
                            - root.Position
                        ).Magnitude
                        or math.huge
                    )
                local projectedDistance =
                    apMeta
                    and tonumber(
                        apMeta.projectedDistance
                    )
                    or distance
                local armThreshold =
                    math.clamp(
                        tonumber(
                            threat.apCurrentArmThreshold
                        ) or (
                            threat.attackType == "M2"
                            and 10.5
                            or 10.0
                        ),
                        6,
                        15
                    )
                local facingDot =
                    ownerRoot
                    and getThreatFacingDot(
                        ownerRoot,
                        root
                    )
                    or -1
                local redirectActive =
                    threat.apCurrentRedirectActive
                        == true

                local minimumFacing
                if distance <= 4.5 then
                    minimumFacing = -0.82
                elseif distance <= 7.0 then
                    minimumFacing = -0.38
                elseif distance <= 9.0 then
                    minimumFacing = -0.12
                else
                    minimumFacing = 0.08
                end

                local currentInLane =
                    distance
                        <= armThreshold
                            + AP_ONLY_CURRENT_RANGE_SLACK
                local projectedInLane =
                    projectedDistance
                        <= armThreshold
                            + AP_ONLY_PROJECTED_RANGE_SLACK
                local aimedEnough =
                    redirectActive
                    or facingDot >= minimumFacing

                local currentCap =
                    threat.attackType == "M2"
                    and AUTOFACE_AP_ONLY_M2_CURRENT_CAP
                    or AUTOFACE_AP_ONLY_M1_CURRENT_CAP

                local matureLearnedMiss =
                    isTrustedAutoFaceLearnedMiss(
                        hitboxModel,
                        hitboxSamples,
                        distance
                    )

                if distance > currentCap
                    or matureLearnedMiss
                    or not currentInLane
                    or not projectedInLane
                    or not aimedEnough
                then
                    return false, {
                        model = "ap-path-lane-reject",
                        distance = distance,
                        projectedDistance =
                            projectedDistance,
                        armThreshold =
                            armThreshold,
                        facingDot = facingDot,
                        minimumFacing =
                            minimumFacing,
                    }
                end

                return true,
                    apMeta
            end

            return false,
                hitboxMeta
                or apMeta
        end

    local function getThreatEvidence(threat, owner, root, now)
        if not threat
            or threat.expired == true
            or threat.autoFaceEndedAt ~= nil
            or threat.serverHitboxEndedAt ~= nil
        then
            return nil
        end

        if threat.counterStance == true
            and threat.serverConfirmed ~= true
        then
            return nil
        end

        if threat.fired == true then
            local firedAt =
                tonumber(
                    threat.firedAt
                ) or now
            local expectedContact =
                tonumber(
                    threat.expectedContactAbs
                )
            local keepUntil =
                firedAt + 0.14

            if expectedContact then
                keepUntil =
                    math.max(
                        keepUntil,
                        expectedContact
                            + 0.10
                    )
            end

            if now > keepUntil then
                return nil
            end
        end

        local ownerRoot = getRoot(owner)
        if not ownerRoot then
            return nil
        end

        local toOwner = flat(ownerRoot.Position - root.Position)
        local distance = toOwner.Magnitude
        local aliRightM2 = threat.attackType == "M2"
            and string.lower(tostring(threat.style or "")) == "ali"
            and string.lower(tostring(threat.variant or "")) == "right"
        local acquireRange = Runtime.primaryTarget == owner
            and PRIMARY_ACQUIRE_RANGE
            or PRIMARY_ACQUIRE_RANGE
        if aliRightM2 then
            acquireRange += 1.0
        end
        if distance <= 0.05 or distance > acquireRange then
            return nil
        end

        local eta = getThreatEta(threat, now)
        local facingDot = getThreatFacingDot(ownerRoot, root)
        local relativeVelocity = flat(
            ownerRoot.AssemblyLinearVelocity
                - root.AssemblyLinearVelocity
        )
        local closing = 0
        if distance > 0.05 then
            closing = -relativeVelocity:Dot(toOwner.Unit)
        end

        local serverPhysical =
            isServerHitboxTouchingLocal(
                threat,
                root
            )
        local liveServerHitbox =
            hasLiveServerHitbox(
                threat
            )

        if serverPhysical then
            threat.autoFaceLastPhysicalAt = now
            threat.autoFaceLastPhysicalHitbox =
                threat.hitbox
        else
            local lastPhysicalAt =
                tonumber(
                    threat.autoFaceLastPhysicalAt
                ) or 0
            local sameHitbox =
                threat.autoFaceLastPhysicalHitbox
                    == threat.hitbox

            if liveServerHitbox
                and sameHitbox
                and now - lastPhysicalAt
                    <= AUTOFACE_PHYSICAL_HIT_GRACE
                and distance
                    <= AUTOFACE_PHYSICAL_GRACE_MAX_OWNER_DISTANCE
            then
                serverPhysical = true
            end
        end

        local liveMissUntil =
            tonumber(
                threat.autoFaceLiveMissUntil
            ) or 0

        if liveMissUntil > now
            and not serverPhysical
        then
            local missHitbox =
                threat.autoFaceLiveMissHitbox
            local currentHitbox =
                threat.hitbox

            -- A genuinely new hitbox instance can represent a later multi-hit
            -- pulse, so allow that new pulse to be evaluated normally.
            if currentHitbox
                and currentHitbox.Parent
                and missHitbox
                and currentHitbox ~= missHitbox
            then
                threat.autoFaceLiveMissUntil = 0
                threat.autoFaceLiveMissHitbox = nil
                threat.autoFaceLastPhysicalAt = 0
                threat.autoFaceLastPhysicalHitbox = nil
            else
                return nil
            end
        end

        if liveServerHitbox
            and not serverPhysical
        then
            local expectedContact =
                tonumber(
                    threat.expectedContactAbs
                )
            local missUntil =
                now
                + AUTOFACE_LIVE_MISS_QUARANTINE

            if expectedContact then
                missUntil =
                    math.max(
                        missUntil,
                        expectedContact + 0.10
                    )
            end

            threat.autoFaceLiveMissUntil =
                math.max(
                    tonumber(
                        threat.autoFaceLiveMissUntil
                    ) or 0,
                    missUntil
                )
            threat.autoFaceLiveMissHitbox =
                threat.hitbox

            local lastMissLogAt =
                tonumber(
                    threat.autoFaceLiveMissLogAt
                ) or 0

            if now - lastMissLogAt >= 0.08 then
                threat.autoFaceLiveMissLogAt = now

                local hitbox =
                    threat.hitbox
                local hitboxDistance =
                    hitbox
                    and hitbox.Parent
                    and (
                        hitbox.Position
                        - root.Position
                    ).Magnitude
                    or ""

                debugLog(
                    "AUTOFACE_LIVE_HITBOX_MISS",
                    {
                        owner =
                            threat.ownerName
                            or owner.Name,
                        attack =
                            threat.attackType
                            or "",
                        style =
                            threat.style
                            or "",
                        source =
                            threat.source
                            or "",
                        hitboxDistance =
                            hitboxDistance,
                    },
                    true
                )
            end

            return nil
        end

        if threat.attackType ~= "M1"
            and threat.attackType ~= "M2"
        then
            return nil
        end

        local trackPlaying =
            false

        if threat.track ~= nil then
            pcall(function()
                trackPlaying =
                    threat.track.IsPlaying
                        == true
            end)
        end

        local stoppedTrackHandoffActive =
            tonumber(
                threat.trackStopHandoffUntil
            ) ~= nil
            and now <= (
                tonumber(
                    threat.trackStopHandoffUntil
                ) or 0
            )

        local ownerAttackActive =
            trackPlaying
            or stoppedTrackHandoffActive
            or (
                threat.attackType == "M1"
                and (
                    owner:GetAttribute("M1") == true
                    or owner:GetAttribute("M1Hold") == true
                    or owner:GetAttribute("PendingM1") == true
                )
            )
            or (
                threat.attackType == "M2"
                and (
                    owner:GetAttribute("M2") == true
                    or owner:GetAttribute("PendingM2") == true
                )
            )

        if not ownerAttackActive
            and threat.serverConfirmed ~= true
            and not serverPhysical
        then
            return nil
        end

        local armThreshold = math.clamp(
            tonumber(threat.apCurrentArmThreshold)
                or (threat.attackType == "M2" and 10.5 or 10.0),
            6,
            15
        )
        local projectionHorizon = math.clamp(eta + 0.08, 0.08, 0.26)
        local projectedDistance = math.max(
            0,
            distance - math.max(0, closing) * projectionHorizon
        )
        local aimedThreshold
        if distance <= 4.25 then
            aimedThreshold = -0.20
        elseif distance <= 8 then
            aimedThreshold = 0.12
        else
            aimedThreshold = 0.32
        end
        if aliRightM2 then
            aimedThreshold = math.max(-0.32, aimedThreshold - 0.24)
        end

        local redirectActive =
            threat.apCurrentRedirectActive
                == true
        local aimedAtLocal =
            facingDot
                >= aimedThreshold
            or redirectActive
        local withinStrikePath =
            projectedDistance
                <= armThreshold
                    + 1.25

        local hitboxWillHit,
            hitboxPrediction =
                Runtime.projectThreatHitbox(
                    threat,
                    ownerRoot,
                    root,
                    now,
                    eta,
                    armThreshold
                )

        local apPathVerified,
            apPathMeta =
                Runtime.isAPCommittedThreatPath(
                    threat,
                    owner,
                    root,
                    now
                )

        if apPathVerified == true
            and hitboxWillHit ~= true
            and not serverPhysical
        then
            local apDistance =
                apPathMeta
                and tonumber(apPathMeta.distance)
                or distance
            local apProjectedDistance =
                apPathMeta
                and tonumber(
                    apPathMeta.projectedDistance
                )
                or projectedDistance

            local minimumFacing
            if apDistance <= 4.5 then
                minimumFacing = -0.82
            elseif apDistance <= 7.0 then
                minimumFacing = -0.38
            elseif apDistance <= 9.0 then
                minimumFacing = -0.12
            else
                minimumFacing = 0.08
            end

            local currentInLane =
                apDistance
                    <= armThreshold
                        + AP_ONLY_CURRENT_RANGE_SLACK
            local projectedInLane =
                apProjectedDistance
                    <= armThreshold
                        + AP_ONLY_PROJECTED_RANGE_SLACK
            local aimedEnough =
                redirectActive
                or facingDot >= minimumFacing

            local currentCap =
                threat.attackType == "M2"
                and AUTOFACE_AP_ONLY_M2_CURRENT_CAP
                or AUTOFACE_AP_ONLY_M1_CURRENT_CAP

            local hitboxSamples =
                hitboxPrediction
                and (
                    tonumber(
                        hitboxPrediction.profileSamples
                    ) or 0
                )
                or 0
            local matureLearnedMiss =
                hitboxPrediction
                and isTrustedAutoFaceLearnedMiss(
                    hitboxPrediction.model,
                    hitboxSamples,
                    apDistance
                )

            if apDistance > currentCap
                or matureLearnedMiss
                or not currentInLane
                or not projectedInLane
                or not aimedEnough
            then
                apPathVerified = false
            end
        end

        if not serverPhysical
            and hitboxWillHit ~= true
            and apPathVerified ~= true
        then
            return nil
        end

        if hitboxWillHit == true
            and threat.style == "kickboxing"
            and threat.attackType == "M2"
        then
            local lastLogAt =
                tonumber(
                    threat.apKickboxingM2FaceLogAt
                ) or 0

            if now - lastLogAt >= 0.08 then
                threat.apKickboxingM2FaceLogAt = now
                debugLog(
                    "AUTOFACE_KICKBOXING_M2_SWEEP",
                    {
                        owner = threat.ownerName or owner.Name,
                        distance = distance,
                        eta = eta,
                        model = hitboxPrediction and hitboxPrediction.model or "",
                        lateral = hitboxPrediction and hitboxPrediction.lateral or "",
                        vertical = hitboxPrediction and hitboxPrediction.vertical or "",
                        depth = hitboxPrediction and hitboxPrediction.depth or "",
                        profile = hitboxPrediction and hitboxPrediction.profileKey or "",
                    },
                    true
                )
            end
        end

        local armReady =
            apPathVerified == true
            or threat.apCurrentArmCommitted == true
            or threat.apCurrentApproachReady == true
            or redirectActive
            or (
                aliRightM2
                and aimedAtLocal
                and withinStrikePath
                and eta <= 0.46
            )
        local contactTravelTime = 0
        if distance > armThreshold and closing > 0.5 then
            contactTravelTime = (distance - armThreshold) / closing
        end
        local impactEta = serverPhysical
            and 0
            or math.max(eta, contactTravelTime)
        local dangerTier =
            serverPhysical
                and 5
            or (
                hitboxWillHit == true
                and impactEta
                    <= CROWD_EMERGENCY_ETA
                and 4
            )
            or (
                hitboxWillHit == true
                and 3
            )
            or (
                apPathVerified == true
                and 3
            )
            or 1
        local score =
            projectedDistance * 0.52
            + distance * 0.10
            + math.min(impactEta, 0.75) * 8.5
            + (1 - math.clamp(facingDot, -1, 1)) * 0.90

        if threat.attackType == "M2" then
            score -= 0.18
        end
        if aliRightM2 then
            score -= 0.42
        end
        if armReady then
            score -= 0.75
        end
        if threat.serverConfirmed == true then
            score -= 0.40
        end
        if serverPhysical then
            score -= 5.0
        end

        return {
            target = owner,
            threatRef = threat,
            attack = threat.attackType,
            style = threat.style or "",
            variant = threat.variant or "",
            aliRightM2 = aliRightM2,
            source = threat.source or "",
            reason =
                serverPhysical
                    and "physical-hitbox"
                or (
                    hitboxWillHit == true
                    and hitboxPrediction
                    and hitboxPrediction.model
                )
                or (
                    apPathVerified == true
                    and "ap-committed-path"
                )
                or "predicted-hitbox",
            distance = distance,
            projectedDistance = projectedDistance,
            armThreshold = armThreshold,
            facingDot = facingDot,
            closing = closing,
            eta = eta,
            impactEta = impactEta,
            score = score,
            serverPhysical = serverPhysical,
            hitboxWillHit =
                hitboxWillHit == true,
            apPathVerified =
                apPathVerified == true,
            apPathProjectedDistance =
                apPathMeta
                and apPathMeta.projectedDistance
                or "",
            apPathVerticalDifference =
                apPathMeta
                and apPathMeta.verticalDifference
                or "",
            hitboxModel =
                hitboxPrediction
                and hitboxPrediction.model
                or "",
            hitboxProfileKey =
                hitboxPrediction
                and hitboxPrediction.profileKey
                or "",
            hitboxProfileSamples =
                hitboxPrediction
                and hitboxPrediction.profileSamples
                or 0,
            hitboxLateral =
                hitboxPrediction
                and hitboxPrediction.lateral
                or "",
            hitboxDepth =
                hitboxPrediction
                and hitboxPrediction.depth
                or "",
            hitboxVertical =
                hitboxPrediction
                and hitboxPrediction.vertical
                or "",
            armReady = armReady,
            dangerTier = dangerTier,
        }
    end

    local function evidenceOutranks(candidate, current)
        if not candidate then
            return false
        end
        if not current then
            return true
        end

        if candidate.dangerTier ~= current.dangerTier then
            return candidate.dangerTier > current.dangerTier
        end

        local candidateEta = tonumber(candidate.impactEta) or math.huge
        local currentEta = tonumber(current.impactEta) or math.huge
        if math.abs(candidateEta - currentEta) >= 0.022 then
            return candidateEta < currentEta
        end

        if math.abs(candidate.score - current.score) >= 0.16 then
            return candidate.score < current.score
        end

        return candidate.distance < current.distance
    end

    local function isPlausibleCrowdEmergency(meta)
        if not meta then
            return false
        end
        if meta.serverPhysical == true
            or meta.hitboxWillHit == true
            or meta.apPathVerified == true
        then
            return true
        end

        local distance = tonumber(meta.distance) or math.huge
        local projectedDistance = tonumber(meta.projectedDistance) or distance
        local armThreshold = tonumber(meta.armThreshold) or 10
        local closing = tonumber(meta.closing) or 0
        local pointBlank = distance <= 4.50
        local pathCommitted = meta.armReady == true
            or (tonumber(meta.dangerTier) or 0) >= 3
        local canActuallyReach = projectedDistance <= armThreshold + 0.40
        local movementPlausible = pointBlank or closing >= 1.25

        return pathCommitted
            and canActuallyReach
            and movementPlausible
    end

    local function hasLiveIncomingThreat(target, root, now)
        if not target or not target.Parent then
            return false
        end

        local targetRoot = getRoot(target)
        if not targetRoot then
            return false
        end

        if flat(targetRoot.Position - root.Position).Magnitude
            > PRIMARY_ACQUIRE_RANGE + 1.0
        then
            return false
        end

        local function live(threat)
            if threatOwner(threat) ~= target
                or (threat.attackType ~= "M1" and threat.attackType ~= "M2")
                or not isThreatStillActive(threat, target, now)
            then
                return false
            end

            return getThreatEvidence(threat, target, root, now) ~= nil
        end

        for _, threat in pairs(animationThreats) do
            if live(threat) then
                return true
            end
        end

        for _, threat in pairs(serverFallbackThreats) do
            if live(threat) then
                return true
            end
        end

        return false
    end

    local function localAttackAimActive(
        target,
        reason,
        now
    )
        local character =
            getCharacter()

        if character
            and character.Parent
            and (
                character:GetAttribute("M1")
                    == true
                or character:GetAttribute(
                    "PendingM1"
                ) == true
                or character:GetAttribute("M2")
                    == true
                or character:GetAttribute(
                    "PendingM2"
                ) == true
            )
        then
            return true
        end

        reason =
            string.lower(
                tostring(
                    reason
                    or ""
                )
            )

        if string.find(
                reason,
                "punish",
                1,
                true
            )
            or string.find(
                reason,
                "autopunish",
                1,
                true
            )
            or string.find(
                reason,
                "stun-chain",
                1,
                true
            )
        then
            local runtime =
                Menu
                and Menu
                    ._AutoPunishRuntime

            if runtime
                and type(
                    runtime
                        .isImpactFaceHoldActive
                ) == "function"
            then
                local ok,
                    active =
                        pcall(
                            runtime
                                .isImpactFaceHoldActive,
                            target,
                            now
                        )

                if ok
                    and active == true
                then
                    return true
                end
            end
        end

        return false
    end

    local function chooseTarget(root, now)
        if Runtime.lockedTarget then
            local reason =
                string.lower(tostring(Runtime.lockReason or "external"))
            local localAim =
                string.find(reason, "local-", 1, true) ~= nil
                or string.find(reason, "parry-punish", 1, true) ~= nil
                or string.find(reason, "stun-chain", 1, true) ~= nil
                or string.find(reason, "wingchun-counter", 1, true) ~= nil
            local lockJustified =
                localAim
                    and localAttackAimActive(
                        Runtime.lockedTarget,
                        reason,
                        now
                    )
                or hasLiveIncomingThreat(
                    Runtime.lockedTarget,
                    root,
                    now
                )

            if lockJustified
                and now <= (tonumber(Runtime.lockUntil) or 0)
                and targetCanBeFaced(
                    Runtime.lockedTarget,
                    root,
                    PRIMARY_ACQUIRE_RANGE + 1.0
                )
            then
                local targetRoot = getRoot(Runtime.lockedTarget)
                local distance = targetRoot
                    and flat(targetRoot.Position - root.Position).Magnitude
                    or math.huge
                local facingDot = targetRoot
                    and getThreatFacingDot(root, targetRoot)
                    or -1
                Runtime.activeCandidateCount = 1
                return Runtime.lockedTarget, {
                    mode = "lock",
                    reason = Runtime.lockReason or "external",
                    selection = "authoritative-lock",
                    candidates = 1,
                    primary = Runtime.lockedTarget.Name,
                    distance = distance,
                    facingDot = facingDot,
                    eta = 0,
                    impactEta = 0,
                    dangerTier = 5,
                    score = -math.huge,
                }
            end
            clearTargetLock()
        end

        local candidates = {}

        local function consider(threat)
            local owner = threatOwner(threat)
            if not owner or not isThreatStillActive(threat, owner, now) then
                return
            end
            local evidence = getThreatEvidence(threat, owner, root, now)
            if evidence then
                local previous = candidates[owner]
                if evidenceOutranks(evidence, previous) then
                    candidates[owner] = evidence
                end
            end
        end

        for _, threat in pairs(animationThreats) do
            consider(threat)
        end
        for _, threat in pairs(serverFallbackThreats) do
            consider(threat)
        end

        local candidateCount = 0
        local bestTarget
        local bestMeta
        for owner, evidence in pairs(candidates) do
            candidateCount += 1
            if evidenceOutranks(evidence, bestMeta) then
                bestTarget = owner
                bestMeta = evidence
            end
        end
        Runtime.activeCandidateCount = candidateCount

        if Runtime.defenseHintTarget
            and (
                now > (tonumber(Runtime.defenseHintUntil) or 0)
                or not Runtime.defenseHintTarget.Parent
                or not targetCanBeFaced(
                    Runtime.defenseHintTarget,
                    root,
                    PRIMARY_ACQUIRE_RANGE + 1.0
                )
            )
        then
            clearDefenseHint()
        end

        local defenseHintMeta = Runtime.defenseHintTarget
            and candidates[Runtime.defenseHintTarget]
            or nil

        if Runtime.primaryTarget
            and (
                not Runtime.primaryTarget.Parent
                or not targetCanBeFaced(
                    Runtime.primaryTarget,
                    root,
                    PRIMARY_ACQUIRE_RANGE + 1.0
                )
            )
        then
            Runtime.primaryTarget = nil
            Runtime.primaryUntil = 0
        end

        local primaryMeta = Runtime.primaryTarget
            and candidates[Runtime.primaryTarget]
            or nil

        if primaryMeta then
            Runtime.primaryUntil = now + PRIMARY_MEMORY_SECONDS
        elseif Runtime.primaryTarget
            and now > (tonumber(Runtime.primaryUntil) or 0)
        then
            Runtime.primaryTarget = nil
            Runtime.primaryUntil = 0
        end

        if not Runtime.primaryTarget and bestTarget then
            Runtime.primaryTarget = bestTarget
            Runtime.primaryUntil = now + PRIMARY_MEMORY_SECONDS
            primaryMeta = bestMeta
        end

        local selectedTarget = bestTarget
        local selectedMeta = bestMeta
        local selection = "best-threat"

        if primaryMeta then
            selectedTarget = Runtime.primaryTarget
            selectedMeta = primaryMeta
            selection = candidateCount > 1
                and "crowd-primary"
                or "primary"

            if bestTarget and bestTarget ~= Runtime.primaryTarget then
                local bestImpact = tonumber(bestMeta.impactEta) or math.huge
                local primaryImpact = tonumber(primaryMeta.impactEta) or math.huge
                local physicalEmergency = bestMeta.serverPhysical == true
                    and primaryMeta.serverPhysical ~= true
                local plausibleEmergency = isPlausibleCrowdEmergency(bestMeta)
                local imminentEmergency =
                    plausibleEmergency
                    and
                    bestImpact <= CROWD_EMERGENCY_ETA
                    and bestImpact + CROWD_SWITCH_ETA_ADVANTAGE
                        < primaryImpact
                local higherDanger =
                    plausibleEmergency
                    and
                    bestMeta.dangerTier > primaryMeta.dangerTier
                    and bestImpact + 0.022 < primaryImpact
                local decisiveScore =
                    plausibleEmergency
                    and
                    bestImpact <= primaryImpact + 0.025
                    and bestMeta.score + CROWD_SWITCH_SCORE_ADVANTAGE
                        < primaryMeta.score

                if physicalEmergency
                    or imminentEmergency
                    or higherDanger
                    or decisiveScore
                then
                    selectedTarget = bestTarget
                    selectedMeta = bestMeta
                    selection = physicalEmergency
                        and "crowd-physical-emergency"
                        or (imminentEmergency
                            and "crowd-imminent-emergency"
                            or (higherDanger
                                and "crowd-higher-danger"
                                or "crowd-decisive-score"))
                end
            end
        elseif Runtime.primaryTarget and bestTarget then
            selection = "crowd-cover-primary-gap"
        end

        if defenseHintMeta
            and Runtime.defenseHintTarget
            and selectedTarget ~= Runtime.defenseHintTarget
        then
            local hintImpact =
                tonumber(defenseHintMeta.impactEta)
                    or tonumber(Runtime.defenseHintImpactEta)
                    or math.huge
            local selectedImpact =
                tonumber(selectedMeta and selectedMeta.impactEta)
                    or math.huge
            local hintDanger =
                tonumber(defenseHintMeta.dangerTier) or 0
            local selectedDanger =
                tonumber(selectedMeta and selectedMeta.dangerTier) or 0
            local hintWins =
                defenseHintMeta.serverPhysical == true
                or (
                    isPlausibleCrowdEmergency(defenseHintMeta)
                    and hintImpact + 0.020 < selectedImpact
                )
                or (
                    isPlausibleCrowdEmergency(defenseHintMeta)
                    and hintImpact <= 0.22
                    and hintImpact <= selectedImpact + 0.010
                    and hintDanger >= selectedDanger
                )

            if hintWins then
                selectedTarget = Runtime.defenseHintTarget
                selectedMeta = defenseHintMeta
                selection = "parry-prearm-hint"
            end
        end

        local stickyMeta = Runtime.stickyTarget
            and candidates[Runtime.stickyTarget]
            or nil

        if selectedTarget
            and Runtime.stickyTarget
            and selectedTarget ~= Runtime.stickyTarget
            and stickyMeta
        then
            local selectedImpact = tonumber(selectedMeta.impactEta) or math.huge
            local stickyImpact = tonumber(stickyMeta.impactEta) or math.huge
            local urgentSwitch = selectedMeta.serverPhysical == true
                or (
                    isPlausibleCrowdEmergency(selectedMeta)
                    and
                    selectedImpact <= CROWD_EMERGENCY_ETA
                    and selectedImpact + CROWD_SWITCH_ETA_ADVANTAGE
                        < stickyImpact
                )
                or (
                    isPlausibleCrowdEmergency(selectedMeta)
                    and
                    selectedMeta.dangerTier > stickyMeta.dangerTier
                    and selectedImpact + 0.022 < stickyImpact
                )

            if now - (tonumber(Runtime.selectedAt) or 0)
                    < CROWD_MIN_TARGET_HOLD
                and not urgentSwitch
            then
                selectedTarget = Runtime.stickyTarget
                selectedMeta = stickyMeta
                selection = "crowd-minimum-hold"
            end
        end

        local committedMeta = Runtime.defenseTarget
            and candidates[Runtime.defenseTarget]
            or nil

        if Runtime.defenseTarget
            and now > (
                tonumber(
                    Runtime.defenseUntil
                ) or 0
            )
        then
            Runtime.defenseTarget = nil
            Runtime.defenseUntil = 0
            Runtime.defenseImpactEta =
                math.huge
            committedMeta = nil
        elseif Runtime.defenseTarget
            and not committedMeta
            and Runtime.verifiedHoldTarget
                == Runtime.defenseTarget
            and now <= (
                tonumber(
                    Runtime.verifiedHoldUntil
                ) or 0
            )
        then
            committedMeta =
                Runtime.verifiedHoldMeta
        elseif Runtime.defenseTarget
            and not committedMeta
        then
            Runtime.defenseTarget = nil
            Runtime.defenseUntil = 0
            Runtime.defenseImpactEta =
                math.huge
        end

        if committedMeta
            and selectedTarget
            and selectedTarget ~= Runtime.defenseTarget
        then
            local challengerImpact =
                tonumber(selectedMeta and selectedMeta.impactEta)
                    or math.huge
            local committedImpact =
                tonumber(committedMeta.impactEta)
                    or tonumber(Runtime.defenseImpactEta)
                    or math.huge
            local challengerPhysical =
                selectedMeta and selectedMeta.serverPhysical == true
            local committedPhysical =
                committedMeta.serverPhysical == true
            local challengerDanger =
                tonumber(selectedMeta and selectedMeta.dangerTier) or 0
            local committedDanger =
                tonumber(committedMeta.dangerTier) or 0
            local trulyEarlier =
                selectedMeta
                and isPlausibleCrowdEmergency(selectedMeta)
                and challengerDanger >= committedDanger
                and challengerImpact + DEFENSE_SWITCH_ETA_ADVANTAGE
                    < committedImpact

            if not (
                (challengerPhysical and not committedPhysical)
                or trulyEarlier
            ) then
                selectedTarget = Runtime.defenseTarget
                selectedMeta = committedMeta
                selection = "defense-commit"
            else
                Runtime.defenseTarget = nil
                Runtime.defenseUntil = 0
                Runtime.defenseImpactEta = math.huge
            end
        elseif committedMeta and not selectedTarget then
            selectedTarget = Runtime.defenseTarget
            selectedMeta = committedMeta
            selection = "defense-commit"
        end

        local selectedIsLiveCandidate =
            selectedTarget ~= nil
            and selectedMeta ~= nil
            and candidates[selectedTarget] == selectedMeta

        if selectedTarget and selectedMeta then
            local selectedImpact =
                tonumber(selectedMeta.impactEta) or math.huge
            local selectedDanger =
                tonumber(selectedMeta.dangerTier) or 0

            if selectedIsLiveCandidate
                and selectedDanger >= 2
                and selectedImpact <= DEFENSE_COMMIT_ETA
            then
                local commitFor = math.clamp(
                    selectedImpact + DEFENSE_COMMIT_POST_CONTACT,
                    0.16,
                    0.38
                )

                if Runtime.defenseTarget ~= selectedTarget then
                    Runtime.defenseTarget = selectedTarget
                    Runtime.defenseUntil = now + commitFor
                else
                    Runtime.defenseUntil = math.max(
                        tonumber(Runtime.defenseUntil) or 0,
                        now + commitFor
                    )
                end
                Runtime.defenseImpactEta = selectedImpact
            end
        end

        if selectedTarget then
            if Runtime.stickyTarget ~= selectedTarget then
                Runtime.selectedAt = now
            end
            Runtime.stickyTarget = selectedTarget
            Runtime.stickyScore = selectedMeta.score
            Runtime.stickyUntil = now

            if selectedIsLiveCandidate
                and selectedMeta
                and (
                    selectedMeta.hitboxWillHit == true
                    or selectedMeta.serverPhysical == true
                    or selectedMeta.apPathVerified == true
                )
            then
                local holdImpact =
                    math.clamp(
                        tonumber(
                            selectedMeta.impactEta
                        ) or 0,
                        0,
                        0.18
                    )
                Runtime.verifiedHoldTarget =
                    selectedTarget
                Runtime.verifiedHoldUntil =
                    now
                    + math.clamp(
                        holdImpact + 0.075,
                        0.070,
                        0.210
                    )
                Runtime.verifiedHoldMeta =
                    selectedMeta
            end

            selectedMeta.mode = candidateCount > 1 and "crowd" or "threat"
            selectedMeta.selection = selection
            selectedMeta.candidates = candidateCount
            selectedMeta.primary = Runtime.primaryTarget
                and Runtime.primaryTarget.Name
                or ""
            return selectedTarget, selectedMeta
        end

        local verifiedThreat =
            Runtime.verifiedHoldMeta
            and Runtime.verifiedHoldMeta.threatRef
            or nil

        if verifiedThreat
            and (
                verifiedThreat.expired == true
                or verifiedThreat.autoFaceEndedAt ~= nil
                or verifiedThreat.serverHitboxEndedAt ~= nil
            )
        then
            Runtime.verifiedHoldTarget = nil
            Runtime.verifiedHoldUntil = 0
            Runtime.verifiedHoldMeta = nil
        elseif verifiedThreat
            and hasLiveServerHitbox(
                verifiedThreat
            )
            and not isServerHitboxTouchingLocal(
                verifiedThreat,
                root
            )
        then
            Runtime.verifiedHoldTarget = nil
            Runtime.verifiedHoldUntil = 0
            Runtime.verifiedHoldMeta = nil
        end

        if Runtime.verifiedHoldTarget
            and Runtime.verifiedHoldTarget.Parent
            and now
                <= (
                    tonumber(
                        Runtime.verifiedHoldUntil
                    ) or 0
                )
            and targetCanBeFaced(
                Runtime.verifiedHoldTarget,
                root,
                PRIMARY_ACQUIRE_RANGE + 1.0
            )
        then
            local heldMeta =
                Runtime.verifiedHoldMeta
                or {}
            heldMeta.mode = "threat"
            heldMeta.reason =
                "verified-hitbox-handoff"
            heldMeta.selection =
                "verified-hold"
            heldMeta.candidates = 1
            heldMeta.primary =
                Runtime.verifiedHoldTarget.Name
            heldMeta.hitboxWillHit = true

            return Runtime.verifiedHoldTarget,
                heldMeta
        end

        Runtime.verifiedHoldTarget = nil
        Runtime.verifiedHoldUntil = 0
        Runtime.verifiedHoldMeta = nil

        Runtime.stickyTarget = nil
        Runtime.stickyUntil = 0
        Runtime.stickyScore = nil
        if Runtime.primaryTarget
            and now > (tonumber(Runtime.primaryUntil) or 0)
        then
            Runtime.primaryTarget = nil
            Runtime.primaryUntil = 0
        end
        return nil
    end

    local function reportTarget(target, meta)
        local now = os.clock()
        local mode = meta and meta.mode or nil
        if Runtime.lastReportedTarget == target
            and Runtime.lastReportedMode == mode
        then
            return
        end

        local previous = Runtime.lastReportedTarget
        Runtime.lastReportedTarget = target
        Runtime.lastReportedMode = mode

        if target then
            debugLog("AUTOFACE_TARGET", {
                target = target.Name,
                previous = previous and previous.Name or "",
                mode = mode or "",
                reason = meta and meta.reason or "",
                attack = meta and meta.attack or "",
                style = meta and meta.style or "",
                variant = meta and meta.variant or "",
                source = meta and meta.source or "",
                distance = meta and meta.distance or "",
                projectedDistance = meta and meta.projectedDistance or "",
                armThreshold = meta and meta.armThreshold or "",
                facingDot = meta and meta.facingDot or "",
                closing = meta and meta.closing or "",
                eta = meta and meta.eta or "",
                impactEta = meta and meta.impactEta or "",
                dangerTier = meta and meta.dangerTier or "",
                hitboxWillHit =
                    meta
                    and meta.hitboxWillHit
                    or false,
                apPathVerified =
                    meta
                    and meta.apPathVerified
                    or false,
                apPathProjectedDistance =
                    meta
                    and meta.apPathProjectedDistance
                    or "",
                apPathVerticalDifference =
                    meta
                    and meta.apPathVerticalDifference
                    or "",
                hitboxModel =
                    meta
                    and meta.hitboxModel
                    or "",
                hitboxProfile =
                    meta
                    and meta.hitboxProfileKey
                    or "",
                hitboxSamples =
                    meta
                    and meta.hitboxProfileSamples
                    or 0,
                hitboxLateral =
                    meta
                    and meta.hitboxLateral
                    or "",
                hitboxDepth =
                    meta
                    and meta.hitboxDepth
                    or "",
                candidates = meta and meta.candidates or 0,
                primary = meta and meta.primary or "",
                selection = meta and meta.selection or "",
                score = meta and meta.score or "",
                fullOwnership = true,
                speedSetting =
                    tonumber(
                        Flags.ap_auto_face_speed
                    ) or 1320,
                smoothnessSetting =
                    tonumber(
                        Flags.ap_auto_face_smoothness
                    ) or 16,
                appliedYaw =
                    Runtime.lastAppliedYaw
                    or "",
                punishImpactHold =
                    Menu._AutoPunishRuntime
                    and Menu._AutoPunishRuntime
                        .isImpactFaceHoldActive
                    and Menu._AutoPunishRuntime
                        .isImpactFaceHoldActive(
                            target,
                            now
                        )
                    or false,
                punishImpactRemaining =
                    (
                        Menu._AutoPunishRuntime
                        and Menu._AutoPunishRuntime
                            .impactFaceTarget
                            == target
                    )
                    and math.max(
                        0,
                        (
                            tonumber(
                                Menu._AutoPunishRuntime
                                    .impactFaceUntil
                            ) or now
                        ) - now
                    )
                    or 0,
                shiftLockGuard =
                    Runtime.rotationGuardInstalled
                    == true,
                renderOwner =
                    Runtime.renderBound
                    == true,
            }, true)

            if previous
                and previous ~= target
                and meta
                and (tonumber(meta.candidates) or 0) > 1
            then
                debugLog("AUTOFACE_CROWD_SWITCH", {
                    previous = previous.Name,
                    target = target.Name,
                    primary = meta.primary or "",
                    selection = meta.selection or "",
                    candidates = meta.candidates or 0,
                    attack = meta.attack or "",
                    impactEta = meta.impactEta or "",
                    dangerTier = meta.dangerTier or "",
                    distance = meta.distance or "",
                }, true)
            end
        elseif previous then
            debugLog("AUTOFACE_RELEASE", {
                previous = previous.Name,
            }, true)
        end
    end

    local function applyFacing(target, dt, forceSnap, meta)
        if not isAutoFaceCombatEnabled() then
            return false
        end

        local character = getCharacter()
        local root = getRoot(character)
        local humanoid = character
            and character:FindFirstChildOfClass("Humanoid")
        local targetRoot = getRoot(target)

        if not character
            or not root
            or not humanoid
            or humanoid.Health <= 0
            or not targetRoot
        then
            return false
        end

        local direction = flat(targetRoot.Position - root.Position)
        if direction.Magnitude <= 0.05 then
            return false
        end

        ownAutoRotate(humanoid)
        Runtime.ownedRoot = root

        local locked = Runtime.lockedTarget == target
        local lockReason = tostring(Runtime.lockReason or "")
        local localAliRightM2 = locked
            and string.find(lockReason, "local-ali-right-m2", 1, true) ~= nil

        if localAliRightM2 then
            local targetVelocity = flat(targetRoot.AssemblyLinearVelocity)
            local leadSeconds = math.clamp(
                direction.Magnitude / 70,
                0.035,
                0.095
            )
            local predictedDirection = flat(
                targetRoot.Position
                    + targetVelocity * leadSeconds
                    - root.Position
            )
            if predictedDirection.Magnitude > 0.05 then
                direction = predictedDirection
            end
        end
        local defensiveLock = locked
            and string.find(lockReason, "parry-defense", 1, true) ~= nil
        local impactEta = tonumber(meta and meta.impactEta)
        local threatUrgent =
            impactEta ~= nil
            and impactEta >= 0
            and impactEta <= 0.34
            and (
                meta.mode == "threat"
                or meta.mode == "crowd"
                or meta.mode == "lock"
            )

        local rawDesiredYaw = math.atan2(
            -direction.Unit.X,
            -direction.Unit.Z
        )
        local sameTarget = Runtime.lastFacingTarget == target
        local desiredYaw = rawDesiredYaw

        if sameTarget
            and type(Runtime.lastDesiredYaw) == "number"
            and forceSnap ~= true
        then
            local desiredDelta = math.atan2(
                math.sin(rawDesiredYaw - Runtime.lastDesiredYaw),
                math.cos(rawDesiredYaw - Runtime.lastDesiredYaw)
            )
            local absDesiredDelta = math.abs(desiredDelta)

            if direction.Magnitude < 1.10 and not defensiveLock then
                desiredYaw = Runtime.lastDesiredYaw
            else
                local targetDeadzone = defensiveLock
                    and math.rad(0.12)
                    or (
                        threatUrgent
                            and math.rad(0.28)
                            or math.rad(0.65)
                    )

                if absDesiredDelta <= targetDeadzone then
                    desiredYaw = Runtime.lastDesiredYaw
                elseif not defensiveLock then
                    local sliderSmooth =
                        math.clamp(
                            tonumber(
                                Flags.ap_auto_face_smoothness
                            ) or 16,
                            0,
                            100
                        ) / 100

                    local blend =
                        1
                        - sliderSmooth * 0.62

                    if direction.Magnitude <= 3.25 then
                        blend *=
                            threatUrgent
                                and 0.82
                                or 0.62
                    elseif absDesiredDelta
                        <= math.rad(16)
                    then
                        blend *=
                            threatUrgent
                                and 0.92
                                or 0.80
                    end

                    blend =
                        math.clamp(
                            blend,
                            0.18,
                            1
                        )

                    desiredYaw =
                        Runtime.lastDesiredYaw
                        + desiredDelta * blend
                end
            end
        end

        Runtime.lastFacingTarget = target
        Runtime.lastDesiredYaw = desiredYaw

        local currentLook = flat(root.CFrame.LookVector)
        if currentLook.Magnitude <= 0.05 then
            writeOwnedYaw(
                root,
                desiredYaw
            )
            return true
        end

        local actualCurrentYaw =
            math.atan2(
                -currentLook.Unit.X,
                -currentLook.Unit.Z
            )
        local currentYaw =
            actualCurrentYaw

        if sameTarget
            and forceSnap ~= true
            and type(
                Runtime.lastAppliedYaw
            ) == "number"
        then
            currentYaw =
                Runtime.lastAppliedYaw
        end

        local deltaYaw = math.atan2(
            math.sin(desiredYaw - currentYaw),
            math.cos(desiredYaw - currentYaw)
        )

        if forceSnap == true then
            if math.abs(deltaYaw) > math.rad(0.30) then
                writeOwnedYaw(
                    root,
                    desiredYaw
                )
            end
            return true
        end

        local speedDeg = math.clamp(
            tonumber(Flags.ap_auto_face_speed) or 1320,
            60,
            1800
        )
        local smoothness = math.clamp(
            tonumber(Flags.ap_auto_face_smoothness) or 16,
            0,
            100
        ) / 100

        local settleDegrees =
            threatUrgent
                and (
                    0.10
                    + smoothness * 0.24
                )
                or (
                    0.24
                    + smoothness * 0.76
                )

        if localAliRightM2 then
            settleDegrees =
                math.min(
                    settleDegrees,
                    0.16
                )
        elseif defensiveLock then
            settleDegrees =
                math.min(
                    settleDegrees,
                    0.20
                )
        end

        local settleEpsilon =
            math.rad(
                settleDegrees
            )

        if math.abs(deltaYaw) <= settleEpsilon then
            return true
        end

        dt = math.clamp(
            tonumber(dt) or (1 / 60),
            1 / 360,
            0.05
        )

        local responseHz =
            30
            - smoothness * 24

        responseHz =
            math.clamp(
                responseHz,
                6,
                30
            )

        local alpha =
            1
            - math.exp(
                -responseHz * dt
            )
        local maxStep =
            math.rad(speedDeg)
            * dt
        local step = math.clamp(
            deltaYaw * alpha,
            -maxStep,
            maxStep
        )

        if math.abs(step) > math.rad(0.002) then
            local nextYaw =
                currentYaw
                + step

            writeOwnedYaw(
                root,
                nextYaw
            )
        end

        return true
    end

    Runtime.faceNow = function(target)
        if Flags.ap_enable ~= true
            or Flags.ap_auto_face ~= true
            or not isAutoFaceCombatEnabled()
            or not target
            or not target.Parent
            or (Menu._IsFriendlyCharacter and Menu._IsFriendlyCharacter(target))
        then
            return false
        end
        return applyFacing(target, 0, true)
    end

    local function resetAutoFaceState()
        clearTargetLock()
        clearDefenseHint()
        Runtime.stickyTarget = nil
        Runtime.stickyUntil = 0
        Runtime.stickyScore = nil
        Runtime.lastFacingTarget = nil
        Runtime.lastDesiredYaw = nil
        Runtime.lastAppliedYaw = nil
        Runtime.lastRenderAt = nil
        Runtime.primaryTarget = nil
        Runtime.primaryUntil = 0
        Runtime.selectedAt = 0
        Runtime.activeCandidateCount = 0
        Runtime.defenseTarget = nil
        Runtime.defenseUntil = 0
        Runtime.defenseImpactEta = math.huge
        Runtime.currentTarget = nil
        Runtime.currentMeta = nil
        Runtime.currentEvidenceAt = 0
        Runtime.verifiedHoldTarget = nil
        Runtime.verifiedHoldUntil = 0
        Runtime.verifiedHoldMeta = nil
    end

    Runtime.invalidateThreat =
        function(threat, reason)
            if not threat then
                return false
            end

            local now =
                os.clock()
            local owner =
                threat.owner

            if not owner
                or not owner.Parent
            then
                owner =
                    resolveOwner(
                        threat
                    )
            end

            local localCharacter =
                getCharacter()

            if not owner
                or not owner.Parent
                or owner == localCharacter
                or (
                    threat.attackType ~= "M1"
                    and threat.attackType ~= "M2"
                )
            then
                owner = nil
            end

            threat.autoFaceEndedAt =
                now
            threat.autoFaceEndReason =
                reason
                or "expired"

            local root =
                getRoot(
                    getCharacter()
                )

            local impactHoldActive =
                false
            local punishActive =
                false
            local punish =
                Menu._AutoPunishRuntime

            if owner
                and punish
                and type(
                    punish
                        .isImpactFaceHoldActive
                ) == "function"
            then
                local ok,
                    active =
                        pcall(
                            punish
                                .isImpactFaceHoldActive,
                            owner,
                            now
                        )

                impactHoldActive =
                    ok
                    and active == true
            end

            local lockReasonLower =
                string.lower(
                    tostring(
                        Runtime.lockReason
                        or ""
                    )
                )
            local punishLockActive =
                owner
                and Runtime.lockedTarget
                    == owner
                and now <= (
                    tonumber(
                        Runtime.lockUntil
                    ) or 0
                )
                and string.find(
                    lockReasonLower,
                    "parry-punish",
                    1,
                    true
                ) ~= nil
                or false

            punishActive =
                impactHoldActive
                or punishLockActive

            local heldMeta =
                Runtime.verifiedHoldMeta

            if heldMeta
                and heldMeta.threatRef == threat
            then
                Runtime.verifiedHoldTarget = nil
                Runtime.verifiedHoldUntil = 0
                Runtime.verifiedHoldMeta = nil
            end

            if owner
                and Runtime.defenseHintTarget
                    == owner
            then
                clearDefenseHint()
            end

            local hasOtherThreat =
                owner
                and root
                and hasLiveIncomingThreat(
                    owner,
                    root,
                    now
                )
                or false

            if owner
                and Runtime.defenseTarget
                    == owner
                and not hasOtherThreat
            then
                Runtime.defenseTarget = nil
                Runtime.defenseUntil = 0
                Runtime.defenseImpactEta =
                    math.huge
            end

            if owner
                and Runtime.stickyTarget
                    == owner
                and not hasOtherThreat
                and not punishActive
            then
                Runtime.stickyTarget = nil
                Runtime.stickyUntil = 0
                Runtime.stickyScore = nil
            end

            local defenseLock =
                string.find(
                    lockReasonLower,
                    "parry-defense",
                    1,
                    true
                ) ~= nil

            if owner
                and impactHoldActive
                and Runtime.lockedTarget
                    == owner
            then
                local punishAttack =
                    tostring(
                        punish.impactFaceAttack
                        or "M1"
                    )
                local impactReason =
                    punishAttack == "M2"
                    and "parry-punish-m2-impact"
                    or "parry-punish-m1-impact"

                Runtime.lockReason =
                    impactReason
                Runtime.lockPriority =
                    getLockPriority(
                        impactReason
                    )
                Runtime.lockUntil =
                    math.max(
                        tonumber(
                            Runtime.lockUntil
                        ) or 0,
                        tonumber(
                            punish.impactFaceUntil
                        ) or now
                    )
            elseif owner
                and Runtime.lockedTarget
                    == owner
                and defenseLock
                and not hasOtherThreat
                and not punishActive
            then
                clearTargetLock()
            end

            if owner
                and Runtime.currentTarget
                    == owner
                and not hasOtherThreat
                and not punishActive
            then
                Runtime.currentTarget = nil
                Runtime.currentMeta = nil
                Runtime.currentEvidenceAt = 0
                Runtime.lastFacingTarget = nil
                Runtime.lastDesiredYaw = nil

                reportTarget(nil)
                releaseRotation()
            end

            debugLog(
                "AUTOFACE_THREAT_INVALIDATE",
                {
                    owner =
                        owner
                        and owner.Name
                        or (
                            threat.ownerName
                            or ""
                        ),
                    attack =
                        threat.attackType
                        or "",
                    style =
                        threat.style
                        or "",
                    source =
                        threat.source
                        or "",
                    reason =
                        reason
                        or "expired",
                    otherThreat =
                        hasOtherThreat,
                    punishHold =
                        punishActive,
                    lockReason =
                        Runtime.lockReason
                        or "",
                },
                true
            )

            return true
        end

    Runtime.release = releaseRotation

    local function updateAutoFace(dt)
        if Flags.ap_enable ~= true
            or Flags.ap_auto_face ~= true
        then
            if Runtime.wasHeartbeatActive == true
                or Runtime.lockedTarget ~= nil
                or Runtime.defenseHintTarget ~= nil
                or Runtime.stickyTarget ~= nil
                or Runtime.verifiedHoldTarget ~= nil
                or Runtime.humanoid ~= nil
            then
                Runtime.wasHeartbeatActive = false
                resetAutoFaceState()
                reportTarget(nil)
                releaseRotation()
            end
            return
        end

        Runtime.wasHeartbeatActive = true

        if not isAutoFaceCombatEnabled() then
            Runtime.wasHeartbeatActive = false
            resetAutoFaceState()
            reportTarget(nil)
            releaseRotation()
            return
        end

        local character = getCharacter()
        local root = getRoot(character)
        local humanoid = character
            and character:FindFirstChildOfClass("Humanoid")
        if not character
            or not root
            or not humanoid
            or humanoid.Health <= 0
        then
            resetAutoFaceState()
            reportTarget(nil)
            releaseRotation()
            return
        end

        local now = os.clock()

        local ali = Menu._AliCounterRuntime
        if ali and tonumber(ali.pendingUntil)
            and tonumber(ali.pendingUntil) > now
        then
            Runtime.currentTarget = nil
            Runtime.currentMeta = nil
            Runtime.currentEvidenceAt = 0
            releaseRotation()
            return
        end

        local target, targetMeta = chooseTarget(root, now)
        Runtime.currentTarget = target
        Runtime.currentMeta = targetMeta
        Runtime.currentEvidenceAt = target and now or 0
        reportTarget(target, targetMeta)

        if not target then
            Runtime.currentEvidenceAt = 0
            Runtime.lastFacingTarget = nil
            Runtime.lastDesiredYaw = nil
            releaseRotation()
            return
        end

        applyFacing(target, dt, false, targetMeta)
    end

    Runtime.renderBound = false
    pcall(function()
        RunService:UnbindFromRenderStep(
            AUTO_FACE_RENDER_BIND
        )
    end)

    Runtime.connection =
        Menu._ScriptRuntime:Track(
            RunService.Heartbeat:Connect(
                updateAutoFace
            )
        )

    local function enforceRenderOwnership()
        if Flags.ap_enable ~= true
            or Flags.ap_auto_face ~= true
            or not isAutoFaceCombatEnabled()
        then
            return
        end

        local target =
            Runtime.currentTarget

        if not target
            or not target.Parent
        then
            return
        end

        local character =
            getCharacter()
        local root =
            getRoot(
                character
            )
        local humanoid =
            character
            and character
                :FindFirstChildOfClass(
                    "Humanoid"
                )

        if not root
            or not humanoid
            or humanoid.Health <= 0
        then
            return
        end

        local now = os.clock()
        local evidenceAt =
            tonumber(Runtime.currentEvidenceAt) or 0
        local staleReason = nil

        if evidenceAt <= 0
            or now - evidenceAt > 0.18
        then
            staleReason = "evidence-timeout"
        end

        local meta = Runtime.currentMeta
        local threat =
            meta and meta.threatRef or nil

        if not staleReason and threat then
            if threat.expired == true
                or threat.autoFaceEndedAt ~= nil
                or threat.serverHitboxEndedAt ~= nil
                or threatOwner(threat) ~= target
            then
                staleReason = "threat-ended"
            elseif hasLiveServerHitbox(threat)
                and not isServerHitboxTouchingLocal(
                    threat,
                    root
                )
            then
                local keepPhysicalGrace = false
                local hitbox = threat.hitbox
                local lastPhysicalAt =
                    tonumber(
                        threat.autoFaceLastPhysicalAt
                    ) or 0

                if hitbox
                    and hitbox.Parent
                    and threat.autoFaceLastPhysicalHitbox
                        == hitbox
                    and now - lastPhysicalAt
                        <= AUTOFACE_PHYSICAL_HIT_GRACE
                then
                    local targetRoot =
                        getRoot(target)
                    local ownerDistance =
                        targetRoot
                        and flat(
                            targetRoot.Position
                                - root.Position
                        ).Magnitude
                        or math.huge

                    keepPhysicalGrace =
                        ownerDistance
                            <= AUTOFACE_PHYSICAL_GRACE_MAX_OWNER_DISTANCE
                end

                if not keepPhysicalGrace then
                    -- A replicated hitbox is authoritative, but only after the
                    -- short overlap hysteresis has expired. This prevents
                    -- RenderStepped from undoing the candidate-side grace on
                    -- the very next frame.
                    staleReason = "live-hitbox-miss"
                end
            end
        end

        if staleReason then
            Runtime.currentTarget = nil
            Runtime.currentMeta = nil
            Runtime.currentEvidenceAt = 0
            Runtime.lastFacingTarget = nil
            Runtime.lastDesiredYaw = nil

            if Runtime.stickyTarget == target then
                Runtime.stickyTarget = nil
                Runtime.stickyUntil = 0
                Runtime.stickyScore = nil
            end
            if Runtime.primaryTarget == target then
                Runtime.primaryTarget = nil
                Runtime.primaryUntil = 0
            end
            if Runtime.defenseTarget == target then
                Runtime.defenseTarget = nil
                Runtime.defenseUntil = 0
                Runtime.defenseImpactEta = math.huge
            end
            if Runtime.defenseHintTarget == target then
                clearDefenseHint()
            end

            reportTarget(nil)
            releaseRotation()

            debugLog(
                "AUTOFACE_RENDER_STALE_RELEASE",
                {
                    target = target.Name,
                    reason = staleReason,
                    source = meta and meta.source or "",
                    attack = meta and meta.attack or "",
                    evidenceAge = evidenceAt > 0
                        and (now - evidenceAt)
                        or "",
                },
                true
            )
            return
        end

        ownAutoRotate(
            humanoid
        )
        Runtime.ownedRoot =
            root

        local appliedYaw =
            tonumber(
                Runtime.lastAppliedYaw
            )

        if appliedYaw == nil then
            return
        end

        local currentLook =
            flat(
                root.CFrame.LookVector
            )

        if currentLook.Magnitude <= 0.05 then
            writeOwnedYaw(
                root,
                appliedYaw
            )
            return
        end

        local currentYaw =
            math.atan2(
                -currentLook.Unit.X,
                -currentLook.Unit.Z
            )
        local deltaYaw =
            math.atan2(
                math.sin(
                    appliedYaw
                    - currentYaw
                ),
                math.cos(
                    appliedYaw
                    - currentYaw
                )
            )

        if math.abs(deltaYaw)
            > math.rad(0.18)
        then
            writeOwnedYaw(
                root,
                appliedYaw
            )
        end
    end

    pcall(function()
        RunService:BindToRenderStep(
            AUTO_FACE_RENDER_BIND,
            Enum.RenderPriority.Last.Value
                - 1,
            enforceRenderOwnership
        )

        Runtime.renderBound =
            true
    end)

    debugLog(
        "AUTOFACE_SMOOTH_OWNER_READY",
        {
            comboBridge =
                COMBO_BRIDGE_SECONDS,
            strictThreatOnly =
                true,
            hitboxDriven =
                true,
            maxThreatRange =
                PRIMARY_ACQUIRE_RANGE
                + 1.0,
            crowdHold =
                CROWD_MIN_TARGET_HOLD,
            defensePostContact =
                DEFENSE_COMMIT_POST_CONTACT,
            shiftLockGuard =
                Runtime.rotationGuardInstalled
                == true,
            renderOwner =
                Runtime.renderBound
                == true,
            speedSliderAuthoritative =
                true,
            smoothnessSliderAuthoritative =
                true,
            renderSnap =
                false,
            logicalYawOwnership =
                true,
            apCommittedPathEvidence =
                true,
            autoPunishImpactOwnership =
                true,
            largeFireSnap =
                false,
            verifiedThreatHold =
                true,
            staleRenderWatchdog =
                true,
            renderEvidenceTimeout =
                0.18,
            renderPriority =
                Enum.RenderPriority.Last.Value
                - 1,
            apFireIndependent =
                true,
        },
        true
    )

    Runtime.shutdown = function()
        pcall(function()
            RunService:UnbindFromRenderStep(AUTO_FACE_RENDER_BIND)
        end)
        Runtime.renderBound = false
        if Runtime.connection then
            pcall(function()
                Runtime.connection:Disconnect()
            end)
            Runtime.connection = nil
        end
        resetAutoFaceState()
        reportTarget(nil)
        releaseRotation()
    end

end

local serverLinks = {}
local seenSwingIds = {}
local seenActionTokens = {}
local timingBias = {}
Menu._ResolverTimingRuntime.biasSamples = Menu._ResolverTimingRuntime.biasSamples or {}
Menu._ResolverTimingRuntime.surfaceThreats = Menu._ResolverTimingRuntime.surfaceThreats or {}
Menu._ResolverTimingRuntime.surfaceSerial = tonumber(Menu._ResolverTimingRuntime.surfaceSerial) or 0
Menu._hakariObservedSpeed = Menu._hakariObservedSpeed or {}
local watchedCharacters = setmetatable({}, {__mode = "k"})
local animationMaps = setmetatable({}, {__mode = "k"})





local resolverStateByCharacter = setmetatable({}, {__mode = "k"})
local RESOLVER_TOKEN_PROOF_WINDOW = 0.40
local RESOLVER_COOLDOWN_PROOF_WINDOW = 0.40
local RESOLVER_TOKEN_PREPAD = 0.050

-- Main410 resolver hardening for desync/fake combat animations.
-- A visual attack is not allowed to borrow stale replicated state from an
-- earlier swing.  Proof must be temporally bound to this exact animation.
Menu._ResolverProofRuntime = Menu._ResolverProofRuntime or {}
Menu._ResolverProofRuntime.ANIM_PROOF_PREPAD = 0.055
Menu._ResolverProofRuntime.ANIM_TOKEN_POSTPAD_M1 = 0.070
Menu._ResolverProofRuntime.ANIM_TOKEN_POSTPAD_M2 = 0.090
Menu._ResolverProofRuntime.ANIM_REPLICATED_POSTPAD_M1 = 0.145
Menu._ResolverProofRuntime.ANIM_REPLICATED_POSTPAD_M2 = 0.170
Menu._ResolverProofRuntime.ANIM_COOLDOWN_POSTPAD_M1 = 0.090
Menu._ResolverProofRuntime.ANIM_COOLDOWN_POSTPAD_M2 = 0.110
Menu._ResolverProofRuntime.EARLY_STOP_FAKE_M1 = 0.080
Menu._ResolverProofRuntime.EARLY_STOP_FAKE_M2 = 0.100
Menu._ResolverProofRuntime.WEAK_STOP_HOLD_M1 = 0.115
Menu._ResolverProofRuntime.WEAK_STOP_HOLD_M2 = 0.145
Menu._ResolverProofRuntime.INCOMING_PUNISH_CONTEXT_HOLD = 1.25
Menu._ResolverProofRuntime.INCOMING_PUNISH_M1_EMERGENCY_STOP = 0.012
Menu._ResolverProofRuntime.INCOMING_PUNISH_M2_EMERGENCY_STOP = 0.012
Menu._ResolverProofRuntime.INCOMING_PUNISH_M1_CONTACT = 0.105
Menu._ResolverProofRuntime.INCOMING_PUNISH_M2_CONTACT = 0.105
Menu._ResolverProofRuntime.INCOMING_PUNISH_M1_GUARD_HOLD = 0.380
Menu._ResolverProofRuntime.INCOMING_PUNISH_M2_GUARD_HOLD = 0.300
Menu._ResolverProofRuntime.localPunishContextUntil =
    tonumber(Menu._ResolverProofRuntime.localPunishContextUntil) or 0

-- Main410: some desynced attacks use a second lifecycle that is different
-- from the 3-6 ms AutoPunish shell.  The visual track can stop almost
-- immediately, then a fresh replicated M1/M2 edge appears ~80-110 ms later,
-- while the real server hitbox does not arrive until the original combat
-- timeline (~0.34-0.38 s for Boxing M1).  Keep the stopped visual as a
-- short-lived latent candidate and only restore it when that later replicated
-- edge belongs to the same owner/attack.
Menu._ResolverProofRuntime.LATENT_STOP_SURFACE_WINDOW_M1 = 0.240
Menu._ResolverProofRuntime.LATENT_STOP_SURFACE_WINDOW_M2 = 0.220
Menu._ResolverProofRuntime.LATENT_STOP_CONTACT_GRACE = 0.180
Menu._ResolverProofRuntime.LATENT_STOP_GUARD_HOLD_M1 = 0.240
Menu._ResolverProofRuntime.LATENT_STOP_GUARD_HOLD_M2 = 0.300
Menu._ResolverProofRuntime.latentStoppedByCharacter =
    Menu._ResolverProofRuntime.latentStoppedByCharacter
    or setmetatable({}, {__mode = "k"})

Menu._ResolverProofRuntime.armLatentStopped = function(threat, now)
    if not threat
        or not threat.owner
        or not threat.owner.Parent
        or (
            threat.attackType ~= "M1"
            and threat.attackType ~= "M2"
        )
    then
        return false
    end

    now = tonumber(now) or os.clock()

    local speed =
        math.clamp(
            tonumber(threat.speedMultiplier) or 1,
            0.2,
            3
        )
    local hitTL =
        tonumber(threat.hitTL)
        or getThreatHitTimeline(threat)
    local expectedContactAbs =
        tonumber(threat.expectedContactAbs)
        or (
            (tonumber(threat.createdAt) or now)
            + hitTL / speed
            + Menu._ResolverTimingRuntime.getBias(threat)
        )
    local window =
        threat.attackType == "M2"
        and Menu._ResolverProofRuntime.LATENT_STOP_SURFACE_WINDOW_M2
        or Menu._ResolverProofRuntime.LATENT_STOP_SURFACE_WINDOW_M1

    local candidate = {
        threat = threat,
        owner = threat.owner,
        ownerName = threat.ownerName or threat.owner.Name,
        attackType = threat.attackType,
        combo = threat.combo or 0,
        style = threat.style or "",
        animationName = threat.animationName or "",
        animationId = threat.animationId or "",
        createdAt = tonumber(threat.createdAt) or now,
        stoppedAt = now,
        hitTL = hitTL,
        speedMultiplier = speed,
        expectedContactAbs = expectedContactAbs,
        expiresAt = now + window,
        consumed = false,
    }

    Menu._ResolverProofRuntime.latentStoppedByCharacter[
        threat.owner
    ] = candidate

    debugLog(
        "AP_RESOLVER_LATENT_STOP_ARM",
        {
            attack = candidate.attackType,
            owner = candidate.ownerName,
            style = candidate.style,
            combo = candidate.combo,
            animationName = candidate.animationName,
            stopAge = now - candidate.createdAt,
            contactIn = expectedContactAbs - now,
            surfaceWindow = window,
        },
        true
    )

    task.delay(window + 0.035, function()
        local active =
            Menu._ResolverProofRuntime.latentStoppedByCharacter[
                candidate.owner
            ]

        if active ~= candidate
            or candidate.consumed == true
        then
            return
        end

        Menu._ResolverProofRuntime.latentStoppedByCharacter[
            candidate.owner
        ] = nil

        if candidate.threat
            and candidate.threat.serverConfirmed ~= true
            and candidate.threat.fired ~= true
        then
            Menu._APBreakerResolver.noteFake(
                candidate.threat,
                os.clock(),
                "latent-no-replicated-edge"
            )
        end

        debugLog(
            "AP_RESOLVER_LATENT_STOP_EXPIRE",
            {
                attack = candidate.attackType,
                owner = candidate.ownerName,
                style = candidate.style,
                combo = candidate.combo,
                animationName = candidate.animationName,
                age = os.clock() - candidate.stoppedAt,
            },
            true
        )
    end)

    return true
end

Menu._ResolverProofRuntime.takeLatentStopped = function(
    character,
    attackType,
    edgeAt,
    now
)
    local candidate =
        Menu._ResolverProofRuntime.latentStoppedByCharacter[
            character
        ]

    if not candidate
        or candidate.consumed == true
        or candidate.attackType ~= attackType
    then
        return nil
    end

    now = tonumber(now) or os.clock()
    edgeAt = tonumber(edgeAt) or now

    local originalThreat =
        candidate.threat

    if originalThreat
        and (
            originalThreat.serverConfirmed == true
            or originalThreat.fired == true
        )
    then
        candidate.consumed = true
        Menu._ResolverProofRuntime.latentStoppedByCharacter[
            character
        ] = nil
        return nil
    end

    local originalHandoffUntil =
        originalThreat
        and tonumber(
            originalThreat.trackStopHandoffUntil
        )
        or 0
    local originalStillOwns =
        originalThreat
        and originalThreat.expired ~= true
        and (
            originalThreat.resolverStoppedTrackHandoff == true
            or originalHandoffUntil > now
        )

    if originalStillOwns then
        return nil
    end

    local stopToEdge =
        edgeAt
        - (
            tonumber(candidate.stoppedAt)
            or edgeAt
        )
    local window =
        attackType == "M2"
        and Menu._ResolverProofRuntime.LATENT_STOP_SURFACE_WINDOW_M2
        or Menu._ResolverProofRuntime.LATENT_STOP_SURFACE_WINDOW_M1

    if stopToEdge < -0.015
        or stopToEdge > window
        or now
            > (
                tonumber(candidate.expectedContactAbs)
                or now
            )
                + Menu._ResolverProofRuntime.LATENT_STOP_CONTACT_GRACE
    then
        return nil
    end

    candidate.consumed = true
    candidate.surfaceEdgeAt = edgeAt
    candidate.promotedAt = now
    Menu._ResolverProofRuntime.latentStoppedByCharacter[
        character
    ] = nil

    return candidate
end

-- Main410: an opponent's scripted AutoPunish can begin while the local
-- character is still in the parried/stunned recovery state.  Those attacks
-- may stop their visual track immediately even though a real server hitbox
-- follows.  Keep this context separate from normal fake-animation proof so
-- global breaker filtering remains strict.
Menu._ResolverProofRuntime.isLocalPunishContext = function(now)
    now = tonumber(now) or os.clock()

    local character =
        LocalPlayer
        and LocalPlayer.Character
        or nil

    if not character
        or not character.Parent
    then
        return false, ""
    end

    local parried =
        character:GetAttribute("Parried") == true
    local stunned =
        character:GetAttribute("Stunned") == true
    local localAttackActive =
        character:GetAttribute("M1") == true
        or character:GetAttribute("M1Hold") == true
        or character:GetAttribute("PendingM1") == true
        or character:GetAttribute("M2") == true
        or character:GetAttribute("PendingM2") == true
        or character:GetAttribute("CombatAttacking") == true

    local localAttackDebug =
        Menu._AutoParryLocalAttackDebug
        or {}
    local lastManualAttackAt =
        tonumber(
            localAttackDebug.lastManualAttackAt
        ) or 0
    local recentManualAttack =
        lastManualAttackAt > 0
        and now - lastManualAttackAt <= 0.95
    local recentScriptedAttack =
        tonumber(
            localAttackDebug.scriptedUntil
        ) or 0
    recentScriptedAttack =
        recentScriptedAttack >= now

    if parried
        or (
            stunned
            and (
                localAttackActive
                or recentManualAttack
                or recentScriptedAttack
                or now
                    <= (
                        tonumber(
                            Menu._ResolverProofRuntime
                                .localPunishContextUntil
                        ) or 0
                    )
            )
        )
    then
        Menu._ResolverProofRuntime.localPunishContextUntil =
            math.max(
                tonumber(
                    Menu._ResolverProofRuntime
                        .localPunishContextUntil
                ) or 0,
                now
                    + Menu._ResolverProofRuntime
                        .INCOMING_PUNISH_CONTEXT_HOLD
            )

        return true,
            parried
                and "local-parried"
                or (
                    localAttackActive
                    and "local-stunned-after-attack"
                    or (
                        recentManualAttack
                        and "local-stunned-after-recent-manual"
                        or (
                            recentScriptedAttack
                            and "local-stunned-after-recent-scripted"
                            or "recent-local-parry"
                        )
                    )
                )
    end

    if now
        <= (
            tonumber(
                Menu._ResolverProofRuntime
                    .localPunishContextUntil
            ) or 0
        )
    then
        return true, "recent-local-parry"
    end

    return false, ""
end

local function getCombatResolverToken(character)
    if not character then
        return nil, nil
    end

    for _, attributeName in ipairs({
        "CombatToken",
        "combatToken",
        "combat_token",
    }) do
        local value = character:GetAttribute(attributeName)
        if value ~= nil then
            return value, attributeName
        end
    end

    local tokenObject = character:FindFirstChild("CombatToken")
    if tokenObject then
        local ok, value = pcall(function()
            return tokenObject.Value
        end)
        if ok and value ~= nil then
            return value, "CombatToken.Value"
        end
    end

    local fallback = character:GetAttribute("CombatActionToken")
    if fallback ~= nil then
        return fallback, "CombatActionToken"
    end

    return nil, nil
end

local function getCombatResolverTokenType(token)
    if typeof(token) ~= "string" then
        return nil
    end

    local value = string.lower(token)
    if string.find(value, "m2", 1, true)
        or string.find(value, "heavy", 1, true) then
        return "M2"
    end

    if string.find(value, "m1", 1, true)
        or string.find(value, "light", 1, true) then
        return "M1"
    end

    return nil
end

local function getReplicatedAttackType(character)
    if not character then
        return nil
    end

    if character:GetAttribute("M2") == true
        or character:GetAttribute("PendingM2") == true then
        return "M2"
    end

    if character:GetAttribute("M1") == true
        or character:GetAttribute("M1Hold") == true
        or character:GetAttribute("PendingM1") == true then
        return "M1"
    end

    return nil
end

local function getResolverCooldownActive(character, attackType)
    if not character then
        return false
    end

    local prefix = attackType == "M2" and "M2" or "M1"
    local cooldown = character:GetAttribute(prefix .. "Cooldown")
    local remaining = character:GetAttribute(prefix .. "CooldownRemaining")

    return cooldown == true
        or (typeof(cooldown) == "number" and cooldown > 0)
        or (typeof(remaining) == "number" and remaining > 0)
end

local function hasResolverSurface(character)
    if not character then
        return false
    end

    if character:FindFirstChild("CombatToken") then
        return true
    end

    local attributes = character:GetAttributes()
    for _, name in ipairs({
        "CombatToken", "combatToken", "combat_token", "CombatActionToken",
        "CombatAttacking", "M1", "M1Hold", "PendingM1",
        "M2", "PendingM2", "M1Cooldown", "M1CooldownRemaining",
        "M2Cooldown", "M2CooldownRemaining",
    }) do
        if attributes[name] ~= nil then
            return true
        end
    end

    return false
end

local function refreshResolverState(character, now)
    if not character then
        return nil
    end

    now = now or os.clock()
    local state = resolverStateByCharacter[character]
    if not state then
        state = {
            initialized = false,
            cooldownActive = {},
            cooldownEdgeAt = {},
        }
        resolverStateByCharacter[character] = state
    end

    local token, tokenSource = getCombatResolverToken(character)
    if not state.initialized then
        state.token = token
        state.tokenSource = tokenSource
        state.tokenType = getCombatResolverTokenType(token)
        state.initialized = true
    elseif state.token ~= token or state.tokenSource ~= tokenSource then
        state.previousToken = state.token
        state.previousTokenSource = state.tokenSource
        state.token = token
        state.tokenSource = tokenSource
        state.tokenType = getCombatResolverTokenType(token)
        state.tokenChangedAt = now

        if state.tokenType == "M1" or state.tokenType == "M2" then
            state.surfaceSerial = (tonumber(state.surfaceSerial) or 0) + 1
            state.surfaceAttackType = state.tokenType
            state.surfaceEdgeAt = now
            state.surfaceProofReason = "combat-token-type"
        end
    else
        state.tokenType = getCombatResolverTokenType(token)
    end

    local replicatedType = getReplicatedAttackType(character)
    if replicatedType ~= state.replicatedType then
        state.previousReplicatedType = state.replicatedType
        state.replicatedType = replicatedType
        if replicatedType then
            state.replicatedEdgeAt = now
            state.replicatedSerial = (tonumber(state.replicatedSerial) or 0) + 1
            state.surfaceSerial = (tonumber(state.surfaceSerial) or 0) + 1
            state.surfaceAttackType = replicatedType
            state.surfaceEdgeAt = now
            state.surfaceProofReason = "replicated-" .. replicatedType
        end
    end
    if replicatedType then
        state.lastReplicatedType = replicatedType
        state.lastReplicatedAt = now
    end

    for _, attackType in ipairs({"M1", "M2"}) do
        local active = getResolverCooldownActive(character, attackType)
        local wasActive = state.cooldownActive[attackType] == true
        if active and not wasActive then
            state.cooldownEdgeAt[attackType] = now
        end
        state.cooldownActive[attackType] = active
    end

    state.surfaceAvailable = hasResolverSurface(character)
    return state
end

Menu._APBreakerResolver = Menu._APBreakerResolver or {}
Menu._APBreakerResolver.tuning = Menu._APBreakerResolver.tuning or {
    startWindow = 1.25,
    fakeWindow = 1.20,
    restartMax = 0.36,
    activeHold = 3.00,
    proofPrepad = 0.065,
    proofPostpad = 0.22,
    earlyRejectGrace = 0.060,
    timelineDrift = 0.045,
}

Menu._APBreakerResolver.isActive = function(character, now)
    local state = character and resolverStateByCharacter[character]
    return state ~= nil
        and (tonumber(state.breakerActiveUntil) or 0) > (now or os.clock())
end

Menu._APBreakerResolver.activate = function(character, now, reason, fields)
    local state = refreshResolverState(character, now)
    if not state then
        return
    end

    local wasActive = (tonumber(state.breakerActiveUntil) or 0) > now
    state.breakerObserved = true
    state.breakerReason = tostring(reason or "pattern")
    state.breakerActiveUntil = math.max(
        tonumber(state.breakerActiveUntil) or 0,
        now + Menu._APBreakerResolver.tuning.activeHold
    )

    if not wasActive then
        local payload = fields or {}
        payload.owner = character.Name
        payload.reason = state.breakerReason
        debugLog("AP_BREAKER_DETECTED", payload, true)
    end
end

Menu._APBreakerResolver.noteAnimationStart = function(
    character,
    animationId,
    attackType,
    combo,
    visualSpeed,
    now
)
    local state = refreshResolverState(character, now)
    if not state then
        return
    end

    state.breakerStarts = state.breakerStarts or {}
    local key = tostring(animationId or "")
        .. "|" .. tostring(attackType or "")
        .. "|" .. tostring(combo or 0)
    local starts = state.breakerStarts[key] or {}
    state.breakerStarts[key] = starts

    local cutoff = now - Menu._APBreakerResolver.tuning.startWindow
    local write = 1
    for i = 1, #starts do
        local sample = starts[i]
        if sample and (tonumber(sample.at) or 0) >= cutoff then
            starts[write] = sample
            write += 1
        end
    end
    for i = #starts, write, -1 do
        starts[i] = nil
    end

    starts[#starts + 1] = {
        at = now,
        speed = tonumber(visualSpeed) or 1,
    }

    if #starts < 4 then
        return
    end

    local minSpeed = math.huge
    local maxSpeed = -math.huge
    local fastRestarts = 0
    for i, sample in ipairs(starts) do
        local speed = tonumber(sample.speed) or 1
        minSpeed = math.min(minSpeed, speed)
        maxSpeed = math.max(maxSpeed, speed)
        if i > 1 then
            local gap = (tonumber(sample.at) or now)
                - (tonumber(starts[i - 1].at) or now)
            if gap <= Menu._APBreakerResolver.tuning.restartMax then
                fastRestarts += 1
            end
        end
    end

    local speedSpan = maxSpeed - minSpeed
    if fastRestarts >= 3
        and (speedSpan >= 0.10 or #starts >= 5)
    then
        Menu._APBreakerResolver.activate(character, now, "bait-restart-pattern", {
            animationId = animationId or "",
            attack = attackType or "",
            combo = combo or 0,
            starts = #starts,
            fastRestarts = fastRestarts,
            speedMin = minSpeed,
            speedMax = maxSpeed,
        })
    end
end

Menu._APBreakerResolver.noteFake = function(threat, now, reason)
    local character = threat and threat.owner
    local state = refreshResolverState(character, now)
    if not state then
        return
    end

    state.breakerFakeTimes = state.breakerFakeTimes or {}
    local cutoff = now - Menu._APBreakerResolver.tuning.fakeWindow
    local write = 1
    for i = 1, #state.breakerFakeTimes do
        local at = tonumber(state.breakerFakeTimes[i]) or 0
        if at >= cutoff then
            state.breakerFakeTimes[write] = at
            write += 1
        end
    end
    for i = #state.breakerFakeTimes, write, -1 do
        state.breakerFakeTimes[i] = nil
    end
    state.breakerFakeTimes[#state.breakerFakeTimes + 1] = now
    state.breakerBaitCount = (tonumber(state.breakerBaitCount) or 0) + 1

    if #state.breakerFakeTimes >= 3 then
        Menu._APBreakerResolver.activate(character, now, "fake-animation-burst", {
            attack = threat.attackType or "",
            animationId = threat.animationId or "",
            animationName = threat.animationName or "",
            fakeCount = #state.breakerFakeTimes,
            proofReject = tostring(reason or ""),
        })
    end
end

function Menu._ResolverProofRuntime.getAnimationProofPostpad(attackType, kind)
    if kind == "replicated" then
        return attackType == "M2"
            and Menu._ResolverProofRuntime.ANIM_REPLICATED_POSTPAD_M2
            or Menu._ResolverProofRuntime.ANIM_REPLICATED_POSTPAD_M1
    elseif kind == "cooldown" then
        return attackType == "M2"
            and Menu._ResolverProofRuntime.ANIM_COOLDOWN_POSTPAD_M2
            or Menu._ResolverProofRuntime.ANIM_COOLDOWN_POSTPAD_M1
    end

    return attackType == "M2"
        and Menu._ResolverProofRuntime.ANIM_TOKEN_POSTPAD_M2
        or Menu._ResolverProofRuntime.ANIM_TOKEN_POSTPAD_M1
end

function Menu._ResolverProofRuntime.getAnimationProofOwner(
    threat,
    proofAt,
    postpad
)
    if not threat
        or typeof(proofAt) ~= "number"
    then
        return nil, "missing-proof-time", nil
    end

    local createdAt =
        tonumber(threat.createdAt)
        or proofAt
    local delta =
        proofAt - createdAt

    if delta < -Menu._ResolverProofRuntime.ANIM_PROOF_PREPAD
        or delta > postpad
    then
        return nil, "proof-outside-animation-window", delta
    end

    local bestThreat = threat
    local bestDistance = math.abs(delta)
    local bestCreatedAt = createdAt

    for _, candidate in pairs(animationThreats) do
        if candidate
            and candidate ~= threat
            and candidate.expired ~= true
            and candidate.source == "animation"
            and candidate.owner == threat.owner
            and candidate.attackType == threat.attackType
        then
            local candidateCreatedAt =
                tonumber(candidate.createdAt)

            if candidateCreatedAt then
                local candidateDelta =
                    proofAt - candidateCreatedAt

                if candidateDelta
                        >= -Menu._ResolverProofRuntime.ANIM_PROOF_PREPAD
                    and candidateDelta
                        <= postpad
                then
                    local distance =
                        math.abs(candidateDelta)

                    if distance + 0.006
                            < bestDistance
                        or (
                            math.abs(
                                distance
                                - bestDistance
                            ) <= 0.006
                            and candidateCreatedAt
                                > bestCreatedAt
                        )
                    then
                        bestThreat = candidate
                        bestDistance = distance
                        bestCreatedAt =
                            candidateCreatedAt
                    end
                end
            end
        end
    end

    if bestThreat ~= threat then
        return bestThreat,
            "proof-owned-by-nearer-animation",
            delta
    end

    return threat, nil, delta
end

function Menu._ResolverProofRuntime.logAnimationProofReject(
    threat,
    now,
    reason,
    proofAt,
    evidence
)
    if not threat then
        return
    end

    local signature =
        tostring(reason or "")
        .. "|"
        .. tostring(evidence or "")

    if threat.resolverProofRejectSignature
            == signature
        and now
            - (
                tonumber(
                    threat.resolverProofRejectLoggedAt
                ) or 0
            )
            < 0.18
    then
        return
    end

    threat.resolverProofRejectSignature =
        signature
    threat.resolverProofRejectLoggedAt =
        now

    debugLog(
        "AP_RESOLVER_PROOF_REJECT",
        {
            attack =
                threat.attackType or "",
            owner =
                threat.ownerName or "",
            style =
                threat.style or "",
            combo =
                threat.combo or 0,
            animationName =
                threat.animationName or "",
            animationId =
                threat.animationId or "",
            evidence =
                evidence or "",
            reason =
                reason or "",
            proofDelta =
                typeof(proofAt) == "number"
                and (
                    proofAt
                    - (
                        tonumber(
                            threat.createdAt
                        ) or proofAt
                    )
                )
                or "",
            age =
                now
                - (
                    tonumber(
                        threat.createdAt
                    ) or now
                ),
        },
        true
    )
end

function Menu._ResolverProofRuntime.acceptAnimationResolverProof(
    threat,
    now,
    reason,
    proofAt,
    strength,
    kind
)
    local postpad =
        Menu._ResolverProofRuntime.getAnimationProofPostpad(
            threat.attackType,
            kind
        )
    local proofOwner,
        rejectReason,
        proofDelta =
            Menu._ResolverProofRuntime.getAnimationProofOwner(
                threat,
                proofAt,
                postpad
            )

    if proofOwner ~= threat then
        local boundAt =
            tonumber(
                threat.resolverProofBoundAt
            )

        if boundAt
            and typeof(proofAt) == "number"
            and math.abs(
                boundAt - proofAt
            ) <= 0.0005
        then
            threat.resolverProofStrength = nil
            threat.resolverProofBoundAt = nil
            threat.resolverProofDelta = nil
        end

        Menu._ResolverProofRuntime.logAnimationProofReject(
            threat,
            now,
            rejectReason
                or "proof-not-owned",
            proofAt,
            reason
        )
        return false,
            rejectReason
                or "proof-not-owned",
            proofAt
    end

    threat.resolverProofStrength =
        strength or "strong"
    threat.resolverProofDelta =
        proofDelta
    threat.resolverProofBoundAt =
        proofAt

    return true,
        reason,
        proofAt
end

local function getAnimationResolverProof(threat, now)
    if threat.serverConfirmed == true then
        threat.resolverProofStrength = "server"
        threat.resolverProofDelta = 0
        return true, "server-hitbox", now
    end

    if threat.style == "hakari"
        and threat.source == "animation"
        and threat.track
        and threat.track.IsPlaying ~= false
        and (
            threat.attackType == "M1"
            or threat.attackType == "M2"
        )
    then
        threat.resolverProofStrength = "style-verified"
        threat.resolverProofDelta = 0
        return true, "hakari-combat-animation", threat.createdAt
    end

    local character = threat.owner
    if not character or not character.Parent then
        return false, "owner-missing", nil
    end

    local state = refreshResolverState(character, now)
    if not state then
        return false, "state-missing", nil
    end

    local attackType = threat.attackType
    local breakerActive =
        Menu._APBreakerResolver.isActive(
            character,
            now
        )

    -- Strong action-sequence evidence wins over replicated M1/M2 state.
    -- This lets a genuinely desynced/short real swing survive while a fake
    -- visual track that only inherited stale M1 state is discarded.
    local tokenChangedAt =
        tonumber(state.tokenChangedAt)
    local tokenRecent =
        tokenChangedAt
        and now - tokenChangedAt
            <= RESOLVER_TOKEN_PROOF_WINDOW

    if tokenRecent then
        local tokenType =
            state.tokenType

        if tokenType == attackType then
            local okProof,
                reason,
                proofAt =
                    Menu._ResolverProofRuntime.acceptAnimationResolverProof(
                        threat,
                        now,
                        "combat-token-type",
                        tokenChangedAt,
                        "strong",
                        "token"
                    )

            if okProof then
                return okProof,
                    reason,
                    proofAt
            end
        elseif tokenType == nil then
            local okProof,
                reason,
                proofAt =
                    Menu._ResolverProofRuntime.acceptAnimationResolverProof(
                        threat,
                        now,
                        "combat-token-edge",
                        tokenChangedAt,
                        "strong",
                        "token"
                    )

            if okProof then
                return okProof,
                    reason,
                    proofAt
            end
        else
            Menu._ResolverProofRuntime.logAnimationProofReject(
                threat,
                now,
                "token-type-mismatch",
                tokenChangedAt,
                "combat-token-edge"
            )
        end
    end

    local cooldownEdgeAt =
        state.cooldownEdgeAt
        and tonumber(
            state.cooldownEdgeAt[
                attackType
            ]
        )
        or nil

    if cooldownEdgeAt
        and now - cooldownEdgeAt
            <= RESOLVER_COOLDOWN_PROOF_WINDOW
    then
        local okProof,
            reason,
            proofAt =
                Menu._ResolverProofRuntime.acceptAnimationResolverProof(
                    threat,
                    now,
                    string.lower(attackType)
                        .. "-cooldown-edge",
                    cooldownEdgeAt,
                    "strong",
                    "cooldown"
                )

        if okProof then
            return okProof,
                reason,
                proofAt
        end
    end

    -- Replicated M1/M2 state is deliberately weaker.  It is accepted only
    -- when the edge is close enough to this exact animation and this threat
    -- is the nearest animation to that edge.
    local replicatedType =
        getReplicatedAttackType(character)
    local replicatedEdgeAt =
        tonumber(state.replicatedEdgeAt)

    if replicatedType == attackType
        and replicatedEdgeAt
    then
        local okProof,
            reason,
            proofAt =
                Menu._ResolverProofRuntime.acceptAnimationResolverProof(
                    threat,
                    now,
                    "replicated-" .. attackType,
                    replicatedEdgeAt,
                    "weak",
                    "replicated"
                )

        if okProof then
            if breakerActive then
                Menu._ResolverProofRuntime.logAnimationProofReject(
                    threat,
                    now,
                    "breaker-requires-strong-proof",
                    proofAt,
                    reason
                )
            else
                return okProof,
                    reason,
                    proofAt
            end
        end
    end


    if state.surfaceAvailable ~= true then
        threat.resolverProofStrength =
            "resolver-unavailable"
        threat.resolverProofDelta = 0
        return true,
            "resolver-unavailable",
            threat.createdAt
    end

    -- While a breaker/fake-animation pattern is active, an unbound animation
    -- is immediately treated as a decoy.  Outside breaker mode it remains
    -- pending until its parry deadline so late legitimate replication can
    -- still rescue it.
    if breakerActive then
        return false,
            "ap-breaker-decoy",
            nil
    end

    return false,
        "no-replicated-proof",
        nil
end

local lastParryAt = 0
local autoBlocking = false
local autoBlockSerial = 0
local KYOKUSHIN_M2_SERVER_WINDOW_LEAD = -0.015
local KYOKUSHIN_M2_STOPPED_TRACK_CONTACT_GRACE = 0.260
local KYOKUSHIN_M2_STOPPED_TRACK_EARLY_FIRE_LEAD = 0.155
local KYOKUSHIN_M2_ATTACK_PREEMPT_WINDOW = 0.240
local KYOKUSHIN_M2_AUTOFACE_PREARM = 0.550
local KYOKUSHIN_M2_GUARD_HOLD = 0.420

local KYOKUSHIN_M2_40MS_PING_MIN = 0.035
local KYOKUSHIN_M2_40MS_PING_MAX = 0.055
local KYOKUSHIN_M2_40MS_SERVER_WINDOW_LEAD = -0.022
local KYOKUSHIN_M2_40MS_STOPPED_TRACK_EARLY_FIRE_LEAD = 0.145
local KYOKUSHIN_M2_40MS_ATTACK_PREEMPT_WINDOW = 0.260
local KYOKUSHIN_M2_40MS_AUTOFACE_PREARM = 0.580
local KYOKUSHIN_M2_40MS_GUARD_HOLD = 0.440

local function getKyokushinM2NetworkProfile(ping)
    local measuredPing = tonumber(ping) or 0
    if measuredPing >= KYOKUSHIN_M2_40MS_PING_MIN
        and measuredPing <= KYOKUSHIN_M2_40MS_PING_MAX
    then
        return
            KYOKUSHIN_M2_40MS_SERVER_WINDOW_LEAD,
            KYOKUSHIN_M2_40MS_STOPPED_TRACK_EARLY_FIRE_LEAD,
            KYOKUSHIN_M2_40MS_ATTACK_PREEMPT_WINDOW,
            KYOKUSHIN_M2_40MS_AUTOFACE_PREARM,
            KYOKUSHIN_M2_40MS_GUARD_HOLD,
            "40ms"
    end

    return
        KYOKUSHIN_M2_SERVER_WINDOW_LEAD,
        KYOKUSHIN_M2_STOPPED_TRACK_EARLY_FIRE_LEAD,
        KYOKUSHIN_M2_ATTACK_PREEMPT_WINDOW,
        KYOKUSHIN_M2_AUTOFACE_PREARM,
        KYOKUSHIN_M2_GUARD_HOLD,
        "default"
end

local AP_SERVER_REPLICATION_LATE_GRACE = 0.110
-- Hakari can stop its visible combat track far before the replicated hitbox arrives.
-- Keep a verified stopped track alive through its already-predicted contact instead of
-- discarding the animation threat and reacting late to the server hitbox.
Menu._APHakariStopTuning = Menu._APHakariStopTuning or {
    contactGrace = 0.240,
    minRemaining = 0.045,
    maxRemaining = 0.580,
    extraLead = 0.012,
    rangePad = 1.35,
}
Menu._apBlockActive = false
Menu._apRecentParryCoverage = Menu._apRecentParryCoverage or {}

local function getTimingBiasKey(threat)
    local style = tostring(threat.style or "default")
    local attackType = tostring(threat.attackType or "")
    local key = style .. "|" .. attackType





    if style == "hakari"
        or style == "muaythai"
        or style == "karate"
        or style == "ali"
    then
        key = key
            .. "|o"
            .. tostring(
                threat.ownerName
                    or (threat.owner and threat.owner.Name)
                    or "unknown"
            )
    end





    if attackType == "M1" then
        local comboSpecific = false
        pcall(function()
            local styleConfig = CombatConfig.GetStyleConfig(style)
            comboSpecific = (
                styleConfig
                and typeof(styleConfig.M1HitboxDelayOffsets) == "table"
            )
                or style == "muaythai"
                or style == "hakari"
                or style == "karate"
                or style == "kickboxing"
                or style == "ali"
        end)

        if comboSpecific then
            key = key
                .. "|c"
                .. tostring(math.clamp(tonumber(threat.combo) or 1, 1, 4))
        end
    end

    if attackType == "M2" and style == "ali" then
        key = key .. "|v" .. tostring(threat.variant or "Left")
    elseif attackType == "M2" and style == "hakari" then
        key = key .. "|" .. (threat.hakariMomentum == true and "momentum" or "normal")
    end

    return key
end

function Menu._ResolverTimingRuntime.getOwnerBiasKey(threat)
    local ownerName =
        tostring(
            threat
            and (
                threat.ownerName
                or (
                    threat.owner
                    and threat.owner.Name
                )
            )
            or "unknown"
        )

    local sourceSuffix = ""
    if threat and threat.source == "resolver_surface" then
        sourceSuffix = "|surface"
    end

    return ownerName
        .. "@"
        .. getTimingBiasKey(threat)
        .. sourceSuffix
end

function Menu._ResolverTimingRuntime.getBias(threat)
    local learned =
        tonumber(
            timingBias[
                Menu._ResolverTimingRuntime.getOwnerBiasKey(threat)
            ]
        ) or 0

    if threat.attackType == "M2" and threat.style == "boxing" then
        return 0.145 + learned
    end

    return learned
end

function Menu._ResolverTimingRuntime.recordResidual(
    threat,
    residual,
    now
)
    if not threat
        or (
            threat.source ~= "animation"
            and threat.source ~= "resolver_surface"
        )
    then
        return
    end

    residual = tonumber(residual)
    if residual == nil
        or math.abs(residual) > 0.45
    then
        return
    end

    local key =
        Menu._ResolverTimingRuntime.getOwnerBiasKey(threat)
    local previous =
        tonumber(timingBias[key]) or 0
    local samples =
        tonumber(
            Menu._ResolverTimingRuntime.biasSamples[
                key
            ]
        ) or 0
    local alpha =
        samples < 2
        and 0.50
        or (
            samples < 5
            and 0.34
            or 0.22
        )

    -- Do not let one replicated-edge outlier yank a mature timing model.
    -- Animation and resolver-surface models are keyed independently.
    local adaptiveResidual =
        math.clamp(
            residual,
            -0.18,
            0.18
        )
    local learned =
        math.clamp(
            previous
                + adaptiveResidual * alpha,
            -0.35,
            0.35
        )

    timingBias[key] = learned
    Menu._ResolverTimingRuntime.biasSamples[
        key
    ] = samples + 1

    local state =
        threat.owner
        and refreshResolverState(
            threat.owner,
            now or os.clock()
        )
        or nil

    if state then
        state.resolverTimingSamples =
            (
                tonumber(
                    state.resolverTimingSamples
                ) or 0
            ) + 1
        state.resolverTimingBias =
            learned
        state.resolverTimingLastResidual =
            residual
        state.resolverTimingLastSource =
            threat.source

        if samples + 1 >= 2
            and (
                math.abs(learned) >= 0.040
                or math.abs(residual) >= 0.075
            )
        then
            state.resolverTimingObserved =
                true
            state.resolverTimingActiveUntil =
                math.max(
                    tonumber(
                        state.resolverTimingActiveUntil
                    ) or 0,
                    (now or os.clock())
                        + 8
                )
        end
    end

    debugLog(
        "AP_RESOLVER_TIMING_LEARN",
        {
            attack =
                threat.attackType or "",
            owner =
                threat.ownerName or "",
            style =
                threat.style or "",
            combo =
                threat.combo or 0,
            residual =
                residual,
            learned =
                learned,
            samples =
                samples + 1,
            source =
                threat.source or "",
        },
        true
    )
end


local function releaseAutoBlock(serial)
    if serial ~= autoBlockSerial or not autoBlocking then
        return
    end

    autoBlocking = false
    Menu._apBlockActive = false
    if type(Menu._apCurrentBlock) == "table"
        and tonumber(Menu._apCurrentBlock.serial) == tonumber(serial)
    then
        Menu._apCurrentBlock = nil
    end

    local character = getCharacter()
    local blockModule = getCombatModule("Block")

    if character
        and character:GetAttribute("Blocking") == true
        and blockModule
        and type(blockModule.Unblock) == "function"
    then
        pcall(blockModule.Unblock)
    end

    local releasedAt = os.clock()
    for _, coverage in pairs(Menu._apRecentParryCoverage) do
        if type(coverage) == "table" and coverage.serial == serial then
            coverage.releasedAt = releasedAt
        end
    end

    debugLog("UNBLOCK", {
        serial = serial,
    })
end

local function extendAutoBlockHold(duration, reason, ownerName)
    if not autoBlocking then
        return false
    end

    local previousSerial = autoBlockSerial
    autoBlockSerial += 1
    local serial = autoBlockSerial
    for _, coverage in pairs(Menu._apRecentParryCoverage) do
        if type(coverage) == "table"
            and coverage.serial == previousSerial
        then
            coverage.serial = serial
        end
    end
    local hold = math.clamp(tonumber(duration) or 0.20, 0.05, 0.75)
    task.delay(hold, function()
        releaseAutoBlock(serial)
    end)

    debugLog("AUTO_BLOCK_EXTEND", {
        owner = ownerName or "",
        reason = reason or "",
        holdMs = math.floor(hold * 1000 + 0.5),
        serial = serial,
    }, true)
    return true
end

Menu._releaseAutoBlockForDodge = function()
    if not autoBlocking then
        Menu._apBlockActive = false
        return false
    end

    local serial = autoBlockSerial
    releaseAutoBlock(serial)
    return autoBlocking ~= true
end

local REAR_PARRY_FACE_MAX_TURN_DEGREES = 240
local REAR_PARRY_FACE_DODGE_ONLY_ANGLE = 118
local REAR_PARRY_FACE_MAX_SPEED = 900
local REAR_PARRY_FACE_ACCEL = 9000
local REAR_PARRY_FACE_STOP_EPSILON = 1.5
local AUTOFACE_PARRY_PREARM = 0.40

-- These must live in the same scope as prepareAutoFaceForParry().
-- R14 accidentally referenced the similarly named locals from the earlier
-- AutoFace runtime block, which are out of scope here.
local AUTOFACE_PARRY_M1_CURRENT_CAP = 10.75
local AUTOFACE_PARRY_M2_CURRENT_CAP = 11.75
local AUTOFACE_PARRY_MATURE_MISS_DISTANCE = 6.75

local function stopBehindParryFacing()
end

local function releaseBehindParryFacingForThreat()
end

local function prepareAutoFaceForParry(threat, context, forceReady)
    if Flags.ap_enable ~= true
        or Flags.ap_auto_face ~= true
        or not threat
        or not threat.owner
        or not threat.owner.Parent
    then
        return false
    end

    local runtime = Menu and Menu._AutoFaceRuntime
    if not runtime then
        return false
    end

    local character = context and context.character
    local root = context and context.myRoot
    if not character or not character.Parent
        or not root or not root.Parent
        or character:GetAttribute("Equip") ~= true
    then
        return false
    end

    local nowFace = os.clock()
    local contactAbs = tonumber(threat.expectedContactAbs)
    local impactEta = contactAbs
        and math.max(0, contactAbs - nowFace)
        or nil

    local liveHitbox = threat.hitbox
    if liveHitbox
        and liveHitbox.Parent
        and liveHitbox:IsA("BasePart")
    then
        local localPoint =
            liveHitbox.CFrame:PointToObjectSpace(root.Position)
        local rootRadius =
            math.max(root.Size.X, root.Size.Z) * 0.5
        local rootHalfY =
            root.Size.Y * 0.5
        local cushion =
            0.70
        local touching =
            math.abs(localPoint.X)
                    <= liveHitbox.Size.X * 0.5
                        + rootRadius
                        + cushion
                and math.abs(localPoint.Z)
                    <= liveHitbox.Size.Z * 0.5
                        + rootRadius
                        + cushion
                and math.abs(localPoint.Y)
                    <= liveHitbox.Size.Y * 0.5
                        + rootHalfY
                        + cushion

        if not touching then
            return false
        end
    end

    if forceReady == true then
        local forceDistance =
            tonumber(
                context and context.distance
            )

        if not forceDistance then
            local ownerRoot =
                getRoot(threat.owner)

            if ownerRoot
                and ownerRoot.Parent
                and root
                and root.Parent
            then
                forceDistance =
                    (
                        ownerRoot.Position
                        - root.Position
                    ).Magnitude
            end
        end

        forceDistance =
            tonumber(forceDistance)
            or math.huge

        local forceCurrentCap =
            threat.attackType == "M2"
            and AUTOFACE_PARRY_M2_CURRENT_CAP
            or AUTOFACE_PARRY_M1_CURRENT_CAP

        if forceDistance > forceCurrentCap then
            return false
        end

        if forceDistance
            >= AUTOFACE_PARRY_MATURE_MISS_DISTANCE
            and type(
                runtime.isThreatPathVerified
            ) == "function"
        then
            local ok,
                verified =
                    pcall(
                        runtime.isThreatPathVerified,
                        threat
                    )

            if not ok
                or verified ~= true
            then
                return false
            end
        end

        local claimed = false
        if type(runtime.lockTarget) == "function" then
            local lockDuration = math.clamp(
                (tonumber(impactEta) or 0.08) + 0.14,
                0.18,
                0.34
            )
            pcall(function()
                claimed = runtime.lockTarget(
                    threat.owner,
                    lockDuration,
                    "parry-defense-fire",
                    {
                        forceReplace = true,
                        snapNow = false,
                        impactEta = impactEta,
                    }
                ) == true
            end)
        end

        if type(runtime.faceNow) == "function" then
            pcall(runtime.faceNow, threat.owner)
        end

        return claimed
    end

    if type(runtime.setDefenseHint) ~= "function" then
        return false
    end

    local verified = false
    if type(runtime.isThreatPathVerified) == "function" then
        local ok, willHit =
            pcall(
                runtime.isThreatPathVerified,
                threat
            )
        verified =
            ok
            and willHit == true
    end

    if not verified then
        return false
    end

    local hintDuration = math.clamp(
        (tonumber(impactEta) or 0.22) + 0.055,
        0.12,
        0.36
    )
    local hinted = false
    pcall(function()
        hinted = runtime.setDefenseHint(
            threat.owner,
            hintDuration,
            impactEta
        ) == true
    end)
    return hinted
end

local function estimateRearParryTurnTime(angleDegrees)
    local angle = math.clamp(
        tonumber(angleDegrees) or 0,
        0,
        REAR_PARRY_FACE_MAX_TURN_DEGREES
    )

    if angle <= REAR_PARRY_FACE_STOP_EPSILON then
        return 0
    end

    local accel = REAR_PARRY_FACE_ACCEL
    local maxSpeed = REAR_PARRY_FACE_MAX_SPEED
    local accelDistance = (maxSpeed * maxSpeed) / (2 * accel)


    if angle <= accelDistance * 2 then
        return 2 * math.sqrt(angle / accel)
    end


    local accelTime = maxSpeed / accel
    local cruiseDistance = angle - accelDistance * 2

    return accelTime * 2 + cruiseDistance / maxSpeed
end

local function getRearDodgeEmergency(
    threat,
    prediction,
    context,
    now
)
    if Flags.dodge_enable ~= true
        or Flags.dodge_if_cant_parry ~= true
        or not threat
        or threat.mustDodgeSelected == true
        or (
            threat.attackType ~= "M1"
            and threat.attackType ~= "M2"
        )
        or (
            threat.counterStance == true
            and threat.serverConfirmed ~= true
        )
    then
        if threat then
            threat.dodgeRearEmergency = false
            threat.dodgeRearDodgeOnly = false
        end
        return false
    end

    threat.dodgeRearDodgeOnly = false

    local root = context and context.myRoot
    local ownerRoot = context and context.ownerRoot

    if not root or not root.Parent or not ownerRoot or not ownerRoot.Parent then
        threat.dodgeRearEmergency = false
        return false
    end

    local toThreat = flat(ownerRoot.Position - root.Position)
    local look = flat(root.CFrame.LookVector)

    if toThreat.Magnitude <= 0.05 or look.Magnitude <= 0.0001 then
        threat.dodgeRearEmergency = false
        return false
    end

    local dot = math.clamp(
        look.Unit:Dot(toThreat.Unit),
        -1,
        1
    )


    if dot >= 0 then
        threat.dodgeRearEmergency = false
        return false
    end

    local angle = math.deg(math.acos(dot))
    if angle <= 90 then
        threat.dodgeRearEmergency = false
        return false
    end

    now = now or os.clock()

    local pressAtQ = tonumber(prediction and prediction.pressAtQ) or now
    local contactAbs = tonumber(prediction and prediction.contactAbs) or now
    local parryIn = pressAtQ - now
    local contactIn = contactAbs - now



    local dodgeOnlyRear =
        angle >= REAR_PARRY_FACE_DODGE_ONLY_ANGLE

    if not dodgeOnlyRear then
        threat.dodgeRearEmergency = false
        threat.dodgeRearDodgeOnly = false
        threat.dodgeRearReason = nil
        return false
    end

    if contactIn > 0.56 then
        threat.dodgeRearEmergency = false
        threat.dodgeRearDodgeOnly = false
        threat.dodgeRearReason = nil
        return false
    end

    local turnTime = estimateRearParryTurnTime(angle)

    threat.dodgeRearEmergency = true
    threat.dodgeRearDodgeOnly = true
    threat.dodgeRearReason = "rear_dodge_only"
    threat.dodgeRearAngle = angle
    threat.dodgeRearTurnTime = turnTime
    threat.dodgeRearParryIn = parryIn
    threat.dodgeRearContactIn = contactIn

    if threat.dodgeRearEmergencyLogged ~= true then
        threat.dodgeRearEmergencyLogged = true
        debugLog("DODGE_REAR_EMERGENCY", {
            attack = threat.attackType or "",
            owner = threat.ownerName or "",
            style = threat.style or "",
            source = threat.source or "",
            reason = threat.dodgeRearReason,
            angle = angle,
            turnTimeMs = math.floor(turnTime * 1000 + 0.5),
            parryInMs = math.floor(parryIn * 1000 + 0.5),
            contactInMs = math.floor(contactIn * 1000 + 0.5),
            dodgeOnly = dodgeOnlyRear,
            autoRearMaxAngle = REAR_PARRY_FACE_DODGE_ONLY_ANGLE,
        }, true)
    end

    return true
end

local function tryRearEmergencyDodge(
    threat,
    prediction,
    context,
    now
)
    if threat
        and threat.style == "cqc"
        and threat.attackType == "M1"
        and (tonumber(threat.cqcInitialFacingDot) or -1) >= 0.22
        and (tonumber(context and context.distance) or math.huge) <= 12.25
        and threat.track
        and threat.track.IsPlaying ~= false
    then
        local hitTL = tonumber(threat.hitTL) or 0.40
        local trackTime = tonumber(threat.track.TimePosition) or 0
        if trackTime <= hitTL + 0.12 then
            return false, false
        end
    end

    if not getRearDodgeEmergency(
        threat,
        prediction,
        context,
        now
    ) then
        return false, false
    end

    local runtime = Menu._DodgeRuntime
    if not runtime or type(runtime.try) ~= "function" then
        if threat.dodgeRearDodgeOnly == true then
            threat.dodgeRearReclaimedByParry = true

            if threat.dodgeRearReclaimLogged ~= true then
                threat.dodgeRearReclaimLogged = true
                debugLog("DODGE_REAR_RECLAIM", {
                    attack = threat.attackType or "",
                    owner = threat.ownerName or "",
                    style = threat.style or "",
                    source = threat.source or "",
                    reason = "runtime_unavailable",
                    angle = threat.dodgeRearAngle or "",
                    parryIn = threat.dodgeRearParryIn or "",
                    contactIn = threat.dodgeRearContactIn or "",
                    policy = "AP_EMERGENCY_FALLBACK",
                }, true)
            end
        end

        return false, false
    end

    local ok, committed = pcall(
        runtime.try,
        threat,
        prediction,
        context,
        now
    )

    if not ok then
        debugLog("DODGE_RUNTIME_ERROR", {
            attack = threat.attackType or "",
            owner = threat.ownerName or "",
            style = threat.style or "",
            source = threat.source or "",
            error = tostring(committed),
            rearEmergency = true,
        }, true)

        if threat.dodgeRearDodgeOnly == true then
            threat.dodgeRearReclaimedByParry = true

            if threat.dodgeRearReclaimLogged ~= true then
                threat.dodgeRearReclaimLogged = true
                debugLog("DODGE_REAR_RECLAIM", {
                    attack = threat.attackType or "",
                    owner = threat.ownerName or "",
                    style = threat.style or "",
                    source = threat.source or "",
                    reason = "runtime_error",
                    angle = threat.dodgeRearAngle or "",
                    parryIn = threat.dodgeRearParryIn or "",
                    contactIn = threat.dodgeRearContactIn or "",
                    policy = "AP_EMERGENCY_FALLBACK",
                }, true)
            end
        end

        return false, false
    end

    if committed == true or threat.dodgeCommitted == true then
        threat.dodgeRearReclaimedByParry = false
        return true, true
    end

    local dodgeOwnsThreat =
        threat.dodgeTaskArmed == true
        or threat.dodgeAttemptPending == true
        or threat.dodgeDispatching == true

    if dodgeOwnsThreat then
        threat.dodgeRearReclaimedByParry = false
    elseif threat.dodgeRearDodgeOnly == true then
        threat.dodgeRearReclaimedByParry = true

        if threat.dodgeRearReclaimLogged ~= true then
            threat.dodgeRearReclaimLogged = true
            debugLog("DODGE_REAR_RECLAIM", {
                attack = threat.attackType or "",
                owner = threat.ownerName or "",
                style = threat.style or "",
                source = threat.source or "",
                reason = threat.dodgeGateReason or "not_armed",
                angle = threat.dodgeRearAngle or "",
                parryIn = threat.dodgeRearParryIn or "",
                contactIn = threat.dodgeRearContactIn or "",
                dodgeFireIn =
                    tonumber(threat.dodgeFireAt)
                    and (tonumber(threat.dodgeFireAt) - now)
                    or "",
                policy = "AP_EMERGENCY_FALLBACK",
            }, true)
        end
    end

    if dodgeOwnsThreat
        and threat.dodgeRearParallelLogged ~= true
    then
        threat.dodgeRearParallelLogged = true
        debugLog("DODGE_REAR_PRIORITY", {
            attack = threat.attackType or "",
            owner = threat.ownerName or "",
            style = threat.style or "",
            source = threat.source or "",
            reason = threat.dodgeRearReason or "",
            angle = threat.dodgeRearAngle or "",
            policy = "DODGE_ARMED_HOLD",
        }, true)
    end

    if dodgeOwnsThreat then
        return true, false
    end

    return false, false
end

local function performParry(threat, prediction, context)
    local now = os.clock()

    if threat.fired or threat.expired then
        return false
    end

    local parryOwner = threat.owner
    if not parryOwner and threat.hitbox then
        parryOwner = resolveOwner(threat)
    end
    if parryOwner
        and Menu._IsFriendlyCharacter
        and Menu._IsFriendlyCharacter(parryOwner)
    then
        return false
    end

    if Menu._AliCounterRuntime
        and type(
            Menu._AliCounterRuntime.isEvasiveEnabled
        ) == "function"
        and Menu._AliCounterRuntime.isEvasiveEnabled()
        and (
            threat.aliCounterPending == true
            or threat.aliCounterCommitted == true
            or (
                threat.aliCounterAttempted == true
                and now
                    <= (
                        tonumber(
                            threat.aliCounterPendingUntil
                        ) or 0
                    )
            )
        )
    then
        if threat.aliParrySuppressedLogged ~= true then
            threat.aliParrySuppressedLogged =
                true

            debugLog(
                "ALI_COUNTER_PARRY_SUPPRESS",
                {
                    attack =
                        threat.attackType
                        or "",
                    owner =
                        threat.ownerName
                        or "",
                    style =
                        threat.style
                        or "",
                    pending =
                        threat.aliCounterPending == true,
                    committed =
                        threat.aliCounterCommitted == true,
                    reason =
                        "ali_evasive_active",
                },
                true
            )
        end

        return false
    end

    if Menu._AliCounterRuntime
        and tonumber(
            Menu._AliCounterRuntime.fPulseUntil
        )
        and now
            < tonumber(
                Menu._AliCounterRuntime.fPulseUntil
            )
    then
        return false
    end

    if Menu._AliCounterRuntime
        and tonumber(
            Menu._AliCounterRuntime.chainUntil
        )
        and now
            < tonumber(
                Menu._AliCounterRuntime.chainUntil
            )
    then
        if threat.aliChainParrySuppressedLogged
            ~= true
        then
            threat.aliChainParrySuppressedLogged =
                true

            debugLog(
                "ALI_DODGE_ABUSE_PARRY_SUPPRESS",
                {
                    attack =
                        threat.attackType
                        or "",
                    owner =
                        threat.ownerName
                        or "",
                    reason =
                        "ali_dodge_abuse_chain",
                    remaining =
                        math.max(
                            0,
                            tonumber(
                                Menu._AliCounterRuntime.chainUntil
                            )
                                - now
                        ),
                },
                true
            )
        end

        return false
    end

    if now - lastParryAt < 0.025 then
        return false
    end

    local character = context.character

    if not character or not character.Parent then
        return false
    end

    if character:GetAttribute("Blocking") == true and not autoBlocking then
        threat.fired = true

        debugLog("SKIP_MANUAL_BLOCK", {
            source = threat.source or "",
            swingId = threat.swingId or "",
            attack = threat.attackType,
            owner = threat.ownerName or "",
        })

        return false
    end

    local equipped, equipReason = ensureEquipped()

    if not equipped and character:GetAttribute("Equip") ~= true then
        if not threat.equipSkipLogged then
            threat.equipSkipLogged = true

            debugLog("SKIP_EQUIP", {
                source = threat.source or "",
                swingId = threat.swingId or "",
                owner = threat.ownerName or "",
                reason = equipReason,
            })
        end

        return false
    end

    threat.equipSkipLogged = nil

    local blockModule = getCombatModule("Block")

    if not blockModule or type(blockModule.Block) ~= "function" then
        debugLog("BLOCK_MODULE_MISSING", {
            source = threat.source or "",
            swingId = threat.swingId or "",
        })

        return false
    end

    threat.fired = true
    threat.firedAt = now
    lastParryAt = now
    autoBlocking = true
    Menu._apBlockActive = true
    autoBlockSerial = autoBlockSerial + 1

    local serial = autoBlockSerial
    threat.apBlockSerial = serial
    Menu._apCurrentBlock = {
        serial = serial,
        owner = threat.ownerName or "",
        attack = threat.attackType or "",
        source = threat.source or "",
        startedAt = now,
    }
    prepareAutoFaceForParry(threat, context, true)
    local ok, blockResult = pcall(blockModule.Block)
    local accepted = ok and blockResult ~= false
    local err = not ok and blockResult or nil
    local styleGuardHold = 0

    if threat.source ~= "server_hitbox" then
        if threat.style == "kyokushin" then
            styleGuardHold = threat.attackType == "M2"
                and (
                    tonumber(prediction.kyokushinM2GuardHold)
                    or KYOKUSHIN_M2_GUARD_HOLD
                )
                or (
                    tonumber(threat.combo) == 1
                    and threat.apAttackPreempted == true
                    and 0.285
                    or 0.25
                )
        elseif threat.style == "hakari" then
            if threat.attackType == "M2" then
                styleGuardHold =
                    threat.hakariMomentum == true
                    and 0.30
                    or 0.34
            elseif threat.hakariStoppedTrackRescue == true then
                -- Stopped-track Hakari M1s in the trace replicated 90-200 ms after
                -- the animation-scheduled parry point. Keep guard alive through that
                -- delayed server contact instead of releasing on the normal M1 hold.
                styleGuardHold = 0.27
            end
        elseif threat.style == "cqc"
            and threat.attackType == "M1"
        then
            styleGuardHold = 0.27
        end

        if threat.resolverPunishRescue == true
            or threat.resolverLatentCorroborated == true
        then
            styleGuardHold =
                math.max(
                    styleGuardHold,
                    tonumber(
                        threat.resolverPunishGuardHold
                    )
                        or (
                            threat.attackType == "M2"
                            and Menu._ResolverProofRuntime
                                .INCOMING_PUNISH_M2_GUARD_HOLD
                            or Menu._ResolverProofRuntime
                                .INCOMING_PUNISH_M1_GUARD_HOLD
                        )
                )
        end
    end

    if accepted then



        AutoPunishRuntime.recordParryAttempt(threat, context)

        local coverageKey = tostring(threat.ownerName or "")
            .. "|"
            .. tostring(threat.attackType or "")
        Menu._apRecentParryCoverage[coverageKey] = {
            at = now,
            serial = serial,
            source = threat.source or "",
            swingId = threat.swingId,
        }
    end

    debugLog("PARRY_PRESS", {
        ok = ok,
        callOk = ok,
        invoked = accepted,
        accepted = accepted, 
        blockResult = blockResult == nil and "nil" or blockResult,
        error = err,
        source = threat.source or "",
        attack = threat.attackType,
        attackName = threat.attackName or "",
        animationName = threat.animationName or "",
        owner = threat.ownerName or "",
        style = threat.style or "",
        combo = threat.combo or 0,
        variant = threat.variant or "",
        swingId = threat.swingId or "",
        actionToken = threat.actionToken or "",
        strikeDamage = threat.strikeDamage or "",
        serverConfirmed = threat.serverConfirmed == true,
        distance = context.distance,
        heightDiff = context.heightDiff,
        ping = prediction.ping,
        pingPlayer =
            Menu._APPingSourceSnapshot
            and Menu._APPingSourceSnapshot.player
            or "",
        pingStats =
            Menu._APPingSourceSnapshot
            and Menu._APPingSourceSnapshot.stats
            or "",
        pingSelected =
            Menu._APPingSourceSnapshot
            and Menu._APPingSourceSnapshot.selected
            or prediction.ping,
        up = prediction.up,
        kureNetworkTrim = prediction.kureNetworkTrim or 0,
        cqcNetworkTrim = prediction.cqcNetworkTrim or 0,
        kyokushinM2TimingLead =
            prediction.kyokushinM2TimingLead or 0,
        kyokushinM2NetworkProfile =
            prediction.kyokushinM2NetworkProfile or "",
        hakariM2PerfectTrim =
            prediction.hakariM2PerfectTrim or 0,
        styleGuardHold = styleGuardHold,
        hitTL = prediction.hitTL or 0,
        trackTime =
            prediction.trackTime or 0,
        trackSpeed =
            prediction.trackSpeed or 0,
        visualTrackTime =
            prediction.visualTrackTime or "",
        visualTrackSpeed =
            prediction.visualTrackSpeed or "",
        combatTimelineSpeed =
            prediction.combatTimelineSpeed or "",
        ownerAttackSpeed =
            prediction.ownerAttackSpeed or "",
        speedDesynced =
            prediction.speedDesynced == true,
        hakariStopRescue =
            threat.hakariStoppedTrackRescue == true,
        overlapDelay = prediction.overlapDelay,
        target = prediction.target,
        lookahead = prediction.lookahead,
        pressDelta = prediction.pressAt - now,
    }, true)





    if not accepted then
        threat.fired = false
        threat.firedAt = nil
        autoBlocking = false
        Menu._apBlockActive = false
        if type(Menu._apCurrentBlock) == "table"
            and tonumber(Menu._apCurrentBlock.serial) == tonumber(serial)
        then
            Menu._apCurrentBlock = nil
        end
        lastParryAt = 0

        return false
    end

    local hold
    if threat.source == "server_hitbox" then



        hold = threat.attackType == "M2" and threat.style == "boxing"
            and 0.19
            or 0.15
    else
        hold = math.clamp(
            (prediction.pwin or 0.125)
                + 0.045
                + math.min(math.max(tonumber(prediction.ping) or 0, 0) * 0.12, 0.012),
            0.17,
            0.20
        )




        local contactCoverage =
            math.max(0, tonumber(prediction.target) or 0)
            + math.max(0, tonumber(prediction.up) or 0)
            + math.max(0, tonumber(prediction.lookahead) or 0)
            + 0.065

        hold = math.clamp(
            math.max(hold, contactCoverage),
            0.19,
            0.255
        )




        if threat.attackType == "M2" and threat.style == "boxing" then
            hold = math.max(hold, 0.24)
        end

        hold = math.max(hold, styleGuardHold)
    end

    if threat.source == "wingchun_counter" then
        local firstHitDelay = math.max(
            0,
            tonumber(threat.counterHitDelay) or (25 / 60)
        )
        hold = math.clamp(
            math.max(
                hold,
                firstHitDelay
                    + 0.12
                    + math.min(
                        math.max(tonumber(prediction.ping) or 0, 0),
                        0.15
                    )
            ),
            0.46,
            0.72
        )
        debugLog("WINGCHUN_COUNTER_GUARD_HOLD", {
            owner = threat.ownerName or "",
            firstHitDelayMs = math.floor(firstHitDelay * 1000 + 0.5),
            holdMs = math.floor(hold * 1000 + 0.5),
            playbackSpeed = threat.counterPlaybackSpeed or "",
        }, true)
    elseif threat.source == "wingchun_counter_prearm" then
        local guardUntil = tonumber(threat.wingChunGuardUntil) or now
        hold = math.clamp(
            math.max(hold, guardUntil - now),
            0.18,
            0.68
        )
        debugLog("WINGCHUN_COUNTER_PREARM_HOLD", {
            owner = threat.ownerName or "",
            holdMs = math.floor(hold * 1000 + 0.5),
        }, true)
    end

    if threat.source == "animation"
        or threat.source == "resolver_surface"
    then
        debugLog(
            "AP_GUARD_HOLD",
            {
                attack = threat.attackType or "",
                owner = threat.ownerName or "",
                style = threat.style or "",
                source = threat.source or "",
                holdMs = math.floor(hold * 1000 + 0.5),
                targetMs = math.floor((tonumber(prediction.target) or 0) * 1000 + 0.5),
                upMs = math.floor((tonumber(prediction.up) or 0) * 1000 + 0.5),
                lookaheadMs = math.floor((tonumber(prediction.lookahead) or 0) * 1000 + 0.5),
                speedDesynced = prediction.speedDesynced == true,
                punishRescue =
                    threat.resolverPunishRescue == true,
                punishEmergency =
                    threat.resolverPunishEmergency == true,
                latentCorroborated =
                    threat.resolverLatentCorroborated == true,
            },
            true
        )
    end

    task.delay(hold, function()
        releaseAutoBlock(serial)
    end)

    return true
end

local function tryKyokushinM2StoppedTrackRescue(threat, now)
    if threat.style ~= "kyokushin"
        or threat.attackType ~= "M2"
        or threat.fired
    then
        return false
    end

    local contactAbs = tonumber(threat.expectedContactAbs)
    if not contactAbs
        or now > contactAbs
            + KYOKUSHIN_M2_STOPPED_TRACK_CONTACT_GRACE
    then
        return false
    end

    local proofReason = tostring(threat.resolverProofReason or "")
    local verified = threat.serverConfirmed == true
        or proofReason == "replicated-M2"
        or proofReason == "m2-cooldown-edge"
        or proofReason == "combat-token-type"
        or proofReason == "combat-token-edge"

    if not verified then
        return false
    end

    local allowed, rejectReason, context = passesThreatFilters(threat)
    if not allowed or not context then
        if now <= contactAbs + KYOKUSHIN_M2_STOPPED_TRACK_CONTACT_GRACE
            and (
                rejectReason == "reach"
                or rejectReason == "range"
                or rejectReason == "own_attack"
                or rejectReason == "cant_anything"
                or rejectReason == "parry_attack_lockout"
                or rejectReason == "block_cooldown"
                or rejectReason == "stunned"
            )
        then
            if threat.kyokushinM2TrackRescuePendingLogged ~= true then
                threat.kyokushinM2TrackRescuePendingLogged = true
                debugLog("AP_KYOKUSHIN_M2_TRACK_RESCUE_PENDING", {
                    owner = threat.ownerName or "",
                    reason = rejectReason or "",
                    proof = proofReason,
                    contactIn = contactAbs - now,
                }, true)
            end

            return true
        end

        return false
    end

    local ping, up = getUplink()
    local target, lookahead, pwin = predictionWindow()
    local timingLead,
        stoppedTrackEarlyFireLead,
        _attackPreemptWindow,
        autoFacePrearm,
        guardHold,
        networkProfile =
            getKyokushinM2NetworkProfile(ping)
    local pressAt = contactAbs
        - target
        - up
        - timingLead
    local pressAtQ = pressAt - lookahead

    if threat.kyokushinM2TrackRescueLogged ~= true then
        threat.kyokushinM2TrackRescueLogged = true
        debugLog("AP_KYOKUSHIN_M2_TRACK_RESCUE", {
            owner = threat.ownerName or "",
            distance = context.distance or "",
            armReady = context.armReady == true,
            proof = proofReason,
            contactIn = contactAbs - now,
            fireIn = pressAtQ - now,
            kyokushinM2TimingLead =
                timingLead,
            networkProfile = networkProfile,
            ping = ping,
        }, true)
    end

    if context.armReady ~= true then
        local rescueThreshold =
            tonumber(context.armThreshold)
            or tonumber(threat.apCurrentArmThreshold)
            or tonumber(context.effectiveReach)
            or 0
        local rescueDistance =
            tonumber(context.distance) or math.huge
        local rescueRangePad = 1.35

        if rescueThreshold > 0
            and rescueDistance
                <= rescueThreshold + rescueRangePad
        then
            context.armReady = true
            context.kyokushinM2VerifiedReacquire = true

            if threat.kyokushinM2ReacquireLogged ~= true then
                threat.kyokushinM2ReacquireLogged = true
                debugLog("AP_KYOKUSHIN_M2_REACQUIRE", {
                    owner = threat.ownerName or "",
                    distance = rescueDistance,
                    armThreshold = rescueThreshold,
                    rangePad = rescueRangePad,
                    proof = proofReason,
                    contactIn = contactAbs - now,
                    fireIn = pressAtQ - now,
                }, true)
            end
        end
    end

    local rescueFireAt = math.min(
        pressAtQ,
        contactAbs - stoppedTrackEarlyFireLead
    )

    if rescueFireAt - now <= autoFacePrearm then
        prepareAutoFaceForParry(threat, context, false)
    end

    if context.armReady ~= true or now < rescueFireAt then
        return true
    end

    local track = threat.track
    local visualTrackTime = track
        and math.max(0, tonumber(track.TimePosition) or 0)
        or 0
    local visualTrackSpeed = track
        and (tonumber(track.Speed) or 1)
        or 1
    local combatTimelineSpeed = tonumber(
        threat.speedMultiplier or getSpeedMultiplier(threat.owner)
    ) or 1
    if combatTimelineSpeed < 0.2 or combatTimelineSpeed > 3 then
        combatTimelineSpeed = 1
    end
    local prediction = {
        ping = ping,
        up = up,
        target = target,
        pwin = pwin,
        lookahead = lookahead,
        overlapDelay = 0,
        velLead = 0,
        appliedMotionLead = 0,
        hitTL = threat.hitTL or getThreatHitTimeline(threat),
        trackTime = visualTrackTime,
        trackSpeed = combatTimelineSpeed,
        visualTrackTime = visualTrackTime,
        visualTrackSpeed = visualTrackSpeed,
        combatTimelineSpeed = combatTimelineSpeed,
        ownerAttackSpeed =
            threat.speedMultiplier or getSpeedMultiplier(threat.owner),
        speedDesynced = false,
        kureNetworkTrim = 0,
        cqcNetworkTrim = 0,
        kyokushinM2TimingLead =
            timingLead,
        kyokushinM2StoppedTrackEarlyFireLead =
            stoppedTrackEarlyFireLead,
        kyokushinM2AutoFacePrearm =
            autoFacePrearm,
        kyokushinM2GuardHold =
            guardHold,
        kyokushinM2NetworkProfile =
            networkProfile,
        contactAbs = contactAbs,
        pressAt = pressAt,
        pressAtQ = pressAtQ,
    }

    if threat.kyokushinM2TrackRescueFireLogged ~= true then
        threat.kyokushinM2TrackRescueFireLogged = true
        debugLog("AP_KYOKUSHIN_M2_TRACK_RESCUE_FIRE", {
            owner = threat.ownerName or "",
            distance = context.distance or "",
            proof = proofReason,
            lateBy = math.max(0, now - rescueFireAt),
            scheduledFireIn = rescueFireAt - now,
            earlyFireLead = stoppedTrackEarlyFireLead,
            networkProfile = networkProfile,
            ping = ping,
            contactIn = contactAbs - now,
        }, true)
    end

    performParry(threat, prediction, context)
    return true
end

Menu._APTryHakariStoppedTrackRescue = function(threat, now)
    if threat.style ~= "hakari"
        or threat.source ~= "animation"
        or threat.fired
    then
        return false
    end

    local stoppedAt = tonumber(threat.trackStoppedAt)
    local contactAbs = tonumber(threat.expectedContactAbs)
    if not stoppedAt or not contactAbs then
        return false
    end

    local remainingAtStop = contactAbs - stoppedAt
    if threat.hakariStoppedTrackRescue ~= true then
        local proofReason = tostring(threat.resolverProofReason or "")
        local verified = threat.serverConfirmed == true
            or proofReason == "hakari-combat-animation"

        if not verified
            or remainingAtStop < Menu._APHakariStopTuning.minRemaining
            or remainingAtStop > Menu._APHakariStopTuning.maxRemaining
        then
            return false
        end

        threat.hakariStoppedTrackRescue = true
        threat.hakariLifecycleDesynced = true
        threat.trackStopHandoffUntil = math.max(
            tonumber(threat.trackStopHandoffUntil) or 0,
            contactAbs + Menu._APHakariStopTuning.contactGrace
        )

        debugLog("AP_HAKARI_STOP_DESYNC", {
            owner = threat.ownerName or "",
            attack = threat.attackType or "",
            combo = threat.combo or 0,
            animationName = threat.animationName or "",
            proof = proofReason,
            stopAge = stoppedAt - threat.createdAt,
            contactRemaining = remainingAtStop,
            handoffRemaining = threat.trackStopHandoffUntil - now,
        }, true)
    end

    if now > contactAbs + Menu._APHakariStopTuning.contactGrace then
        return false
    end

    local allowed, rejectReason, context = passesThreatFilters(threat)
    if not allowed or not context then
        local pending = rejectReason == "reach"
            or rejectReason == "range"
            or rejectReason == "own_attack"
            or rejectReason == "cant_anything"
            or rejectReason == "parry_attack_lockout"
            or rejectReason == "block_cooldown"
            or rejectReason == "stunned"
            or rejectReason == "equip"
            or rejectReason == "not_equipped"

        if pending and now <= contactAbs + Menu._APHakariStopTuning.contactGrace then
            if threat.hakariStoppedTrackPendingLogged ~= true then
                threat.hakariStoppedTrackPendingLogged = true
                debugLog("AP_HAKARI_STOP_RESCUE_PENDING", {
                    owner = threat.ownerName or "",
                    attack = threat.attackType or "",
                    combo = threat.combo or 0,
                    reason = rejectReason or "",
                    contactIn = contactAbs - now,
                }, true)
            end
            return true
        end

        return false
    end

    if context.armReady ~= true then
        local threshold = tonumber(context.armThreshold)
            or tonumber(threat.apCurrentArmThreshold)
            or tonumber(context.effectiveReach)
            or 0
        local distance = tonumber(context.distance) or math.huge

        if threshold > 0
            and distance <= threshold + Menu._APHakariStopTuning.rangePad
        then
            context.armReady = true
            context.hakariStoppedTrackReacquire = true

            if threat.hakariStoppedTrackReacquireLogged ~= true then
                threat.hakariStoppedTrackReacquireLogged = true
                debugLog("AP_HAKARI_STOP_REACQUIRE", {
                    owner = threat.ownerName or "",
                    attack = threat.attackType or "",
                    combo = threat.combo or 0,
                    distance = distance,
                    armThreshold = threshold,
                    rangePad = Menu._APHakariStopTuning.rangePad,
                    contactIn = contactAbs - now,
                }, true)
            end
        end
    end

    local ping, up = getUplink()
    local target, lookahead, pwin = predictionWindow()
    local combatTimelineSpeed = tonumber(
        threat.speedMultiplier or getSpeedMultiplier(threat.owner)
    ) or 1
    if combatTimelineSpeed < 0.2 or combatTimelineSpeed > 3 then
        combatTimelineSpeed = 1
    end

    local hakariPressLead = 0
    if threat.attackType ~= "M2"
        or threat.hakariMomentum == true
    then
        hakariPressLead = combatTimelineSpeed >= 1.20 and 0.018 or 0.008
    end

    local hakariM2PerfectTrim = threat.attackType == "M2"
        and threat.hakariMomentum ~= true
        and (combatTimelineSpeed >= 1.20 and 0.014 or 0.022)
        or 0

    local pressAt = contactAbs
        - target
        - up
        - hakariPressLead
        + hakariM2PerfectTrim
    local pressAtQ = pressAt - lookahead

    -- Frame spikes were present in the supplied trace. A small bounded extra lead keeps
    -- the stopped-track rescue from landing one rendered frame late at ~20 FPS.
    local frameSpikeLead = math.clamp(
        math.max((tonumber(lastFrameDt) or (1 / 60)) - (1 / 60), 0) * 0.65,
        0,
        0.024
    )
    local rescueFireAt = pressAtQ
        - Menu._APHakariStopTuning.extraLead
        - frameSpikeLead

    if rescueFireAt - now <= AUTOFACE_PARRY_PREARM then
        prepareAutoFaceForParry(threat, context, false)
    end

    if context.armReady ~= true or now < rescueFireAt then
        return true
    end

    local track = threat.track
    local visualTrackTime = track
        and math.max(0, tonumber(track.TimePosition) or 0)
        or 0
    local visualTrackSpeed = track
        and (tonumber(track.Speed) or 1)
        or 1
    local animationStartedAt = tonumber(threat.animationStartedAt) or threat.createdAt
    local syntheticTrackTime = math.max(
        visualTrackTime,
        math.max(0, now - animationStartedAt) * combatTimelineSpeed
    )

    local prediction = {
        ping = ping,
        up = up,
        target = target,
        pwin = pwin,
        lookahead = lookahead,
        overlapDelay = 0,
        velLead = 0,
        appliedMotionLead = 0,
        closing = 0,
        hitTL = threat.hitTL or getThreatHitTimeline(threat),
        trackTime = syntheticTrackTime,
        trackSpeed = combatTimelineSpeed,
        visualTrackTime = visualTrackTime,
        visualTrackSpeed = visualTrackSpeed,
        combatTimelineSpeed = combatTimelineSpeed,
        ownerAttackSpeed = combatTimelineSpeed,
        speedDesynced = false,
        kureNetworkTrim = 0,
        cqcNetworkTrim = 0,
        hakariM2PerfectTrim = hakariM2PerfectTrim,
        contactAbs = contactAbs,
        pressAt = pressAt,
        pressAtQ = pressAtQ,
    }

    if threat.hakariStoppedTrackRescueFireLogged ~= true then
        threat.hakariStoppedTrackRescueFireLogged = true
        debugLog("AP_HAKARI_STOP_RESCUE_FIRE", {
            owner = threat.ownerName or "",
            attack = threat.attackType or "",
            combo = threat.combo or 0,
            distance = context.distance or "",
            stopAge = stoppedAt - threat.createdAt,
            contactIn = contactAbs - now,
            scheduledFireIn = rescueFireAt - now,
            frameSpikeLead = frameSpikeLead,
            proof = threat.resolverProofReason or "",
        }, true)
    end

    performParry(threat, prediction, context)
    return true
end

local function normalizeAnimationId(value)
    value = tostring(value or "")
    return value:match("%d+") or value
end

local function classifyAnimationName(name)
    local raw = string.lower(tostring(name or ""))
    local compact = raw:gsub("[%s_%-%#]", "")

    if compact:find("1stm1", 1, true) then
        return "M1", 1
    elseif compact:find("2ndm1", 1, true) then
        return "M1", 2
    elseif compact:find("3rdm1", 1, true) then
        return "M1", 3
    elseif compact:find("4thm1", 1, true) then
        return "M1", 4
    end

    if compact == "m2"
        or compact == "momentumm2"
        or compact == "leftm2"
        or compact == "rightm2"
        or compact == "m2left"
        or compact == "m2right"
        or (
            compact:find("m2", 1, true)
            and not compact:find("hit", 1, true)
            and not compact:find("block", 1, true)
            and not compact:find("victim", 1, true)
            and not compact:find("success", 1, true)
            and not compact:find("activate", 1, true)
            and not compact:find("counter", 1, true)
        )
    then
        return "M2", nil
    end

    return nil, nil
end

local function getAnimationMap(character)
    local ok, folder = pcall(
        CombatAnimationUtils.GetCombatAnimsFolderForCharacter,
        character
    )

    if not ok or not folder then
        return nil
    end

    local cached = animationMaps[folder]

    if cached then
        return cached
    end

    local map = {}

    for _, object in ipairs(folder:GetDescendants()) do
        if object:IsA("Animation") then
            local attackType, combo = classifyAnimationName(object.Name)

            if attackType then
                local key = normalizeAnimationId(object.AnimationId)

                if key ~= "" then
                    map[key] = {
                        attackType = attackType,
                        combo = combo,
                        animationName = object.Name,
                    }
                end
            end
        end
    end

    animationMaps[folder] = map
    return map
end

local function classifyTrack(character, track)
    local animation = track.Animation
    local animationId = animation and normalizeAnimationId(animation.AnimationId) or ""
    local map = getAnimationMap(character)
    local info = map and map[animationId]

    if info then
        return info.attackType, info.combo, info.animationName, animationId
    end

    local styleProfile = VerifiedStyleProfiles[getStyle(character)]
    local verified = styleProfile
        and styleProfile.animations
        and styleProfile.animations[animationId]

    if verified then
        return verified.attackType, verified.combo, verified.name, animationId
    end

    local attackType, combo = classifyAnimationName(
        animation and animation.Name or track.Name
    )

    return attackType, combo, animation and animation.Name or track.Name, animationId
end





local AlbertEinstein = {
    Enabled = false,
    Mode = "Fighting Style",
    Animator = nil,
    AnimationConnection = nil,
    MovementController = nil,
    LastCharacter = nil,
    NextMaintenanceAt = 0,
    LocomotionSpoofDepth = 0,
    LocomotionSpoofInstalled = false,
    LocomotionOldNamecall = nil,
}

local function aeGetMovementController()
    if type(AlbertEinstein.MovementController) == "table" then
        return AlbertEinstein.MovementController
    end

    local function usableModule(
        candidate
    )
        if not candidate
            or not candidate:IsA(
                "ModuleScript"
            )
            or candidate.Parent == nil
        then
            return false
        end

        local ok,
            inGame =
            pcall(
                candidate.IsDescendantOf,
                candidate,
                game
            )

        return ok
            and inGame == true
    end

    local module

    pcall(function()
        local shared =
            ReplicatedStorage:
                FindFirstChild(
                    "Shared"
                )
        local services =
            shared
            and shared:FindFirstChild(
                "Services"
            )
        local movementService =
            services
            and services:FindFirstChild(
                "MovementService"
            )
        local candidate =
            movementService
            and movementService:
                FindFirstChild(
                    "MovementServiceClient"
                )

        if usableModule(
            candidate
        )
        then
            module = candidate
        end
    end)

    if not module
        and type(getloadedmodules)
            == "function"
    then
        pcall(function()
            for _, loaded
                in ipairs(
                    getloadedmodules()
                )
            do
                if usableModule(
                    loaded
                )
                    and loaded.Name
                        == "MovementServiceClient"
                then
                    module = loaded
                    break
                end
            end
        end)
    end

    if not usableModule(
        module
    )
    then
        return nil
    end

    local ok,
        controller =
        pcall(
            require,
            module
        )

    if ok
        and type(controller)
            == "table"
    then
        AlbertEinstein.MovementController =
            controller

        return controller
    end

    return nil
end

local function aeInstallEquipSpoof()
    if AlbertEinstein.LocomotionSpoofInstalled then
        return true
    end

    if type(hookmetamethod) ~= "function" or type(getnamecallmethod) ~= "function" then
        return false
    end

    local wrap = newcclosure or function(callback)
        return callback
    end

    AlbertEinstein.LocomotionOldNamecall = hookmetamethod(game, "__namecall", wrap(function(self, ...)
        if (AlbertEinstein.LocomotionSpoofDepth or 0) > 0
            and getnamecallmethod() == "GetAttribute"
            and self == getCharacter()
            and select(1, ...) == "Equip" then
            return false
        end

        return AlbertEinstein.LocomotionOldNamecall(self, ...)
    end))

    AlbertEinstein.LocomotionSpoofInstalled = true
    return true
end

local function aeCallUnequipped(callback, controller, ...)
    if type(callback) ~= "function" then
        return nil
    end

    if not aeInstallEquipSpoof() then
        local ok, result = pcall(callback, controller, ...)
        return ok and result or nil
    end

    AlbertEinstein.LocomotionSpoofDepth = (AlbertEinstein.LocomotionSpoofDepth or 0) + 1
    local result = table.pack(pcall(callback, controller, ...))
    AlbertEinstein.LocomotionSpoofDepth = math.max(0, (AlbertEinstein.LocomotionSpoofDepth or 1) - 1)

    if result[1] ~= true then
        return nil
    end

    return table.unpack(result, 2, result.n)
end

local function aeGetAnimator(character)
    local humanoid = character and character:FindFirstChildOfClass("Humanoid")
    if not humanoid then
        return nil, nil
    end

    local animator = humanoid:FindFirstChildOfClass("Animator")
    if not animator then
        pcall(function()
            animator = humanoid:WaitForChild("Animator", 0.25)
        end)
    end

    return humanoid, animator
end

local function aeAnimationId(track)
    local animation = track and track.Animation
    return animation and normalizeAnimationId(animation.AnimationId) or ""
end

local function aeIsCurrentStyleLocomotionId(animationId)
    if not animationId or animationId == "" then
        return false
    end

    local folder
    pcall(function()
        folder = CombatAnimationUtils.GetCombatAnimsFolderForPlayer(LocalPlayer)
    end)

    if not folder then
        return false
    end

    for _, object in ipairs(folder:GetDescendants()) do
        if object:IsA("Animation") then
            local name = string.lower(object.Name)
            if name == "idle" or name == "walk" or name == "run" or name == "sprint" then
                if normalizeAnimationId(object.AnimationId) == animationId then
                    return true
                end
            end
        end
    end

    return false
end

local function aeStopTrack(track, fade)
    if not track then
        return
    end

    pcall(function()
        track:Stop(tonumber(fade) or 0)
    end)
end

local function aeClearControllerTrack(controller, track)
    if type(controller) ~= "table" or not track then
        return
    end

    if controller._walkTrack == track then
        controller._walkTrack = nil
        controller._lastWalkPlaybackSpeed = nil
    end

    if controller._idleTrack == track then
        controller._idleTrack = nil
        controller._idleUsingWalkEmote = false
    end

    if controller._runTrack == track then
        controller._runTrack = nil
        if type(controller._sprintTrackLastSpeed) == "table" then
            controller._sprintTrackLastSpeed[track] = nil
        end
    end
end

local function aeStopStyleLocomotion()
    local character = getCharacter()
    if not character or not character.Parent then
        return
    end

    local controller = aeGetMovementController()
    local _, animator = aeGetAnimator(character)
    local handled = setmetatable({}, {__mode = "k"})

    local function stop(track)
        if not track or handled[track] then
            return
        end
        handled[track] = true

        if aeIsCurrentStyleLocomotionId(aeAnimationId(track)) then
            aeStopTrack(track, 0)
            aeClearControllerTrack(controller, track)
        end
    end

    if animator then
        pcall(function()
            for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
                stop(track)
            end
        end)
    end

    if type(controller) == "table" then
        stop(controller._idleTrack)
        stop(controller._walkTrack)
        stop(controller._runTrack)
    end
end

local function aeSuppressTrack(track)
    if AlbertEinstein.Enabled ~= true or not track then
        return false
    end

    local character = getCharacter()
    if not character then
        return false
    end

    local attackType = classifyTrack(character, track)

    local breakerRuntime = Menu._APBreakerRuntime
    if breakerRuntime
        and Flags.desync_auto_parry_breaker == true
    then
        if breakerRuntime.baitTracks
            and breakerRuntime.baitTracks[track]
        then
            return false
        end

        if Flags.desync_ap_breaker_passive == true
            and (attackType == "M1" or attackType == "M2")
        then
            return false
        end
    end

    local shouldSuppress = attackType == "M1" or attackType == "M2"
    local styleLocomotion = false

    if not shouldSuppress and AlbertEinstein.Mode == "No Fighting Style" then
        styleLocomotion = aeIsCurrentStyleLocomotionId(aeAnimationId(track))
        shouldSuppress = styleLocomotion
    end

    if not shouldSuppress then
        return false
    end

    pcall(function()
        track:AdjustWeight(0, 0)
        track:AdjustSpeed(0)
        track:Stop(0)
    end)

    if styleLocomotion then
        aeClearControllerTrack(aeGetMovementController(), track)
    end

    return true
end

local function aeSuppressPlayingTracks()
    local character = getCharacter()
    local _, animator = aeGetAnimator(character)
    if not animator then
        return
    end

    pcall(function()
        for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
            aeSuppressTrack(track)
        end
    end)
end

local function aeDisconnectAnimatorHook()
    if AlbertEinstein.AnimationConnection then
        pcall(function()
            AlbertEinstein.AnimationConnection:Disconnect()
        end)
    end

    AlbertEinstein.AnimationConnection = nil
    AlbertEinstein.Animator = nil
end

local function aeEnsureAnimatorHook()
    local character = getCharacter()
    local _, animator = aeGetAnimator(character)

    if animator == AlbertEinstein.Animator
        and AlbertEinstein.AnimationConnection
        and AlbertEinstein.AnimationConnection.Connected then
        return
    end

    aeDisconnectAnimatorHook()
    AlbertEinstein.Animator = animator

    if animator then
        AlbertEinstein.AnimationConnection = animator.AnimationPlayed:Connect(function(track)
            if AlbertEinstein.Enabled then
                aeSuppressTrack(track)
            end
        end)
    end
end

local function aeUseGameOwnedLocomotion(controller, character)
    if not character or not character.Parent then
        return true
    end

    if character:GetAttribute("PlayingInstrument") ~= nil
        or character:GetAttribute("PlayingArcade") ~= nil
        or character:GetAttribute("PlayingAirHockey") ~= nil
        or character:GetAttribute("PlayingArmWrestling") ~= nil
        or character:GetAttribute("PlayingBasketballMatch") ~= nil
        or character:GetAttribute("BasketballMatchLocked") == true
        or character:GetAttribute("Emoting") ~= nil then
        return true
    end

    local states = controller and (controller._states or character:FindFirstChild("States"))
    local carrying = states and states:FindFirstChild("Carrying")
    return carrying and carrying:IsA("ObjectValue") and carrying.Value ~= nil or false
end

local function aeIsMoving(humanoid, root)
    if not humanoid or not root then
        return false
    end

    local horizontalSpeed = Vector3.new(
        root.AssemblyLinearVelocity.X,
        0,
        root.AssemblyLinearVelocity.Z
    ).Magnitude

    return humanoid.MoveDirection.Magnitude > 0.03 or horizontalSpeed > 0.20
end

local function aeCallLocomotion(controller, callback, unequipped, ...)
    if type(callback) ~= "function" then
        return
    end

    if unequipped then
        aeCallUnequipped(callback, controller, ...)
    else
        pcall(callback, controller, ...)
    end
end

local function aeRebuildLocomotion(unequipped)
    local controller = aeGetMovementController()
    local character = getCharacter()
    if type(controller) ~= "table" or not character or not character.Parent then
        return false
    end

    local humanoid = character:FindFirstChildOfClass("Humanoid")
    local root = character:FindFirstChild("HumanoidRootPart")
    if not humanoid or not root then
        return false
    end




    pcall(function()
        if type(controller._stopIdleAnimation) == "function" then
            controller:_stopIdleAnimation()
        end
        if type(controller._stopWalkAnimation) == "function" then
            controller:_stopWalkAnimation()
        end
    end)

    if controller._runTrack then
        aeStopTrack(controller._runTrack, 0.05)
        if type(controller._sprintTrackLastSpeed) == "table" then
            controller._sprintTrackLastSpeed[controller._runTrack] = nil
        end
        controller._runTrack = nil
    end

    if unequipped then
        aeStopStyleLocomotion()
    end

    if type(controller._onEquipChanged) == "function" then
        aeCallLocomotion(controller, controller._onEquipChanged, unequipped, character)
    end

    if aeUseGameOwnedLocomotion(controller, character) then
        return true
    end

    if controller._running == true then
        if type(controller._ensureRunAnimation) == "function" then
            aeCallLocomotion(controller, controller._ensureRunAnimation, unequipped, humanoid)
        end

        local runTrack = controller._runTrack
        if runTrack then
            pcall(function()
                runTrack.Looped = true
                if not runTrack.IsPlaying then
                    runTrack:Play(0.08)
                end
                if type(controller._sprintTrackLastSpeed) == "table" then
                    controller._sprintTrackLastSpeed[runTrack] = nil
                end
            end)
        end
    elseif aeIsMoving(humanoid, root) then
        if type(controller._playWalkAnimation) == "function" then
            aeCallLocomotion(controller, controller._playWalkAnimation, unequipped, 0.05)
        end
    elseif type(controller._playIdleAnimation) == "function" then
        aeCallLocomotion(controller, controller._playIdleAnimation, unequipped)
    end

    if unequipped then
        aeStopStyleLocomotion()
    end

    return true
end

local function aeNeedsNoStyleRebuild()
    local controller = aeGetMovementController()
    local character = getCharacter()
    if type(controller) ~= "table" or not character or not character.Parent then
        return false
    end

    if AlbertEinstein.LastCharacter ~= character then
        return true
    end

    if aeUseGameOwnedLocomotion(controller, character) then
        return false
    end

    local humanoid = character:FindFirstChildOfClass("Humanoid")
    local root = character:FindFirstChild("HumanoidRootPart")
    if not humanoid or not root then
        return false
    end

    local track
    if controller._running == true then
        track = controller._runTrack
    elseif aeIsMoving(humanoid, root) then
        track = controller._walkTrack
    else
        track = controller._idleTrack
    end

    if not track then
        return true
    end

    return aeIsCurrentStyleLocomotionId(aeAnimationId(track))
end

local function aeApplyNoStyle(force)
    if AlbertEinstein.Enabled ~= true or AlbertEinstein.Mode ~= "No Fighting Style" then
        return
    end

    aeEnsureAnimatorHook()
    aeStopStyleLocomotion()
    aeSuppressPlayingTracks()

    if force or aeNeedsNoStyleRebuild() then
        if aeRebuildLocomotion(true) then
            AlbertEinstein.LastCharacter = getCharacter()
        end
    end

    aeSuppressPlayingTracks()
end

local function aeRestoreRealLocomotion()
    AlbertEinstein.LastCharacter = nil
    aeRebuildLocomotion(false)
end

local function aeSetMode(mode)
    mode = mode == "No Fighting Style" and "No Fighting Style" or "Fighting Style"
    AlbertEinstein.Mode = mode
    AlbertEinstein.NextMaintenanceAt = 0
    AlbertEinstein.LastCharacter = nil

    if not AlbertEinstein.Enabled then
        return
    end

    if mode == "No Fighting Style" then
        aeApplyNoStyle(true)
    else
        aeRestoreRealLocomotion()
        aeEnsureAnimatorHook()
        aeSuppressPlayingTracks()
    end
end

local function aeSetEnabled(enabled)
    enabled = enabled == true




    AlbertEinstein.Enabled = enabled
    AlbertEinstein.NextMaintenanceAt = 0
    AlbertEinstein.LastCharacter = nil

    if not enabled then
        aeDisconnectAnimatorHook()
        aeRestoreRealLocomotion()
        return
    end

    aeEnsureAnimatorHook()

    if AlbertEinstein.Mode == "No Fighting Style" then
        aeApplyNoStyle(true)
    else
        aeSuppressPlayingTracks()
    end
end

Menu._ScriptRuntime:Track(RunService.Heartbeat:Connect(function()
    if not AlbertEinstein.Enabled then
        return
    end

    local now = os.clock()
    if now < (AlbertEinstein.NextMaintenanceAt or 0) then
        return
    end
    AlbertEinstein.NextMaintenanceAt = now + 0.05

    aeEnsureAnimatorHook()
    aeSuppressPlayingTracks()

    if AlbertEinstein.Mode == "No Fighting Style" then
        aeApplyNoStyle(false)
    end
end))

Menu._ScriptRuntime:Track(LocalPlayer.CharacterAdded:Connect(function()
    AlbertEinstein.Animator = nil
    AlbertEinstein.AnimationConnection = nil
    AlbertEinstein.LastCharacter = nil

    if AlbertEinstein.Enabled then
        task.delay(0.15, function()
            if not AlbertEinstein.Enabled then
                return
            end

            aeEnsureAnimatorHook()
            if AlbertEinstein.Mode == "No Fighting Style" then
                aeApplyNoStyle(true)
            else
                aeSuppressPlayingTracks()
            end
        end)
    end
end))

do
    Menu._APBreakerRuntime = Menu._APBreakerRuntime or {}
    local runtime = Menu._APBreakerRuntime

    runtime.baitTracks = runtime.baitTracks or setmetatable({}, {__mode = "k"})
    runtime.passiveTracks = runtime.passiveTracks or setmetatable({}, {__mode = "k"})
    runtime.cachedTracks = runtime.cachedTracks or {}
    runtime.nextBaitAt = 0
    runtime.character = runtime.character or nil
    runtime.style = runtime.style or ""
    runtime.animator = runtime.animator or nil
    runtime.animationConnection = runtime.animationConnection or nil
    runtime.serial = tonumber(runtime.serial) or 0
    runtime.visualMaskPose = runtime.visualMaskPose or setmetatable({}, {__mode = "k"})
    runtime.visualMaskUntil = tonumber(runtime.visualMaskUntil) or 0
    runtime.baitCursor = tonumber(runtime.baitCursor) or 0
    runtime.baitPauseUntil = tonumber(runtime.baitPauseUntil) or 0
    runtime.lastCommitTrapAt = tonumber(runtime.lastCommitTrapAt) or 0
    runtime.commitTrapSerial = tonumber(runtime.commitTrapSerial) or 0
    runtime.lastInputTrapAt = tonumber(runtime.lastInputTrapAt) or 0
    runtime.lastInputTrapAttack = tostring(runtime.lastInputTrapAttack or "")
    runtime.lastRealReleaseAt = tonumber(runtime.lastRealReleaseAt) or 0
    runtime.lastObservedM1Combo = tonumber(runtime.lastObservedM1Combo) or 0
    runtime.lastObservedM1At = tonumber(runtime.lastObservedM1At) or 0
    runtime.serverSplitSerial = tonumber(runtime.serverSplitSerial) or 0
    runtime.skipServerCheckUntil = runtime.skipServerCheckUntil or {
        M1 = 0,
        M2 = 0,
    }
    runtime.pendingM1HoldSerial = tonumber(runtime.pendingM1HoldSerial) or 0
    runtime.pendingM1ReleaseSerial =
        tonumber(runtime.pendingM1ReleaseSerial) or 0
    runtime.pendingM1ActivationSerial =
        tonumber(runtime.pendingM1ActivationSerial) or 0
    runtime.lastCommitBaitAt = tonumber(runtime.lastCommitBaitAt) or 0
    runtime.lastCommitContactDelay =
        tonumber(runtime.lastCommitContactDelay) or 0.18
    runtime.lastCommitStopDelay =
        tonumber(runtime.lastCommitStopDelay) or 0.23

    -- Compatibility fields from the older proof-delay experiments are kept in
    -- the runtime table, but Main322 does not delay real M1 ServerCheck. The
    -- active breaker strategy is the same-signature duplicate-window pre-roll
    -- implemented below.
    runtime.m1ProofDelaySeconds =
        tonumber(runtime.m1ProofDelaySeconds) or 0.16
    runtime.m1ProofDelayArmedUntil =
        tonumber(runtime.m1ProofDelayArmedUntil) or 0
    runtime.m1ProofDelaySerial =
        tonumber(runtime.m1ProofDelaySerial) or 0
    runtime.manualM1LoopToken =
        tonumber(runtime.manualM1LoopToken) or 0
    runtime.manualM1LoopActive =
        runtime.manualM1LoopActive == true
    runtime.realM1CycleSerial =
        tonumber(runtime.realM1CycleSerial) or 0
    runtime.realM1CompletedSerial =
        tonumber(runtime.realM1CompletedSerial) or 0
    runtime.realM1ActiveTrack = runtime.realM1ActiveTrack or nil
    runtime.realM1StartedAt =
        tonumber(runtime.realM1StartedAt) or 0
    runtime.realM1EndedAt =
        tonumber(runtime.realM1EndedAt) or 0
    -- Main410: all manual M1 input is animation-gated. Holding or spam-clicking
    -- cannot begin the next genuine M1 until the previous genuine M1 animation
    -- has fully ended. There is no fixed post-animation delay.
    runtime.holdPostAnimationGap = 0
    runtime.manualM1PhysicalHeld = false
    runtime.manualM1PhysicalSerial =
        tonumber(runtime.manualM1PhysicalSerial) or 0
    runtime.manualM1NativeRepeatSuppress =
        tonumber(runtime.manualM1NativeRepeatSuppress) or 0
    runtime.manualM1CadenceSuppress =
        tonumber(runtime.manualM1CadenceSuppress) or 0

    runtime.guardProbeSeconds =
        tonumber(runtime.guardProbeSeconds) or 0.30
    runtime.duplicatePreRollM1 =
        tonumber(runtime.duplicatePreRollM1) or 0.098
    runtime.duplicatePreRollM2 =
        tonumber(runtime.duplicatePreRollM2) or 0.072

    -- Remote replication handoff. Main322 allowed the low-weight bait and the
    -- genuine same-animation track to overlap. Other clients could coalesce the
    -- two starts and visually remain on the nearly invisible bait track.
    runtime.replicationHandoffM1 =
        tonumber(runtime.replicationHandoffM1) or 0.024
    runtime.replicationHandoffM2 =
        tonumber(runtime.replicationHandoffM2) or 0.020

    -- Manual M1 buffering follows the game's real client cadence instead of
    -- allowing multiple breaker pre-rolls to overlap.
    runtime.m1PreRollBusyUntil =
        tonumber(runtime.m1PreRollBusyUntil) or 0
    runtime.nextBufferedM1At =
        tonumber(runtime.nextBufferedM1At) or 0
    runtime.lastBreakerRealAt =
        tonumber(runtime.lastBreakerRealAt) or 0

    -- Do not inherit Main322's longer pre-roll values in the same server.
    runtime.duplicatePreRollM1 = 0.098
    runtime.duplicatePreRollM2 = 0.072

    runtime.guardReleaseTimeout =
        tonumber(runtime.guardReleaseTimeout) or 0.65
    runtime.baitSignatureLastUsed =
        runtime.baitSignatureLastUsed or {}
    runtime.baitSignatureSerial =
        tonumber(runtime.baitSignatureSerial) or 0
    runtime.lastGuardTarget = runtime.lastGuardTarget or nil
    runtime.lastGuardCommittedAt =
        tonumber(runtime.lastGuardCommittedAt) or 0

    -- Mask Visual is bait-only presentation cleanup. It must NEVER hide,
    -- pause, freeze, or zero the weight/speed/time of a genuine M1/M2.
    --
    -- Main312 only stabilized lower-body joints, so upper-body movement from the
    -- phase-advanced decoy was still visible. Main322 snapshots every character
    -- Motor6D during the short false swing and releases before the genuine attack.
    runtime.clearVisualMask = function()
        runtime.visualMaskUntil = 0
        table.clear(runtime.visualMaskPose)
    end

    runtime.captureVisualMask = function(character, holdSeconds)
        table.clear(runtime.visualMaskPose)

        if not character or not character.Parent then
            runtime.visualMaskUntil = 0
            return
        end

        local captured = 0
        local motors = 0
        local bones = 0

        for _, descendant in ipairs(character:GetDescendants()) do
            if descendant:IsA("Motor6D") or descendant:IsA("Bone") then
                local okTransform, transform = pcall(function()
                    return descendant.Transform
                end)

                if okTransform and typeof(transform) == "CFrame" then
                    runtime.visualMaskPose[descendant] = transform
                    captured += 1

                    if descendant:IsA("Motor6D") then
                        motors += 1
                    else
                        bones += 1
                    end
                end
            end
        end

        runtime.visualMaskUntil = os.clock() + math.max(
            tonumber(holdSeconds) or 0,
            0
        )

        debugLog("AP_BREAKER_MASK_BEGIN", {
            joints = captured,
            motors = motors,
            bones = bones,
            hold = math.max(tonumber(holdSeconds) or 0, 0),
        }, true)
    end

    runtime.stopActiveBaits = function(reason)
        for baitTrack, marker in pairs(runtime.baitTracks) do
            if baitTrack
                and marker ~= true
            then
                runtime.baitTracks[baitTrack] = true
                pcall(function()
                    if baitTrack.IsPlaying then
                        baitTrack:AdjustWeight(0, 0.01)
                        baitTrack:Stop(0.02)
                    end
                end)
            end
        end

        runtime.clearVisualMask()

        if reason then
            debugLog("AP_BREAKER_BAIT_STOP", {
                reason = tostring(reason),
            }, true)
        end
    end

    runtime.promoteActiveBaits = function(attackType, source)
        local promoted = 0

        for baitTrack, marker in pairs(runtime.baitTracks) do
            if baitTrack
                and marker ~= true
                and baitTrack.IsPlaying == true
            then
                -- Keep the exact same duplicate timeline alive. Only change its
                -- presentation at the moment the genuine attack begins.
                pcall(function()
                    baitTrack.Priority = Enum.AnimationPriority.Action4
                    baitTrack:AdjustWeight(1, 0.008)
                end)

                promoted += 1
            end
        end

        debugLog("AP_BREAKER_VISUAL_PROMOTE", {
            attack = tostring(attackType or ""),
            source = tostring(source or ""),
            promoted = promoted,
        }, true)

        return promoted
    end

    runtime.getNearestGuardTarget = function(maxDistance)
        local localCharacter = getCharacter()
        local localRoot =
            localCharacter
            and localCharacter:FindFirstChild("HumanoidRootPart")
            or nil

        if not localRoot then
            return nil, math.huge
        end

        local bestCharacter
        local bestDistance = tonumber(maxDistance) or 12

        for _, player in ipairs(
            game:GetService("Players"):GetPlayers()
        ) do
            if player ~= LocalPlayer then
                local character = player.Character
                local humanoid =
                    character
                    and character:FindFirstChildOfClass("Humanoid")
                    or nil
                local root =
                    character
                    and character:FindFirstChild("HumanoidRootPart")
                    or nil

                if character
                    and humanoid
                    and humanoid.Health > 0
                    and root
                    and character:GetAttribute("Downed") ~= true
                then
                    local distance =
                        (root.Position - localRoot.Position).Magnitude

                    if distance <= bestDistance then
                        bestCharacter = character
                        bestDistance = distance
                    end
                end
            end
        end

        return bestCharacter, bestDistance
    end

    runtime.getCommitWindow = function(attackType)
        attackType = tostring(attackType or "")

        local contactDelay =
            tonumber(runtime.lastCommitContactDelay) or 0.18
        local stopDelay =
            tonumber(runtime.lastCommitStopDelay) or 0.23
        local baitAge =
            os.clock() - (tonumber(runtime.lastCommitBaitAt) or 0)

        if baitAge > 0.80 then
            contactDelay = 0.18
            stopDelay = 0.23
        end

        if attackType == "M2" then
            -- M2 has a long real windup, so begin it earlier and let its actual
            -- hit arrive during the false-parry cooldown window.
            return math.clamp(
                contactDelay + 0.020,
                0.180,
                0.235
            )
        end

        -- M1 begins only after the false M1 has cleanly ended. Main314 started
        -- the genuine M1 while the bait was still alive, which let stricter AP
        -- transition directly from the fake threat onto the real one.
        return math.clamp(
            stopDelay + 0.055,
            0.265,
            0.335
        )
    end

    runtime.waitForCommitWindow = function(attackType, source)
        attackType = tostring(attackType or "")
        source = tostring(source or "")

        if attackType ~= "M1" and attackType ~= "M2" then
            return false
        end

        -- Main322 restores Main320's proven duplicate-window timing.
        -- The bait MUST remain alive when the genuine attack begins.
        local delay =
            attackType == "M2"
            and math.clamp(
                tonumber(runtime.duplicatePreRollM2) or 0.072,
                0.045,
                0.095
            )
            or math.clamp(
                tonumber(runtime.duplicatePreRollM1) or 0.098,
                0.075,
                0.105
            )

        if attackType == "M1" then
            runtime.m1PreRollBusyUntil =
                os.clock() + delay
        end

        debugLog("AP_BREAKER_DUPLICATE_PREROLL", {
            attack = attackType,
            source = source,
            delay = delay,
            overlap = true,
            baitContactDelay =
                tonumber(runtime.lastCommitContactDelay) or 0,
            baitStopDelay =
                tonumber(runtime.lastCommitStopDelay) or 0,
        }, true)

        task.wait(delay)

        -- Visibility fix that does NOT alter the breaker:
        -- Main320's low-weight bait stays alive for duplicate/proof merging,
        -- but becomes full-weight exactly as the real M1/M2 starts. If remote
        -- clients coalesce the genuine same-ID restart, they still render this
        -- already-replicated track visibly.
        if type(runtime.promoteActiveBaits) == "function" then
            runtime.promoteActiveBaits(
                attackType,
                source
            )
        end

        runtime.lastBreakerRealAt = os.clock()
        return true
    end

    runtime.priority = function()
        local value = Flags.desync_ap_breaker_priority
        if type(value) == "table" then
            value = value[1] or value.value or value.Value
        end
        value = tostring(value or "Action")
        local priorities = {
            Core = Enum.AnimationPriority.Core,
            Idle = Enum.AnimationPriority.Idle,
            Movement = Enum.AnimationPriority.Movement,
            Action = Enum.AnimationPriority.Action,
            Action2 = Enum.AnimationPriority.Action2,
            Action3 = Enum.AnimationPriority.Action3,
            Action4 = Enum.AnimationPriority.Action4,
        }
        return priorities[value] or Enum.AnimationPriority.Action
    end

    runtime.clearTracks = function()
        runtime.clearVisualMask()

        for _, item in ipairs(runtime.cachedTracks) do
            local track = item and item.track
            if track then
                runtime.baitTracks[track] = nil
                pcall(function()
                    track:Stop(0)
                end)
            end
        end
        table.clear(runtime.cachedTracks)
    end

    runtime.disconnectAnimator = function()
        if runtime.animationConnection then
            pcall(function()
                runtime.animationConnection:Disconnect()
            end)
        end
        runtime.animationConnection = nil
        runtime.animator = nil
    end

    runtime.releaseRealTrack = function(track, state, reason)
        if not track or type(state) ~= "table" then
            return false
        end

        local current = runtime.passiveTracks[track]
        if current ~= state then
            return false
        end

        runtime.passiveTracks[track] = nil

        pcall(function()
            if track.IsPlaying then
                track:AdjustWeight(1, tonumber(state.replayFade) or 0.015)
                track:AdjustSpeed(tonumber(state.speed) or 1)
            end
        end)

        runtime.lastRealReleaseAt = os.clock()
        debugLog("AP_BREAKER_REAL_RELEASE", {
            attack = tostring(state.attackType or ""),
            age = os.clock() - (tonumber(state.createdAt) or os.clock()),
            reason = tostring(reason or ""),
            serial = tonumber(state.serial) or 0,
        }, true)

        return true
    end

    runtime.releaseRealAttack = function(attackType, serverAddedAt)
        -- Compatibility hook retained for the server-hitbox watcher. Real
        -- animations are never held anymore, so there is nothing to release.
        return false
    end

    runtime.releaseAllRealTracks = function(reason)
        local pending = {}
        for track, state in pairs(runtime.passiveTracks) do
            if type(state) == "table" then
                pending[#pending + 1] = {track, state}
            end
        end

        for _, item in ipairs(pending) do
            runtime.releaseRealTrack(item[1], item[2], reason or "clear")
        end
    end

    runtime.getNativeM1Module = function()
        local cached = runtime.nativeM1Module
        if type(cached) == "table"
            and type(cached.OnM1Activated) == "function"
            and type(cached.Hold) == "function"
        then
            return cached
        end

        local okModule, module = pcall(function()
            return require(
                game:GetService("ReplicatedStorage")
                    :WaitForChild("CombatSystemClient")
                    :WaitForChild("Combat")
                    :WaitForChild("Base")
                    :WaitForChild("M1")
            )
        end)

        if not okModule or type(module) ~= "table" then
            debugLog("AP_BREAKER_M1_MODULE_FAIL", {
                error = tostring(module),
            }, true)
            return nil
        end

        runtime.nativeM1Module = module
        return module
    end

    -- Main410 hold pacing: one physical LMB hold is translated into a
    -- sequence of discrete M1 clicks. A later click cannot begin until the
    -- genuine local M1 animation from the previous click has completely ended.
    runtime.waitForRealM1Cycle = function(afterSerial, loopToken)
        afterSerial = tonumber(afterSerial) or 0
        loopToken = tonumber(loopToken) or -1

        local startDeadline = os.clock() + 1.10
        local observedSerial = 0

        while os.clock() <= startDeadline do
            if runtime.manualM1LoopToken ~= loopToken
                or Flags.desync_auto_parry_breaker ~= true
            then
                return false, 0, "cancelled"
            end

            local currentSerial =
                tonumber(runtime.realM1CycleSerial) or 0
            if currentSerial > afterSerial then
                observedSerial = currentSerial
                break
            end

            task.wait()
        end

        if observedSerial <= afterSerial then
            return false, 0, "no_animation_start"
        end

        local finishDeadline = os.clock() + 2.20
        while os.clock() <= finishDeadline do
            if runtime.manualM1LoopToken ~= loopToken
                or Flags.desync_auto_parry_breaker ~= true
            then
                return false, observedSerial, "cancelled"
            end

            if (tonumber(runtime.realM1CompletedSerial) or 0)
                >= observedSerial
            then
                -- The completed AnimationTrack is the cadence gate. Once Ended
                -- has fired, there is no additional fixed time delay.
                return true, observedSerial, "animation_ended"
            end

            task.wait()
        end

        return false, observedSerial, "animation_timeout"
    end

    runtime.waitForHeldM1Ready = function(loopToken)
        loopToken = tonumber(loopToken) or -1
        local deadline = os.clock() + 1.80

        while os.clock() <= deadline do
            if runtime.manualM1LoopToken ~= loopToken
                or Flags.desync_auto_parry_breaker ~= true
            then
                return false
            end

            local player = game:GetService("Players").LocalPlayer
            local character = player and player.Character or nil
            if not character or not character.Parent then
                return false
            end

            local blocked =
                character:GetAttribute("Equip") ~= true
                or character:GetAttribute("Ragdoll") == true
                or character:GetAttribute("Downed") == true
                or character:GetAttribute("GuardBroken") == true
                or character:GetAttribute("Blocking") == true
                or character:GetAttribute("M1") == true
                or character:GetAttribute("M2") == true
                or character:GetAttribute("PendingM1") == true
                or character:GetAttribute("PendingM2") == true
                or character:GetAttribute("M1Cooldown") == true
                or character:GetAttribute("CombatAttacking") == true
                or character:GetAttribute("Stunned") == true
                or (
                    character:GetAttribute("CantAnything") == true
                    and character:GetAttribute("CombatRecovery") ~= true
                )

            if not blocked then
                return true
            end

            task.wait()
        end

        return false
    end

    -- Main410 global manual-M1 cadence gate. This applies to both held LMB and
    -- rapid separate clicks. A new physical press cannot create another real M1
    -- while the previous genuine M1 animation is still active. The instant that
    -- animation fully ends, the next M1 may proceed (subject to native readiness).
    runtime.isManualM1CadenceBlocked = function()
        local started = tonumber(runtime.realM1CycleSerial) or 0
        local completed = tonumber(runtime.realM1CompletedSerial) or 0
        if started > completed then
            return true, "animation_active", started
        end

        return false, "ready", started, 0
    end

    runtime.waitForManualM1Cadence = function(loopToken)
        loopToken = tonumber(loopToken) or -1
        local deadline = os.clock() + 2.60

        while os.clock() <= deadline do
            if runtime.manualM1LoopToken ~= loopToken
                or Flags.desync_auto_parry_breaker ~= true
            then
                return false, "cancelled"
            end

            local blocked, reason, serial, remaining =
                runtime.isManualM1CadenceBlocked()

            if not blocked then
                return true, "ready"
            end

            if reason == "animation_active" then
                local completed, _, cycleReason =
                    runtime.waitForRealM1Cycle(
                        math.max((tonumber(serial) or 1) - 1, 0),
                        loopToken
                    )
                if not completed then
                    return false, tostring(cycleReason or "cycle_wait_failed")
                end
            else
                task.wait()
            end
        end

        return false, "cadence_timeout"
    end

    -- Keep a physical mouse-hold lifecycle separate from the game's repeated
    -- HoldActivated remote calls. The latter can fire many times from one hold.
    -- Only a real release is allowed to end the Main410 hold scheduler.
    if runtime.manualM1PhysicalReleaseConnection == nil then
        runtime.manualM1PhysicalReleaseConnection =
            Menu._ScriptRuntime:Track(UserInputService.InputEnded:Connect(function(input)
                if input.UserInputType ~= Enum.UserInputType.MouseButton1 then
                    return
                end

                if runtime.manualM1PhysicalHeld == true then
                    runtime.manualM1PhysicalHeld = false
                    runtime.manualM1LoopToken += 1
                    runtime.manualM1LoopActive = false

                    debugLog("AP_BREAKER_HOLD_PHYSICAL_RELEASE", {
                        token = runtime.manualM1LoopToken,
                    }, true)
                end
            end))
    end

    runtime.ensureCombatRemoteHook = function()
        local sharedEnv
        if type(getgenv) == "function" then
            local okEnv, result = pcall(getgenv)
            if okEnv and type(result) == "table" then
                sharedEnv = result
            end
        end
        sharedEnv = sharedEnv or _G

        local okModule, combatRemote = pcall(function()
            return require(
                ReplicatedStorage
                    :WaitForChild("Shared")
                    :WaitForChild("Network")
                    :WaitForChild("CombatRemoteClient")
            )
        end)

        if not okModule
            or type(combatRemote) ~= "table"
            or type(combatRemote.Fire) ~= "function"
        then
            return false
        end

        local currentHook =
            sharedEnv.__SilentAPBreakerCombatRemoteHook45

        local priorHook =
            currentHook
            or sharedEnv.__SilentAPBreakerCombatRemoteHook42
            or sharedEnv.__SilentAPBreakerCombatRemoteHook323
            or sharedEnv.__SilentAPBreakerCombatRemoteHook322
            or sharedEnv.__SilentAPBreakerCombatRemoteHook321
            or sharedEnv.__SilentAPBreakerCombatRemoteHook320
            or sharedEnv.__SilentAPBreakerCombatRemoteHook319
            or sharedEnv.__SilentAPBreakerCombatRemoteHook318
            or sharedEnv.__SilentAPBreakerCombatRemoteHook317
            or sharedEnv.__SilentAPBreakerCombatRemoteHook316
            or sharedEnv.__SilentAPBreakerCombatRemoteHook315
            or sharedEnv.__SilentAPBreakerCombatRemoteHook314
            or sharedEnv.__SilentAPBreakerCombatRemoteHook313

        local hookState = currentHook

        if type(hookState) == "table"
            and hookState.module == combatRemote
            and type(hookState.original) == "function"
            and type(hookState.wrapper) == "function"
        then
            hookState.runtime = runtime
            hookState.flags = Flags
            hookState.debugLog = debugLog

            if combatRemote.Fire ~= hookState.wrapper then
                combatRemote.Fire = hookState.wrapper
            end

            runtime.combatRemoteHookState = hookState
            return true
        end

        local baseOriginal = combatRemote.Fire
        if type(priorHook) == "table"
            and priorHook.module == combatRemote
            and type(priorHook.original) == "function"
        then
            baseOriginal = priorHook.original
        end

        hookState = {
            module = combatRemote,
            original = baseOriginal,
            runtime = runtime,
            flags = Flags,
            debugLog = debugLog,
        }

        hookState.wrapper = function(action, func, ...)
            local activeRuntime = hookState.runtime
            local activeFlags = hookState.flags
            local activeDebug = hookState.debugLog

            if type(activeRuntime) ~= "table"
                or type(activeFlags) ~= "table"
                or activeFlags.desync_auto_parry_breaker ~= true
            then
                return hookState.original(action, func, ...)
            end

            action = tostring(action or "")
            func = tostring(func or "")

            -- Main322 manual M1 path.
            --
            -- M1.Hold("Start") sets the game's private hold state before it
            -- reaches CombatRemoteClient.Fire("M1","HoldActivated"). Use the
            -- exported M1 module itself to clear that state and fire the real M1;
            -- do not depend on cross-scope helper locals.
            if action == "M1" and func == "HoldActivated" then
                local m1Module =
                    type(activeRuntime.getNativeM1Module) == "function"
                    and activeRuntime.getNativeM1Module()
                    or nil

                if not m1Module
                    or type(m1Module.OnM1Activated) ~= "function"
                    or type(m1Module.Hold) ~= "function"
                then
                    if type(activeDebug) == "function" then
                        activeDebug("AP_BREAKER_M1_NATIVE_FAIL", {
                            phase = "HoldActivated",
                        }, true)
                    end

                    return hookState.original(action, func, ...)
                end

                -- One physical LMB press can cause the game to emit many fresh
                -- HoldActivated calls. Main40 treated every one as a new manual
                -- tap, cancelled the previous animation gate, and started the next
                -- combo swing before the prior AnimationTrack.Ended. Swallow every
                -- repeat until the physical button is actually released.
                if activeRuntime.manualM1PhysicalHeld == true then
                    activeRuntime.internalM1HoldStop = true
                    pcall(m1Module.Hold, "Stop")
                    activeRuntime.internalM1HoldStop = false
                    activeRuntime.manualM1NativeRepeatSuppress =
                        (tonumber(activeRuntime.manualM1NativeRepeatSuppress) or 0) + 1

                    if type(activeDebug) == "function" then
                        activeDebug("AP_BREAKER_HOLD_NATIVE_REPEAT_SUPPRESS", {
                            count = activeRuntime.manualM1NativeRepeatSuppress,
                            token = activeRuntime.manualM1LoopToken,
                        }, true)
                    end

                    return true
                end

                activeRuntime.manualM1PhysicalHeld = true
                activeRuntime.manualM1PhysicalSerial =
                    (tonumber(activeRuntime.manualM1PhysicalSerial) or 0) + 1

                -- Clear the private hold flag/M1Hold attribute using the game's
                -- own stopHoldIfActive implementation.
                activeRuntime.internalM1HoldStop = true
                local okStop, stopError = pcall(m1Module.Hold, "Stop")
                activeRuntime.internalM1HoldStop = false

                if not okStop then
                    activeRuntime.manualM1PhysicalHeld = false

                    if type(activeDebug) == "function" then
                        activeDebug("AP_BREAKER_M1_NATIVE_FAIL", {
                            phase = "HoldStop",
                            error = tostring(stopError),
                        }, true)
                    end

                    return hookState.original(action, func, ...)
                end

                activeRuntime.manualM1LoopToken += 1
                local loopToken = activeRuntime.manualM1LoopToken
                activeRuntime.manualM1LoopActive = true

                local function tryRealM1(source)
                    if activeFlags.desync_auto_parry_breaker ~= true
                        or activeRuntime.manualM1LoopToken ~= loopToken
                    then
                        return false
                    end

                    local player =
                        game:GetService("Players").LocalPlayer
                    local currentCharacter =
                        player and player.Character or nil

                    if not currentCharacter
                        or not currentCharacter.Parent
                        or currentCharacter:GetAttribute("Equip") ~= true
                        or currentCharacter:GetAttribute("Ragdoll") == true
                        or currentCharacter:GetAttribute("Downed") == true
                    then
                        return false
                    end

                    -- Buffer rapid manual clicks to the game's real M1 cadence.
                    -- Recompute after every wait because another concurrent input
                    -- may have just completed its pre-roll / genuine swing.
                    for _ = 1, 3 do
                        local nowBuffer = os.clock()
                        local readyAt = math.max(
                            tonumber(activeRuntime.m1PreRollBusyUntil) or 0,
                            tonumber(activeRuntime.nextBufferedM1At) or 0
                        )
                        local remaining = readyAt - nowBuffer

                        if remaining <= 0 then
                            break
                        end

                        task.wait(math.min(remaining + 0.006, 1.30))
                    end

                    local baitFired = false
                    if type(activeRuntime.fireInputTrap) == "function" then
                        local okBait, resultBait = pcall(
                            activeRuntime.fireInputTrap,
                            "M1",
                            source,
                            false
                        )
                        baitFired =
                            okBait and resultBait == true
                    end

                    local guardCommitted = false
                    if baitFired
                        and type(activeRuntime.waitForCommitWindow) == "function"
                    then
                        guardCommitted =
                            activeRuntime.waitForCommitWindow(
                                "M1",
                                source
                            ) == true
                    end

                    local okAttack, attackError =
                        pcall(m1Module.OnM1Activated)

                    if type(activeDebug) == "function" then
                        activeDebug("AP_BREAKER_M1_REAL_FIRE", {
                            source = source,
                            callOk = okAttack,
                            error = okAttack and "" or tostring(attackError),
                            baitFired = baitFired,
                            guardCommitted = guardCommitted,
                            token = loopToken,
                        }, true)
                    end

                    return okAttack
                end

                -- Main410: manual tapping and held LMB share the same cadence.
                -- If a player spam-clicks before the previous genuine M1 fully
                -- ends, do not let that fresh physical press bypass the animation
                -- gate. A held press may wait and continue; a quick spam tap will
                -- be cancelled naturally by InputEnded before it can fire.
                local firstCycleBefore =
                    tonumber(activeRuntime.realM1CycleSerial) or 0
                local cadenceBlocked, cadenceReason, cadenceSerial, cadenceRemaining =
                    activeRuntime.isManualM1CadenceBlocked()

                if not cadenceBlocked then
                    tryRealM1("manual-tap")
                else
                    activeRuntime.manualM1CadenceSuppress =
                        (tonumber(activeRuntime.manualM1CadenceSuppress) or 0) + 1

                    if type(activeDebug) == "function" then
                        activeDebug("AP_BREAKER_MANUAL_CADENCE_SUPPRESS", {
                            count = activeRuntime.manualM1CadenceSuppress,
                            reason = tostring(cadenceReason or ""),
                            cycle = tonumber(cadenceSerial) or 0,
                            remaining = tonumber(cadenceRemaining) or 0,
                            token = loopToken,
                        }, true)
                    end
                end

                -- Holding LMB still works, but it cannot run faster than the
                -- same full-animation cadence used by deliberate manual taps.
                task.spawn(function()
                    local inputService =
                        game:GetService("UserInputService")
                    local cycleBefore = firstCycleBefore

                    if cadenceBlocked then
                        local cadenceReady, cadenceWaitReason =
                            activeRuntime.waitForManualM1Cadence(loopToken)

                        if not cadenceReady then
                            if type(activeDebug) == "function" then
                                activeDebug("AP_BREAKER_MANUAL_CADENCE_WAIT", {
                                    ready = false,
                                    reason = tostring(cadenceWaitReason or ""),
                                    token = loopToken,
                                }, true)
                            end
                            return
                        end

                        if activeRuntime.manualM1PhysicalHeld ~= true
                            or not inputService:IsMouseButtonPressed(
                                Enum.UserInputType.MouseButton1
                            )
                        then
                            return
                        end

                        if type(activeRuntime.waitForHeldM1Ready) == "function"
                            and not activeRuntime.waitForHeldM1Ready(loopToken)
                        then
                            return
                        end

                        if activeRuntime.manualM1PhysicalHeld ~= true
                            or not inputService:IsMouseButtonPressed(
                                Enum.UserInputType.MouseButton1
                            )
                        then
                            return
                        end

                        cycleBefore =
                            tonumber(activeRuntime.realM1CycleSerial) or cycleBefore

                        if type(activeDebug) == "function" then
                            activeDebug("AP_BREAKER_HOLD_NEXT_CLICK", {
                                previousCycle = cycleBefore,
                                nextFrom = cycleBefore,
                                source = "cadence-gated-press",
                                token = loopToken,
                            }, true)
                        end

                        tryRealM1("manual-hold-cadence-gated")
                    end

                    while activeFlags.desync_auto_parry_breaker == true
                        and activeRuntime.manualM1LoopToken == loopToken
                        and activeRuntime.manualM1PhysicalHeld == true
                        and inputService:IsMouseButtonPressed(
                            Enum.UserInputType.MouseButton1
                        )
                    do
                        local completed, cycleSerial, reason =
                            activeRuntime.waitForRealM1Cycle(
                                cycleBefore,
                                loopToken
                            )

                        if not completed then
                            if type(activeDebug) == "function" then
                                activeDebug("AP_BREAKER_HOLD_CYCLE_WAIT", {
                                    completed = false,
                                    cycle = cycleSerial,
                                    reason = reason,
                                    token = loopToken,
                                }, true)
                            end
                            break
                        end

                        if activeRuntime.manualM1PhysicalHeld ~= true
                            or not inputService:IsMouseButtonPressed(
                                Enum.UserInputType.MouseButton1
                            )
                        then
                            break
                        end

                        if type(activeRuntime.waitForHeldM1Ready) == "function"
                            and not activeRuntime.waitForHeldM1Ready(loopToken)
                        then
                            break
                        end

                        if activeRuntime.manualM1PhysicalHeld ~= true
                            or not inputService:IsMouseButtonPressed(
                                Enum.UserInputType.MouseButton1
                            )
                        then
                            break
                        end

                        cycleBefore =
                            tonumber(activeRuntime.realM1CycleSerial) or cycleSerial

                        if type(activeDebug) == "function" then
                            activeDebug("AP_BREAKER_HOLD_NEXT_CLICK", {
                                previousCycle = cycleSerial,
                                nextFrom = cycleBefore,
                                source = "animation-ended",
                                token = loopToken,
                            }, true)
                        end

                        tryRealM1("manual-hold-animation-ended")
                    end

                    if activeRuntime.manualM1LoopToken == loopToken then
                        activeRuntime.manualM1LoopActive = false
                    end
                end)

                return true
            end

            if action == "M1" and func == "HoldDeactivated" then
                if activeRuntime.internalM1HoldStop == true then
                    return true
                end

                if activeRuntime.manualM1PhysicalHeld == true
                    or activeRuntime.manualM1LoopActive == true
                then
                    activeRuntime.manualM1PhysicalHeld = false
                    activeRuntime.manualM1LoopToken += 1
                    activeRuntime.manualM1LoopActive = false

                    if type(activeDebug) == "function" then
                        activeDebug("AP_BREAKER_HOLD_PHYSICAL_RELEASE", {
                            source = "remote",
                            token = activeRuntime.manualM1LoopToken,
                        }, true)
                    end

                    return true
                end

                return hookState.original(action, func, ...)
            end

            if (action == "M1" or action == "M2")
                and func == "ServerCheck"
            then
                -- Main322 intentionally leaves real M1 ServerCheck untouched.
                -- Main322 proved that delaying ServerCheck also delays the real
                -- server hitbox, so proof-based AP still receives a full reaction
                -- window and simply reparries the shifted attack.

                local skipUntil =
                    tonumber(activeRuntime.skipServerCheckUntil[action]) or 0

                if os.clock() <= skipUntil then
                    activeRuntime.skipServerCheckUntil[action] = 0
                    return hookState.original(action, func, ...)
                end

                -- Prime only from the game's accepted manual M2 ServerCheck.
                if action == "M2" then
                    local baitFired = false
                    if type(activeRuntime.fireInputTrap) == "function" then
                        local okBait, resultBait = pcall(
                            activeRuntime.fireInputTrap,
                            "M2",
                            "manual-remote",
                            false
                        )
                        baitFired = okBait and resultBait == true
                    end

                    if not baitFired then
                        return hookState.original(action, func, ...)
                    end

                    local args = table.pack(...)
                    activeRuntime.serverSplitSerial += 1
                    local splitSerial =
                        activeRuntime.serverSplitSerial

                    task.spawn(function()
                        local guardCommitted = false

                        if type(activeRuntime.waitForCommitWindow) == "function" then
                            guardCommitted =
                                activeRuntime.waitForCommitWindow(
                                    "M2",
                                    "manual-remote"
                                ) == true
                        end

                        local okFire, result = pcall(
                            hookState.original,
                            action,
                            func,
                            table.unpack(args, 1, args.n)
                        )

                        if type(activeDebug) == "function" then
                            activeDebug("AP_BREAKER_REAL_DELAY_FIRE", {
                                attack = "M2",
                                phase = "guard-adaptive",
                                guardCommitted = guardCommitted,
                                ok = okFire,
                                result = result,
                                serial = splitSerial,
                            }, true)
                        end
                    end)

                    return true
                end
            end

            return hookState.original(action, func, ...)
        end

        sharedEnv.__SilentAPBreakerCombatRemoteHook45 = hookState
        combatRemote.Fire = hookState.wrapper
        runtime.combatRemoteHookState = hookState

        debugLog("AP_BREAKER_REMOTE_HOOK", {
            installed = true,
        }, true)

        return true
    end

    runtime.ensureAnimator = function()
        local character = getCharacter()
        local humanoid, animator = aeGetAnimator(character)
        if not character or not humanoid or not animator then
            return nil, nil
        end

        if runtime.character ~= character
            or runtime.animator ~= animator
        then
            runtime.clearTracks()
            runtime.disconnectAnimator()
            runtime.character = character
            runtime.animator = animator
            runtime.style = tostring(getStyle(character) or "")

            runtime.animationConnection = animator.AnimationPlayed:Connect(function(track)
                if Flags.desync_auto_parry_breaker ~= true
                    or runtime.baitTracks[track]
                    or runtime.passiveTracks[track]
                then
                    return
                end

                local attackType, realCombo = classifyTrack(character, track)
                if attackType ~= "M1" and attackType ~= "M2" then
                    return
                end

                if attackType == "M1"
                    and tonumber(realCombo)
                    and tonumber(realCombo) >= 1
                    and tonumber(realCombo) <= 4
                then
                    runtime.lastObservedM1Combo = tonumber(realCombo)
                    runtime.lastObservedM1At = os.clock()

                    local speed =
                        math.max(tonumber(track.Speed) or 1, 0.20)
                    local cooldown =
                        tonumber(realCombo) == 4
                        and (1.25 / speed)
                        or (0.45 / speed)

                    runtime.nextBufferedM1At =
                        os.clock() + cooldown

                    -- Hold pacing is tied to the genuine local animation itself,
                    -- not a guessed cooldown. Bait tracks returned above and never
                    -- reach this block.
                    runtime.realM1CycleSerial += 1
                    local m1CycleSerial = runtime.realM1CycleSerial
                    runtime.realM1ActiveTrack = track
                    local m1CycleStartedAt = os.clock()
                    runtime.realM1StartedAt = m1CycleStartedAt

                    debugLog("AP_BREAKER_HOLD_CYCLE_START", {
                        cycle = m1CycleSerial,
                        combo = tonumber(realCombo) or 0,
                        speed = tonumber(track.Speed) or 1,
                        length = tonumber(track.Length) or 0,
                    }, true)

                    local completed = false
                    local endedConnection
                    local stoppedConnection

                    local function finishM1Cycle(reason)
                        if completed then
                            return
                        end
                        completed = true

                        if endedConnection then
                            pcall(function() endedConnection:Disconnect() end)
                        end
                        if stoppedConnection then
                            pcall(function() stoppedConnection:Disconnect() end)
                        end

                        runtime.realM1CompletedSerial = math.max(
                            tonumber(runtime.realM1CompletedSerial) or 0,
                            m1CycleSerial
                        )
                        if runtime.realM1ActiveTrack == track then
                            runtime.realM1ActiveTrack = nil
                        end
                        runtime.realM1EndedAt = os.clock()

                        debugLog("AP_BREAKER_HOLD_CYCLE_END", {
                            cycle = m1CycleSerial,
                            combo = tonumber(realCombo) or 0,
                            reason = tostring(reason or ""),
                            age = os.clock() - m1CycleStartedAt,
                        }, true)
                    end

                    local okEnded, endedSignal = pcall(function()
                        return track.Ended
                    end)
                    if okEnded and endedSignal then
                        -- Ended fires only after the animation has completely
                        -- finished moving its joints, including fade-out. This is
                        -- the gate used for the next held-LMB click.
                        endedConnection = endedSignal:Connect(function()
                            finishM1Cycle("ended")
                        end)
                    else
                        -- Conservative compatibility fallback only when Ended is
                        -- unavailable. Never race Ended with an early Stopped edge.
                        stoppedConnection = track.Stopped:Connect(function()
                            task.delay(0.120, function()
                                if not completed and track.IsPlaying ~= true then
                                    finishM1Cycle("stopped-fallback")
                                end
                            end)
                        end)
                    end
                end

                runtime.lastBreakerRealAt = os.clock()

                runtime.serial += 1
                local serial = runtime.serial

                -- Genuine attack detected: immediately release any bait-only pose
                -- stabilization so the real M1/M2 remains completely visible.
                runtime.clearVisualMask()

                -- Blend/stop any currently active fake bait as soon as the real
                -- swing begins. This prevents two attack tracks from fighting over
                -- the same joints and causing the shaky/jittery character motion.
                for baitTrack, marker in pairs(runtime.baitTracks) do
                    if baitTrack
                        and marker ~= true
                        and baitTrack ~= track
                    then
                        runtime.baitTracks[baitTrack] = true
                        pcall(function()
                            if baitTrack.IsPlaying then
                                baitTrack:AdjustWeight(0, 0.015)
                                baitTrack:Stop(0.025)
                            end
                        end)
                    end
                end

                -- Do not modify TimePosition, Speed, or WeightTarget/WeightCurrent
                -- of the real attack. AP Breaker is not allowed to make genuine
                -- combat animations invisible.
                debugLog("AP_BREAKER_REAL_VISIBLE", {
                    attack = attackType,
                    combo = tonumber(realCombo) or 0,
                    serial = serial,
                    speed = tonumber(track.Speed) or 1,
                }, true)
            end)
        end

        return character, animator
    end

    runtime.ensureBaits = function()
        local character, animator = runtime.ensureAnimator()
        if not character or not animator then
            return false
        end

        local style = tostring(getStyle(character) or "")
        if runtime.style ~= style then
            runtime.clearTracks()
            runtime.style = style
        end

        if #runtime.cachedTracks > 0 then
            return true
        end

        local folder
        pcall(function()
            folder = CombatAnimationUtils.GetCombatAnimsFolderForPlayer(LocalPlayer)
        end)
        if not folder then
            return false
        end

        local animations = {}
        for _, object in ipairs(folder:GetDescendants()) do
            if object:IsA("Animation") then
                local attackType, combo = classifyAnimationName(object.Name)
                if attackType == "M1" or attackType == "M2" then
                    animations[#animations + 1] = {
                        animation = object,
                        attackType = attackType,
                        combo = tonumber(combo) or 0,
                        animationName = object.Name,
                    }
                end
            end
        end

        table.sort(animations, function(a, b)
            if tostring(a.attackType) ~= tostring(b.attackType) then
                return tostring(a.attackType) < tostring(b.attackType)
            end
            if a.combo == b.combo then
                return tostring(a.animation.Name) < tostring(b.animation.Name)
            end
            return a.combo < b.combo
        end)

        for _, info in ipairs(animations) do
            if #runtime.cachedTracks >= 10 then
                break
            end

            local ok, track = pcall(animator.LoadAnimation, animator, info.animation)
            if ok and track then
                pcall(function()
                    track.Looped = false
                    track.Priority = runtime.priority()
                end)
                runtime.baitTracks[track] = true
                runtime.cachedTracks[#runtime.cachedTracks + 1] = {
                    track = track,
                    attackType = info.attackType,
                    combo = info.combo,
                    animationName = info.animationName,
                }
            end
        end

        return #runtime.cachedTracks > 0
    end

    runtime.fireBait = function(mode, realAttackType, trapSerial)
        if Flags.desync_auto_parry_breaker ~= true
            or not runtime.ensureBaits()
        then
            return false
        end

        local character = runtime.character
        if not character or not character.Parent then
            return false
        end

        if character:GetAttribute("Downed") == true
            or character:GetAttribute("Ragdoll") == true
            or character:GetAttribute("Stunned") == true
            or character:GetAttribute("CantAnything") == true
        then
            return false
        end

        local chosen
        local chosenIndex
        local chosenInfo
        local chosenSignature = ""
        local chosenSignatureGap = math.huge
        local count = #runtime.cachedTracks
        local desiredAttackType = tostring(realAttackType or "")
        local predictedCombo = 0

        if desiredAttackType == "M1" then
            local nowCombo = os.clock()
            if nowCombo - (tonumber(runtime.lastObservedM1At) or 0) > 1.55 then
                predictedCombo = 1
            else
                predictedCombo =
                    ((tonumber(runtime.lastObservedM1Combo) or 0) % 4) + 1
            end
        end

        -- Main322 first tries to match the exact signature of the genuine
        -- attack that will begin ~70-100ms later. For M1 this is the predicted
        -- next combo animation; for M2 use an actual M2 signature when available.
        -- This makes the later genuine AnimationPlayed event look like a duplicate
        -- restart to animation+proof resolvers instead of a clean second threat.
        local nowBait = os.clock()
        local oldestUsedAt = math.huge

        if desiredAttackType == "M1" and predictedCombo > 0 then
            for index, item in ipairs(runtime.cachedTracks) do
                if item
                    and item.track
                    and item.track.IsPlaying ~= true
                    and item.attackType == "M1"
                    and tonumber(item.combo) == predictedCombo
                then
                    chosen = item.track
                    chosenIndex = index
                    chosenInfo = item
                    chosenSignature =
                        tostring(item.animationName or "M1")
                        .. "|M1|"
                        .. tostring(predictedCombo)
                    local lastUsedAt =
                        tonumber(runtime.baitSignatureLastUsed[chosenSignature])
                        or -math.huge
                    chosenSignatureGap =
                        lastUsedAt == -math.huge
                        and math.huge
                        or nowBait - lastUsedAt
                    break
                end
            end
        elseif desiredAttackType == "M2" then
            for index, item in ipairs(runtime.cachedTracks) do
                if item
                    and item.track
                    and item.track.IsPlaying ~= true
                    and item.attackType == "M2"
                then
                    local signature =
                        tostring(item.animationName or "M2")
                        .. "|M2|"
                        .. tostring(tonumber(item.combo) or 0)
                    local lastUsedAt =
                        tonumber(runtime.baitSignatureLastUsed[signature])
                        or -math.huge

                    if lastUsedAt < oldestUsedAt then
                        oldestUsedAt = lastUsedAt
                        chosen = item.track
                        chosenIndex = index
                        chosenInfo = item
                        chosenSignature = signature
                        chosenSignatureGap =
                            lastUsedAt == -math.huge
                            and math.huge
                            or nowBait - lastUsedAt
                    end
                end
            end
        end

        -- Fallback: least-recently-used M1 signature. This preserves the old
        -- breaker behavior for styles where an exact M2/next-combo animation is
        -- unavailable, while avoiding rapid same-signature restart patterns.
        if not chosen then
            oldestUsedAt = math.huge

            for index, item in ipairs(runtime.cachedTracks) do
                if item
                    and item.track
                    and item.track.IsPlaying ~= true
                    and item.attackType == "M1"
                then
                    local signature =
                        tostring(item.animationName or "M1")
                        .. "|M1|"
                        .. tostring(tonumber(item.combo) or 0)
                    local lastUsedAt =
                        tonumber(runtime.baitSignatureLastUsed[signature])
                        or -math.huge

                    if lastUsedAt < oldestUsedAt then
                        oldestUsedAt = lastUsedAt
                        chosen = item.track
                        chosenIndex = index
                        chosenInfo = item
                        chosenSignature = signature
                        chosenSignatureGap =
                            lastUsedAt == -math.huge
                            and math.huge
                            or nowBait - lastUsedAt
                    end
                end
            end
        end

        if not chosen then
            return false
        end

        runtime.baitCursor = chosenIndex or runtime.baitCursor
        runtime.baitSignatureSerial += 1
        runtime.baitSignatureLastUsed[chosenSignature] = nowBait

        local configuredSpeed = math.clamp(
            (tonumber(Flags.desync_ap_breaker_speed) or 100) / 100,
            0.25,
            2.0
        )
        local isCommitTrap = mode == "commit"

        -- Use normal playback only. No TimePosition phase jump.
        local speed = configuredSpeed
        if isCommitTrap then
            speed = math.clamp(
                math.max(configuredSpeed, 1.50),
                0.25,
                1.65
            )
        end
        local weight = math.clamp(
            (tonumber(Flags.desync_ap_breaker_target_weight) or 100) / 100,
            0,
            1
        )
        local fade = math.clamp(
            (tonumber(Flags.desync_ap_breaker_fade_time) or 10) / 1000,
            0,
            0.10
        )

        local maskVisual =
            Flags.desync_ap_breaker_mask_visual == true

        local phaseAdvance = 0
        local sourceHitTL = 0

        if chosenInfo then
            local styleKey = tostring(getStyle(character) or "")
            local speedMultiplier = math.clamp(
                tonumber(getSpeedMultiplier(character)) or 1,
                0.2,
                3
            )

            pcall(function()
                sourceHitTL = CombatConfig.GetScaledStyleM1HitboxDelay(
                    styleKey,
                    math.clamp(
                        tonumber(chosenInfo.combo) or 1,
                        1,
                        4
                    ),
                    speedMultiplier
                )
            end)
        end

        sourceHitTL = tonumber(sourceHitTL) or 0
        if sourceHitTL <= 0 then
            sourceHitTL = 0.30
        end

        local naturalContactDelay = math.clamp(
            sourceHitTL / math.max(speed, 0.05),
            0.10,
            0.40
        )

        local baitStopDelay = math.clamp(
            naturalContactDelay + 0.085,
            0.235,
            0.39
        )

        if isCommitTrap then
            runtime.lastCommitBaitAt = os.clock()
            runtime.lastCommitContactDelay = naturalContactDelay
            runtime.lastCommitStopDelay = baitStopDelay
        end

        -- The current combat rig exposes no Motor6D/Bone transforms to this
        -- collector. Keep Mask Visual jitter-free by lowering only the bait's
        -- animation weight. The genuine M1/M2 remains completely untouched.
        runtime.clearVisualMask()

        local playWeight =
            maskVisual
            and math.min(weight, 0.025)
            or weight

        pcall(function()
            chosen.Priority =
                isCommitTrap
                and Enum.AnimationPriority.Action4
                or runtime.priority()
            chosen.TimePosition = 0
            chosen:Play(fade, playWeight, speed)
        end)

        runtime.serial += 1
        local serial = runtime.serial
        runtime.baitTracks[chosen] = serial

        task.delay(isCommitTrap and baitStopDelay or 0.18, function()
            if runtime.baitTracks[chosen] ~= serial then
                return
            end
            pcall(function()
                chosen:Stop(0.01)
            end)
            runtime.baitTracks[chosen] = true
        end)

        if isCommitTrap then
            debugLog("AP_BREAKER_SOURCE_SYNC", {
                attack = tostring(realAttackType or ""),
                strategy = "same_signature_duplicate_preroll",
                decoyAttack = chosenInfo and chosenInfo.attackType or "",
                decoyCombo = chosenInfo and chosenInfo.combo or 0,
                decoySignature = chosenSignature,
                signatureGap = chosenSignatureGap,
                signatureSerial = runtime.baitSignatureSerial,
                realAttack = desiredAttackType,
                predictedCombo = predictedCombo,
                phaseAdvance = 0,
                sourceHitTL = sourceHitTL,
                naturalContactDelay = naturalContactDelay,
                baitStopDelay = baitStopDelay,
                maskVisual = maskVisual,
                playWeight = playWeight,
                trapSerial = tonumber(trapSerial) or 0,
            }, true)

            debugLog("AP_BREAKER_COMMIT_TRAP", {
                attack = tostring(realAttackType or ""),
                baitSpeed = speed,
                configuredSpeed = configuredSpeed,
                phaseAdvance = 0,
                trapSerial = tonumber(trapSerial) or 0,
                decoySignature = chosenSignature,
                signatureGap = chosenSignatureGap,
                signatureSerial = runtime.baitSignatureSerial,
                weight = weight,
                playWeight = playWeight,
                priority = tostring(
                    isCommitTrap
                    and Enum.AnimationPriority.Action4
                    or runtime.priority()
                ),
            }, true)
        end

        return true
    end

    runtime.fireInputTrap = function(attackType, trapSource, scripted)
        if Flags.desync_auto_parry_breaker ~= true then
            return false
        end

        attackType = tostring(attackType or "")
        trapSource = tostring(trapSource or "unknown")
        scripted = scripted == true
        if attackType ~= "M1" and attackType ~= "M2" then
            return false
        end

        local character = getCharacter()
        if not character or not character.Parent then
            return false
        end

        if character:GetAttribute("Equip") ~= true
            or character:GetAttribute("Ragdoll") == true
            or character:GetAttribute("Downed") == true
            or character:GetAttribute("GuardBroken") == true
            or character:GetAttribute("Blocking") == true
            or character:GetAttribute("ParryAttackLockout") == true
            or character:GetAttribute("BlockAttackLockout") == true
            or character:GetAttribute("GrappleWinnerStun") == true
            or character:GetAttribute("Grappling") == true
            or character:GetAttribute("Greenzone") == true
            or character:GetAttribute("RpCombatLocked") == true
            or (
                character:GetAttribute("CantAnything") == true
                and character:GetAttribute("CombatRecovery") ~= true
            )
        then
            return false
        end

        if attackType == "M2" then
            if character:GetAttribute("Stunned") == true
                or character:GetAttribute("M2Cooldown") == true
                or character:GetAttribute("CombatAttacking") == true
            then
                return false
            end

            -- Raw RMB edges can arrive while the game's private M2 readiness
            -- boolean is still false. Those clicks never produce ServerCheck,
            -- so emitting a breaker decoy for them only pollutes the opponent's
            -- AP state. Scripted callers already perform this readiness check.
            if not scripted then
                local m2Module = getCombatModule("M2")
                if m2Module
                    and type(m2Module.OnM2Activated) == "function"
                then
                    local internalReady =
                        getCompatUpvalue(m2Module.OnM2Activated, 2)
                    if internalReady == false then
                        debugLog("AP_BREAKER_TRAP_SKIP", {
                            attack = attackType,
                            source = trapSource,
                            reason = "m2_internal_not_ready",
                        }, true)
                        return false
                    end
                end
            end
        else
            if character:GetAttribute("M1Cooldown") == true
                or character:GetAttribute("M1") == true
                or character:GetAttribute("M2") == true
                or character:GetAttribute("PendingM2") == true
                or character:GetAttribute("CombatAttacking") == true
            then
                return false
            end
        end

        local now = os.clock()
        if now - (tonumber(runtime.lastInputTrapAt) or 0) < 0.075 then
            return false
        end

        runtime.commitTrapSerial += 1
        local trapSerial = runtime.commitTrapSerial
        runtime.lastInputTrapAt = now
        runtime.lastInputTrapAttack = attackType
        runtime.lastCommitTrapAt = now

        local fired = runtime.fireBait("commit", attackType, trapSerial)
        if fired then
            local quietWindow = attackType == "M2" and 0.52 or 0.40
            runtime.baitPauseUntil = math.max(
                tonumber(runtime.baitPauseUntil) or 0,
                now + quietWindow
            )
            debugLog("AP_BREAKER_SINGLE_TRAP", {
                attack = attackType,
                source = trapSource,
                scripted = scripted,
                trapSerial = trapSerial,
                quietWindow = quietWindow,
            }, true)
        end

        return fired
    end

    Menu._MarkAutoParryScriptedAttack = function(attackType, source)
        attackType = tostring(attackType or "")
        source = tostring(source or "scripted")

        if attackType ~= "M1" and attackType ~= "M2" then
            return false
        end

        local state = Menu._AutoParryLocalAttackDebug
        if state then
            state.scriptedType = attackType
            state.scriptedSource = source
            state.scriptedUntil = os.clock() + 0.80

            if attackType == "M1" then
                state.scriptedM1Count =
                    (tonumber(state.scriptedM1Count) or 0) + 1
            else
                state.scriptedM2Count =
                    (tonumber(state.scriptedM2Count) or 0) + 1
            end
        end

        -- Main322: scripted M1/M2 use the same duplicate-window pre-roll path.
        local fired = runtime.fireInputTrap(
            attackType,
            source,
            true
        )

        debugLog("AP_BREAKER_SCRIPTED_TRAP", {
            attack = attackType,
            source = source,
            fired = fired == true,
        }, true)

        return fired
    end

    Menu._ScriptRuntime:Track(RunService.PreSimulation:Connect(function()
        if Flags.desync_auto_parry_breaker ~= true
            or Flags.desync_ap_breaker_mask_visual ~= true
        then
            if runtime.visualMaskUntil ~= 0
                or next(runtime.visualMaskPose) ~= nil
            then
                runtime.clearVisualMask()
            end
            return
        end

        if os.clock() > (tonumber(runtime.visualMaskUntil) or 0) then
            if next(runtime.visualMaskPose) ~= nil then
                runtime.clearVisualMask()
            end
            return
        end

        for motor, transform in pairs(runtime.visualMaskPose) do
            if motor and motor.Parent then
                pcall(function()
                    motor.Transform = transform
                end)
            else
                runtime.visualMaskPose[motor] = nil
            end
        end
    end))

    Menu._ScriptRuntime:Track(RunService.Heartbeat:Connect(function()
        if Flags.desync_auto_parry_breaker ~= true then
            runtime.nextBaitAt = 0
            runtime.clearVisualMask()
            if next(runtime.passiveTracks) ~= nil then
                runtime.releaseAllRealTracks("breaker_disabled")
            end
            return
        end

        runtime.ensureCombatRemoteHook()
        runtime.ensureAnimator()

        -- Never emit a free-running bait stream. Main307 still did this when
        -- Passive was enabled, which continuously refreshed the opponent AP's live
        -- threat/guard state. Real M1/M2 animations are never hidden anymore;
        -- Mask Visual only stabilizes bait-induced joint twitch. The breaker stays
        -- one false commit per actual attack in every mode.
        runtime.nextBaitAt = 0
        return
    end))

    runtime.ensureCombatRemoteHook()

    Menu._ScriptRuntime:Track(LocalPlayer.CharacterAdded:Connect(function()
        runtime.releaseAllRealTracks("character_reset")
        runtime.clearTracks()
        runtime.disconnectAnimator()
        runtime.character = nil
        runtime.style = ""
        runtime.nextBaitAt = 0
        runtime.baitPauseUntil = 0
        runtime.baitCursor = 0
        runtime.lastCommitTrapAt = 0
        runtime.lastInputTrapAt = 0
        runtime.lastInputTrapAttack = ""
        runtime.lastObservedM1Combo = 0
        runtime.lastObservedM1At = 0
        runtime.pendingM1HoldSerial += 1
        runtime.pendingM1ReleaseSerial = 0
        runtime.pendingM1ActivationSerial = 0
        runtime.manualM1LoopToken += 1
        runtime.manualM1LoopActive = false
        runtime.realM1CycleSerial = 0
        runtime.realM1CompletedSerial = 0
        runtime.realM1ActiveTrack = nil
        runtime.realM1StartedAt = 0
        runtime.realM1EndedAt = 0
        runtime.internalM1HoldStop = false
        runtime.m1ProofDelayArmedUntil = 0
        runtime.lastGuardTarget = nil
        runtime.lastGuardCommittedAt = 0
        runtime.skipServerCheckUntil.M1 = 0
        runtime.skipServerCheckUntil.M2 = 0
        runtime.lastCommitBaitAt = 0
        runtime.lastCommitContactDelay = 0.18
        runtime.lastCommitStopDelay = 0.23
        runtime.m1PreRollBusyUntil = 0
        runtime.nextBufferedM1At = 0
        runtime.lastBreakerRealAt = 0
        table.clear(runtime.baitSignatureLastUsed)
        runtime.baitSignatureSerial = 0
        local attackDebug = Menu._AutoParryLocalAttackDebug
        if attackDebug then
            attackDebug.scriptedType = ""
            attackDebug.scriptedSource = ""
            attackDebug.scriptedUntil = 0
        end
        runtime.clearVisualMask()
    end))
end

local function getEffectiveTrackSpeed(threat)
    local track = threat.track
    local trackSpeed = track and track.Speed
    local ownerSpeed = threat.speedMultiplier or getSpeedMultiplier(threat.owner)

    if typeof(ownerSpeed) == "number"
        and ownerSpeed >= 0.2
        and ownerSpeed <= 3.0
    then
        threat.speedMultiplier = ownerSpeed
    else
        ownerSpeed = 1
    end

    if threat.style == "hakari" then
        local ownerName = tostring(
            threat.ownerName
                or (threat.owner and threat.owner.Name)
                or ""
        )
        local now = os.clock()
        local observed = ownerName ~= ""
            and Menu._hakariObservedSpeed[ownerName]
            or nil

        if typeof(trackSpeed) == "number"
            and trackSpeed >= 1.08
            and trackSpeed <= 2.25
            and ownerName ~= ""
        then
            Menu._hakariObservedSpeed[ownerName] = {
                speed = trackSpeed,
                at = now,
            }
            observed = Menu._hakariObservedSpeed[ownerName]
        end

        if observed
            and now - (tonumber(observed.at) or 0) <= 1.40
            and (tonumber(observed.speed) or 1) > 1.08
            and (
                typeof(trackSpeed) ~= "number"
                or math.abs(trackSpeed - 1) <= 0.035
            )
        then
            trackSpeed = math.clamp(
                tonumber(observed.speed) or 1,
                1,
                2.25
            )
        end
    end

    if typeof(trackSpeed) == "number"
        and trackSpeed >= 0.2
        and trackSpeed <= 3.0
    then
        if math.abs(trackSpeed - 1) <= 0.025
            and math.abs(ownerSpeed - 1) > 0.015
        then
            return ownerSpeed
        end

        return trackSpeed
    end

    return ownerSpeed
end

;(function()
    local previous = Menu._WingChunCounterRuntime
    if previous and type(previous.cancelAll) == "function" then
        pcall(previous.cancelAll, "runtime_replace")
    end

    local Runtime = {}
    Menu._WingChunCounterRuntime = Runtime

    Runtime.serialByOwner = setmetatable({}, {__mode = "k"})
    Runtime.reservedThreats = setmetatable({}, {__mode = "k"})
    Runtime.activeUntil = 0
    Runtime.lastAttemptAt = 0

    local STARTUP_SECONDS = 7 / 60
    local ATTEMPT_GAP = 0.10
    local RESERVE_LEAD = 0.10
    local INPUT_HANDOFF_TIMEOUT = 0.085
    local CONFIRM_TIMEOUT = 0.18
    local POST_CONTACT_HOLD = 0.14

    local function getUpvalueValue(func, index)
        if type(func) ~= "function" then
            return nil
        end

        local getter = getupvalue or (debug and debug.getupvalue)
        if type(getter) ~= "function" then
            return nil
        end

        local packed = table.pack(pcall(getter, func, index))
        if packed[1] ~= true then
            return nil
        end

        if packed.n >= 3 then
            return packed[3]
        end
        return packed[2]
    end

    local function normalizeStyle(value)
        return string.lower(tostring(value or "")):gsub("[^%w]", "")
    end

    local function getLocalStyle(character)
        local ok, style = pcall(
            CombatAnimationUtils.GetPlayerCombatStyle,
            LocalPlayer
        )
        if ok and typeof(style) == "string" and style ~= "" then
            return normalizeStyle(style)
        end

        return normalizeStyle(getStyle(character))
    end

    local function getRange()
        return math.clamp(
            tonumber(Flags.ap_wingchun_counter_range) or 6.5,
            3,
            14
        )
    end

    local function getAimPoint()
        return math.clamp(
            (tonumber(Flags.ap_wingchun_counter_aim_point) or 35) / 100,
            0.10,
            0.80
        )
    end

    local function getWingChunConfig()
        local config
        pcall(function()
            config = CombatConfig.GetStyleConfig("wingchun")
        end)
        return type(config) == "table" and config or nil
    end

    local function getCounterWindow()
        local config = getWingChunConfig()
        local value = config and tonumber(config.M2CounterWindowDuration) or 0.58
        return math.clamp(value or 0.58, 0.20, 1.25)
    end

    local function isEnabled()
        if Flags.ap_wingchun_counter ~= true then
            return false
        end

        local character = getCharacter()
        if not character or not character.Parent then
            return false
        end

        if getLocalStyle(character) ~= "wingchun" then
            return false
        end

        local config = getWingChunConfig()
        return config ~= nil
            and config.M2RequiresCounterHit == true
    end

    local function distanceTo(owner)
        local character = getCharacter()
        local myRoot = getRoot(character)
        local ownerRoot = getRoot(owner)

        if not myRoot or not ownerRoot then
            return math.huge, math.huge
        end

        local delta = ownerRoot.Position - myRoot.Position
        return flat(delta).Magnitude, math.abs(delta.Y)
    end

    local function isGrabThreat(threat)
        if not threat or threat.attackType ~= "M2" then
            return false
        end

        local style = normalizeStyle(threat.style)
        if style == "wrestling" then
            return true
        end

        local label = string.lower(
            tostring(threat.animationName or threat.variant or "")
        )

        return string.find(label, "grab", 1, true) ~= nil
            or string.find(label, "grapple", 1, true) ~= nil
            or string.find(label, "throw", 1, true) ~= nil
            or string.find(label, "slam", 1, true) ~= nil
    end

    local function trackAlive(threat)
        local track = threat and threat.track
        if not track then
            return false
        end

        local ok, playing = pcall(function()
            return track.IsPlaying
        end)

        return ok and playing == true
    end

    local function currentAttackPresent(owner, threat)
        if not owner or not owner.Parent then
            return false
        end

        if threat and threat.serverConfirmed == true then
            return true
        end

        local track = threat and threat.track
        if track then
            local ok, playing = pcall(function()
                return track.IsPlaying
            end)
            if ok and playing == true then
                return true
            end
        end

        return owner:GetAttribute("M1") == true
            or owner:GetAttribute("M1Hold") == true
            or owner:GetAttribute("PendingM1") == true
            or owner:GetAttribute("M2") == true
            or owner:GetAttribute("PendingM2") == true
            or owner:GetAttribute("CombatAttacking") == true
    end

    local function countNearbyThreatOwners(primaryOwner)
        local character = getCharacter()
        local myRoot = getRoot(character)
        if not myRoot then
            return math.huge
        end

        local owners = setmetatable({}, {__mode = "k"})
        local scanRange = math.max(8, getRange() + 2.5)

        for _, activeThreat in pairs(animationThreats) do
            local owner = activeThreat and activeThreat.owner
            if owner
                and owner.Parent
                and owner ~= character
                and activeThreat.expired ~= true
                and activeThreat.counterStance ~= true
            then
                local ownerRoot = getRoot(owner)
                if ownerRoot
                    and flat(ownerRoot.Position - myRoot.Position).Magnitude <= scanRange
                    and currentAttackPresent(owner, activeThreat)
                then
                    owners[owner] = true
                end
            end
        end

        local playersFolder = Workspace:FindFirstChild("Players")
        if playersFolder then
            for _, owner in ipairs(playersFolder:GetChildren()) do
                if owner ~= character and owner.Parent then
                    local ownerRoot = getRoot(owner)
                    if ownerRoot
                        and flat(ownerRoot.Position - myRoot.Position).Magnitude <= scanRange
                        and currentAttackPresent(owner, nil)
                    then
                        owners[owner] = true
                    end
                end
            end
        end

        if primaryOwner
            and primaryOwner.Parent
            and next(owners) == nil
        then
            owners[primaryOwner] = true
        end

        local count = 0
        for _ in pairs(owners) do
            count += 1
        end
        return count
    end

    local function getTiming(threat)
        local hitTL = tonumber(threat.hitTL) or getThreatHitTimeline(threat)
        threat.hitTL = hitTL

        local track = threat.track
        local visualTime = 0
        local visualSpeed = 1
        local playing = false

        if track then
            pcall(function()
                visualTime = math.max(0, tonumber(track.TimePosition) or 0)
                visualSpeed = tonumber(track.Speed) or 1
                playing = track.IsPlaying == true
            end)
        end

        if visualSpeed < 0.2 or visualSpeed > 3 then
            visualSpeed = 1
        end

        local ownerSpeed = tonumber(threat.speedMultiplier)
            or getSpeedMultiplier(threat.owner)
            or 1

        if ownerSpeed < 0.2 or ownerSpeed > 3 then
            ownerSpeed = 1
        end

        local timingSpeed = getEffectiveTrackSpeed(threat)
        local timingTime = visualTime

        if not playing then
            timingSpeed = ownerSpeed
            local startedAt = tonumber(threat.animationStartedAt)
                or tonumber(threat.createdAt)
                or os.clock()
            timingTime = math.max(0, (os.clock() - startedAt) * timingSpeed)
        end

        local remaining =
            (hitTL - timingTime) / math.max(timingSpeed, 0.2)

        local impactAt = os.clock() + math.max(0, remaining)
        local window = getCounterWindow()
        local _, uplink = getUplink()
        local pingComp = math.max(0, tonumber(uplink) or 0)

        local fireLead =
            STARTUP_SECONDS
            + window * getAimPoint()
            + pingComp

        return remaining, impactAt, window, pingComp, fireLead
    end

    local function getM2ReadyIn(module)
        if not module or type(module.OnM2Activated) ~= "function" then
            return math.huge, "m2_module"
        end

        local activate = module.OnM2Activated
        local internalReady = getUpvalueValue(activate, 2)

        if internalReady == false then
            return math.huge, "m2_internal_cooldown"
        end

        local now = os.clock()
        local readyIn = 0
        local reason

        for index = 4, 6 do
            local lockUntil = getUpvalueValue(activate, index)
            if typeof(lockUntil) == "number" and lockUntil > now then
                local left = lockUntil - now
                if left > readyIn then
                    readyIn = left
                    reason = index == 4 and "parry_lockout"
                        or (index == 5 and "block_lockout" or "attempt_lockout")
                end
            end
        end

        return readyIn, reason
    end

    local function hardEligibility(character)
        if not character or not character.Parent then
            return false, "local_missing"
        end

        if not isEnabled() then
            return false, "disabled"
        end

        if character:GetAttribute("Equip") == false then
            return false, "not_equipped"
        end

        local humanoid = character:FindFirstChildOfClass("Humanoid")
        if not humanoid or humanoid.Health <= 0 then
            return false, "dead"
        end

        if character:GetAttribute("SpecTimeSlowed") == true then
            return false, "spec_time_slowed"
        end
        if character:GetAttribute("M2Cooldown") == true then
            return false, "m2_cooldown"
        end
        if character:GetAttribute("GuardBroken") == true then
            return false, "guard_broken"
        end
        if character:GetAttribute("CantAnything") == true
            and character:GetAttribute("CombatRecovery") ~= true
        then
            return false, "cant_anything"
        end
        if character:GetAttribute("Stunned") == true then
            return false, "stunned"
        end
        if character:GetAttribute("Ragdoll") == true then
            return false, "ragdoll"
        end
        if character:GetAttribute("GrappleWinnerStun") == true then
            return false, "grapple_winner_stun"
        end
        if character:GetAttribute("Grappling") == true then
            return false, "grappling"
        end
        if character:GetAttribute("Greenzone") == true then
            return false, "greenzone"
        end
        if character:GetAttribute("RpCombatLocked") == true then
            return false, "rp_combat_locked"
        end

        return true
    end

    local function transientBusy(character)
        if not character then
            return true, "local_missing"
        end

        if character:GetAttribute("M2") == true
            or character:GetAttribute("PendingM2") == true
        then
            return true, "m2_busy"
        end

        if character:GetAttribute("Blocking") == true
            or character:GetAttribute("PerfectBlocking") == true
        then
            return true, "blocking"
        end

        if character:GetAttribute("CombatAttacking") == true
            or character:GetAttribute("M1") == true
            or character:GetAttribute("M1Hold") == true
            or character:GetAttribute("PendingM1") == true
        then
            return true, "combat_attacking"
        end

        if character:GetAttribute("ParryAttackLockout") == true then
            return true, "parry_attack_lockout"
        end

        if character:GetAttribute("BlockAttackLockout") == true then
            return true, "block_attack_lockout"
        end

        return false
    end

    local function prepareInput(character)
        if not character or not character.Parent then
            return
        end

        if character:GetAttribute("Blocking") == true
            or character:GetAttribute("PerfectBlocking") == true
        then
            local block = getCombatModule("Block")
            if block and type(block.Unblock) == "function" then
                pcall(block.Unblock)
            end
        end

        if character:GetAttribute("M1") == true
            or character:GetAttribute("M1Hold") == true
            or character:GetAttribute("PendingM1") == true
            or character:GetAttribute("CombatAttacking") == true
        then
            local m1 = getCombatModule("M1")
            if m1 and type(m1.Hold) == "function" then
                pcall(m1.Hold, "Stop")
            end
        end
    end

    local function waitForInputHandoff(character, deadline)
        while os.clock() < deadline do
            local hardOk, hardReason = hardEligibility(character)
            if not hardOk then
                return false, hardReason
            end

            prepareInput(character)

            local busy, busyReason = transientBusy(character)
            if not busy then
                return true
            end

            RunService.Heartbeat:Wait()
        end

        local busy, busyReason = transientBusy(character)
        return not busy, busyReason or "input_handoff_timeout"
    end

    local function plausibleThreat(threat)
        local owner = threat and threat.owner
        if not owner or not owner.Parent then
            return false, "owner_missing"
        end

        local distance, heightDiff = distanceTo(owner)
        if distance > getRange() then
            return false, "range"
        end

        if heightDiff > AUTO_PARRY_MAX_HEIGHT_DIFF then
            return false, "height"
        end

        if not currentAttackPresent(owner, threat) then
            return false, "attack_ended"
        end

        local allowed, reason, context = passesThreatFilters(threat)
        if allowed then
            return true, "autoparry_geometry", context
        end

        local character = getCharacter()
        local myRoot = getRoot(character)
        local ownerRoot = getRoot(owner)

        if not myRoot or not ownerRoot then
            return false, "root_missing"
        end

        local toLocal = flat(myRoot.Position - ownerRoot.Position)
        local ownerLook = flat(ownerRoot.CFrame.LookVector)
        local facingDot = -1

        if toLocal.Magnitude > 0.1 and ownerLook.Magnitude > 0.1 then
            facingDot = math.clamp(ownerLook.Unit:Dot(toLocal.Unit), -1, 1)
        end

        local relativeVelocity =
            flat(ownerRoot.AssemblyLinearVelocity)
            - flat(myRoot.AssemblyLinearVelocity)

        local closing = 0
        if toLocal.Magnitude > 0.1 then
            closing = relativeVelocity:Dot(toLocal.Unit)
        end

        local closeEnough = distance <= math.min(getRange(), 3.75)
        local aimed = facingDot >= -0.15
        local approaching = closing >= 2.0

        if closeEnough or aimed or approaching or threat.serverConfirmed == true then
            return true, "counter_range_live", {
                distance = distance,
                heightDiff = heightDiff,
                attackerFacingDot = facingDot,
                closing = closing,
            }
        end

        return false, reason or "not_live_threat"
    end

    local function setReserved(threat, state, reason)
        if not threat then
            return
        end

        if state then
            Runtime.reservedThreats[threat] = true
            threat.wingChunCounterReserved = true
            threat.wingChunCounterReserveReason = reason or "timing"
        else
            Runtime.reservedThreats[threat] = nil
            threat.wingChunCounterReserved = false
            threat.wingChunCounterReserveReason = reason or "released"
        end
    end

    Runtime.cancelAll = function(reason)
        for threat in pairs(Runtime.reservedThreats) do
            setReserved(threat, false, reason or "cancel_all")
        end

        for owner in pairs(Runtime.serialByOwner) do
            Runtime.serialByOwner[owner] =
                (Runtime.serialByOwner[owner] or 0) + 1
        end

        Runtime.activeUntil = 0
    end

    Runtime.isEnabled = isEnabled
    Runtime.getRange = getRange
    Runtime.isHolding = function()
        return os.clock() <= (tonumber(Runtime.activeUntil) or 0)
    end

    Runtime.schedule = function(threat)
        if not threat
            or threat.source ~= "animation"
            or not threat.owner
            or not threat.owner.Parent
            or not threat.track
            or threat.counterStance == true
            or threat.expired == true
            or threat.fired == true
            or not isEnabled()
        then
            return false
        end

        if threat.attackType ~= "M1"
            and threat.attackType ~= "M2"
        then
            return false
        end

        if isGrabThreat(threat) then
            return false
        end

        local distance = distanceTo(threat.owner)
        if distance > getRange() then
            return false
        end

        local character = getCharacter()
        local hardOk, hardReason = hardEligibility(character)
        if not hardOk then
            debugLog("WINGCHUN_COUNTER_SKIP", {
                owner = threat.ownerName or threat.owner.Name,
                attack = threat.attackType or "",
                style = threat.style or "",
                reason = hardReason or "not_ready",
            })
            return false
        end

        local module = getCombatModule("M2")
        if not module or type(module.OnM2Activated) ~= "function" then
            return false
        end

        local readyIn, readyReason = getM2ReadyIn(module)
        if readyIn == math.huge then
            debugLog("WINGCHUN_COUNTER_SKIP", {
                owner = threat.ownerName or threat.owner.Name,
                attack = threat.attackType or "",
                style = threat.style or "",
                reason = readyReason or "m2_internal_cooldown",
            })
            return false
        end

        local owner = threat.owner
        Runtime.serialByOwner[owner] =
            (Runtime.serialByOwner[owner] or 0) + 1
        local serial = Runtime.serialByOwner[owner]

        task.spawn(function()
            local reserved = false

            local function cancel(reason)
                if reserved then
                    setReserved(threat, false, reason)
                end

                debugLog("WINGCHUN_COUNTER_SKIP", {
                    owner = threat.ownerName or (owner and owner.Name) or "",
                    attack = threat.attackType or "",
                    style = threat.style or "",
                    reason = reason or "cancelled",
                })
            end

            while true do
                if not isEnabled()
                    or not owner.Parent
                    or Runtime.serialByOwner[owner] ~= serial
                    or threat.expired == true
                    or threat.fired == true
                then
                    cancel("cancelled")
                    return
                end

                if not trackAlive(threat) then
                    cancel("track_stopped")
                    return
                end

                local remaining, _, _, _, fireLead = getTiming(threat)
                if remaining < -0.045 then
                    cancel("late")
                    return
                end

                local untilFire = remaining - fireLead

                if not reserved and untilFire <= RESERVE_LEAD then
                    local plausible, proof = plausibleThreat(threat)
                    if not plausible then
                        cancel("threat_" .. tostring(proof or "reject"))
                        return
                    end

                    local count = countNearbyThreatOwners(owner)
                    if count ~= 1 then
                        cancel("threat_count_" .. tostring(count))
                        return
                    end

                    setReserved(threat, true, "timing")
                    reserved = true

                    prepareInput(getCharacter())

                    debugLog("WINGCHUN_COUNTER_ARM", {
                        owner = threat.ownerName or owner.Name,
                        attack = threat.attackType or "",
                        style = threat.style or "",
                        range = getRange(),
                        aimPoint = math.floor(getAimPoint() * 100 + 0.5),
                        proof = proof or "",
                        fireInMs = math.floor(math.max(0, untilFire) * 1000 + 0.5),
                    }, true)
                end

                if reserved and untilFire <= 0.060 then
                    prepareInput(getCharacter())
                end

                if untilFire <= 0.002 then
                    break
                end

                task.wait(
                    math.min(
                        untilFire > 0.025 and 0.020 or 0.004,
                        math.max(0.001, untilFire * 0.50)
                    )
                )
            end

            if not reserved then
                local plausible, proof = plausibleThreat(threat)
                if not plausible then
                    cancel("threat_" .. tostring(proof or "reject"))
                    return
                end
                setReserved(threat, true, "final_timing")
                reserved = true
            end

            if isGrabThreat(threat) then
                cancel("grab")
                return
            end

            local count = countNearbyThreatOwners(owner)
            if count ~= 1 then
                cancel("threat_count_" .. tostring(count))
                return
            end

            local plausible, proof, context = plausibleThreat(threat)
            if not plausible then
                cancel("threat_" .. tostring(proof or "reject"))
                return
            end

            local localCharacter = getCharacter()
            local eligibleNow, eligibleReason = hardEligibility(localCharacter)
            if not eligibleNow then
                cancel(eligibleReason or "not_ready")
                return
            end

            prepareInput(localCharacter)

            local handoffDeadline = os.clock() + INPUT_HANDOFF_TIMEOUT
            local handoffOk, handoffReason =
                waitForInputHandoff(localCharacter, handoffDeadline)

            if not handoffOk then
                cancel(handoffReason or "input_handoff_timeout")
                return
            end

            module = getCombatModule("M2") or module
            if not module or type(module.OnM2Activated) ~= "function" then
                cancel("m2_module")
                return
            end

            local nativeReadyIn, nativeReason = getM2ReadyIn(module)
            if nativeReadyIn == math.huge then
                cancel(nativeReason or "m2_internal_cooldown")
                return
            end

            local _, impactAt, window, pingComp = getTiming(threat)
            local latestStart =
                impactAt - STARTUP_SECONDS - pingComp - 0.006

            while nativeReadyIn > 0.003
                and os.clock() < latestStart
            do
                RunService.Heartbeat:Wait()

                local stillOk, stillReason = hardEligibility(localCharacter)
                if not stillOk then
                    cancel(stillReason or "not_ready")
                    return
                end

                prepareInput(localCharacter)

                nativeReadyIn, nativeReason = getM2ReadyIn(module)
                if nativeReadyIn == math.huge then
                    cancel(nativeReason or "m2_internal_cooldown")
                    return
                end
            end

            if nativeReadyIn > 0.003 then
                cancel(nativeReason or "activation_window_missed")
                return
            end

            if os.clock() - Runtime.lastAttemptAt < ATTEMPT_GAP then
                cancel("attempt_gap")
                return
            end

            local beforeReady = getUpvalueValue(module.OnM2Activated, 2)
            local beforeStanceToken =
                localCharacter:GetAttribute("M2CounterStanceToken")
            local beforeActionToken =
                localCharacter:GetAttribute("CombatActionToken")
            local beforeCooldown =
                localCharacter:GetAttribute("M2Cooldown")

            Runtime.lastAttemptAt = os.clock()

            local marker = Menu and Menu._MarkAutoParryScriptedAttack
            if type(marker) == "function" then
                pcall(marker, "M2", "wingchun_counter_v3")
            end

            local okActivate, activateError =
                pcall(module.OnM2Activated)

            if not okActivate then
                cancel("activate_error:" .. tostring(activateError))
                return
            end

            local afterReady = getUpvalueValue(module.OnM2Activated, 2)
            local started =
                beforeReady == true and afterReady == false

            if not started then
                local confirmUntil = os.clock() + CONFIRM_TIMEOUT

                while os.clock() < confirmUntil do
                    RunService.Heartbeat:Wait()

                    local stanceToken =
                        localCharacter:GetAttribute("M2CounterStanceToken")
                    local actionToken =
                        localCharacter:GetAttribute("CombatActionToken")
                    local cooldown =
                        localCharacter:GetAttribute("M2Cooldown")

                    if stanceToken ~= beforeStanceToken
                        or actionToken ~= beforeActionToken
                        or (
                            beforeCooldown ~= cooldown
                            and (
                                cooldown == true
                                or (typeof(cooldown) == "number" and cooldown > 0)
                            )
                        )
                        or localCharacter:GetAttribute("M2") == true
                        or localCharacter:GetAttribute("PendingM2") == true
                    then
                        started = true
                        break
                    end
                end
            end

            if not started then
                cancel("no_start")
                return
            end

            setReserved(threat, false, "committed")
            reserved = false

            threat.wingChunCounterCommitted = true
            threat.wingChunCounterImpactAt = impactAt
            threat.wingChunCounterProof = proof
            threat.fired = true
            threat.firedAt = os.clock()

            Runtime.activeUntil = math.max(
                Runtime.activeUntil,
                impactAt + POST_CONTACT_HOLD,
                os.clock() + STARTUP_SECONDS + window + 0.04
            )

            AutoPunishRuntime.requestFaceLock(
                owner,
                math.max(0.40, math.max(0, impactAt - os.clock()) + 0.20),
                "wingchun-counter"
            )

            debugLog("WINGCHUN_COUNTER_FIRE", {
                owner = threat.ownerName or owner.Name,
                attack = threat.attackType or "",
                style = threat.style or "",
                distance = select(1, distanceTo(owner)),
                aimPoint = math.floor(getAimPoint() * 100 + 0.5),
                startupMs = math.floor(STARTUP_SECONDS * 1000 + 0.5),
                pingCompMs = math.floor(pingComp * 1000 + 0.5),
                windowMs = math.floor(window * 1000 + 0.5),
                contactInMs = math.floor(
                    math.max(0, impactAt - os.clock()) * 1000 + 0.5
                ),
                stanceTokenBefore = beforeStanceToken or "",
                stanceTokenAfter =
                    localCharacter:GetAttribute("M2CounterStanceToken") or "",
                proof = proof or "",
                facingDot =
                    context and context.attackerFacingDot or "",
            }, true)
        end)

        return true
    end
end)()

local function updateTurnRateFromPart(threat, part, now)
    if not part then
        return
    end

    local look = flat(part.CFrame.LookVector)

    if look.Magnitude <= 0.1 then
        return
    end

    look = look.Unit

    if threat.previousLook and threat.previousLook.Magnitude > 0.1 then
        local dt = math.max(now - (threat.previousLookAt or now), 1 / 240)
        local dot = math.clamp(threat.previousLook:Dot(look), -1, 1)
        local measured = math.acos(dot) / dt

        threat.turnRate = (threat.turnRate or measured) * 0.5 + measured * 0.5
    end

    threat.previousLook = look
    threat.previousLookAt = now
end

local function getBoxingCounterM2RangeContext(threat)
    if not threat
        or threat.attackType ~= "M2"
        or type(BoxingCounterRuntime.isEnabled) ~= "function"
        or BoxingCounterRuntime.isEnabled() ~= true
        or type(BoxingCounterRuntime.getRange) ~= "function"
    then
        return nil
    end

    local character = getCharacter()
    local myRoot = getRoot(character)
    local owner = threat.owner or resolveOwner(threat)
    local ownerRoot = getRoot(owner)

    if not character
        or not myRoot
        or not owner
        or not owner.Parent
        or not ownerRoot
        or owner.Name == localWorkspaceCharacterName
    then
        return nil
    end

    local delta = ownerRoot.Position - myRoot.Position
    local distance = flat(delta).Magnitude
    local heightDiff = math.abs(delta.Y)
    local counterRange = math.clamp(
        tonumber(BoxingCounterRuntime.getRange()) or 8,
        3,
        14
    )

    if distance > counterRange
        or heightDiff > AUTO_PARRY_MAX_HEIGHT_DIFF
    then
        return nil
    end

    return {
        character = character,
        myRoot = myRoot,
        owner = owner,
        ownerRoot = ownerRoot,
        distance = distance,
        heightDiff = heightDiff,
        boxingCounterM2Only = true,
    }
end


function Menu._ResolverTimingRuntime.hasStrongProof(threat)
    if not threat then
        return false
    end

    if threat.serverConfirmed == true then
        return true
    end

    local strength =
        tostring(
            threat.resolverProofStrength
            or ""
        )

    if strength == "server"
        or strength == "strong"
        or strength == "style-verified"
    then
        return true
    end

    local reason =
        tostring(
            threat.resolverProofReason
            or threat.apBreakerProofReason
            or ""
        )

    -- replicated-M1 / replicated-M2 are intentionally excluded here.
    -- They are useful timing evidence, but not strong enough to keep a
    -- 20-50 ms fake animation alive after the visual track has stopped.
    return reason == "m1-cooldown-edge"
        or reason == "m2-cooldown-edge"
        or reason == "combat-token-type"
        or reason == "combat-token-edge"
        or reason == "server-hitbox"
        or reason == "hakari-combat-animation"
end


function Menu._ResolverTimingRuntime.shouldHoldStoppedTrack(
    threat,
    now
)
    if not threat
        or threat.fired == true
    then
        return false
    end

    local contactAbs =
        tonumber(
            threat.expectedContactAbs
        )

    if not contactAbs then
        return false
    end

    if threat.resolverPunishRescue == true then
        return true
    end

    if Menu._ResolverTimingRuntime.hasStrongProof(
        threat
    ) then
        return true
    end

    local reason =
        tostring(
            threat.resolverProofReason
            or threat.apBreakerProofReason
            or ""
        )
    local weakReplicatedProof =
        reason == "replicated-M1"
        or reason == "replicated-M2"

    if not weakReplicatedProof then
        return false
    end

    local stoppedAt =
        tonumber(
            threat.trackStoppedAt
        ) or now
    local stopAge =
        stoppedAt
        - (
            tonumber(
                threat.createdAt
            ) or stoppedAt
        )
    local minimumWeakStopAge =
        threat.attackType == "M2"
        and Menu._ResolverProofRuntime.WEAK_STOP_HOLD_M2
        or Menu._ResolverProofRuntime.WEAK_STOP_HOLD_M1

    if stopAge < minimumWeakStopAge then
        return false
    end

    local state =
        threat.owner
        and resolverStateByCharacter[
            threat.owner
        ]
        or nil
    local timingObserved =
        state
        and (
            state.resolverTimingObserved
            == true
            or (
                tonumber(
                    state.resolverTimingActiveUntil
                ) or 0
            ) > now
        )

    -- Breaker/fake-animation mode is stricter, not looser: weak replicated
    -- proof may not extend a stopped track while a bait pattern is active.
    if Menu._APBreakerResolver.isActive(
        threat.owner,
        now
    ) then
        return false
    end

    return timingObserved == true
end


function Menu._ResolverTimingRuntime.tryStoppedTrackParry(
    threat,
    now
)
    if not Menu._ResolverTimingRuntime.shouldHoldStoppedTrack(
        threat,
        now
    ) then
        return false
    end

    local contactAbs =
        tonumber(
            threat.expectedContactAbs
        )

    if not contactAbs
        or now > contactAbs + 0.36
    then
        return false
    end

    local allowed,
        rejectReason,
        context =
            passesThreatFilters(threat)

    if not allowed then
        threat.lastReject =
            rejectReason
        return false
    end

    local ping, up =
        getUplink()
    local target,
        lookahead,
        pwin =
            predictionWindow()
    local pressAt =
        contactAbs
            - target
            - up
    local pressAtQ =
        pressAt
            - lookahead
    local prediction = {
        ping = ping,
        up = up,
        target = target,
        pwin = pwin,
        lookahead = lookahead,
        overlapDelay = 0,
        velLead = 0,
        closing = 0,
        side = 0,
        hitTL =
            threat.hitTL
            or getThreatHitTimeline(
                threat
            ),
        trackTime =
            threat.track
            and (
                tonumber(
                    threat.track.TimePosition
                ) or 0
            )
            or 0,
        trackSpeed =
            getEffectiveTrackSpeed(
                threat
            ),
        contactAbs = contactAbs,
        pressAt = pressAt,
        pressAtQ = pressAtQ,
    }

    if threat.apResolverStoppedScheduleLogged
        ~= true
    then
        threat.apResolverStoppedScheduleLogged =
            true

        debugLog(
            "AP_RESOLVER_STOP_SCHEDULE",
            {
                attack =
                    threat.attackType or "",
                owner =
                    threat.ownerName or "",
                style =
                    threat.style or "",
                combo =
                    threat.combo or 0,
                proof =
                    threat.resolverProofReason
                    or threat.apBreakerProofReason
                    or "",
                contactIn =
                    contactAbs - now,
                fireIn =
                    pressAtQ - now,
                timingBias =
                    Menu._ResolverTimingRuntime.getBias(
                        threat
                    ),
            },
            true
        )
    end

    if pressAtQ - now
        <= AUTOFACE_PARRY_PREARM
    then
        prepareAutoFaceForParry(
            threat,
            context,
            false
        )
    end

    if now >= pressAtQ then
        performParry(
            threat,
            prediction,
            context
        )
    end

    return true
end


local function updateAnimationThreat(threat, now)
    if threat.expired then
        releaseBehindParryFacingForThreat(threat, "expired")
        return false
    end

    if threat.fired then
        return now - (threat.firedAt or threat.createdAt) <= 0.65
    end

    if threat.serverHitboxEndedAt ~= nil then
        threat.lastReject =
            threat.lastReject
            or "server_hitbox_ended"
        threat.expired = true

        releaseBehindParryFacingForThreat(
            threat,
            "server_hitbox_ended"
        )

        return false
    end

    local track = threat.track
    local owner = threat.owner

    if not owner or not owner.Parent or not track then
        releaseBehindParryFacingForThreat(threat, "owner_or_track_missing")
        return false
    end

    if threat.attackType == "M2"
        and normalizeCombatStyleKey(tostring(
            threat.style or getStyle(owner) or ""
        )) == "cqc"
    then
        if threat.cqcM2InterruptOnlyLogged ~= true then
            threat.cqcM2InterruptOnlyLogged = true
            debugLog("AP_CQC_M2_INTERRUPT_ONLY", {
                owner = threat.ownerName or owner.Name or "",
                source = threat.source or "",
                window = (AutoPunishRuntime
                    and tonumber(AutoPunishRuntime.cqcM2CancelWindow))
                    or 0.50,
                attack = "M2",
                style = "cqc",
            }, true)
        end

        if track.IsPlaying == false then
            if Menu._AutoFaceRuntime
                and type(Menu._AutoFaceRuntime.invalidateThreat) == "function"
            then
                pcall(
                    Menu._AutoFaceRuntime.invalidateThreat,
                    threat,
                    "cqc_m2_stopped"
                )
            end
            threat.expired = true
            threat.lastReject = "cqc_m2_stopped"
            releaseBehindParryFacingForThreat(threat, "cqc_m2_stopped")
            return false
        end

        local cqcCancel =
            AutoPunishRuntime
            and AutoPunishRuntime.tryCqcM2M1Cancel

        if type(cqcCancel) == "function" then
            local okCancel, cancelError =
                pcall(cqcCancel, threat, now)

            if not okCancel then
                debugLog("CQC_M2_AUTOPUNISH_ERROR", {
                    owner = threat.ownerName or owner.Name or "",
                    attack = "M2",
                    style = "cqc",
                    error = tostring(cancelError),
                }, true)
            end
        else
            debugLog("CQC_M2_AUTOPUNISH_RUNTIME_MISSING", {
                owner = threat.ownerName or owner.Name or "",
                attack = "M2",
                style = "cqc",
            }, true)
        end

        return true
    end

    if Menu._APBreakerResolver.isActive(owner, now)
        and now - threat.createdAt
            >= Menu._APBreakerResolver.tuning.earlyRejectGrace
    then
        local breakerProof, breakerReason, breakerProofAt =
            getAnimationResolverProof(threat, now)

        if breakerProof then
            threat.apBreakerProofAt = breakerProofAt
            threat.apBreakerProofReason = breakerReason
        elseif breakerReason == "ap-breaker-decoy" then
            threat.lastReject = "resolver_ap_breaker_bait"
            threat.expired = true

            if Menu._AutoFaceRuntime
                and type(Menu._AutoFaceRuntime.invalidateThreat) == "function"
            then
                pcall(
                    Menu._AutoFaceRuntime.invalidateThreat,
                    threat,
                    "resolver_ap_breaker_bait"
                )
            end

            releaseBehindParryFacingForThreat(
                threat,
                "resolver_ap_breaker_bait"
            )
            Menu._APBreakerResolver.noteFake(threat, now, breakerReason)
            debugLog("RESOLVER_AP_BREAKER_BAIT", {
                attack = threat.attackType or "",
                animationName = threat.animationName or "",
                animationId = threat.animationId or "",
                owner = threat.ownerName or "",
                style = threat.style or "",
                combo = threat.combo or 0,
                age = now - threat.createdAt,
                reason = breakerReason,
            }, true)
            return false
        end
    end

    local wingChunRuntime = Menu._WingChunCounterRuntime

    if wingChunRuntime
        and type(wingChunRuntime.isHolding) == "function"
        and wingChunRuntime.isHolding()
    then
        threat.lastReject = "wingchun_counter_active"
        releaseBehindParryFacingForThreat(threat, "wingchun_counter_active")
        return true
    end

    if track.IsPlaying == false then
        if tryKyokushinM2StoppedTrackRescue(threat, now) then
            return true
        end

        if Menu._APTryHakariStoppedTrackRescue(threat, now) then
            return true
        end

        local liveServerHitbox =
            threat.serverConfirmed == true
            and threat.hitbox
            and threat.hitbox.Parent

        local handoffUntil =
            tonumber(
                threat.trackStopHandoffUntil
            ) or 0

        if not liveServerHitbox
            and now <= handoffUntil
        then
            Menu._ResolverTimingRuntime.tryStoppedTrackParry(
                threat,
                now
            )

            if threat.apAnimStopHandoffLogged
                ~= true
            then
                threat.apAnimStopHandoffLogged =
                    true

                debugLog(
                    "AP_ANIM_STOP_HANDOFF",
                    {
                        owner =
                            threat.ownerName
                            or "",
                        attack =
                            threat.attackType
                            or "",
                        style =
                            threat.style
                            or "",
                        handoffRemaining =
                            handoffUntil
                            - now,
                    },
                    true
                )
            end

            return true
        end

        if not liveServerHitbox then
            if Menu._AutoFaceRuntime
                and type(
                    Menu._AutoFaceRuntime
                        .invalidateThreat
                ) == "function"
            then
                pcall(
                    Menu._AutoFaceRuntime
                        .invalidateThreat,
                    threat,
                    "animation_stopped"
                )
            end

            threat.expired = true
            threat.lastReject =
                threat.lastReject
                or "animation_stopped"

            releaseBehindParryFacingForThreat(
                threat,
                "animation_stopped"
            )

            return false
        end
    end

    if threat.wingChunCounterReserved == true then
        threat.lastReject = "wingchun_counter_reserved"
        releaseBehindParryFacingForThreat(threat, "wingchun_counter_reserved")
        return true
    end

    local allowed, rejectReason, context = passesThreatFilters(threat)

    if threat.apLegacyCoreLogged ~= true then
        threat.apLegacyCoreLogged = true
        debugLog("AP_LEGACY_CORE", {
            attack = threat.attackType or "",
            combo = threat.combo or 0,
            owner = threat.ownerName or "",
            style = threat.style or "",
            allowed = allowed == true,
            reject = rejectReason or "",
            tracking = context
                and context.tracking == true
                or false,
            armReady = context
                and context.armReady == true
                or false,
            distance = context
                and context.distance
                or "",
            effectiveReach = context
                and context.effectiveReach
                or "",
        }, true)
    end

    local boxingCounterM2Only = false

    if not allowed
        and rejectReason == "reach"
        and threat.attackType == "M2"
    then
        local boxingContext = getBoxingCounterM2RangeContext(threat)
        if boxingContext then
            allowed = true
            context = boxingContext
            boxingCounterM2Only = true
            threat.lastReject = nil

            if threat.boxingCounterM2RangeLogged ~= true then
                threat.boxingCounterM2RangeLogged = true
                debugLog("BOXING_COUNTER_M2_RANGE", {
                    attack = "M2",
                    target = threat.ownerName or "",
                    enemyStyle = threat.style or "",
                    source = threat.source or "",
                    distance = boxingContext.distance,
                    counterRange = BoxingCounterRuntime.getRange(),
                    normalReject = "reach",
                })
            end
        end
    end

    if not allowed then
        threat.lastReject = rejectReason
        releaseBehindParryFacingForThreat(
            threat,
            "filter_" .. tostring(rejectReason or "reject")
        )
        return true
    end




    if threat.counterStance == true and threat.serverConfirmed ~= true then
        threat.lastReject = "counter_stance_wait"
        releaseBehindParryFacingForThreat(threat, "counter_stance_wait")
        return true
    end

    updateTurnRateFromPart(threat, context.ownerRoot, now)

    local hitTL = threat.hitTL or getThreatHitTimeline(threat)
    threat.hitTL = hitTL

    if threat.style == "cqc"
        and threat.attackType == "M1"
        and threat.cqcInitialFacingDot == nil
    then
        threat.cqcInitialFacingDot =
            tonumber(context.attackerFacingDot)
        threat.cqcInitialDistance =
            tonumber(context.distance)
    end

    local visualTrackTime =
        math.max(
            0,
            tonumber(track.TimePosition) or 0
        )
    local visualTrackSpeed =
        tonumber(track.Speed) or 1
    local ownerAttackSpeed =
        tonumber(
            threat.speedMultiplier
                or getSpeedMultiplier(threat.owner)
        ) or 1

    if ownerAttackSpeed < 0.2
        or ownerAttackSpeed > 3
    then
        ownerAttackSpeed = 1
    end

    if visualTrackSpeed < 0.2
        or visualTrackSpeed > 3
    then
        visualTrackSpeed =
            ownerAttackSpeed
    end

    local effectiveSpeed =
        getEffectiveTrackSpeed(threat)
    local combatTimelineSpeed =
        effectiveSpeed
    local timingTrackTime =
        visualTrackTime
    local speedDesynced =
        visualTrackSpeed >= 1.15
        and visualTrackSpeed
            > ownerAttackSpeed + 0.10

    if Menu._APBreakerResolver.isActive(owner, now) then
        local breakerProof, breakerReason, breakerProofAt =
            getAnimationResolverProof(threat, now)
        breakerProofAt = tonumber(breakerProofAt)

        if breakerProof
            and breakerProofAt
            and breakerProofAt <= now
            and breakerReason ~= "resolver-unavailable"
            and breakerReason ~= "hakari-combat-animation"
        then
            local proofTimeline = math.max(
                0,
                (now - breakerProofAt) * ownerAttackSpeed
            )
            local timelineDrift = math.abs(
                visualTrackTime - proofTimeline
            )
            local speedDrift = math.abs(
                visualTrackSpeed - ownerAttackSpeed
            )
            local delayedReplay =
                (tonumber(threat.animationStartedAt) or threat.createdAt)
                    > breakerProofAt + 0.035
            local frozenFrameZero =
                now - breakerProofAt > 0.050
                and visualTrackTime < 0.030

            if delayedReplay
                or frozenFrameZero
                or timelineDrift >= Menu._APBreakerResolver.tuning.timelineDrift
                or speedDrift >= 0.08
            then
                combatTimelineSpeed = ownerAttackSpeed
                timingTrackTime = proofTimeline
                speedDesynced = true
                threat.apBreakerTimelineAnchored = true
                threat.apBreakerProofAt = breakerProofAt
                threat.apBreakerProofReason = breakerReason

                if threat.apBreakerTimelineLogged ~= true then
                    threat.apBreakerTimelineLogged = true
                    debugLog("AP_BREAKER_TIMELINE_ANCHOR", {
                        attack = threat.attackType or "",
                        owner = threat.ownerName or "",
                        style = threat.style or "",
                        combo = threat.combo or 0,
                        proof = breakerReason,
                        visualTrackTime = visualTrackTime,
                        timingTrackTime = timingTrackTime,
                        visualTrackSpeed = visualTrackSpeed,
                        combatTimelineSpeed = combatTimelineSpeed,
                        timelineDrift = timelineDrift,
                        speedDrift = speedDrift,
                        delayedReplay = delayedReplay,
                        frozenFrameZero = frozenFrameZero,
                    }, true)
                end
            end
        end
    end

    if speedDesynced
        and threat.apBreakerTimelineAnchored ~= true
    then
        combatTimelineSpeed =
            ownerAttackSpeed
        local animationStartedAt =
            tonumber(
                threat.animationStartedAt
            ) or threat.createdAt

        timingTrackTime =
            math.max(
                0,
                (now - animationStartedAt)
                    * combatTimelineSpeed
            )

        if threat.apSpeedDesyncLogged
            ~= true
        then
            threat.apSpeedDesyncLogged = true
            debugLog("AP_SPEED_DESYNC", {
                attack =
                    threat.attackType or "",
                owner =
                    threat.ownerName or "",
                style =
                    threat.style or "",
                combo =
                    threat.combo or 0,
                visualTrackSpeed =
                    visualTrackSpeed,
                combatTimelineSpeed =
                    combatTimelineSpeed,
                visualTrackTime =
                    visualTrackTime,
                timingTrackTime =
                    timingTrackTime,
                hitTL = hitTL,
            }, true)
        end
    end




    local staleGrace = math.max(
        AP_SERVER_REPLICATION_LATE_GRACE,
        math.min(0.10, math.min(lastFrameDt, 0.04) * 2.5)
    )

    if threat.style == "kyokushin"
        and threat.attackType == "M2"
        and threat.source == "animation"
        and (
            threat.serverConfirmed == true
            or tostring(threat.resolverProofReason or "") == "replicated-M2"
            or tostring(threat.resolverProofReason or "") == "m2-cooldown-edge"
            or tostring(threat.resolverProofReason or "") == "combat-token-type"
            or tostring(threat.resolverProofReason or "") == "combat-token-edge"
        )
    then
        staleGrace = math.max(staleGrace, 0.24)
    end





    if threat.attackType == "M2" and threat.style == "capoeira" then
        local activeDuration = 0
        pcall(function()
            activeDuration = CombatConfig.GetStyleM2HitboxDuration("capoeira")
        end)

        if typeof(activeDuration) == "number" then
            staleGrace = math.max(
                staleGrace,
                math.clamp(activeDuration, 0, 0.35)
            )
        end
    end




    local positiveTimingBias = math.min(math.max(Menu._ResolverTimingRuntime.getBias(threat), 0), 0.18)

    if threat.serverConfirmed ~= true
        and timingTrackTime
            > hitTL
                + staleGrace
                + positiveTimingBias
    then
        threat.hakariProjectedUntil = 0
        threat.apProjectedUntil = 0
        threat.apIntentUntil = 0
        threat.lastReject = "stale_post_hit"

        if Menu._AutoFaceRuntime
            and type(
                Menu._AutoFaceRuntime
                    .invalidateThreat
            ) == "function"
        then
            pcall(
                Menu._AutoFaceRuntime
                    .invalidateThreat,
                threat,
                "stale_post_hit"
            )
        end

        threat.expired = true

        releaseBehindParryFacingForThreat(threat, "stale_post_hit")

        debugLog("ANIM_STALE_POST_HIT", {
            attack = threat.attackType,
            animationName = threat.animationName or "",
            owner = threat.ownerName or "",
            style = threat.style or "",
            hitTL = hitTL,
            trackTime = timingTrackTime,
            visualTrackTime =
                visualTrackTime,
            visualTrackSpeed =
                visualTrackSpeed,
            combatTimelineSpeed =
                combatTimelineSpeed,
            speedDesynced =
                speedDesynced,
            lateBy =
                timingTrackTime - hitTL,
            positiveTimingBias = positiveTimingBias,
        })

        return false
    end





    local timelineRemaining =
        (
            hitTL - timingTrackTime
        ) / math.max(
            combatTimelineSpeed,
            0.2
        )

    local overlapDelay, velLead, closing, side =
        computeLiveOverlapDelay(threat, context)

    local ping, up = getUplink()
    local target, lookahead, pwin = predictionWindow()
    local learnedBias = Menu._ResolverTimingRuntime.getBias(threat)

    local aggressiveStyle =
        isAggressiveAutoParryStyle(threat.style)




    local appliedMotionLead = aggressiveStyle
        and velLead
        or velLead * 0.50

    local contactAbs =
        now
        + timelineRemaining
        + overlapDelay
        + learnedBias
        - appliedMotionLead




    if threat.serverReactiveCorrection == true
        and threat.serverConfirmed == true
        and not threat.fired
    then
        contactAbs = math.min(
            contactAbs,
            tonumber(threat.serverReactiveAt) or now,
            now
        )
    end

    local hakariPressLead = 0
    if threat.style == "hakari" then
        if threat.attackType == "M2"
            and threat.hakariMomentum ~= true
        then
            hakariPressLead = 0
        else
            hakariPressLead =
                combatTimelineSpeed >= 1.20
                    and 0.018
                    or 0.008
        end
    end

    local kureNetworkTrim = 0
    if threat.style == "kure"
        and threat.attackType == "M1"
    then
        kureNetworkTrim = math.clamp(
            math.max(
                0,
                (tonumber(up) or 0)
                    - (tonumber(ping) or 0)
            ),
            0,
            0.024
        )
    end

    local cqcNetworkTrim = 0
    if threat.style == "cqc"
        and threat.attackType == "M1"
    then
        cqcNetworkTrim = math.clamp(
            math.max(
                0,
                (tonumber(up) or 0)
                    - (tonumber(ping) or 0)
            ) * 0.55,
            0,
            0.014
        )
    end

    local kyokushinM2TimingLead = 0
    local kyokushinM2StoppedTrackEarlyFireLead =
        KYOKUSHIN_M2_STOPPED_TRACK_EARLY_FIRE_LEAD
    local kyokushinM2AttackPreemptWindow =
        KYOKUSHIN_M2_ATTACK_PREEMPT_WINDOW
    local kyokushinM2AutoFacePrearm =
        KYOKUSHIN_M2_AUTOFACE_PREARM
    local kyokushinM2GuardHold =
        KYOKUSHIN_M2_GUARD_HOLD
    local kyokushinM2NetworkProfile = "default"

    if threat.style == "kyokushin"
        and threat.attackType == "M2"
    then
        kyokushinM2TimingLead,
        kyokushinM2StoppedTrackEarlyFireLead,
        kyokushinM2AttackPreemptWindow,
        kyokushinM2AutoFacePrearm,
        kyokushinM2GuardHold,
        kyokushinM2NetworkProfile =
            getKyokushinM2NetworkProfile(ping)

        threat.kyokushinM2TimingLead =
            kyokushinM2TimingLead
        threat.kyokushinM2StoppedTrackEarlyFireLead =
            kyokushinM2StoppedTrackEarlyFireLead
        threat.kyokushinM2AttackPreemptWindow =
            kyokushinM2AttackPreemptWindow
        threat.kyokushinM2AutoFacePrearm =
            kyokushinM2AutoFacePrearm
        threat.kyokushinM2GuardHold =
            kyokushinM2GuardHold
        threat.kyokushinM2NetworkProfile =
            kyokushinM2NetworkProfile
    end

    local kyokushinM1PreemptTrim =
        threat.style == "kyokushin"
        and threat.attackType == "M1"
        and tonumber(threat.combo) == 1
        and threat.apAttackPreempted == true
        and 0.030
        or 0

    local kyokushinM2HighPingTrim = 0

    local hakariM2PerfectTrim =
        threat.style == "hakari"
        and threat.attackType == "M2"
        and threat.hakariMomentum ~= true
        and (
            combatTimelineSpeed >= 1.20
            and 0.014
            or 0.022
        )
        or 0

    local pressAt =
        contactAbs
        - target
        - up
        - hakariPressLead
        - kyokushinM2TimingLead
        + kureNetworkTrim
        + cqcNetworkTrim
        + kyokushinM1PreemptTrim
        + kyokushinM2HighPingTrim
        + hakariM2PerfectTrim
    local pressAtQ = pressAt - lookahead

    local kyokushinM2ProposedPressAtQ = pressAtQ
    local kyokushinM2PreventedDelay = 0

    if threat.style == "kyokushin"
        and threat.attackType == "M2"
    then
        local previousContactAbs = tonumber(
            threat.kyokushinM2LatchedContactAbs
        )
        local previousPressAt = tonumber(
            threat.kyokushinM2LatchedPressAt
        )
        local previousPressAtQ = tonumber(
            threat.kyokushinM2LatchedPressAtQ
        )

        if previousContactAbs == nil
            or contactAbs < previousContactAbs
        then
            previousContactAbs = contactAbs
            threat.kyokushinM2LatchedContactAbs = contactAbs
        end

        if previousPressAt == nil
            or pressAt < previousPressAt
        then
            previousPressAt = pressAt
            threat.kyokushinM2LatchedPressAt = pressAt
        end

        if previousPressAtQ == nil
            or pressAtQ < previousPressAtQ
        then
            previousPressAtQ = pressAtQ
            threat.kyokushinM2LatchedPressAtQ = pressAtQ
        else
            kyokushinM2PreventedDelay = math.max(
                0,
                pressAtQ - previousPressAtQ
            )
        end

        contactAbs = math.min(contactAbs, previousContactAbs)
        pressAt = math.min(pressAt, previousPressAt)
        pressAtQ = math.min(pressAtQ, previousPressAtQ)

        if kyokushinM2PreventedDelay >= 0.012
            and threat.kyokushinM2ScheduleHoldLogged ~= true
        then
            threat.kyokushinM2ScheduleHoldLogged = true
            debugLog("AP_KYOKUSHIN_M2_SCHEDULE_HOLD", {
                owner = threat.ownerName or "",
                proposedFireIn = kyokushinM2ProposedPressAtQ - now,
                latchedFireIn = pressAtQ - now,
                preventedDelayMs =
                    math.floor(kyokushinM2PreventedDelay * 1000 + 0.5),
                proof = threat.resolverProofReason or "",
                networkProfile = kyokushinM2NetworkProfile,
            }, true)
        end
    end

    threat.expectedContactAbs = contactAbs

    local prediction = {
        ping = ping,
        up = up,
        target = target,
        pwin = pwin,
        lookahead = lookahead,
        overlapDelay = overlapDelay,
        velLead = velLead,
        appliedMotionLead = appliedMotionLead,
        closing = closing,
        side = side,
        hitTL = hitTL,
        trackTime = timingTrackTime,
        trackSpeed =
            combatTimelineSpeed,
        visualTrackTime =
            visualTrackTime,
        visualTrackSpeed =
            visualTrackSpeed,
        combatTimelineSpeed =
            combatTimelineSpeed,
        ownerAttackSpeed =
            ownerAttackSpeed,
        speedDesynced =
            speedDesynced,
        kureNetworkTrim =
            kureNetworkTrim,
        cqcNetworkTrim =
            cqcNetworkTrim,
        kyokushinM2TimingLead =
            kyokushinM2TimingLead,
        kyokushinM2StoppedTrackEarlyFireLead =
            kyokushinM2StoppedTrackEarlyFireLead,
        kyokushinM2AttackPreemptWindow =
            kyokushinM2AttackPreemptWindow,
        kyokushinM2AutoFacePrearm =
            kyokushinM2AutoFacePrearm,
        kyokushinM2GuardHold =
            kyokushinM2GuardHold,
        kyokushinM2NetworkProfile =
            kyokushinM2NetworkProfile,
        kyokushinM1PreemptTrim =
            kyokushinM1PreemptTrim,
        kyokushinM2HighPingTrim =
            kyokushinM2HighPingTrim,
        hakariM2PerfectTrim =
            hakariM2PerfectTrim,
        contactAbs = contactAbs,
        pressAt = pressAt,
        pressAtQ = pressAtQ,
    }

    if not threat.predictionLogged then
        threat.predictionLogged = true

        debugLog("PREDICT_ANIM", {
            attack = threat.attackType,
            animationName = threat.animationName or "",
            animationId = threat.animationId or "",
            owner = threat.ownerName or "",
            style = threat.style or "",
            combo = threat.combo or 0,
            variant = threat.variant or "",
            distance = context.distance,
            ping = ping,
            up = up,
            hitTL = hitTL,
            trackTime =
                timingTrackTime,
            trackSpeed =
                combatTimelineSpeed,
            visualTrackTime =
                visualTrackTime,
            visualTrackSpeed =
                visualTrackSpeed,
            rawTrackSpeed =
                visualTrackSpeed,
            ownerAttackSpeed =
                ownerAttackSpeed,
            combatTimelineSpeed =
                combatTimelineSpeed,
            speedDesynced =
                speedDesynced,
            target = target,
            lookahead = lookahead,
            overlapDelay = overlapDelay,
            velLead = velLead,
            appliedMotionLead = appliedMotionLead,
            closing = closing,
            timingBias = learnedBias,
            hakariPressLead = hakariPressLead,
            kureNetworkTrim = kureNetworkTrim,
            cqcNetworkTrim = cqcNetworkTrim,
            kyokushinM2TimingLead =
                kyokushinM2TimingLead,
            kyokushinM2NetworkProfile =
                kyokushinM2NetworkProfile,
            kyokushinM1PreemptTrim =
                kyokushinM1PreemptTrim,
            kyokushinM2HighPingTrim =
                kyokushinM2HighPingTrim,
            hakariM2PerfectTrim =
                hakariM2PerfectTrim,
            counterStance = threat.counterStance == true,
            hakariMomentum = threat.hakariMomentum == true,
            capoeiraRootLock = threat.attackType == "M2"
                and threat.style == "capoeira",
            fireIn = pressAtQ - now,
        })
    end

    if threat.style == "kyokushin"
        and threat.attackType == "M2"
        and threat.kyokushinM2ScheduleLogged ~= true
    then
        threat.kyokushinM2ScheduleLogged = true
        debugLog("AP_KYOKUSHIN_M2_SCHEDULE", {
            owner = threat.ownerName or "",
            distance = context.distance or "",
            hitTL = hitTL,
            fireIn = pressAtQ - now,
            ping = ping,
            networkProfile = kyokushinM2NetworkProfile,
            timingLead = kyokushinM2TimingLead,
            preemptWindow = kyokushinM2AttackPreemptWindow,
            autoFacePrearm = kyokushinM2AutoFacePrearm,
            stoppedTrackEarlyFireLead =
                kyokushinM2StoppedTrackEarlyFireLead,
            guardHold = kyokushinM2GuardHold,
        }, true)
    end

    if context.armReady ~= true
        and threat.attackType == "M1"
        and threat.source == "animation"
        and threat.serverConfirmed ~= true
        and threat.track
        and threat.track.IsPlaying ~= false
        and now >= pressAtQ
    then
        local edgeThreshold =
            tonumber(context.armThreshold)
            or tonumber(context.effectiveReach)
            or 0
        local edgeGap =
            math.max(
                0,
                (tonumber(context.distance) or math.huge)
                    - edgeThreshold
            )
        local facingDot =
            tonumber(context.attackerFacingDot)
            or -1
        local timelineLate =
            timingTrackTime
                - hitTL

        local edgeRescue =
            edgeThreshold > 0
            and edgeGap <= 1.20
            and facingDot >= 0.34
            and timelineLate <= 0.055

        if edgeRescue then
            context.armReady = true
            context.apEdgeRescue = true

            if threat.apEdgeRescueLogged ~= true then
                threat.apEdgeRescueLogged = true
                debugLog("AP_EDGE_RESCUE", {
                    attack = threat.attackType or "",
                    combo = threat.combo or 0,
                    owner = threat.ownerName or "",
                    style = threat.style or "",
                    distance = context.distance or "",
                    effectiveReach = context.effectiveReach or "",
                    armThreshold = edgeThreshold,
                    edgeGap = edgeGap,
                    attackerFacingDot = facingDot,
                    attackerFacingAngle =
                        context.attackerFacingAngle or "",
                    trackTime = timingTrackTime,
                    hitTL = hitTL,
                    lateBy = math.max(0, now - pressAtQ),
                }, true)
            end
        end
    end

    if context.tracking == true
        and context.armReady == true
        and threat.apArmReadyLogged ~= true
    then
        threat.apArmReadyLogged = true
        debugLog("AP_ARM_READY", {
            attack = threat.attackType or "",
            combo = threat.combo or 0,
            owner = threat.ownerName or "",
            style = threat.style or "",
            distance = context.distance,
            effectiveReach = context.effectiveReach or "",
            armSlack = context.armSlack or "",
            armThreshold = context.armThreshold or "",
            armCommitted =
                context.armCommitted == true,
            redirectActive =
                context.redirectActive == true,
            approachReady =
                context.approachReady == true,
            approachProjection =
                context.approachProjection or "",
            projectedContactDistance =
                context.projectedContactDistance or "",
            projectionClosing =
                context.projectionClosing or "",
            attackerFacingDot =
                context.attackerFacingDot or "",
            attackerFacingAngle =
                context.attackerFacingAngle or "",
            trackTime =
                timingTrackTime,
            visualTrackTime =
                visualTrackTime,
            visualTrackSpeed =
                visualTrackSpeed,
            combatTimelineSpeed =
                combatTimelineSpeed,
            speedDesynced =
                speedDesynced,
            hitTL = hitTL,
            fireIn = pressAtQ - now,
            lateBy = math.max(0, now - pressAtQ),
        }, true)
    end

    if Menu._AliCounterRuntime
        and type(
            Menu._AliCounterRuntime.try
        ) == "function"
        and now
            >= (
                tonumber(
                    threat.aliRuntimeErrorUntil
                ) or 0
            )
    then
        local okAli, aliHandled =
            pcall(
                Menu._AliCounterRuntime.try,
                threat,
                prediction,
                context,
                now
            )

        if okAli then
            threat.aliRuntimeErrorLogged =
                nil
            threat.aliRuntimeErrorUntil =
                0
        end

        if okAli and aliHandled == true then
            return true
        elseif not okAli then
            threat.aliRuntimeErrorUntil =
                now + 0.75

            if threat.aliRuntimeErrorLogged
                ~= true
            then
                threat.aliRuntimeErrorLogged =
                    true

                debugLog(
                    "ALI_COUNTER_RUNTIME_ERROR",
                    {
                        attack =
                            threat.attackType or "",
                        owner =
                            threat.ownerName or "",
                        style =
                            threat.style or "",
                        source =
                            threat.source or "",
                        error =
                            tostring(aliHandled),
                        backoffMs =
                            750,
                    },
                    true
                )
            end
        end
    end

    local dodgeForced = false

    if Menu._DodgeRuntime then
        local explicitSpecialSelected = false
        if type(
            Menu._DodgeRuntime.isExplicitSpecialThreat
        ) == "function"
        then
            local okSpecial, selectedSpecial = pcall(
                Menu._DodgeRuntime.isExplicitSpecialThreat,
                threat
            )
            explicitSpecialSelected =
                okSpecial and selectedSpecial == true
        end

        local prearmDistance = tonumber(
            context.projectedContactDistance
                or context.distance
        ) or math.huge
        local prearmThreshold =
            (tonumber(context.armThreshold)
                or tonumber(context.effectiveReach)
                or 0)
            + 2.25
        local priorityPrearm =
            (threat.mustDodgeSelected == true
                or explicitSpecialSelected)
            and prearmThreshold > 2.25
            and prearmDistance <= prearmThreshold

        local dodgeRuntimeEnabled =
            Flags.dodge_enable == true
            or explicitSpecialSelected

        if dodgeRuntimeEnabled
            and (
                context.armReady == true
                or priorityPrearm
            )
        then
            local dodgeResolverAllowed, dodgeResolverReason =
                getAnimationResolverProof(threat, now)

            if dodgeResolverAllowed then
                if (
                    explicitSpecialSelected
                    or threat.mustDodgeSelected == true
                )
                    and type(Menu._DodgeRuntime.try) == "function"
                then
                    local okDodge, dodgeCommitted = pcall(
                        Menu._DodgeRuntime.try,
                        threat,
                        prediction,
                        context,
                        now
                    )

                    if not okDodge then
                        debugLog("DODGE_RUNTIME_ERROR", {
                            attack = threat.attackType or "",
                            owner = threat.ownerName or "",
                            style = threat.style or "",
                            source = threat.source or "",
                            error = tostring(dodgeCommitted),
                            explicitSpecial = explicitSpecialSelected,
                        }, true)
                    elseif dodgeCommitted == true then
                        return true
                    end
                elseif Flags.dodge_enable == true
                    and Flags.dodge_if_cant_parry == true
                    and type(
                        Menu._DodgeRuntime.queuePassiveTry
                    ) == "function"
                then
                    Menu._DodgeRuntime.queuePassiveTry(
                        threat,
                        prediction,
                        context,
                        now
                    )
                end
            elseif threat.dodgeResolverReject ~= dodgeResolverReason then
                threat.dodgeResolverReject = dodgeResolverReason
                debugLog("DODGE_GATE", {
                    attack = threat.attackType or "",
                    owner = threat.ownerName or "",
                    style = threat.style or "",
                    source = threat.source or "",
                    reason = "resolver_" .. tostring(
                        dodgeResolverReason or "reject"
                    ),
                    explicitSpecial = explicitSpecialSelected,
                }, true)
            end
        end

        if type(Menu._DodgeRuntime.isForced) == "function" then
            dodgeForced = Menu._DodgeRuntime.isForced(threat)
        end
    end

    if Flags.ap_enable == true then
        local resolverAllowed, resolverReason =
            getAnimationResolverProof(
                threat,
                now
            )

        if not resolverAllowed
            and context.redirectActive == true
            and threat.attackType == "M1"
            and threat.source == "animation"
            and threat.track
            and threat.track.IsPlaying ~= false
        then
            resolverAllowed = true
            resolverReason =
                "late-redirect-animation"

            if threat.apRedirectProofLogged
                ~= true
            then
                threat.apRedirectProofLogged = true
                debugLog(
                    "AP_REDIRECT_PROOF",
                    {
                        attack =
                            threat.attackType or "",
                        owner =
                            threat.ownerName or "",
                        style =
                            threat.style or "",
                        combo =
                            threat.combo or 0,
                        distance =
                            context.distance or "",
                        attackerFacingDot =
                            context.attackerFacingDot or "",
                        attackerFacingAngle =
                            context.attackerFacingAngle or "",
                        visualTrackSpeed =
                            visualTrackSpeed,
                        combatTimelineSpeed =
                            combatTimelineSpeed,
                        fireIn =
                            pressAtQ - now,
                    },
                    true
                )
            end
        end

        if resolverAllowed then
            if threat.resolverProofReason ~= resolverReason then
                threat.resolverProofReason = resolverReason

                if resolverReason == "recognized-combat-animation" then
                    debugLog("AP_ANIMATION_READY", {
                        attack = threat.attackType or "",
                        owner = threat.ownerName or "",
                        style = threat.style or "",
                        combo = threat.combo or 0,
                        age = now - threat.createdAt,
                        serverConfirmed = false,
                    }, true)
                end

                debugLog("RESOLVER_PROOF", {
                    attack = threat.attackType,
                    animationName = threat.animationName or "",
                    animationId = threat.animationId or "",
                    owner = threat.ownerName or "",
                    style = threat.style or "",
                    reason = resolverReason,
                    proofStrength =
                        threat.resolverProofStrength
                        or "",
                    proofDelta =
                        threat.resolverProofDelta
                        or "",
                    age = now - threat.createdAt,
                    serverConfirmed = threat.serverConfirmed == true,
                })
            end

            if context.armReady ~= true
                and threat.style == "kyokushin"
                and threat.attackType == "M2"
                and now >= pressAtQ
            then
                local proofReason = tostring(
                    threat.resolverProofReason or ""
                )
                local verifiedKyokushinM2 =
                    threat.serverConfirmed == true
                    or proofReason == "replicated-M2"
                    or proofReason == "m2-cooldown-edge"
                    or proofReason == "combat-token-type"
                    or proofReason == "combat-token-edge"

                local dueThreshold =
                    tonumber(context.armThreshold)
                    or tonumber(threat.apCurrentArmThreshold)
                    or tonumber(context.effectiveReach)
                    or 0
                local dueDistance =
                    tonumber(context.distance) or math.huge
                local dueRangePad = 1.35

                if verifiedKyokushinM2
                    and dueThreshold > 0
                    and dueDistance <= dueThreshold + dueRangePad
                then
                    context.armReady = true
                    context.kyokushinM2DueReacquire = true

                    if threat.kyokushinM2DueReacquireLogged ~= true then
                        threat.kyokushinM2DueReacquireLogged = true
                        debugLog("AP_KYOKUSHIN_M2_DUE_REACQUIRE", {
                            owner = threat.ownerName or "",
                            distance = dueDistance,
                            armThreshold = dueThreshold,
                            rangePad = dueRangePad,
                            proof = proofReason,
                            lateBy = math.max(0, now - pressAtQ),
                        }, true)
                    end
                end
            end

            if context.armReady ~= true then
                threat.lastReject = "tracking_wait_reach"

                if now >= pressAtQ
                    and threat.apTrackingWaitLogged ~= true
                then
                    threat.apTrackingWaitLogged = true
                    debugLog("AP_TRACK_WAIT", {
                        attack = threat.attackType or "",
                        combo = threat.combo or 0,
                        owner = threat.ownerName or "",
                        style = threat.style or "",
                        distance = context.distance,
                        effectiveReach = context.effectiveReach or "",
                        armSlack = context.armSlack or "",
                        armThreshold = context.armThreshold or "",
                        armCommitted =
                            context.armCommitted == true,
                        redirectActive =
                            context.redirectActive == true,
                        approachReady =
                            context.approachReady == true,
                        approachProjection =
                            context.approachProjection or "",
                        projectedContactDistance =
                            context.projectedContactDistance or "",
                        projectionClosing =
                            context.projectionClosing or "",
                        attackerFacingDot =
                            context.attackerFacingDot or "",
                        attackerFacingAngle =
                            context.attackerFacingAngle or "",
                        trackTime =
                            timingTrackTime,
                        visualTrackTime =
                            visualTrackTime,
                        visualTrackSpeed =
                            visualTrackSpeed,
                        combatTimelineSpeed =
                            combatTimelineSpeed,
                        speedDesynced =
                            speedDesynced,
                        hitTL = hitTL,
                        fireIn = pressAtQ - now,
                        lateBy = math.max(0, now - pressAtQ),
                    }, true)
                end

                return true
            end

            threat.lastReject = nil

            local localDefenseCharacter =
                context.character
            local prepIn =
                pressAtQ - now

            local attackPreemptWindow =
                threat.style == "kyokushin"
                    and threat.attackType == "M2"
                    and (
                        tonumber(
                            prediction.kyokushinM2AttackPreemptWindow
                        )
                        or KYOKUSHIN_M2_ATTACK_PREEMPT_WINDOW
                    )
                or (
                    threat.style == "kure"
                        and threat.attackType == "M1"
                        and 0.22
                        or 0.12
                )

            if localDefenseCharacter
                and prepIn <= attackPreemptWindow
                and prepIn >= -0.10
            then
                local localM1Busy =
                    localDefenseCharacter:GetAttribute(
                        "M1"
                    ) == true
                    or localDefenseCharacter:GetAttribute(
                        "M1Hold"
                    ) == true
                    or localDefenseCharacter:GetAttribute(
                        "PendingM1"
                    ) == true

                local kureRepreempt =
                    threat.style == "kure"
                    and threat.attackType == "M1"
                    and threat.apAttackPreempted == true
                    and prepIn <= 0.10
                    and prepIn >= -0.04
                    and now
                        - (
                            tonumber(
                                threat.apAttackPreemptedAt
                            ) or 0
                        )
                        >= 0.035

                if localM1Busy
                    and (
                        threat.apAttackPreempted
                            ~= true
                        or kureRepreempt
                    )
                then
                    local m1Module =
                        getCombatModule("M1")
                    local stopped = false

                    if m1Module
                        and type(m1Module.Hold)
                            == "function"
                    then
                        stopped =
                            pcall(
                                m1Module.Hold,
                                "Stop"
                            )
                    end

                    if stopped == true then
                        threat.apAttackPreempted = true
                        threat.apAttackPreemptedAt = now

                        if threat.style == "kyokushin"
                            and threat.attackType == "M1"
                            and tonumber(threat.combo) == 1
                            and kyokushinM1PreemptTrim <= 0
                        then
                            kyokushinM1PreemptTrim = 0.030
                            pressAt += kyokushinM1PreemptTrim
                            pressAtQ += kyokushinM1PreemptTrim
                            prediction.pressAt = pressAt
                            prediction.pressAtQ = pressAtQ
                            prediction.kyokushinM1PreemptTrim =
                                kyokushinM1PreemptTrim
                        end
                    end

                    debugLog("AP_ATTACK_PREEMPT", {
                        attack =
                            threat.attackType or "",
                        owner =
                            threat.ownerName or "",
                        style =
                            threat.style or "",
                        combo =
                            threat.combo or 0,
                        prepIn = prepIn,
                        preemptWindow =
                            attackPreemptWindow,
                        stopped = stopped,
                        repreempt =
                            kureRepreempt == true,
                        localM1 =
                            localDefenseCharacter:GetAttribute(
                                "M1"
                            ) == true,
                        localM1Hold =
                            localDefenseCharacter:GetAttribute(
                                "M1Hold"
                            ) == true,
                        localPendingM1 =
                            localDefenseCharacter:GetAttribute(
                                "PendingM1"
                            ) == true,
                    }, true)
                end

                local localM2Busy =
                    localDefenseCharacter:GetAttribute(
                        "M2"
                    ) == true
                    or localDefenseCharacter:GetAttribute(
                        "PendingM2"
                    ) == true

                if localM2Busy
                    and threat.apM2ConflictLogged
                        ~= true
                then
                    threat.apM2ConflictLogged =
                        true
                    debugLog("AP_ATTACK_CONFLICT", {
                        attack =
                            threat.attackType or "",
                        owner =
                            threat.ownerName or "",
                        style =
                            threat.style or "",
                        combo =
                            threat.combo or 0,
                        prepIn = prepIn,
                        localM2 =
                            localDefenseCharacter:GetAttribute(
                                "M2"
                            ) == true,
                        localPendingM2 =
                            localDefenseCharacter:GetAttribute(
                                "PendingM2"
                            ) == true,
                    }, true)
                end
            end

            if not dodgeForced then
                local rearHold, rearCommitted =
                    tryRearEmergencyDodge(
                        threat,
                        prediction,
                        context,
                        now
                    )

                if rearCommitted or rearHold then
                    return true
                end

                if Menu._DodgeRuntime
                    and type(Menu._DodgeRuntime.isForced) == "function"
                then
                    dodgeForced = Menu._DodgeRuntime.isForced(threat)
                end
            end

            if not dodgeForced then
                if tryBoxingCounterSafe(threat, prediction, context, now) then
                    return true
                end
            elseif threat.dodgePriorityLogged ~= true then
                threat.dodgePriorityLogged = true
                debugLog("DODGE_PRIORITY", {
                    attack = threat.attackType or "",
                    owner = threat.ownerName or "",
                    style = threat.style or "",
                    source = threat.source or "",
                    reason = "boxing_counter_suppressed",
                }, true)
            end

            local boxingCounterArmed =
                threat.boxingCounterTaskArmed == true

            if boxingCounterM2Only then



                return true
            end

            local suppressParryForDodge = false
            if dodgeForced
                and Menu._DodgeRuntime
                and type(Menu._DodgeRuntime.shouldSuppressParry) == "function"
            then
                suppressParryForDodge =
                    Menu._DodgeRuntime.shouldSuppressParry(
                        threat,
                        prediction,
                        now
                    ) == true
            end

            if suppressParryForDodge then
                if threat.dodgeParryHoldLogged ~= true then
                    threat.dodgeParryHoldLogged = true
                    debugLog("DODGE_PRIORITY", {
                        attack = threat.attackType or "",
                        owner = threat.ownerName or "",
                        style = threat.style or "",
                        source = threat.source or "",
                        reason = "normal_parry_held_for_evasive",
                        contactIn = math.max(
                            0,
                            (tonumber(prediction.contactAbs) or now) - now
                        ),
                    }, true)
                end

                return true
            end

            local fireIn = pressAtQ - now
            local autoFacePrearmWindow =
                threat.style == "kyokushin"
                    and threat.attackType == "M2"
                    and (
                        tonumber(
                            prediction.kyokushinM2AutoFacePrearm
                        )
                        or KYOKUSHIN_M2_AUTOFACE_PREARM
                    )
                    or AUTOFACE_PARRY_PREARM

            if fireIn <= autoFacePrearmWindow then
                prepareAutoFaceForParry(threat, context, false)
            end

            if now >= pressAtQ then
                performParry(threat, prediction, context)
            end
        elseif now >= pressAtQ
            and context.armReady == true
        then
            local redirectWait =
                threat.attackType == "M1"
                and threat.source == "animation"
                and context.redirectCandidate == true
                and threat.track
                and threat.track.IsPlaying ~= false
                and timingTrackTime
                    <= hitTL + 0.18

            if redirectWait then
                threat.lastReject =
                    "redirect_wait"

                if threat.apRedirectWaitLogged
                    ~= true
                then
                    threat.apRedirectWaitLogged = true
                    debugLog(
                        "AP_REDIRECT_WAIT",
                        {
                            attack =
                                threat.attackType or "",
                            owner =
                                threat.ownerName or "",
                            style =
                                threat.style or "",
                            combo =
                                threat.combo or 0,
                            distance =
                                context.distance or "",
                            attackerFacingDot =
                                context.attackerFacingDot or "",
                            attackerFacingAngle =
                                context.attackerFacingAngle or "",
                            visualTrackTime =
                                visualTrackTime,
                            timingTrackTime =
                                timingTrackTime,
                            hitTL = hitTL,
                            fireIn =
                                pressAtQ - now,
                        },
                        true
                    )
                end

                return true
            end

            threat.lastReject = "resolver_fake_animation"

            if Menu._AutoFaceRuntime
                and type(
                    Menu._AutoFaceRuntime
                        .invalidateThreat
                ) == "function"
            then
                pcall(
                    Menu._AutoFaceRuntime
                        .invalidateThreat,
                    threat,
                    "resolver_fake_animation"
                )
            end

            Menu._APBreakerResolver.noteFake(threat, now, resolverReason)
            threat.expired = true

            releaseBehindParryFacingForThreat(threat, "resolver_fake_animation")

            debugLog("RESOLVER_FAKE_ANIM", {
                attack = threat.attackType,
                animationName = threat.animationName or "",
                animationId = threat.animationId or "",
                owner = threat.ownerName or "",
                style = threat.style or "",
                reason = resolverReason,
                age = now - threat.createdAt,
                hitTL = hitTL,
                trackTime =
                    timingTrackTime,
                visualTrackTime =
                    visualTrackTime,
                fireIn = pressAtQ - now,
            }, true)

            return false
        end
    end

    return true
end

local function updateServerFallback(threat, now)
    if threat.expired then
        releaseBehindParryFacingForThreat(threat, "server_expired")
        return false
    end

    if threat.fired then
        return false
    end

    local hitbox = threat.hitbox

    if not hitbox or not hitbox.Parent then
        releaseBehindParryFacingForThreat(threat, "server_hitbox_ended")
        return false
    end

    resolveOwner(threat)
    refreshAttackName(threat)

    if threat.attackType == "M2"
        and normalizeCombatStyleKey(tostring(
            threat.style or getStyle(threat.owner) or ""
        )) == "cqc"
    then
        threat.lastReject = "cqc_m2_interrupt_only"
        releaseBehindParryFacingForThreat(threat, "cqc_m2_interrupt_only")
        return true
    end

    local allowed, rejectReason, context = passesThreatFilters(threat)

    if not allowed then
        threat.lastReject = rejectReason
        releaseBehindParryFacingForThreat(
            threat,
            "server_filter_" .. tostring(rejectReason or "reject")
        )
        return true
    end

    updateTurnRateFromPart(threat, hitbox, now)

    local overlapDelay, velLead, closing, side =
        computeLiveOverlapDelay(threat, context)

    local ping, up = getUplink()
    local target, lookahead, pwin = predictionWindow()




    local contactAbs = now + overlapDelay
    local pressAt = contactAbs - target - up
    local pressAtQ = pressAt - lookahead

    local prediction = {
        ping = ping,
        up = up,
        target = target,
        pwin = pwin,
        lookahead = lookahead,
        overlapDelay = overlapDelay,
        velLead = velLead,
        closing = closing,
        side = side,
        hitTL = 0,
        trackTime = 0,
        trackSpeed = 0,
        contactAbs = contactAbs,
        pressAt = pressAt,
        pressAtQ = pressAtQ,
    }

    if not threat.predictionLogged then
        threat.predictionLogged = true

        debugLog("PREDICT_SERVER_FALLBACK", {
            attack = threat.attackType,
            attackName = threat.attackName or "",
            owner = threat.ownerName or "",
            style = threat.style or "",
            swingId = threat.swingId or "",
            actionToken = threat.actionToken or "",
            strikeDamage = threat.strikeDamage or "",
            distance = context.distance,
            ping = ping,
            up = up,
            target = target,
            overlapDelay = overlapDelay,
            fireIn = pressAtQ - now,
        })
    end

    if Menu._AliCounterRuntime
        and type(
            Menu._AliCounterRuntime.try
        ) == "function"
        and now
            >= (
                tonumber(
                    threat.aliRuntimeErrorUntil
                ) or 0
            )
    then
        local okAli, aliHandled =
            pcall(
                Menu._AliCounterRuntime.try,
                threat,
                prediction,
                context,
                now
            )

        if okAli then
            threat.aliRuntimeErrorLogged =
                nil
            threat.aliRuntimeErrorUntil =
                0
        end

        if okAli and aliHandled == true then
            return true
        elseif not okAli then
            threat.aliRuntimeErrorUntil =
                now + 0.75

            if threat.aliRuntimeErrorLogged
                ~= true
            then
                threat.aliRuntimeErrorLogged =
                    true

                debugLog(
                    "ALI_COUNTER_RUNTIME_ERROR",
                    {
                        attack =
                            threat.attackType or "",
                        owner =
                            threat.ownerName or "",
                        style =
                            threat.style or "",
                        source =
                            threat.source or "",
                        error =
                            tostring(aliHandled),
                        backoffMs =
                            750,
                    },
                    true
                )
            end
        end
    end

    local dodgeForced = false

    if Menu._DodgeRuntime then
        local serverAntiGrabSelected = false
        local explicitSpecialSelected = false

        if type(
            Menu._DodgeRuntime.isServerAntiGrabThreat
        ) == "function"
        then
            local okSpecial, selectedSpecial = pcall(
                Menu._DodgeRuntime.isServerAntiGrabThreat,
                threat
            )
            serverAntiGrabSelected =
                okSpecial and selectedSpecial == true
        end

        if type(
            Menu._DodgeRuntime.isExplicitSpecialThreat
        ) == "function"
        then
            local okExplicit, selectedExplicit = pcall(
                Menu._DodgeRuntime.isExplicitSpecialThreat,
                threat
            )
            explicitSpecialSelected =
                okExplicit and selectedExplicit == true
        end

        local dodgeRuntimeEnabled =
            Flags.dodge_enable == true
            or serverAntiGrabSelected
            or explicitSpecialSelected

        if dodgeRuntimeEnabled
            and (
                serverAntiGrabSelected
                or explicitSpecialSelected
                or threat.mustDodgeSelected == true
            )
            and type(Menu._DodgeRuntime.try) == "function"
        then
            local okDodge, dodgeCommitted = pcall(
                Menu._DodgeRuntime.try,
                threat,
                prediction,
                context,
                now
            )

            if not okDodge then
                debugLog("DODGE_RUNTIME_ERROR", {
                    attack = threat.attackType or "",
                    owner = threat.ownerName or "",
                    style = threat.style or "",
                    source = threat.source or "",
                    error = tostring(dodgeCommitted),
                    serverAntiGrab = serverAntiGrabSelected,
                    explicitSpecial = explicitSpecialSelected,
                }, true)
            elseif dodgeCommitted == true then
                return true
            end
        elseif Flags.dodge_enable == true
            and Flags.dodge_if_cant_parry == true
            and type(
                Menu._DodgeRuntime.queuePassiveTry
            ) == "function"
        then
            Menu._DodgeRuntime.queuePassiveTry(
                threat,
                prediction,
                context,
                now
            )
        end

        if type(Menu._DodgeRuntime.isForced) == "function" then
            dodgeForced = Menu._DodgeRuntime.isForced(threat)
        end
    end

    if Flags.ap_enable == true then
        local coverageKey = tostring(threat.ownerName or "")
            .. "|"
            .. tostring(threat.attackType or "")
        local coverage = Menu._apRecentParryCoverage[coverageKey]
        local coverageAge = coverage
            and now - (tonumber(coverage.at) or 0)
            or math.huge
        local releasedAge = coverage
            and coverage.releasedAt
            and now - coverage.releasedAt
            or math.huge

        local activeCoverage =
            autoBlocking == true
            and coverage
            and coverageAge >= 0
            and coverageAge <= (
                threat.style == "kyokushin"
                and threat.attackType == "M2"
                and 0.54
                or 0.28
            )

        local justReleasedSameParry =
            coverage
            and coverage.source == "animation"
            and releasedAge >= 0
            and releasedAge <= 0.18

        local hakariRecentAnimationCoverage =
            threat.style == "hakari"
            and coverage
            and coverage.source == "animation"
            and coverageAge >= 0
            and coverageAge <= 0.305

        if activeCoverage
            or justReleasedSameParry
            or hakariRecentAnimationCoverage
        then
            threat.fired = true
            threat.firedAt = now
            threat.lastReject = hakariRecentAnimationCoverage
                and "covered_by_hakari_animation"
                or (
                    justReleasedSameParry
                    and "covered_by_just_released_block"
                    or "covered_by_active_block"
                )
            releaseBehindParryFacingForThreat(
                threat,
                threat.lastReject
            )

            debugLog("SERVER_FALLBACK_COVERED", {
                attack = threat.attackType or "",
                owner = threat.ownerName or "",
                style = threat.style or "",
                swingId = threat.swingId or "",
                actionToken = threat.actionToken or "",
                coverageAge = coverageAge,
                coverageSource = coverage and coverage.source or "",
                coverageSerial = coverage and coverage.serial or "",
                releasedAge = releasedAge,
                coverageMode = hakariRecentAnimationCoverage
                    and "hakari_recent_animation"
                    or (
                        justReleasedSameParry
                        and "just_released_block"
                        or "active_block"
                    ),
                distance = context.distance,
            })

            return true
        end

        if not dodgeForced then
            local rearHold, rearCommitted =
                tryRearEmergencyDodge(
                    threat,
                    prediction,
                    context,
                    now
                )

            if rearCommitted or rearHold then
                return true
            end

            if Menu._DodgeRuntime
                and type(Menu._DodgeRuntime.isForced) == "function"
            then
                dodgeForced = Menu._DodgeRuntime.isForced(threat)
            end
        end

        if not dodgeForced then
            if tryBoxingCounterSafe(threat, prediction, context, now) then
                return true
            end
        elseif threat.dodgePriorityLogged ~= true then
            threat.dodgePriorityLogged = true
            debugLog("DODGE_PRIORITY", {
                attack = threat.attackType or "",
                owner = threat.ownerName or "",
                style = threat.style or "",
                source = threat.source or "",
                reason = "boxing_counter_suppressed",
            }, true)
        end

        local boxingCounterArmed =
            threat.boxingCounterTaskArmed == true

        local suppressParryForDodge = false
        if dodgeForced
            and Menu._DodgeRuntime
            and type(Menu._DodgeRuntime.shouldSuppressParry) == "function"
        then
            suppressParryForDodge =
                Menu._DodgeRuntime.shouldSuppressParry(
                    threat,
                    prediction,
                    now
                ) == true
        end

        if suppressParryForDodge then
            if threat.dodgeParryHoldLogged ~= true then
                threat.dodgeParryHoldLogged = true
                debugLog("DODGE_PRIORITY", {
                    attack = threat.attackType or "",
                    owner = threat.ownerName or "",
                    style = threat.style or "",
                    source = threat.source or "",
                    reason = "normal_parry_held_for_evasive",
                    contactIn = math.max(
                        0,
                        (tonumber(prediction.contactAbs) or now) - now
                    ),
                }, true)
            end

            return true
        end

        if pressAtQ - now <= AUTOFACE_PARRY_PREARM then
            prepareAutoFaceForParry(threat, context, false)
        end

        if now >= pressAtQ then
            performParry(threat, prediction, context)
        end
    end

    return true
end


function Menu._ResolverTimingRuntime.surfaceHasAnimation(
    character,
    attackType,
    edgeAt
)
    local mergeWindow =
        attackType == "M2"
        and 0.18
        or 0.14

    for _, existing in pairs(
        animationThreats
    ) do
        if existing
            and existing.expired ~= true
            and existing.owner == character
            and existing.attackType == attackType
            and math.abs(
                (
                    tonumber(
                        existing.createdAt
                    ) or edgeAt
                )
                - edgeAt
            ) <= mergeWindow
        then
            return true
        end
    end

    return false
end

function Menu._ResolverTimingRuntime.surfaceOwnerUnavailable(character)
    if not character or not character.Parent then
        return true, "owner_missing"
    end

    if character:GetAttribute("Downed") == true then
        return true, "downed"
    end

    if character:GetAttribute("Ragdoll") == true then
        return true, "ragdoll"
    end

    if character:GetAttribute("GuardBroken") == true then
        return true, "guard_broken"
    end

    if character:GetAttribute("Stunned") == true then
        return true, "stunned"
    end

    if character:GetAttribute("CantAnything") == true then
        return true, "cant_anything"
    end

    local humanoid = character:FindFirstChildOfClass("Humanoid")
    if humanoid and humanoid.Health <= 0 then
        return true, "dead"
    end

    return false, nil
end

function Menu._ResolverTimingRuntime.getSurfaceCorroboration(
    state,
    attackType,
    edgeAt,
    now
)
    if not state then
        return false, "state_missing", nil
    end

    local tokenAt = tonumber(state.tokenChangedAt)
    local cooldownAt =
        state.cooldownEdgeAt
        and tonumber(state.cooldownEdgeAt[attackType])
        or nil
    local window = attackType == "M2" and 0.16 or 0.135

    if tokenAt
        and math.abs(tokenAt - edgeAt) <= window
        and now - tokenAt <= 0.22
    then
        return true, "combat-token-edge", tokenAt
    end

    if cooldownAt
        and math.abs(cooldownAt - edgeAt) <= window
        and now - cooldownAt <= 0.22
    then
        return true,
            string.lower(attackType) .. "-cooldown-edge",
            cooldownAt
    end

    return false, "replicated-only", nil
end

function Menu._ResolverTimingRuntime.createSurfaceThreat(
    character,
    state,
    now
)
    if Flags.ap_enable ~= true
        or not character
        or not character.Parent
        or character.Name
            == localWorkspaceCharacterName
        or not state
    then
        return nil
    end

    local attackType =
        state.surfaceAttackType

    if attackType ~= "M1"
        and attackType ~= "M2"
    then
        return nil
    end

    local edgeAt =
        tonumber(
            state.surfaceEdgeAt
        ) or now
    local serial =
        tonumber(
            state.surfaceSerial
        ) or 0

    if serial <= (
        tonumber(
            state.surfaceConsumedSerial
        ) or 0
    ) then
        return nil
    end

    local surfaceAge = now - edgeAt
    local minimumSurfaceAge =
        attackType == "M2"
        and 0.045
        or 0.060

    if surfaceAge < minimumSurfaceAge then
        return nil
    end

    local latent =
        Menu._ResolverProofRuntime.takeLatentStopped(
            character,
            attackType,
            edgeAt,
            now
        )

    if latent then
        state.surfaceConsumedSerial =
            serial

        Menu._ResolverTimingRuntime.surfaceSerial += 1

        local threat = {
            source = "resolver_surface",
            resolverSurfaceSerial =
                Menu._ResolverTimingRuntime.surfaceSerial,
            resolverLatentCorroborated = true,
            resolverLatentStopAt =
                latent.stoppedAt,
            serverConfirmed = false,
            owner = character,
            ownerName = character.Name,
            ownerSource = "resolver-latent",
            attackType = attackType,
            combo = latent.combo or 0,
            createdAt =
                latent.createdAt,
            animationStartedAt =
                latent.createdAt,
            animationName =
                latent.animationName or "",
            animationId =
                latent.animationId or "",
            resolverProofReason =
                "late-replicated-after-micro-stop",
            resolverProofAt =
                edgeAt,
            resolverProofStrength =
                "corroborated",
            speedMultiplier =
                latent.speedMultiplier
                or getSpeedMultiplier(character),
            turnRate = 0,
            hitTL =
                latent.hitTL,
            style =
                latent.style
                or getStyle(character),
            expectedContactAbs =
                latent.expectedContactAbs,
            resolverPunishGuardHold =
                attackType == "M2"
                and Menu._ResolverProofRuntime
                    .LATENT_STOP_GUARD_HOLD_M2
                or Menu._ResolverProofRuntime
                    .LATENT_STOP_GUARD_HOLD_M1,
        }

        if not tonumber(
            threat.expectedContactAbs
        ) then
            local speed =
                math.clamp(
                    tonumber(
                        threat.speedMultiplier
                    ) or 1,
                    0.2,
                    3
                )
            threat.hitTL =
                tonumber(threat.hitTL)
                or getThreatHitTimeline(threat)
            threat.expectedContactAbs =
                threat.createdAt
                + threat.hitTL / speed
                + Menu._ResolverTimingRuntime.getBias(
                    threat
                )
        end

        Menu._ResolverTimingRuntime.surfaceThreats[
            Menu._ResolverTimingRuntime.surfaceSerial
        ] = threat

        state.desyncSurfaceObserved =
            true
        state.desyncSurfaceActiveUntil =
            math.max(
                tonumber(
                    state.desyncSurfaceActiveUntil
                ) or 0,
                now + 6
            )

        debugLog(
            "AP_RESOLVER_LATENT_PROMOTE",
            {
                attack = attackType,
                owner = character.Name,
                style = threat.style or "",
                combo = threat.combo or 0,
                animationName =
                    threat.animationName or "",
                edgeProof =
                    state.surfaceProofReason or "",
                stopToSurface =
                    edgeAt
                    - (
                        tonumber(
                            latent.stoppedAt
                        ) or edgeAt
                    ),
                surfaceAge =
                    surfaceAge,
                contactIn =
                    (
                        tonumber(
                            threat.expectedContactAbs
                        ) or now
                    )
                    - now,
            },
            true
        )

        return threat
    end

    if Menu._ResolverTimingRuntime.surfaceHasAnimation(
        character,
        attackType,
        edgeAt
    ) then
        state.surfaceConsumedSerial =
            serial
        return nil
    end

    local unavailable, unavailableReason =
        Menu._ResolverTimingRuntime.surfaceOwnerUnavailable(
            character
        )

    if unavailable then
        state.surfaceConsumedSerial = serial
        debugLog(
            "AP_DESYNC_SURFACE_SUPPRESS",
            {
                attack = attackType,
                owner = character.Name,
                reason = unavailableReason or "owner_unavailable",
                age = surfaceAge,
                proof = state.surfaceProofReason or "",
            },
            true
        )
        return nil
    end

    local surfaceProofReason =
        state.surfaceProofReason
        or ("replicated-" .. attackType)
    local corroborated = false
    local corroborationReason = ""
    local corroborationAt = nil

    if surfaceProofReason == "replicated-" .. attackType then
        corroborated, corroborationReason, corroborationAt =
            Menu._ResolverTimingRuntime.getSurfaceCorroboration(
                state,
                attackType,
                edgeAt,
                now
            )

        if attackType == "M1" and not corroborated then
            local proofWait = 0.145

            if surfaceAge <= proofWait then
                if state.surfaceWaitLoggedSerial ~= serial then
                    state.surfaceWaitLoggedSerial = serial
                    debugLog(
                        "AP_DESYNC_SURFACE_WAIT",
                        {
                            attack = attackType,
                            owner = character.Name,
                            age = surfaceAge,
                            waitFor = proofWait,
                            proof = surfaceProofReason,
                            reason = corroborationReason,
                        },
                        true
                    )
                end
                return nil
            end

            state.surfaceConsumedSerial = serial
            debugLog(
                "AP_DESYNC_SURFACE_DROP",
                {
                    attack = attackType,
                    owner = character.Name,
                    age = surfaceAge,
                    proof = surfaceProofReason,
                    reason = corroborationReason,
                },
                true
            )
            return nil
        end

        if corroborated then
            surfaceProofReason = corroborationReason
        end
    end

    state.surfaceConsumedSerial =
        serial

    local combo = 0

    if attackType == "M1" then
        local previousM1At =
            tonumber(
                state.surfaceLastM1At
            ) or 0

        if edgeAt - previousM1At
            <= 1.20
        then
            state.surfaceM1Combo =
                (
                    tonumber(
                        state.surfaceM1Combo
                    ) or 0
                ) % 4
                + 1
        else
            state.surfaceM1Combo = 1
        end

        state.surfaceLastM1At =
            edgeAt
        combo =
            state.surfaceM1Combo
    end

    Menu._ResolverTimingRuntime.surfaceSerial += 1

    local threat = {
        source = "resolver_surface",
        resolverSurfaceSerial =
            Menu._ResolverTimingRuntime.surfaceSerial,
        serverConfirmed = false,
        owner = character,
        ownerName = character.Name,
        ownerSource = "resolver",
        attackType = attackType,
        combo = combo,
        createdAt = edgeAt,
        animationStartedAt = edgeAt,
        resolverProofReason =
            surfaceProofReason,
        resolverProofAt =
            corroborationAt
            or edgeAt,
        speedMultiplier =
            getSpeedMultiplier(
                character
            ),
        turnRate = 0,
    }

    threat.style =
        getStyle(character)
    threat.hitTL =
        getThreatHitTimeline(
            threat
        )

    local speed =
        math.clamp(
            tonumber(
                threat.speedMultiplier
            ) or 1,
            0.2,
            3
        )

    threat.expectedContactAbs =
        edgeAt
        + threat.hitTL / speed
        + Menu._ResolverTimingRuntime.getBias(threat)

    Menu._ResolverTimingRuntime.surfaceThreats[
        Menu._ResolverTimingRuntime.surfaceSerial
    ] = threat

    state.desyncSurfaceObserved =
        true
    state.desyncSurfaceActiveUntil =
        math.max(
            tonumber(
                state.desyncSurfaceActiveUntil
            ) or 0,
            now + 6
        )

    debugLog(
        "AP_DESYNC_SURFACE_THREAT",
        {
            attack =
                attackType,
            owner =
                character.Name,
            style =
                threat.style or "",
            combo =
                combo,
            proof =
                threat.resolverProofReason
                or "",
            edgeProof =
                state.surfaceProofReason
                or "",
            corroborated =
                corroborated == true,
            corroborationAge =
                corroborationAt
                and (corroborationAt - edgeAt)
                or "",
            contactIn =
                threat.expectedContactAbs
                - now,
            modeSupport =
                "Fighting Style/No Fighting Style",
        },
        true
    )

    return threat
end

function Menu._ResolverTimingRuntime.updateSurfaceThreat(
    threat,
    now
)
    if not threat
        or threat.expired == true
    then
        return false
    end

    if threat.fired == true then
        return now
            - (
                tonumber(
                    threat.firedAt
                )
                or threat.createdAt
            )
            <= 0.75
    end

    local owner =
        threat.owner

    if not owner
        or not owner.Parent
    then
        threat.expired = true
        return false
    end

    local unavailable, unavailableReason =
        Menu._ResolverTimingRuntime.surfaceOwnerUnavailable(
            owner
        )

    local latentUnavailableBypass =
        threat.resolverLatentCorroborated == true
        and (
            unavailableReason == "cant_anything"
            or unavailableReason == "stunned"
        )
        and now
            <= (
                tonumber(
                    threat.expectedContactAbs
                ) or now
            )
                + Menu._ResolverProofRuntime
                    .LATENT_STOP_CONTACT_GRACE

    if unavailable
        and threat.serverConfirmed ~= true
        and not latentUnavailableBypass
    then
        threat.expired = true
        if threat.surfaceUnavailableLogged ~= true then
            threat.surfaceUnavailableLogged = true
            debugLog(
                "AP_DESYNC_SURFACE_SUPPRESS",
                {
                    attack = threat.attackType or "",
                    owner = threat.ownerName or "",
                    style = threat.style or "",
                    reason = unavailableReason or "owner_unavailable",
                    age = now - (tonumber(threat.createdAt) or now),
                    phase = "active_surface",
                },
                true
            )
        end
        return false
    elseif latentUnavailableBypass
        and threat.latentUnavailableBypassLogged ~= true
    then
        threat.latentUnavailableBypassLogged = true
        debugLog(
            "AP_RESOLVER_LATENT_OWNER_BYPASS",
            {
                attack = threat.attackType or "",
                owner = threat.ownerName or "",
                style = threat.style or "",
                reason = unavailableReason or "",
                contactIn =
                    (
                        tonumber(
                            threat.expectedContactAbs
                        ) or now
                    )
                    - now,
            },
            true
        )
    end

    threat.style =
        getStyle(owner)
    threat.speedMultiplier =
        getSpeedMultiplier(owner)

    if Menu._ResolverTimingRuntime.surfaceHasAnimation(
        owner,
        threat.attackType,
        tonumber(threat.createdAt) or now
    ) then
        threat.expired = true

        if threat.surfaceMergeLogged ~= true then
            threat.surfaceMergeLogged = true
            debugLog(
                "AP_DESYNC_SURFACE_MERGE",
                {
                    attack =
                        threat.attackType or "",
                    owner =
                        threat.ownerName or "",
                    style =
                        threat.style or "",
                    combo =
                        threat.combo or 0,
                    age =
                        now
                        - (
                            tonumber(
                                threat.createdAt
                            ) or now
                        ),
                },
                true
            )
        end

        return false
    end

    local allowed,
        rejectReason,
        context =
            passesThreatFilters(
                threat
            )

    if not allowed then
        threat.lastReject =
            rejectReason

        if now
            > (
                tonumber(
                    threat.expectedContactAbs
                ) or now
            )
                + 0.40
        then
            threat.expired = true
            return false
        end

        return true
    end

    local speed =
        math.clamp(
            tonumber(
                threat.speedMultiplier
            ) or 1,
            0.2,
            3
        )
    local hitTL =
        threat.hitTL
        or getThreatHitTimeline(
            threat
        )
    threat.hitTL = hitTL

    local contactAbs =
        tonumber(
            threat.expectedContactAbs
        )

    if not contactAbs then
        contactAbs =
            threat.createdAt
            + hitTL / speed
            + Menu._ResolverTimingRuntime.getBias(threat)
        threat.expectedContactAbs =
            contactAbs
    end

    if threat.serverConfirmed == true
        and threat.hitbox
        and threat.hitbox.Parent
    then
        contactAbs =
            math.min(
                contactAbs,
                now
            )
    end

    local ping, up =
        getUplink()
    local target,
        lookahead,
        pwin =
            predictionWindow()
    local pressAt =
        contactAbs
        - target
        - up
    local pressAtQ =
        pressAt
        - lookahead

    local prediction = {
        ping = ping,
        up = up,
        target = target,
        pwin = pwin,
        lookahead = lookahead,
        overlapDelay = 0,
        velLead = 0,
        closing = 0,
        side = 0,
        hitTL = hitTL,
        trackTime =
            math.max(
                0,
                (
                    now
                    - threat.createdAt
                ) * speed
            ),
        trackSpeed = speed,
        visualTrackTime = "",
        visualTrackSpeed = "",
        combatTimelineSpeed = speed,
        ownerAttackSpeed = speed,
        speedDesynced = true,
        contactAbs = contactAbs,
        pressAt = pressAt,
        pressAtQ = pressAtQ,
    }

    if pressAtQ - now
        <= AUTOFACE_PARRY_PREARM
    then
        prepareAutoFaceForParry(
            threat,
            context,
            false
        )
    end

    if now >= pressAtQ then
        performParry(
            threat,
            prediction,
            context
        )
    end

    if now > contactAbs + 0.40
        and threat.serverConfirmed
            ~= true
    then
        threat.expired = true
        return false
    end

    return true
end


local function createAnimationThreat(character, track)
    if Flags.ap_enable ~= true
        or not character
        or character.Name == localWorkspaceCharacterName
    then
        return
    end

    local localRoot =
        getRoot(getCharacter())
    local ownerRoot =
        getRoot(character)

    if localRoot and ownerRoot then
        local observeDistance =
            flat(
                ownerRoot.Position
                    - localRoot.Position
            ).Magnitude

        if observeDistance
            > (
                tonumber(Menu._APObserveRadius)
                or 80
            )
        then
            return
        end
    end

    local attackType, combo, animationName, animationId =
        classifyTrack(character, track)

    if not attackType then
        return
    end

    local now = os.clock()
    local style = getStyle(character)
    local initialVisualSpeed =
        tonumber(track.Speed) or 1
    local initialTrackTime =
        math.max(
            0,
            tonumber(track.TimePosition) or 0
        )

    if initialVisualSpeed < 0.2
        or initialVisualSpeed > 3
    then
        initialVisualSpeed = 1
    end

    Menu._apRecentAnimationStarts =
        Menu._apRecentAnimationStarts
        or {}

    local animationSignature =
        tostring(character.Name)
        .. "|"
        .. tostring(animationId or animationName or "")
        .. "|"
        .. tostring(attackType or "")
        .. "|"
        .. tostring(combo or 0)
    local previousStart =
        Menu._apRecentAnimationStarts[
            animationSignature
        ]

    if previousStart
        and now
            - (
                tonumber(previousStart.at)
                or 0
            )
            <= 0.11
        and previousStart.threat
        and previousStart.threat.expired
            ~= true
        and previousStart.threat.fired
            ~= true
    then
        debugLog(
            "ANIM_DUPLICATE_SUPPRESS",
            {
                attack =
                    attackType or "",
                owner =
                    character.Name,
                style = style,
                combo = combo or 0,
                animationId =
                    animationId or "",
                animationName =
                    animationName or "",
                visualTrackSpeed =
                    initialVisualSpeed,
                duplicateAge =
                    now
                    - (
                        tonumber(
                            previousStart.at
                        ) or now
                    ),
            },
            true
        )
        return
    end

    local threat = {
        source = "animation",
        track = track,
        owner = character,
        ownerName = character.Name,
        attackType = attackType,
        combo = combo,
        animationName = animationName,
        animationId = animationId,
        style = style,
        speedMultiplier =
            getSpeedMultiplier(character),
        createdAt = now,
        animationStartedAt =
            now
            - initialTrackTime
                / math.max(
                    initialVisualSpeed,
                    0.2
                ),
        turnRate = 0,
    }

    threat.resolverPunishContext,
        threat.resolverPunishReason =
            Menu._ResolverProofRuntime
                .isLocalPunishContext(now)

    if attackType == "M2" then
        local compactAnimationName = string.lower(tostring(animationName or ""))
            :gsub("[%s_%-%#]", "")

        if style == "ali" then



            if compactAnimationName == "m2right"
                or compactAnimationName == "rightm2"
            then
                threat.variant = "Right"
            elseif compactAnimationName == "m2"
                or compactAnimationName == "m2left"
                or compactAnimationName == "leftm2"
            then
                threat.variant = "Left"
            end
        elseif style == "hakari" then


            threat.hakariMomentum = compactAnimationName == "momentumm2"
                or character:GetAttribute("HakariM2DoubleWindow") == true
        end

        if threat.variant == nil then
            local okVariant, variant = pcall(
                CombatStepUtils.ResolveM2VariantId,
                style,
                character
            )

            if okVariant then
                threat.variant = variant
            end
        end

        pcall(function()
            local styleConfig = CombatConfig.GetStyleConfig(style)
            threat.counterStance = styleConfig
                and styleConfig.M2RequiresCounterHit == true
                or false
        end)
    end

    threat.hitTL = getThreatHitTimeline(threat)

    Menu._APBreakerResolver.noteAnimationStart(
        character,
        animationId,
        attackType,
        combo,
        initialVisualSpeed,
        now
    )



    threat.mustDodgeSelected = false
    if Flags.dodge_enable == true
        and Menu._DodgeRuntime
        and type(Menu._DodgeRuntime.isMustDodgeThreat) == "function"
    then
        local okMustDodge, selected = pcall(
            Menu._DodgeRuntime.isMustDodgeThreat,
            threat
        )
        threat.mustDodgeSelected = okMustDodge and selected == true
    end

    animationThreats[track] = threat
    Menu._apRecentAnimationStarts[
        animationSignature
    ] = {
        at = now,
        threat = threat,
    }

    if Menu._WingChunCounterRuntime
        and type(Menu._WingChunCounterRuntime.schedule) == "function"
    then
        task.defer(Menu._WingChunCounterRuntime.schedule, threat)
    end

    local initialCombatSpeed =
        tonumber(threat.speedMultiplier)
        or 1
    local initialSpeedDesynced =
        initialVisualSpeed >= 1.15
        and initialVisualSpeed
            > initialCombatSpeed + 0.10

    debugLog("ANIM_ATTACK", {
        attack = attackType,
        animationName = animationName or "",
        animationId = animationId or "",
        owner = character.Name,
        style = style,
        combo = combo or 0,
        variant = threat.variant or "",
        hitTL = threat.hitTL,
        trackTime =
            initialTrackTime,
        trackSpeed =
            initialVisualSpeed,
        visualTrackTime =
            initialTrackTime,
        visualTrackSpeed =
            initialVisualSpeed,
        ownerAttackSpeed =
            initialCombatSpeed,
        combatTimelineSpeed =
            initialCombatSpeed,
        speedDesynced =
            initialSpeedDesynced,
        counterStance = threat.counterStance == true,
        hakariMomentum = threat.hakariMomentum == true,
    })

    if attackType == "M2"
        and normalizeCombatStyleKey(tostring(style or "")) == "cqc"
    then
        local cqcCancel =
            AutoPunishRuntime
            and AutoPunishRuntime.tryCqcM2M1Cancel

        if type(cqcCancel) == "function" then
            local okCancel, cancelError =
                pcall(cqcCancel, threat, os.clock())

            if not okCancel then
                debugLog("CQC_M2_AUTOPUNISH_ERROR", {
                    owner = threat.ownerName or character.Name or "",
                    attack = "M2",
                    style = "cqc",
                    stage = "animation_start",
                    error = tostring(cancelError),
                }, true)
            end
        else
            debugLog("CQC_M2_AUTOPUNISH_RUNTIME_MISSING", {
                owner = threat.ownerName or character.Name or "",
                attack = "M2",
                style = "cqc",
                stage = "animation_start",
            }, true)
        end
    end

    track.Stopped:Connect(function()
        if animationThreats[track] ~= threat or threat.serverConfirmed then
            return
        end

        threat.trackStoppedAt = os.clock()

        debugLog("ANIM_STOP", {
            attack = threat.attackType,
            owner = threat.ownerName,
            fired = threat.fired == true,
            reject = threat.lastReject or "",
            age = threat.trackStoppedAt - threat.createdAt,
        })

        if not threat.fired then
            local stopAge =
                threat.trackStoppedAt
                - (
                    tonumber(
                        threat.createdAt
                    ) or threat.trackStoppedAt
                )
            local earlyStopLimit =
                threat.attackType == "M2"
                and Menu._ResolverProofRuntime.EARLY_STOP_FAKE_M2
                or Menu._ResolverProofRuntime.EARLY_STOP_FAKE_M1
            local protectedLifecycle =
                threat.style == "hakari"
                or (
                    threat.style == "kyokushin"
                    and threat.attackType == "M2"
                )

            -- Refresh proof once at the exact stop edge.  Very short tracks
            -- are a strong fake/desync signature when all we have is weak
            -- replicated state.  Do not convert those into long stopped-track
            -- handoffs that can fire a parry after the visual bait is gone.
            local stopProof,
                stopProofReason,
                stopProofAt =
                    getAnimationResolverProof(
                        threat,
                        threat.trackStoppedAt
                    )

            if stopProof then
                threat.resolverProofReason =
                    stopProofReason
                threat.resolverProofBoundAt =
                    stopProofAt
            end

            -- Main410 delayed-shell catch: the missed Boxing M1s in the latest
            -- trace stopped in ~0.2-0.3 ms, did not qualify for the contextual
            -- AutoPunish rescue, then produced a replicated M1 edge ~90 ms
            -- later and a real hitbox on the original ~0.35 s timeline.
            -- Arm a latent candidate for every micro-stop; it cannot parry by
            -- itself and is only promoted by a later matching replicated edge.
            if stopAge <= 0.012
                and not protectedLifecycle
                and threat.serverConfirmed ~= true
            then
                threat.resolverLatentMicroArmed =
                    Menu._ResolverProofRuntime.armLatentStopped(
                        threat,
                        threat.trackStoppedAt
                    ) == true
            end

            if stopAge <= earlyStopLimit
                and not protectedLifecycle
                and threat.serverConfirmed ~= true
                and threat.resolverPunishContext == true
                and not Menu._ResolverTimingRuntime.hasStrongProof(
                    threat
                )
            then
                threat.resolverPunishRescue = true
                threat.resolverProofReason =
                    threat.resolverProofReason
                    or "incoming-autopunish-context"
                threat.resolverProofStrength =
                    threat.resolverProofStrength
                    or "contextual"

                local emergencyStopLimit =
                    threat.attackType == "M2"
                    and Menu._ResolverProofRuntime
                        .INCOMING_PUNISH_M2_EMERGENCY_STOP
                    or Menu._ResolverProofRuntime
                        .INCOMING_PUNISH_M1_EMERGENCY_STOP
                local emergencyContact =
                    threat.attackType == "M2"
                    and Menu._ResolverProofRuntime
                        .INCOMING_PUNISH_M2_CONTACT
                    or Menu._ResolverProofRuntime
                        .INCOMING_PUNISH_M1_CONTACT

                threat.resolverPunishGuardHold =
                    math.max(
                        tonumber(
                            threat.resolverPunishGuardHold
                        ) or 0,
                        threat.attackType == "M2"
                            and Menu._ResolverProofRuntime
                                .INCOMING_PUNISH_M2_GUARD_HOLD
                            or Menu._ResolverProofRuntime
                                .INCOMING_PUNISH_M1_GUARD_HOLD
                    )

                if stopAge <= emergencyStopLimit then
                    -- Desynced AutoPunish shells in this trace can stop in
                    -- ~0.2 ms and spawn their real server hitbox only 3-6 ms
                    -- later.  Give both M1 and M2 a short contextual contact
                    -- edge so the resolver blocks before that hitbox arrives.
                    threat.resolverPunishEmergency = true
                    threat.expectedContactAbs =
                        math.min(
                            tonumber(
                                threat.expectedContactAbs
                            ) or math.huge,
                            threat.trackStoppedAt
                                + emergencyContact
                        )
                elseif tonumber(
                    threat.expectedContactAbs
                ) == nil
                then
                    -- A non-micro stopped punish still needs a real contact
                    -- timeline.  Main410 marked these as rescue candidates but
                    -- left M1 contactIn at zero, so the stopped-track scheduler
                    -- had nothing to fire from.
                    threat.expectedContactAbs =
                        threat.createdAt
                        + (
                            tonumber(
                                threat.hitTL
                            )
                            or getThreatHitTimeline(
                                threat
                            )
                        )
                            / math.clamp(
                                tonumber(
                                    threat.speedMultiplier
                                ) or 1,
                                0.2,
                                3
                            )
                        + Menu._ResolverTimingRuntime.getBias(
                            threat
                        )
                end

                debugLog(
                    "AP_RESOLVER_AUTOPUNISH_RESCUE",
                    {
                        attack = threat.attackType or "",
                        owner = threat.ownerName or "",
                        style = threat.style or "",
                        combo = threat.combo or 0,
                        animationName = threat.animationName or "",
                        stopAge = stopAge,
                        context = threat.resolverPunishReason or "",
                        emergency =
                            threat.resolverPunishEmergency == true,
                        contactIn =
                            (
                                tonumber(
                                    threat.expectedContactAbs
                                ) or threat.trackStoppedAt
                            )
                            - threat.trackStoppedAt,
                    },
                    true
                )
            end

            if stopAge <= earlyStopLimit
                and not protectedLifecycle
                and threat.serverConfirmed ~= true
                and threat.resolverPunishContext ~= true
                and not Menu._ResolverTimingRuntime.hasStrongProof(
                    threat
                )
            then
                local latentArmed =
                    threat.resolverLatentMicroArmed == true
                    or Menu._ResolverProofRuntime.armLatentStopped(
                        threat,
                        threat.trackStoppedAt
                    )

                threat.lastReject =
                    latentArmed
                    and "resolver_latent_stop"
                    or "resolver_early_stop_fake"
                threat.expired = true

                if Menu._AutoFaceRuntime
                    and type(
                        Menu._AutoFaceRuntime
                            .invalidateThreat
                    ) == "function"
                then
                    pcall(
                        Menu._AutoFaceRuntime
                            .invalidateThreat,
                        threat,
                        latentArmed
                            and "resolver_latent_stop"
                            or "resolver_early_stop_fake"
                    )
                end

                if not latentArmed then
                    Menu._APBreakerResolver.noteFake(
                        threat,
                        threat.trackStoppedAt,
                        stopProofReason
                            or "early-stop-weak-proof"
                    )
                end

                releaseBehindParryFacingForThreat(
                    threat,
                    latentArmed
                        and "resolver_latent_stop"
                        or "resolver_early_stop_fake"
                )

                debugLog(
                    "AP_RESOLVER_EARLY_STOP_FAKE",
                    {
                        attack =
                            threat.attackType or "",
                        owner =
                            threat.ownerName or "",
                        style =
                            threat.style or "",
                        combo =
                            threat.combo or 0,
                        animationName =
                            threat.animationName or "",
                        animationId =
                            threat.animationId or "",
                        stopAge =
                            stopAge,
                        limit =
                            earlyStopLimit,
                        proof =
                            stopProofReason
                            or threat.resolverProofReason
                            or "",
                        proofStrength =
                            threat.resolverProofStrength
                            or "",
                        proofDelta =
                            threat.resolverProofDelta
                            or "",
                        latent =
                            latentArmed == true,
                    },
                    true
                )

                return
            end
            local keepKyokushinM2 =
                threat.style == "kyokushin"
                and threat.attackType == "M2"
                and tonumber(threat.expectedContactAbs) ~= nil
                and threat.trackStoppedAt
                    <= (
                        tonumber(threat.expectedContactAbs)
                        + KYOKUSHIN_M2_STOPPED_TRACK_CONTACT_GRACE
                    )
                and (
                    threat.serverConfirmed == true
                    or tostring(
                        threat.resolverProofReason or ""
                    ) == "replicated-M2"
                    or tostring(
                        threat.resolverProofReason or ""
                    ) == "m2-cooldown-edge"
                    or tostring(
                        threat.resolverProofReason or ""
                    ) == "combat-token-type"
                    or tostring(
                        threat.resolverProofReason or ""
                    ) == "combat-token-edge"
                )

            if keepKyokushinM2 then
                threat.kyokushinM2StoppedHandoff = true

                debugLog(
                    "AP_KYOKUSHIN_M2_STOP_HANDOFF",
                    {
                        owner =
                            threat.ownerName or "",
                        proof =
                            threat.resolverProofReason
                            or "",
                        contactIn =
                            (
                                tonumber(
                                    threat.expectedContactAbs
                                )
                                or threat.trackStoppedAt
                            )
                            - threat.trackStoppedAt,
                        timingLead =
                            tonumber(
                                threat.kyokushinM2TimingLead
                            )
                            or KYOKUSHIN_M2_SERVER_WINDOW_LEAD,
                        networkProfile =
                            threat.kyokushinM2NetworkProfile
                            or "default",
                    },
                    true
                )

                return
            end

            threat.trackStopHandoffUntil =
                math.max(
                    tonumber(
                        threat.trackStopHandoffUntil
                    ) or 0,
                    threat.trackStoppedAt
                        + AP_SERVER_REPLICATION_LATE_GRACE
                )

            if Menu._ResolverTimingRuntime.shouldHoldStoppedTrack(
                threat,
                threat.trackStoppedAt
            )
            then
                local contactAbs =
                    tonumber(
                        threat.expectedContactAbs
                    )
                local resolverHold =
                    contactAbs
                    and (
                        contactAbs
                        + 0.36
                    )
                    or (
                        threat.trackStoppedAt
                        + 0.36
                    )

                threat.trackStopHandoffUntil =
                    math.max(
                        tonumber(
                            threat.trackStopHandoffUntil
                        ) or 0,
                        resolverHold
                    )
                threat.resolverStoppedTrackHandoff =
                    true

                debugLog(
                    "AP_RESOLVER_STOP_HANDOFF",
                    {
                        attack =
                            threat.attackType or "",
                        owner =
                            threat.ownerName or "",
                        style =
                            threat.style or "",
                        combo =
                            threat.combo or 0,
                        proof =
                            threat.resolverProofReason
                            or threat.apBreakerProofReason
                            or "",
                        stopAge =
                            threat.trackStoppedAt
                            - threat.createdAt,
                        contactIn =
                            contactAbs
                            and (
                                contactAbs
                                - threat.trackStoppedAt
                            )
                            or "",
                        handoffRemaining =
                            threat.trackStopHandoffUntil
                            - threat.trackStoppedAt,
                    },
                    true
                )
            end

            if threat.resolverPunishEmergency == true then
                Menu._ResolverTimingRuntime.tryStoppedTrackParry(
                    threat,
                    threat.trackStoppedAt
                )
            end

            if threat.style == "hakari" then
                local contactAbs = tonumber(threat.expectedContactAbs)
                local remainingAtStop = contactAbs
                    and (contactAbs - threat.trackStoppedAt)
                    or nil
                local proofReason = tostring(threat.resolverProofReason or "")

                if contactAbs
                    and remainingAtStop >= Menu._APHakariStopTuning.minRemaining
                    and remainingAtStop <= Menu._APHakariStopTuning.maxRemaining
                    and (
                        threat.serverConfirmed == true
                        or proofReason == "hakari-combat-animation"
                    )
                then
                    threat.hakariStoppedTrackRescue = true
                    threat.hakariLifecycleDesynced = true
                    threat.trackStopHandoffUntil = math.max(
                        tonumber(threat.trackStopHandoffUntil) or 0,
                        contactAbs + Menu._APHakariStopTuning.contactGrace
                    )

                    if threat.hakariStopDesyncLogged ~= true then
                        threat.hakariStopDesyncLogged = true
                        debugLog("AP_HAKARI_STOP_DESYNC", {
                            owner = threat.ownerName or "",
                            attack = threat.attackType or "",
                            combo = threat.combo or 0,
                            animationName = threat.animationName or "",
                            proof = proofReason,
                            stopAge = threat.trackStoppedAt - threat.createdAt,
                            contactRemaining = remainingAtStop,
                            handoffRemaining = threat.trackStopHandoffUntil - threat.trackStoppedAt,
                        }, true)
                    end
                end
            end

        end
    end)
end

Menu._APServerHitbox = Menu._APServerHitbox or {}

Menu._APObserveRadius = 80

function Menu._APServerHitbox.watchCharacter(character)
    if not character
        or watchedCharacters[character]
        or character.Name == localWorkspaceCharacterName
    then
        return
    end

    watchedCharacters[character] = true
    refreshResolverState(character, os.clock())

    for _, attributeName in ipairs({
        "CombatToken",
        "combatToken",
        "combat_token",
        "CombatActionToken",
        "M1",
        "M1Hold",
        "PendingM1",
        "M2",
        "PendingM2",
        "M1Cooldown",
        "M1CooldownRemaining",
        "M2Cooldown",
        "M2CooldownRemaining",
    }) do
        Menu._ScriptRuntime:Track(
            character:GetAttributeChangedSignal(
                attributeName
            ):Connect(function()
                if character.Parent then
                    refreshResolverState(
                        character,
                        os.clock()
                    )
                end
            end)
        )
    end

    local tokenObject =
        character:FindFirstChild(
            "CombatToken"
        )

    if tokenObject
        and tokenObject.Changed
    then
        Menu._ScriptRuntime:Track(
            tokenObject.Changed:Connect(
                function()
                    if character.Parent then
                        refreshResolverState(
                            character,
                            os.clock()
                        )
                    end
                end
            )
        )
    end

    local function onCqcRingChanged()
        if not Menu._ScriptRuntime
            or Menu._ScriptRuntime.alive ~= true
            or not character.Parent
            or character:GetAttribute("CQCRingActive") ~= true
        then
            return
        end

        local style = normalizeCombatStyleKey(tostring(getStyle(character) or ""))
        if style ~= "cqc" then
            return
        end

        local ringNow = os.clock()
        local previous = tonumber(cqcRingActivationAt[character]) or 0
        if previous > 0 and ringNow - previous < 0.15 then
            return
        end

        cqcRingActivationAt[character] = ringNow

        local ringDistance = math.huge
        local distanceGetter =
            AutoPunishRuntime
            and AutoPunishRuntime.getDistance
        if type(distanceGetter) == "function" then
            local okDistance, measuredDistance = pcall(distanceGetter, character)
            if okDistance and type(measuredDistance) == "number" then
                ringDistance = measuredDistance
            end
        end

        debugLog("CQC_M2_RING_ACTIVE", {
            owner = character.Name,
            source = "CQCRingActive",
            cancelWindow = (AutoPunishRuntime
                and tonumber(AutoPunishRuntime.cqcM2CancelWindow))
                or 0.50,
            distance = ringDistance,
        }, true)

        local cqcCancel =
            AutoPunishRuntime
            and AutoPunishRuntime.tryCqcM2M1Cancel

        if type(cqcCancel) ~= "function" then
            debugLog("CQC_M2_AUTOPUNISH_RUNTIME_MISSING", {
                owner = character.Name,
                attack = "M2",
                style = "cqc",
                stage = "ring_active",
            }, true)
            return
        end

        local ringThreat = {
            attackType = "M2",
            style = "cqc",
            owner = character,
            ownerName = character.Name,
            source = "cqc_ring",
            createdAt = ringNow,
            cqcRingStartedAt = ringNow,
        }

        local okCancel, cancelError = pcall(cqcCancel, ringThreat, ringNow)
        if not okCancel then
            debugLog("CQC_M2_AUTOPUNISH_ERROR", {
                owner = character.Name,
                attack = "M2",
                style = "cqc",
                stage = "ring_active",
                error = tostring(cancelError),
            }, true)
        end
    end

    Menu._ScriptRuntime:Track(
        character:GetAttributeChangedSignal("CQCRingActive"):Connect(
            onCqcRingChanged
        )
    )

    task.spawn(function()
        local humanoid = character:FindFirstChildOfClass("Humanoid")
            or character:WaitForChild("Humanoid", 10)

        if not Menu._ScriptRuntime
            or Menu._ScriptRuntime.alive ~= true
            or not humanoid
            or not character.Parent
        then
            return
        end

        local animator = humanoid:FindFirstChildOfClass("Animator")
            or humanoid:WaitForChild("Animator", 10)

        if not animator
            or Menu._ScriptRuntime.alive ~= true
        then
            return
        end

        Menu._ScriptRuntime:Track(animator.AnimationPlayed:Connect(function(track)
            createAnimationThreat(character, track)
        end))

        for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
            createAnimationThreat(character, track)
        end
    end)
end

function Menu._APServerHitbox.getServerHitboxOwner(hitbox, allowNearest)
    local ownerValue = hitbox:FindFirstChild("Owner")

    if ownerValue
        and ownerValue:IsA("StringValue")
        and ownerValue.Value ~= ""
    then
        return ownerValue.Value,
            getWorkspaceCharacterByName(ownerValue.Value),
            "explicit"
    end

    if allowNearest ~= true then
        return nil, nil, "pending"
    end

    local owner, distance = nearestOwner(hitbox)

    if owner and distance <= 8 then
        return owner.Name, owner, "nearest"
    end

    return nil, nil, "none"
end

function Menu._APServerHitbox.findAnimationThreatForHitbox(
    attackType,
    hitbox,
    serverAddedAt,
    serverOwnerName
)
    local bestThreat
    local bestScore = math.huge

    local function consider(threat)
        if not threat
            or threat.expired
            or threat.serverConfirmed
            or threat.attackType ~= attackType
            or serverAddedAt - threat.createdAt > 1.25
            or serverAddedAt < threat.createdAt
            or (
                serverOwnerName ~= nil
                and serverOwnerName ~= ""
                and threat.ownerName ~= serverOwnerName
            )
        then
            return
        end

        local ownerRoot = getRoot(threat.owner)

        if not ownerRoot then
            return
        end

        local spatial =
            (ownerRoot.Position - hitbox.Position).Magnitude

        if spatial > 16 then
            return
        end

        local expectedAbs =
            tonumber(
                threat.expectedContactAbs
            )
        local timelineError

        if expectedAbs then
            timelineError =
                math.abs(
                    serverAddedAt
                    - expectedAbs
                )
        else
            local hitTL =
                threat.hitTL
                or getThreatHitTimeline(
                    threat
                )
            local speed =
                tonumber(
                    threat.speedMultiplier
                )
                or getEffectiveTrackSpeed(
                    threat
                )
            local expectedAge =
                math.max(
                    0.05,
                    hitTL
                        / math.max(
                            speed,
                            0.2
                        )
                        + Menu._ResolverTimingRuntime.getBias(
                            threat
                        )
                )
            local actualAge =
                serverAddedAt
                - threat.createdAt

            timelineError =
                math.abs(
                    actualAge
                    - expectedAge
                )
        end

        local score =
            timelineError
            + spatial * 0.008

        if threat.source
            == "resolver_surface"
        then
            score =
                score + 0.008
        end

        if score < bestScore then
            bestScore = score
            bestThreat = threat
        end
    end

    for _, threat in pairs(animationThreats) do
        consider(threat)
    end

    for _, threat in pairs(Menu._ResolverTimingRuntime.surfaceThreats) do
        consider(threat)
    end

    return bestThreat, bestScore
end

function Menu._APServerHitbox.getActionTokenKey(ownerName, attackType, actionToken)
    if typeof(ownerName) ~= "string"
        or ownerName == ""
        or actionToken == nil
    then
        return nil
    end

    return ownerName .. "|" .. tostring(attackType) .. "|" .. tostring(actionToken)
end

function Menu._APServerHitbox.rememberActionToken(ownerName, attackType, actionToken, now)
    local key = Menu._APServerHitbox.getActionTokenKey(ownerName, attackType, actionToken)

    if not key then
        return false
    end

    local previous = seenActionTokens[key]
    seenActionTokens[key] = now

    return previous ~= nil and now - previous <= 1.25
end

function Menu._APServerHitbox.isServerHitboxPhysicallyThreatening(hitbox)
    if not hitbox
        or not hitbox.Parent
        or not hitbox:IsA("BasePart")
    then
        return false, math.huge
    end

    local character = getCharacter()
    local myRoot = getRoot(character)

    if not myRoot then
        return false, math.huge
    end

    local localPoint = hitbox.CFrame:PointToObjectSpace(myRoot.Position)
    local rootRadius = math.max(myRoot.Size.X, myRoot.Size.Z) * 0.5
    local rootHalfY = myRoot.Size.Y * 0.5
    local cushion = 0.70
    local flatHitboxDistance = flat(hitbox.Position - myRoot.Position).Magnitude

    local physical =
        math.abs(localPoint.X)
            <= hitbox.Size.X * 0.5 + rootRadius + cushion
        and math.abs(localPoint.Z)
            <= hitbox.Size.Z * 0.5 + rootRadius + cushion
        and math.abs(localPoint.Y)
            <= hitbox.Size.Y * 0.5 + rootHalfY + cushion

    return physical, flatHitboxDistance
end

function Menu._APServerHitbox.getHitboxProfileKeys(threat)
    local style =
        string.lower(
            tostring(
                threat
                and threat.style
                or ""
            )
        )
    local attack =
        tostring(
            threat
            and threat.attackType
            or ""
        )
    local combo =
        math.floor(
            tonumber(
                threat
                and threat.combo
            ) or 0
        )
    local variant =
        string.lower(
            tostring(
                threat
                and threat.variant
                or ""
            )
        )

    return style
            .. "|"
            .. attack
            .. "|"
            .. tostring(combo)
            .. "|"
            .. variant,
        style
            .. "|"
            .. attack
            .. "|*"
end

function Menu._APServerHitbox.rememberHitboxProfile(threat, hitbox)
    if not threat
        or not hitbox
        or not hitbox.Parent
        or not hitbox:IsA("BasePart")
    then
        return
    end

    local owner =
        threat.owner
        or resolveOwner(
            threat
        )
    local ownerRoot =
        getRoot(
            owner
        )

    if not ownerRoot then
        return
    end

    local relativeCFrame =
        ownerRoot.CFrame
            :ToObjectSpace(
                hitbox.CFrame
            )
    local size =
        hitbox.Size
    local exactKey,
        genericKey =
            Menu._APServerHitbox
                .getHitboxProfileKeys(
                    threat
                )

    local function store(key)
        if not key
            or key == "||0|"
            or key == "||*"
        then
            return
        end

        local profile =
            Menu._APHitboxProfiles[
                key
            ]

        if type(profile) ~= "table" then
            profile = {
                key = key,
                samples = 0,
            }
            Menu._APHitboxProfiles[
                key
            ] = profile
        end

        profile.samples =
            (
                tonumber(
                    profile.samples
                ) or 0
            ) + 1
        profile.relativeCFrame =
            relativeCFrame

        if typeof(profile.size)
            == "Vector3"
        then
            profile.size =
                Vector3.new(
                    math.max(
                        profile.size.X,
                        size.X
                    ),
                    math.max(
                        profile.size.Y,
                        size.Y
                    ),
                    math.max(
                        profile.size.Z,
                        size.Z
                    )
                )
        else
            profile.size =
                size
        end

        profile.observedAt =
            os.clock()
    end

    store(exactKey)
    store(genericKey)
end

function Menu._APServerHitbox.attachServerHitbox(threat, hitbox, serverAddedAt)
    threat.hitbox = hitbox
    threat.serverConfirmed = true
    threat.autoFaceEndedAt = nil
    threat.autoFaceEndReason = nil
    threat.trackStopHandoffUntil = nil
    threat.serverHitboxEndedAt = nil
    threat.serverAddedAt = serverAddedAt
    threat.swingId = hitbox:GetAttribute("VictimSwingId")
    threat.actionToken = hitbox:GetAttribute("VictimActionToken")
    threat.strikeDamage = hitbox:GetAttribute("VictimStrikeDamage")

    local function refreshChildren()
        local ownerValue = hitbox:FindFirstChild("Owner")
        local attackValue = hitbox:FindFirstChild("AttackName")

        if ownerValue and ownerValue:IsA("StringValue") and ownerValue.Value ~= "" then
            threat.ownerName = ownerValue.Value
            threat.owner = getWorkspaceCharacterByName(ownerValue.Value) or threat.owner
            threat.ownerSource = "explicit"
            threat.style = getStyle(threat.owner)
        end

        if attackValue and attackValue:IsA("StringValue") and attackValue.Value ~= "" then
            threat.attackName = attackValue.Value
        end
    end

    refreshChildren()

    Menu._APServerHitbox.rememberHitboxProfile(
        threat,
        hitbox
    )

    Menu._APServerHitbox.rememberActionToken(
        threat.ownerName,
        threat.attackType,
        threat.actionToken,
        serverAddedAt
    )

    hitbox.ChildAdded:Connect(function(child)
        if child.Name == "Owner" or child.Name == "AttackName" then
            task.defer(refreshChildren)
        end
    end)

    local replicationArrivalError = threat.expectedContactAbs
        and (serverAddedAt - threat.expectedContactAbs)
        or 0

    if threat.expectedContactAbs then
        Menu._ResolverTimingRuntime.recordResidual(
            threat,
            replicationArrivalError,
            serverAddedAt
        )
    end

    if threat.expectedContactAbs then
        local style = tostring(threat.style or "")
        local aggressiveStyle =
            isAggressiveAutoParryStyle(style)
        local earlyThreshold = aggressiveStyle
            and -0.065
            or (
                threat.attackType == "M1"
                and -0.085
                or -0.10
            )

        if replicationArrivalError < earlyThreshold and not threat.fired then
            local trackTime = threat.track
                and math.max(0, tonumber(threat.track.TimePosition) or 0)
                or 0

            threat.serverReactiveCorrection = true
            threat.serverReactiveAt = serverAddedAt

            debugLog("SERVER_EARLY_CORRECTION", {
                attack = threat.attackType,
                owner = threat.ownerName or "",
                style = threat.style or "",
                combo = threat.combo or 0,
                swingId = threat.swingId or "",
                actionToken = threat.actionToken or "",
                contactError = replicationArrivalError,
                replicationArrivalError = replicationArrivalError,
                threshold = earlyThreshold,
                trackTime = trackTime,
                timingBias = Menu._ResolverTimingRuntime.getBias(threat),
            }, true)
        end
    end

    local physicalThreat, physicalHitboxDistance =
        Menu._APServerHitbox.isServerHitboxPhysicallyThreatening(hitbox)

    if physicalThreat == true
        and not (
            threat.attackType == "M2"
            and normalizeCombatStyleKey(tostring(
                threat.style or getStyle(threat.owner) or ""
            )) == "cqc"
        )
        and Flags.ap_auto_face == true
        and threat.owner
        and threat.owner.Parent
        and Menu._AutoFaceRuntime
        and type(
            Menu._AutoFaceRuntime.lockTarget
        ) == "function"
    then
        local faceClaimed =
            false

        pcall(function()
            faceClaimed =
                Menu._AutoFaceRuntime
                    .lockTarget(
                        threat.owner,
                        0.095,
                        "parry-defense-hitbox",
                        {
                            forceReplace =
                                true,
                            snapNow =
                                true,
                            impactEta =
                                0,
                        }
                    ) == true
        end)

        debugLog(
            "AUTOFACE_HITBOX_INTERCEPT",
            {
                owner =
                    threat.ownerName
                    or "",
                attack =
                    threat.attackType
                    or "",
                style =
                    threat.style
                    or "",
                claimed =
                    faceClaimed,
                hitboxDistance =
                    physicalHitboxDistance,
                swingId =
                    threat.swingId
                    or "",
            },
            true
        )
    end

    debugLog("SERVER_HITBOX_CONFIRM", {
        source = threat.source or "",
        attack = threat.attackType,
        owner = threat.ownerName or "",
        style = threat.style or "",
        combo = threat.combo or 0,
        variant = threat.variant or "",
        swingId = threat.swingId or "",
        actionToken = threat.actionToken or "",
        strikeDamage = threat.strikeDamage or "",
        size = hitbox.Size,
        position = hitbox.Position,
        predictedContactError = replicationArrivalError,
        replicationArrivalError = replicationArrivalError,
        physicalThreat = physicalThreat == true,
        physicalHitboxDistance = physicalHitboxDistance,
        serverReactive = threat.serverReactiveCorrection == true,
        timingBias = Menu._ResolverTimingRuntime.getBias(threat),
        ownerAttackSpeed = threat.speedMultiplier or getSpeedMultiplier(threat.owner),
        ownerSource = threat.ownerSource or "explicit",
    })

    local currentArmThreshold =
        tonumber(threat.apCurrentArmThreshold)
        or 0
    local nearMatchedHitbox =
        threat.source == "animation"
        and currentArmThreshold > 0
        and physicalHitboxDistance
            <= currentArmThreshold + 0.75

    local shouldImmediateReeval =
        threat.serverReactiveCorrection == true
        or physicalThreat == true
        or nearMatchedHitbox

    if shouldImmediateReeval
        and not threat.fired
        and not threat.expired
        and threat.track
    then
        if threat.serverConfirmReevalLogged ~= true then
            threat.serverConfirmReevalLogged = true
            debugLog("SERVER_CONFIRM_REEVAL", {
                attack = threat.attackType or "",
                owner = threat.ownerName or "",
                style = threat.style or "",
                combo = threat.combo or 0,
                swingId = threat.swingId or "",
                actionToken = threat.actionToken or "",
                reason = physicalThreat == true
                    and "physical_overlap"
                    or (
                        nearMatchedHitbox
                        and "near_matched_hitbox"
                        or "early_replication_arrival"
                    ),
                hitboxDistance = physicalHitboxDistance,
                replicationArrivalError = replicationArrivalError,
            }, true)
        end

        task.defer(function()
            if not threat.fired
                and not threat.expired
                and threat.track
                and threat.hitbox
                and threat.hitbox.Parent
            then
                updateAnimationThreat(threat, os.clock())
            end
        end)
    end
end

function Menu._APServerHitbox.addServerHitbox(hitbox)
    if Flags.ap_enable ~= true
        or not hitbox:IsA("BasePart")
    then
        return
    end

    local attackType

    if hitbox.Name == "M1Hitbox" then
        attackType = "M1"
    elseif hitbox.Name == "M2Hitbox" then
        attackType = "M2"
    else
        return
    end

    local localRoot =
        getRoot(getCharacter())

    if localRoot then
        local hitboxDistance =
            flat(
                hitbox.Position
                    - localRoot.Position
            ).Magnitude
        local hitboxExtent =
            math.max(
                hitbox.Size.X,
                hitbox.Size.Z
            ) * 0.5

        if hitboxDistance
            > (
                tonumber(Menu._APObserveRadius)
                or 80
            ) + hitboxExtent
        then
            return
        end
    end

    local serverAddedAt = os.clock()
    local swingId = hitbox:GetAttribute("VictimSwingId")
    local dedupeKey

    if swingId ~= nil then
        dedupeKey = attackType .. ":" .. tostring(swingId)

        if seenSwingIds[dedupeKey] then
            return
        end

        seenSwingIds[dedupeKey] = serverAddedAt
    end

    local removed = false

    hitbox.AncestryChanged:Connect(function(_, parent)
        if parent ~= nil or removed then
            return
        end

        removed = true

        local linkedThreat = serverLinks[hitbox]

        if linkedThreat then
            serverLinks[hitbox] = nil

            if Menu._AutoFaceRuntime
                and type(
                    Menu._AutoFaceRuntime
                        .invalidateThreat
                ) == "function"
            then
                pcall(
                    Menu._AutoFaceRuntime
                        .invalidateThreat,
                    linkedThreat,
                    "server_hitbox_end"
                )
            end

            linkedThreat.hitbox = nil
            linkedThreat.serverHitboxEndedAt =
                os.clock()

            debugLog("SERVER_HITBOX_END", {
                source = linkedThreat.source or "",
                attack = linkedThreat.attackType,
                owner = linkedThreat.ownerName or "",
                swingId = linkedThreat.swingId or "",
                fired = linkedThreat.fired == true,
                reject = linkedThreat.lastReject or "",
                age = os.clock() - linkedThreat.createdAt,
            })

            return
        end

        local fallback = serverFallbackThreats[hitbox]

        if fallback then
            if Menu._AutoFaceRuntime
                and type(
                    Menu._AutoFaceRuntime
                        .invalidateThreat
                ) == "function"
            then
                pcall(
                    Menu._AutoFaceRuntime
                        .invalidateThreat,
                    fallback,
                    "server_hitbox_end"
                )
            end

            fallback.expired = true
            serverFallbackThreats[hitbox] = nil

            debugLog("SERVER_HITBOX_END", {
                source = fallback.source,
                attack = fallback.attackType,
                owner = fallback.ownerName or "",
                swingId = fallback.swingId or "",
                fired = fallback.fired == true,
                reject = fallback.lastReject or "",
                age = os.clock() - fallback.createdAt,
            })
        end
    end)

    task.spawn(function()



        local ownerName
        local ownerCharacter
        local ownerSource = "pending"
        local deadline = os.clock() + 0.030

        repeat



            ownerName, ownerCharacter, ownerSource =
                Menu._APServerHitbox.getServerHitboxOwner(hitbox, false)

            if ownerSource == "explicit" then
                break
            end

            RunService.Heartbeat:Wait()
        until os.clock() >= deadline or not hitbox.Parent

        if not hitbox.Parent or removed then
            return
        end

        if ownerSource ~= "explicit" then
            ownerName, ownerCharacter, ownerSource =
                Menu._APServerHitbox.getServerHitboxOwner(hitbox, true)

            debugLog("SERVER_OWNER_FALLBACK", {
                attack = attackType,
                owner = ownerName or "",
                ownerSource = ownerSource,
                swingId = swingId or "",
                wait = os.clock() - serverAddedAt,
            })
        end

        if ownerName
                == localWorkspaceCharacterName
            and Menu._AutoPunishRuntime
            and type(
                Menu._AutoPunishRuntime
                    .observeLocalImpactHitbox
            ) == "function"
        then
            pcall(
                Menu._AutoPunishRuntime
                    .observeLocalImpactHitbox,
                hitbox,
                attackType,
                serverAddedAt
            )
        end

        if ownerName == localWorkspaceCharacterName
            and Menu._APBreakerRuntime
            and type(Menu._APBreakerRuntime.releaseRealAttack) == "function"
        then
            pcall(
                Menu._APBreakerRuntime.releaseRealAttack,
                attackType,
                serverAddedAt
            )
        end




        local linked
        local matchScore

        if ownerSource == "explicit" then
            linked, matchScore = Menu._APServerHitbox.findAnimationThreatForHitbox(
                attackType,
                hitbox,
                serverAddedAt,
                ownerName
            )
        end

        if linked then
            if ownerCharacter then
                linked.owner = ownerCharacter
                linked.ownerName = ownerName
                linked.ownerSource = ownerSource
                linked.style = getStyle(ownerCharacter)
                linked.speedMultiplier = getSpeedMultiplier(ownerCharacter)
            end






            local grabPhaseStyle =
                linked.style == "wrestling"
            local lateGrabM2 = linked.attackType == "M2"
                and grabPhaseStyle
                and linked.fired == true
                and linked.firedAt ~= nil
                and serverAddedAt - linked.firedAt > 0.205

            if lateGrabM2 then
                debugLog(
                    "WRESTLING_M2_LATE_PHASE",
                    {
                        owner = linked.ownerName or ownerName or "",
                        swingId = swingId or "",
                        actionToken = hitbox:GetAttribute("VictimActionToken") or "",
                        sinceParry = serverAddedAt - linked.firedAt,
                        score = matchScore or 0,
                    },
                    true
                )
                linked = nil
            else
                Menu._APServerHitbox.attachServerHitbox(linked, hitbox, serverAddedAt)
                serverLinks[hitbox] = linked

                debugLog("SERVER_MATCH", {
                    attack = attackType,
                    owner = ownerName or "",
                    swingId = swingId or "",
                    score = matchScore or 0,
                    wait = os.clock() - serverAddedAt,
                    ownerSource = ownerSource,
                })

                return
            end
        end

        local fallback = {
            source = "server_hitbox",
            serverConfirmed = true,
            hitbox = hitbox,
            attackType = attackType,
            createdAt = serverAddedAt,
            serverAddedAt = serverAddedAt,
            owner = ownerCharacter,
            ownerName = ownerName,
            ownerSource = ownerSource,
            swingId = swingId,
            actionToken = hitbox:GetAttribute("VictimActionToken"),
            strikeDamage = hitbox:GetAttribute("VictimStrikeDamage"),
            turnRate = 0,
        }

        resolveOwner(fallback)
        fallback.style = getStyle(fallback.owner)
        fallback.speedMultiplier = getSpeedMultiplier(fallback.owner)
        refreshAttackName(fallback)

        fallback.mustDodgeSelected = false
        if Flags.dodge_enable == true
            and Menu._DodgeRuntime
            and type(Menu._DodgeRuntime.isMustDodgeThreat) == "function"
        then
            local okMustDodge, selected = pcall(
                Menu._DodgeRuntime.isMustDodgeThreat,
                fallback
            )
            fallback.mustDodgeSelected = okMustDodge and selected == true
        end

        local repeatedAction = Menu._APServerHitbox.rememberActionToken(
            fallback.ownerName,
            attackType,
            fallback.actionToken,
            serverAddedAt
        )
        local allowMultiHitAction = false
        local multiHitReason = ""

        if repeatedAction and attackType == "M2" then
            pcall(function()
                local styleConfig = CombatConfig.GetStyleConfig(fallback.style)
                local count = styleConfig and tonumber(styleConfig.M2MultiHitCount)

                if count ~= nil and count > 1 then
                    allowMultiHitAction = true
                    multiHitReason = "config_multi_hit"
                elseif styleConfig
                    and fallback.style ~= "kure"
                    and tonumber(styleConfig.M2GrabTargetForwardOffset) ~= nil
                then
                    allowMultiHitAction = true
                    multiHitReason =
                        fallback.style == "wrestling"
                        and "wrestling_grab_phase"
                        or "style_grab_phase"
                end
            end)
        end

        if repeatedAction and not allowMultiHitAction then
            fallback.expired = true

            debugLog("SERVER_HITBOX_DUPLICATE_ACTION", {
                attack = attackType,
                owner = fallback.ownerName or "",
                style = fallback.style or "",
                swingId = fallback.swingId or "",
                actionToken = fallback.actionToken or "",
            }, true)
        else
            serverFallbackThreats[hitbox] = fallback

            debugLog(allowMultiHitAction and "SERVER_HITBOX_MULTI_HIT" or "SERVER_HITBOX_UNMATCHED", {
                attack = attackType,
                owner = fallback.ownerName or "",
                style = fallback.style or "",
                swingId = fallback.swingId or "",
                actionToken = fallback.actionToken or "",
                strikeDamage = fallback.strikeDamage or "",
                size = hitbox.Size,
                position = hitbox.Position,
                ownerWait = os.clock() - serverAddedAt,
                repeatedAction = repeatedAction == true,
                multiHitReason = multiHitReason,
                ownerAttackSpeed = fallback.speedMultiplier or 1,
                ownerSource = fallback.ownerSource or ownerSource,
            }, allowMultiHitAction)
        end

        hitbox.ChildAdded:Connect(function(child)
            if child.Name == "Owner" or child.Name == "AttackName" then
                task.defer(function()
                    resolveOwner(fallback)
                    fallback.style = getStyle(fallback.owner)
                    refreshAttackName(fallback)
                end)
            end
        end)
    end)
end

(function()
local playersFolder = Workspace:FindFirstChild("Players")
local npcsFolder = Workspace:FindFirstChild("NPCs")

for _, folder in ipairs({playersFolder, npcsFolder}) do
    if folder then
        for _, character in ipairs(folder:GetChildren()) do
            Menu._APServerHitbox.watchCharacter(character)
        end

        Menu._ScriptRuntime:Track(
            folder.ChildAdded:Connect(Menu._APServerHitbox.watchCharacter)
        )
    end
end

local hitboxFolder = Workspace:FindFirstChild("Hitboxes")

if not hitboxFolder then
    hitboxFolder = Workspace:WaitForChild("Hitboxes", 20)
end

if hitboxFolder then
    for _, child in ipairs(hitboxFolder:GetChildren()) do
        Menu._APServerHitbox.addServerHitbox(child)
    end

    Menu._ScriptRuntime:Track(
        hitboxFolder.ChildAdded:Connect(Menu._APServerHitbox.addServerHitbox)
    )

    debugLog("HITBOX_WATCH_READY", {
        path = hitboxFolder:GetFullName(),
    }, true)
else
    debugLog("HITBOX_FOLDER_MISSING", {}, true)
end

Menu._APHeartbeatWasEnabled =
    Flags.ap_enable == true
Menu._APMaintenanceNextAt = 0

Menu._ScriptRuntime:Track(RunService.Heartbeat:Connect(function(dt)
    if Flags.ap_enable ~= true then
        if Menu._APHeartbeatWasEnabled then
            Menu._APHeartbeatWasEnabled = false
            table.clear(animationThreats)
            table.clear(Menu._ResolverTimingRuntime.surfaceThreats)
            table.clear(serverFallbackThreats)
            table.clear(serverLinks)
            table.clear(seenSwingIds)
            table.clear(seenActionTokens)
            table.clear(AutoPunishRuntime.recentParryAttempts)
        end
        return
    end

    Menu._APHeartbeatWasEnabled = true
    updateFrameStats(dt)

    pingAccumulator = pingAccumulator + dt

    if pingAccumulator >= 0.10 then
        pingAccumulator = pingAccumulator % 0.10
        pushPingSample()
    end

    local now = os.clock()

    if dt >= 0.045
        and now
            >= (
                tonumber(
                    Menu._APNextFrameSpikeLogAt
                ) or 0
            )
    then
        Menu._APNextFrameSpikeLogAt =
            now + 0.25

        local animationCount = 0
        local fallbackCount = 0
        local linkCount = 0

        for _ in pairs(animationThreats) do
            animationCount += 1
        end

        for _ in pairs(serverFallbackThreats) do
            fallbackCount += 1
        end

        for _ in pairs(serverLinks) do
            linkCount += 1
        end

        debugLog(
            "AP_FRAME_SPIKE",
            {
                frameMs =
                    dt * 1000,
                fps =
                    1 / math.max(
                        dt,
                        1 / 1000
                    ),
                animationThreats =
                    animationCount,
                serverFallbacks =
                    fallbackCount,
                serverLinks =
                    linkCount,
                totalEvents =
                    debugSequence,
            },
            true
        )
    end

    for character, state in pairs(resolverStateByCharacter) do
        if character
            and character.Parent
            and character.Name
                ~= localWorkspaceCharacterName
        then
            refreshResolverState(
                character,
                now
            )
            Menu._ResolverTimingRuntime.createSurfaceThreat(
                character,
                state,
                now
            )
        end
    end

    for track, threat in pairs(animationThreats) do
        if not updateAnimationThreat(threat, now) then
            animationThreats[track] = nil
        end
    end

    for serial, threat in pairs(Menu._ResolverTimingRuntime.surfaceThreats) do
        if not Menu._ResolverTimingRuntime.updateSurfaceThreat(threat, now) then
            Menu._ResolverTimingRuntime.surfaceThreats[serial] = nil
        end
    end

    for hitbox, threat in pairs(serverFallbackThreats) do
        if not updateServerFallback(threat, now) then
            serverFallbackThreats[hitbox] = nil
        end
    end

    if now >= (tonumber(Menu._APMaintenanceNextAt) or 0) then
        Menu._APMaintenanceNextAt =
            now + 0.25

        for key, seenAt in pairs(seenSwingIds) do
            if now - seenAt > 8 then
                seenSwingIds[key] = nil
            end
        end

        for key, seenAt in pairs(seenActionTokens) do
            if now - seenAt > 2 then
                seenActionTokens[key] = nil
            end
        end
    end

    for target, attempt in pairs(AutoPunishRuntime.recentParryAttempts) do
        local confirmed = false
        if type(AutoPunishRuntime.checkReplicatedConfirm) == "function" then
            confirmed = AutoPunishRuntime.checkReplicatedConfirm(
                target,
                attempt,
                now
            ) == true
        end

        if not confirmed then
            local seenAt = type(attempt) == "table" and tonumber(attempt.at) or 0
            if not target.Parent
                or now - seenAt > AutoPunishRuntime.matchWindow
            then
                AutoPunishRuntime.recentParryAttempts[target] = nil
            end
        end
    end
end))

