Connect(AutoPunishUI.ParryMode["on_dropdown_change"], function(value)
    if type(value) == "table" then
        value = value[1]
    end

    value = value == "While Stunned"
        and "While Stunned"
        or "Once"

    Flags.ap_auto_punish_parry_mode = value
    AutoPunishRuntime.parryModeSerial =
        (tonumber(AutoPunishRuntime.parryModeSerial) or 0) + 1

    local comboMode = Flags.ap_auto_punish_combo_mode
    if type(comboMode) == "table" then
        comboMode = comboMode[1]
    end

    if value == "While Stunned" and comboMode == "Fixed" then
        AutoPunishRuntime.forceParryModeOnce(true)
        autoParryDebugUi.syncFeatures()
        debugLog("AUTOPUNISH_PARRY_MODE_BLOCKED", {
            requested = "While Stunned",
            comboMode = "Fixed",
            fallback = "Once",
        }, true)
        return
    end

    if value ~= "While Stunned" then
        if AutoPunishRuntime.stunChains then
            table.clear(AutoPunishRuntime.stunChains)
        end
    end

    if AutoPunishRuntime.recentParryAttempts then
        table.clear(AutoPunishRuntime.recentParryAttempts)
    end
    autoParryDebugUi.syncFeatures()
    debugLog("AUTOPUNISH_PARRY_MODE", {
        mode = value == "While Stunned" and "While Stunned" or "Once",
    }, true)
end)

Connect(AutoPunishUI.ComboMode["on_dropdown_change"], function(value)
