    })
end)

Menu._RunAutoPunishTestSwing = function()
    task.spawn(function()
        local getMode = AutoPunishRuntime.getComboMode
        local getFixed = AutoPunishRuntime.getFixedComboHit
        local getFollow = AutoPunishRuntime.getFollowCombo

        if type(getMode) ~= "function"
            or type(getFixed) ~= "function"
            or type(getFollow) ~= "function"
        then
            debugLog("AUTOPUNISH_TEST_SWING", {
                phase = "rejected",
                reason = "combo_runtime_unavailable",
                getMode = type(getMode),
                getFixed = type(getFixed),
                getFollow = type(getFollow),
            }, true)
            return
        end

        local mode = getMode()
        local selectedHit = mode == "Fixed"
            and getFixed()
            or getFollow()

        debugLog("AUTOPUNISH_TEST_SWING", {
            phase = "attempt",
            comboMode = mode,
            combo = selectedHit,
            masterEnabled = Flags.ap_auto_punish == true,
        }, true)

        local startedAt = os.clock()
        local deadline = startedAt + 0.60
        local fired = false
        local attempts = 0

        repeat
            attempts += 1
            fired = AutoPunishRuntime.fireM1(nil, true, "test")
            if fired then
                break
            end

            if os.clock() >= deadline then
                break
            end

            RunService.Heartbeat:Wait()
        until false

        debugLog("AUTOPUNISH_TEST_SWING", {
            phase = fired and "fired" or "rejected",
            comboMode = mode,
            combo = selectedHit,
            attempts = attempts,
            waitedMs = math.floor((os.clock() - startedAt) * 1000 + 0.5),
            masterEnabled = Flags.ap_auto_punish == true,
        }, true)
    end)
end

if (tonumber(Menu._AutoPunishTestSwingPending) or 0) > 0 then
    Menu._AutoPunishTestSwingPending = 0
    Menu._RunAutoPunishTestSwing()
end

Connect(DesyncMode["on_dropdown_change"], function(value)
    if type(value) == "table" then
        value = value[1]
    end
    aeSetMode(value)
end)

Connect(DesyncEnable["on_toggle_change"], function(enabled)
    aeSetEnabled(enabled == true)
end)



do




    if Menu._wingChunCounterBroadcastConnection then
        pcall(function()
            Menu._wingChunCounterBroadcastConnection:Disconnect()
        end)
        Menu._wingChunCounterBroadcastConnection = nil
    end

    local state = {
        pending = setmetatable({}, {__mode = "k"}),
        serial = 0,
    }
    Menu._WingChunPostM2Runtime = state

    state.getCounterWindow = function()
        local window = 0.58
        pcall(function()
            local config = CombatConfig.GetStyleConfig("wingchun")
            if config and typeof(config.M2CounterWindowDuration) == "number" then
                window = config.M2CounterWindowDuration
            end
        end)
        return math.clamp(window, 0.20, 1.25)
    end

    state.getWhiffWindow = function()
        local window = 0.60
        pcall(function()
            local config = CombatConfig.GetStyleConfig("wingchun")
            if config and typeof(config.M2CounterWhiffStun) == "number" then
                window = config.M2CounterWhiffStun
            end
        end)
        return math.clamp(window, 0.20, 1.50)
    end

    state.cancel = function(owner, reason, victimName)
        local record = owner and state.pending[owner]
        if not record then
            return nil
        end

        state.pending[owner] = nil
        record.cancelled = true

        debugLog("WINGCHUN_POST_M2_CANCEL", {
            owner = owner.Name,
            victim = victimName or "",
            reason = reason or "cancelled",
            age = os.clock() - record.startedAt,
        }, true)

        return record
    end

    state.isCounterActive = function(owner)
        local record = owner and state.pending[owner]
        if not record
            or record.cancelled == true
            or not owner.Parent
        then
            return false
        end

        return os.clock()
            <= record.startedAt + record.counterWindow + 0.08
    end

    state.armPreemptiveGuard = function(owner, record)
        local character = getCharacter()
        if not character
            or not character.Parent
            or Flags.ap_enable ~= true
        then
            return false
        end

        local attackInFlight =
            character:GetAttribute("CombatAttacking") == true
            or character:GetAttribute("M1") == true
            or character:GetAttribute("M1Hold") == true
            or character:GetAttribute("PendingM1") == true
            or character:GetAttribute("M2") == true
            or character:GetAttribute("PendingM2") == true

        if not attackInFlight then
            return false
        end

        local myRoot = getRoot(character)
        local ownerRoot = getRoot(owner)
        if not myRoot or not ownerRoot then
            return false
        end

        local distance = flat(ownerRoot.Position - myRoot.Position).Magnitude
        if distance > 10.5 then
            return false
        end

        record.prearmPending = true
        debugLog("WINGCHUN_COUNTER_PREARM", {
            owner = owner.Name,
            phase = "armed",
            distance = distance,
            playbackSpeed = record.playbackSpeed,
            counterWindowMs = math.floor(record.counterWindow * 1000 + 0.5),
        }, true)

        task.spawn(function()
            local deadline = record.startedAt + record.counterWindow

            while os.clock() < deadline do
                if record.cancelled
                    or state.pending[owner] ~= record
                    or not owner.Parent
                    or Flags.ap_enable ~= true
                then
                    return
                end

                character = getCharacter()
                if not character or not character.Parent then
                    return
                end

                local busy =
                    character:GetAttribute("CombatAttacking") == true
                    or character:GetAttribute("M1") == true
                    or character:GetAttribute("PendingM1") == true
                    or character:GetAttribute("M2") == true
                    or character:GetAttribute("PendingM2") == true

                local hardBlocked =
                    character:GetAttribute("Stunned") == true
                    or character:GetAttribute("Ragdoll") == true
                    or character:GetAttribute("GuardBroken") == true
                    or (
                        character:GetAttribute("CantAnything") == true
                        and character:GetAttribute("CombatRecovery") ~= true
                    )

                if not busy and not hardBlocked then
                    local threat = {
                        source = "wingchun_counter_prearm",
                        serverConfirmed = true,
                        attackType = "M2",
                        owner = owner,
                        ownerName = owner.Name,
                        style = "wingchun",
                        createdAt = os.clock(),
                        counterStance = true,
                        turnRate = 0,
                        wingChunGuardUntil = deadline + 0.08,
                    }

                    local allowed, reason, context = passesThreatFilters(threat)
                    if allowed then
                        local now = os.clock()
                        local ping, up = getUplink()
                        local target, _, pwin = predictionWindow()
                        local prediction = {
                            ping = ping,
                            up = up,
                            target = target,
                            pwin = pwin,
                            lookahead = 0,
                            overlapDelay = 0,
                            velLead = 0,
                            closing = 0,
                            side = 0,
                            hitTL = math.max(0, deadline - now),
                            trackTime = 0,
                            trackSpeed = 0,
                            contactAbs = deadline,
                            pressAt = now,
                            pressAtQ = now,
                        }

                        if performParry(threat, prediction, context) then
                            record.prearmPending = false
                            record.prearmFired = true
                            debugLog("WINGCHUN_COUNTER_PREARM", {
                                owner = owner.Name,
                                phase = "guarding",
                                distance = context.distance,
                                remainingMs = math.floor(
                                    math.max(0, deadline - now) * 1000 + 0.5
                                ),
                            }, true)
                            return
                        end
                    elseif record.prearmRejectLogged ~= true then
                        record.prearmRejectLogged = true
                        debugLog("WINGCHUN_COUNTER_PREARM", {
                            owner = owner.Name,
                            phase = "filtered",
                            reason = reason or "",
                        }, true)
                    end
                end

                RunService.Heartbeat:Wait()
            end

            record.prearmPending = false
        end)

        return true
    end

    state.schedule = function(owner, playbackSpeed)
        if not owner or not owner.Parent then
            return
        end

        state.serial += 1

        local startedAt = os.clock()
        local counterWindow = state.getCounterWindow()
        local whiffWindow = state.getWhiffWindow()

        local old = state.pending[owner]
        if old then
            old.cancelled = true
        end

        local record = {
            serial = state.serial,
            startedAt = startedAt,
            counterWindow = counterWindow,
            whiffWindow = whiffWindow,
            playbackSpeed = math.max(
                0.05,
                tonumber(playbackSpeed) or 1
            ),
            cancelled = false,
        }
        state.pending[owner] = record

        debugLog("WINGCHUN_POST_M2_START", {
            owner = owner.Name,
            counterWindowMs = math.floor(counterWindow * 1000 + 0.5),
            whiffWindowMs = math.floor(whiffWindow * 1000 + 0.5),
            playbackSpeed = record.playbackSpeed,
        }, true)

        state.armPreemptiveGuard(owner, record)

        task.spawn(function()
            local deadline = startedAt + counterWindow

            while os.clock() < deadline do
                if record.cancelled
                    or not owner.Parent
                    or state.pending[owner] ~= record
                then
                    return
                end
                RunService.Heartbeat:Wait()
            end

            if record.cancelled
                or not owner.Parent
                or state.pending[owner] ~= record
            then
                return
            end

            state.pending[owner] = nil

            local distance = math.huge
            local character = getCharacter()
            local myRoot = getRoot(character)
            local ownerRoot = getRoot(owner)
            if myRoot and ownerRoot then
                distance = flat(ownerRoot.Position - myRoot.Position).Magnitude
            end

            debugLog("WINGCHUN_POST_M2_READY", {
                owner = owner.Name,
                distance = distance,
                elapsed = os.clock() - startedAt,
                punishWindowMs = math.floor(whiffWindow * 1000 + 0.5),
            }, true)

            local autoFired = false
            local autoAction = ""
            local autoReason = "disabled"

            if AutoPunishRuntime
                and type(AutoPunishRuntime.firePostWingChun) == "function"
            then
                local ok, fired, actionOrReason = pcall(
                    AutoPunishRuntime.firePostWingChun,
                    owner
                )
                autoFired = ok and fired == true
                if autoFired then
                    autoAction = tostring(actionOrReason or "")
                else
                    autoReason = ok
                        and tostring(actionOrReason or "not_ready")
                        or tostring(fired)
                end
            end

            if autoFired then
                debugLog("WINGCHUN_POST_M2_ACTION", {
                    owner = owner.Name,
                    action = "prefer_m2",
                    attack = autoAction,
                    autoplayReason = autoReason,
                    distance = distance,
                }, true)
                return
            end

            local boxingFired = false
            local boxingReason = "disabled"

            if BoxingCounterRuntime
                and type(BoxingCounterRuntime.firePostWingChun) == "function"
            then
                local ok, fired, reason = pcall(
                    BoxingCounterRuntime.firePostWingChun,
                    owner
                )
                boxingFired = ok and fired == true
                boxingReason = ok and tostring(reason or "") or tostring(fired)
            end

            if boxingFired then
                debugLog("WINGCHUN_POST_M2_ACTION", {
                    owner = owner.Name,
                    action = "boxing_counter",
                    attack = "M2",
                    distance = distance,
                }, true)
                return
            end

            debugLog("WINGCHUN_POST_M2_ACTION", {
                owner = owner.Name,
                action = autoFired and "autoplay" or "none",
                attack = autoAction,
                boxingReason = boxingReason,
                autoplayReason = autoReason,
                distance = distance,
            }, true)
        end)
    end

    pcall(function()
        local shared = ReplicatedStorage:FindFirstChild("Shared")
        local network = shared and shared:FindFirstChild("Network")
        local remote = network and network:FindFirstChild("CombatBroadcastURE")

        if remote and remote:IsA("UnreliableRemoteEvent") then
            Menu._wingChunCounterBroadcastConnection = remote.OnClientEvent:Connect(function(
                eventName,
                attackerName,
                victimName,
                playbackSpeed
            )
                if typeof(attackerName) ~= "string" then
                    return
                end

                if eventName == "WingChunCounterStartup" then
                    local owner = getWorkspaceCharacterByName(attackerName)
                    if owner and owner.Parent then
                        state.schedule(owner, victimName)
                    end
                    return
                end

                if eventName ~= "WingChunCounterHit" then
                    return
                end

                local owner = getWorkspaceCharacterByName(attackerName)
                local record = owner and state.pending[owner] or nil
                if owner and owner.Parent then
                    state.cancel(
                        owner,
                        "counter_hit",
                        typeof(victimName) == "string" and victimName or ""
                    )
                end

                if Flags.ap_enable ~= true
                    or typeof(victimName) ~= "string"
                then
                    return
                end

                local character = getCharacter()
                if not character or victimName ~= character.Name then
                    return
                end

                if not owner or not owner.Parent then
                    return
                end

                local counterPlaybackSpeed = math.max(
                    0.05,
                    tonumber(playbackSpeed)
                        or (record and record.playbackSpeed)
                        or 1
                )
                local firstHitDelay = (25 / 60) / counterPlaybackSpeed

                local threat = {
                    source = "wingchun_counter",
                    serverConfirmed = true,
                    attackType = "M2",
                    owner = owner,
                    ownerName = attackerName,
                    style = "wingchun",
                    createdAt = os.clock(),
                    counterStance = true,
                    turnRate = 0,
                    counterPlaybackSpeed = counterPlaybackSpeed,
                    counterHitDelay = firstHitDelay,
                }

                local allowed, reason, context = passesThreatFilters(threat)
                if not allowed then
                    debugLog("WINGCHUN_COUNTER_SIGNAL", {
                        owner = attackerName,
                        victim = victimName,
                        accepted = false,
                        reason = reason or "",
                    }, true)
                    return
                end

                local now = os.clock()
                local ping, up = getUplink()
                local target, _, pwin = predictionWindow()
                local prediction = {
                    ping = ping,
                    up = up,
                    target = target,
                    pwin = pwin,
                    lookahead = 0,
                    overlapDelay = 0,
                    velLead = 0,
                    closing = 0,
                    side = 0,
                    hitTL = firstHitDelay,
                    trackTime = 0,
                    trackSpeed = 0,
                    contactAbs = now + firstHitDelay,
                    pressAt = now,
                    pressAtQ = now,
                }

                debugLog("WINGCHUN_COUNTER_SIGNAL", {
                    owner = attackerName,
                    victim = victimName,
                    accepted = true,
                    distance = context.distance,
                    heightDiff = context.heightDiff,
                    playbackSpeed = counterPlaybackSpeed,
                    firstHitDelayMs = math.floor(firstHitDelay * 1000 + 0.5),
                    prearmed = record and record.prearmFired == true or false,
                }, true)

                local extended = false
                if autoBlocking == true
                    and character:GetAttribute("Blocking") == true
                then
                    extended = extendAutoBlockHold(
                        math.clamp(
                            firstHitDelay
                                + 0.12
                                + math.min(
                                    math.max(tonumber(ping) or 0, 0),
                                    0.15
                                ),
                            0.46,
                            0.72
                        ),
                        "wingchun-counter-hit",
                        attackerName
                    )
                end

                if extended then
                    debugLog("WINGCHUN_COUNTER_GUARD_EXTEND", {
                        owner = attackerName,
                        victim = victimName,
                        firstHitDelayMs = math.floor(
                            firstHitDelay * 1000 + 0.5
                        ),
                    }, true)
                else
                    performParry(threat, prediction, context)
                end
            end)
        end
    end)
end

Connect(Enable["on_toggle_change"], function(enabled)
    debugLog("AUTOPARRY_TOGGLE", {
        enabled = enabled,
        detectionFov = enabled and 360 or 0,
    }, true)

    if not enabled then
        stopBehindParryFacing()
    end

    if not enabled and autoBlocking then
        autoBlockSerial = autoBlockSerial + 1
        local serial = autoBlockSerial
        autoBlocking = true
        releaseAutoBlock(serial)
    end

    if not enabled then
        Menu._apBlockActive = false
        Menu._apRecentParryCoverage = {}
    else
        task.defer(function()
            for _, folder in ipairs({
                Workspace:FindFirstChild("Players"),
                Workspace:FindFirstChild("NPCs"),
            }) do
                if folder then
                    for _, character in ipairs(folder:GetChildren()) do
                        local humanoid = character:FindFirstChildOfClass("Humanoid")
                        local animator = humanoid
                            and humanoid:FindFirstChildOfClass("Animator")

                        if animator then
                            for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
                                createAnimationThreat(character, track)
                            end
                        end
                    end
                end
            end

            local folder = Workspace:FindFirstChild("Hitboxes")
            if folder then
                for _, hitbox in ipairs(folder:GetChildren()) do
                    Menu._APServerHitbox.addServerHitbox(hitbox)
                end
            end
        end)
    end
end)

local function cleanupGakuranFeatures()
    stopBehindParryFacing()

    if autoBlocking then
        releaseAutoBlock(autoBlockSerial, true)
    end

    if Menu._wingChunCounterBroadcastConnection then
        pcall(function()
            Menu._wingChunCounterBroadcastConnection:Disconnect()
        end)
        Menu._wingChunCounterBroadcastConnection = nil
    end

    if ESPVisuals and type(ESPVisuals.Unload) == "function" then
        pcall(ESPVisuals.Unload, ESPVisuals)
    end

    for _, runtime in ipairs({
        Menu._PlayerModRuntime,
        Menu._SpoofRuntime,
    }) do
        if type(runtime) == "table"
            and type(runtime.Unload) == "function"
        then
            pcall(runtime.Unload, runtime)
        end
    end

    if Menu._MiscRuntime
        and type(Menu._MiscRuntime.shutdown) == "function"
    then
        pcall(Menu._MiscRuntime.shutdown)
    end

    local otherRuntime = Menu._OtherRuntime
    if type(otherRuntime) == "table" then
        for _, methodName in ipairs({
            "SetAutoRhythmEnabled",
            "SetAutoBasketballEnabled",
            "SetAutoWrestlingEnabled",
            "SetChessEnabled",
        }) do
            local method = otherRuntime[methodName]
            if type(method) == "function" then
                pcall(method, false)
            end
        end
    end

    for _, runtime in ipairs({
        Menu._DodgeRuntime,
        Menu._SoundRuntime,
        Menu._IndicatorRuntime,
    }) do
        if type(runtime) == "table"
            and type(runtime.shutdown) == "function"
        then
            pcall(runtime.shutdown)
        end
    end

    if Menu._AutoFaceRuntime then
        if type(Menu._AutoFaceRuntime.shutdown) == "function" then
            pcall(Menu._AutoFaceRuntime.shutdown)
        elseif type(Menu._AutoFaceRuntime.release) == "function" then
            pcall(Menu._AutoFaceRuntime.release)
        end
    end

    AutoPunishRuntime.restoreHooks()

    if Menu._WingChunCounterRuntime
        and type(Menu._WingChunCounterRuntime.cancelAll) == "function"
    then
        pcall(Menu._WingChunCounterRuntime.cancelAll, "unload")
    end
    if Menu._wingChunCounterBroadcastConnection then
        pcall(function()
            Menu._wingChunCounterBroadcastConnection:Disconnect()
        end)
        Menu._wingChunCounterBroadcastConnection = nil
    end

    aeSetEnabled(false)
end

do
    local runtime = rawget(env, "__GakuranScriptRuntime")
    if type(runtime) == "table"
        and type(runtime.AddCleanup) == "function"
    then
        runtime:AddCleanup(cleanupGakuranFeatures)
    end
end

do
    local originalUnload = Menu.unload
    if type(originalUnload) == "function" then
        function Menu:unload(...)
            local runtime = rawget(env, "__GakuranScriptRuntime")
            if type(runtime) == "table"
                and type(runtime.Unload) == "function"
            then
                pcall(runtime.Unload, runtime)
            else
                pcall(cleanupGakuranFeatures)
            end
            return originalUnload(self, ...)
        end
    end
end

if type(Menu.update_layout) == "function" then
    Menu.update_layout()
end

if type(Menu.set_open) == "function" and Menu._boot_silent_load == true then
    Menu:set_open(false)
end

end)()

return Menu
]======]

local nativeChunk, compileError =
    compiler(nativeSource, "@Runtime.lua")

if type(nativeChunk) ~= "function" then
    error(
        "runtime compile failed: "
            .. tostring(compileError),
        0
    )
end

nativeSource = nil
return nativeChunk()
